const chapterTitleMap={1:"第1章 人寿保险简介",2:"第2章 人寿保险及年金的种类",3:"第3章 保险利益附约及其他产品",4:"第4章 阐释人寿保险单",5:"第5章 人寿保险程序"},papers=[{id:"paper3-2026-02",type:"卷三",title:"2026年2月真题",premium:!1,isMock:!1,total:100},{id:"paper3-2026-01",type:"卷三",title:"2026年1月真题",premium:!0,isMock:!1,total:100},{id:"paper3-2025-12",type:"卷三",title:"2025年12月真题",premium:!0,isMock:!1,total:100},{id:"paper3-2025-11",type:"卷三",title:"2025年11月真题",premium:!0,isMock:!1,total:100},{id:"paper3-2025-10",type:"卷三",title:"2025年10月真题",premium:!0,isMock:!1,total:100},{id:"paper3-2025-09",type:"卷三",title:"2025年9月真题",premium:!0,isMock:!1,total:100},{id:"paper3-2025-08",type:"卷三",title:"2025年8月真题",premium:!0,isMock:!1,total:100},{id:"paper3-mock-09",type:"卷三",title:"卷三模拟试题9",premium:!0,isMock:!0,total:908},{id:"paper1-2026-02",type:"卷一",title:"2026年2月真题",premium:!1,isMock:!1,total:100},{id:"paper1-2026-01",type:"卷一",title:"2026年1月真题",premium:!0,isMock:!1,total:100},{id:"paper1-2025-12",type:"卷一",title:"2025年12月真题",premium:!0,isMock:!1,total:100},{id:"paper1-2025-11",type:"卷一",title:"2025年11月真题",premium:!0,isMock:!1,total:100},{id:"paper1-2025-10",type:"卷一",title:"2025年10月真题",premium:!0,isMock:!1,total:100},{id:"paper1-2025-09",type:"卷一",title:"2025年9月真题",premium:!0,isMock:!1,total:100},{id:"paper1-2025-08",type:"卷一",title:"2025年8月真题",premium:!0,isMock:!1,total:100},{id:"paper1-mock-08",type:"卷一",title:"卷一模拟试题8",premium:!0,isMock:!0,total:914}],questionsByPaper={"paper1-2025-10":[{c:"1.1.2(b)",s:"汽車意外、個人損傷等情況，最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:0,e:"特定風險造成的後果是相對有限的汽\n車意外、個人損傷就是例子"},{c:"3.3.3(iii)",s:"如果索償涉及______________，該項索償很有可能被拒",o:["不保危險","除外危險","自然災害造成的損失","人為錯誤"],a:1,e:"除外危險的發生一般會令保險索償\n或保險金要求失敗，但複雜的例外情\n況是存在的。"},{c:"1.1.3",s:"不提供食物及飲料以避免食物中毒的風險，屬哪種風險管理的措施?",o:["風險避免","損失防範","損失降低","風險轉移"],a:0,e:"風險避免是不讓自己暴露在某項風險\n之下，從而免除遭受相關損失的機會"},{c:"1.1.1",s:"如果一名由保險人聘請的檢驗人，提出他必須就某項「風險」進行檢驗，那麼「風險」\n一詞在這方面有下列哪項或哪些含義？",o:["將要成為被保險人的繳付保費的能力","將要承保的財產","將要成為被保險人的人的信貸資料","以上任何一項"],a:1,e:"保險從業員在使用「風險」一詞時，\n可能有其他意思，其中包括「他們正\n在承保或考慮承保的受風險財物或人\n身」"},{c:"1.1.1",s:"有一類風險會使我們情緒上感到難過及悲傷，但並不涉及財務損失。這類風險",o:["在任何情況下是可保的","通常得到承保","只有損失是由意外造成才受保的","相當可能不受保"],a:3,e:"難過及悲傷的情緒上損失難以用金錢\n衡量損失，以商業方式處理此等風險\n，在財務上是不可行的。"},{c:"1.1.1",s:"當保險單提供「全險」的保障時，所提及的風險是指",o:["造成損失的原因","所承保的財物","正在考慮承保的人身","正在考慮承保的財物或人身"],a:0,e:"「全險」的保險保障意思是說除非出\n事原因屬保障範圍以外，否則由任何\n原因造成的"},{c:"1.1.2",s:"商業保險人所保的風險主要是",o:["特定風險及基本風險","純粹風險及基本風險","純粹風險及特定風險","純粹風險及投機風險"],a:2,e:"商業保險人所保的風險主要是特定風\n險及基本風險"},{c:"1.1.2a",s:"以下哪項是屬於投機風險的？",o:["投資股票","兩輛汽車相撞","雷電打擊造成建築物嚴重的破壞","以上的沒有一項是"],a:0,e:"投機風險能產生收益 、\n損失等兩種可能的結果。這類風險包\n括賭博、業務開創及投資活動等"},{c:"1.1.2b",s:"從可保程度的角度來看，哪項是用來形容特定風險的?",o:["永不可保的","必然可保的","可保程度較可能低於基本風險","可保程度較可能高於基本風險"],a:3,e:"商業保險人所保的風險主要是特定風\n險，基本風險一般是不可保的，因為\n要求他們以商業方式處理此等風險看\n來在財務上是不可行的。"},{c:"1.1.2b",s:"以下哪項是「基本風險」？",o:["冠狀病毒爆發","一棵大樹倒塌","一個人自殺","商舖被盜竊"],a:0,e:"基本風險發生的原因是超逾一個人或\n甚至一群人所能操控的，受影響的人\n不計其數。這類風險包括饑荒、戰爭\n、恐怖襲擊、大規模洪\n災和其他災害等"},{c:"1.1.3",s:"以下哪項有關風險管理是正確的？",o:["在保險中只涉及投機風險","在銀行中只涉及純粹風險","涉及識別風險","只涉及識別及量化風險"],a:2,e:"作為一個獨立的知識與研究的領域，\n風險管理可以解釋為管理學的一個分\n支，進行的步驟包括：識別，量化，\n及應對"},{c:"2.2(a)(b)",s:"以下哪頂是代理法的描述是正確的?",o:["僅用於保險業務","根據代理法，保險經紀不屬代理人","委託人受代理人沒有授權的行為行為所約束","以上各項都不正確"],a:2,e:"代理人代表委託人行事，無論其結果\n是好是壞，經授權的行為，有時甚至\n是沒有授權的行為，都會對委託人產\n生約束力"},{c:"2.1.3",s:"以下項是「可使無效」的合約最佳描述?",o:["一個法律不能撤銷的合約","一個法律無法生效的合約","一個於投保階段提供錯誤投保資料的保險合約","一個法律不存在的合約"],a:2,e:"於投保階段提供錯誤投保資料的保險\n合約，保險人有可能就投保人違反最\n高誠信推翻保單"},{c:"2.2.1",s:"一名母親指使其小孩到一家雜貨店購買雞蛋，意味著",o:["商店與該名母親之間訂立了一份銷售合約","小孩與該名母親之間訂立了一份銷售合約","小孩負上轉承責任","代理法約束著小孩的行為"],a:0,e:"商店與該名母親之間訂立了一份銷售\n合約，因為母親作為委託人承擔了支\n付貨款的法律責任 。"},{c:"2.1.3(d)",s:"訂約的行爲能力是簡單合約其中一項要求，其意義是",o:["未成的人沒有能力訂立合約","其含義是指訂立合約的法律能力","精神錯亂的人完全沒有能力訂立合約","以上各項皆不是"],a:1,e:"訂約的行為能力是指訂立合約的法律\n能力。"},{c:"2.1.4",s:"“非合約的一方第三者，便沒有責任履行該合約的條款”，這描述普通法中的哪一種?",o:["合約法","合約的相對性","訂約的行為能力","合法性"],a:1,e:'合約的相對性的其中一個原則是"非合\n約的一方第三者，便沒有責任履行該\n合約的條款"'},{c:"2.1.1",s:"合約可以界定為",o:["在法律上可強制執行的協議","兩人或多人之間的承諾","以書面形式表達的協議","任何兩方或多方的協議"],a:0,e:"合約可以界定為在法律上可強制執行\n的協議"},{c:"2.1.3",s:"一般協議有別於合約的原因，以下有哪些或哪項的描述是正確的？",o:["合約必須以書面形式訂立","合約必須有兩位以上的見證人","合約包含多項法律準則","以上所有各項"],a:2,e:"合約可透過口頭，書面及行為形式訂\n立，協定涉及的內容必須是合法的"},{c:"2.1.3",s:"以下哪項可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含義完全相同","受屈的一方可於合理時間內把合約視為無效的決定","只有被保險人才能把保單視作可使無效(即可予以取消)"],a:2,e:"可使無效的合約是項明顯有法律效力\n的合約，其法律效力一直維持下去，\n除非及直至有受屈的一方把合約視為\n自訂立時起即屬無效，但須在一段合\n理時間內進行"},{c:"2.1.3(a)",s:"保險合約中的要約人是",o:["通常是保險人","通常是被保險人","可以是保險人或被保險人","通常是中介人代表的一方"],a:2,e:"在保險中，要約人可以是投保的一方\n，也可以是保險人透過反要約的形式\n，表示願意承保或續保"},{c:"2.2",s:"「透過他人行事與自己親自執行並無分別」法律原則是來自",o:["合約法","代理法","侵權法","保險業條例"],a:1,e:"代理法律原則是「透過他人行事與親\n自執行並無分別」，代理人代表委託\n人行事，無論其結果好壞，\n經授權的行為或沒有授權的行為，都\n會對委託人產生約束力"},{c:"2.2.1",s:"保險代理人在安排一份保險時，為保險人行事，當中涉及兩份合約。其中一份存在於保\n險代理人與保險人之間，另一份則存在於",o:["保險代理人與第三者之間","保險人與保單持有人之間","保險代理人與保單持有人之間","保險人與保險經紀之間"],a:1,e:"保險代理人在安排一份保險時，為保\n險人行事，當中涉及兩份合約。其中\n一份存在於保險代理人與保險人之間\n，另一份則存在於保險人與保單持有\n人之間"},{c:"2.2.2",s:"由委託人追認而確認的代理關係是指",o:["委託人已有效地「追溯」他當時代理人的動作的批准","在代理人行動前委託人已經表明不授權","代理人曾在緊急情況下替委託人辦事","代理人進行類似過去曾被批准的未授權行動"],a:0,e:"追認是指對某行為授予追溯權。雖然\n代理人在行事時並未取得授權，但只\n要委託人事後確認該行動"},{c:"2.2.3(b)",s:"以下哪個是表面權限的正確描述",o:["明示權限","沒有實際權限","是局限於委託人與第三者之間的關係","實際權限"],a:2,e:"表面權限是當一個代理人的權限是透\n過委託人對第三者表明同意而產生的\n，該權限便是表面而非實際。"},{c:"2.2.3(d)",s:"不容反悔的代理權是來自",o:["明示權限","法定條文","事後對代理人的行為所作的明確指示","據稱的委託人的行為"],a:3,e:"不容反悔的代理權的其中一項法則，\n是當據稱代理人完全沒被授權但卻被\n容許看似獲授權時應用的。"},{c:"2.2.4",s:"有關代理人必須對委託人所收取金錢進行「報帳」，意思是",o:["只能間中提供回佣","代理人對代表委託人所收取的金錢或其他物件報帳，必須確定保存足夠的記錄以反映\n其代理業務的狀況","代理人必須書面紀錄與委託人的認真溝通","代理人以委託人的名義收取的所有的物品必須在3天之內交回委託人"],a:1,e:"「報帳」，意思是代理人對代表委託\n人所收取的金錢報帳，確定保存足夠\n的記錄以反映其代理業務的狀況"},{c:"2.2.6",s:"如果代理協議在生效六個月後變成非法，以下哪項有關該協議的描述是正確的?",o:["即時終止","必須待至期限終結","其中一方提出便可終結","雙方同意便可終結"],a:0,e:"如果代理關係或代理協議的履行不再\n為法律所容許的話，協議便會自動終\n止"},{c:"3.1.3",s:"以下哪項是債權人對債務人的生命購買保險，具有可保權益必須符合的必要條件?",o:["財務關係一直存在","僅適用於抵押一直存在","沒有任何必要條件","償還債務的金額"],a:0,e:"在法律上假定有可保權益的存在，須\n提出財務關係的證據"},{c:"3.3.1",s:"下列哪項有關近因的陳述是正確的？",o:["它僅適用於財產保險","由一個以上的成因引致的損失，只有涉及保險風險引致的損失得到保障","由單一成因引致的損失是一項不保危險，便不能就所引致的損失得到保障","由一系列的事故引致的損失，只有首個的成因能構成近因"],a:2,e:"如果只有單一成因，假如它是不保或\n除外危險便不受保"},{c:"3.3.4",s:"一項保險原則，尋求保險人將受保財物恢復到其受毀或受損以前那一刻所處的狀況，這\n是甚麼原則?",o:["彌償","代位","最高誠信","可保權益"],a:0,e:"財產保險單通常訂明保險人可透過恢\n復原狀作為提供彌償的一種方法，它\n意指使受保財物恢復到其受毀或受損\n以前那一刻所處的狀況"},{c:"3.1",s:"以下哪項不是可保權益必須符合條件?",o:["必須先有可被保的","必須是該保險的標的","就財產保險而言，投保人必須所屬國家的公民","投保人與保險標的之間必須存在法律認可的關係"],a:2,e:"投保人必須所屬國家的公民不是可保\n權益必須符合條件"},{c:"3.2.4",s:"根據普通法，投保人需要遵守最高誠信責任的期限",o:["直至索償為止","直至該合約生效為止","涉及整段合約生效時","僅至簽署投保書時為止"],a:1,e:"在普通法中，於保險合約訂立後，投\n保人才得知的重要事實，不必予以披\n露。"},{c:"3.3.1",s:'以下哪項屬於近因中被視為"危險"?',o:["地震","身體嚴重受傷","火警警報器故障","以上各項皆是"],a:0,e:"有關危險即是有關損失的成因，地震\n造成的損失"},{c:"3.2.3(b)",s:"以下哪項不會影響保險合約存在與否或保險條款?",o:["重要事實","非重要事實","可保權益","以上各項皆不是"],a:1,e:"非重要事實對保險人來說是不會影響\n保險合約存在與否或保險條款"},{c:"3.4.7(b)",s:"以下哪項阻止了保單為被保險人作出彌償?\ni. 比例分攤\nii. 多於二人有可保權益\niii. 免賠額\niv. 起賠額",o:["i,ii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"比例分攤，免賠額，起賠額屬限制彌\n償的保單條文，意味着規定的賠償金\n額 比彌償金額為低"},{c:"3.1.4(b)",s:"於所有保險合約中，以下哪項保險項目在索償時需要有可保權益？\ni. 責任保險\nii. 汽車保險\niii. 船上貨物保險\niv. 人壽保險",o:["i,ii,iii","ii, iii, iv","i,ii,iv(cid:9)","i,iii,iv"],a:0,e:"在水險或其他類型的彌償保險，可保\n權益只須損失時存在，所以選項i,ii,\niii是正確。"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["轉讓人不會把保險合約中的責任轉移到承讓人的身上","承讓人將取得收款人的權利，而非訴訟權","承讓人承讓人承諾支付未來的保費","承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費"],a:0,e:"保單「轉讓」通常是指權利的轉移。\n轉讓是不會讓轉讓人在保險合約的責\n任轉移到承讓人的身上的"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約性質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險人的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓\n收取保險金的權利無需取得保險人的\n同意"},{c:"3.2.6",s:"違反最高誠信的形式分別有欺詐性失實陳述，非欺詐性失實陳述，欺詐性不披露，非欺\n詐性不披露的四個類別，當中非欺詐性不披露是",o:["蓄意地提供虛假重要事實給另一方","無意地或疏忽地向另一方提供虛假重要事實","無意地或疏忽地漏了向另一方披露重要事實","蓄意地或疏忽地漏了向另一方披露重要事實"],a:2,e:"非欺詐性不披露是無意地或疏忽地漏\n了向另一方披露重要事實"},{c:"3.4.5",s:"以下哪項不是Salvage一詞的定義?",o:["在海商法中，有關財物擁有人向救助人支付的”救助賞金”","於非海上保險中，指保險標的受損後的殘餘價值","懲罰不足投保額","以上各項皆不是"],a:2,e:"懲罰不足投保額的比例分攤原則的英\n文名稱是Average。"},{c:"3.5.1",s:"以下哪項是標準火險保單理賠時遇上重複保險運用到的條款？",o:["保單限額","比率之數","比例分攤","以上各項皆不是"],a:1,e:"比率之數條款是在重複保險的情況下\n，如果有關的保單包含了這項條款，\n被保險人就不再可以單靠一個保險人\n而獲全額賠償"},{c:"3.1.5",s:"人壽保險與其他保險一樣要求可保權益的存在，但對人壽保險而言可保權益必須存在於",o:["只是索償出現的時候","只是保單開始的時候","只是保單可能轉讓的時候","保單開始及索償出現的時候"],a:1,e:"人壽保險可保權益只須存在於保單開\n始的時候"},{c:"3.2.4",s:"最高誠信的要求有時會改變，以下哪項是正確描述？",o:["這是法律不容許的","普通法要求在保單任何時間都需要","所有保險都是要求只在保單開始時需要","可以因為雙方的協議而修改"],a:3,e:"如果在保單有效期內要求更改合約，\n最高誠信的責任便適用於這些更改事\n項上"},{c:"3.2.3",s:"以下哪項屬於必須披露的重要事實？",o:["任何過去的入屋犯法行為﹝盜竊保險﹞","載貨船的名稱﹝海上貨物保險﹞","投保貨物的高度可燃性﹝火險﹞","上述所有各項"],a:3,e:"上述所有各項都屬增加風險的事實，\n必須予以披露。"},{c:"3.2.3(b)",s:"以下哪項是投保人須披露",o:["與常識有關的資料","保險人已知或會影響是否承保風險的事實","投保人過往的索償紀錄","以上所有各項"],a:2,e:"投保人過往的索償紀錄屬增加風險的\n事實，必須予以披露。"},{c:"3.2.6",s:"如果投保人違反了最高誠信",o:["只要牽涉詐騙的情況下，保險人可得到補救","保險人可以從起保日開始推翻有關合約","詐騙或疏忽的情況下，保險人可得到補救","該份保單會自動失效"],a:1,e:"從起保日開始推翻有關合約屬於投保\n人違反了最高誠信保險人的補救方法"},{c:"3.3.1",s:"近因",o:["對人壽保險來說從不重要","對所有索償情況來說均屬重要","從不被保單措詞所更改","符合以上各項的陳述"],a:1,e:"近因即是造成損失的原因，對所有索\n償情況來說均屬重要"},{c:"3.3.2",s:"在考慮「近因」時，如果一項特定損失涉及一項單一成因，那麼",o:["如果該成因是一項受保危險，被保險人便能就所引致的損失得到保障","如果該成因是一項不保危險，被保險人便不能就所引致的損失得到保障","如果該成因是一項除外危險，被保險人便不能就所引致的損失得到保障","上述所有各項陳述均屬正確"],a:3,e:"如果只有單一成因，只有受保危險所\n引起的損失是受保的。如果涉及一項\n以上的危險，涉及除外危險的發生一\n般會令保險索償或保險金要求失敗"},{c:"3.3.2",s:"假設火險保單只保障火災或雷電帶來的損失或損壞。如果雨水透過開敞窗戶而進入室內\n而造成的損失是得不到保障的，因為其近因是",o:["除外危險","不保危險","外來危險","不可保危險"],a:1,e:"火險保單中，單單因為雨水造成損失\n屬不保危險"},{c:"3.3.3",s:"以下哪項是描述「既不是受保也不是除外責任的危險，而是在保單保障的範圍以外」？",o:["受保危險","除外危險","不保危險","非受保特定危險"],a:2,e:"不保危險是「既不是受保也不是除外\n責任的危險，而是在保單保障的範圍\n以外」"},{c:"3.3.3",s:"某些受商業火險保障的存貨因火警的濃煙而毀於一旦，這項損失︰",o:["是不受保障的，因為濃煙並非受保危險","是不受保障的，因為濃煙必然屬於除外危險","是受保障的，因為有關摧毀是由受保危險引致的","必然可獲保險人的賠償，但只能是同情的顯示"],a:2,e:"濃煙造成的損失是由受保的，因為有\n關摧毀是由火警這類受保危險引致的"},{c:"3.4.5",s:"作為計算彌償時予以考慮的一環，「損餘」應解作",o:["維修受損害物件時應付的金錢","搶救涉及索償的物件的成本","受到摧毀的保險標的剩餘部分","剛出現損害前該物件的價值"],a:2,e:"「損餘」應解作受到摧毀的保險標的\n剩餘部分"},{c:"3.4.7(a)",s:"如果一份財產保險單被稱為「受比例分攤條件約束」，那麼它的意思是",o:["所代表的是一種標準風險，因此標準保費適用於該風險","不足額保險是不重要的","在任何情況下均不會對損失提供十足的支付","如果保額足夠的話，便會對損失提供十足的支付"],a:3,e:"大部分類型的非水險財產保險\n均受比例分攤的 限制\n，保險人預期受保財產會以其全額的\n價值投保。"},{c:"3.4.7(b)",s:"在彌償中，下列哪些條件有時意味著比應予賠償為少的金額?\ni)保單免賠額\nii)保單起賠額\niii)約定價值保單\niv)水險保單",o:["i，ii","i，iii","ii，iii","iii，iv"],a:0,e:"保單免賠額及保單起賠額屬限制彌償\n的保單條文"},{c:"3.4.8",s:"一部電視機受火災損害時已經使用五年之久，損失維修費用$5,000，有關家居保險人全\n數支付，由此可推斷該保險由以下哪項訂立？",o:["「以新代舊」方式","商業重置保險","恢復原狀方式","約定價值方式"],a:0,e:"「以新代舊」的保險保障不會就損耗\n、折舊等因素扣減賠償金額，這詞一\n般較多用於家居風險單和船體保險單\n。"},{c:"3.5.4",s:"分擔的原則只會應用在",o:["人壽保險合約之間","提供利益的合約之間","非提供彌償的保險合約之間","提供彌償的保險合約之間"],a:3,e:"分擔的原則只會應用在提供彌償的保\n險合約之間"},{c:"3.5.5",s:"當發生一項$1,000,000的財產損失，當中出現重複保險。此保單的全損為$30,000,000\n，另設有單一物件限制$5,000。這次總賠償金額為$995,000，這顯示以下哪項所述是正\n確的?",o:["所有其他有關保單都有分擔條款","這份保單有分擔條款","這份保單有比例分攤條款","所有有關保單均有比率之數條款"],a:1,e:"分擔條款又稱比率之數條款，把保險\n人的責任限於損失的某個比率份額。\n在重複保險的情況下，如果每份有關\n的保單均包含了這項條款的話，被保\n險人就不再可以單靠一個保險人而獲\n全額賠償。"},{c:"3.6.2",s:"代位如何出現?\ni) 在侵權法上\nii) 在合約上\niii) 在法規下\niv) 在損餘中",o:["i，ii，iii","i，ii，iv","ii，iii，iv","i，ii，iii，iv"],a:3,e:"代位權可透過以下多種方式產生，以\n上各項都是正確答案"},{c:"4.4",s:"以下哪項是保險銷售部門的職能範圍?\ni. 與產品各環節建立緊密的聯繫\nii. 加強銷售計劃\niii. 監察銷售成果和趨勢\niv. 印制產品單張及宣傳刊物",o:["i,ii,ii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:0,e:"印制產品單張及宣傳刊物不是保險銷\n售部門的職能範圍"},{c:"4.9(b)",s:"在一般保險中，以下哪項是「長尾業務」的特點?",o:["索賠可以在短時間內結清","保單承保時間較長","索賠時間很長，例如長至保單終期後五年甚至更長的時間","保單支付的時間很長"],a:2,e:"在長期責任業務 (long-tail\nbusiness)，\n這類業務的索償過程，從產生到之後\n的發展往往經歷一段長時間，例如長\n至保單終結後五年甚 更長的時間"},{c:"4.6(d)",s:"人壽保險合同的保費支付有著獨特之處，以下哪項描述是正確?",o:["總是每月形式支付","人壽保險的保費較一般保險為低","合同存在與否是看是否收到第一期保費","保費可於保險期內任何時間支付"],a:2,e:"人壽保險合同存在與否是看是否收到\n第一期保費"},{c:"4.1",s:"以下哪項有關全新產品「具有競爭力的壽命」的描述是正確的？",o:["非常短，通常只有幾個星期或幾個月","大約一年","在競爭對手把焦點集中在新的保險產品之前， 至少兩年時間","非常之長"],a:0,e:"全新產品「具有競爭力的壽命」非常\n短，通常只有幾個星期或幾個月"},{c:"4.5",s:"人壽保險核保部門眼中的「目標風險」，較可能屬於以下哪類風險？",o:["極高保額的風險","保險人尤其願意承保的風險","保險人尤不願意承保的風險","有關保險代理人可得到較高佣金率的風險"],a:1,e:"目標風險在人壽保險中可以解釋為極\n為合意的業務類型"},{c:"4.5",s:"對於核保部門而言，「拒絕名單」涉及︰",o:["應予鼓勵接受更多的風險","不應予鼓勵接受風險或應拒風險","代理人在該年度內無須接受更多業務的指示","直到繳交保費前無須接受新業務的指示"],a:1,e:"對於核保部門而言，「拒絕名單」涉\n及不應予鼓勵接受風險或應拒風險"},{c:"4.7",s:"處理人壽及非人壽索償時有的共同特性是數額的問題及",o:["如何處理彌償的問題","分擔的問題","責任的問題","代位權的問題"],a:2,e:"處理人壽及非人壽索償時有的共同特\n性是數額的問題及責任的問題"},{c:"4.9",s:"「精算師」角色在各類保險產品中日見重要，當中尤為與那類別至為緊密",o:["汽車保險","人身意外保險","人壽保險","家居保險"],a:2,e:"「精算師」角色在各類保險產品中日\n見重要，當中尤為與那類別至為緊密"},{c:"4.9",s:"一種要經過一段時間後，索償才會出現或形成的保險，精算師可說是居功不少，以下哪\n個是正確的。",o:["長期責任業務","短期責任業務","長期保單","長期業務"],a:0,e:"在長期責任業務在計算所需未決申索\n儲備金，尤其需要精算師的專業知識"},{c:"5.1.3",s:"為學術及專業考試的目的，保險往往按照保險標的或保險的功能分為",o:["人身保險","財產保險","經濟權益保險","以上各項皆是"],a:3,e:"學術及專業考試目的，保險往往按照\n保險標的或保險的功能分為人身保險\n，財產保險\n，責任保險及經濟權益保險"},{c:"5.1.3",s:"以下哪項屬於保險的學術上類別的分類?",o:["火災保險","財產保險","僱傭保險","以上各項皆是"],a:1,e:"財產保險屬於保險的學術上類別的分\n類"},{c:"5.5.1",s:"以下哪項關於香港保險業聯會的陳述是正確的?",o:["它的目標之一是要推廣在香港經營業務的保險人的共同利益","多年來,所有在香港成立為法團或經營業務的保險人都是其會員","它是保險代理登記委員會所成立","它存在的目的就是為香港及世界其他地方推廣保險信息"],a:0,e:"香港保險業聯會它的目標之一是要推\n廣在香港經營業務的保險人的共同利\n益"},{c:"6.1.2b",s:"根據《承保商專業守則》，以下哪項是就保單所提出的建議？",o:["重要事實應以清晰的問題作出提問","對於續保時須要披露重要事實的最高誠信原則的要求，應予以詳盡的解釋","索償時解釋最高誠信原則要求的重要性","小心解釋任何附帶問卷的重要性"],a:1,e:"只有選項ii是根據《承保商專業守則\n》就保單所提出的建議，其他選項是"},{c:"6.2.1",s:"根據保險業條例，以下哪項是持牌保險經紀公司個負責人的委任條件?\ni. 負責人可以是持牌業務代表（經紀人）\nii. 負責人必須是適當人選\niii. 委任負責人之前，必先獲得保監局的認可\niv. 負責人可以是持牌經紀人",o:["i,ii,iii","i,ii,iv","ii,iv","以上各項皆正確"],a:0,e:"持牌經紀人不屬保險業條例五類牌照\n類別，選項iv不正確"},{c:"6.1.2",s:"以下哪項是《承保商專業守則》的描述是正確的?",o:["前稱《保險業條例》","規定了保險人獲得授權的最低要求","接管保監處規管香港保險業的法定職能","訂立符合標準的優保險做法"],a:3,e:"《承保商專業守則》是由保險業聯會\n執行，訂立符合標準的優保險做法，\n與保險業條例無關，只有選項iv正確\n。"},{c:"6.2.1",s:"根據保險業條例，以下哪一項是屬於五類持牌人士??",o:["持牌個人經紀","持牌負責人","持牌業務代表（經紀）","持牌保險代理公司"],a:2,e:"只有選項iii屬於五類持牌人士，根據\n條例五類持牌人士包括持牌個人保險\n代理，持牌業務代表(代理人)，持牌\n保險代理機構，持牌業務代表(經紀)\n及持牌保險經紀公司"},{c:"6.1.1f",s:"於香港的一般業務保險人必須就其從香港保險業務所產生的負債在香港維持正資產，以\n下哪項就所需數額計算的描述是正確的?\ni. 計算與淨負債額的80%有關\nii. 與淨負債額 （即已經扣除再保險所保的那部分）成正比\niii. 必須根據香港精算學會訂明匯算方法的其中一種方法計算\niv.計算保險人的淨負債額 （不扣除具爭議的債務）的80% 及有關數額加起來",o:["i,ii","i,ii,iv","ii,iii","ii,iii,iv"],a:0,e:"只有選項i,ii\n才是一般業務保險人所需數額計算的\n正確描述"},{c:"6.1.3",s:"以下哪項是保險投訴局(ICB)的描述是正確的?\ni) 涉及的投訴個案保單須屬個人保單\nii) 投訴委員會是由一位主席、四位委員組成\niii) 投訴委員會的委員中有兩位是來自保險業界\niv) 它是由所有在香港的獲授權保險人所組成",o:["i,ii,iii","i,iv","ii,iii","ii,iii,iv"],a:0,e:"所有所有在香港從事個人保險業務的\n獲授權保險人均必須申請成為保險投\n訴局的會員，選項iv不正確"},{c:"6.1.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["制訂規管保險業的有效策略","透過新的發牌制度，規管保險保險公司運作","對保單持有人和潛在保單持有人提供直接保障","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從業員"],a:0,e:"只有制訂規管保險業的有效策略屬於\n保險業監管局根據保險業條例承擔的\n職能或任務"},{c:"6.2.4(iv)",s:"以下哪項是持牌保險經紀公司的發牌條件?",o:["最少獲得1名獲授權的保險人委任","最少獲得4名獲授權的保險人委任","申請人並非持有保險代理機構牌照","申請人持有保險代理機構牌照"],a:2,e:"持牌保險經紀公司的其中一個發牌條\n件是申請人並非持有保險代理機構牌\n照"},{c:"6.1.1b",s:"根據《保險業條例》，實繳股本的最低要求為200萬港元適用於？",o:["綜合保險業務","專屬自保保險人","只經營一般業務","只經營長期業務"],a:1,e:"根據《保險業條例》，實繳股本的最\n低要求為200萬港元適用於專屬自保保\n險人"},{c:"6.2.2",s:"《保險業條例》第68條對_______________就其委任的保險代理人的作為須負上\n轉承責任。",o:["保單持有人","受保人","獲授權保險人","獲授權被保險人"],a:2,e:"《保險業條例》第68條對獲授權保險\n人就其委任的保險代理人的作為須負\n上 轉承責任"},{c:"6.1.1b",s:"有關保險人的獲授權要求，以下哪一項描述是正確的?",o:["《承保商專業守則》規定了保險人獲得授權的最低要求","同時經營一般及長期業務的實繳股本最高為2000萬港元","足夠再保險是保險人獲的授權的最低要求","《承保商專業守則》規定了“適當人選 ”的相關要求"],a:2,e:"《保險業條例》就有關的事宜，定明\n獲得授權的最低要求，當中包括：實\n繳股本；償付準備金；董事及控權人\n及足夠的再保險安排。"},{c:"6.1",s:"以下哪一項就《保險業條例》的描述是正確的?",o:["《保險業條例》原稱《保險公司規管條例》","《保險業條例》涵蓋對保險人及保險中介人的監察和規管","《保險業條例》於2015年經修訂後由保險業監理處執行","《保險業條例》2017年6生效後，已重新命名為《保險公司條例》"],a:1,e:"《保險業條例》涵蓋對保險人及保險\n中介人的監察和規管，其他選項都不\n屬"},{c:"6.1.1f(e)",s:"在某些情況下，保險業監管局現在可以披露某些財務和統計資料，然而，不得披露個別\n保單持有人的這種資料，除非",o:["在涉及欺詐時","在明確的法律程序下","在有關保單持有人死亡之後","在保單持有人被宣佈破產時"],a:1,e:"在某些情況下，保險業監管局現在可\n以披露某些財務和統計資料，然而，\n不得披露個別保單持有人的這種資料\n，除非在明確的法律程序下"},{c:"6.2.4",s:"個人持牌人承擔並非與進行受規管活動有關的責任，該等責任是否將會引致利益衝突，\n涉及甚麼領域?",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:1,e:"個人持牌人承擔並非與進行受規管活\n動有關的責任，屬於適當人選中勝任\n能力的範疇"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有保證價值此事實","保險人未有及時將續保條款及時通知保單持有人的投訴","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒有\n驗證其真實年齡","年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，導致損失了有關的保\n單利息"],a:1,e:"與服務水平有關的投訴個案，不屬於\n保險投訴局的職務範圍"},{c:"6.1.3c",s:"以下哪項與索償無關的個案屬保險投訴局的職權範圍?\ni. 一項涉及100,000港元的保單爭議金額\nii. 已就該糾紛個案進入法律程序\niii. 保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒\n有驗證其真實年齡\niv. 對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單是屬於「抗通脹保\n單」",o:["i, ii","i,ii,iv","ii,iii","i,iii,iv"],a:3,e:"保險投訴局受理的投訴個案不可以正\n在進行法律程序或仲裁。"},{c:"6.1.1f",s:"為更有效規管保險人名保單持有人的利益，以下哪項是《2015年修訂條例》下保監局獲\n賦予新增的規管權力?",o:["進行查察、展開調查及向獲授權保險人施加罰款的權力","命令一個保險集團的每個成員委任獨立審計師的權力","命令保險人以審計署作為審計師的權力","進行查察及對未應健全承保政策的保險人展開調查及向獲授權保險人施罰款的權力"],a:0,e:"進行查察、展開調查及向獲授權保險\n人施加罰款的權力是《2015年修訂條\n例》下保監局獲賦予新增的規管權力"},{c:"6.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["制訂規管保險業的有效策略","對保單持有人提供直接保障","促進保險業市場的高速發展","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從業員"],a:0,e:"制訂規管保險業的有效策略，屬於保\n險業監管局根據保險業條例承擔的職\n能或任務"},{c:"6.1.1f(iii)",s:"償付準備金的計算方法為",o:["保險人的流動資產除以流動負債","保險人的流動資產減去流動負債","保險人的資產減去負債","以上都不是"],a:2,e:"償付準備金的計算方法為保險人的資\n產減去負債"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求描述是正確的?",o:["代表保險人的第三者，應該具備相關經驗","代表保險人的第三者，應該相關經驗及具備專業資格","不得委派律師或理賠師以外第三者","代表保險人的第三者，在任何情況下都應當合理地行事，並且應該具備專業資格"],a:3,e:"根據《承保商專業守則》代表保險人\n的第三者（理賠師等），在任何情況\n下都應當合理地行事，並且應該具備\n專業資格。"},{c:"7.2.1(c)(i)",s:"向客戶提供一份「收集個人資料聲明」，應包括些甚麼?\ni. 清楚説明收集資料的目的\nii. 資料可能會轉移給什麽類別的人\niii. 不提供資料所須承受的後果\niv. 要求查閲及改正資料的權利",o:["i,ii,ii","i,ii,iv","i,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是「收集個人資料聲明」\n包括的內容"},{c:"7.4.4",s:"以下哪項屬於洗錢的階段?\ni. 整合\nii. 投資\niii. 分層交易\niv. 轉化交易",o:["i,ii,iii","i, iii,iv","ii,iii,iv","i,iii"],a:3,e:"洗錢通常分為3個階段，按次序是存放\n，分層交易及整合。"},{c:"7.5.1b(iii)",s:"根據《防止賄賂條例》，款待不是利益，以下哪項屬款待的定義?",o:["酒店住宿","歌舞節目表演","即場享用之美食","海外公幹"],a:2,e:"即場享用之美食屬款待不是利益"},{c:"7.4.7c",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3），保險機構的高級管理層有責任實施\n有效的打擊洗錢及恐怖分子資金籌集制度，所制訂的管控措施應涵蓋的範疇包括﹕",o:["限制接受外幣","委任一名法律主任","成立一個情報單位","以上各項皆不是"],a:3,e:"以上各項皆不是打擊洗錢及恐怖分子\n資金籌集制度所制訂的管控措施"},{c:"7.2.2",s:"在《個人資料（私隱）條例》涉及範圍中，就保險人所擁有保單持有者的資料使用上，\n以下哪項是合法的？",o:["向保單持有人的親屬透露其壽險保單資料","向保單持有人發出續保通知","向著名的報紙出賣被保險人資料","以上所有各項"],a:1,e:"向保單持有人發出續保通知在《個人\n資料（私隱）條例》涉及範圍中是容\n許的"},{c:"7.5.1",s:"以下哪項觸犯了《防止賄賂條例》第9(三)條?",o:["一名持牌個人保險代理人意圖利用偽造的保險申請書來騙取保險公司的佣金","保險公司的採購人員提交虛假文件，令採購合約判給與該名採購人員有關連的公司","一名持牌業務代表(代理人)偽造培訓紀錄以騙取培訓津貼","以上各項皆是"],a:3,e:"以上各項皆是觸犯了《防止賄賂條例\n》第9(三)條的例子"},{c:"7.5.1",s:"以下哪一項是《防止賄賂條例》下僱員應該遵守或避免的行為?",o:["僱員從事有關業務或事務時，如未經僱主同意，不得創業","僱員從事有關業務或事務時，如未經僱主同意，不得在其關係終止5年內創業","僱員從事有關業務或事務時，如未經僱主同意，不得索取或接受任何利益","僱員從事有關業務或事務時，如未經僱主同意，不得委任分代理人"],a:2,e:"根據《條例》第9(1)條的規定，代理\n人在處理其主事人的業務或事務時，\n如未經主事人的允許，不得索取或接\n受任何利益"},{c:"7.6.1",s:"犯罪者不是以主犯的身份犯罪就是以那麼的身份犯罪?",o:["次犯","從犯","助犯","刑事代替犯"],a:1,e:"犯罪者不是以主犯的身份就是以從犯\n的身份參與犯罪。一項刑事罪的從犯\n是指一名協助、教唆、慫使或促致犯\n該罪行的人"},{c:"7.2.1",s:"根據《個人資料（私隱）條例》保障資料第1原則，若資料使用者收集個人資料時",o:["個人資料應是準確的,最新的，其保留期限不應超過所需時間","合法和公平地收集個人資料","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資料處理者的個人資料\n的保存時間超過處理該資料所需的時間","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資料處理者的個人資料\n的保存時間超過30天"],a:1,e:"保障資料原則第1原則:收集個人料的\n目的及方式，此原則描繪如何合法和\n公平地收集個人資料"},{c:"7.5",s:"以下哪項是貪污，必須避免觸犯？",o:["個人為謀取私利，從而引至社會利益受損","個人為謀取私利，濫用職權，從而引至他人利益受損","個人未經準許謀取私利，從而引至他人利益受損","個人挪用屬於他人的財產"],a:1,e:"貪污是指個人為謀取私利，濫用職權\n，從而引至他人利益受損"}],"paper1-2025-11":[{c:"1.1.2b",s:"商業保險人所保的風險主要是對____________________提供保障。",o:["特定風險","基本風險","純粹風險","投機風險"],a:0,e:"商業保險人所保的風險主要是對特定風\n險提供保障"},{c:"1.1.2b(ii)",s:"以下哪項對於基本風險的描述是正確?",o:["泛指地震等的天然災害","只影響個別的保單持有人","影響到整個社會而非個人","A 及C都正確"],a:3,e:"基本風險包括饑荒、戰爭、恐怖襲擊等\n數、大規模洪災等。這些災害影響到整\n個社會或人類，而非其中的特定個體，\n所以A 及C都正確。"},{c:"3.3.3(iii)",s:"如果索償涉及______________，該項索償很有可能被拒",o:["不保危險","除外危險","自然災害造成的損失","人為錯誤"],a:1,e:"除外危險的發生一般會令保險索償\n或保險金要求失敗，但複雜的例外情況\n是存在的。"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni. 保險為本港提供就業機會\nii. 保險對受保損失的被保險人提供財務補償\niii. 一般保險的慣例下倡導防範損失的措施\niv. 某些業務可以涉及很高的純粹風險，或會令投資者卻步，除非他們可以投保潛在的\n財務損失",o:["i, ii, iii","i, ii","i,iii,iv","i, ii, iii, iv"],a:2,e:"保險對受保損失的被保險人提供財務補\n償可視為保險為香港帶來的基本功能/\n好處，,選項(ii)不正確"},{c:"1.1.1",s:"有一類風險會使我們情緒上感到難過及悲傷，但並不涉及財務損失。這類風險",o:["在任何情況下是可保的","通常得到承保","只有損失是由意外造成才受保的","相當可能不受保"],a:3,e:"難過及悲傷的情緒上損失難以用金錢衡\n量損失，以商業方式處理此等風險，在\n財務上是不可行的。"},{c:"1.1.1",s:"保險與風險之間的聯繫如何 ?",o:["有些風險(不過並非所有種類)是可保的","若有保險的保障，所有財務損失都是保險人的責任","風險提供保障的唯一方法就是保險","所有類型的風險都是可保的"],a:0,e:"例如財務上及身體上的風險較有可能成\n為商業上的可保風險，不過並非所有種\n類的風險是可保的"},{c:"1.1.2a",s:"從可保程度的角度來看，純粹風險屬於",o:["永不可保的","必然可保的","可保程度可能低於投機風險","可保程度可能高於投機風險"],a:3,e:"商業保險人所保的風險主要是純粹風險\n及特定風險，投機風險及基本風險是較\n不可保。"},{c:"1.1.2b",s:"如果根據風險所帶來的影響區別，風險可以分為",o:["純粹風險及投機風險","可保風險及不可保風險","投機風險及特定風險","特定風險及基本風險"],a:3,e:"如果根據風險所帶來的影響區別，風險\n可以分為特定風險及基本風險"},{c:"1.1.3",s:"在投資術語中，「風險管理」一詞包括以下哪項?",o:["純粹風險和投機風險","投機風險","僅僅是可保風險","保險計劃的安排"],a:1,e:"在投資術語中，「風險管理」一詞包括\n投機風險"},{c:"1.1.3",s:"作為一門獨立的學科及研究的範圍，風險管理",o:["只處理純粹風險","只處理投機風險","可以處理純粹風險或投機風險","既非處理純粹風險也非投機風險"],a:2,e:"作為一門獨立的學科及研究的範圍，風\n險管理應對某家機構構成威脅的風險，\n不論是純粹風險還是投機風險"},{c:"1.1.3",s:"作為風險管理在獨立的知識及研究範疇上，一般的理解為",o:["投資或投機風險所帶來的損失","保險人對受保風險損失上的改善","以識別、量化及處理作為進行的步驟","環繞著對保險合約的訂立及處理"],a:2,e:"風險管理可以解釋為管理學的一個分支\n，它要進行的步驟包括識別、量化及處\n理"},{c:"1.2",s:"保險對社會有益處嗎？",o:["是有的，通過保險人要求而進行的風險防範或風險降低措施(統稱風險控制)","是有的，保險是社會的一種手段","沒有，僅僅是私人的安排","沒有，除非是強制的"],a:0,e:"保險對社會有益處的，通過保險人要求\n而進行的風險防範或風險降低措施(統\n稱風險控制)"},{c:"2.1.3(c)",s:"保險人於保險合約所付的代價是",o:["填寫投保書","提出要約後並承諾續保","依照保單條款的規定支付索償的承諾","以上各項皆不正確"],a:2,e:"保險人於保險合約所付的代價是依照保\n單條款的規定支付索償的承諾"},{c:"2.2.3",s:"「明示權限」的中的明示是指",o:["與明示合約條款中的「明示」的意思相同","於迫切或危急情況發生後必要的授權","委託人對代理人已作出具體的指示","委託人對代理人的指示總是書面的"],a:2,e:"明示是指以口頭或書面方式故意授予的\n實際權限，最貼近這個定義的答案是C"},{c:"2.2.3(b)",s:"表面權限意味著",o:["授權不存在，而且代理人的行為會對委託人並沒有約束力","基於過去的交易，代理人的行為會對委託人產生約束力","權限是透過委託人表明同意而產生的，並可能會對委託人產生約束力","在緊急的情況下持有必要權限為委託人採取行動，並成為必要代理人"],a:1,e:"表面權限是當一個代理人的權限是透過\n委託人對第三者(不是委託人)表明同意\n而產生的，基於過去的交易，代理人的\n行為會對委託人產生約束力"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構成要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就沒\n有合約。"},{c:"2.1.3",s:"以下哪項正確描述無效的合約？",o:["保險人可以取消合約","任何一方可以取消合約","合約在法律上不存在，完全無法律效力","保險人已拒絕賠償"],a:2,e:"無效的合約指所擬訂的合約在法律上不\n存在，完全無法律效力"},{c:"2.1.3",s:"以下哪項可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含義完全相同","受屈的一方可於合理時間內把合約視為無效的決定","只有被保險人才能把保單視作可使無效(即可予以取消)"],a:2,e:"可使無效的合約是項明顯有法律效力的\n合約，其法律效力一直維持下去，除非\n及直至有受屈的一方把合約視為自訂立\n時起即屬無效，但須在一段合理時間內\n進行"},{c:"2.1.3(b)",s:"在一份建議合約上的要約對象稱為",o:["要約人","受要約人","被動人","準客戶"],a:1,e:"在一份建議合約上的要約對象稱為受要\n約人"},{c:"2.1.3(c)",s:"安琪在登機前購買一份旅遊保險，保險人容許她在旅程後繳付保險費。安琪不幸在旅\n程中斷了一條腿，保險人拒絕賠付安琪有關的醫療費用，請問保險人有權這樣做嗎？",o:["沒有。根據承保商專業守則，保險人須就投保人合理的期望賠","沒有。一張旅遊保險合約已經生效","有。保險人若賠付只出於同情","有。安琪沒有交保費"],a:1,e:"如果所保事故在支付已承諾的保費以前\n已經發生，被保險人仍然享有索償權，\n而保險人則另外有權追討未繳清的保費\n，答案B正確"},{c:"2.1.3(f)",s:"一份協議是缺乏與另一方訂立法律關係的意向情況下訂立，因此",o:["技術上它是合約","技術上它是協議","不能是合約","受屈一方有權索取賠償"],a:2,e:"完整合約要素包括訂立法律關係的意向\n，合約如要有效，各方必須清晰地表示\n有意給有關合約具有法律效力"},{c:"2.2.2",s:"雖然在行動時並未獲授權，但只要委託人事後確認該行動，就如同給予一種追溯性的\n授權。此種情況下產生之代理關係稱為",o:["通過協議","明示協議","追認","隱含授權"],a:2,e:"追認是指對某行為授予追溯權。即雖然\n\\代理人在行事時並未取得授權，但只\n要委託人事後確認該行動，就有效地產\n生了一種追溯性的授權。"},{c:"2.2.3(a)",s:"「明示權限」的明示是指",o:["與明示合約條款中的「明示」的意思相同","於迫切或危急情況發生後必要的授權","委託人已明確地指示代理人","委託人對代理人的指示必須是書面的"],a:2,e:"「明示權限」的明示是指委託人已明確\n地指示代理人"},{c:"2.2.3(c)",s:"如果出於人道或其他合理的原因，某人承擔並支付代理另一人行事的開支，則即使他\n人沒有在產生開支期間或之後授權，此人也可以被認為是他的代理人，這種代理關係\n的成立是基於",o:["明示權限","不容反悔","必要權限","追認"],a:2,e:"如某人受着迫切的危害而不存在向他通\n報的機會，一名現有代理人在這個危急\n的情況下必地為該人採取行動的話，可\n以說該代理人持有必要權限作出該等行\n為，並透過該等行為成為必要代理人。"},{c:"2.2.6",s:"如果代理協議在生效六個月後變成非法，以下哪項有關該協議的描述是正確的?",o:["即時終止","必須待至期限終結","其中一方提出便可終結","雙方同意便可終結"],a:0,e:"如果代理關係或代理協議的履行不再為\n法律所容許的話，協議便會自動終止"},{c:"2.2.6",s:"以下哪項或哪些有關由於精神錯亂而導致代理人關係的終止的描述是正確的？",o:["只有代理人可終止而不能是委托人","只有委托人一方可終止而不能是代理人","代理人和委托人（自然人）均可終止","代理人和委托人均沒有權力終止"],a:2,e:"如果委託人和代理人的任何一方因精神\n錯亂不再能夠履行協議，則協議會自動\n終結"},{c:"3.4.4",s:"彌償最通常的方式是現金支付，其他方式包括？\ni.更換\nii.修理\niii.續保\niv. 恢復原狀",o:["i,ii","ii,iv","i,ii,iv","i,ii,iii,iv"],a:2,e:"續保不是彌償的方法，選項iii不正確"},{c:"3.1.2",s:"下列哪項有關缺乏可保權益的保險的陳述是不正確的?",o:["該項保險屬於可使無效","涉及保費是否退還等的法律問題","所有損失不獲賠償","該份保險合約從索償產生時被視為無效"],a:3,e:"缺乏可保權益的話，有關保險協議便屬\n無效，而退還保費的相關規則，則因所\n屬險種而異，相關規則例如《保險業條\n例》和《海上保險條例》的相關條文，\n答案D不正確"},{c:"3.4.5",s:"以下哪項對Salvage一詞的定義不正確?",o:["保險標的在受損後會留下剩餘部分稱為 「損餘 」","在提供彌償時，必須把該價值考慮在內","在海商法中，“Salvage”一詞帶有截然不同的 意思","只有在懲罰投保額不足時適用"],a:3,e:"懲罰投保額的限制彌償原則是比例分攤\nAverage，答案D不正確"},{c:"3.2.4",s:"在保單有效期內若在風險上出現的重大轉變，以下哪項或哪些對於這些轉變的評論是\n正確的？",o:["在合約有效期內，要求披露重要資料是一種特殊做法","在普通法中，在保險期限內如有風險上的變更，必須予以披露","可能因保單條款的要求而需要披露這些轉變","以上所有各項皆是正確評論"],a:2,e:"在保單有效期內若在風險上出現的重大\n轉變，可能因保單條款的要求而需要披\n露這些轉變"},{c:"3.1.3",s:"以下哪項可保權益的陳述是正確？",o:["盜賊可以替自己偷竊得來的賊贓物投購保險","可保權益只適用於人壽保險","某人與保險標的之間必須存在被法律認可的關係","以上各項皆不正確"],a:2,e:"可保權益是某人對某項保險標的在法律\n上被認可的一種關係，這種關係賦予他\n對該保險標的購買保險的權利。既然這\n種關係必須是合法的，盜賊並沒有權利\n就其管有的贓物 購買保險"},{c:"3.2.6",s:"就保單而言，非欺詐性不披露",o:["投保人無意地違反了保險條款","該保險人可以推翻保單","受屈的保險人僅可以訴訟提出損害賠償申索","投保人對重要事實作出失實陳述"],a:1,e:"非欺詐性不披露是無意地或疏忽地漏了\n向另一方披露重要事實，受屈的保險人\n可在合理時間内自始推翻整個合約"},{c:"3.3.2",s:"除外危險_____________",o:["保單不承保的危險","與不保危險有相同的對待","除超額保障以外，將承保的危險","例如各種天災，地震等"],a:0,e:"除外危險是被除外責任條款豁免承保的"},{c:"3.2.1",s:"正面回答所有被問及的問題並保證作出的回答是真實的，這屬於",o:["一般誠信","最高誠信","內在誠信","合約誠信"],a:0,e:"一般誠信是本着誠實的態度行事，所提\n供的資訊必須是實質上真實的"},{c:"3.1.4(b)",s:"於所有保險合約中，以下哪項保險項目在索償時需要有可保權益？\ni. 責任保險\nii. 汽車保險\niii. 船上貨物保險\niv. 人壽保險",o:["i,ii,iii","ii, iii, iv","i,ii,iv(cid:9)","i,iii,iv"],a:0,e:"在水險或其他類型的彌償保險，可保權\n益只須損失時存在，所以選項i,ii,iii\n是正確。"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["轉讓人不會把保險合約中的責任轉移到承讓人的身上","承讓人將取得收款人的權利，而非訴訟權","承讓人承讓人承諾支付未來的保費","承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費"],a:0,e:"保單「轉讓」通常是指權利的轉移。轉\n讓是不會讓轉讓人在保險合約的責任轉\n移到承讓人的身上的"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約性質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險人的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓收\n取保險金的權利無需取得保險人的同意"},{c:"3.4.5",s:"以下哪項不是Salvage一詞的定義?",o:["在海商法中，有關財物擁有人向救助人支付的”救助賞金”","於非海上保險中，指保險標的受損後的殘餘價值","懲罰不足投保額","以上各項皆不是"],a:2,e:"懲罰不足投保額的比例分攤原則的英文\n名稱是Average。"},{c:"3.1.4",s:"構成財產保險可保權益的是",o:["在擁有人同意下管有該項財產","需對保管的財產的損失負責","絕對擁有該項財產","以上各項皆是"],a:3,e:"構成財產保險可保權益的條件，可以是\n持有次於絕對擁有權的權利，分別為遺\n產、信託財產、按揭財產投保。"},{c:"3.1.4(b)",s:"阿倫給予他的朋友玫瑰一個他所擁有的單位免費住兩個月，請問玫瑰有權為該單位購\n買保險?理由何在?",o:["有，合法地佔有某單位的任何人有權以所有人的代理人的身份就該單位購買保險","沒有，因為她沒有付出代價","有，她是以單位託管人的身份人對該單位具有權益的","沒有，因為她並非擁有該單位"],a:2,e:"受託保管人持有次於絕對擁有權，在得\n到某貨品的擁有人或其代理人的同意下\n，管有該貨品的人可以對所保管的貨品\n進行投保。"},{c:"3.1.5",s:"以下哪項或哪些情況出現之損失或索償，在沒有構成可保權益下，都不會形成拒絕損\n失索償的理由",o:["人壽保險(被保險人為前配偶，現已離婚)","火險，由「前承按人」購買(欠款已於火災前清還)","車險(汽車於意外摧毀前己賣出)","以上各項"],a:0,e:"在人壽保險中，可保權益只須在保單起\n保時存在。"},{c:"3.1.6",s:"收取保險金的轉讓，意思是指",o:["必須把保單應該支付的金錢轉付予指定的第三者","把保單轉讓予另一保險公司","把保單的擁有權轉讓予他人","讓另一個人替代原本的被保險人"],a:0,e:"收取保險金的轉讓，意思是把保單應該\n支付的金錢轉付予指定的第三者"},{c:"3.2",s:"最高誠信的責任適用於",o:["被保險人而非保險人","保險人而非被保險人","任何情況下的被保險人及保險人","被保險人及保險人，但只限於保單有這要求"],a:2,e:"可以說，最高誠信是對投保人或被保險\n人定下一項披露資訊的責任。技術上，\n保險人須負同樣的責任。"},{c:"3.2.4",s:"在非人壽保險單續保時，最高誠信的責任",o:["要再履行","無須履行","不再適用","只對保險人適用"],a:0,e:"一些非人壽保單要求，在保險期限內\n如有風險上的變更或續保時，例如買了\n人身意外保險後轉職，必須予以披露。"},{c:"3.3.2",s:"下列哪三種屬於決定一項損失的近因時，須予考慮的危險種類？\ni) 受保危險\nii) 不保危險\niii) 額外危險\niv) 除外危險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"額外危險是近因原則須予考慮的危險種\n類，選項iii不正確"},{c:"3.3.2",s:"就近因而言，描述相關承保風險所引致損失的成因稱為",o:["風險","危險","投機風險","事故"],a:1,e:"為了找出損失的近因，我們經常須要分\n析在整個引致該損失的過程中，所涉及\n的成因，這種分析很大程度上視乎有關\n危險(亦即有關損失的成因)的識別。"},{c:"3.3.4",s:"保險單",o:["從不更改近因原則","通常排除應用近因原則","可能包含更改應用近因原則的短句","符合以上各項陳述"],a:2,e:"很通常保險人借助某些保單措詞，更改\n近因法則的應用"},{c:"3.4.2",s:"人壽與人身意外保險都不受彌償的原則約束，因為",o:["人命是可以財務計算價值","不可能以財務方法精確計算人命的","保險人不願意作出十足的財務補償","以上所以各項"],a:1,e:"壽險及個人意外保險是提供利益的保單\n，而不是提供彌償的保單。因人命的損\n失不可能以財務方法精確計算，壽險及\n個人意外保險能辦到的僅是按照死亡或\n損傷訂明的數額支付利益"},{c:"3.4.3",s:"彌償與可保權益這兩項保險原則",o:["是完全相同的","是毫不相干的","與近因原則的關係非常密切","皆有共同的基礎，因爲他們均涉及被保險人的財務權益"],a:3,e:"可保權益是對某項標的的財務「權益」\n，就全損的情況下賠付多少錢才能讓保\n單持有人得到完全的彌償，所以彌償與\n可保權益這兩項保險原則，皆有共同的\n基礎，因爲他們均涉及被保險人的財務\n權益"},{c:"3.4.6",s:"當被保險人提出索償時，將損餘部份交予保險人以換取索取全數賠償。可能在機緣巧\n合下，在出售損餘後的款項高於實質賠償的金額，那麼",o:["保險人便可賺取不俗的利潤","盈餘須與被保險人以五五分賑形式分享","這項事宜須呈予法庭解決","盈餘須歸予被保險人"],a:0,e:"委付是保險標的或它的殘餘部分必須完\n全地移交給保險人，致使保險人可從中\n獲取利益"},{c:"3.4.7",s:"在水險中，術語「海損」的意思是",o:["部分(非全部)的損失","對不足額保險的懲罰","吸引標準保費率的風險","損失後標的的殘餘價值"],a:0,e:"在水險中，「海損」的意思所指的是部\n分損失，即不屬全損的損失。"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約定價值$1,000,000」\n，意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方式\n提供保險保障的，約定價值一律被視為\n損失時的實質價值"},{c:"3.5.1",s:'假設銀行借錢給"A"購買物業，不尋常地，該銀行對該物業的權益購買保險保障，而"A\n"亦按照其意志投買保險，如果投保損失發生',o:["按照分擔原則，兩名保險人各自賠償50%","分擔原則不適用，因不是保險相同的權益","A的保單將作出賠償，因他是物業的真正擁有者","銀行的保單將作出賠償，因為借貸協定給它優先權"],a:1,e:"分擔原則不適用，因業主A與銀行所購\n買的保險所保障的權益不相同"},{c:"3.5.5",s:"當發生一項$1,000,000的財產損失，當中出現重複保險。此保單的全損為$30,000,000\n，另設有單一物件限制$5,000。這次總賠償金額為$995,000，這顯示以下哪項所述是\n正確的?",o:["所有其他有關保單都有分擔條款","這份保單有分擔條款","這份保單有比例分攤條款","所有有關保單均有比率之數條款"],a:1,e:"分擔條款又稱比率之數條款，把保險人\n的責任限於損失的某個比率份額。在重\n複保險的情況下，如果每份有關的保單\n均包含了這項條款的話，被保險人就不\n再可以單靠一個保險人而獲全額賠償。"},{c:"3.5.5",s:"一份商業火險保險單含有所謂的「海上條款」，這條款的主要目的是",o:["豁免承保儲存在碼頭旁邊倉庫裡的財產","避免和任何足額水險分擔","確保任何承保了有關財產的現有水險無效","如果有水險保單也承保了有關財產，就可以完成避開火險保單"],a:1,e:"標準火險保單中的所謂「海上條款」規\n定，如果在水險單與火險單之間存在潛\n在的分擔，火險單將不分擔損失，答案\nＢ正確"},{c:"4.5(b)",s:"在一般保險承保中，以下哪項是出現錯誤的優勢?",o:["錯誤從不可犯","保單在續保時，條件可以檢討，在必要時保單甚至可以取消","錯誤可用計算機自動修正","錯誤有特別的保單承保"],a:1,e:"一般保險的核保過程中出現的錯誤並不\n是永久性的，保單在續保的時候，條件\n可以檢討，必要時保單甚至可以取消\n。正確答案是B"},{c:"4.7(a)",s:"以下哪項不屬人壽保險的理賠樣須考慮的問題?",o:["對於死亡的真確性或死者的身份","驗證最大賦值","可能有還未清償的保單貸款","分紅保單涉及紅利／股息的因素"],a:1,e:"驗證最大賦值不屬人壽保險的理賠樣須\n考慮的問題"},{c:"4.6(d)",s:"人壽保險合同的保費支付有著獨特之處，以下哪項描述是正確?",o:["總是每月形式支付","人壽保險的保費較一般保險為低","合同存在與否是看是否收到第一期保費","保費可於保險期內任何時間支付"],a:2,e:"人壽保險合同存在與否是看是否收到第\n一期保費"},{c:"4.1",s:"哪句說話最可以形容產品開發部的功能?",o:["針對小客戶而設","對維持保險公司的競爭力至為重要","為應付法規要求而設","純粹為行銷目的而設"],a:1,e:"由於競爭對手樂於倣效及抄襲別人的新\n產品，全新產品具有競爭力的壽命極為\n短暫，可能只有數個星期而已。"},{c:"4.1",s:"對於保險人，產品的開發",o:["是一種延續不斷的過程","對大型保險人來說是沒有必要的","對強制性的業務來說是沒有必要的","在敲定了保單的用字後便不再需要"],a:0,e:"對於保險人，產品的開發是一種延續不\n斷的過程"},{c:"4.5",s:"核保的職責是",o:["製備核保手冊、訂費指引","製備拒絕名單","界定承保的風險","以上皆是"],a:3,e:"以上皆是核保的職責"},{c:"4.5",s:"在人壽保險這個類別，核保顯得十分重要，因為",o:["被保險的對像是人類","保險人不能取消保單","通常人壽保險涉及大額的保費","人壽保險能為保險代理人提供較高的佣金"],a:1,e:"在人壽保險這個類別，核保顯得十分重\n要，因為保險人不能單方面取消保單"},{c:"4.5",s:"以下哪項或哪些陳述有關一般保險核保是正確的?",o:["它們會集中在總部核部","它們涉及保障類型多不勝數","在每一份保單只能發生一次","包括以上各項"],a:1,e:"一般保險的保障類型多不勝數，答案B\n正確"},{c:"4.5",s:"火災保險中，「目標風險」一詞指",o:["沒有什麼價值的投保物件","一項大的，很高的風險","一項普遍的風險","很低的保險費率"],a:1,e:"火災保險中，「目標風險」一詞指一項\n大的，很高的風險"},{c:"4.5",s:"對於核保部門而言，「拒絕名單」涉及︰",o:["應予鼓勵接受更多的風險","不應予鼓勵接受風險或應拒風險","代理人在該年度內無須接受更多業務的指示","直到繳交保費前無須接受新業務的指示"],a:1,e:"對於核保部門而言，「拒絕名單」涉及\n不應予鼓勵接受風險或應拒風險"},{c:"4.9",s:"最可能涉及訂定保費率，計算儲備及債務估值的專業人士為",o:["損失公估人","精算師","會計師","核保人"],a:1,e:"涉及訂定保費率，計算儲備及債務估值\n的專業人士為精算師"},{c:"5.1.1",s:"保險業條例把保險業務分為兩類",o:["長期業務及短期業務","長期業務及一般業務","財產保險及非財產保險","水險及非水險"],a:1,e:"法定保險業務分類，是為保險業監管機\n構授權及監察而設，《保險業條例》把\n保險分為長期業務及一般業務兩類"},{c:"5.1.1",s:"以下哪項是保險法定類別中長期保險業務所包括的保障",o:["疾病","擔保","資本贖回","財產損壞"],a:2,e:"資本贖回屬於長期保險的業務範圍"},{c:"5.1.4",s:"對於特定的保險公司，「分出再保險」與「分入再保險」",o:["它們含有相同的意思","分出再保險以該公司作為再保險人","分入再保險為購買再保險的公司","以上所有各項皆不是"],a:3,e:"對於特定的保險公司，「分出再保險」\n與「分入再保險」的分别是分入再保險\n以該公司作為再保險人，分出再保險是\n保險人向其他保險人／再保險人購買保\n險，以上所有各項皆不正確"},{c:"6.2.4(c)",s:"負責人最低限度的經驗是",o:["最少2行業經驗，其中包括2年管理經驗","最少5行業經驗，其中包括2年管理經驗","最少10行業經驗，其中包括5年管理經驗","最少10行業經驗，其中包括10年管理經驗"],a:1,e:"負責人最低限度的經驗是最少5行業經\n驗，其中包括2年管理經驗"},{c:"6.1.2",s:"以下哪項是《承保商專業守則》提供建議及處理事宜?",o:["保單","銷售資料","投保書","以上各項皆是"],a:3,e:"以上各項皆是《承保商專業守則》提供\n建議及處理事宜"},{c:"6.2.4",s:"《持牌保險經紀操守守則》提及經紀操守守則的兩個目標，其中一項是",o:["頒布持牌保險經紀應遵守的操守原則及相關的標準及常規","監管保險公司及保障消費者","制定定價準則及規管市場行為","訂立持牌保險經紀的培訓標準"],a:0,e:"《持牌保險經紀操守守則》提及經紀操\n守守則的兩個目標，其中一項是頒布持\n牌保險經紀應遵守的操守原則及相關的\n標準及常規。"},{c:"6.1.2d",s:"有關承保商專業守則，誰有責任令保險人的代理人遵守?",o:["保險監管局","保險公司監管處","保險人的高級行政人員","相關保代理人的委託人的保險人"],a:3,e:"通常情況下，保險人負責確保它的保險\n代理人遵守所有適用的法律，答案D正\n確"},{c:"6.2.1",s:"根據保險業條例，以下哪項是持牌保險經紀公司個負責人的委任條件?\ni. 負責人可以是持牌業務代表（經紀人）\nii. 負責人必須是適當人選\niii. 委任負責人之前，必先獲得保監局的認可\niv. 負責人可以是持牌經紀人",o:["i,ii,iii","i,ii,iv","ii,iv","以上各項皆正確"],a:0,e:"持牌經紀人不屬保險業條例五類牌照類\n別，選項iv不正確"},{c:"6.1.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["制訂規管保險業的有效策略","透過新的發牌制度，規管保險保險公司運作","對保單持有人和潛在保單持有人提供直接保障","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從業員"],a:0,e:"只有制訂規管保險業的有效策略屬於保\n險業監管局根據保險業條例承擔的職能\n或任務"},{c:"6.1.1c",s:"以下哪幾項有關保險公司的償付準備金規定的描述是正確的?\ni. 償付準備金至少相當於 「有關數額」\nii. 一般業務及長期業務保險人有相同的最低償付準備金額要求\niii. 一般業務及長期業務保險人有不同的計算準則\nvi. 專屬自保保險人有另一套適用的計算準則",o:["i,ii,iii","i, iii,iv","ii,iii,iv","i,iii"],a:1,e:"從究一般業務不能少於一千萬港元，如\n經營法定保險業務則不能少於二千萬港\n元，長期業務保險人最低償付準備金額\n總額不能少於二百萬港元，選項ii不正\n確"},{c:"6.2",s:"《持牌保險代理人操守守則》一般原則4–勝任提供意見，持牌保險代理人應",o:["向客戶提供準確及充足的資料，使客戶得以作出知情的決定","具備所需特定技巧或知識的事宜進行受規管活動","應以合理標準的謹慎、技巧和努力進行受規管活動","應盡其最大努力避免利益衝突"],a:1,e:"《持牌保險代理人操守守則》一般原則\n4 –\n勝任提供意見:持牌保險代理人應具備\n適當程度的專業知識和經驗，及只可進\n行該代理人所勝任的受規管活動。"},{c:"6.1.1a",s:"在香港或從香港經營保險業務以前，任何「人」必先________________",o:["具備2000萬港元的實收資本","應對有關的保險中介人資格考試","獲得保險業監管局的授權","成為保險業聯會的會員"],a:2,e:"在香港或從香港經營保險業務以前，任\n何「人」必先獲得保險業監管局的授權"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是正確的？",o:["實繳股本是保險人獲得授權其中一項最低要求","實繳股本的管控人必須符合適當人選要求","同時經營一般及長期業務實繳股本要求最高為2000萬港元","實繳股本可按保費收入計算"],a:0,e:"不同的規定實繳股本數額是保險人獲得\n授權其中一項最低要求"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項是保險業監管局成立的政策目標？\ni. 就影響保險業的事宜，進行研究\nii. 提升保險業界在環球保險業市場的競爭力\niii. 協助特區行政長官維持香港金融穩定\niv. 提高保單持有人對保險產品和保險業的了解",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:1,e:"保險業監管局其中一項成立的政策目標\n是協助財政司司長維持香港金融穩定。"},{c:"6.2.4",s:"持牌個人保險代理應就其可能進行受規管活動的各類保險產品的性質及主要特點，以\n及所承保及其相關的風險有充分了解，屬於哪個領域?",o:["產品知識","合適性","清楚其知識的局限性","利益衝突"],a:0,e:"持牌個人保險代理應就其可能進行受規\n管活動的各類保險產品的性質及主要特\n點，以及所承保及其相關的風險有充分\n了解，《持牌保險代理人操守守則》中\n產品知識要求"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["列明保險中介人八大操守原則","由香港保險監管局執行","列明保險代理管理的優良保險做法","以上各項皆是"],a:2,e:"承保商專業守則由香港保險業聯會執行\n，列明保險代理管理的優良保險做法"},{c:"6.1.1f",s:"為更有效規管保險人名保單持有人的利益，以下哪項是《2015年修訂條例》下保監局\n獲賦予新增的規管權力?",o:["進行查察、展開調查及向獲授權保險人施加罰款的權力","命令一個保險集團的每個成員委任獨立審計師的權力","命令保險人以審計署作為審計師的權力","進行查察及對未應健全承保政策的保險人展開調查及向獲授權保險人施罰款的權力"],a:0,e:"進行查察、展開調查及向獲授權保險人\n施加罰款的權力是《2015年修訂條例》\n下保監局獲賦予新增的規管權力"},{c:"6.1.1f",s:"《保險業條例》列明經營一般業務的保險人必須就其從香港保險業務所產生的負債在\n香港維持資產，用來釐定這一數據的方法之一，是計算有關數額與以下之總和",o:["毛負債額（不扣除再保險部分）的80%","净負債額（扣除不保部分）的80%","净負債額（扣除再保險部分及可爭議負債）的80%","净負債額（扣除再保險部分）的80%"],a:3,e:"經營一般業務的保險人，必須就其從香\n港保險業務所產生的負債在香港維持資\n產，所需數額以訂明的兩種匯算方法之\n一計算，其一所要求的數額不能少於兩\n項的總和:(i)淨負債額（即已經扣除再\n保險所保的那部分）的百分之八十\n；及(ii) 有關數額。"},{c:"6.1.1f",s:"經營一般業務的保險人，須每年就香港有關的業務向保險業監管局呈交?",o:["經營香港及海外業務的保險人：須呈交一份經審計的一般業務報表，及一份經審計\n的資產產負債表","經營香港業務的保險人：須呈交一份經審計的一般業務報表，及一份經審計的資產\n產負債表，除非經營該業務少於兩年","經營香港業務的保險人：須呈交一份經審計的一般業務報表，及一份經審計的損益\n表","經營香港業務的保險人：須呈交一份經審計的一般業務報表，及一份經審計的資產\n產負債表"],a:3,e:"經營一般業務的保險人，須每年就香港\n有關的業務向保險業監管局呈交須呈交\n一份經審計的一般業務報表，及一份經\n審計的資產產負債表"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求描述是正確的?",o:["代表保險人的第三者，應該具備相關經驗","代表保險人的第三者，應該相關經驗及具備專業資格","不得委派律師或理賠師以外第三者","代表保險人的第三者，在任何情況下都應當合理地行事，並且應該具備專業資格"],a:3,e:"根據《承保商專業守則》代表保險人的\n第三者（理賠師等），在任何情況下都\n應當合理地行事，並且應該具備專業資\n格。"},{c:"6.1.3c",s:"以下哪項無權享有向保險投訴局提出爭議個案有關的投訴?",o:["提供保費融資的銀行保單持有人","保單共同所有人","保單受益人","合法索償人（如承讓人）"],a:0,e:"有權向保險投訴局的投訴人必須為保單\n持有人、保單受益人、受保人或合法索\n償人（如承讓人）"},{c:"6.2",s:"有關《持牌保險代理人操守守則》，以下哪項描述是正確的?\ni.該守則由保監局頒布\nii.該守則列明八項持牌保險代理人應遵守的基本操守原則的一般原則\niii.為《保險業條例》提供指引，考慮持牌保險中介人是否屬繼續持牌的適當人選\niv.該守則保險業條例的附屬法例及有法律效力",o:["i, ii","i, ii, iii","ii, iv","ii, iii, iv"],a:1,e:"守則保險業條例的附屬法例及有法律效\n力"},{c:"6.2.5(a)",s:"根據規則3，任何人最多可獲4名獲授權保險人委任為“持牌人士”—持牌保險代理或\n持牌個人代理—進行受規管活動，其中獲授權經營__________________不得超過2名。",o:["一般業務的保險人","長期業務的保險人","綜合業務保險人","以上各項皆不是"],a:1,e:"任何人最多可獲4名獲授權保險人委任\n為“持牌人士”—持牌保險代理或持牌\n個人代理—進行受規管活動，其中獲授\n權經營長期業務的保險人不得超過2名"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項有關最低實繳股本的要求是正確的 ?\ni)專屬自保保險公司為港幣200萬元\nii)只從事相連長期保險業務的保險人為港幣1,000萬元\niii)同時從事一般業務及長期業務為港幣2,000萬元\niv)從事一般業務的保險人﹝包括法定保險業務﹞為港幣2,000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"四個最低實繳股本的要求描述都正確，\n詳細請參閱研習資料手冊 6.1.1b"},{c:"6.1.3a",s:"保險索償投訴委員會成員是由以下哪個團體所委派",o:["保險投訴局","保險業聯會","保險監督","壽險業協會"],a:0,e:"保險索償投訴委員會成員是由保險投訴\n局所委派"},{c:"6.2.5(g)",s:"保險經紀備存的妥善簿冊及帳目，所需保留的最低限期為",o:["一年","三年","五年","七年"],a:3,e:"保險經紀備存的妥善簿冊及帳目，所需\n保留的最低限期為七年"},{c:"7.6.2(b)",s:"就保險詐騙性索償，保險中介人有以下哪項責任?\ni. 拒絕索償\nii. 執行相關法律\niii. 舉報可疑事件或提供證據\niv. 協助保險人揭露詐騙行為",o:["i,iii,iv","i,ii,iv","iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是就保險詐騙性索償，保險\n中介人須要負上責任"},{c:"7.6.2",s:"以下哪碰項有關保險詐騙的陳述是正確的?",o:["舉報保險詐騙是中介人的責任","失實地陳述投保資料 ，即屬詐騙","失實地陳述投保資料，即屬詐騙","以上各項皆正確"],a:3,e:"以上各項皆是有關保險詐騙的正確陳述"},{c:"7.2.1",s:"個人資料（私隱）條例》列明的六項保障資料原則， 以下哪一項就第 1 原\n則的描述正確?",o:["個人資料保留期限不應超過所需時間","個人資料應是準確的、最新的，其保留期限不應超過所需時間","採取適當的保安措施，以確保個人資料受保障而不受未獲准或意外的查閱","描繪如何合法和公平地收集個人資料"],a:3,e:"保障資料第1原則:收集個人資料的目的\n及方式，此原則描繪如何合法和公平地\n收集個人資料，及當資料使用者收集某\n人的個人資料時，必須向該資料當事人\n提供的訊息。"},{c:"7.5.1",s:"以下哪一項是《防止賄賂條例》下僱員應該遵守或避免的行為?",o:["僱員從事有關業務或事務時，如未經僱主同意，不得創業","僱員從事有關業務或事務時，如未經僱主同意，不得在其關係終止5年內創業","僱員從事有關業務或事務時，如未經僱主同意，不得索取或接受任何利益","僱員從事有關業務或事務時，如未經僱主同意，不得委任分代理人"],a:2,e:"根據《條例》第9(1)條的規定，代理人\n在處理其主事人的業務或事務時，如未\n經主事人的允許，不得索取或接受任何\n利益"},{c:"7.2.1",s:"根據《個人資料（私隱）條例》保障資料第1原則，若資料使用者收集個人資料時",o:["個人資料應是準確的,最新的，其保留期限不應超過所需時間","合法和公平地收集個人資料","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資料處理者的個人資\n料的保存時間超過處理該資料所需的時間","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資料處理者的個人資\n料的保存時間超過30天"],a:1,e:"保障資料原則第1原則:收集個人料的目\n的及方式，此原則描繪如何合法和公平\n地收集個人資料"},{c:"7.3.2",s:"以下哪項有關保險人對投保人給予性別差別對待是法律容許的，並不觸犯歧視條例？",o:["有關待遇是藉參照可合理依據的來源所得的精算數據","有關待遇是藉參照可合理依據的來源所得的精算數據或其他數據而給予的","就有關因素而言屬於合理","一切參照可合理依據的來源所得的精算數據"],a:1,e:"保險人對投保人給予性別差別對待是藉\n參照可合理依據的來源所得的精算數據\n或其他數據而給予的"},{c:"7.3.3",s:"以下哪項或哪些是保險中的不公平歧視?",o:["向女性徵收比同一年齡、健康狀況等的男性較低的人壽保險保費率","向男性比同一年齡、健康狀況等的女性付出較高的年金款項","向女性駕駛者收取較高的保費","以上全部皆是"],a:2,e:"向女性駕駛者收取較高的保費是保險中\n的不公平歧視"},{c:"7.6",s:"對保險代理人而言，以下哪項或哪些技術性地構成詐騙？",o:["建議客戶不要透露某些重要事實","在詐騙索償中，沒有將明確的資料交給保險人","在安排保險過程中，故意隱瞞一些不良影響的資料","以上各項皆是"],a:3,e:"以上各項皆是技術性地構成詐騙的罪行"}],"paper1-2025-12":[{c:"1.2",s:"以下哪項是保險的基本功能／好處而非輔助功能？\ni)把個人的潛在財務損失轉移給保險人\nii)損失的控制/防範\niii)儲蓄／投資\niv)使商家倖免由於嚴重的火災、沉重的法律責任等情況而造成的巨大損失",o:["i, ii","ii, iii","i, iv","iii, iv"],a:2,e:"風險轉移及為損失作財務上的補償是保險的\n基本功能"},{c:"1.1.2(b)",s:"盜竊最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:2,e:"盜竊會有金錢上損失，純粹風險只具有財務\n損失的可能性"},{c:"1.1.3(c)(iii)",s:"就以下風險管理措施，提供安全訓練屬於",o:["風險避免","損失防範","損失降低","風險轉移"],a:1,e:"損失防範降低已識別出來的損失發生的頻率\n。提供安全訓練是例子"},{c:"1.1.2(b)",s:"汽車意外、個人損傷等情況，最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:0,e:"特定風險造成的後果是相對有限，例如汽車\n意外、個人損傷就是例子"},{c:"1.1.2",s:"商業保險人所保的風險主要是",o:["特定風險及基本風險","純粹風險及基本風險","純粹風險及特定風險","純粹風險及投機風險"],a:2,e:"商業保險人所保的風險主要是純粹風險及特\n定風險"},{c:"1.1.3",s:"以下哪項陳述是正確的?",o:["風險管理是工業科學的一項分科","風險管理是僅僅保險其中的一環","風險管理是與保險完全相同的學科","保險是風險管理的工具"],a:3,e:"保險只是處理風險其中一種工具或措施"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni. 保險對受保損失的被保險人提供財務補償\nii. 保險為本港提供就業機會\niii. 一般保險的慣例下倡導防範損失的措施\niv. 一般保險的慣例下倡導控制損失的措施",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:3,e:"保險對受保損失的被保險人提供財務補償屬\n保險的基本功能,選項(i)不正確"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni. 保險為本港提供就業機會\nii. 保險對受保損失的被保險人提供財務補償\niii. 一般保險的慣例下倡導防範損失的措施\niv. 某些業務可以涉及很高的純粹風險，或會令投資者卻步，除非他們可以投保潛在的\n財務損失",o:["i, ii, iii","i, ii","i,iii,iv","i, ii, iii, iv"],a:2,e:"保險對受保損失的被保險人提供財務補償可\n視為保險為香港帶來的基本功能/好處，,選\n項(ii)不正確"},{c:"2.1.3(b)",s:"在反要約的過程中，下列哪項是不正確的？",o:["原本的要約人成為受要約人","原本的受要約人成為要約人","原本的要約內容立刻被終止並撤銷","若反要約的內容不被接納，原本的要約內容可再次有效"],a:3,e:"如果受要約人有意更改合約條件，這種意向\n一經傳達便構成了反要約，後果是原要約內\n容失效"},{c:"2.1.3(d)",s:"有關「立約行為能力」，下列哪項陳述是正確的？\ni) 未成年者的立約能力受到限制\nii) 是指訂立合約的法律能力\niii) 精神病者的立約能力受到限制\niv) 是指有關業務開展的合法授權",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii ,iii, iv"],a:3,e:"訂約的行為能力是指訂立合約的法律能力。\n精神錯亂或未成年的個人可以選擇推翻他們\n所訂立的合約。又以公司為例，它們不得超\n越其法律權力而行事 。以上各項皆正確"},{c:"2.1.3(f)",s:"一份協議是缺乏與另一方訂立法律關係的意向情況下訂立，因此",o:["技術上它是合約","技術上它是協議","不能是合約","受屈一方有權索取賠償"],a:2,e:"完整合約要素包括訂立法律關係的意向，合\n約如要有效，各方必須清晰地表示有意給有\n關合約具有法律效力"},{c:"2.2",s:"「透過他人行事與自己親自執行並無分別」法律原則是來自",o:["合約法","代理法","侵權法","保險業條例"],a:1,e:"代理法律原則是「透過他人行事與親自執行\n並無分別」，代理人代表委託人行事，無論\n其結果好壞，\n經授權的行為或沒有授權的行為，都會對委\n託人產生約束力"},{c:"2.2.2",s:"代理的追認是指？",o:["代理人追認某次行動","代理人確認委託人","委託人追認代理人行動","委託人無須為代理負法律責任，除非代理作出追認"],a:2,e:"代理人在行事時並未取得授權，但只要委託\n人事後確認該行"},{c:"2.2.4",s:"一名代理人在下列哪種情況，可以把他的權限及責任下放給一位分代理人？",o:["任何時候，只要他願意便可","只當他具備這方面的權限","只要他認為合理才可","他可以這樣做，並有權從委託人收取雙份佣金"],a:1,e:"代理人不能把取得的代理權及承擔上的職責\n，下放給他人(分代理人），除非他具有這\n樣做的權限。"},{c:"2.2.6",s:"下列哪項或哪些屬於保險代理協議终止的途徑?",o:["撤銷","衝突或沒有達成協議","不忠誠","以上所有各項"],a:0,e:"撤銷屬於代理協議终止的其中一項途徑"},{c:"2.1.1",s:"合約是一項法律上可強制執行的協議",o:["然而這點是在它們以書面形式出現時才成立；","而且必須總是涉及重要的財務安排；","它們可能與重要的或較次要的事情有關；","然而只有以書面為證及在第三者見證下才成立。"],a:2,e:"合約所涉及的可以是瑣碎的事情，例如購買\n報章或乘電車，也可以是十分重要的事情，\n例如大型建築工程項目或僱傭合約"},{c:"2.2.3(a)",s:"明示權限是",o:["由委託人迅速地給予的","談判經蓋章的合約的授權","祇可談判書面的合約的授權","委託人明確地以口頭或書面形式賦予的授權"],a:3,e:"明示權限是委託人明確地以口頭或書面形式\n賦予的授權"},{c:"2.2.3(d)",s:"不容反悔的代理權是來自",o:["明示權限","法定條文","事後對代理人的行為所作的明確指示","據稱的委託人的行為"],a:3,e:"不容反悔的代理權的其中一項法則，是當據\n稱代理人完全沒被授權，但卻被容許看似獲\n委託人授權時應用的。"},{c:"2.2",s:"以下哪項對代理法的描述是正確的?\ni. 委託人受其代理人的行為所約束\nii. 代理人受其委託人的行為所約束\niii. 委託人受其代理人的行為而須負起轉承責任\niv.代理法只適用於保險代理人及經紀",o:["i,ii,iii","i,iii","ii,iii","i,ii,iii,iv"],a:1,e:"代理關係中的委託人，受其代理人的行為所\n約束，所以，委託人須就其代理人的作為或\n不作為負起轉承責任，另外，代理法適用的\n範圍，比保險代理人方面的應用廣泛得多，\n只有選項i,iii 正確，正確答案是B"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構成要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就沒有合\n約。"},{c:"2.1.2",s:"以下哪項陳述是正確的?",o:["保險合約屬於契據","大部分的保險合約屬簡單合約，因它可以用口頭或書面形式訂立","保險合約有效性必須以書面合約為證","保險合約屬於簡單合約，因內容淺白令一般人易於明白"],a:1,e:"簡單合約是意味着合約的訂立是簡單、容易\n的。因它可以用口頭或書面形式訂立"},{c:"2.2.5",s:"代理人代表委託人行事時招致的費用，委託人應",o:["只支付與交通有關的費用","只支付委託人事前同意的費用","向代理人報銷行事時適當及合理地招致的費用及開支","只支付在符合代理協定條件下的費用"],a:2,e:"在符合代理協定的任何明示條件下，委託人\n必須對代理人代表其行事時適當及合理地招\n致的費用及開支， 予以償還。"},{c:"2.2.3(b)",s:"表面權限意味著",o:["授權不存在，而且代理人的行為會對委託人並沒有約束力","基於過去的交易，代理人的行為會對委託人產生約束力","權限是透過委託人表明同意而產生的，並可能會對委託人產生約束力","在緊急的情況下持有必要權限為委託人採取行動，並成為必要代理人"],a:1,e:"表面權限是當一個代理人的權限是透過委託\n人對第三者(不是委託人)表明同意而產生的\n，基於過去的交易，代理人的行為會對委託\n人產生約束力"},{c:"2.2.3",s:"「明示權限」的中的明示是指",o:["與明示合約條款中的「明示」的意思相同","於迫切或危急情況發生後必要的授權","委託人對代理人已作出具體的指示","委託人對代理人的指示總是書面的"],a:2,e:"明示權限是指以口頭或書面方式故意授予的\n實際權限，最貼近這個定義的答案是C"},{c:"3.1.4(b)",s:"阿倫給予他的朋友玫瑰一個他所擁有的單位免費住兩個月，請問玫瑰有權為該單位購\n買保險?理由何在?",o:["有，合法地佔有某單位的任何人有權以所有人的代理人的身份就該單位購買保險","沒有，因為她沒有付出代價","有，她是以單位託管人的身份人對該單位具有權益的","沒有，因為她並非擁有該單位"],a:2,e:"受託保管人持有次於絕對擁有權，在得到某\n貨品的擁有人或其代理人的同意下，管有該\n貨品的人可以對所保管的貨品進行投保。"},{c:"3.1.4(c)",s:"一間育兒院要求每一位家長必須簽署一份協議書，當中訂明其孩子在育兒院內所受之\n傷害，家長不得向育兒院追究。儘管如此，育兒院營運人就其所照顧的孩子在其處所\n所受之傷害的潛在法律責任購買了一入責任保險。請問育兒院是否布權購買此份保險\n，理由何在?",o:["他不必購買此份保險，因政府註冊的育兒院不須承擔責任","保險無效；因大部份的責任保險將「受保處所之傷害」列為除外責任","保險有效；育兒院營運人需為其作為或不作為負擔其潛在的法律責任","保險無效；因沒有法律責任，在欠缺可保權益下不能購買保險"],a:2,e:"育兒院營運人可以對其僱員的疏忽等行為所\n導致的法律責任購買保險。"},{c:"3.1.6",s:"「將根據合約所需給付的金額，轉付予保單持有人以外的人。」此句子是指",o:["代位","權益轉讓","委付","保單收益轉讓"],a:3,e:"「將根據合約所需給付的金額，轉付予保單\n持有人以外的人。」此句子是指保單收益轉\n讓"},{c:"3.2.1",s:"有別於最高誠信，一般誠信的意思是",o:["不論有否問及必需披露重要事實","所披露的必須確保百分百真實","所提及的需承諾及保證完全真實","本著誠信的態度的行事，而資訊必須是實質上真實"],a:3,e:"一般誠信原則適用於大部分商業合約，合約\n各方必須本着誠實的態度行事，所提供的資\n訊必須是實質上真實的，但他們沒有責任確\n保對方取得可能影響他是否訂立合約條件的\n一切重要資訊。"},{c:"3.2.4",s:"如在保險保障期間，風險上有重大的轉變",o:["很明顯地對保險人極其重要","某些保險合約可能要求被保險人作出披露","普通法要求在續約時方須要提出","以上各項皆正確"],a:3,e:"一些非人壽保單要求，在保險期限內有風險\n上的變更，例如買了人身意外保險後轉職，\n必須予以披露。不過，在普通法中，構成風\n險增加的狀況，只須在續保時通知保險人就\n足夠。以上各項皆正確。"},{c:"3.2.6",s:"如果投保人違反了最高誠信",o:["只要牽涉詐騙的情況下，保險人可得到補救","保險人可以從起保日開始推翻有關合約","詐騙或疏忽的情況下，保險人可得到補救","該份保單會自動失效"],a:1,e:"從起保日開始推翻有關合約屬於投保人違反\n了最高誠信保險人的補救方法"},{c:"3.3.2",s:"在考慮「近因」時，如果一項特定損失涉及一項單一成因，那麼",o:["如果該成因是一項受保危險，被保險人便能就所引致的損失得到保障","如果該成因是一項不保危險，被保險人便不能就所引致的損失得到保障","如果該成因是一項除外危險，被保險人便不能就所引致的損失得到保障","上述所有各項陳述均屬正確"],a:3,e:"如果只有單一成因，只有受保危險所引起的\n損失是受保的。如果涉及一項以上的危險，\n涉及除外危險的發生一般會令保險索償或保\n險金要求失敗，上述所有各項陳述均屬正確"},{c:"3.3.3",s:"就近因而言，以下哪項或哪些陳述是正確的?",o:["要構成有效的索償，近因不能屬於不保危險","如非單一成因引起，危險必須既不是不保危險，也不是除外危險，便可得到保障","由自然地來自除外危險導致的損害是不受到保障的","以上各項皆正確"],a:2,e:"如果涉及一項以上的危險，由受保危險直接\n引發的不保危險所引致的損失或事件可獲賠\n償，而除外危的發生，一般會令保險索償或\n保險金要求失敗。只有答案C描述正確"},{c:"3.4.4",s:"最為普遍，甚至在某些情況下是唯一的彌償方法?",o:["以現金支付","更換受保物品","維修受破壞的受保物品","將受保資產恢復原狀"],a:0,e:"以現金支付少對保險人而言，這是最方便的\n方法"},{c:"3.4.7(b)",s:"假設保單的免賠額是X，下列哪項有關的陳述是正確的？",o:["被保險人的首X損失將不獲保障","索償時會獲得最高X的賠償","索償超越X時，將獲全數賠償","被保險人需付額外X保費"],a:0,e:"免賠額規定損失超過免賠額金額，被保險人\n就可以得到扣除免賠額後的賠償金額"},{c:"3.4.8",s:"一部電視機受火災損害時已經使用五年之久，損失維修費用$5,000，有關家居保險人\n全數支付，由此可推斷該保險由以下哪項訂立？",o:["「以新代舊」方式","商業重置保險","恢復原狀方式","約定價值方式"],a:0,e:"「以新代舊」的保險保障不會就損耗、折舊\n等因素扣減賠償金額，這詞一般較多用於家\n居風險單和船體保險單。"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約定價值$1,000,000」\n，意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方式提供\n保險保障的，約定價值一律被視為損失時的\n實質價值"},{c:"3.5",s:"代位和分擔有近似的目標，它們都是",o:["它們都有兩份保單","每份保單都有共同的保障","保險人向引致疏忽的人作出追討賠償","賠償額不能大於彌償"],a:3,e:"分擔及代位是彌償原則的引伸，由於人壽保\n單屬利益保單，不適用於彌償原則，正確答\n是D。"},{c:"3.5.1",s:"如果發現保單持有人持有兩份保單來保障自已的財產(例如:盜竊)，合法的情況應該是",o:["他有權接受兩份賠償","因為這可能是欺詐，他將得不到任何賠償","僅僅是他投保的第一個保險人必須賠償損失","兩個保險人將得到最終分擔提供彌償的責任"],a:3,e:"當有兩份或以上被保險人自行購買的保單，\n遇上重複保險情況，並保障了相權益的保單\n，便會應用分擔原則，任何一位保險人將得\n到最終分擔提供彌償的責任，答案Ｄ正確"},{c:"3.6.4",s:"就保險而言，普通法規定當提提供彌償後，可取得代位權。非水險保單條件",o:["從不可改變普通法的規定","在法律上不得更改普通法的規定","只當就索償結清達成後方給予保險人代位權","通常即時給予保險人代位權，以便馬上展開追償行動"],a:3,e:"在普通法中，只有在給予彌償以後，才可取\n得代位權，非水險保單通常規定，即使還沒\n作出彌償，保險人也能行使代位權。"},{c:"3.6.4",s:"建築商就一意外向一架私家車擁有人支付$13,000,000。因為一項每宗責任事故限額的\n應用，該名私家車司機只有向其責任保險人取得保險金$12,000,000。如果保險人後來\n向第三者追回$7,000,000，請問誰有權取得這筆錢?又怎樣分這筆金額?",o:["保險人佔 $7,000,000，被保險人沒有份兒","保險人沒有份兒，被保險人 $7,000,000","保險人佔 $6,000,000，被保險人 $1,000,000","保險人佔十三分之十二，被保險人佔十三分之一"],a:2,e:"因為保單限額的應用，被保險人尚欠100萬\n的賠償，如果保險人後來向第三者追回700\n萬，被保險人可分享100萬代位益，保險人\n則享餘下600萬"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["承讓人承諾支付未來的保費","保單轉讓人只會把在合約中的權益轉移到承讓人的身上","保單轉讓人只會把在合約中的的責任轉移到承讓人的身上","保單轉讓人在合約中的權益和責任均完全轉移到承讓人的身上"],a:1,e:"保單「轉讓」通常是指權利的轉移。轉讓是\n不會讓轉讓人在保險合約的責任轉移到承讓\n人的身上的"},{c:"3.2.1",s:"以下哪項有關「一般誠信」一詞是正確的描述",o:["是常識範圍内的事實","不論對方是否問及有關的資料，各方必須向他方披露所有重要的資料","各方向他方披露的資料可以是真實或虛假，所以不可信","訂立合約時，本著誠實態度行事，所提供的資訊是實質上真實的，而對於另一方沒\n有詢問的事情保持緘默"],a:3,e:"一般誠信意思是合約各方必須本着誠實的態\n度行事，所提供的資訊必須是實質上真實的\n，但他們沒有責任確保對方取得可能影響他\n是否訂立合約的一切重要資訊。答案D正確"},{c:"3.2.4",s:"投保人於投保時遵守最高誠信以披露重要事實的期限",o:["只有保單持有人特別提出要求時予以延伸","法律並不容許予以延伸","一直至合約具約束力結束為止，並無例外","有時通過相互協議予以延伸"],a:3,e:"在普通法中，於保險合約訂立後，投保人才\n得知的重要事實，不必予以披露。所以，保\n險人有時通過相互協議予以延伸最高誠信以\n披露重要事實的期限"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?\ni. 承讓人承諾支付未來一切保費\nii. 轉讓人不會把保險合約中的責任轉移到承讓人的身上\niii. 承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費\niv. 如將保單的責任轉移到第三者，須得到保險人的同意",o:["i , ii, iii","ii,iv","ii,iii,iv","i,ii,iii,iv"],a:1,e:"轉讓是不會讓轉讓人在保險合約的責任轉移\n到承讓人的身上的 。\n這類轉移須得到保險人的同意\n。只有選項ii,iv 正確"},{c:"3.4.7(b)",s:"保單的免賠額是$1000元，哪麼意味著",o:["如果損失超過$1000元，將不獲任何賠償","如果損失$1000元以下，將不獲任何賠償","保額減去$1000元","賠償金額以$1000元為上限"],a:1,e:"免賠額是規定了低於某指定金額的任何損失\n，被保險人都不獲賠償。\n即是說，該金額將從每宗索償中扣除。"},{c:"3.4.2",s:"彌償原則合適用以上甚麼保險項目類型?",o:["人壽保險","醫療保險","人身意外保險","以上各項皆是"],a:1,e:"醫療保險於彌償原則合適用"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約性質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險人的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓收取保\n險金的權利無需取得保險人的同意"},{c:"3.4.2",s:"人壽與保險不受彌償的原則約束，原因是",o:["無法精確計算人命價值","無限額的可保權益","無論支付多少錢不能精確地作出彌償","以上各項皆成立"],a:3,e:"人壽保險及人身意外保險所針對的都是人的\n傷亡，\n根本沒有任何方法可以把人命損失精確地用\n金錢來量度出來，所以這些類型的業務一般\n不適用彌償原則 。"},{c:"3.3.2",s:"除外危險_____________",o:["保單不承保的危險","與不保危險有相同的對待","除超額保障以外，將承保的危險","例如各種天災，地震等"],a:0,e:"除外危險是被除外責任條款豁免承保的"},{c:"3.1.4",s:"以下哪項可保權益的陳述正確?",o:["適用於計算保費融資利率","又可稱為保險標的","又可稱為保險標的","沒有保權益，有關保險協議便屬無效"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效"},{c:"3.1.2",s:"下列哪項有關缺乏可保權益的保險的陳述是不正確的?",o:["該項保險屬於可使無效","涉及保費是否退還等的法律問題","所有損失不獲賠償","該份保險合約從索償產生時被視為無效"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效\n，而退還保費的相關規則，則因所屬險種而\n異，相關規則例如《保險業條例》和《海上\n保險條例》的相關條文，答案D不正確"},{c:"3.4.5",s:"以下哪項對Salvage一詞的定義不正確?",o:["保險標的在受損後會留下剩餘部分稱為 「損餘 」","在提供彌償時，必須把該價值考慮在內","在海商法中，“Salvage”一詞帶有截然不同的 意思","只有在懲罰投保額不足時適用"],a:3,e:"懲罰投保額不足的限制彌償原則是比例分攤\n(Average)，答案D不正確"},{c:"3.2.6",s:"假如被保險人違反最高誠信，保險人可作出以下哪項的補救行動",o:["保險人可選擇推翻保單","可作出特定賠償，並於剩餘的保險期內把保單視為有效","可提出侵權法訴訟要求損害賠償","A&C"],a:3,e:"作出特定賠償，並於剩餘的保險期內把保單\n視為有效，並不是被保險人違反最高誠信，\n保險人可作出的補救行動，只有選項A&C正\n確"},{c:"3.3.2",s:"除外危險_____________",o:["也稱排除危險","與不保危險相同對待","除非保單分限額，否則將獲承保","自然災害等例如颱風"],a:3,e:"自然災害等屬基本風險，這些災害影響到整\n個社會或人類，對商業保險人來說基本風險\n，一般是不可保的除外危險"},{c:"4.2",s:"以下哪三方面有可能屬於客戶服務部門的職能範圍？\ni) 文件的提供\nii) 公共關係\niii) 索償的談判\niv) 一般的聯絡",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"索償的談判不屬於客戶服務部門的職能範圍\n，選項iii不正確"},{c:"4.4",s:"下列哪項或哪些較可能屬於保險銷售部的工作範圍 ?",o:["産品聯絡","監察進度或趨勢","進行加強銷售計劃","以上各項皆是"],a:3,e:"以上各項皆是保險銷售部的工作範圍"},{c:"4.5",s:"人壽保險核保部門眼中的「目標風險」，較可能屬於以下哪類風險？",o:["極高保額的風險","保險人尤其願意承保的風險","保險人尤不願意承保的風險","有關保險代理人可得到較高佣金率的風險"],a:1,e:"目標風險在人壽保險中可以解釋為極為合意\n的業務類型"},{c:"4.1",s:"產品開發是保險公司的重要功能，原因是",o:["產品開發有助於確保公司的財務穩定","香港有着競爭激烈的營商環境","可以看出，由於在過去幾年中保險監管框架的迅速變化，保險產品很快就過時了","必須根據不斷變化的法規要求對強制性保險單進行頻繁的修訂"],a:1,e:"由於香港有著開放又競爭激烈的營商環境，\n保險人在設計準備銷售的產品時，必須做到\n高效而有活力"},{c:"4.12",s:"保險人必須先取得保險業監管局的認可，方可委任＿＿＿＿？",o:["管控要員","公司的財務經理或財務行政人員","精算部門的職員","理賠部門的職員"],a:0,e:"保險人必須先取得保險業監管局的認可，方\n可委任管控要員"},{c:"4.9",s:"以下哪項就精算支援的描述是正確的?\ni. 《保險業條例》要求所有獲授權保險人必須委任一名合資格並被保監局接納的精算\n師\nii. 精算師的主要職責是對所有資產及負債進行評估\niii. 只有人壽保險需要精算支援\niv. 精算支援負責估算所需的未決申索儲備金",o:["ii,iv","i,ii,iv","ii,iii,iv","i,iv"],a:0,e:"《保險業條例》要求所有從事長期業務的保\n險人，委任一名合資格並被保險業監管局接\n納的精算師。人壽保險及一般保險需要精算\n支援。所以選項ii 及iv才正確。"},{c:"4.3&4.4",s:"哪句說話最可以形容市場行銷及保險的銷售部門的關係?",o:["他們可以完全獨立運作","他們的工作出現高度重疊","他們向不同的管理層匯報","他們面對著不同的客戶群"],a:1,e:"保險銷售與市場行銷之間有着十分密切的關\n聯 。在活動範圍上， 可能出現重大重疊"},{c:"4.7",s:"所有的保險索償須驗證甚麼?",o:["投保人當前的地址","保費最近支付日期","保險人對保單承擔的責任","代理人佣金結構"],a:2,e:"處理任何保險賠案時，保險人應該承擔的賠\n償責任及給付數額都是必須解決的共同問題\n。"},{c:"5.1.1",s:"因意外喪失能力或健康欠佳提供利益的長期保單是？",o:["意外","永久健康","意外及疾病","永久喪失能力"],a:1,e:"永久健康是因意外喪失能力或健康欠佳提供\n利益的長期保單，屬一般保險業務"},{c:"5.1.3",s:"以下哪項或哪些是保險業中的學術分類?",o:["工程保險","經濟權益保險","一籃子保險","以上各項都是"],a:1,e:"保險的學術類別可分為人身，財產，責任及\n經濟權益保險"},{c:"5.5.3",s:"香港汽車保險局的工作包括",o:["維護汽車車主","售賣車險","維護公平保費","向無辜死傷的交通意外受害人提供補償"],a:3,e:"香港汽車保險局的工作包括向無辜死傷的交\n通意外受害人提供補償"},{c:"5.1.1",s:"保險業務種類可分為法定的、實務的及學術的，然而法定的是為著什麼而設立",o:["為公司內部組織而設","為專業進修而設","為保險業監管機構授權及監察而設","以上各項皆是"],a:2,e:"法定保險業務分類，是為保險業監管機構授\n權及監察而設，《保險業條例》把保險分為\n長期業務及一般業務兩類"},{c:"5.2",s:"以下哪項就獲授權的保險人的描述是不正確的?",o:["獲授權保險人可以是從事「 純 」 長期業務","獲授權保險人可以是從事「 純 」 一般業務","獲授權保險人不可以是專業再保險人","獲授權保險人可以是綜合業務保險人"],a:2,e:"獲授權保險人可以是專業再保險人，所以答\n案C不正確"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項有關最低實繳股本的要求是正確的 ?\ni)專屬自保保險公司為港幣200萬元\nii)只從事相連長期保險業務的保險人為港幣1,000萬元\niii)同時從事一般業務及長期業務為港幣2,000萬元\niv)從事一般業務的保險人﹝包括法定保險業務﹞為港幣2,000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"四個最低實繳股本的要求描述都正確，詳細\n請參閱研習資料手冊 6.1.1b"},{c:"6.1.1f",s:"《保險業條例》要求參與一般業務的保險人定期繳交甚麼報表?\ni) 經審計的一般業務報表\nii) 經審計的資產負債表\niii) 經審計的精算報告表\niv) 經審計的長期業務報表",o:["i，ii","i，iii","ii，iii，iv","i，ii，iii"],a:0,e:"《保險業條例》要求參與一般業務的保險人\n定期繳交經審計的一般業務報表及經審計的\n資產負債表"},{c:"6.1.1g",s:"根據《保險業條例》及相關法例，以下哪項屬於保險業監管局的干預範圍：\ni) 限制保費收入\nii) 將保險人清盤\niii) 特定的精算調查\niv) 行使對保險人的管理權",o:["只有 i, ii","只有 ii, iii","只有 i, ii, iii","i, ii, iii, iv"],a:3,e:"以上各項都屬保險業監管局的干預權力，詳\n細請參閱研習資料手冊 6.1.1g"},{c:"6.1.2c",s:"根據《承保商專業守則》，假如符合兩項條件，即使違反保證亦不會在索償時被拒絕\n，其中是包括以下哪項？",o:["損失不超過2,000元","被保險人承認違反保證","損失與違反保證兩者並無因果關係","以上各項皆不是"],a:2,e:"根據《承保商專業守則》的索償建議，沒有\n涉及欺詐成分違反了保證，而且該違反沒有\n引致有關損失，保險人不應拒絕賠償\n或支付保險金"},{c:"6.1.3",s:"保險投訴局成員包括",o:["本港所有獲授權的保險人","本港獲授權一般業務的保險人而已","本港獲授權長期業務的保險人而已","本港所有承保個人壽險的獲授權保險人"],a:3,e:"所有在香港從事個人保險業務的獲授權保險\n人均必須繼續申請成為保險投訴局的會員"},{c:"6.1.3a",s:"保險索償投訴委員會成員是由以下哪個團體所委派",o:["保險投訴局","保險業聯會","保險監督","壽險業協會"],a:0,e:"保險索償投訴委員會成員是由保險投訴局所\n委派"},{c:"6.1.1f",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（修訂）條例》所授予\n，對獲授權保險人施予的紀律處分？\ni. 將保險人清盤\nii. 限制投資\niii. 非公開譴責\niv. 罰款",o:["i, ii","i, ii, iii","iii，iv","ii，iii，iv"],a:2,e:"非公開譴責及罰款屬於《2015年保險公司（\n修訂）條例》所授予保險業監管局新增的監\n管權力，答案C正確"},{c:"6.2.1",s:"根據法定規定， 以下哪些需要至少一名負責人?\n(i) 持牌保險機構\n(ii) 持牌保險代理\n(iii) 持牌保險代理機構\n(iv) 持牌保險經紀公司",o:["(i)及 (ii) 而已","(i)及 (iii) 而已","(ii)及 (iv) 而已","(iii)及 (iv) 而已"],a:3,e:"條例就受規管人士中的“負責人”，規定每\n個持牌保險代理機構和持牌保險經紀公司最\n少有一個負責人，而所有負責人必須是持牌\n業務代表（代理人）或持牌業務代表（經紀\n）"},{c:"6.1.1f",s:"《保險業條例》列明經營一般業務的保險人必須就其從香港保險業務所產生的負債在\n香港維持資產，用來釐定這一數據的方法之一，是計算有關數額與以下之總和",o:["毛負債額（不扣除再保險部分）的80%","净負債額（扣除不保部分）的80%","净負債額（扣除再保險部分及可爭議負債）的80%","净負債額（扣除再保險部分）的80%"],a:3,e:"經營一般業務的保險人，必須就其從香港保\n險業務所產生的負債在香港維持資產，所需\n數額以訂明的兩種匯算方法之一計算，其一\n所要求的數額不能少於兩項的總和:(i)淨負\n債額（即已經扣除再保險所保的那部分）的\n百分之八十 ；及(ii) 有關數額。"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有保證價值此事實\nii.投保人訴在核保結果為次標準風險\niii保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒\n有驗證其真實年齡\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單是屬於「抗通脹保\n單」",o:["i,ii,iii","i,iii,iv","iii,iv","i,ii,iii,iv"],a:1,e:"保險投訴局受理的投訴個案與保險人的服務\n水平或核保決定無關"},{c:"6.2.1",s:"在新的牌照制度下，已獲保監局發出作為任何持牌保險代理機構進行一個或多於一個\n業務系列的受規管活動的牌照的個人，屬於以下哪一個牌照類別?",o:["持牌業務代表（代理人）","持牌業務代表（經紀）","持牌保險代理機構","以上皆不是"],a:0,e:"已獲保監局發出作為任何持牌保險代理機構\n進行一個或多於一個業務系列的受規管活動\n的牌照的個人，屬持牌業務代表（代理人）"},{c:"6.2.4(a)",s:"如申請人屬於獨資經營人、合夥和公司，其所有控權人、合夥人和董事必須屬於與進\n行該等業務系列的受規管活動有聯繫的適當人選。控權人被定義為直接或間接地擁有\n或控制（包括透過信託或持票人股份持有）該公司已發行股本的不少於X %， 哪麼X\n%是多少?",o:["15%","20%","25%","30%"],a:0,e:"申請人屬於獨資經營人、合夥和公司，其所\n有控權人、合夥人和董事必須屬於與進行該\n等業務系列的受規管活動有聯繫的適當人選\n。控權人被定義為直接或間接地擁有或控制\n（包括透過信託或持票人股份持有）該公司\n已發行股本的不少於15%"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求描述是正確的?",o:["代表保險人的第三者，應該具備相關經驗","代表保險人的第三者，應該相關經驗及具備專業資格","不得委派律師或理賠師以外第三者","代表保險人的第三者，在任何情況下都應當合理地行事，並且應該具備專業資格"],a:3,e:"根據《承保商專業守則》代表保險人的第三\n者（理賠師等），在任何情況下都應當合理\n地行事，並且應該具備專業資格。"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有保證價值此事實","保單持有人投訴保險人花上一個月才批出保單，導致他未能及時交給所屬銀行","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒\n有驗 證其真實年齡","年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，導致損失了有關的\n保單利息"],a:1,e:"保險投訴局受理的投訴個案與保險人的服務\n水平或核保決定無關"},{c:"6.1.3",s:"以下哪項是保險投訴局的描述是正確的?",o:["2018年成立取代保險索償投訴局","處理保單屬非金錢性質的投訴個案","只能處理保單屬非索償相關的投訴個案","所有在香港從事個人保險業務的獲授權保險人可自願申請成為保險投訴局的會員"],a:0,e:"所有在香港從事個人保險業務的獲授權保險\n人均必須成為保險投訴局的會員，並會受理\n索償相關及非索償相關的金錢性質保險糾紛\n投訴個案，保險投訴局於2018年1月16日成\n立，旨在取代保險索償投訴局，正確答案是\nA"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["列明保險中介人八大操守原則","由香港保險監管局執行","列明保險代理管理的優良保險做法","以上各項皆是"],a:2,e:"承保商專業守則由香港保險業聯會執行，列\n明保險代理管理的優良保險做法"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項是保險業監管局成立的政策目標？\ni. 就影響保險業的事宜，進行研究\nii. 提升保險業界在環球保險業市場的競爭力\niii. 協助特區行政長官維持香港金融穩定\niv. 提高保單持有人對保險產品和保險業的了解",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:1,e:"保險業監管局其中一項成立的政策目標是協\n助財政司司長維持香港金融穩定。"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不是保險業監管局成立的政策目標\n？\ni. 為保單持有人提供經濟援助\nii. 確保保險業的規管架構與時並進，促使保險業的高速發展\niii. 確保保險業的償付準備金與國際慣例看齊\niv. 與國際慣常做法看齊，監管機構在財政上和運作上獨立於政府",o:["i, iv","i, ii, iii","i, ii","ii, iii, iv"],a:1,e:"由此描述iv是屬於保險業監管局成立的政策\n目標，選項i,ii,iii則不是保險業監管局成\n立的政策目標，詳細參閱研習資料手冊6.1.\n1"},{c:"6.2.2",s:"《保險業條例》第68條對_______________就其委任的保險代理人的作為須負上\n轉承責任。",o:["保單持有人","受保人","獲授權保險人","獲授權被保險人"],a:2,e:"《保險業條例》第68條對獲授權保險人就其\n委任的保險代理人的作為須負上轉承責任"},{c:"6.1.1f(d)",s:"根據《保險業條例》的要求，所有保險人每年向保監局呈交",o:["資產負債表","一般業務報表","財務報表","以上各項皆是"],a:2,e:"根據《保險業條例》的要求，所有保險人每\n年須向保監局呈交其財務報表"},{c:"6.2.4",s:"以下哪頂就《持牌保險代理人操守守則》的陳述正確?",o:["於2019年9月由保險業聯會所頒布","列明八項基本操守原則的一般原則","作為附屬法例，頒布於通常情況下期望持牌保險代理人在進行受規管活動時應遵守\n的操守原則及相關的標準及常規","以上各項皆是"],a:1,e:"《持牌保險代理人操守守則》列明八項保監\n局認為屬持牌保險經紀在進行受規管活動時\n應採納並遵守的基本操守原則的一般原則，\n守則”不具法律效力，也不是附屬法例，只\n有答案B正確。"},{c:"7.6",s:"保險中介人挪用了代保險人收取的保費後，會被控以下哪項罪名？",o:["挪用金錢罪","盜竊罪","不誠實罪","故意偷竊罪"],a:1,e:"保險中介人挪用了代保險人收取的保費後，\n會被控盜竊罪罪名"},{c:"7.3.2",s:"以下哪項有關保險人對投保人給予性別差別對待是法律容許的，並不觸犯歧視條例？",o:["有關待遇是藉參照可合理依據的來源所得的精算數據","有關待遇是藉參照可合理依據的來源所得的精算數據或其他數據而給予的","就有關因素而言屬於合理","一切參照可合理依據的來源所得的精算數據"],a:1,e:"保險人對投保人給予性別差別對待是藉參照\n可合理依據的來源所得的精算數據或其他數\n據而給予的"},{c:"7.1.2",s:"以下哪一項就保險代理人的描述是不正確?",o:["因執行業務的疏忽行為所須承擔侵權法律責任的機會並非較高","因疏忽而對保單持有人提供不當的保險意見，須承擔侵權法律責任的機會並非較高","因疏忽而對保單持有人提供錯誤的保險意見，須承擔侵權法律責任的機會並非較高","保險代理人完全不用承擔任何侵權法律責任風險之中"],a:3,e:"一個保險代理人如果在為顧客承擔進行某項\n活動時，他因不當履行責任而被判須負法律\n責任的機會，相對經紀來說是比較小，但並\n不代表保險代理人完全不用承擔任何侵權法\n律責任風險之中"},{c:"7.2.1",s:"以下哪項對《個人資料(私隱)條例》範圍的陳述是正確的?：\ni. 自動化操作資料\nii.只適用於人手操作資料\niii. 只適用香港永久居民\niv. 它既涉及公營機構及私營機構",o:["i,ii,iii","i,iii,iv","i,iv","i,ii,iii,iv"],a:2,e:"個人資料是指自動化操作資料及涉及公營機\n構及私營機構"},{c:"7.5.1",s:"以下哪一項是《防止賄賂條例》下僱員應該遵守或避免的行為?",o:["僱員從事有關業務或事務時，如未經僱主同意，不得創業","僱員從事有關業務或事務時，如未經僱主同意，不得在其關係終止5年內創業","僱員從事有關業務或事務時，如未經僱主同意，不得索取或接受任何利益","僱員從事有關業務或事務時，如未經僱主同意，不得委任分代理人"],a:2,e:"根據《條例》第9(1)條的規定，代理人在處\n理其主事人的業務或事務時，如未經主事人\n的允許，不得索取或接受任何利益"},{c:"7.5.2",s:"以下哪一項是廉政公署24小時舉報熱線？",o:["999","25 266 366","1823","24 266 366"],a:1,e:"以下哪一項是廉政公署24小時舉報熱線是25\n266 366"},{c:"7.2.1",s:"根據《個人資料(私隱)條例》，資料當事人有權查閱及更正其個人資料，屬於哪項資\n料使用原則?",o:["第1原則:收集個人資料的目的及方式","第2原則:個人資料的準確性及保留期限","第5原則:資訊須在一般情況下可提供","第6原則:查閱個人資料"],a:3,e:"根據《個人資料(私隱)條例》，資料當事人\n有權查閱及更正其個人資料，屬於第6原則:\n查閱個人資料"},{c:"7.4.7",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）不適用於",o:["再保險公司","銀行業條例下成立的金融機構","持牌保險經紀公司","持牌個人保險代理"],a:1,e:"《打擊洗錢及恐怖分子資金籌集指引》（指\n引3）不適用於銀行業條例下成立的金融機\n構"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項屬於利益?\ni. 客戶送贈的禮物\nii. 團隊隊員給予的佣金\niii. 百貨公司折扣禮劵\niv. 保險公司職位",o:["i","i,ii","i,ii,iv","以上各項皆是"],a:3,e:"「利益」的定義廣泛，包括金錢、饋贈、貸\n款、報酬、佣金、職位、任何職位、受僱工\n作或合約、服務、優待及任何有價證券或任\n何種類的其他財產或財產權益"},{c:"7.4.7b",s:"基於風險為本的關鍵原則是",o:["正確釐定保費","所有交易應用相同措施","根據風險級別分配資源","遵循標準慣例"],a:2,e:"基於風險為本的關鍵原則是根據風險級別分\n配資源"},{c:"7.2.1",s:"資料使用者透過制定服務合約，對資料處理者施加的責任是:\ni. 資料使用者有權審核及視察資料處理者如何處理和儲存個人資料\nii. 不再需要就受託目的處理有關個人資料時， 必須適時交還、銷毀或刪除有關資料\niii. 須採取的保安措施，以保障受託的個人資料，並要求資料處理者遵從保障資料原\n則\niv. 資料處理者必須居於香港",o:["i.ii","ii,iii,iv","iii,iv","i.ii.iii"],a:3,e:"資料處理者必須居於香港不是對資料處理者\n施加的責任"},{c:"7.6.2(b)",s:"就保險詐騙性索償，保險中介人有以下哪項責任?\ni. 拒絕索償\nii. 執行相關法律\niii. 舉報可疑事件或提供證據\niv. 協助保險人揭露詐騙行為",o:["i,iii,iv","i,ii,iv","iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是就保險詐騙性索償，保險中介\n人須要負上責任"}],"paper1-2025-08":[{c:"1.1.2(b)",s:"最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:2,e:"盜竊會有金錢上損失，純粹風險只具\n有財務損失的可能性"},{c:"1.1.3",s:"不提供食物及飲料以避免食物中毒的風險，屬哪種風險管理的措施?",o:["風險避免","損失防範","損失降低","風險轉移"],a:0,e:"風險避免是不讓自己暴露在某項風險\n之下，從而免除遭受相關損失的機會"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni. 保險對受保損失的被保險人提供財務補償\nii. 保險為本港提供就業機會\niii. 一般保險的慣例下倡導防範損失的措施\niv. 一般保險的慣例下倡導控制損失的措施",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:3,e:"保險對受保損失的被保險人提供財務\n補償屬保險的基本功能, 選項i不正確"},{c:"1.1.1",s:"當風險真正出現時，以下哪項風險後果相當可能屬於不可保?",o:["財務損失的風險","因別人不誠實而引致損失的風險","因意外引致喪失肢體的風險","悲傷及傷心的風險"],a:3,e:"悲傷及傷心的風險難以用金錢衡量損\n失，對於保險人而言是不可保的風險"},{c:"1.1.2b",s:"從可保程度的角度來看，哪項是用來形容特定風險的?",o:["永不可保的","必然可保的","可保程度較可能低於基本風險","可保程度較可能高於基本風險"],a:3,e:"商業保險人所保的風險主要是特定風\n險，基本風險一般是不可保的，因為\n要求他們以商業方式處理此等風險看\n來在財務上是不可行的。"},{c:"1.1.3",s:"以下哪項有關風險管理的描述是正確的？",o:["保險是風險管理的其中一環","風險管理僅是保險的其中一環","保險與風險管理是完全相同之學科","風險管理是工程技術的一門學科"],a:0,e:"保險只是多種風險管理措施當中的其\n中一種方法"},{c:"1.1.3",s:"考慮改善受保風險之潛在損失的可能性時，保險人所採用的字眼為",o:["核保","風險評估","風險管理","保險風險分析"],a:2,e:"當保險人談及「風險管理」時，所指\n的可能是某些可以用來降低或改善所\n承保或獲邀承保「風險」的潛在損失\n的方法或手段。"},{c:"1.1.3",s:"作為風險管理在獨立的知識及研究範疇上，一般的理解為",o:["投資或投機風險所帶來的損失","保險人對受保風險損失上的改善","以識別、量化及處理作為進行的步驟","環繞著對保險合約的訂立及處理"],a:2,e:"風險管理可以解釋為管理學的一個分\n支，它要進行的步驟包括識別、量化\n及處理"},{c:"1.2",s:"一名被保險人死亡後，保險人向其受養人支付死亡保險金，這做法顯示",o:["人壽保險的唯一好處","人壽保險的基本功能","壽險的唯一好處及功能","並非壽險的好處及功能"],a:1,e:"保險的基本功能及好處是，保險可以\n為被保險人提供財務補償。人壽保險\n會在悲劇來臨或給人帶來幫助。"},{c:"1.2",s:"以下哪項或哪幾項是保險的基本的好處？",o:["為保單持有人提供財務補償","增加就業機會","以人壽保險及年金作為儲蓄","金融服務的發展"],a:0,e:"保險的基本功能及好處是，在各種不\n同的投保事件中，當災害發生時，保\n險可以為被保險人提供財務補償。"},{c:"2.1.3",s:"在保險上，保險人的代價是：\ni. 被保險人向保險人支付保費的承諾\nii. 保險人依照保單條款的規定給付賠償\niii. 保險人依照保單條款的規定收取款項\nvi. 保險人依照保單條款的規定給予補償的承諾",o:["ii,iv","只有ii","只有i","只有iii"],a:0,e:"在保險上，代價就是：保險人依照保\n單條款的規定付款或給予補償的承諾\n。"},{c:"2.1.3(d)",s:"以下哪項不是簡單合約具備的元素？",o:["合法性","代價","訂約的行為能力","合理便宜的價格"],a:3,e:"合法性，代價，訂約的行為能力都屬\n六項「合約元素」的準則"},{c:"2.2.5",s:"代理人代表委託人行事時招致的費用，委託人應",o:["只支付與交通有關的費用","只支付委託人事前同意的費用","向代理人報銷行事時適當及合理地招致的費用及開支","只支付在符合代理協定條件下的費用"],a:2,e:"在符合代理協定的任何明示條件下，\n委託人必須對代理人代表其行事時適\n當及合理地招致的費用及開支，\n予以償還。"},{c:"2.2.3(b)",s:"表面權限意味著",o:["授權不存在，而且代理人的行為會對委託人並沒有約束力","基於過去的交易，代理人的行為會對委託人產生約束力","權限是透過委託人表明同意而產生的，並可能會對委託人產生約束力","在緊急的情況下持有必要權限為委託人採取行動，並成為必要代理人"],a:1,e:"表面權限是當一個代理人的權限是透\n過委託人對第三者(不是委託人)表明\n同意而產生的，基於過去的交易，代\n理人的行為會對委託人產生約束力"},{c:"2.1.2",s:"以下哪項陳述是正確的?",o:["保險合約屬於契據","大部分的保險合約屬簡單合約，因它可以用口頭或書面形式訂立","保險合約有效性必須以書面合約為證","保險合約屬於簡單合約，因內容淺白令一般人易於明白"],a:1,e:"簡單合約是意味着合約的訂立是簡單\n、容易的。因它可以用口頭或書面形\n式訂立"},{c:"2.2.2",s:"代理關係可以透過以下哪些途徑產生?\ni. 明示協議\nii. 隱含協議\niii. 追認\niv. 代理人出錯",o:["i,ii","i,ii,iii","iii,iv","以上皆是"],a:1,e:"代理關係可以透過明示，隱含或追認\n方式產生"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構成要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就\n沒有合約。"},{c:"2.1.2(b)",s:"以下哪種合約是保險人會以契據方式成立的？",o:["忠誠保證保險","強制性(第三者)汽車保險","擔保","以上所有各項"],a:2,e:"某些交易例如土地的轉讓，\n必須以契據達成。擔保必然是以契據\n形式發出的"},{c:"2.1.3",s:"以下哪項可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含義完全相同","受屈的一方可於合理時間內把合約視為無效的決定","只有被保險人才能把保單視作可使無效(即可予以取消)"],a:2,e:"可使無效的合約是項明顯有\n法律效力的合約，其法律效力一直維\n持下去，除非及直至有受屈的一方把\n合約視為自訂立時起即屬無效，但須\n在一段合理時間內進行"},{c:"2.1.3(d)",s:"在簡單合約中，「訂約的行為能力」是指訂立合約的能力。在保險合約中，這項要求適\n用於",o:["投保人和保險人","未達成年歲數的投保人","投保人，但不一定適用於保險人","保險人，但不一定適用於投保人"],a:0,e:"「訂約的行為能力」是指訂立合約的\n能力。在保險合約中，這項要求適用\n於投保人和保險人"},{c:"2.2.3",s:"代理人的權限包括：\ni) 實際權限\nii) 表面權限\niii) 非表面權限\niv) 必要權限",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"非表面權限不屬代理人的權限種類"},{c:"2.2.3(b)",s:"就表面權限而言，權限問題與代理關係是有所相關及分別，以下哪些或哪項是正確的?",o:["局限在委託人與第三者之間的關係","代理人的權限是委託人對第三者表明同意產生的","在無授權情況之下，而幫助委託人訂立合約時，會令委託人受代理人行為約束","以上各項皆是"],a:3,e:"A,B及C的描述正是表面櫂限的正確描\n述"},{c:"2.2.3(c)",s:"如果需要或出於人道或其他合理的原因，某人代理另一人行事的開支，即使沒有獲授權\n，此人也可以被認為是他的代理人，這種代理關係的成立是基於以下那項？",o:["實際權限","表面權限","必要權限","不容反悔"],a:2,e:"必要權限是:當一名現有委託人的財產\n或權益受着迫切的危害，而有一名現\n有代理人在這個危急的情況下，必要\n地採取行動，即使沒有取得明示權限\n，透過該等行為成為必要代理人。"},{c:"2.2.6",s:"下列哪項或哪些屬於保險代理協議终止的途徑?",o:["撤銷","衝突或沒有達成協議","不忠誠","以上所有各項"],a:0,e:"撤銷屬於代理協議终止的其中一項途\n徑"},{c:"2.2.6",s:"以下哪一項是代理人精神錯亂的處理方法？",o:["可以終止合約","由代理人的最近親代替成為代理","維持代理合約直至代理人康復","確保繼續支付佣金給代理人"],a:0,e:"精神錯亂屬於代理協議终止的其中一\n項途徑"},{c:"3.3.2",s:"除外危險_____________",o:["保單不承保的危險","與不保危險有相同的對待","除超額保障以外，將承保的危險","例如各種天災，地震等"],a:0,e:"除外危險是被除外責任條款豁免承保\n的"},{c:"3.4.3",s:"以下哪項與彌償保險原則沒有關係？",o:["可保權益","分擔","代位","退還財產"],a:3,e:"退還財產不屬保險原則"},{c:"3.2.1",s:"正面回答所有被問及的問題並保證作出的回答是真實的，這屬於",o:["一般誠信","最高誠信","內在誠信","合約誠信"],a:0,e:"一般誠信是本着誠實的態度行事，所\n提供的資訊必須是實質上真實的"},{c:"3.4.7(b)",s:"以下哪項阻止了保單為被保險人作出彌償?\ni. 比例分攤\nii. 多於二人有可保權益\niii. 免賠額\niv. 起賠額",o:["i,ii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"比例分攤，免賠額，起賠額屬限制彌\n償的保單條文，意味着規定的賠償金\n額 比彌償金額為低"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["承讓人承諾支付未來的保費","保單轉讓人只會把在合約中的權益轉移到承讓人的身上","保單轉讓人只會把在合約中的的責任轉移到承讓人的身上","保單轉讓人在合約中的權益和責任均完全轉移到承讓人的身上"],a:1,e:"保單「轉讓」通常是指權利的轉移。\n轉讓是不會讓轉讓人在保險合約的責\n任轉移到承讓人的身上的"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["轉讓人不會把保險合約中的責任轉移到承讓人的身上","承讓人將取得收款人的權利，而非訴訟權","承讓人承讓人承諾支付未來的保費","承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費"],a:0,e:"保單「轉讓」通常是指權利的轉移。\n轉讓是不會讓轉讓人在保險合約的責\n任轉移到承讓人的身上的"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約性質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險人的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓\n收取保險金的權利無需取得保險人的\n同意"},{c:"3.2.4",s:"投保人於投保時遵守最高誠信以披露重要事實的期限",o:["只有保單持有人特別提出要求時予以延伸","法律並不容許予以延伸","一直至合約具約束力結束為止，並無例外","有時通過相互協議予以延伸"],a:3,e:"在普通法中，於保險合約訂立後，投\n保人才得知的重要事實，不必予以披\n露。所以，保險人有時通過相互協議\n予以延伸最高誠信以披露重要事實的\n期限"},{c:"3.4.7",s:"於香港處理財產保險的保險中介人，需盡力地確保客戶釐定投保額時最低限度代表財產\n價值。以下哪一項是出現投保額不足導致的後果?",o:["令該次索償無效","投保人需支付額外保費","賠償金額將可能受到比例分攤原則所約束","保險人將拒絕續保"],a:2,e:"大部分類型的非水險財產保險，均明\n文受比例分攤的限制。它的意思是保\n險人預期受保財產會以其全額的價值\n投保。否則，當出現損失時，賠付金\n額便會按不足額投保的比率遞減。"},{c:"3.1.2",s:"以下哪項有關沒有可保權益的說明正確?",o:["該份保險合約從索償產生時被視為無效","該份保險屬可使無效","只有涉及沒有可保權益導致的損失時才無效","一般情況下，在不知道保險無效的情況下繼續支付的保費是可退回的"],a:3,e:"缺乏可保權益的話，有關保險協議便\n屬無效，一般情況下，在不知道保險\n無效的情況下繼續支付的保費是可退\n回的"},{c:"3.1.4(a)",s:"在香港，每一名人士對以下哪項人士的生命不具有可保權益？",o:["個人的本身","個人的配偶","個人的兄弟及父母","個人十八歲以下的子女或受監護人"],a:2,e:"在香港，有血緣的家庭關係一般不可\n構成可保權益，例如兄弟及父母"},{c:"3.1.4(a)",s:"在香港，每一名人士對以下哪項或哪些人士的生命不具有可保權益(為個人本身的利益購\n買人壽保險)？",o:["個人的本身","個人的配偶","個人17歲的妻子","以上所有各項均存在可保權益"],a:3,e:"人身保險：每個人對自己的生命、自\n己的配偶的生命享有可保權益"},{c:"3.1.4(c)",s:"以下哪項或哪幾項是符合可保權益所需要之條件",o:["一男子希望幫助他偷竊回來的財物投買保險","一男子希望幫助他一員工之不忠實投買保險","一男子因為自己的利益,希望幫助他粗心大意的朋友的手錶投買保險","以上各項皆是"],a:1,e:"每個人對他人的作為或不作為負上的\n轉承責任投保，例如僱主可以對其僱\n員的疏忽等行為所導致對公眾的法律\n責任購買保險"},{c:"3.1.4(d)",s:"符合法律認可關係的可保權益，以下哪項為非人身、財物或法律責任的可保權益?",o:["為酒樓電力中斷後，營業利潤損失購買保險","為自己的建築物購買火險","債主為自己的債務購買保險","僱主為受僱職員的損傷購買保險"],a:0,e:"可保權益亦可透過其他合法權利保險\n產生。因自身的合法權利可能受到侵\n犯、或可能喪失未來的收入，而面臨\n潛在損失的威脅的人，都有權對這種\n風險購買保險。"},{c:"3.1.6",s:"以下哪項對轉讓的陳述是正確的?\ni)人壽保險可以不經保險人同意自由轉讓\nii)海上貨物保險可以不經保險人同意自由轉讓\niii)商業「全險」保單不可以沒有保險人同意便轉讓\niv)人壽保險不可以沒有保險人同意便轉讓",o:["i，ii，iii","i，ii，iv","i，iii，iv","ii，iii，iv"],a:0,e:"人壽保險可以沒有保險人同意便轉讓\n，描述iv不正確"},{c:"3.2.4",s:"如果保險人要求保證所有披露資料，不論重要與否，均需完全真實，這表示",o:["違反法例並不能強制執行","延伸普通法中的最高誠信的要求","這合約受制於而非最高誠信","這合約受制於最高誠信"],a:1,e:"保險受到一種更為嚴格、在普通法中\n常被稱為最高誠信的原則所約束。"},{c:"3.2.4",s:"在非人壽保險單續保時，最高誠信的責任",o:["要再履行","無須履行","不再適用","只對保險人適用"],a:0,e:"一些非人壽保單要求，在保險期限內\n如有風險上的變更或續保時，例如買\n了人身意外保險後轉職，必須予以披\n露。"},{c:"3.2.6",s:"某投保人在投保火險保單時忘記披露某些重要事實，該保單的保費為港幣一萬二千元，\n而保險人在保單起保一個月後發現這件事，以下哪項為受屈的保險人可享用的補救",o:["保險人可選擇推翻保單，並保留保單的所有保費","保險人可選擇推翻保單，但須將已付的保費退回","保險人可選擇推翻保單，並保留一個月的保費(即港幣一千元)","保險人可選擇取消合約，並保留一個月的保費(即港幣一千二百元)"],a:1,e:"一般情況下，在不知道保險無效的情\n況下繼續支付的保費是可退回的"},{c:"3.2.6",s:"如果投保人違反最高誠信",o:["保險人可不作追究","除非牽涉詐騙成份的情況下，保險人才可得到補救","除非牽涉詐騙或疏忽成份的情況下，保險人才可得到補救","保險保單會自動取消"],a:0,e:"只撤銷合約的一部分，並不屬於可以\n執行的投保人違反最高誠信補救措施\n，可行的是對違反不予追究"},{c:"3.3.2",s:"在考慮「近因」時，如果一項特定損失涉及一項單一成因，那麼",o:["如果該成因是一項受保危險，被保險人便能就所引致的損失得到保障","如果該成因是一項不保危險，被保險人便不能就所引致的損失得到保障","如果該成因是一項除外危險，被保險人便不能就所引致的損失得到保障","上述所有各項陳述均屬正確"],a:3,e:"如果只有單一成因，只有受保危險所\n引起的損失是受保的。如果涉及一項\n以上的危險，涉及除外危險的發生一\n般會令保險索償或保險金要求失敗"},{c:"3.3.4",s:"在保險索償中，近因法則是",o:["不可以由保單條款來修改","往往可以由保單條款來修改","有時可以透過保單條款來修改","是絕對性的，不可經私人協議而修改"],a:2,e:"很通常保險人借助某些保單措詞，更\n改近因法則的應用，"},{c:"3.4.2",s:"以下哪項不是一般業務的處理範圍",o:["計算彌償","運用比例分攤","計算及處理保單抵押貸款","應用代位"],a:2,e:"計算及處理保單抵押貸款是屬人壽保\n險業務處理範圍"},{c:"3.4.2",s:"彌償只能出現於",o:["人壽保險保單之間","提供收益的保單之間","非提供彌償的保單之間","提供彌償的保單之間"],a:3,e:"彌償只能出現於提供彌償的保單之間"},{c:"3.4.7(b)",s:"如果保單受x金額免賠額條約所約束，這就意味著",o:["如果損失超過x金額，得不到任何賠償","除非損失超過x金額，否則得不到任何賠償","超過x元的損失保險人全額賠償","保單保額受x元限制"],a:1,e:"免賠額規定損失超過免賠額金額，被\n保險人就可以得到扣除免賠額後的賠\n償金額"},{c:"3.4.8",s:"重置保險，「以新代舊」保障，約定價值保單及水險保單之共通點是",o:["不受彌償限制","同樣提供超越彌償","同樣適用於所有業務","跟彌償沒有關係"],a:1,e:"重置保險，「以新代舊」保障，約定\n價值保單及水險保單同樣提供超越彌\n償保單"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約定價值$1,000,000」，\n意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方\n式提供保險保障的，約定價值一律被\n視為損失時的實質價值"},{c:"3.5.1",s:"保單持有人購買了一份意外死亡保險及汽車意外保險。若保單持有人在一次汽車意外中\n死亡，以下哪項索償是正確的？",o:["僅僅是首先生效的保單","僅僅是最大保額的保單","兩份保單也會作出賠償","由於是在汽車意外死亡，故只有汽車意外保險作出賠償"],a:2,e:"壽險及個人意外保險是些提供利益的\n保單，按照被保險人死亡或有關損傷\n訂明的數額支付利益"},{c:"3.5.5",s:"以下那項條款是指「把保險人的責任限於它對損失的比率份額」？",o:["免分擔條款","比率之數條款/分擔條款","代位權","更具體受保條款"],a:1,e:"比率之數條款或分擔條款是把保險人\n的責任限於損失的某個比率份額。"},{c:"3.6.2",s:"代位權的出現，是由第三者疏忽地對受保財產造成損毀，並且該財產的保險人承繼對疏\n忽人士行使法律權利。技術上，此代位權是來自",o:["侵權法","法規下","分攤","因他人的行為疏忽而負上責任"],a:0,e:"一般情況因第三者疏忽而引致了損失\n，這是在侵權法上產生的代位權"},{c:"3.6.4",s:"對於一隻購買了全險的指環，在遺失後按照保額的5萬元如數結清。該指環稍後時間尋回\n並以6萬元售出。在代位的原則下，該1萬元的利潤",o:["屬於保險人","屬於被保險人","由保險人及被保險人平均分享","給付由保險人指明的慈善機構"],a:1,e:"在這情況下，保險人只能保留相當於\n自己已賠付的金額，任何餘額則歸被\n保險人所有。"},{c:"3.6.4",s:"建築商就一意外向一架私家車擁有人支付$13,000,000。因為一項每宗責任事故限額的應\n用，該名私家車司機只有向其責任保險人取得保險金$12,000,000。如果保險人後來向第\n三者追回$7,000,000，請問誰有權取得這筆錢?又怎樣分這筆金額?",o:["保險人佔 $7,000,000，被保險人沒有份兒","保險人沒有份兒，被保險人 $7,000,000","保險人佔 $6,000,000，被保險人 $1,000,000","保險人佔十三分之十二，被保險人佔十三分之一"],a:2,e:"因為保單限額的應用，被保險人尚欠1\n00萬的賠償，如果保險人後來向第三\n者追回700萬，被保險人可分享100萬\n代位益，保險人則享餘下600萬"},{c:"4.1",s:"哪句說話最可以形容產品開發部的功能?",o:["針對小客戶而設","對維持保險公司的競爭力至為重要","為應付法規要求而設","純粹為行銷目的而設"],a:1,e:"由於競爭對手樂於倣效及抄襲別人的\n新產品，全新產品具有競爭力的壽命\n極為短暫，可能只有數個星期而已。"},{c:"4.3&4.4",s:"哪句說話最可以形容市場行銷及保險的銷售部門的關係?",o:["他們可以完全獨立運作","他們的工作出現高度重疊","他們向不同的管理層匯報","他們面對著不同的客戶群"],a:1,e:"保險銷售與市場行銷之間有着十分密\n切的關聯 。在活動範圍上，\n可能出現重大重疊"},{c:"4.9",s:"以下哪項就精算支援的描述是正確的?\ni. 《保險業條例》要求所有獲授權保險人必須委任一名合資格並被保監局接納的精算師\nii. 精算師的主要職責是對所有資產及負債進行評估\niii. 只有人壽保險需要精算支援\niv. 精算支援負責估算所需的未決申索儲備金",o:["ii,iv","i,ii,iv","ii,iii,iv","i,iv"],a:0,e:"《保險業條例》要求所有從事長期業\n務的保險人，委任一名合資格並被保\n險業監管局接納的精算師。人壽保險\n及一般保險需要精算支援。所以選項i\ni 及iv才正確。"},{c:"4.1",s:"產品研究應將焦點放在",o:["本身的產品而已","競爭對手的產品而已","本身及競爭對手的產品","本身及競爭對手的產品，以及市場的趨勢"],a:3,e:"產品研究可從三個方面來考慮包括原\n有產品，競爭對手的產品及市場趨勢"},{c:"4.5",s:"一項保險，保險人於其後時間不能取消，而且只可能對每項風險進行一次核保，此保險\n為",o:["人壽保險","汽車保險","海上船體保險","公眾責任保險"],a:0,e:"人壽保險一經生效可存在數十年，所\n以人壽保險核保機會只有一次。"},{c:"4.5",s:"下列哪一項有關一般保險業務的陳述是錯誤？",o:["核保會採取較較為分散的處理方式","業務範圍十分廣泛","涉及之業務風險甚高","其賠償涉及複雜的紅利計算"],a:3,e:"只有人壽保險才涉及複雜的紅利計算"},{c:"4.5",s:"人壽保險核保部門眼中的「目標風險」，較可能屬於以下哪類風險？",o:["極高保額的風險","保險人尤其願意承保的風險","保險人尤不願意承保的風險","有關保險代理人可得到較高佣金率的風險"],a:1,e:"目標風險在人壽保險中可以解釋為極\n為合意的業務類型"},{c:"4.7",s:"處理人壽保險及一般保險理賠時出現的兩項主要共同的特點是責任及",o:["如何提供彌償","數額","分擔","代位權"],a:1,e:"處理任何保險賠案時，責任和數額問\n題必須解決"},{c:"4.10",s:"下列哪項屬於會計及投資部門的工作?\ni)紀錄保存\nii)款項收集\niii)付款\niv)投資",o:["i，ii，iii","i，ii，iv","ii，iii，iv","以上各項皆是"],a:3,e:"紀錄保存，款項收集，付款，投資都\n屬於會計及投資部門的工作。"},{c:"5.2",s:"以下哪項就獲授權的保險人的描述是不正確的?",o:["獲授權保險人可以是從事「 純 」 長期業務","獲授權保險人可以是從事「 純 」 一般業務","獲授權保險人不可以是專業再保險人","獲授權保險人可以是綜合業務保險人"],a:2,e:"獲授權保險人可以是專業再保險人，\n所以答案C不正確"},{c:"5.5",s:"香港保險業聯會的成立，其使命宣言是鼓勵會員達到最高道德標準及",o:["專業水平","效率","能力","索償標準"],a:0,e:"香港保險業聯會的成立，其使命宣言\n是鼓勵會員達到最高道德標準及專業\n水平"},{c:"5.5",s:"過去曾經營辦保險代理登記委員會的自我規管團體是",o:["香港保險業聯會","香港保險業監管局","香港保險顧問聯會","香港專業保險經紀協會"],a:0,e:"香港保險業聯會過去曾經營辦保險代\n理登記委員會的自我規管團體"},{c:"5.1.1",s:"根據《保險業條例》的分類，保證合約稱為",o:["疾病","擔保","資本贖回","財產損壞"],a:1,e:"擔保保證合約，包括忠實保證及履約\n保證，屬一般保險業務"},{c:"5.1.1",s:"因意外喪失能力或健康欠佳提供利益的長期保單是？",o:["意外","永久健康","意外及疾病","永久喪失能力"],a:1,e:"永久健康是因意外喪失能力或健康欠\n佳提供利益的長期保單，屬一般保險\n業務"},{c:"5.1.1",s:"根據《保險業條例》的保險類別分類，以下哪項保險屬於一般保險而非包括在長期業務\n的業務範圍內",o:["信貸","相連長期","永久健康","資本贖回"],a:0,e:"信貸承保因債務人不能償還債務而使\n債權人遭受損失，屬一般保險業務"},{c:"5.1.3",s:"以下哪項或哪些是保險業中的學術分類?",o:["工程保險","經濟權益保險","一籃子保險","以上各項都是"],a:1,e:"保險的學術類別可分為人身，財產，\n責任及經濟權益保險"},{c:"5.1.4",s:"以下哪一項是有關再保險的正確描述?",o:["當保險人發現某保單保額不足的時，以再保險方式購買多一份保險以彌補賠償損失","保險人以再保險降低賠償時的變現風險，尤其於重大事故發生巨額賠償時，保險人可\n能即時需要大量現金","再保險只適用於核事故或天災的大型風險","再保險是保險人增加資本的方法"],a:1,e:"再保險人向保險人提供保險保障"},{c:"6.11f",s:"於香港的一般業務保險人必須就其從香港保險業務所產生的負債在香港維持正資產，以\n下哪項就所需數額計算的描述是正確的?\ni. 淨負債額 （即已經扣除再保險所保的那部分）的百分之80%\nii. 計算保險人的淨負債額 （即已經扣除不保損失的部分）的80% 及有關數額加起來\niii. 所需數額以訂明的兩種匯算方法之一計算\niv. 計算保險人的淨負債額 （即已經扣除具爭議的債務）的80% 及有關數額加起來",o:["i, iii","ii,iv","i,ii,iv","i, iii,iv"],a:0,e:"經營一般業務的保險人，在香港維持\n資產，所需數額以訂明的兩種匯算方\n法之一計算，其中一項是淨負債額即\n已經扣除再保險所保的那部分）的百\n分之八十，所以描述ii及iv不是答案"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不是保險業監管局成立的政策目標？\ni. 為保單持有人提供經濟援助\nii. 確保保險業的規管架構與時並進，促使保險業的高速發展\niii. 確保保險業的償付準備金與國際慣例看齊\niv. 與國際慣常做法看齊，監管機構在財政上和運作上獨立於政府",o:["i, iv","i, ii, iii","i, ii","ii, iii, iv"],a:1,e:"由此描述iv是屬於保險業監管局成立\n的政策目標，i,ii,iii則不是保險業\n監管局成立的政策目標，詳細參閱研\n習資料手冊6.1"},{c:"6.2.5(f)(ii)",s:"以下哪項有關《持牌保險經紀操守守則》一般原則 2\n–以符合客戶的最佳利益行事並公平對待客戶的描述是正確的？",o:["在推薦保險產品予客戶前，應從充足範圍的不同保險人處，尋找及選擇充足範圍並可\n供選擇的保險產品，而該等產品是適合其客戶情況","應採取合理步驟，準確及時地執行客戶的指示","應就其進行的受規管活動保存妥善的紀錄，以遵守所有適用的法律","應有足夠的管控及保障，以防止未經授權存取客戶資產"],a:0,e:"詳細參閱研習資料手冊6.2.5(f)(ii)\n《持牌保險經紀操守守則》"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["列明保險中介人八大操守原則","由香港保險監管局執行","列明保險代理管理的優良保險做法","以上各項皆是"],a:2,e:"承保商專業守則由香港保險業聯會執\n行，列明保險代理管理的優良保險做\n法"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["由香港保險業聯會執行","列明保險中介人八大操守原則","保險人的資本規定","以上皆是"],a:0,e:"承保商專業守則由香港保險業聯會執\n行，列明保險代理管理的優良保險做\n法"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求描述是正確的?",o:["代表保險人的第三者，應該具備相關經驗","代表保險人的第三者，應該相關經驗及具備專業資格","不得委派律師或理賠師以外第三者","代表保險人的第三者，在任何情況下都應當合理地行事，並且應該具備專業資格"],a:3,e:"根據《承保商專業守則》代表保險人\n的第三者（理賠師等），在任何情況\n下都應當合理地行事，並且應該具備\n專業資格。"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有保證價值此事實\nii.投保人訴在核保結果為次標準風險\niii保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒有\n驗證其真實年齡\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單是屬於「抗通脹保單\n」",o:["i,ii,iii","i,iii,iv","iii,iv","i,ii,iii,iv"],a:1,e:"投訴個案與保險人的服務水平或核保\n決定無關"},{c:"6.2.4(c)",s:"負責人須最少具有多少年保險業管理經驗？",o:["2年","5年","10年","15年"],a:0,e:"負責人須最少具有兩年保險業管理經\n驗"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項有關最低實繳股本的要求是正確的 ?\ni)專屬自保保險公司為港幣200萬元\nii)只從事相連長期保險業務的保險人為港幣1,000萬元\niii)同時從事一般業務及長期業務為港幣2,000萬元\niv)從事一般業務的保險人﹝包括法定保險業務﹞為港幣2,000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"四個最低實繳股本的要求描述都正確\n，詳細請參閱研習資料手冊 6.1.1b"},{c:"6.1.1d",s:"根據《保險業條例》的條文，須事先取得保險業監管局認可才可委任的是︰",o:["公司精算師","保險人的管控要員","保險公司的任何一位財務總監","保險公司的理賠經理"],a:1,e:"保險人的管控要員須事先取得保險業\n監管局認可才可委任"},{c:"6.1.1d",s:"良好的公司管治，有助促進公司的業務和加強其問責性。保險業監管局發出了《獲授權\n保險人的公司管治指引》旨在",o:["防止獲授權保險人出現行政上的出錯","防止獲授權保險人管理層作出欺詐行為","董事局應該優先考慮投保人利益","獲授權保險人建立高水平的公司管治，加強投保人香港保險業的信心"],a:3,e:"《獲授權保險人的公司管治指引》旨\n在建立獲授權保險人高水平的公司管\n治，加強投保人香港保險業的信心"},{c:"6.1.1g",s:"根據《保險業條例》及相關法例，以下哪項屬於保險業監管局的干預範圍：\ni) 限制保費收入\nii) 將保險人清盤\niii) 特定的精算調查\niv) 行使對保險人的管理權",o:["只有 i, ii","只有 ii, iii","只有 i, ii, iii","i, ii, iii, iv"],a:3,e:"四個描述都保險業監管局的干預權力\n，詳細請參閱研習資料手冊 6.1.1g"},{c:"6.1.3",s:"保險投訴局成立的基本目的是",o:["代表成員處理及給付理賠","處理各類針對人之投訴","處理來自以個人作保單持有人的索償投訴","處理來自第三者的法定保險索償"],a:2,e:"保險投訴局的職權範圍涉案保單屬於\n個人保單，投訴個案不涉及商業、工\n業或第三者保險"},{c:"6.1.3a",s:"投訴索償委員會由5人組成，當中有幾人來自保險業？",o:["無1人","2人","3人","4人"],a:1,e:"投訴委員會的委員中，只有兩位是來\n自保險業的，其餘兩位則為業外人士\n。"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有保證價值此事實\nii.保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒有\n驗 證其真實年齡\niii.客人投訴保險人服務差，從而令客人有損失\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單是屬於「抗通脹保單\n」",o:["i , ii , iv","ii , iii","ii ,iii ,iv","iii ,iv"],a:0,e:"投訴個案與保險人的服務水平或核保\n決定無關"},{c:"6.2.5(g)",s:"保險經紀備存的妥善簿冊及帳目，所需保留的最低限期為",o:["一年","三年","五年","七年"],a:3,e:"保險經紀備存的妥善簿冊及帳目，所\n需保留的最低限期為七年"},{c:"6.2.5(g)",s:"保險經紀必須備有「專業賠償保險」，最低的賠償限額為",o:["港幣10萬元","港幣200萬元","港幣300萬元","港幣400萬元"],a:2,e:"保險經紀必須備有「專業賠償保險」\n，最低的賠償限額為港幣300萬元"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項屬於利益?\ni. 客戶送贈的禮物\nii. 團隊隊員給予的佣金\niii. 百貨公司折扣禮劵\niv. 保險公司職位",o:["i","i,ii","i,ii,iv","以上各項皆是"],a:3,e:"「利益」的定義廣泛，包括金錢、饋\n贈、貸款、報酬、佣金、職位、任何\n職位、受僱工作或合約、服務、優待\n及任何有價證券或任何種類的其他財\n產或財產權益"},{c:"7.4.7b",s:"基於風險為本的關鍵原則是",o:["正確釐定保費","所有交易應用相同措施","根據風險級別分配資源","遵循標準慣例"],a:2,e:"基於風險為本的關鍵原則是根據風險\n級別分配資源"},{c:"7.2.1",s:"資料使用者透過制定服務合約，對資料處理者施加的責任是:\ni. 資料使用者有權審核及視察資料處理者如何處理和儲存個人資料\nii. 不再需要就受託目的處理有關個人資料時， 必須適時交還、銷毀或刪除有關資料\niii. 須採取的保安措施，以保障受託的個人資料，並要求資料處理者遵從保障資料原則\niv. 資料處理者必須居於香港",o:["i.ii","ii,iii,iv","iii,iv","i.ii.iii"],a:3,e:"資料處理者必須居於香港不是對資料\n處理者施加的責任"},{c:"7.5.2",s:"以下哪一項是廉政公署24小時舉報熱線？",o:["999","25 266 366","1823","24 266 366"],a:1,e:"以下哪一項是廉政公署24小時舉報熱\n線是25 266 366"},{c:"7.2.1",s:"《個人資料 （私隱 條例》 由哪個機構執行?",o:["個人資料私隱專員公署","保險業監管局","資訊科技監控辦公室","以上各項皆不是"],a:0,e:"《個人資料（私隱條例》由個人資料\n私隱專員公署執行"},{c:"7.2.1",s:"以下哪項對《個人資料(私隱)條例》範圍的陳述是正確的?：\ni. 自動化操作資料\nii.只適用於人手操作資料\niii. 只適用香港永久居民\niv. 它既涉及公營機構及私營機構",o:["i,ii,iii","i,iii,iv","i,iv","i,ii,iii,iv"],a:2,e:"個人資料是指自動化操作資料及涉及\n公營機構及私營機構"},{c:"7.3.2",s:"對保險業而言，以下哪項屬於公平歧視(即合法)的情況",o:["向女性取較低的人壽保險保費","向男性付出年金款項比同一年齡的女性較多","向殘疾人士的保單加設特定條款","以上各項皆是"],a:3,e:"答案選項A,B及C都屬於保險中的公平\n歧視"},{c:"7.3.2",s:"以下哪項有關保險人對投保人給予性別差別對待是法律容許的，並不觸犯歧視條例？",o:["有關待遇是藉參照可合理依據的來源所得的精算數據","有關待遇是藉參照可合理依據的來源所得的精算數據或其他數據而給予的","就有關因素而言屬於合理","一切參照可合理依據的來源所得的精算數據"],a:1,e:"保險人對投保人給予性別差別對待是\n藉參照可合理依據的來源所得的精算\n數據或其他數據而給予的"},{c:"7.5",s:"以下哪項是貪污，必須避免觸犯？",o:["個人為謀取私利，從而引至社會利益受損","個人為謀取私利，濫用職權，從而引至他人利益受損","個人未經準許謀取私利，從而引至他人利益受損","個人挪用屬於他人的財產"],a:1,e:"貪污是指個人為謀取私利，濫用職權\n，從而引至他人利益受損"},{c:"7.6",s:"保險事宜上的詐騙",o:["可循多種途徑發生，不論是否與索償有關","只會於涉及索償時發生","從來不會於人壽保險上發生","只會於涉及財產損害的索償時發生"],a:0,e:"保險事宜上的詐騙可循多種途徑發生\n，不論是否與索償有關"}],"paper1-2025-09":[{c:"1.1.2(a)",s:"因心臟病產生的醫療開支最有可以被歸類為_____________。",o:["純粹風險","投機風險","特定風險","基本風險"],a:2,e:"特定風險能成的後果是相對有限的，\n只影響個人或為數較少的人。這類風\n險包括汽車意外、個人損傷等情況。"},{c:"1.1.2b(ii)",s:"以下哪項對於基本風險的描述是正確?",o:["泛指地震等的天然災害","只影響個別的保單持有人","影響到整個社會而非個人","A 及C都正確"],a:3,e:"基本風險包括饑荒、戰爭、恐怖襲擊\n等數、大規模洪災等。這些災害影響\n到整個社會或人類，而非其中的特定\n個體，所以A 及C都正確。"},{c:"3.3.3(iii)",s:"如果索償涉及______________，該項索償很有可能被拒",o:["不保危險","除外危險","自然災害造成的損失","人為錯誤"],a:1,e:"除外危險的發生一般會令保險索償\n或保險金要求失敗，但複雜的例外情\n況是存在的。"},{c:"1.1.3(c)(iii)",s:"就以下風險管理措施，提供安全訓練屬於",o:["風險避免","損失防範","損失降低","風險轉移"],a:1,e:"損失防範降低已識別出來的損失發生\n的頻率。提供安全訓練是例子"},{c:"1.1.3",s:"不提供食物及飲料以避免食物中毒的風險，屬哪種風險管理的措施?",o:["風險避免","損失防範","損失降低","風險轉移"],a:0,e:"風險避免是不讓自己暴露在某項風險\n之下，從而免除遭受相關損失的機會"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni. 保險對受保損失的被保險人提供財務補償\nii. 保險為本港提供就業機會\niii. 一般保險的慣例下倡導防範損失的措施\niv. 一般保險的慣例下倡導控制損失的措施",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:3,e:"保險對受保損失的被保險人提供財務\n補償屬保險的基本功能,選項(i)不正\n確"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni. 保險為本港提供就業機會\nii. 保險對受保損失的被保險人提供財務補償\niii. 一般保險的慣例下倡導防範損失的措施\niv. 某些業務可以涉及很高的純粹風險，或會令投資者卻步，除非他們可以投保潛在的\n財務損失",o:["i, ii, iii","i, ii","i,iii,iv","i, ii, iii, iv"],a:2,e:"保險對受保損失的被保險人提供財務\n補償可視為保險為香港帶來的基本功\n能/好處，,選項(ii)不正確"},{c:"1.1.1",s:"「風險」的定義是",o:["保險人有可能變成資不抵債的危險性","潛在利益有關的不確定性","對可能發生的風險有保護措施","潛在損失有關的不確定性"],a:3,e:"「風險」帶有損失或危險的意思，可\n以把它定義為「與潛在損失有關的不\n確定性」"},{c:"1.1.1",s:"保險與風險之間的聯繫如何",o:["有些風險(不過並非所有種類)是可保的","若有保險的保障，所有財務損失都是保險人的責任","風險提供保障的唯一方法就是保險","所有類型的風險都是可保的"],a:0,e:"例如財務上及身體上的風險較有可能\n成為商業上的可保風險，不過並非所\n有種類的風險是可保的"},{c:"1.1.1",s:"以下哪項有關風險的陳述是正確的？\ni.所有風險都是可保的\nii.並非所有風險都屬於商業上可保的\niii.保險是應付風險的唯一方法\niv.保險人談及風險時可以有很多不同的含義",o:["i, ii","ii, iii","ii, iv","iii, iv"],a:2,e:"例如財務上及身體上的風險，較有可\n能成為商業上的可保風險，不過，並\n非所有種類的風險是可保的，而購買\n保險只是應付風險的其中一項方法"},{c:"1.1.3",s:"以下哪項不是「風險管理」的正確陳述？",o:["這個詞可以是與純粹風險及投機風險有關","以銀行為例，指對投資及其他投機風險的管理","保險人可把範圍縮窄至只對可保風險的管理","保險人只會在談論承保損失價值時才用這個詞"],a:3,e:"就保險公司而言，這可能僅指對粹風\n險的管理，甚至可把範圍進一步收窄\n至只對可保風險的管理，而不是只在\n談論承保損失價值時才用這個詞"},{c:"1.1.3",s:"以下哪項有關「風險管理」一詞的描述是正確的",o:["只適用於保險公司","保險公司不大可能收窄此詞之應用至純風險","它指三步驟:風險識別˴風險免除及風險融資","它包含二個步驟: 風險識別及風險量化"],a:3,e:"一個獨立的知識與研究的領域，風險\n管理可以解釋為管理學的一個分支，\n它要進行的步驟包括識別；量化，及\n應對"},{c:"2.2.2",s:"代理關係的產生必須存在以下哪項條件?",o:["該關係可以是通過代理協議產生的","訂約行為能力","該關係必須得到法律認可的關係","代價"],a:0,e:"代理關係是指存在於委託人與其代理\n人之間的一種關係。它的出現是基於\n事實，而不一定經過一個精確的委任\n代理過程。"},{c:"2.1.2(a)",s:"就簡單合約而言，以下哪項描述是正確的?",o:["僅以書面或從行為中推斷出來的合約","從名稱來看因為合約對大部分人易於理解","簡單合約的有效性並不取決於特殊的手續","以上各項皆是"],a:2,e:"簡單合約卻不表示內容容易理解，它\n只是意味着合約的訂立是簡單、容易\n的。"},{c:"2.2.5",s:"代理人代表委託人行事時招致的費用，委託人應",o:["只支付與交通有關的費用","只支付委託人事前同意的費用","向代理人報銷行事時適當及合理地招致的費用及開支","只支付在符合代理協定條件下的費用"],a:2,e:"在符合代理協定的任何明示條件下，\n委託人必須對代理人代表其行事時適\n當及合理地招致的費用及開支，\n予以償還。"},{c:"2.2.3(b)",s:"表面權限意味著",o:["授權不存在，而且代理人的行為會對委託人並沒有約束力","基於過去的交易，代理人的行為會對委託人產生約束力","權限是透過委託人表明同意而產生的，並可能會對委託人產生約束力","在緊急的情況下持有必要權限為委託人採取行動，並成為必要代理人"],a:1,e:"表面權限是當一個代理人的權限是透\n過委託人對第三者(不是委託人)表明\n同意而產生的，基於過去的交易，代\n理人的行為會對委託人產生約束力"},{c:"2.2.1",s:"一名母親指使其小孩到一家雜貨店購買雞蛋，意味著",o:["商店與該名母親之間訂立了一份銷售合約","小孩與該名母親之間訂立了一份銷售合約","小孩負上轉承責任","代理法約束著小孩的行為"],a:0,e:"商店與該名母親之間訂立了一份銷售\n合約，因為母親作為委託人承擔了支\n付貨款的法律責任 。"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構成要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就\n沒有合約。"},{c:"2.2",s:"以下哪項對代理法的描述是正確的?\ni.保險人透過保險代理人行事與親自執行沒有分別\nii.委託人需對代理人行為負起轉承責任\niii.保險代理人及保險經紀有能力就保險人的行為負起轉承責任\niv.代理關係必須透過書面方式訂立而產生",o:["i , ii","i, ii, iii","ii,iii","i, ii, iii, iv"],a:0,e:"代理關係是指存在於委託人與其代理\n人之間的一種關係。它的出現是基於\n事實，而不一定經過一個精確的委任\n代理過程。委託人須對其代理人的行\n為負上轉承責任責任。"},{c:"2.2.3(d)",s:"如果有人允許他人表示另一人是他的代理人，而他不能否定該代理人的權限。這代理權\n法則稱為",o:["實際權限","必要權限","表面權限","不容反悔的代理權"],a:3,e:"如果有人允許他人表示另一人是他的\n代理人，而他不能否定該代理人的權\n限。這代理權法則稱為不容反悔的代\n理權"},{c:"2.1.2(a)",s:"某人從一個小販那裏拿起一份雜誌，清楚地表明他要購買，技術上，這是",o:["行為中推斷出來的合約","契據","簡單合約","嚴格來說，這並不構成合約"],a:0,e:"技術上，一個合約已經在買主與賣主\n之間產生了，它是通過付錢與收錢等\n行為而訂立的，無需借助任何言語或\n文字"},{c:"2.1.3(b)",s:"如果保險人表示須就某項投保取額外保費及附加保單免賠額，才會接納該風險，這種由\n保險人提出的建議在法律上可以稱為",o:["反要約","相反的要約","有保留承約","有條件承約"],a:0,e:"如果保險人有意更改擬訂合約的條件\n，例如要求增加保費或附加保單限制\n，這種意向一經傳達便構成了反要約"},{c:"2.2",s:"在法律上「一種透過他人行事與自己親自執行並無分別」的原則稱為",o:["轉承責任","必要責任","替代責任","不容反悔代理權"],a:0,e:"在法律上「一種透過他人行事與自己\n親自執行並無分別」的原則稱為轉承\n責任"},{c:"2.2.3",s:"代理人的權限包括：\ni) 實際權限\nii) 表面權限\niii) 非表面權限\niv) 必要權限",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"非表面權限不屬代理人的權限種類"},{c:"2.2.3(a)",s:"委託人明示或隱含地向代理人表明同意代理人代表委託人或替其行事，是屬於下列哪項\n代理人的權限",o:["實際權限","表面權限","必要權限","不容反悔的代理權"],a:0,e:"委託人明示或隱含地向代理人表明同\n意代理人代表委託人或替其行事，屬\n於實際權限"},{c:"2.2.3(c)",s:"如果需要或出於人道或其他合理的原因，某人代理另一人行事的開支，即使沒有獲授權\n，此人也可以被認為是他的代理人，這種代理關係的成立是基於以下那項？",o:["實際權限","表面權限","必要權限","不容反悔"],a:2,e:"必要權限是:當一名現有委託人的財產\n或權益受着迫切的危害，而有一名現\n有代理人在這個危急的情況下，必要\n地採取行動，即使沒有取得明示權限\n，透過該等行為成為必要代理人。"},{c:"2.2.4",s:"一名代理人在下列哪種情況，可以把他的權限及責任下放給一位分代理人？",o:["任何時候，只要他願意便可","只當他具備這方面的權限","只要他認為合理才可","他可以這樣做，並有權從委託人收取雙份佣金"],a:1,e:"代理人不能把取得的代理權及承擔上\n的職責，下放給他人(分代理人），除\n非他具有這樣做的權限。"},{c:"2.2.6",s:"下列哪項或哪些屬於保險代理協議终止的途徑?",o:["撤銷","衝突或沒有達成協議","不忠誠","以上所有各項"],a:0,e:"撤銷屬於代理協議终止的其中一項途\n徑"},{c:"3.3.2",s:'以下哪項屬於近因中被視為"危險"',o:["合約責任","金錢","職員盜竊","汽車損壞"],a:2,e:"危險，即是造成有關損失的成因，職\n員盜竊是造成財務有關損失的成因。"},{c:"3.1.2",s:"以下哪項對可保權益的描述是不正確?",o:["必須先有可被保的","必須是該保險的標的","如對該保單的保單所有人生命購買保險是無須擁有","投保人與保險標的之間存在被法律認可的關係"],a:2,e:"缺乏可保權益的話，有關保險協議便\n屬無效"},{c:"3.1.4",s:"以下哪項可保權益的陳述正確?",o:["適用於計算保費融資利率","又可稱為保險標的","又可稱為保險標的","沒有保權益，有關保險協議便屬無效"],a:3,e:"缺乏可保權益的話，有關保險協議便\n屬無效"},{c:"3.2.6",s:"就保單而言，非欺詐性不披露",o:["投保人無意地違反了保險條款","該保險人可以推翻保單","受屈的保險人僅可以訴訟提出損害賠償申索","投保人對重要事實作出失實陳述"],a:1,e:"非欺詐性不披露是無意地或疏忽地漏\n了向另一方披露重要事實，受屈的保\n險人可在合理時間内自始推翻整個合\n約"},{c:"3.2.4",s:"根據普通法，投保人需要遵守最高誠信責任的期限",o:["直至索償為止","直至該合約生效為止","涉及整段合約生效時","僅至簽署投保書時為止"],a:1,e:"在普通法中，於保險合約訂立後，投\n保人才得知的重要事實，不必予以披\n露。"},{c:"3.1.4",s:"以下哪項可保權益的陳述正確?\ni.每人對自己的肢體都有保險利益\nii.承按人不可以對按揭財產投保\niii.又可稱為保險標的\niv.保險人與被保險人之間法律認可的關係",o:["i","i,ii,iii","ii,iv","i, ii,iv"],a:0,e:"可保權益是投保人與保險標的之間必\n須存在被法律認可的關係，承按人是\n持有次於絕對擁有權的權利，可以對\n按揭財產投保，只有選項(i)是正確"},{c:"3.3.2",s:"除外危險_____________",o:["保單不承保的危險","與不保危險有相同的對待","除超額保障以外，將承保的危險","例如各種天災，地震等"],a:0,e:"除外危險是被除外責任條款豁免承保\n的"},{c:"3.1.4",s:"構成財產保險可保權益的條件是",o:["單單管有該財產不構成可保權益","與保險標的之間存在法律認可的關係","構成可保權不一定擁有該財產","以上各項皆是"],a:3,e:"構成財產保險可保權益的條件，可以\n是持有次於絕對擁有權的權利，分別\n為遺產、信託財產、按揭財產投保。"},{c:"3.4.7(b)",s:"以下哪項阻止了保單作出彌償?\ni. 起賠額\nii. 免賠額\niii. 起賠期限\niv. 重複保險",o:["i,ii","i,ii,iii","iii,iv","以上皆是"],a:1,e:"分擔適用於理賠時遇上重複保險的情\n況，更有效地達到彌償效果。選項(iv\n)不正確"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["承讓人承諾支付未來的保費","保單轉讓人只會把在合約中的權益轉移到承讓人的身上","保單轉讓人只會把在合約中的的責任轉移到承讓人的身上","保單轉讓人在合約中的權益和責任均完全轉移到承讓人的身上"],a:1,e:"保單「轉讓」通常是指權利的轉移。\n轉讓是不會讓轉讓人在保險合約的責\n任轉移到承讓人的身上的"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約性質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險人的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓\n收取保險金的權利無需取得保險人的\n同意"},{c:"3.2.4",s:"投保人於投保時遵守最高誠信以披露重要事實的期限",o:["只有保單持有人特別提出要求時予以延伸","法律並不容許予以延伸","一直至合約具約束力結束為止，並無例外","有時通過相互協議予以延伸"],a:3,e:"在普通法中，於保險合約訂立後，投\n保人才得知的重要事實，不必予以披\n露。所以，保險人有時通過相互協議\n予以延伸最高誠信以披露重要事實的\n期限"},{c:"3.4.7(b)",s:"保單的免賠額是$1000元，哪麼意味著",o:["如果損失超過$1000元，將不獲任何賠償","如果損失$1000元以下，將不獲任何賠償","保額減去$1000元","賠償金額以$1000元為上限"],a:1,e:"免賠額是規定了低於某指定金額的任\n何損失，被保險人都不獲賠償。\n即是說，該金額將從每宗索償中扣除\n。"},{c:"3.1",s:"彌償及可保權益這兩項保險原則",o:["在財務利益方面存在著密切關聯","完全沒有共通之處","各自有完全相反的用意","尋求確立損失的有效原因"],a:0,e:"「權益」一詞是指一種與某物件或與\n某人之間的財務關係。"},{c:"3.1.4",s:"構成財產保險可保權益的是",o:["在擁有人同意下管有該項財產","需對保管的財產的損失負責","絕對擁有該項財產","以上各項皆是"],a:3,e:"構成財產保險可保權益的條件，可以\n是持有次於絕對擁有權的權利，分別\n為遺產、信託財產、按揭財產投保。"},{c:"3.1.4(c)",s:"一間育兒院要求每一位家長必須簽署一份協議書，當中訂明其孩子在育兒院內所受之傷\n害，家長不得向育兒院追究。儘管如此，育兒院營運人就其所照顧的孩子在其處所所受\n之傷害的潛在法律責任購買了一入責任保險。請問育兒院是否布權購買此份保險，理由\n何在?",o:["他不必購買此份保險，因政府註冊的育兒院不須承擔責任","保險無效；因大部份的責任保險將「受保處所之傷害」列為除外責任","保險有效；育兒院營運人需為其作為或不作為負擔其潛在的法律責任","保險無效；因沒有法律責任，在欠缺可保權益下不能購買保險"],a:2,e:"育兒院營運人可以對其僱員的疏忽等\n行為所 導致的法律責任購買保險。"},{c:"3.2.1",s:"有別於最高誠信，一般誠信要求有關各方",o:["保證他們作出的每項陳述均是百分百真實","不論有否被問及也要披露所有重要事實","擔保他們沒有遺漏任何對有關合約的重要事實","忠誠及確保將要提供給對方的資料在實質上真實"],a:3,e:"在普通法上，一般誠信要求有關各方\n必須本着誠實的態度行事，所提供的\n資訊必須是實質上真實的"},{c:"3.2.4",s:"在非人壽保險單續保時，最高誠信的責任",o:["要再履行","無須履行","不再適用","只對保險人適用"],a:0,e:"一些非人壽保單要求，在保險期限內\n如有風險上的變更或續保時，例如買\n了人身意外保險後轉職，必須予以披\n露。"},{c:"3.2.6",s:"如果違反最高誠信，保險人可以",o:["拒絕賠償這次損失，合約在餘下時期內將被視為有效，可以索償","不再追究","如果已經錯誤賠償，可向被保險人提出刑事檢控要求損害賠償","以上所有各項"],a:1,e:"不追究是受屈的保險人針對違反最高\n誠信一方的其中一種補救方法"},{c:"3.3.2",s:"在考慮「近因」時，如果一項特定損失涉及一項單一成因，那麼",o:["如果該成因是一項受保危險，被保險人便能就所引致的損失得到保障","如果該成因是一項不保危險，被保險人便不能就所引致的損失得到保障","如果該成因是一項除外危險，被保險人便不能就所引致的損失得到保障","上述所有各項陳述均屬正確"],a:3,e:"如果只有單一成因，只有受保危險所\n引起的損失是受保的。如果涉及一項\n以上的危險，涉及除外危險的發生一\n般會令保險索償或保險金要求失敗"},{c:"3.4.6",s:"當被保險人提出索償時，將損餘部份交予保險人以換取索取全數賠償。可能在機緣巧合\n下，在出售損餘後的款項高於實質賠償的金額，那麼",o:["保險人便可賺取不俗的利潤","盈餘須與被保險人以五五分賑形式分享","這項事宜須呈予法庭解決","盈餘須歸予被保險人"],a:0,e:"委付是保險標的或它的殘餘部分必須\n完全地移交給保險人，致使保險人可\n從中獲取利益"},{c:"3.4.6",s:"把受保財產的所有權交給保險人，以取得全損賠款的慣例稱為",o:["損餘","轉讓","代位","委付"],a:3,e:"這個詞大多數出現在水險中，它是指\n在某些情況下向保險人交出保險標的\n，作為索取全損的賠償金額的條件。\n在水險中，這是一種十分標準的做法"},{c:"3.4.7(a)",s:"在香港處理財產保險的保險中介人，應該盡力確保客戶將要釐定的保額最低限度代表該\n財產的價值，因為如果有不足額保險出現的話",o:["該保額便告無效","有關的被保險人須支付額外的保費","任何索償相當可能受到比例攤分條款約束","有關保險人在續保時可以拒絕繼續提供保險"],a:2,e:"大部分類型的非水險財產保險均明文\n受比例分攤的限制。它的意思是，保\n險人預期受保財產會以其全額的價值\n投保。否則，當出現損失時，賠付金\n額便會按不足投保的比率遞減，稱為\n比例分攤"},{c:"3.4.8",s:"下列哪項及哪些保單的保障，可以提供超越彌償的索償結清",o:["定值保單 (水險)","重置保單 (火險)","約定價值保單 (非水險)","以上所有各項"],a:3,e:"提供超額彌償的保單有約定價值保單\n，水險保單，重置保險及「 以新代舊\n」 的保險保障"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約定價值$1,000,000」，\n意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方\n式提供保險保障的，約定價值一律被\n視為損失時的實質價值"},{c:"3.5.1",s:"在重複保險上，以下哪項不應出現分擔原理？",o:["火險","盜竊保險","人身意外保險中的人壽利益部份","以上各項皆是"],a:2,e:"只有當彌償出現時，分擔才會適用。\n所以，假如一名購買了兩份或兩份以\n上獨立的人壽保險單的被保險人死亡\n，\n每份保單均因人壽保險不適用彌償原\n則，而須全額賠付。"},{c:"3.5.1",s:'假設銀行借錢給"A"購買物業，不尋常地，該銀行對該物業的權益購買保險保障，而"A"\n亦按照其意志投買保險，如果投保損失發生',o:["按照分擔原則，兩名保險人各自賠償50%","分擔原則不適用，因不是保險相同的權益","A的保單將作出賠償，因他是物業的真正擁有者","銀行的保單將作出賠償，因為借貸協定給它優先權"],a:1,e:"分擔原則不適用，因業主A與銀行所購\n買的保險所保障的權益不相同"},{c:"3.5.5",s:"當發生一項$1,000,000的財產損失，當中出現重複保險。此保單的全損為$30,000,000\n，另設有單一物件限制$5,000。這次總賠償金額為$995,000，這顯示以下哪項所述是正\n確的?",o:["所有其他有關保單都有分擔條款","這份保單有分擔條款","這份保單有比例分攤條款","所有有關保單均有比率之數條款"],a:1,e:"分擔條款又稱比率之數條款，把保險\n人的責任限於損失的某個比率份額。\n結果是，在重複保險的情況下，如果\n每份有關的保單均包含了這項條款的\n話，被保險人就不再可以單靠一個保\n險人而獲全額 賠償。"},{c:"3.6.4",s:"建築商就一意外向一架私家車擁有人支付$13,000,000。因為一項每宗責任事故限額的\n應用，該名私家車司機只有向其責任保險人取得保險金$12,000,000。如果保險人後來\n向第三者追回$7,000,000，請問誰有權取得這筆錢?又怎樣分這筆金額?",o:["保險人佔 $7,000,000，被保險人沒有份兒","保險人沒有份兒，被保險人 $7,000,000","保險人佔 $6,000,000，被保險人 $1,000,000","保險人佔十三分之十二，被保險人佔十三分之一"],a:2,e:"因為保單限額的應用，被保險人尚欠1\n00萬的賠償，如果保險人後來向第三\n者追回700萬，被保險人可分享100萬\n代位益，保險人則享餘下600萬"},{c:"3.6.4",s:"在委付及給予彌償後，保險人應如何處理售賣損餘中得到的利潤？",o:["將利潤歸還保單持有人","保險人和保單持有人五五分帳","利益歸保險人","保險人不可售賣損餘"],a:2,e:"在被保險人將投保財產委付給保險人\n之後，附於這財產的一切權利都屬於\n保險人，包括「從中牟利」的權利"},{c:"4.3&4.4",s:"哪句說話最可以形容市場行銷及保險的銷售部門的關係?",o:["他們可以完全獨立運作","他們的工作出現高度重疊","他們向不同的管理層匯報","他們面對著不同的客戶群"],a:1,e:"保險銷售與市場行銷之間有着十分密\n切的關聯 。在活動範圍上，\n可能出現重大重疊"},{c:"4.9",s:"以下哪項就精算支援的描述是正確的?\ni. 《保險業條例》要求所有獲授權保險人必須委任一名合資格並被保監局接納的精算師\nii. 精算師的主要職責是對所有資產及負債進行評估\niii. 只有人壽保險需要精算支援\niv. 精算支援負責估算所需的未決申索儲備金",o:["ii,iv","i,ii,iv","ii,iii,iv","i,iv"],a:0,e:"《保險業條例》要求所有從事長期業\n務的保險人，委任一名合資格並被保\n險業監管局接納的精算師。人壽保險\n及一般保險需要精算支援。所以選項i\ni 及iv才正確。"},{c:"4.1",s:"產品開發是保險公司的重要功能，原因是",o:["產品開發有助於確保公司的財務穩定","香港有着競爭激烈的營商環境","可以看出，由於在過去幾年中保險監管框架的迅速變化，保險產品很快就過時了","必須根據不斷變化的法規要求對強制性保險單進行頻繁的修訂"],a:1,e:"由於香港有著開放又競爭激烈的營商\n環境，保險人在設計準備銷售的產品\n時，必須做到 高效而有活力"},{c:"4.1",s:"市場上以「組合」形式推出的產品很多，這是屬於產品發展的什麼過程?",o:["個別產品的開發","產品組合的開發","產品的研究","獨立產品的開發"],a:1,e:"產品組合的開發以「組合」形式出現\n的產品，其中尤以大型的客戶為對象"},{c:"4.5",s:"以下哪項有關核保是不正確?",o:["它包括選擇承保的風險","它包括應用受保風險的條款","它同時涉及非人壽業務保險的保單續保","作為人壽保險的保單，它是一種每年重覆的過程"],a:3,e:"個別產品的開發是一個延續不停的過\n程，由於競爭對手樂於倣效及抄襲別\n人的新產品，全新產品具有競爭力的\n壽命極為短暫，可能只有數個星期或\n幾個月而已。"},{c:"4.5",s:"核保的職責是",o:["製備核保手冊、訂費指引","製備拒絕名單","界定承保的風險","以上皆是"],a:3,e:"以上皆是核保的職責"},{c:"4.5",s:"以下哪項或哪些陳述有關一般保險核保是正確的？",o:["它們會集中在總部核保","它們涉及廣泛保障範圍的考慮","在每一份保單只能發生一次","包括以上各項"],a:1,e:"一般保險的保障類型多不勝數。核保\n過程中出現的錯誤並不是永久性的\n，在續保的時候，條件可以檢討，必\n要時保單甚至可以取消，因此核保權\n限可以較為分散。"},{c:"4.5",s:"人壽保險核保部門眼中的「目標風險」，較可能屬於以下哪類風險？",o:["極高保額的風險","保險人尤其願意承保的風險","保險人尤不願意承保的風險","有關保險代理人可得到較高佣金率的風險"],a:1,e:"目標風險在人壽保險中可以解釋為極\n為合意的業務類型"},{c:"5.4(a)",s:"除非取得特定豁免，進行任何受規受規管活動必須獲得保險業監管局授予________",o:["證書","許可證","一個帳戶","會員資格"],a:1,e:"從2019年9月23日起，其所有保險中介\n人都必須獲得保險業監管局的直接許\n可。"},{c:"5.1.1",s:"因意外喪失能力或健康欠佳提供利益的長期保單是？",o:["意外","永久健康","意外及疾病","永久喪失能力"],a:1,e:"永久健康是因意外喪失能力或健康欠\n佳提供利益的長期保單，屬一般保險\n業務"},{c:"6.2.4(f)",s:"以下哪項就《持牌保險經紀操守守則》八大原則的描述是不正確?",o:["頒布於通常情況下期望持牌保險經紀在進行受規管活動時應遵守的操守原則及相關的\n標準及常規","告知並解釋適用於持牌保險經紀的《保險業條例》第90及第92條的法定操守規定","凡持牌保險經紀沒有遵從經紀操守守則”，此事本身會令該經紀可在任何司法律程序\n中被起訴","載列保險購買人在與持牌保險經紀往來時有權期望的專業操守之基本原則"],a:2,e:"凡任何持牌保險中介人沒有遵從操守\n守則，此事本身不會令該中介人可在\n任何司法或其他法律程序中被起訴。\n不過，在為《保險業條例》任何條文\n的目的而考慮持牌保險中介人是否屬\n繼續持牌的適當人選時，可顧及該中\n介人沒有遵從操守守則一事"},{c:"6.1.1f(d)",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（修訂）條例》所授予，\n對獲授權保險新增的規管權力？",o:["罰款","限制保費收入","對新業務的限制","特定的精算調查"],a:0,e:"《2015年修訂條例》下新增的規管權\n力：保監局可以施加的紀律處分包括\n：撤銷暫時撤銷給予保險人的授權、\n禁止申請經營某類別保險業務的授權\n、公開或非公開的譴責、罰款等。"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是不正確的？",o:["專屬自保保險人為3000萬港元","法定或強制性的一般保險業務一般業務為1000萬港元","同時經營一般及長期業務為2000萬港元","只經營長期業務為1000萬港元"],a:0,e:"專屬自保保險人為200萬港元"},{c:"6.1.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不屬保險業監管局成立的政策目標？\ni. 為保單持有人提供更佳的保障\nii. 建立一個直接規管保險中介人的制度，以補充舊有的自律規管制度\niii. 確保保險業的規管架構與時並進，促使保險業的高速發展\niv. 就保險業採取適當措施，鞏固香港的國際保險中心地位",o:["i,ii","i,ii,iii","ii,iii,iv(cid:9)","iii,iv"],a:2,e:"只有選項(i)為保單持有人提供更佳的\n保障屬保險業監管局成立的政策目標\n，其他都不是，詳細請參閱研集資料\n手冊6.1.1"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不是保險業監管局成立的政策目標？\ni. 為保單持有人提供經濟援助\nii. 確保保險業的規管架構與時並進，促使保險業的高速發展\niii. 確保保險業的償付準備金與國際慣例看齊\niv. 與國際慣常做法看齊，監管機構在財政上和運作上獨立於政府",o:["i, iv","i, ii, iii","i, ii","ii, iii, iv"],a:1,e:"由此描述iv是屬於保險業監管局成立\n的政策目標，選項i,ii,iii則不是保\n險業監管局成立的政策目標，詳細參\n閱研習資料手冊6.1.1"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是正確的？",o:["實繳股本是保險人獲得授權其中一項最低要求","實繳股本的管控人必須符合適當人選要求","同時經營一般及長期業務實繳股本要求最高為2000萬港元","實繳股本可按保費收入計算"],a:0,e:"不同的規定實繳股本數額是保險人獲\n得授權其中一項最低要求"},{c:"6.2.1",s:"以下哪一項是保險業條例下不能與受監管意見許可的豁免?",o:["專屬自保保險公司的僱員","會計師","保險經紀","律師"],a:2,e:"從2019年9月23日起，其所有保險中介\n人都必須獲得保險業監管局的直接許\n可。"},{c:"6.1.3c",s:"保險人與保單持有人發生爭議，保險合約可能包含仲裁條款，保單持有人可向保險投訴\n局尋求調解服務，保險投訴局解釋以下哪項條件先需要滿足？\ni. 投訴個案透過仲裁未能達成協議\nii. 爭議雙方已盡力但仍無法達成和解\niii.未能滿足保險投訴局的裁決條件\niv 涉案保險人已對涉案保險人已對索償爭議作出了最終決定",o:["ii,iv","i,ii,iv","i, iii","ii, iii, iv"],a:0,e:"保險投訴局有權處理的投訴，必須符\n合若干條件，投訴個案並非正在進行\n法律程序或仲裁。詳細參閱研習資料\n手冊6.1.3b"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項是保險業監管局成立的政策目標？\ni. 就影響保險業的事宜，進行研究\nii. 提升保險業界在環球保險業市場的競爭力\niii. 協助特區行政長官維持香港金融穩定\niv. 提高保單持有人對保險產品和保險業的了解",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:1,e:"保險業監管局其中一項成立的政策目\n標是協助財政司司長維持香港金融穩\n定。"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["列明保險中介人八大操守原則","由香港保險監管局執行","列明保險代理管理的優良保險做法","以上各項皆是"],a:2,e:"承保商專業守則由香港保險業聯會執\n行，列明保險代理管理的優良保險做\n法"},{c:"6.1.1f",s:"《保險業條例》列明經營一般業務的保險人必須就其從香港保險業務所產生的負債在香\n港維持資產，用來釐定這一數據的方法之一，是計算有關數額與以下之總和",o:["毛負債額（不扣除再保險部分）的80%","净負債額（扣除不保部分）的80%","净負債額（扣除再保險部分及可爭議負債）的80%","净負債額（扣除再保險部分）的80%"],a:3,e:"經營一般業務的保險人，必須就其從\n香港保險業務所產生的負債在香港維\n持資產，所需數額以訂明的兩種匯算\n方法之一計算，其一所要求的數額不\n能少於兩項的總和:\n(i) 淨負債額\n（即已經扣除再保險所保的那部分）\n的百分之八十 ；\n及(ii) 有關數額。"},{c:"6.1.1g",s:"以下哪一項是《2015年修訂條例》賦予保監局的干預權力?\ni. 限制海外股本\nii. 總投資佔股本最高比率必須由保監局指明\niii. 限制保費收入\niv. 將保險人清盤",o:["i , ii , iii","i, ii, iv","iii, iv","ii, iii, iv"],a:2,e:"選項i,ii則不是《2015年修訂條例》\n賦予保監局的干預權力，詳細參閱研\n習資料手冊6.1.1g"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求描述是正確的?",o:["代表保險人的第三者，應該具備相關經驗","代表保險人的第三者，應該相關經驗及具備專業資格","不得委派律師或理賠師以外第三者","代表保險人的第三者，在任何情況下都應當合理地行事，並且應該具備專業資格"],a:3,e:"根據《承保商專業守則》代表保險人\n的第三者（理賠師等），在任何情況\n下都應當合理地行事，並且應該具備\n專業資格。"},{c:"6.1.3",s:"以下哪項是保險投訴局的描述是正確的?\ni)保險投訴局成立目的是代表會員處理及支付索償\nii)會員是在香港從事個人保險業務的獲授權保險人\niii)涉及的投訴個案保單須屬個人保單\niv)投訴委員會的委員中有兩位來自保險業",o:["i,ii,iii(cid:9)","ii,iii,iv(cid:9)","iii, iv(cid:9)","i. ii, iii, iv"],a:1,e:"處理及支付索償不是保險投訴局的成\n立目的及職權範圍，選項(i)不正確"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有保證價值此事實\nii.投保人訴在核保結果為次標準風險\niii保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴於銷售的過程中沒\n有驗證其真實年齡\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單是屬於「抗通脹保\n單」",o:["i,ii,iii","i,iii,iv","iii,iv","i,ii,iii,iv"],a:1,e:"投訴個案與保險人的服務水平或核保\n決定無關"},{c:"6.1.3c",s:"以下哪項無權享有向保險投訴局提出爭議個案有關的投訴?",o:["提供保費融資的銀行保單持有人","保單共同所有人","保單受益人","合法索償人（如承讓人）"],a:0,e:"有權向保險投訴局的投訴人必須為保\n單持有人、保單受益人、受保人或合\n法索償人（如承讓人）"},{c:"6.2.1",s:"根據法定規定， 以下哪些需要至少一名負責人\n(i) 持牌保險機構\n(ii) 持牌保險代理\n(iii) 持牌保險代理機構\n(iv) 持牌保險經紀公司",o:["(i)及 (ii) 而已","(i)及 (iii) 而已","(ii)及 (iv) 而已","(iii)及 (iv) 而已"],a:3,e:"條例就受規管人士中的“負責人”，\n規定每個持牌保險代理機構和持牌保\n險經紀公司最少有一個負責人，而所\n有負責人必須是持牌業務代表（代理\n人）或持牌業務代表（經紀）"},{c:"6.2.4(c)",s:"評估商業實體有否識別出主要風險，及制訂策略以減低該等風險。涉及以下哪領域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:1,e:"就“適當人選”的斷定，詳細參閱研\n習資料手冊 6.2.4(c)"},{c:"6.2.4(c)",s:"曾在香港或其他地方被任何專業團體、行業公會或監管機構譴責、紀律處分或公開批評\n。涉及以下哪領域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:0,e:"就“適當人選”的斷定，詳細參閱研\n習資料手冊 6.2.4(c)"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項有關最低實繳股本的要求是正確的 ?\ni)專屬自保保險公司為港幣200萬元\nii)只從事相連長期保險業務的保險人為港幣1,000萬元\niii)同時從事一般業務及長期業務為港幣2,000萬元\niv)從事一般業務的保險人﹝包括法定保險業務﹞為港幣2,000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"四個最低實繳股本的要求描述都正確\n，詳細請參閱研習資料手冊 6.1.1b"},{c:"6.1.1g",s:"根據《保險業條例》及相關法例，以下哪項屬於保險業監管局的干預範圍：\ni) 限制保費收入\nii) 將保險人清盤\niii) 特定的精算調查\niv) 行使對保險人的管理權",o:["只有 i, ii","只有 ii, iii","只有 i, ii, iii","i, ii, iii, iv"],a:3,e:"四個描述都保險業監管局的干預權力\n，詳細請參閱研習資料手冊 6.1.1g"},{c:"6.1.3",s:"保險投訴局成員包括",o:["本港所有獲授權的保險人","本港獲授權一般業務的保險人而已","本港獲授權長期業務的保險人而已","本港所有承保個人壽險的獲授權保險人"],a:3,e:"所有在香港從事個人保險業務的獲授\n權保險人均必須繼續申請成為保險投\n訴局的會員"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項屬於利益?\ni. 客戶送贈的禮物\nii. 團隊隊員給予的佣金\niii. 百貨公司折扣禮劵\niv. 保險公司職位",o:["i","i,ii","i,ii,iv","以上各項皆是"],a:3,e:"「利益」的定義廣泛，包括金錢、饋\n贈、貸款、報酬、佣金、職位、任何\n職位、受僱工作或合約、服務、優待\n及任何有價證券或任何種類的其他財\n產或財產權益"},{c:"7.4.7b",s:"基於風險為本的關鍵原則是",o:["正確釐定保費","所有交易應用相同措施","根據風險級別分配資源","遵循標準慣例"],a:2,e:"基於風險為本的關鍵原則是根據風險\n級別分配資源"},{c:"7.2.1",s:"資料使用者透過制定服務合約，對資料處理者施加的責任是:\ni. 資料使用者有權審核及視察資料處理者如何處理和儲存個人資料\nii. 不再需要就受託目的處理有關個人資料時， 必須適時交還、銷毀或刪除有關資料\niii. 須採取的保安措施，以保障受託的個人資料，並要求資料處理者遵從保障資料原則\niv. 資料處理者必須居於香港",o:["i.ii","ii,iii,iv","iii,iv","i.ii.iii"],a:3,e:"資料處理者必須居於香港不是對資料\n處理者施加的責任"},{c:"7.5.2",s:"以下哪一項是廉政公署24小時舉報熱線？",o:["999","25 266 366","1823","24 266 366"],a:1,e:"以下哪一項是廉政公署24小時舉報熱\n線是25 266 366"},{c:"7.1.2",s:"以下哪一項就保險代理人的描述是不正確?",o:["因執行業務的疏忽行為所須承擔侵權法律責任的機會並非較高","因疏忽而對保單持有人提供不當的保險意見，須承擔侵權法律責任的機會並非較高","因疏忽而對保單持有人提供錯誤的保險意見，須承擔侵權法律責任的機會並非較高","保險代理人完全不用承擔任何侵權法律責任風險之中"],a:3,e:"一個保險代理人如果在為顧客承擔進\n行某項活動時，他因不當履行責任而\n被判須負法律責任的機會，相對經紀\n來說是比較小，但並不代表保險代理\n人完全不用承擔任何侵權法律責任風\n險之中"},{c:"7.2.1",s:"以下哪項對《個人資料(私隱)條例》範圍的陳述是正確的?：\ni. 自動化操作資料\nii.只適用於人手操作資料\niii. 只適用香港永久居民\niv. 它既涉及公營機構及私營機構",o:["i,ii,iii","i,iii,iv","i,iv","i,ii,iii,iv"],a:2,e:"個人資料是指自動化操作資料及涉及\n公營機構及私營機構"},{c:"7.2.1",s:"個人資料（私隱）條例》列明的六項保障資料原則， 以下哪一項就第 1 原\n則的描述正確?",o:["個人資料保留期限不應超過所需時間","個人資料應是準確的、最新的，其保留期限不應超過所需時間","採取適當的保安措施，以確保個人資料受保障而不受未獲准或意外的查閱","描繪如何合法和公平地收集個人資料"],a:3,e:"保障資料第1原則:收集個人資料的目\n的及方式，此原則描繪如何合法和公\n平地收集個人資料，及當資料使用者\n收集某人的個人資料時，必須向該資\n料當事人提供的訊息。"},{c:"7.5.1",s:"以下哪項不會觸犯《防止賄賂條例》第9條?",o:["持牌個人保險代理收受客戶提供的利益，以協助對方在購買人壽保險時隱瞞已存在的\n疾病投保","持牌業務代表（經紀）間中宴請客戶，以維持與客戶良好關係","持牌個人保險代理為取得公司客戶的員工團體保險合約，私下向公司客戶的人事部經\n理提供利益以換取簽訂員工團體保險合約","持牌業務代表(代理人)利用偽造的保險申請書來騙取持牌保險代理機構的佣金"],a:1,e:"款待（即當場享用之飲食）則不是利\n益。"},{c:"7.3.2",s:"以下哪項有關保險人對投保人給予性別差別對待是法律容許的，並不觸犯歧視條例？",o:["有關待遇是藉參照可合理依據的來源所得的精算數據","有關待遇是藉參照可合理依據的來源所得的精算數據或其他數據而給予的","就有關因素而言屬於合理","一切參照可合理依據的來源所得的精算數據"],a:1,e:"保險人對投保人給予性別差別對待是\n藉參照可合理依據的來源所得的精算\n數據或其他數據而給予的"},{c:"7.5",s:"以下哪項是貪污，必須避免觸犯？",o:["個人為謀取私利，從而引至社會利益受損","個人為謀取私利，濫用職權，從而引至他人利益受損","個人未經準許謀取私利，從而引至他人利益受損","個人挪用屬於他人的財產"],a:1,e:"貪污是指個人為謀取私利，濫用職權\n，從而引至他人利益受損"}],"paper1-2026-01":[{c:"1.1.1",s:"「一項潛在損失的不確定性」，這項定義最能恰當地描述?",o:["風險","一種可能出現的損失或收益","那些可保的風險而已","任何預期之外的事件， 不論結果怎樣"],a:0,e:"「一項潛在損失的不確定性」，這項定義最能恰當\n地描述風險一詞"},{c:"1.1.2(a)",s:"因心臟病產生的醫療開支最有可以被歸類為_____________。",o:["純粹風險","投機風險","特定風險","基本風險"],a:2,e:"特定風險能成的後果是相對有限的，只影響個人或\n為數較少的人。這類風險包括汽車意外、個人損傷\n等情況。"},{c:"1.1.2a",s:"從可保程度的角度來看，以下哪項關於純粹風險的描述是正確的?",o:["屬於必然可保","屬於必然不可保","比投機風險可保性為低","比投機風險可保性為高"],a:3,e:"商業保險人所承保的風險主要是特定風險及純粹風\n險，而投機風險一般是不可保的，因為要求他們以\n商業方式處理投機風險，在財務上是不可行的"},{c:"1.1.2a",s:"以下哪項或哪些是「純粹風險」的項目？",o:["賽馬賭博","開展一門生意的決定","已身故債務人無法償還的財務損失","沒有以上一項"],a:2,e:"債務人無法償還的財務損失，只有導致損失的可能\n性，是「純粹風險」"},{c:"1.1.2b",s:"以下哪些描述「基本風險」是正確的？",o:["它包括大規模洪災及地震這類自然災害","它只影響個別的投保人士","被視為社會並非個人的災害","A 和 C"],a:3,e:"基本風險發生的原因是超逾一個人或甚至一群人所\n能操控的，受影響的人不計其數。這類風險包括饑\n荒、戰爭、恐怖襲擊、大規模洪災和其他災害等。\n這些災害影響到整個社會或人類，而非其中的特定\n個體。只有選項A 和 C正確"},{c:"1.1.3",s:"進行能促進工業安全的活動是以下那項處理風險的方法？",o:["風險避免","損失防範","損失降低","風險融資"],a:1,e:"損失防範是降低已識別出來的可能損失的發生率，\n例如， 進行能促進工業安全的活動"},{c:"1.1.3",s:"如果風險被視為獨立的知識及研究學科，「風險管理」一詞會經常\n被提及或應用， 當保險人應用風險管理時",o:["與獨立的知識及研究學科中的意思無異","較為著重改善風險","指的是投機風險而非純風險","只涉及保費計算"],a:1,e:"當保險人談及「風險管理」時，其所指的可能是某\n些可以用來降低或改善所承保或獲邀承保「風險」\n的潛在損失的方法或手段"},{c:"1.1.3",s:"「安裝自動灑水系統」是以下那項處理風險的方法？",o:["風險避免","損失防範","損失降低","風險融資"],a:2,e:"「安裝自動灑水系統」屬於損失降低的處理風險的\n方法"},{c:"1.1.3",s:"作為風險管理在獨立的知識及研究範疇上，一般的理解為",o:["投資或投機風險所帶來的損失","保險人對受保風險損失上的改善","以識別、量化及處理作為進行的步驟","環繞著對保險合約的訂立及處理"],a:2,e:"風險管理可以解釋為管理學的一個分支，它要進行\n的步驟包括識別、量化及處理"},{c:"1.2",s:"以下哪項或哪幾項是保險的基本的好處？",o:["為保單持有人提供財務補償","增加就業機會","以人壽保險及年金作為儲蓄","金融服務的發展"],a:0,e:"保險的基本功能及好處是，在各種不同的投保事件\n中，當災害發生時，保險可以為被保險人提供財務\n補償。"},{c:"1.2",s:"保險對社會有益處嗎？",o:["是有的，通過保險人要求而進行的風險防範或風險降低措施(統稱\n風險控制)","是有的，保險是社會的一種手段","沒有，僅僅是私人的安排","沒有，除非是強制的"],a:0,e:"保險對社會有益處的，通過保險人要求而進行的風\n險防範或風險降低措施(統稱風險控制)"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni.保 險為本港提供就業機會\nii.保 險對受保損失的被保險人提供財務補償\niii.一 般保險的慣例下倡導防範損失的措施\niv.某 些業務可以涉及很高的純粹風險，或會令投資者卻步，除非他\n們可以投保潛在的財務損失",o:["i, ii, iii","i, ii","i,iii,iv","i, ii, iii, iv"],a:2,e:"保險對受保損失的被保險人提供財務補償可視為保\n險為香港帶來的基本功能/好處，,選項ii不正確"},{c:"1.3",s:"以下哪一項屬風險轉移措施?",o:["取消建築項目","為建築項目安排保險","加強工地的安全措施","禁止員工在工地食煙"],a:1,e:"購買保險是利用合約條件轉移對訂明損失的責任轉\n移到保險公司"},{c:"2.1",s:"以下哪項最恰當描述何謂「保險單」",o:["經蓋章後發出的重要文件","是屬於保險代理人與被保險人之間的合約","保險合約中的一種可見的表達","沒有這份文件，有關的合約便告取消"],a:2,e:"事實上，絕大部分的保險合約都屬於「簡單」合約\n。技術上，保險合約無需書面證明也能生效"},{c:"2.1.1",s:"合約可以界定為",o:["在法律上可強制執行的協議","兩人或多人之間的承諾","以書面形式表達的協議","任何兩方或多方的協議"],a:0,e:"合約可以界定為在法律上可強制執行的協議"},{c:"2.1.1",s:"合約是一項法律上可強制執行的協議",o:["然而這點是在它們以書面形式出現時才成立；","而且必須總是涉及重要的財務安排；","它們可能與重要的或較次要的事情有關；","然而只有以書面為證及在第三者見證下才成立。"],a:2,e:"合約所涉及的可以是瑣碎的事情，例如購買報章或\n乘電車，也可以是十分重要的事情，例如大型建築\n工程項目或僱傭合約"},{c:"2.1.2",s:"以下哪三項是有關僅以所涉及個人行為所設立的簡單合約的說明是\n不正確的？\ni) 在法律上，這種交易不是真正的合約\nii)這些是特殊情況，並因此稱為「蓋印的合約」\niii)如要有效，這種合約隨後須以書面表達\niv)儘管不是以口頭表達或書面方式，這種合約仍是有效的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii ,iii, iv"],a:0,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約。簡單來說，簡單合約的有效性\n並不取決於特殊的手續。選項i,ii,iii不正確"},{c:"2.1.2",s:"一項已經從有關人仕的行為推斷出來的合約肯定是",o:["簡單合約","特別合約","推斷合約","契據"],a:0,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約，答案A正確"},{c:"2.1.3",s:"以下哪項正確描述無效的合約？",o:["保險人可以取消合約","任何一方可以取消合約","合約在法律上不存在，完全無法律效力","保險人已拒絕賠償"],a:2,e:"無效的合約指所擬訂的合約在法律上不存在，完全\n無法律效力"},{c:"2.1.3",s:"以下哪項可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含義完全相同","受屈的一方可於合理時間內把合約視為無效的決定","只有被保險人才能把保單視作可使無效(即可予以取消)"],a:2,e:"可使無效的合約是項明顯有法律效力的合約，其法\n律效力一直維持下去，除非及直至有受屈的一方把\n合約視為自訂立時起即屬無效，但須在一段合理時\n間內進行"},{c:"2.1.3",s:"一般協議有別於合約的原因，以下有哪些或哪項的描述是正確的",o:["合約必須以書面形式訂立","合約必須有兩位以上的見證人","合約包含多項法律準則","以上所有各項"],a:2,e:"合約在法律上可強制執行的協議。協議的種類繁多\n，但不是所有的協議都有法律效力，協定涉及的內\n容必須是合法的。只有答案C正確"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構成\n要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就沒有合約。"},{c:"2.1.3(b)",s:"在反要約的過程中，下列哪項是不正確的？",o:["原本的要約人成為受要約人","原本的受要約人成為要約人","原本的要約內容立刻被終止並撤銷","若反要約的內容不被接納，原本的要約內容可再次有效"],a:3,e:"如果受要約人有意更改合約條件，這種意向一經傳\n達便構成了反要約，後果是原要約內容失效"},{c:"2.1.3(c)",s:"在一個保險合約中，被保險人所付出的代價是",o:["填受投保書","始初要約，其後續保","繳交保費","以上各項皆是"],a:2,e:"在一個保險合約中，被保險人所付出的代價是繳交\n保費"},{c:"2.1.3(c)",s:"安琪在登機前購買一份旅遊保險，保險人容許她在旅程後繳付保險\n費。安琪不幸在旅程中斷了一條腿，保險人拒絕賠付安琪有關的醫\n療費用，請問保險人有權這樣做嗎？",o:["沒有。根據承保商專業守則，保險人須就投保人合理的期望賠","沒有。一張旅遊保險合約已經生效","有。保險人若賠付只出於同情","有。安琪沒有交保費"],a:1,e:"如果所保事故在支付已承諾的保費以前已經發生，\n被保險人仍然享有索償權，而保險人則另外有權追\n討未繳清的保費，答案B正確"},{c:"2.1.3(c)",s:"在保險上，保險人的代價是：\ni.被 保險人向保險人支付保費的承諾\nii.保 險人依照保單條款的規定給付賠償\niii.保 險人依照保單條款的規定收取款項\niv.保 險人依照保單條款的規定給予補償的承諾",o:["ii,iv","只有ii","只有i","只有iii"],a:0,e:"在保險上，代價就是：保險人依照保單條款的規定\n付款或給予補償的承諾。"},{c:"2.2.2",s:"代理關係可以透過以下哪些途徑產生?\ni.明 示協議\nii.隱 含協議\niii.追 認\niv.代 理人出錯",o:["i,ii","i,ii,iii","iii,iv","以上皆是"],a:1,e:"代理關係可以透過明示，隱含或追認方式產生"},{c:"2.2.3",s:"有一日某人在街上發現了一條昂貴的純種狗，他很努力地尋找失主\n。幾天後，他尋找到失主，他在照顧這狗隻期間的狗糧費用、獸醫\n費用，涉及相當數量的金錢，他爭辯有權向失主取回這些相關費用\n。因為他在照顧狗隻期間可被稱為",o:["追認代理人","必要代理人","明示代理人","不容反悔代理人"],a:1,e:"如某人受着迫切的危害而不存在向他通報的機會，\n一名現有代理人在這個危急的情況下必地為該人採\n取行動的話，可以說該代理人持有必要權限作出該\n等行為，並透過該等行為成為必要代理人。"},{c:"2.2.3(c)",s:"第三者根據一名〈假定）委託人的行為，覺得一名〈假定）代理人\n為委託人的代理〈其實並沒有授權），這類代理關係稱為",o:["明示代理","不容反悔代理","必要代理","追索代理"],a:1,e:"不容反悔的代理權是當一名據稱代理人，在完全沒\n被授權，但卻被容許看似獲授權時應用的。"},{c:"2.2.6",s:"以下哪項或哪些有關由於精神錯亂而導致代理人關係的終止的描述\n是正確的？",o:["只有代理人可終止而不能是委托人","只有委托人一方可終止而不能是代理人","代理人和委托人（自然人）均可終止","代理人和委托人均沒有權力終止"],a:2,e:"如果委託人和代理人的任何一方因精神錯亂不再能\n夠履行協議，則協議會自動終結"},{c:"3.1",s:"彌償及可保權益這兩項保險原則",o:["在財務利益方面存在著密切關聯","完全沒有共通之處","各自有完全相反的用意","尋求確立損失的有效原因"],a:0,e:"「權益」一詞是指一種與某物件或與某人之間的財\n務關係。"},{c:"3.1.1",s:"一種作為保險標的，屬於可以受保的事物，是屬於產生下列哪項原\n則的準則?",o:["彌償","可保權益","代位","最高誠信的原則"],a:1,e:"可保權益的產生，必須先有可被保的人身、財產、\n法律責任或法律權利"},{c:"3.1.2",s:"以下哪項有關沒有可保權益的說明是正確?",o:["該份保險屬於無效","在任何情況下，不能退回已繳的保費","一般情況下，在不知道保險無效的情況下繼續支付的保費是可退\n回的","A 和 C 都正確"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效，一般\n情況下，在不知道保險無效的情況下繼續支付的保\n費是可退回的，A 和 C 都正確"},{c:"3.1.3",s:"下列哪項或哪些例子符合可保權益所要求的條件？",o:["一名盜賊希望替自己偷竊得來的財物投買保險","一名男子希望替自己擁有的汽車投買保險","一名男子為了自己的利益，希望替他那位粗心大意的朋友的手錶\n投買保險","上述所有各項"],a:1,e:"財產保險明顯的例子是在絕對擁有權的情況下產生\n可保權益 。答案B正確"},{c:"3.1.3",s:"可保權益除必須先有可被保的人身、財産、責任或法律權利外，某\n人身等必須是該保險的標的，第二個條件是",o:["財物必須有明確的價值","保險標的必須是或屬於受保人的","投保人與保險標的必須具有法律認可的關係","以上各項都不是"],a:2,e:"可保權益除必須先有可被保的人身、財産、責任或\n法律權利外，某人身等必須是該保險的標的，第二\n個條件是，投保人與保險標的必須具有法律認可的\n關係"},{c:"3.1.3",s:"以下哪項是債權人對債務人的生命購買保險，具有可保權益必須符\n合的必要條件?",o:["財務關係一直存在","僅適用於抵押一直存在","沒有任何必要條件","償還債務的金額"],a:0,e:"在法律上假定有可保權益的存在，須提出財務關係\n的證據"},{c:"3.1.4",s:"構成財產保險可保權益的是",o:["在擁有人同意下管有該項財產","需對保管的財產的損失負責","絕對擁有該項財產","以上各項皆是"],a:3,e:"構成財產保險可保權益的條件，可以是持有次於絕\n對擁有權的權利，分別為遺產、信託財產、按揭財\n產投保。"},{c:"3.1.4",s:"以下哪項可保權益的陳述正確?\ni.每人對自己的肢體都有保險利益\nii.承按人不可以對按揭財產投保\niii.又可稱為保險標的\niv.保險人與被保險人之間法律認可的關係",o:["i","i,ii,iii","ii,iv","i, ii,iv"],a:0,e:"可保權益是投保人與保險標的之間必須存在被法律\n認可的關係，承按人是持有次於絕對擁有權的權利\n，可以對按揭財產投保，只有選項(i)是正確"},{c:"3.1.4(b)",s:"阿倫給予他的朋友玫瑰一個他所擁有的單位免費住兩個月，請問玫\n瑰有權為該單位購買保險?理由何在?",o:["有，合法地佔有某單位的任何人有權以所有人的代理人的身份就\n該單位購買保險","沒有，因為她沒有付出代價","有，她是以單位託管人的身份人對該單位具有權益的","沒有，因為她並非擁有該單位"],a:2,e:"受託保管人持有次於絕對擁有權，在得到某貨品的\n擁有人或其代理人的同意下，管有該貨品的人可以\n對所保管的貨品進行投保。"},{c:"3.1.5",s:"以下哪項或哪些情況出現之損失或索償，在沒有構成可保權益下，\n都不會形成拒絕損失索償的理由",o:["人壽保險(被保險人為前配偶，現已離婚)","火險，由「前承按人」購買(欠款已於火災前清還)","車險(汽車於意外摧毀前己賣出)","以上各項"],a:0,e:"在人壽保險中，可保權益只須在保單起保時存在。\n提出索賠時缺乏可保權益不會喪失索取死亡利益的\n資格"},{c:"3.1.6",s:"以下哪項對轉讓的陳述是正確的?\ni)人壽保險可以不經保險人同意自由轉讓\nii)海上貨物保險可以不經保險人同意自由轉讓\niii)商業「全險」保單不可以沒有保險人同意便轉讓\niv)人壽保險不可以沒有保險人同意便轉讓",o:["i，ii，iii","i，ii，iv","i，iii，iv","ii，iii，iv"],a:0,e:"人壽保險可以沒有保險人同意便轉讓，描述iv不正\n確"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["轉讓人不會把保險合約中的責任轉移到承讓人的身上","承讓人將取得收款人的權利，而非訴訟權","承讓人承讓人承諾支付未來的保費","承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費"],a:0,e:"保單「轉讓」通常是指權利的轉移。轉讓是不會讓\n轉讓人在保險合約的責任轉移到承讓人的身上的"},{c:"3.2.1",s:"保險合約的契約各方______",o:["必須披露所有已知的重要事實","無需披露所有已知的重要事實","確保將要提供給對方的資料在實質上真實","確保向合約另一方披露所有重要事實，無論保單上是否有相關的\n問題"],a:3,e:"最高誠信的原則意思是，不論另一方是否要求有關\n的資料，各方必須向另一方披露所有重要事實，即\n使投保單上並沒有相關的問題例如，投保人仍須向\n保險人披露"},{c:"3.2.1",s:"有別於最高誠信，一般誠信要求有關各方",o:["保證他們作出的每項陳述均是百分百真實","不論有否被問及也要披露所有重要事實","擔保他們沒有遺漏任何對有關合約的重要事實","忠誠及確保將要提供給對方的資料在實質上真實"],a:3,e:"在普通法上，一般誠信要求有關各方必須本着誠實\n的態度行事，所提供的資訊必須是實質上真實的"},{c:"3.2.2",s:"以下哪項或哪些有關最高誠信和保險在香港的情況是不正確的？",o:["最高誠信只要求就所發問的問題提供合理的答案","最高誠信只在保單條款有規定的情況下才適用","所有保單內包含某些條款，更改最高誠信責任","以上所有各項都不正確"],a:3,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。保險人有時把普通法中的最高\n誠信責任加以延伸，要求投保人聲明或保證，無論\n是否與「重要」事件有關連，所有經披露的資料都\n必須完全真實的。例如，即使投保單上並沒有相關\n的問題，火險投保人仍須向保險人披露有關損失的\n紀錄。以上所有各項都不正確"},{c:"3.2.4",s:"如果保險人要求保證所有披露資料，不論重要與否，均需完全真實\n，這表示",o:["違反法例並不能強制執行","延伸普通法中的最高誠信的要求","這合約受制於而非最高誠信","這合約受制於最高誠信"],a:1,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。"},{c:"3.2.4",s:"根據普通法，投保人需要遵守最高誠信責任的期限",o:["直至索償為止","直至該合約生效為止","涉及整段合約生效時","僅至簽署投保書時為止"],a:1,e:"在普通法中，於保險合約訂立後，投保人才得知的\n重要事實，不必予以披露。"},{c:"3.2.6",s:"如果投保人違反最高誠信",o:["保險人可不作追究","除非牽涉詐騙成份的情況下，保險人才可得到補救","除非牽涉詐騙或疏忽成份的情況下，保險人才可得到補救","保險保單會自動取消"],a:0,e:"只撤銷合約的一部分，並不屬於可以執行的投保人\n違反最高誠信補救措施，可行的是對違反不予追究"},{c:"3.3.2",s:'以下哪項屬於近因中被視為"危險"',o:["合約責任","金錢","職員盜竊","汽車損壞"],a:2,e:"危險，即是造成有關損失的成因，職員盜竊是造成\n財務有關損失的成因。"},{c:"3.3.3",s:"一個單位購買火險後，鄰居發生火警，在必要情況下，消防員需要\n破壞此單位某些設施進入鄰居救火，有關這些設施的損失",o:["因為受保危險引致不保危險，故此可得到賠償","因為不保危險引致受保危險，故此得不到賠償","屬於不保危險，故此得不到賠償","屬於受保危險，故此得到賠償"],a:0,e:"如果涉及一項以上的危險，由受保危險直接引發的\n不保危險 ，所引致的損失可獲賠償保險金"},{c:"3.3.4",s:"保險單",o:["從不更改近因原則","通常排除應用近因原則","可能包含更改應用近因原則的短句","符合以上各項陳述"],a:2,e:"很通常保險人借助某些保單措詞，更改近因法則的\n應用"},{c:"3.4.2",s:"一男子在人身意外保單和汽車意外保單中投保了意外死亡利益。如\n他在駕駛自己的汽車發生了意外而死亡",o:["每份保單必須賠償死亡利益全數","僅僅首先生效的保單必須支付死亡利益","僅僅提供較大保額的保單必須賠償","既然死亡是由汽車意願導致，僅僅汽車保單須賠付"],a:0,e:"壽險及個人意外保險是提供利益的保單，而不是提\n供彌償的保單。因人命的損失不可能以財務方法精\n確計算，壽險及個人意外保險能辦到的僅是按照死\n亡或損傷訂明的數額支付利益，答案A正確"},{c:"3.4.2",s:"下列哪項最能解釋彌償？",o:["補償","精確賠償","保單的實際保額","保險標的實際價值"],a:1,e:"彌償是指對損失作出既不多也不少的精確財務補償"},{c:"3.4.4",s:"更換一件受摧毀或失掉的受保物件時，可以作為一種提供彌償的形\n式，這種安排適合以下哪項情況?",o:["每類型的索償","僅限於汽車保險","完全沒有或只有少許折舊的物件","只有在盜竊是損失的近因時"],a:2,e:"就全新的、不受或幾乎不受折舊影響的物件而言，\n給被保險人一件替換物件可以是一種非常合適的彌\n償方法"},{c:"3.4.5",s:"損餘在保險公司運作上，通常",o:["保險人是用作量度損失的準確金額時特別留下部份","與海上所指的救援費用同屬同一意思","只限汽車殘駭上的應用","無論任何情況下保險人只付一半賠償"],a:0,e:"保險標的在受損後留下剩餘部分，例如被火損壞的\n存貨 、 車輛的殘骸等 。 這些剩餘部分稱為損餘"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約定\n價值$1,000,000」，意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方式提供保險保\n障的，約定價值一律被視為損失時的實質價值"},{c:"3.5.1",s:'假設銀行借錢給"A"購買物業，不尋常地，該銀行對該物業的權益購\n買保險保障，而"A"亦按照其意志投買保險，如果投保損失發生',o:["按照分擔原則，兩名保險人各自賠償50%","分擔原則不適用，因不是保險相同的權益","A的保單將作出賠償，因他是物業的真正擁有者","銀行的保單將作出賠償，因為借貸協定給它優先權"],a:1,e:"分擔原則不適用，因業主A與銀行所購買的保險所保\n障的權益不相同"},{c:"3.6.2",s:"一名僱員補償保險人巳向受害僱員作出賠償，在一項條款下可向疏\n忽的第三者索償，這是基於",o:["在侵權法上產生的代位權","在合約上產生的代位權","在法規下產生的代位權","在損餘中產生的代位權"],a:2,e:"一名僱員補償保險人巳向受害僱員作出賠償，在一\n項條款下可向疏忽的第三者索償，這是基於在法規\n下產生的代位權"},{c:"3.6.4",s:"在委付及給予彌償後，保險人應如何處理售賣損餘中得到的利潤？",o:["將利潤歸還保單持有人","保險人和保單持有人五五分帳","利益歸保險人","保險人不可售賣損餘"],a:2,e:"在被保險人將投保財產委付給保險人之後，附於這\n財產的一切權利都屬於保險人，包括「從中牟利」\n的權利"},{c:"4.1",s:"以下哪項有關全新產品「具有競爭力的壽命」的描述是正確的？",o:["非常短，通常只有幾個星期或幾個月","大約一年","在競爭對手把焦點集中在新的保險產品之前， 至少兩年時間","非常之長"],a:0,e:"全新產品「具有競爭力的壽命」非常短，通常只有\n幾個星期或幾個月"},{c:"4.1",s:"市場上以「組合」形式推出的產品很多，這是屬於產品發展的什麼\n過程?",o:["個別產品的開發","產品組合的開發","產品的研究","獨立產品的開發"],a:1,e:"產品組合的開發以「組合」形式出現的產品，其中\n尤以大型的客戶為對象"},{c:"4.1",s:"產品開發是保險公司的重要功能，原因是",o:["產品開發有助於確保公司的財務穩定","由於信息技術出現，保險產品很快就過時了","客戶對保險的需求不斷改變","新產品往往被競爭對手完全複製，因保險產品並沒擁有知識產權"],a:3,e:"個別產品的開發是一個延續不停的過程。由於競爭\n對手樂於倣效及抄襲別人的新產品，全新產品具有\n競爭力的壽命極為短暫，答案D正確"},{c:"4.2",s:"客戶服務是保險公司的主要功能，建立公司形象屬於哪種職責範圍?",o:["聯絡","公共關係","文件的提供","投訴"],a:1,e:"公共關係屬於市場行銷人員的職責範圍，然而接待\n客戶的方式，對於公司在大眾心目中的地位，起着\n深遠的影響。"},{c:"4.5",s:"壽險保單核保工作很重要，以下哪項原因是正確的",o:["保險標的是人類","保險人不能單方取消保單","壽險保單的保額通常巨大","壽險保單牽涉的佣金較大"],a:1,e:"壽險保單核保工作很重要，原因是保險人不能單方\n取消保單"},{c:"4.5",s:"人壽保險核保部門眼中的「目標風險」，較可能屬於以下哪類風險\n？",o:["極高保額的風險","保險人尤其願意承保的風險","保險人尤不願意承保的風險","有關保險代理人可得到較高佣金率的風險"],a:1,e:"目標風險在人壽保險中可以解釋為極為合意的業務\n類型"},{c:"4.5",s:"火災保險中，「目標風險」一詞指",o:["沒有什麼價值的投保物件","一項大的，很高的風險","一項普遍的風險","很低的保險費率"],a:1,e:"火災保險中，「目標風險」一詞指一項大的，很高\n的風險"},{c:"4.6",s:"蘇先生致電保險公司投保一份火險，而保險公司承諾可在事後發出\n保單，但蘇先生未繳付保單的保費，但1小時後貨物被火災損毀，請\n問這份保單有效嗎？",o:["否，要約沒有存在","否，保單還沒出","是，代理人在對話中一承認保單，保單已經有效","一份有追溯性的保單合約，在付保費時生效"],a:2,e:"人壽保險以外的其他類型的業務，合約可於還未收\n到保費時便開始生效，答案C正確"},{c:"4.7",s:"處理人壽及非人壽索償時有的共同特性是數額的問題及",o:["如何處理彌償的問題","分擔的問題","責任的問題","代位權的問題"],a:2,e:"處理人壽及非人壽索償時有的共同特性是數額的問\n題及責任的問題"},{c:"5.1.1",s:"以下哪項是保險法定類別中長期保險業務所包括的保障",o:["疾病","擔保","資本贖回","財產損壞"],a:2,e:"資本贖回屬於長期保險的業務範圍"},{c:"5.1.2",s:"根據保險的實務類別，保險分類有四個類別，包括人壽，水險，火\n災及意外，這屬於以下哪項的分類？",o:["法定式","功能式","部門式","業務式"],a:2,e:"保險分類以人壽，水險，火災及意外分類，這屬於\n英國部門式分類的制度"},{c:"5.1.4",s:"對於特定的保險公司，「分出再保險」與「分入再保險」的分别是",o:["分入再保險只涉及香港的再保險人","分出再保險只涉及非香港的再保險人","分入再保險以該公司作為再保險人","分出再保險以該公司作為再保險人"],a:2,e:"對於特定的保險公司，「分出再保險」與「分入再\n保險」的分别是分入再保險以該公司作為再保險人\n，分出再保險是保險人向其他保險人／再保險人購\n買保險"},{c:"5.5.1",s:"以下哪項有關保險業聯會的正確描述？",o:["香港保險業聯會的成立的目的是保障及提升保險人及保險代理人\n的利益","香港保險業聯會的成立的目的是保障及提升保險人及再保險人的\n利益","香港保險業聯會是由保險代理登記委員會成立的","香港保險業聯會的成立目的是向香港及世界各地宣傳保險訊息"],a:1,e:"香港保險業聯會的成立的目的是保障及提升保險人\n及再保險人的利益"},{c:"5.5.1(c)",s:"保監局於2019年從3個自律規管機構接管了",o:["保險監理處的功能","保險人的監管","保險中介人的規管","香港保險監督聯會的功能"],a:2,e:"保監局於2019年從3個自律規管機構接管保險中介人\n的規管"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，保險業監管局成立的政策\n目標是甚麽？",o:["確保保險業的規管架構與時並進，促使保險業的高速增長","確保保險業的規管架構與時並進，促進保險業的穩健發展","建立一個保險中介人的法定發牌制度，補充自律規管制度","以上皆不是"],a:1,e:"保監局有下列任務(i)透過發牌制度，規管保險中介\n人的操守(ii)提高保單持有人和潛在保單持有人對\n保險產品和保險業的了解(iii)制訂規管保險業的有\n效策略、促進保險業市場的可持續發展，並提升保\n險業界在環球保險業市場的競力(iv)就影響保險業\n的事宜，進行研究；及(v)就保險業採取適當措施，\n以協助財政司司長維持香港金融穩定。 答案B正確"},{c:"6.1",s:"以下哪一項就《保險業條例》的描述是正確的?",o:["《保險業條例》原稱《保險公司規管條例》","《保險業條例》涵蓋對保險人及保險中介人的監察和規管","《保險業條例》於2015年經修訂後由保險業監理處執行","《保險業條例》2017年6生效後，已重新命名為《保險公司條例》"],a:1,e:"《保險業條例》涵蓋對保險人及保險中介人的監察\n和規管，其他選項都不屬《保險業條例》的正確描\n述"},{c:"6.1.1a",s:"在香港或從香港經營保險業務以前，任何「人」必先_____________\n___",o:["具備2000萬港元的實收資本","應對有關的保險中介人資格考試","獲得保險業監管局的授權","成為保險業聯會的會員"],a:2,e:"在香港或從香港經營保險業務以前，任何「人」必\n先獲得保險業監管局的授權"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是正確的？",o:["實繳股本是保險人獲得授權其中一項最低要求","實繳股本的管控人必須符合適當人選要求","同時經營一般及長期業務實繳股本要求最高為2000萬港元","實繳股本可按保費收入計算"],a:0,e:"不同的規定實繳股本數額是保險人獲得授權其中一\n項最低要求"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是不正確的？",o:["專屬自保保險人為3000萬港元","法定或強制性的一般保險業務一般業務為1000萬港元","同時經營一般及長期業務為2000萬港元","只經營長期業務為1000萬港元"],a:0,e:"專屬自保保險人為200萬港元"},{c:"6.1.1e",s:"《與有關公司安排再保險的指引》很重要，因為",o:["該指引令核數師很頭痛","高級管理人員會疏於管理","當再保險人與某保險人有關連的時候，姊妹公司 會私相授授","當再保險人與某保險人有關連的時候，相關公司會對其再保險安\n排應行的審慎監控可能會流於鬆懈"],a:3,e:"《與有關公司安排再保險的指引》原因是：當再保\n險人與某保險人有關連的時候，保險人對其再保險\n安排應行使的審慎監控可能會流於鬆懈；如果容許\n鬆懈地監管這情況，會對投保公眾帶來風險。"},{c:"6.1.1f",s:"在某種情況下，保險業監管局可以披露某些財務和統計資料，但不\n能披露任何有關個別保險人的事務的資料，除非",o:["涉嫌詐騙","指明的法律程序","於投保人去世後","當保單持有人宣佈破產"],a:1,e:"保險業監管局可以披露某些財務和統計資料，但不\n能披露任何有關個別保險人的事務的資料，除非指\n明的法律程序下"},{c:"6.1.1f",s:"《保險業條例》列明經營一般業務的保險人必須就其從香港保險業\n務所產生的負債在香港維持資產，用來釐定這一數據的方法之一，\n是計算有關數額與以下之總和",o:["毛負債額（不扣除再保險部分）的80%","净負債額（扣除不保部分）的80%","净負債額（扣除再保險部分及可爭議負債）的80%","净負債額（扣除再保險部分）的80%"],a:3,e:"經營一般業務的保險人，必須就其從香港保險業務\n所產生的負債在香港維持資產，所需數額以訂明的\n兩種匯算方法之一計算，其一所要求的數額不能少\n於兩項的總和:(i)淨負債額（即已經扣除再保險所\n保的那部分）的百分之八十 ；及(ii) 有關數額。"},{c:"6.1.1f(d)",s:"根據《保險業條例》的要求，所有保險人每年向保監局呈交",o:["資產負債表","一般業務報表","財務報表","以上各項皆是"],a:2,e:"根據《保險業條例》的要求，所有保險人每年須向\n保監局呈交其財務報表"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["由香港保險業聯會執行","列明保險中介人八大操守原則","保險人的資本規定","以上皆是"],a:0,e:"承保商專業守則由香港保險業聯會執行，列明保險\n代理管理的優良保險做法"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求\n描述是正確的?",o:["代表保險人的理賠師須具備一定程度的經驗","代表保險人的理賠師須具備一定程度的經驗，以及相關專業資格","不得委派理賠師以外第三者處理索償","代表保險人的理賠師應該具備的專業資格"],a:3,e:"根據《承保商專業守則》代表保險人的第三者（理\n賠師等），在任何情況下都應當合理地行事，並且\n應該具備專業資格。"},{c:"6.1.3a",s:"委派保險索償投訴委員會的是",o:["保險業監管局","政府","保險業聯會","保險投訴局"],a:3,e:"委派保險索償投訴委員會的是保險投訴局"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有\n保證價值此事實","保險人未有及時將續保條款及時通知保單持有人的投訴","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗證其真實年齡","年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，\n導致損失了有關的保單利息"],a:1,e:"與服務水平有關的投訴個案，不屬於保險投訴局的\n職務範圍"},{c:"6.2.1",s:"凡有意在經營業務或受僱過程中或為報酬而進行“受規管活動”必\n須首先獲得保監局發出的牌照，以下哪一項不屬於五類持牌人?",o:["持牌個人保險代理","持牌保險經紀公司","持牌業務代表（代理人 ）","持牌保險業務機構"],a:3,e:"持牌保險業務機構不屬於五類持牌人"},{c:"6.2.2",s:"《保險業條例》對獲授權保險人就其委任的保險代理人(受委人)，\n就其向該客戶就發出保險合約或關乎該合約的相關保險業務有所往\n來的作為須負上 __________。",o:["罰款","轉承責任","最高誠信","牌照"],a:1,e:"《保險業條例》對獲授權保險人就其委任的保險代\n理人(受委人)，就其向該客戶就發出保險合約或關\n乎該合約的相關保險業務有所往來的作為須負上轉\n承責任"},{c:"6.2.4(iv)",s:"以下哪項是持牌保險經紀公司的發牌條件?",o:["最少獲得1名獲授權的保險人委任","最少獲得4名獲授權的保險人委任","申請人並非持有保險代理機構牌照","申請人持有保險代理機構牌照"],a:2,e:"持牌保險經紀公司的其中一個發牌條件是申請人並\n非持有保險代理機構牌照"},{c:"6.2.5",s:"根據《保險業條例》，以下哪些是對保險代理許可的行動?\ni) 發出譴責\nii) 暫停該代理人的委任\niii)終止該代理人的委任\niv)命令該人繳付罰款",o:["i ，ii","i ，ii，iii","iii，iv","i ，ii，iii，iv"],a:3,e:"以下各項皆是根據《保險業條例》，可對保險代理\n許可的行動"},{c:"7.2.1",s:"根據《個人資料（私隱）條例》保障資料第1原則，若資料使用者收\n集個人資料時",o:["個人資料應是準確的,最新的，其保留期限不應超過所需時間","合法和公平地收集個人資料","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資\n料處理者的個人資料的保存時間超過處理該資料所需的時間","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資\n料處理者的個人資料的保存時間超過30天"],a:1,e:"保障資料原則第1原則:收集個人料的目的及方式，\n此原則描繪如何合法和公平地收集個人資料"},{c:"7.2.2",s:"在《個人資料（私隱）條例》涉及範圍中，就保險人所擁有保單持\n有者的資料使用上，以下哪項是合法的？",o:["向保單持有人的親屬透露其壽險保單資料","向保單持有人發出續保通知","向著名的報紙出賣被保險人資料","以上所有各項"],a:1,e:"向保單持有人發出續保通知在《個人資料（私隱）\n條例》涉及範圍中是容許的"},{c:"7.3.2",s:"以下哪三項較為被保險人視為「公平歧視」？\ni) 為女性提供較低的年金\nii) 向男性收取較高的人壽保險保費\niii)向女性收取較高的汽車保險保費\niv)在提供人身意外保險時向殘疾人仕收取較高保費",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"女性收取較高的汽車保險保費不屬保險人的「公平\n歧視」，只有選項i,ii,iv正確"},{c:"7.5",s:"以下哪項是貪污，必須避免觸犯？",o:["個人為謀取私利，從而引至社會利益受損","個人為謀取私利，濫用職權，從而引至他人利益受損","個人未經準許謀取私利，從而引至他人利益受損","個人挪用屬於他人的財產"],a:1,e:"貪污是指個人為謀取私利，濫用職權，從而引至他\n人利益受損"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項並非條例所指的利益？",o:["款待","借貸","職位","服務"],a:0,e:"款待不屬利益"},{c:"7.5",s:"根據《防止賄賂條例》，利益的限額是",o:["100元或以上","500元或以上","1000元或以上","沒設最低金額"],a:3,e:"根據《防止賄賂條例》，利益的限額是沒設最低金\n額"},{c:"7.5.1",s:"以下哪項觸犯了《防止賄賂條例》第9(三)條?",o:["一名持牌個人保險代理人意圖利用偽造的保險申請書來騙取保險\n公司的佣金","保險公司的採購人員提交虛假文件，令採購合約判給與該名採購\n人員有關連的公司","一名持牌業務代表(代理人)偽造培訓紀錄以騙取培訓津貼","以上各項皆是"],a:3,e:"以上各項皆是觸犯了《防止賄賂條例》第9(三)條的\n例子"},{c:"7.5.1(b)(iii)&(iv)",s:"以下哪項不能作為貪污的辯解理由?\ni 收賄是行業或事業的習慣\nii受賄者和行賄者已達成口頭協議，但受賄者無意圖辦理行賄者要\n求的事\niii 透過第三者收賄\niv 貪污目的未達",o:["i & iii","ii & iv","ii, iii & iv","i, ii, iii & iv"],a:3,e:"以上各項都不能作為貪污的辯解理由"},{c:"7.6.1",s:"犯罪者不是以主犯的身份犯罪就是以那麼的身份犯罪?",o:["次犯","從犯","助犯","刑事代替犯"],a:1,e:"犯罪者不是以主犯的身份就是以從犯的身份參與犯\n罪。一項刑事罪的從犯是指一名協助、教唆、慫使\n或促致犯該罪行的人"},{c:"7.6.2(b)",s:"就保險詐騙性索償，保險中介人有以下哪項責任?\ni.拒 絕索償\nii.執 行相關法律\niii.舉 報可疑事件或提供證據\niv.協 助保險人揭露詐騙行為",o:["i,iii,iv","i,ii,iv","iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是就保險詐騙性索償，保險中介人須要\n負上責任"}],"paper1-2026-02":[{c:"1.1.1",s:"「風險」的定義是",o:["保險人有可能變成資不抵債的危險性","潛在利益有關的不確定性","對可能發生的風險有保護措施","潛在損失有關的不確定性"],a:3,e:"「風險」帶有損失或危險的意思，可以把它定義\n為「與潛在損失有關的不確定性」"},{c:"1.1.1",s:"「風險」的定義是",o:["不同人士使用「風險」一詞可能具有不同的意思","任何情況下定義為「與潛在損失有關的不確定性」","一半情況下定義為「與潛在損失有關的不確定性」","以上所有皆非"],a:0,e:"不同人士使用「風險」一詞可能具有不同的意思\n，視乎使用時的場合，「風險管理」一詞具不同\n的含義，在銀行業及其他非保險金融服務領域，\n它大概是指對投資及其他投機風險的管理，就保\n險公司而言，這可能僅指對純粹風險的管理，甚\n至可把範圍進一步收窄至只對可保風險的管理"},{c:"1.1.2(b)",s:"盜竊最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:2,e:"盜竊會有金錢上損失，純粹風險只具有財務損失\n的可能性"},{c:"1.1.2a",s:"從可保程度的角度來看，純粹風險屬於",o:["永不可保的","必然可保的","可保程度可能低於投機風險","可保程度可能高於投機風險"],a:3,e:"商業保險人所保的風險主要是純粹風險及特定風\n險，投機風險及基本風險是較不可保。"},{c:"1.1.2b",s:"以下哪項正確地描述「基本風險」？",o:["它相當可能涉及損失,不會出現收益","它只影響個人而非整體社會","根據定義，它的影響並非災難性的","它相當可能是不可保的"],a:3,e:"商業保險人所保的風險主要是特定風險及純粹風\n險，基本風險一般是不可保的，因為要求他們以\n商業方式處理此等風險，在財務上是不可行的"},{c:"1.1.3",s:"以下哪項陳述是正確的?",o:["風險管理是工業科學的一項分科","風險管理是僅僅保險其中的一環","風險管理是與保險完全相同的學科","保險是風險管理的工具"],a:3,e:"保險只是處理風險其中一種工具或措施"},{c:"1.1.3",s:"以下哪項有關「風險管理」一詞的描述是正確的",o:["只適用於保險公司","保險公司不大可能收窄此詞之應用至純風險","它指三步驟:風險識別˴風險免除及風險融資","它包含二個步驟: 風險識別及風險量化"],a:3,e:"一個獨立的知識與研究的領域，風險管理可以解\n釋為管理學的一個分支，它要進行的步驟包括識\n別；量化，及應對"},{c:"1.1.3",s:"作為一門獨立的學科及研究的範圍，風險管理",o:["只處理純粹風險","只處理投機風險","可以處理純粹風險或投機風險","既非處理純粹風險也非投機風險"],a:2,e:"作為一門獨立的學科及研究的範圍，風險管理應\n對某家機構構成威脅的風險，不論是純粹風險還\n是投機風險"},{c:"1.2",s:"以下哪項是保險的基本功能／好處而非輔助功能？\ni)把個人的潛在財務損失轉移給保險人\nii)損失的控制/防範\niii)儲蓄／投資\niv)使商家倖免由於嚴重的火災、沉重的法律責任等情況而造成的\n巨大損失",o:["i, ii","ii, iii","i, iv","iii, iv"],a:2,e:"風險轉移，以及為損失作財務上的補償是保險的\n基本功能"},{c:"1.2",s:"以下哪項或哪幾項是保險的基本的好處？",o:["為保單持有人提供財務補償","增加就業機會","以人壽保險及年金作為儲蓄","金融服務的發展"],a:0,e:"保險的基本功能及好處是，在各種不同的投保事\n件中，當災害發生時，保險可以為被保險人提供\n財務補償。"},{c:"1.2",s:"以下哪項是保險的輔助功能？",o:["風險轉移","提高就業率","為損失作財務上的補償","以上各項皆是"],a:1,e:"風險轉移及為損失作財務上的補償是保險的基本\n功能，只有答案B正確"},{c:"2.1",s:"以下哪項最恰當描述何謂「保險單」",o:["經蓋章後發出的重要文件","是屬於保險代理人與被保險人之間的合約","保險合約中的一種可見的表達","沒有這份文件，有關的合約便告取消"],a:2,e:"事實上，絕大部分的保險合約都屬於「簡單」合\n約。技術上，保險合約無需書面證明也能生效"},{c:"2.1.2",s:"以下哪項陳述是正確的?",o:["保險合約屬於契據","大部分的保險合約屬簡單合約，因它可以用口頭或書面形式訂\n立","保險合約有效性必須以書面合約為證","保險合約屬於簡單合約，因內容淺白令一般人易於明白"],a:1,e:"簡單合約是意味着合約的訂立是簡單、容易的。\n因它可以用口頭或書面形式訂立"},{c:"2.1.2(a)",s:"以下哪項或哪些是一份「簡單合約」必要的",o:["不需以書面的形式訂立","合約條款易於明白","訂立合約時不須有一些特殊程序","以上各項皆正確"],a:2,e:"簡單合約意味着合約的訂立是簡單、容易的，簡\n單合約的有效性並不取決於特殊的手續"},{c:"2.1.3",s:"以下哪項可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含義完全相同","受屈的一方可於合理時間內把合約視為無效的決定","只有被保險人才能把保單視作可使無效(即可予以取消)"],a:2,e:"可使無效的合約是項明顯有法律效力的合約，其\n法律效力一直維持下去，除非及直至有受屈的一\n方把合約視為自訂立時起即屬無效，但須在一段\n合理時間內進行"},{c:"2.1.3(a)",s:"保險合約中的要約人是",o:["通常是保險人","通常是被保險人","可以是保險人或被保險人","通常是中介人代表的一方"],a:2,e:"在保險中，要約人可以是投保的一方，也可以是\n保險人透過反要約的形式，表示願意承保或續保"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構\n成要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就沒有合約。"},{c:"2.1.3(b)",s:"在反要約的過程中，下列哪項是不正確的？",o:["原本的要約人成為受要約人","原本的受要約人成為要約人","原本的要約內容立刻被終止並撤銷","若反要約的內容不被接納，原本的要約內容可再次有效"],a:3,e:"如果受要約人有意更改合約條件，這種意向一經\n傳達便構成了反要約，後果是原要約內容失效"},{c:"2.1.3(c)",s:"安琪在登機前購買一份旅遊保險，保險人容許她在旅程後繳付保\n險費。安琪不幸在旅程中斷了一條腿，保險人拒絕賠付安琪有關\n的醫療費用，請問保險人有權這樣做嗎？",o:["沒有。根據承保商專業守則，保險人須就投保人合理的期望賠","沒有。一張旅遊保險合約已經生效","有。保險人若賠付只出於同情","有。安琪沒有交保費"],a:1,e:"如果所保事故在支付已承諾的保費以前已經發生\n，被保險人仍然享有索償權，而保險人則另外有\n權追討未繳清的保費，答案B正確"},{c:"2.1.3(f)",s:"簡單合約要素有多種，其中訂立協議雙方明確自己的目的，並知\n道有關條款具有法律效力，此要素稱為",o:["訂立法律關係的意向","合法性","要約及承約","代價"],a:0,e:"完整合約要素包括訂立法律關係的意向，合約如\n要有效，各方必須清晰地表示有意給有關合約具\n有法律效力，答案A正確"},{c:"2.2",s:"以下哪項對代理法的描述是正確的?\ni.保險人透過保險代理人行事與親自執行沒有分別\nii.委託人需對代理人行為負起轉承責任\niii.保險代理人及保險經紀有能力就保險人的行為負起轉承責任\niv.代理關係必須透過書面方式訂立而產生",o:["i , ii","i, ii, iii","ii,iii","i, ii, iii, iv"],a:0,e:"代理關係是指存在於委託人與其代理人之間的一\n種關係。它的出現是基於事實，而不一定經過一\n個精確的委任代理過程。委託人須對其代理人的\n行為負上轉承責任責任。"},{c:"2.2.1",s:"保險代理人在安排一份保險時，為保險人行事，當中涉及兩份合\n約。其中一份存在於保險代理人與保險人之間，另一份則存在於",o:["保險代理人與第三者之間","保險人與保單持有人之間","保險代理人與保單持有人之間","保險人與保險經紀之間"],a:1,e:"保險代理人在安排一份保險時，為保險人行事，\n當中涉及兩份合約。其中一份存在於保險代理人\n與保險人之間，另一份則存在於保險人與保單持\n有人之間"},{c:"2.2.3(a)",s:"明示權限是",o:["由委託人迅速地給予的","談判經蓋章的合約的授權","祇可談判書面的合約的授權","委託人明確地以口頭或書面形式賦予的授權"],a:3,e:"明示權限是委託人明確地以口頭或書面形式賦予\n的授權"},{c:"2.2.3(b)",s:"以下哪個是表面權限的正確描述",o:["明示權限","沒有實際權限","是局限於委託人與第三者之間的關係","實際權限"],a:2,e:"表面權限是當一個代理人的權限是透過委託人對\n第三者表明同意而產生的，該權限便是表面而非\n實際。是局限於委託人與第三者之間的關係"},{c:"2.2.3(d)",s:"如果有人允許他人表示另一人是他的代理人，而他不能否定該代\n理人的權限。這代理權法則稱為",o:["實際權限","必要權限","表面權限","不容反悔的代理權"],a:3,e:"如果有人允許他人表示另一人是他的代理人，而\n他不能否定該代理人的權限。這代理權法則稱為\n不容反悔的代理權"},{c:"2.2.6",s:"代理人可於下列哪種情況終止合約？",o:["委託人已達退休年齡","委託人實在地違反了合約","委託人成立有限公司","以上各項都符合"],a:1,e:"如果委託人和代理人的任何一方基本地違反了合\n約 ，另一方便可以終止合約"},{c:"2.2.6",s:"以下哪項或哪些有關由於精神錯亂而導致代理人關係的終止的描\n述是正確的？",o:["只有代理人可終止而不能是委托人","只有委托人一方可終止而不能是代理人","代理人和委托人（自然人）均可終止","代理人和委托人均沒有權力終止"],a:2,e:"如果委託人和代理人的任何一方因精神錯亂不再\n能夠履行協議，則協議會自動終結"},{c:"3.1",s:"彌償及可保權益這兩項保險原則",o:["在財務利益方面存在著密切關聯","完全沒有共通之處","各自有完全相反的用意","尋求確立損失的有效原因"],a:0,e:"「權益」一詞是指一種與某物件或與某人之間的\n財務關係。"},{c:"3.1.2",s:"下列哪項有關沒有可保權益的保險的陳述是正確的?",o:["可以宣佈該項保險從索償產生時開始無效","保險人不須根據該份保險合約承擔賠償責任","只是那些由缺乏可保權益導致的損失才不獲賠償","該項保險屬於可使無效"],a:1,e:"缺乏可保權益的話，有關保險協議便屬無效"},{c:"3.1.3",s:"在香港，下列哪項可構成可保權益(為自己的利益而購買保險)",o:["自己","自己的配偶","自己精神錯亂的配偶","以上各項皆是"],a:3,e:"以上各項皆是在香港可構成可保權益的。"},{c:"3.1.3",s:"以下哪項可保權益的陳述不正確？",o:["對保險標的必須存在一種法律認可的關係","有可受保的東西","只適用於自身及自身的財物","該東西為有關保險標的"],a:2,e:"財產保險可保權益最明顯的例子是在絕對擁有權\n的情況下產生可保權益。遺囑執行人、遺產管理\n人、信託人、承按人等持有次於絕對擁有權，分\n別為遺產、信託財產、按揭財產投保。受託保管\n人都可以對所保管的貨品進行投保。答案C不正確"},{c:"3.1.3",s:"以下哪項是債權人對債務人的生命購買保險，具有可保權益必須\n符合的必要條件?",o:["財務關係一直存在","僅適用於抵押一直存在","沒有任何必要條件","償還債務的金額"],a:0,e:"在法律上假定有可保權益的存在，須提出財務關\n係的證據"},{c:"3.1.4",s:"彌償及可保權益兩個原則的關係",o:["均與財務利益有密切關係","兩者完全沒有共通之處","意向完全不同","尋求真正造成損失且具有影響力的原因"],a:0,e:"可保權益是對某項保險標的財務「權益」，其價\n值多少，就應在全損的情況下賠付多少錢，才能\n讓保單持有人完全的得到補償，所以彌償及可保\n權益兩個原則均與財務利益有密切關係"},{c:"3.1.4(b)",s:"阿倫給予他的朋友玫瑰一個他所擁有的單位免費住兩個月，請問\n玫瑰有權為該單位購買保險?理由何在?",o:["有，合法地佔有某單位的任何人有權以所有人的代理人的身份\n就該單位購買保險","沒有，因為她沒有付出代價","有，她是以單位託管人的身份人對該單位具有權益的","沒有，因為她並非擁有該單位"],a:2,e:"受託保管人持有次於絕對擁有權，在得到某貨品\n的擁有人或其代理人的同意下，管有該貨品的人\n可以對所保管的貨品進行投保。"},{c:"3.1.4(d)",s:"符合法律認可關係的可保權益，以下哪項為非人身、財物或法律\n責任的可保權益?",o:["為酒樓電力中斷後，營業利潤損失購買保險","為自己的建築物購買火險","債主為自己的債務購買保險","僱主為受僱職員的損傷購買保險"],a:0,e:"可保權益亦可透過其他合法權利保險產生。因自\n身的合法權利可能受到侵犯、或可能喪失未來的\n收入，而面臨潛在損失的威脅的人，都有權對這\n種風險購買保險。"},{c:"3.1.6",s:"收取保險金的轉讓，意思是指",o:["必須把保單應該支付的金錢轉付予指定的第三者","把保單轉讓予另一保險公司","把保單的擁有權轉讓予他人","讓另一個人替代原本的被保險人"],a:0,e:"收取保險金的轉讓，意思是把保單應該支付的金\n錢轉付予指定的第三者"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["轉讓人不會把保險合約中的責任轉移到承讓人的身上","承讓人將取得收款人的權利，而非訴訟權","承讓人承讓人承諾支付未來的保費","承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費"],a:0,e:"保單「轉讓」通常是指權利的轉移。轉讓是不會\n讓轉讓人在保險合約的責任轉移到承讓人的身上\n的"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約\n性質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險\n人的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓收取保險金\n的權利無需取得保險人的同意"},{c:"3.2.1",s:"一般誠信，要求有關合約各方__________________________",o:["確保合約另一方取得可能影響訂立合約的一切重要資訊","必須誠實行事， 提供實質上真實的資訊","不得提供合約另一方要求披露的所有資訊","必須誠實行事， 提供完全真實的資訊"],a:1,e:"一般誠信誠信原則適用於大部分商業合約，在普\n通法上，合\n約各方必須本着誠實的態度行事，所提供的資訊\n必須是實質上真實的，但他們沒有責任確保對方\n取得，可能影響他是否訂立合約的一切重要資訊\n。答案B正確。"},{c:"3.2.4",s:"如果保險人要求保證所有披露資料，不論重要與否，均需完全真\n實，這表示",o:["違反法例並不能強制執行","延伸普通法中的最高誠信的要求","這合約受制於而非最高誠信","這合約受制於最高誠信"],a:1,e:"保險受到一種更為嚴格、在普通法中常被稱為最\n高誠信的原則所約束。"},{c:"3.2.4",s:"如在保險保障期間，風險上有重大的轉變",o:["很明顯地對保險人極其重要","某些保險合約可能要求被保險人作出披露","普通法要求在續約時方須要提出","以上各項皆正確"],a:3,e:"一些非人壽保單要求，在保險期限內有風險上的\n變更，例如買了人身意外保險後轉職，必須予以\n披露。不過，在普通法中，構成風險增加的狀況\n，只須在續保時通知保險人就足夠。以上各項皆\n正確。"},{c:"3.2.4",s:"在非人壽保險單續保時，最高誠信的責任",o:["要再履行","無須履行","不再適用","只對保險人適用"],a:0,e:"一些非人壽保單要求，在保險期限內\n如有風險上的變更或續保時，例如買了人身意外\n保險後轉職，必須予以披露。"},{c:"3.2.4",s:"保險人有時會把普通法中有關最高誠信責任加以延伸，要求投保\n人在保單上作出特定聲明，原因是",o:["沒有該項聲明，投保人就沒有最高誠信披露重要事實的責任","投保人僅就已提供的重要事實必須完全真實","投保人保證無論是否涉及重要事件，所提供的事實必須實質上\n真實","以上各項原因皆不是"],a:3,e:"保險人有時把普通法中的最高誠信責任加以延伸\n，要求投保人聲明或保證，無論是否與「重要」\n事件有關連，所有經披露的資料都必須完全地，\n不僅是實質地真實的。以上各項原因皆不正確"},{c:"3.2.4",s:"投保人於投保時遵守最高誠信以披露重要事實的期限",o:["只有保單持有人特別提出要求時予以延伸","法律並不容許予以延伸","一直至合約具約束力結束為止，並無例外","有時通過相互協議予以延伸"],a:3,e:"在普通法中，於保險合約訂立後，投保人才得知\n的重要事實，不必予以披露。所以，保險人有時\n通過相互協議予以延伸最高誠信以披露重要事實\n的期限"},{c:"3.2.6",s:"如果投保人違反最高誠信",o:["保險人可不作追究","除非牽涉詐騙成份的情況下，保險人才可得到補救","除非牽涉詐騙或疏忽成份的情況下，保險人才可得到補救","保險保單會自動取消"],a:0,e:"只撤銷合約的一部分，並不屬於可以執行的投保\n人違反最高誠信補救措施，可行的是對違反不予\n追究"},{c:"3.2.6",s:"違反最高誠信的形式分別有欺詐性失實陳述，非欺詐性失實陳述\n，欺詐性不披露，非欺詐性不披露的四個類別，當中非欺詐性不\n披露是",o:["蓄意地提供虛假重要事實給另一方","無意地或疏忽地向另一方提供虛假重要事實","無意地或疏忽地漏了向另一方披露重要事實","蓄意地或疏忽地漏了向另一方披露重要事實"],a:2,e:"非欺詐性不披露是無意地或疏忽地漏了向另一方\n披露重要事實"},{c:"3.2.6",s:"假如被保險人違反最高誠信，保險人可作出以下哪項的補救行動",o:["保險人可選擇推翻保單","可作出特定賠償，並於剩餘的保險期內把保單視為有效","可提出侵權法訴訟要求損害賠償","A&C"],a:3,e:"作出特定賠償，並於剩餘的保險期內把保單視為\n有效，並不是被保險人違反最高誠信，保險人可\n作出的補救行動，只有選項A&C正確"},{c:"3.3.1",s:"以下哪項屬於近因中的”危險”?",o:["電單車","身體受傷","受傷僱員","盜竊"],a:3,e:"有關危險，意思是造成有關損失的成因，盜竊造\n成有關損失可以是其中例子"},{c:"3.3.3",s:"下列哪項或哪些有關近因的陳述是正確的？",o:["必須涉及一項受保危險；否則損失不可獲賠償","一項損失如果要受保障，其單一成因必須既不屬於除外危險，\n也不屬於不保危險","如果有一項除外危險引發了一連串事故，索償將會無效","以上所有各項"],a:3,e:"如果涉及一項以上的危險，視乎危險是否以一連\n串事故的形式發生或同時發生，若要索償有效，\n當中必須涉及一項受保危險，損害由一項除外危\n險所引致一般會令保險索償或保險金要求失敗"},{c:"3.3.4",s:"就保單的除外責任所採用的字眼規定某指明成因「直接或間接」\n所引致的損失皆是除外的，哪以下那幾項是正確?\ni)以上採用的字眼不能用於修改近因這項原則的應用\nii)與除外危險關係疏遠的損失也可能是除外的損失\niii)這有利於被保險人\niv)直接由除外成因引致的損失也是不受保障",o:["i, ii","ii, iii","ii, iv","i, iv"],a:2,e:"很通常保險人借助某些保單措詞，更改近因法則\n的應用，例如「直接或間接」引致的損失的保單\n除外條款，即使該除外危險的運作只構成一個疏\n遠近因，有關損失都將不獲賠償。選項ii，\niv正確"},{c:"3.4.4",s:"以下哪項/哪幾項屬於提供彌償的方法？",o:["恢復原狀","更換","現金支付","以上各項皆是"],a:3,e:"以上各項皆是提供彌償的方法"},{c:"3.4.5",s:"損餘在保險公司運作上，通常",o:["保險人是用作量度損失的準確金額時特別留下部份","與海上所指的救援費用同屬同一意思","只限汽車殘駭上的應用","無論任何情況下保險人只付一半賠償"],a:0,e:"保險標的在受損後留下剩餘部分，例如被火損壞\n的存貨 、 車輛的殘骸等 。\n這些剩餘部分稱為損餘"},{c:"3.4.5",s:"以下哪項不是Salvage一詞的定義?",o:["在海商法中，有關財物擁有人向救助人支付的”救助賞金”","於非海上保險中，指保險標的受損後的殘餘價值","懲罰不足投保額","以上各項皆不是"],a:2,e:"懲罰不足投保額的比例分攤原則的英文名稱是Ave\nrage。"},{c:"3.4.7(a)",s:"如果一份財產保險單被稱為「受比例分攤條件約束」，那麼它的\n意思是",o:["所代表的是一種標準風險，因此標準保費適用於該風險","不足額保險是不重要的","在任何情況下均不會對損失提供十足的支付","如果保額足夠的話，便會對損失提供十足的支付"],a:3,e:"大部分類型的非水險財產保險均受比例分攤的限\n制，保險人預期受保財產會以其全額的價值投保\n。否則，當出現損失時，賠付金額便會按不足額\n投保比率遞減。"},{c:"3.4.7(b)",s:"免賠額與起賠額的分別，在於超過(或不低於)x損失的金額時",o:["超過x的免賠額，保險人支付十足的保障","超過x的起賠額，保險人支付十足的保障","超過x的免賠額，保險人收取額外x保費的要求","超過x的起賠額，保險人收取額外x保費的要求"],a:1,e:"免賠額規定損失超過免賠額金額，被保險人就可\n以得到扣除免賠額後的賠償金額，除非損失超過x\n金額，否則得不到任何賠償。起賠額不同之處是\n，當損失的金額超逾或達到起賠額時，該損失便\n可全數獲賠償。答案B正確"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約\n定價值$1,000,000」，意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目\n的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方式提供保險\n保障的，約定價值一律被視為損失時的實質價值"},{c:"3.5",s:"代位及分擔有近似的目標，它們都是",o:["它們都有兩份保單","每份保單都有共同的保障","保險人向引致疏忽的人作出追討賠償","賠償額不可能大於彌償"],a:3,e:"分擔及代位是彌償原則的引伸，由於人壽保單屬\n利益保單，不適用於彌償原則，正確答是D。"},{c:"3.5.5",s:"當發生一項$1,000,000的財產損失，當中出現重複保險。此保單\n的全損為$30,000,000，另設有單一物件限制$5,000。這次總賠償\n金額為$995,000，這顯示以下哪項所述是正確的?",o:["所有其他有關保單都有分擔條款","這份保單有分擔條款","這份保單有比例分攤條款","所有有關保單均有比率之數條款"],a:1,e:"分擔條款又稱比率之數條款，把保險人的責任限\n於損失的某個比率份額。在重複保險的情況下，\n如果每份有關的保單均包含了這項條款的話，被\n保險人就不再可以單靠一個保險人而獲全額賠償\n。"},{c:"3.6.2",s:"代位權的出現，是由第三者疏忽地對受保財產造成損毀，並且該\n財產的保險人承繼對疏忽人士行使法律權利。技術上，此代位權\n是來自",o:["侵權法","法規下","分攤","因他人的行為疏忽而負上責任"],a:0,e:"一般情況因第三者疏忽而引致了損失，這是在侵\n權法上產生的代位權"},{c:"3.6.4",s:"建築商就一意外向一架私家車擁有人支付$13,000,000。因為一項\n每宗責任事故限額的應用，該名私家車司機只有向其責任保險人\n取得保險金$12,000,000。如果保險人後來向第三者追回$7,000,0\n00，請問誰有權取得這筆錢?又怎樣分這筆金額?",o:["保險人佔 $7,000,000，被保險人沒有份兒","保險人沒有份兒，被保險人 $7,000,000","保險人佔 $6,000,000，被保險人 $1,000,000","保險人佔十三分之十二，被保險人佔十三分之一"],a:2,e:"因為保單限額的應用，被保險人尚欠100萬的賠償\n，如果保險人後來向第三者追回700萬，被保險人\n可分享100萬代位益，保險人則享餘下600萬"},{c:"4.1",s:"產品開發是保險公司的重要功能，原因是",o:["產品開發有助於確保公司的財務穩定","香港有着競爭激烈的營商環境","可以看出，由於在過去幾年中保險監管框架的迅速變化，保險\n產品很快就過時了","必須根據不斷變化的法規要求對強制性保險單進行頻繁的修訂"],a:1,e:"由於香港有著開放又競爭激烈的營商環境，保險\n人在設計準備銷售的產品時，必須做到\n高效而有活力"},{c:"4.2",s:"以下哪項或哪些較可能屬於客戶服務的職能？",o:["對索償作出調查","與客戶聯絡","加強銷售計劃","以上各項皆是"],a:1,e:"客戶聯絡較可能屬於客戶服務的職能"},{c:"4.4",s:"以下哪項不大可能屬於保險銷售部門的職能 ?",o:["產品各環節的聯繫","對索償作出調查","監察結果及趨勢","加強銷售計劃"],a:1,e:"對索償作出調查不屬於保險銷售部門的職能"},{c:"4.4(c)",s:"保險銷售部門著眼掌握銷售成果和趨勢，這過程是屬於",o:["促銷","監察","市場調查","推廣"],a:1,e:"監察及掌握銷售成果和趨勢是保險銷售部門其中\n一項重要的 職能，答案B正確"},{c:"4.5",s:"當選擇承保的風險及決定採用的保險條款時，人壽保險與一般保\n險的區別是",o:["人壽保險核保是一次性的過程，因為保險人不能取消保單","人壽保單的核保成本很高","一般保險的核保權限較為集中","以各項皆不正確"],a:0,e:"對於個人人壽保單，核保是一次性的過程，因為\n保險人不能\n取消保單，而且只能在得到被保險人的同意的情\n況下，更改保單的內容。\n因為人壽保險的核保極為重要，所以通常都把相\n關權限集中起來處理。答案A正確"},{c:"4.5(d)",s:"人壽保險中的目標風險是",o:["對保險人特別有吸引力的，保險代理人積極招攬的風險","可以是指大的、甚高的風險","通常人壽保險涉及大額的保費","以上各項都不正確"],a:0,e:"人壽保險中的目標風險是解釋為極為合意的業務\n類型，是保險中介人應該盡力爭取的業務，答案A\n正確"},{c:"4.6",s:"查核保單的準確程度及續保，相當可能屬於以下哪個部門的工作?",o:["理賠","核保","保單處理","市場行銷及促銷"],a:2,e:"查核保單的準確程度及續保，相當可能屬保單處\n理部門的工作"},{c:"4.7",s:"以下哪項可能對人壽保險理賠造成一定的影響?\ni)還未清償的保費貸款\nii)與受益人有關的複雜事項\niii)轉讓保單予第三者的可能性\niv)對死者死亡的真確性或身份存在不確定因素",o:["i，ii","ii，iii","i，iii，iv","i，ii，iii，iv"],a:3,e:"以下各項都可能對人壽保險理賠造成一定的影響"},{c:"4.7",s:"處理人壽及非人壽索償時有的共同特性是數額的問題及",o:["如何處理彌償的問題","分擔的問題","責任的問題","代位權的問題"],a:2,e:"處理人壽及非人壽索償時有的共同特性是數額的\n問題及責任的問題"},{c:"4.9",s:"最可能協助保費率，儲蓄及債務估值方面計算的部門是",o:["精算支援","保單處理","培訓及發展","會計及投資"],a:0,e:"協助保費率，儲蓄及債務估值方面計算的部門是\n精算支援"},{c:"5.1.1",s:"因意外喪失能力或健康欠佳提供利益的長期保單是？",o:["意外","永久健康","意外及疾病","永久喪失能力"],a:1,e:"永久健康是因意外喪失能力或健康欠佳提供利益\n的長期保單，屬一般保險業務"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不屬保險業監\n管局成立的政策目標？\ni.作為保險業監管機構，在財政上和運作上獨立於在財政上和運\n作上獨立於政府\nii.直接為保單持有人提供經濟援助\niii.確保保險業的維持高額償付準備金，與國際慣例看齊\niv.建立一個直接規管保險中介人的制度，以補充現時的自律規管\n制度",o:["i, ii","i, ii, iii(cid:9)","iii, iv","ii,iii,iv"],a:3,e:"保監局的政策目標是確保保險業的規管架構與時\n並進，促進保險業的穩健發展、為保單持有人和\n潛在保單持有人提供更佳的保障、與國際慣常做\n法看齊（即保險業監管機構必須在財政上和運作\n上獨立於政府和業界），及建立一個直接規管保\n險中介人的制度，以取代現時由三個自律規管機\n構執行的自律規管制度。選項ii,iii,iv不正確"},{c:"6.1.1",s:"保險業條例由以下哪個機構負責執行?",o:["保險業監管局","香港保險業聯會","證券及期貨事務監督委員會","保險行業本身自律監督"],a:0,e:"保險業條例由保險業監管局負責執行"},{c:"6.1.1e",s:"《與有關公司安排再保險的指引》之所以重要，原因是",o:["當再保險人與某保險人有關連的時候，所作出某項再保險安排\n不足時，會如何處理","保險人對其再保險安排作出審慎監控","當再保險人與某保險有關連的時候，保險人對其再保險安排時\n須向保監局提出報告","當再保險人與某保險有關連的時候，保險人對其再保險安排時\n須得到保監局批准"],a:0,e:"《與有關公司安排再保險的指引》之所以重要，\n原因是當再保險人與某保險人有關連的時候，所\n作出某項再保險安排不足時，會如何處理"},{c:"6.1.1e",s:"《與有關公司安排再保險的指引》很重要，因為",o:["該指引令核數師很頭痛","高級管理人員會疏於管理","當再保險人與某保險人有關連的時候，姊妹公司 會私相授授","當再保險人與某保險人有關連的時候，相關公司會對其再保險\n安排應行的審慎監控可能會流於鬆懈"],a:3,e:"《與有關公司安排再保險的指引》原因是：當再\n保險人與某保險人有關連的時候，保險人對其再\n保險安排應行使的審慎監控可能會流於鬆懈；如\n果容許鬆懈地監管這情況，會對投保公眾帶來風\n險。"},{c:"6.1.1f",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（\n修訂）條例》所授予，對獲授權保險人施予的紀律處分？\ni. 將保險人清盤\nii. 限制投資\niii. 非公開譴責\niv. 罰款",o:["i, ii","i, ii, iii","iii，iv","ii，iii，iv"],a:2,e:"非公開譴責及罰款屬於《2015年保險公司（修訂\n）條例》所授予保險業監管局新增的監管權力，\n答案C正確"},{c:"6.1.1f",s:"《保險業條例》列明經營一般業務的保險人必須就其從香港保險\n業務所產生的負債在香港維持資產，用來釐定這一數據的方法之\n一，是計算有關數額與以下之總和",o:["毛負債額（不扣除再保險部分）的80%","净負債額（扣除不保部分）的80%","净負債額（扣除再保險部分及可爭議負債）的80%","净負債額（扣除再保險部分）的80%"],a:3,e:"經營一般業務的保險人，必須就其從香港保險業\n務所產生的負債在香港維持資產，所需數額以訂\n明的兩種匯算方法之一計算，其一所要求的數額\n不能少於兩項的總和:(i)淨負債額（即已經扣除\n再保險所保的那部分）的百分之八十 ；及(ii)\n有關數額。"},{c:"6.1.1f",s:"根據《保險業條例》的要求，所有保險人必須每年向保險業監管\n局呈交？",o:["財務報表","資產負債表","損益表","以上皆不是"],a:0,e:"根據《保險業條例》的要求，所有保險人必須每\n年向保險業監管局呈交財務報表"},{c:"6.1.1f(f)",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（\n修訂）條例》所授予，對獲授權保險人施予的紀律處分？\ni. 公開譴責\nii. 對新業務的限制\niii. 罰款\niv. 限制保費收入",o:["i, ii","i, ii, iii","i，iii","ii，iii，iv"],a:2,e:"《2015年修訂條例》下新增的規管權力：保監局\n可以施加的紀律處分包括：撤銷暫時撤銷給予保\n險人的授權、禁止申請經營某類別保險業務的授\n權、公開或非公開的譴責、罰款等。"},{c:"6.1.2",s:"根據《承保商專業守則》，以下哪一項是關於銷售資料的要求描\n述是正確的?",o:["只會在銷售時最初時間提供","必須使用技術的保險用語編寫","資料應該是最新的、精確的，以淺白的語言進行敍述並且不會\n誤導公眾","只要對銷售有利，可輕微地提供虛假資訊"],a:2,e:"承保商專業守則就銷售資料提供建議做法，這些\n資料應該是最新的、精確的，以淺白的語言進行\n敍述並且不會誤導公眾，答案C正確"},{c:"6.1.2c",s:"根據《承保商專業守則》，假如符合兩項條件，即使違反保證亦\n不會在索償時被拒絕，其中是包括以下哪項？",o:["損失不超過2,000元","被保險人承認違反保證","損失與違反保證兩者並無因果關係","以上各項皆不是"],a:2,e:"根據《承保商專業守則》的索償建議，沒有涉及\n欺詐成分違反了保證，而且該違反沒有引致有關\n損失，保險人不應拒絕賠償 或支付保險金"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒\n有保證價值此事實\nii.投保人訴在核保結果為次標準風險\niii保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投\n訴於銷售的過程中沒有驗證其真實年齡\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保\n單是屬於「抗通脹保單」",o:["i,ii,iii","i,iii,iv","iii,iv","i,ii,iii,iv"],a:1,e:"保險投訴局受理的投訴個案與保險人的服務水平\n或核保決定無關"},{c:"6.1.3c",s:"保險人與保單持有人發生爭議，儘管保險合約中可能設有仲裁條\n款，保單持有人仍可向保險投訴局尋求調解服務，以下哪一項是\n該服務需要滿足的條件？\ni.爭議屬承保或服務訴個案\nii.雙方要求提供調解服務服務前，未能透過仲裁調解糾紛\niii.爭議屬索償無關的投訴個案\niv涉案保險人已對索償或爭議作出了最終決定",o:["i,ii","i,ii,iv","ii,iii,iv","iii,iv"],a:3,e:"保險投訴局有權處理的投訴，必須符合以下條件\n：\n-索償相關及非索償相關的投訴個案涉案\n-保險人已對索償／爭議作出了最終決定\n-投訴個案並非正在進行法律程序或仲裁\n-投訴個案與保險人的服務水平或核保決定無關等\n只有選項iii,iv正確"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值\n，導致損失了有關的保單利息","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投\n訴於銷售的過程中沒有驗證其真實年齡","投保人不滿投保申請出乎意料被拒絕","對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保\n單是屬於「抗通脹保單」"],a:2,e:"保險投訴局受理的投訴個案與保險人的服務水平\n或核保決定無關"},{c:"6.2",s:"以下哪項不屬舊有的自律規管機構?",o:["保險代理登記委員會","香港保險顧問聯會","香港專業保險經紀協會","以上各項皆不正確"],a:3,e:"以上各項都是舊有的自律規管機構，答案D不正確"},{c:"6.2.2",s:"當保險代理人獲名獲授權保險人委任為代理人，保險人所承擔的\n轉承責任取決於",o:["委任時間","涉及的業務系列","保險人的選擇","客戶的選擇"],a:1,e:"如果代理人獲多於一名獲授權保險人委任，上述\n往來關乎某特定業務系列，而該代理人只獲該等\n保險人中的其中一名（賦權保險人）委任從事該\n業務系列，那麽，則該賦權保險人須為受委人就\n該等往來作出的作為，承擔法律責任，不論該作\n為是否在受委人的權限範圍內亦然。答案B正確"},{c:"6.2.5",s:"以下哪項是《保險業條例》賦予保監局執行其法定職能時的必要\n權力?",o:["保監局頒布《保險業（獲授權保險人的最高數目）規則》","保監局有撤銷或暫時吊銷屬於持牌保險中介人、負責人或受規\n管人士的牌照權力","保監局可委任該局僱員作為調查員，調查涉嫌違反《保險業條\n例》條文等問題","以上各項皆正確"],a:1,e:"以上各項皆是是《保險業條例》賦予保監局執行\n其法定職能時的必要權力"},{c:"6.2.5(f)",s:"以下哪項是《持牌保險代理人操守守則》，代理人在進行關受規\n管活動時應遵循的行為原則?",o:["在以廣告宣傳、營銷或推廣保險產品時，持牌保險代理人只應\n使用其客戶提供或認可的材料","只應從該代理人的委任保險人所提供並獲其授權進行推廣的保\n險產品範圍中，推薦最符合客戶利益的保險產品","持牌保險代理人不可僱用或委聘他人為其進行受規管活動時提\n供支援","以上各項皆正確"],a:1,e:"在以廣告宣傳、營銷或推廣保險產品時，持牌保\n險代理人只應使用其委任保險人或委任代理機構\n提供或認可的材料。\n持牌保險代理人只應從該代理人的委任保險人或\n委任代理機構所提供並獲其授權進行推廣的保險\n產品範圍中，推薦最符合客戶利益的保險產品。\n若持牌保險代理人僱用或委聘他人為其進行受規\n管活動時提供支援，有關代理人應確保該人具有\n誠信和勝任能力以履行其受僱或受聘的責任，並\n盡職地監督該人履行這些責任。\n只有答案B正確"},{c:"7.1",s:"保險中介人是要擔任諮詢人的角色，既非說客也非執法者，應該",o:["不加諸不當影響","合法行事","不詐騙","不能不公平地從客戶身上獲取好處"],a:0,e:"保險中介人是要擔任諮詢人的角色，既非說客也\n非執法者，不能加諸不當影響"},{c:"7.1.2",s:"以下哪一項就保險代理人的描述是不正確?",o:["因執行業務的疏忽行為所須承擔侵權法律責任的機會並非較高","因疏忽而對保單持有人提供不當的保險意見，須承擔侵權法律\n責任的機會並非較高","因疏忽而對保單持有人提供錯誤的保險意見，須承擔侵權法律\n責任的機會並非較高","保險代理人完全不用承擔任何侵權法律責任風險之中"],a:3,e:"一個保險代理人如果在為顧客承擔進行某項活動\n時，他因不當履行責任而被判須負法律責任的機\n會，相對經紀來說是比較小，但並不代表保險代\n理人完全不用承擔任何侵權法律責任風險之中"},{c:"7.2.1",s:"個人資料(私隱)條例中的第 1 原則",o:["資料應是準確的","當資料使用者收集某人的個人資料時，必須向該資料當事人提\n供的訊息","個人資料應是準確的、最新的","個人資料應是準確的、最新的，其保留期限不 應超過所需時間"],a:1,e:"保障資料第1原則:收集個人資料的目的及方式，\n描繪如何合法和公平地收集個人資料，及當資料\n使用者收集某人的個人資料時，必須向該資料當\n事人提供的訊息"},{c:"7.2.1",s:"以下哪項對《個人資料(私隱)條例》範圍的陳述是正確的?：\ni. 自動化操作資料\nii.只適用於人手操作資料\niii. 只適用香港永久居民\niv. 它既涉及公營機構及私營機構",o:["i,ii,iii","i,iii,iv","i,iv","i,ii,iii,iv"],a:2,e:"個人資料是指自動化操作資料，以及涉及公營機\n構及私營機構"},{c:"7.2.1",s:"個人資料（私隱）條例》列明的六項保障資料原則，\n以下哪一項就第 1 原 則的描述正確?",o:["個人資料保留期限不應超過所需時間","個人資料應是準確的、最新的，其保留期限不應超過所需時間","採取適當的保安措施，以確保個人資料受保障而不受未獲准或\n意外的查閱","描繪如何合法和公平地收集個人資料"],a:3,e:"保障資料第1原則:收集個人資料的目的及方式，\n此原則描繪如何合法和公平地收集個人資料，及\n當資料使用者收集某人的個人資料時，必須向該\n資料當事人提供的訊息。"},{c:"7.4.7",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）不適用於",o:["再保險公司","銀行業條例下成立的金融機構","持牌保險經紀公司","持牌個人保險代理"],a:1,e:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）\n不適用於銀行業條例下成立的金融機構"},{c:"7.5",s:"根據《防止賄賂條例》，利益的限額是",o:["100元或以上","500元或以上","1000元或以上","沒設最低金額"],a:3,e:"根據《防止賄賂條例》，利益的限額是沒設最低\n金額"},{c:"7.5.1",s:"以下哪一項是《防止賄賂條例》下僱員應該遵守或避免的行為?",o:["僱員從事有關業務或事務時，如未經僱主同意，不得創業","僱員從事有關業務或事務時，如未經僱主同意，不得在其關係\n終止5年內創業","僱員從事有關業務或事務時，如未經僱主同意，不得索取或接\n受任何利益","僱員從事有關業務或事務時，如未經僱主同意，不得委任分代\n理人"],a:2,e:"根據《條例》第9(1)條的規定，代理人在處理其\n主事人的業務或事務時，如未經主事人的允許，\n不得索取或接受任何利益"},{c:"7.5.1(a)",s:"根據《條例》第9(1)條的規定，代理人在處理其主事人的業務或\n事務時，如未經_______的允許，不得索取或接受任何利益。",o:["主事人","上司","經理","同事"],a:0,e:"根據《條例》第9(1)條的規定，代理人在處理其\n主事人的業務或事務時，如未經主事人的允許，\n不得索取或接受任何利益"},{c:"7.5.1",s:"以下哪項觸犯了《防止賄賂條例》第9(三)條?",o:["一名持牌個人保險代理人意圖利用偽造的保險申請書來騙取保\n險公司的佣金","保險公司的採購人員提交虛假文件，令採購合約判給與該名採\n購人員有關連的公司","一名持牌業務代表(代理人)偽造培訓紀錄以騙取培訓津貼","以上各項皆是"],a:3,e:"以上各項皆是觸犯了《防止賄賂條例》第9(三)條\n的例子"},{c:"7.6",s:"對保險代理人而言，以下哪項或哪些技術性地構成詐騙？",o:["建議客戶不要透露某些重要事實","在詐騙索償中，沒有將明確的資料交給保險人","在安排保險過程中，故意隱瞞一些不良影響的資料","以上各項皆是"],a:3,e:"以上各項皆是技術性地構成詐騙的罪行"},{c:"7.6.1",s:"犯罪者不是以主犯的身份犯罪就是以那麼的身份犯罪?",o:["次犯","從犯","助犯","刑事代替犯"],a:1,e:"犯罪者不是以主犯的身份就是以從犯的身份參與\n犯罪。一項刑事罪的從犯是指一名協助、教唆、\n慫使或促致犯該罪行的人"}],"paper1-mock-08":[{c:"1.1",s:"考慮風險概念時，以下哪項是不正確的？",o:["在實際環境下，並非所有風險均可以利用商業保險保障的方式","保險是抗衡風險的唯一挽救方法","保險的基本目的是要抗衡風險所產生的財務後果","包括以上所有各項"],a:1,e:"保險只是處理風險其中一種工具或措施"},{c:"1.1.1",s:"「風險」的定義是",o:["保險人有可能變成資不抵債的危險性","潛在利益有關的不確定性","對可能發生的風險有保護措施","潛在損失有關的不確定性"],a:3,e:"「風險」帶有損失或危險的意思，可以把它定義為\n「與潛在損失有關的不確定性」"},{c:"1.1.1",s:"有一類風險會使我們情緒上感到難過及悲傷，但並不涉及財務損失\n。這類風險",o:["在任何情況下是可保的","通常得到承保","只有損失是由意外造成才受保的","相當可能不受保"],a:3,e:"難過及悲傷的情緒上損失難以用金錢衡量損失，以\n商業方式處理此等風險，在財務上是不可行的。"},{c:"1.1.1",s:"「風險」的定義是",o:["不同人士使用「風險」一詞可能具有不同的意思","任何情況下定義為「與潛在損失有關的不確定性」","一半情況下定義為「與潛在損失有關的不確定性」","以上所有皆非"],a:0,e:"不同人士使用「風險」一詞可能具有不同的意思，\n視乎使用時的場合，「風險管理」一詞具不同的含\n義，在銀行業及其他非保險金融服務領域，它大概\n是指對投資及其他投機風險的管理，就保險公司而\n言，這可能僅指對純粹風險的管理，甚至可把範圍\n進一步收窄至只對可保風險的管理"},{c:"1.1.1",s:"以下關於風險的敘述中哪一個是正確的?\ni) 所有風險都是可保的\nii) 並非所有風險都屬於商業上可保的\niii) 保險是應付風險的唯一方法\niv) 保險人談及風險時可以有很多不同的意見",o:["i， ii","ii， iv","i， iv","i， iii， iv"],a:1,e:"保險是應付風險的共其一種方法，就保險公司而言\n，這可能僅指對純粹風險的管理，甚至可把範圍進\n一步收窄至只對可保風險的管理。只有選項ii，\niv正確"},{c:"1.1.1",s:"從保險人的角度，風險一詞是指：\ni) 所保的危險\nii) 承保的財產\niii) 保險人承保的人身\niv) 一項與潛在損失有關的不確定性",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:3,e:"以上各項皆是從保險人的角度，風險一詞的定義"},{c:"1.1.1",s:"風險的定義是",o:["造成損失的影響","保單保障的損失成因","與潛在損失有關的不確定性","與潛在利益有關的不確定性"],a:2,e:"風險的定義是與潛在損失有關的不確定性"},{c:"1.1.1",s:"在不同的情況下，我們可以用同一個詞語來描述損失的可能性，受\n保財產或一項受保危險，這一個詞語是",o:["風險","保單","保險","近因"],a:0,e:"在不同的情況下，我們可以用同一個詞語來描述損\n失的可能性，受保財產或一項受保危險，這一個詞\n語是風險"},{c:"1.1.1",s:"較有可能成為可保風險的是",o:["財務上的潛在損失","情緒上的潛在損失","心理上的潛在損失","以上各項皆是"],a:0,e:"只有財務上的潛在損失及身體上的損失較有可能成\n為商業上的可保風險"},{c:"1.1.1",s:"「一項潛在損失的不確定性」，這項定義最能恰當地描述?",o:["風險","一種可能出現的損失或收益","那些可保的風險而已","任何預期之外的事件， 不論結果怎樣"],a:0,e:"「一項潛在損失的不確定性」，這項定義最能恰當\n地描述風險一詞"},{c:"1.1.1",s:"以下哪項有關風險的陳述是正確的 ?\ni) 所有類型的風險在商業上都是可保的\nii)保險人在使用保險一詞時，通常是指它們的營業成績的不確定性\niii)有些風險是商業保險人視為不可保的\niv)在任何情況下帶來財務後果的風險是可保的",o:["i, ii","ii, iii","iii","iii, iv"],a:2,e:"就保險公司而言，這可能僅指對純粹風險的管理，\n甚至可把範圍進一步收窄至只對可保風險的管理，\n有些風險是商業保險人視為不可保的，只有選項iii\n正確"},{c:"1.1.1",s:"當風險真正出現時，以下哪項風險後果相當可能屬於不可保?",o:["財務損失的風險","因別人不誠實而引致損失的風險","因意外引致喪失肢體的風險","悲傷及傷心的風險"],a:3,e:"悲傷及傷心的風險難以用金錢衡量損失，對於保險\n人而言是不可保的風險"},{c:"1.1.1",s:"描述保險及風險的關係，以下哪項是正確的",o:["並非所有風險都屬於商業上可保的","保險是抗衡風險的唯一挽救方法","所有風險在商業上都是可保的","以上各項皆是"],a:0,e:"只有財務上的潛在損失及身體上的損失，純粹風險\n及特定風險較有可能成為商業上的可保風險"},{c:"1.1.1",s:"風險所帶來的潛在損失可能是身體上，財務上及情緒上。以下哪項\n或哪些潛在損失可能是可保的？",o:["身體上及財務上可保而已","身體上及情緒上可保而已","財務上及情緒上可保而已","身體上、財務上及情緒上"],a:0,e:"只有身體上及財務上帶來的潛在損失，在商業上為\n可保風險"},{c:"1.1.1",s:"對保險人而言，描述受保損失的成因，受保財產的字眼是",o:["風險","危險","被保險人","保單持有人"],a:0,e:"對保險人而言，描述受保損失的成因，受保財產的\n字眼是風險"},{c:"1.1.1",s:"保險與風險之間的聯繫如何 ?",o:["有些風險(不過並非所有種類)是可保的","若有保險的保障，所有財務損失都是保險人的責任","風險提供保障的唯一方法就是保險","所有類型的風險都是可保的"],a:0,e:"例如財務上及身體上的風險較有可能成為商業上的\n可保風險，不過並非所有種類的風險是可保的"},{c:"1.1.1",s:"保險人在運用「風險」一詞時，可能有其他含義，其中包括：\ni) 形容他們承保的財物或保單持有人\nii) 表明承保的危險或造成損失的原因\niii) 對投資及其他投機風險的管理\niv) 作出對任何將會面對的損失及收益的評估",o:["i, ii","i, iii","ii, iii","ii, iv"],a:0,e:"保險人在談及風險一詞時，包括公司承保或被要求\n承保的財物或人身，以及所保危險(即造成損失的原\n因或成因)，就保險公司而言，這可能僅指對純粹風\n險的管理，甚至可把範圍進一步收窄至只對可保風\n險的管理。只有選項i,ii正確"},{c:"1.1.1",s:"保險人在談及風險一詞時，包括",o:["公司投資","應收取的保費","公司承保或被要求承保的財物或人身","管理該公司核保部的行政人員"],a:2,e:"保險人在談及風險一詞時，包括公司承保或被要求\n承保的財物或人身，以及所保危險(即造成損失的原\n因或成因)"},{c:"1.1.1",s:"如果一份保單根據「全險」形式購買，在這方面「風險」的預定含\n義是︰",o:["所保「危險」即造成損失的原因","損失或收益的可能性","被保險的財產","作為保單被保險人的受保障人士"],a:0,e:"保險人在談及風險一詞時，包括公司承保或被要求\n承保的財物或人身，以及所保危險(即造成損失的原\n因或成因)"},{c:"1.1.1",s:"以下哪項或哪些屬於保險人對「風險」含義的慣常理解？",o:["引起損失的一種特定原因﹝或危險﹞","正在承保的財產","正在承保的人身","以上所有各項"],a:3,e:"以上所有各項都屬於保險人對「風險」含義的慣常\n理解"},{c:"1.1.1",s:"以下哪項有關風險的陳述是正確的？\ni.所有風險都是可保的\nii.並非所有風險都屬於商業上可保的\niii.保險是應付風險的唯一方法\niv.保險人談及風險時可以有很多不同的含義",o:["i, ii","ii, iii","ii, iv","iii, iv"],a:2,e:"例如財務上及身體上的風險，較有可能成為商業上\n的可保風險，不過，並非所有種類的風險是可保的\n，而購買保險只是應付風險的其中一項方法，只有\n選項ii,iv正確"},{c:"1.1.1",s:"保險人提供「全險」保障時，所提及的風險是指",o:["造成損失的原因","所承保的財物","正在考慮承保的人身","正在考慮承保的財物或人身"],a:0,e:"有些保險單可能提供「全險」的保險保障，意思是\n說除非出事原因屬保障範圍以外，否則由任何原因\n造成的任何損失均屬受保的，所以釐清造成損失的\n原因或成因相當重要"},{c:"1.1.1",s:"如果一名由保險人聘請的檢驗人，他必須為某項「風險」進行檢驗\n，那麼，「風險」一詞在這方面有以下哪項或哪些含義？",o:["將成為被保險人的那人的繳付保費能力","將成為受保的財產","將成為被保險人的那人的信貸資料","以上任何一項"],a:1,e:"保險人在談及風險一詞時，包括公司承保或被要求\n承保的財物或人身，以及所保危險(即造成損失的原\n因或成因)，只有答案B正確"},{c:"1.1.2",s:"商業保險人所保的風險主要是",o:["特定風險及基本風險","純粹風險及基本風險","純粹風險及特定風險","純粹風險及投機風險"],a:2,e:"商業保險人所保的風險主要是純粹風險及特定風險"},{c:"1.1.2",s:"以下有關基本風險的敘述，哪一項是正確的?",o:["基本只會有損失而無收益","通常範圍不廣泛","個人性而非社會性","相當可能不受保"],a:3,e:"商業保險人所保的風險主要是特定風險，基本風險\n一般是不可保的，因為要求他們以商業方式處理此\n等風險，財務上是不可行的"},{c:"1.1.2(a)",s:"因心臟病產生的醫療開支最有可以被歸類為_____________。",o:["純粹風險","投機風險","特定風險","基本風險"],a:2,e:"特定風險能成的後果是相對有限的，只影響個人或\n為數較少的人。這類風險包括汽車意外、個人損傷\n等情況。"},{c:"1.1.2(b)",s:"盜竊最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:2,e:"盜竊會有金錢上損失，純粹風險只具有財務損失的\n可能性"},{c:"1.1.2(b)",s:"汽車意外、個人損傷等情況，最有可能屬於_______________",o:["特定風險","基本風險","純粹風險","投機風險"],a:0,e:"特定風險造成的後果是相對有限，例如汽車意外、\n個人損傷就是例子"},{c:"1.1.2a",s:"以下哪項屬於「投機風險」類型？",o:["製造商推出新款汽車於市場競爭","對未來恆生指數股數作推測","與友人合資博彩於賽馬活動中","包括以上各項"],a:3,e:"包括以上各項都是既有收益或損失兩種可能結果，\n屬投機風險"},{c:"1.1.2a",s:"從可保程度的角度來看，以下哪項關於純粹風險的描述是正確的?",o:["屬於必然可保","屬於必然不可保","比投機風險可保性為低","比投機風險可保性為高"],a:3,e:"商業保險人所承保的風險主要是特定風險及純粹風\n險，而投機風險一般是不可保的，因為要求他們以\n商業方式處理投機風險，在財務上是不可行的"},{c:"1.1.2a",s:"以下哪項或哪些是「純粹風險」的項目？",o:["賽馬賭博","開展一門生意的決定","已身故債務人無法償還的財務損失","沒有以上一項"],a:2,e:"債務人無法償還的財務損失，只有導致損失的可能\n性，是「純粹風險」"},{c:"1.1.2a",s:"以下哪項是屬於投機風險的？",o:["投資股票","兩輛汽車相撞","雷電打擊造成建築物嚴重的破壞","以上的沒有一項是"],a:0,e:"投機風險能產生收益、損失等兩種可能的結果。這\n類風險包括賭博、業務開創及投資活動等"},{c:"1.1.2a",s:"從可保程度的角度來看，純粹風險屬於",o:["永不可保的","必然可保的","可保程度可能低於投機風險","可保程度可能高於投機風險"],a:3,e:"商業保險人所保的風險主要是純粹風險及特定風險\n，投機風險及基本風險是較不可保。"},{c:"1.1.2a",s:"以下哪類是既有收益或損失兩種可能結果的風險?",o:["基本風險","純粹風險","特定風險","投機風險"],a:3,e:"投機風險既有收益或損失兩種可能結果的風險"},{c:"1.1.2a",s:"下列哪些是可保風險?\ni) 純粹風險\nii) 特定風險\niii) 基本風險\niv) 投機風險",o:["i， ii","i， iii","ii， iii","ii， iii， iv"],a:0,e:"商業保險人所保的風險主要是純粹風險及特定風險"},{c:"1.1.2a",s:"以下哪項或哪些可以分類為「投機」風險?\ni) 恆生指數的波動\nii) 禽流感疫苗的研究及發展\niii) 一個賭場被火災損壞的風險\niv) 在沙田馬場舉行的一場賽馬結果",o:["iii","i， ii","i， ii， iv","i， ii， iii， iv"],a:2,e:"一個賭場被火災損壞的風險屬純粹風險，只有選項i\n,ii,iv正確"},{c:"1.1.2a",s:"只有損失的機會而無收益的可能性之風險稱為",o:["純粹風險","特定風險","投機風險","基本風險"],a:0,e:"只有損失的機會而無收益的可能性之風險稱為純粹\n風險"},{c:"1.1.2a",s:"以下哪項關於「純粹風險」的描述是不正確的？",o:["意外失足引致腿傷","開拓深海攢探技術","建築地盤因火災引致的嚴重損失","一輛飛機墮毀"],a:1,e:"開拓深海攢探技術屬投機風險"},{c:"1.1.2b",s:"以下哪項正確地描述「基本風險」？",o:["它相當可能涉及損失,不會出現收益","它只影響個人而非整體社會","根據定義，它的影響並非災難性的","它相當可能是不可保的"],a:3,e:"商業保險人所保的風險主要是特定風險及純粹風險\n，基本風險一般是不可保的，因為要求他們以商業\n方式處理此等風險，在財務上是不可行的"},{c:"1.1.2b",s:"核風險屬於",o:["所有商業保險人都會承保的","屬影響範圍較小的風險","所有商業保險人都不會承保的","列為特定風險"],a:2,e:"核風險屬基本風險，影響範圍廣泛，人數不計其數\n。所有商業保險人都傾向不會承保的"},{c:"1.1.2b",s:"饑荒˴戰爭及大規模洪災是屬於哪類風險?",o:["純粹風險","災難風險","特定風險","基本風險"],a:3,e:"饑荒˴戰爭及大規模洪災是屬於基本風險"},{c:"1.1.2b",s:"如果根據風險所帶來的影響區別，風險可以分為",o:["純粹風險及投機風險","可保風險及不可保風險","投機風險及特定風險","特定風險及基本風險"],a:3,e:"如果根據風險所帶來的影響區別，風險可以分為特\n定風險及基本風險"},{c:"1.1.2b",s:"基本風險是一種",o:["涉及保單持有人可能面對死亡的風險","相當可能帶來比較有限的後果的風險","相當可能帶來廣泛、甚至災難性後果的風險","可讓保險人容易及直接地評估的風險"],a:2,e:"基本風險是一種相當可能帶來廣泛、甚至災難性後\n果的風險"},{c:"1.1.2b",s:"特定風險是一種",o:["相當可能影響大量數量人數的風險","在核保時需要特別考慮風險","相當可能帶來比較有限的後果的風險","相當可能產生嚴重或災難性後果的風險"],a:2,e:"特定風險是一種相當可能帶來比較有限的後果的風\n險"},{c:"1.1.2b",s:"某種風險可能會造成嚴重，廣泛及災難性的影響，這風險稱為",o:["純粹風險","特定風險","投機風險","基本風險"],a:3,e:"某種風險可能會造成嚴重，廣泛及災難性的影響，\n這風險稱為基本風險"},{c:"1.1.2b",s:"有一種風險，是很多財產保單中的除外責任，這種風險稱為",o:["純粹風險","特定風險","基本風險","以上各項皆是"],a:2,e:"商業保險人所保的風險主要是特定風險，基本風險\n一般是不可保的，因為要求他們以商業方式處理此\n等風險看來在財務上是不可行的。"},{c:"1.1.2b",s:"以下哪項關於基本風險的描述是正確的?",o:["地震或自然災害","通常都屬於除外責任","影響遍及整個社區而非個別人士","以上各項皆正確"],a:3,e:"以上各項皆是基本風險的正確描述"},{c:"1.1.2b",s:"從可保程度的角度來看，哪項是用來形容特定風險的?",o:["永不可保的","必然可保的","可保程度較可能低於基本風險","可保程度較可能高於基本風險"],a:3,e:"商業保險人所保的風險主要是特定風險，基本風險\n一般是不可保的，因為要求他們以商業方式處理此\n等風險看來在財務上是不可行的。"},{c:"1.1.2b",s:"有一類風險，當它們成事實時，可能產生相對有限(即非廣泛)的影\n響。這風險通常稱為︰",o:["純粹風險","特定風險","投機風險","基本風險"],a:1,e:"特定風險是一種相當可能帶來比較有限的後果的風\n險"},{c:"1.1.2b",s:"以下哪些描述「基本風險」是正確的？",o:["它包括大規模洪災及地震這類自然災害","它只影響個別的投保人士","被視為社會並非個人的災害","A 和 C"],a:3,e:"基本風險發生的原因是超逾一個人或甚至一群人所\n能操控的，受影響的人不計其數。這類風險包括饑\n荒、戰爭、恐怖襲擊、大規模洪災和其他災害等。\n這些災害影響到整個社會或人類，而非其中的特定\n個體。只有選項A 和 C正確"},{c:"1.1.2b",s:"以下哪項是「基本風險」？",o:["冠狀病毒爆發","一棵大樹倒塌","一個人自殺","商舖被盜竊"],a:0,e:"冠狀病毒爆發屬基本風險，基本風險發生的原因是\n超逾一個人或甚至一群人所能操控的，受影響的人\n不計其數。這類風險包括饑荒、戰爭、恐怖襲擊、\n大規模洪災和其他災害等"},{c:"1.1.2b(ii)",s:"以下哪項對於基本風險的描述是正確?",o:["泛指地震等的天然災害","只影響個別的保單持有人","影響到整個社會而非個人","A 及C都正確"],a:3,e:"基本風險包括饑荒、戰爭、恐怖襲擊、大規模洪災\n等。這些災害影響到整個社會或人類，而非其中的\n特定個體，所以A 及C都正確。"},{c:"1.1.3",s:"以下哪項不是「風險管理」的正確陳述？",o:["這個詞可以是與純粹風險及投機風險有關","以銀行為例，指對投資及其他投機風險的管理","保險人可把範圍縮窄至只對可保風險的管理","保險人只會在談論承保損失價值時才用這個詞"],a:3,e:"就保險公司而言，這可能僅指對純粹風險的管理，\n甚至可把範圍進一步收窄至只對可保風險的管理，\n而不是只在談論承保損失價值時才用這個詞"},{c:"1.1.3",s:"以下哪三項有關風險管理的陳述是正確的?\ni) 它可能涉及投機風險和純粹風險\nii) 作為一門獨立科學， 它涉及的問題較保險廣泛\niii) 以保險人的角度看， 它絕大程度涉及受保的風險\niv) 以被保險人的角度看， 它只涉及不受保的風險",o:["i， ii， iii","i， ii， iv","i， iii， iv","ii， iii， iv"],a:0,e:"就保險公司而言，這可能僅指對純粹風險的管理，\n甚至可把範圍進一步收窄至只對可保風險的管理。\n選項iv不正確"},{c:"1.1.3",s:"保險業中，風險管理所涉及的風險是指",o:["投資及投機風險","核保部門的行政人員","承保或被要求承保的風險","純粹風險"],a:2,e:"保險從業員在使用「風險」一詞時，可能有其他意\n思，其中包括「他們正在承保或考慮承保的受風險\n財物或人身」"},{c:"1.1.3",s:"進行能促進工業安全的活動是以下那項處理風險的方法？",o:["風險避免","損失防範","損失降低","風險融資"],a:1,e:"損失防範是降低已識別出來的可能損失的發生率，\n例如， 進行能促進工業安全的活動"},{c:"1.1.3",s:"若把風險視為一門擁有本身知識及研究方法的獨門科學，「風險管\n理」便屬於經常採用的用語，當保險人採用這個名詞時",o:["它的含義與在知識及研究方法的獨立學科上的含義是完全一致的","較為著重降低或改善承保的風險","他們指的是投機性而非純粹風險","它的含義只涉及保費"],a:1,e:"圍進一步收窄至只對可保風險的管理。因此，當保\n險人談及「風險管理」時，其所指的可能是某些可\n以用來降低或改善所承保或獲邀承保「風險」的潛\n在損失的方法或手段。"},{c:"1.1.3",s:"在投資術語中，「風險管理」一詞包括以下哪項?",o:["純粹風險和投機風險","投機風險","僅僅是可保風險","保險計劃的安排"],a:1,e:"在投資術語中，「風險管理」一詞包括投機風險"},{c:"1.1.3",s:"以下哪項陳述是正確的?",o:["風險管理是工業科學的一項分科","風險管理是僅僅保險其中的一環","風險管理是與保險完全相同的學科","保險是風險管理的工具"],a:3,e:"保險只是處理風險其中一種工具或措施"},{c:"1.1.3",s:"以下哪項有關風險管理是正確的？",o:["在保險中只涉及投機風險","在銀行中只涉及純粹風險","涉及識別風險","只涉及識別及量化風險"],a:2,e:"作為一個獨立的知識與研究的領域，風險管理可以\n解釋為管理學的一個分支，進行的步驟包括：識別\n，量化，及應對"},{c:"1.1.3",s:"以下哪項有關「風險管理」一詞的描述是正確的",o:["只適用於保險公司","保險公司不大可能收窄此詞之應用至純風險","它指三步驟:風險識別˴風險免除及風險融資","它包含二個步驟: 風險識別及風險量化"],a:3,e:"一個獨立的知識與研究的領域，風險管理可以解釋\n為管理學的一個分支，它要進行的步驟包括識別；\n量化，及應對"},{c:"1.1.3",s:"以下哪項對風險管理的描述是正確的？",o:["風險管理的其中一個方法是保險的安排","風險管理與保險並沒有聯繫","風險管理乃保險業界中的專有詞彙","風險管理即物質上控制風險"],a:0,e:"安排保險只屬風險管理的其中一個方法"},{c:"1.1.3",s:"以下哪項有關風險管理的描述是正確的？",o:["銀行對投機風險的管理","保險公司對可保風險的管理","各行業對風險管理有不同的範圍","以上各項皆是"],a:3,e:"不同人士使用「風險」一詞可能具有不同的意思，\n視乎使用時的場合，「風險管理」一詞具不同的含\n義，在銀行業及其他非保險金融服務領域，它大概\n是指對投資及其他投機風險的管理，就保險公司而\n言，這可能僅指對純粹風險的管理，甚至可把範圍\n進一步收窄至只對可保風險的管理。以上各項皆是\n有關風險管理的正確描述"},{c:"1.1.3",s:"如果風險被視為獨立的知識及研究學科，「風險管理」一詞會經常\n被提及或應用， 當保險人應用風險管理時",o:["與獨立的知識及研究學科中的意思無異","較為著重改善風險","指的是投機風險而非純風險","只涉及保費計算"],a:1,e:"當保險人談及「風險管理」時，其所指的可能是某\n些可以用來降低或改善所承保或獲邀承保「風險」\n的潛在損失的方法或手段"},{c:"1.1.3",s:"以下那個是保險人的風險管理的正確陳述？",o:["核保","保障投資利潤","保險人之理賠服務能力","降低受保風險損失的可能性"],a:3,e:"當保險人談及「風險管理」時，其所指的可能是某\n些可以用來降低或改善所承保或獲邀承保「風險」\n的潛在損失的方法或手段"},{c:"1.1.3",s:"「安裝自動灑水系統」是以下那項處理風險的方法？",o:["風險避免","損失防範","損失降低","風險融資"],a:2,e:"「安裝自動灑水系統」屬於損失降低的處理風險的\n方法"},{c:"1.1.3",s:"以下哪項不是「風險管理」的正確陳述？",o:["這個詞可以是與純粹風險及投機風險有關","以銀行為例，指對投資及其他投機風險的管理","保險人可把範圍縮窄至只對可保風險的管理","保險人只會在談論承保損失價值時才用這個詞"],a:3,e:"當保險人談及「風險管理」時，其所指的可能是某\n些可以用來降低或改善所承保或獲邀承保「風險」\n的潛在損失的方法或手段，答案D不正確"},{c:"1.1.3",s:"考慮改善受保風險之潛在損失的可能性時，保險人所採用的字眼為",o:["核保","風險評估","風險管理","保險風險分析"],a:2,e:"當保險人談及「風險管理」時，所指的可能是某些\n可以用來降低或改善所承保或獲邀承保「風險」的\n潛在損失的方法或手段。"},{c:"1.1.3",s:"很多時候，保險人在使用「風險管理」一詞時，是指下列哪項的管\n理？",o:["公司承保及要求承保的風險","危險的風險","投資及其他投機的風險","機構內主管核保部門的行政人員"],a:0,e:"保險從業員在使用「風險」一詞時，可能有其他意\n思，其中包括正在承保或考慮承保的受風險財物或\n人身，以所保危險，即造成損失的原因或成因，只\n有答案A正確"},{c:"1.1.3",s:"作為一門獨立的學科， 風險管理是",o:["保險的其中一環","涉及可保風險","屬於機構性質的風險","可被形容為在整件過程中包括保險其中一環"],a:3,e:"作為一門獨立的學科，風險管理是可被形容為在整\n件過程中包括保險其中一環"},{c:"1.1.3",s:"作爲一個獨立的知識與研究的領域，風險管理可以解釋爲管理學的\n一個分支，它要進行的步驟包括",o:["識別","量化","應付","以上各項皆是"],a:3,e:"作為一個獨立的知識與研究的領域，風險管理可以\n解釋為管理學的一個分支，進行的步驟包括：識別\n，量化，及應對"},{c:"1.1.3",s:"在風險管理的課題中，處理一間受風險威脅的機構時，應先識別，\n然後",o:["投保","量化","消除","轉移"],a:1,e:"作為一個獨立的知識與研究的領域，風險管理可以\n解釋為管理學的一個分支，它要進行的步驟包括識\n別，量化及應對風險"},{c:"1.1.3",s:"作為一門獨立的學科及研究的範圍，風險管理",o:["只處理純粹風險","只處理投機風險","可以處理純粹風險或投機風險","既非處理純粹風險也非投機風險"],a:2,e:"作為一門獨立的學科及研究的範圍，風險管理應對\n某家機構構成威脅的風險，不論是純粹風險還是投\n機風險"},{c:"1.1.3",s:"作為風險管理在獨立的知識及研究範疇上，一般的理解為",o:["投資或投機風險所帶來的損失","保險人對受保風險損失上的改善","以識別、量化及處理作為進行的步驟","環繞著對保險合約的訂立及處理"],a:2,e:"風險管理可以解釋為管理學的一個分支，它要進行\n的步驟包括識別、量化及處理"},{c:"1.1.3",s:"於識別、量化和應付的方法中，作為一門獨立的學科及研究的範圍\n，這是稱為",o:["風險融資","風險轉移","會計成本","風險管理"],a:3,e:"風險管理可以解釋為管理學的一個分支，它要進行\n的步驟包括識別、量化及處理"},{c:"1.1.3",s:"很多時候，保險人在談論“風險管理”，管理可能涉及到",o:["公司要求承保或被要求承保的風險","危險風險","投資及其他投機風險","公司內主管核保部門的行政人員"],a:0,e:"保險人在談及風險一詞時，包括公司承保或被要求\n承保的財物或人身，以及所保危險(即造成損失的原\n因或成因"},{c:"1.1.3",s:"以下哪項有關風險管理的描述是正確的？",o:["保險是風險管理的其中一環","風險管理僅是保險的其中一環","保險與風險管理是完全相同之學科","風險管理是工程技術的一門學科"],a:0,e:"保險只是多種風險管理措施當中的其中一種方法"},{c:"1.1.3",s:"作為一門獨立的學科及研究的範圍，風險管理",o:["只處理純粹風險","只處理投機風險","可以處理純粹風險或投機風險","既非處理純粹風險也非處理投機風險"],a:2,e:"作為一門獨立的學科及研究的範圍，風險管理可以\n處理純粹風險或投機風險"},{c:"1.1.3",s:"以下哪些有關風險管理的陳述是正確的?\ni.它 只涉及投機風險\nii.它 可能涉及投機風險和純粹風險\niii.作 為一門獨立科學，它涉及的問題較保險廣泛\niv.以 保險人的角度看，它絕大程度涉及受保的風險",o:["i, ii, iii","i, ii","ii,iii,iv","i, ii, iii, iv"],a:2,e:"作為一門獨立的學科及研究的範圍，風險管理可以\n處理純粹風險或投機風險，就保險公司而言，這可\n能僅指對純粹風險的管理，選項ii,iii,iv正確"},{c:"1.1.3",s:"不提供食物及飲料以避免食物中毒的風險，屬哪種風險管理的措施?",o:["風險避免","損失防範","損失降低","風險轉移"],a:0,e:"風險避免是不讓自己暴露在某項風險之下，從而免\n除遭受相關損失的機會"},{c:"1.1.3",s:"不提供專業意見以後避免負上法律責任的風險管理措施是",o:["損失防範","風險避免","風險轉移","損失降低"],a:1,e:"風險避免是不讓自己暴露在某項風險之下，從而免\n除遭受相關損失的機會"},{c:"1.1.3(c)(iii)",s:"就以下風險管理措施，提供安全訓練屬於",o:["風險避免","損失防範","損失降低","風險轉移"],a:1,e:"損失防範降低已識別出來的損失發生的頻率。提供\n安全訓練是例子"},{c:"1.2",s:"以下哪項是保險的基本功能／好處而非輔助功能？\ni)把個人的潛在財務損失轉移給保險人\nii)損失的控制/防範\niii)儲蓄／投資\niv)使商家倖免由於嚴重的火災、沉重的法律責任等情況而造成的巨\n大損失",o:["i, ii","ii, iii","i, iv","iii, iv"],a:2,e:"風險轉移，以及為損失作財務上的補償是保險的基\n本功能"},{c:"1.2",s:"一名被保險人死亡後，保險人向其受養人支付死亡保險金，這做法\n顯示",o:["人壽保險的唯一好處","人壽保險的基本功能","壽險的唯一好處及功能","並非壽險的好處及功能"],a:1,e:"保險的基本功能及好處是，保險可以為被保險人提\n供財務補償。人壽保險會在悲劇來臨或給人帶來幫\n助。"},{c:"1.2",s:"以下哪項或哪幾項是保險的基本的好處？",o:["為保單持有人提供財務補償","增加就業機會","以人壽保險及年金作為儲蓄","金融服務的發展"],a:0,e:"保險的基本功能及好處是，在各種不同的投保事件\n中，當災害發生時，保險可以為被保險人提供財務\n補償。"},{c:"1.2",s:"「風險轉移的機制」的概念",o:["與保險沒有關係","只是保險內的一種輔助功能","是保險內的一個主要功能","只是保險內的意外功能"],a:2,e:"保險本質上屬於一種風險轉移機制，保險的基本的\n好處是，在各種不同的投保事件中，當災害發生時\n，保險可以為被保險人提供財務補償。"},{c:"1.2",s:"以下哪項可視為保險為香港帶來的輔助功能/好處?\ni)作為儲蓄途徑\nii) 提供就業機會\niii) 鼓勵經濟發展\niv) 減低意外／損失的次數",o:["i，ii","i，ii，iii","ii，iii，iv","以上全部都是"],a:3,e:"以上全部都可視為保險為香港帶來的輔助功能/好處"},{c:"1.2",s:"以下哪項不應被視為保險對社會的間接益處",o:["為不少人提供就業機會","協助損失控制","促進經濟發展","對受保項目的受害人提供財務上的補償"],a:3,e:"保險可以為被保險人提供財務補償，屬保險的基本\n的好處，答案D不正確"},{c:"1.2",s:"提供就業機會，損失防範，協助儲蓄及投資，可被形容為",o:["與保險全無關係","是保險的基本功能","是保險的輔助功能而非基本功能","是保險基本目的而非副產品"],a:2,e:"提供就業機會，損失防範，協助儲蓄及投資，是保\n險的輔助功能而非基本功能"},{c:"1.2",s:"下列哪項不是保險的輔助功能 ?",o:["增加就業機會","幫助經濟增長及發展","把金錢上的損失轉移到保險公司身上","作為儲蓄途徑"],a:2,e:"保險本質上屬於一種風險轉移機制，可以為被保險\n人提供財務補償，屬保險的基本的好處，。答案C不\n正確"},{c:"1.2",s:"保險對社會有益處嗎？",o:["是有的，通過保險人要求而進行的風險防範或風險降低措施(統稱\n風險控制)","是有的，保險是社會的一種手段","沒有，僅僅是私人的安排","沒有，除非是強制的"],a:0,e:"保險對社會有益處的，通過保險人要求而進行的風\n險防範或風險降低措施(統稱風險控制)"},{c:"1.2",s:"以下哪項是保險的輔助功能？",o:["風險轉移","提高就業率","為損失作財務上的補償","以上各項皆是"],a:1,e:"風險轉移及為損失作財務上的補償是保險的基本功\n能，只有答案B正確"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni.保 險對受保損失的被保險人提供財務補償\nii.保 險為本港提供就業機會\niii.一 般保險的慣例下倡導防範損失的措施\niv.一 般保險的慣例下倡導控制損失的措施",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:3,e:"保險對受保損失的被保險人提供財務補償屬保險的\n基本功能,選項(i)不正確"},{c:"1.2",s:"以下哪幾項可視為保險為香港帶來的輔助功能/好處?\ni.保 險為本港提供就業機會\nii.保 險對受保損失的被保險人提供財務補償\niii.一 般保險的慣例下倡導防範損失的措施\niv.某 些業務可以涉及很高的純粹風險，或會令投資者卻步，除非他\n們可以投保潛在的財務損失",o:["i, ii, iii","i, ii","i,iii,iv","i, ii, iii, iv"],a:2,e:"保險對受保損失的被保險人提供財務補償可視為保\n險為香港帶來的基本功能/好處，,選項ii不正確"},{c:"1.3",s:"以下哪一項屬風險轉移措施?",o:["取消建築項目","為建築項目安排保險","加強工地的安全措施","禁止員工在工地食煙"],a:1,e:"購買保險是利用合約條件轉移對訂明損失的責任轉\n移到保險公司"},{c:"2.1",s:"以下哪項最恰當描述何謂「保險單」",o:["經蓋章後發出的重要文件","是屬於保險代理人與被保險人之間的合約","保險合約中的一種可見的表達","沒有這份文件，有關的合約便告取消"],a:2,e:"事實上，絕大部分的保險合約都屬於「簡單」合約\n。技術上，保險合約無需書面證明也能生效"},{c:"2.1.1",s:"合約可以界定為",o:["在法律上可強制執行的協議","兩人或多人之間的承諾","以書面形式表達的協議","任何兩方或多方的協議"],a:0,e:"合約可以界定為在法律上可強制執行的協議"},{c:"2.1.1",s:"社交中，朋友的晚飯約會",o:["並非法律上可執行的合約","有兩位以上朋友參與便可稱為合約","若果有書面上的來往便可稱為合約","在法律上被承認為有效的合約"],a:0,e:"一旦任何一方單方面取消約，另一方是不能向爽約\n的一方採取法律行動的，因為社交約會協議在法律\n上不被承認為有效的。"},{c:"2.1.1",s:"以下哪項或哪些是保險單的正確描述",o:["是一份經蓋章發出的重要文件","是保險代理人及被保險人之間的一份合約","是一份證明保險合約的憑證","如果保險單被損毀，保險合便告無效"],a:2,e:"保險單是一份證明保險合約的憑證"},{c:"2.1.1",s:"下列哪項有關經濟權益保險合約的陳述是正確的？\ni) 並非所有協議都是合約\nii) 所有合約必須經蓋章後發生\niii) 合約是一種法律上可強制執行的協議\niv) 嚴格的說，合約是無形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"並非所有協議都是合約，事實上，絕大部分的保險\n合約都屬於「簡單」合約，合約的訂立是簡單、容\n易的，合約的有效性並不取決於特殊的手續，只有\n選項 i, iii, iv 正確"},{c:"2.1.1",s:"合約是一項法律上可強制執行的協議",o:["然而這點是在它們以書面形式出現時才成立；","而且必須總是涉及重要的財務安排；","它們可能與重要的或較次要的事情有關；","然而只有以書面為證及在第三者見證下才成立。"],a:2,e:"合約所涉及的可以是瑣碎的事情，例如購買報章或\n乘電車，也可以是十分重要的事情，例如大型建築\n工程項目或僱傭合約"},{c:"2.1.2",s:"以下哪三項是有關僅以所涉及個人行為所設立的簡單合約的說明是\n不正確的？\ni) 在法律上，這種交易不是真正的合約\nii)這些是特殊情況，並因此稱為「蓋印的合約」\niii)如要有效，這種合約隨後須以書面表達\niv)儘管不是以口頭表達或書面方式，這種合約仍是有效的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii ,iii, iv"],a:0,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約。簡單來說，簡單合約的有效性\n並不取決於特殊的手續。選項i,ii,iii不正確"},{c:"2.1.2",s:"以下哪項有關「簡單合約」的說明是正確?",o:["它由保險人的總經理或副總經理簽署","它可以以口頭或書面形式訂立","它必須蓋章後發出才屬有效","以上各項皆是"],a:1,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約，只有簡單合約意味着合約的訂\n立是簡單、容易的。簡單合約分為口頭合約，不經\n蓋章的書面合約及從行為中推斷出來的合約，答案B\n正確"},{c:"2.1.2",s:"以下哪些關於專業彌償保險合約的描述是正確的?",o:["不是所有協議都是合約","合約必須經過蓋章發出","合約是無形的","A及C"],a:3,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約。簡單來說，簡單合約的有效性\n並不取決於特殊的手續。A及C正確"},{c:"2.1.2",s:"一項已經從有關人仕的行為推斷出來的合約肯定是",o:["簡單合約","特別合約","推斷合約","契據"],a:0,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約，答案A正確"},{c:"2.1.2",s:"以下哪項陳述是正確的?",o:["保險合約屬於契據","大部分的保險合約屬簡單合約，因它可以用口頭或書面形式訂立","保險合約有效性必須以書面合約為證","保險合約屬於簡單合約，因內容淺白令一般人易於明白"],a:1,e:"簡單合約是意味着合約的訂立是簡單、容易的。因\n它可以用口頭或書面形式訂立"},{c:"2.1.2(a)",s:"保險合約之完整條款的書面證據，通常出現於",o:["保單","投保書","保險憑證","與法定保險有關的法例"],a:0,e:"保險合約之完整條款的書面證據，通常出現於保單\n。事實上，絕大部分的保險合約都屬於簡單合約。\n技術上，保險合約無需書面證明也能生效\n，但實際上 ，它們幾乎一律是書面的。"},{c:"2.1.2(a)",s:"以下哪兩項有關簡單合約的陳述是正確的?\ni)它們絕對不能是書面的\nii)它們不是經蓋章後發出的\niii)在任何情況下它們必須是書面的\niv)它們可以是口頭或書面性質出現",o:["i 及ii而已","i 及iii而已","ii 及iii而已","ii 及iv而已"],a:3,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約。簡單來說，簡單合約的有效性\n並不取決於特殊的手續。只有選項ii,iv正確"},{c:"2.1.2(a)",s:"保險合約通常屬於哪一類合約?",o:["簡單合約","蓋章","紀錄","契據"],a:0,e:"事實上，絕大部分的保險合約都屬於「簡單」合約\n。技術上，保險合約無需書面證明也能生效"},{c:"2.1.2(a)",s:"以下哪項或哪些是一份「簡單合約」必要的",o:["必須以書面形式訂立","合約的各方都需付出代價","用詞必須簡單及容易明白","以上各項皆正確"],a:1,e:"事實上，絕大部分的保險合約都屬於「簡單」合約\n。技術上，保險合約無需書面證明也能生效，保險\n人及投保人雙方必須訂出各自應付出的代價；否則\n合約屬無效。答案B正確"},{c:"2.1.2(a)",s:"以下哪項或哪些是一份「簡單合約」必要的",o:["不需以書面的形式訂立","合約條款易於明白","訂立合約時不須有一些特殊程序","以上各項皆正確"],a:2,e:"簡單合約意味着合約的訂立是簡單、容易的，簡單\n合約的有效性並不取決於特殊的手續"},{c:"2.1.2(a)",s:"儘管缺乏口頭或書面證據，但可從涉及之人的行為斷定某項合約的\n存在，在法律上可描述為",o:["簡單合約","契據","推斷合約","以上任何一項"],a:0,e:"簡單合約意味着合約的訂立是簡單、容易的。簡單\n合約分為口頭合約，不經蓋章的書面合約及從行為\n中推斷出來的合約。答案A正確"},{c:"2.1.2(a)",s:"一個人在店鋪內購買物件時，放下金錢並取走物件，過程中不發一\n言，在這種情況下",o:["屬於違法事件","以行為証明下訂立了合約","因為沒有蓋章及簽署，故此訂立了契據","已訂立了一份記錄合約"],a:1,e:"技術上，一個合約已經在這兩個買主與賣主之間產\n生了，它是通過付錢與收錢等行為而訂立的，無需\n借助任何言語或文字。"},{c:"2.1.2(a)",s:"某人從一個小販那裏拿起一份雜誌，清楚地表明他要購買，技術上\n，這是",o:["行為中推斷出來的合約","契據","簡單合約","嚴格來說，這並不構成合約"],a:0,e:"技術上，一個合約已經在買主與賣主之間產生了，\n它是通過付錢與收錢等行為而訂立的，無需借助任\n何言語或文字"},{c:"2.1.2(a)",s:"就簡單合約而言，以下哪項描述是正確的?",o:["僅以書面或從行為中推斷出來的合約","從名稱來看因為合約對大部分人易於理解","簡單合約的有效性並不取決於特殊的手續","以上各項皆是"],a:2,e:"簡單合約卻不表示內容容易理解，它只是意味着合\n約的訂立是簡單、容易的。"},{c:"2.1.2(b)",s:"下列哪項或哪些不是訂立的合約正確的描述？",o:["可以是透過行為而訂立","可以是書面及經蓋章後發出","它必須是個人的合約","可以是口頭及書面訂立"],a:2,e:"合約其中一種可以是簡單合約，意味着合約的訂立\n是簡單、容易的。簡單合約分為口頭合約不經蓋章\n的書面合約， 及從行為中推斷出來的合約\n。答案C不正確"},{c:"2.1.2(b)",s:"以下哪些是有關契據的正確描述?",o:["它是成熟的簡單合約","合約的價值高","以書面形式簽發","以上各項皆是"],a:2,e:"契據是經簽署、蓋章和交付的書面文書。某些交易\n例如土地的轉讓，必須以契據達成。"},{c:"2.1.2(b)",s:"一種與非常正式並需要簽署，蓋章及送遞形式有別，易於構成的合\n約稱為",o:["契約","簡單合約","紀錄合約","不複雜合約"],a:1,e:"合約其中一種可以是簡單合約，意味着合約的訂立\n是簡單、容易的。簡單合約分為口頭合約不經蓋章\n的書面合約， 及從行為中推斷出來的合約"},{c:"2.1.2(b)",s:"以下哪種合約是保險人會以契據方式成立的？",o:["忠誠保證保險","強制性(第三者)汽車保險","擔保","以上所有各項"],a:2,e:"某些交易例如土地的轉讓，必須以契據達成。擔保\n必然是以契據形式發出的"},{c:"2.1.3",s:"如果一份合約稱為可使無效，意味著其中一方可在某種情況下讓合\n約變為無效，如果該一方並未採取有關行動",o:["另一方便可向他採取法律行動","經過一段「合理」時間後，該合約便會變為無效","經過一段「合理」時間後，該合約便不會就該種情況變為無效","為該合約支付的任何金錢均須退還"],a:2,e:"可使無效的合約，其法律效力一直維持下去，除非\n有受屈的一方，並於合理時間內提出反對，合約視\n為自訂立時起即屬無效，答案C正確"},{c:"2.1.3",s:"如果按照保單條款不可對一份不屬於無效的合約作出起訴，該合約\n可被稱為",o:["無投訴","違法","可使無效","不能強制執行"],a:3,e:"不能強制執行的合約無法在法庭上執行（或藉以起\n訴）"},{c:"2.1.3",s:"以下哪一項不屬於簡單合約必須具備元素？",o:["交付","承約","訂約的行為能力","代價"],a:0,e:"交付不屬於簡單合約必須具備元素"},{c:"2.1.3",s:"以下哪項正確描述無效的合約？",o:["保險人可以取消合約","任何一方可以取消合約","合約在法律上不存在，完全無法律效力","保險人已拒絕賠償"],a:2,e:"無效的合約指所擬訂的合約在法律上不存在，完全\n無法律效力"},{c:"2.1.3",s:"以下哪項可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含義完全相同","受屈的一方可於合理時間內把合約視為無效的決定","只有被保險人才能把保單視作可使無效(即可予以取消)"],a:2,e:"可使無效的合約是項明顯有法律效力的合約，其法\n律效力一直維持下去，除非及直至有受屈的一方把\n合約視為自訂立時起即屬無效，但須在一段合理時\n間內進行"},{c:"2.1.3",s:"一份合約由於一些要求還未完成而令致有關合約無法執行，此稱為",o:["可使無效的合約","不能強制執行的合約","無效的合約","不合法的合約"],a:1,e:"一份合約由於一些要求還未完成而令致有關合約無\n法執行，此稱為不能強制執行的合約"},{c:"2.1.3",s:"一般協議有別於合約的原因，以下有哪些或哪項的描述是正確的",o:["合約必須以書面形式訂立","合約必須有兩位以上的見證人","合約包含多項法律準則","以上所有各項"],a:2,e:"合約在法律上可強制執行的協議。協議的種類繁多\n，但不是所有的協議都有法律效力，協定涉及的內\n容必須是合法的。只有答案C正確"},{c:"2.1.3",s:"一般協議有別於合約的原因，以下有哪些或哪項的描述是正確的？",o:["合約必須以書面形式訂立","合約必須有兩位以上的見證人","合約包含多項法律準則","以上所有各項"],a:2,e:"合約可透過口頭，書面及行為形式訂立，協定涉及\n的內容必須是合法的"},{c:"2.1.3",s:"以下哪項可視為「有缺陷的合約」?",o:["簡單合約","不能強制執行的合約","行為推斷的合約","反要約"],a:1,e:"不能強制執行的合約可視為「有缺陷的合約」"},{c:"2.1.3",s:"以下項是「可使無效」的合約最佳描述?",o:["一個法律不能撤銷的合約","一個法律無法生效的合約","一個於投保階段提供錯誤投保資料的保險合約","一個法律不存在的合約"],a:2,e:"於投保階段提供錯誤投保資料的保險合約，保險人\n有可能就投保人違反最高誠信推翻保單"},{c:"2.1.3(a)",s:"如果保險人指出除非有關保險上限縮短為半年，否則不會接受某項\n口頭的投保，這項因保險人提出的建議可以構成?",o:["反承約","相反的要約","反要約","有條件的承約"],a:2,e:"這項因保險人提出的建議可以構成反要約"},{c:"2.1.3(a)",s:"保險合約中的要約人是",o:["通常是保險人","通常是被保險人","可以是保險人或被保險人","通常是中介人代表的一方"],a:2,e:"在保險中，要約人可以是投保的一方，也可以是保\n險人透過反要約的形式，表示願意承保或續保"},{c:"2.1.3(a)",s:"以下哪項有關保單的要約描述是正確的？",o:["根據普通法規定，投保人寫投保書給被遞交表格的保險人已構成\n要約的行為","適用於保險合約的要約法，明顯有別於非保險合約的要約法","沒有要約就沒有合約","非人壽保險的要約法已匯入保險業條例之中"],a:2,e:"要約是訂立合約的起點，沒有要約就沒有合約。"},{c:"2.1.3(b)",s:"如果保險人表示須就某項投保取額外保費及附加保單免賠額，才會\n接納該風險，這種由保險人提出的建議在法律上可以稱為",o:["反要約","相反的要約","有保留承約","有條件承約"],a:0,e:"如果保險人有意更改擬訂合約的條件，例如要求增\n加保費或附加保單限制，這種意向一經傳達便構成\n了反要約"},{c:"2.1.3(b)",s:"在反要約的過程中，下列哪項是不正確的？",o:["原本的要約人成為受要約人","原本的受要約人成為要約人","原本的要約內容立刻被終止並撤銷","若反要約的內容不被接納，原本的要約內容可再次有效"],a:3,e:"如果受要約人有意更改合約條件，這種意向一經傳\n達便構成了反要約，後果是原要約內容失效"},{c:"2.1.3(b)",s:"要成立任何合約，其要約",o:["必須按其原有內容而被承約","可以視乎若干條件後而被承約","必須被承約，並須以書面通知收到","總是須大體上被承約"],a:0,e:"如要成功訂立合約，承約的內容必須與要約的所有\n內容相同"},{c:"2.1.3(b)",s:"在一份建議合約上的要約對象稱為",o:["要約人","受要約人","被動人","準客戶"],a:1,e:"在一份建議合約上的要約對象稱為受要約人"},{c:"2.1.3(b)",s:"下列哪項有關〝反要約〞之陳述是正確的？\ni) 反要約出現時，原要約人會變成受要約人\nii) 反要約出現時，原受要約人變成要約人\niii) 反要約出現代表原要約的婉拒及終止\niv) 若反要約不被接納，則可以從新執行原要約",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii ,iii, iv"],a:0,e:"若反要約一方提出條件，不被受要約一方接納，原\n要約的內容便不再有效，只有選項i, ii, iii正確"},{c:"2.1.3(b)",s:"在訂立合約的過程中，「甲方」是提出要約的一方；即「要約人」\n，而「乙方」則是「受要約人」，如「乙方」不接受「甲方」的提\n議，並作出反要約",o:["「甲方」便成為「受要約人」","「甲方」仍是要約人，「乙方」仍是「受要約人」","原本的要約仍然有效","在保險合約中，永不會出現「反要約」"],a:0,e:"在反要約中，要約人「甲方」反過來成了受要約人\n，並可以接受該反要約。"},{c:"2.1.3(b)",s:"要約如何能轉變為一份有效協議?",o:["以精確的字句接納原有的內容","必須被接納及以書面通知","必須在四十八小時內承約","接受以上的條件"],a:0,e:"如要成功訂立合約，承約的內容必須與要約的所有\n內容相同，只有答案A正確"},{c:"2.1.3(c)",s:"以下哪項是簡單合約訂立時必須具備的條件？",o:["以書面形式","合約雙方年滿十八歲","合約雙方付出代價","以上各項皆是"],a:2,e:"在一個簡單合約中，雙方必須訂出各自應付出的代\n價，否則合約屬無效。"},{c:"2.1.3(c)",s:"在保險合約當中，被保險人所付出的代價是",o:["承諾每年續保","向保險人繳付的保費","只要要約及續保時出現","以上所述各項都不是"],a:1,e:"被保險人於保險合約所付的代價，是向保險人支付\n保費的承諾"},{c:"2.1.3(c)",s:"在簡單合約上，就被保險人承諾繳付保費，而保險人則需承諾支付\n有效的索償，這是指甚麼合約元素？",o:["要約","訂約的行為能力","承約","代價"],a:3,e:"在保險上，代價就是被保險人向保險人支付保費的\n承諾及保險人依照保單條款的規定付款或給予補償\n的承諾。"},{c:"2.1.3(c)",s:"在一份保險合約上，保險人提供的代價就是",o:["索債的支付","支付有效索償的承諾","向保險代理人支付的佣金","誠實"],a:1,e:"在一份保險合約上，保險人提供的代價就是支付有\n效索償的承諾"},{c:"2.1.3(c)",s:"在一項屬簡單合約的保險上，代價",o:["必須由被保險人及保險人雙方付出","只須由被保險人付出","只須由保險人付出","毋須由被保險人付出，但合約訂立需要以書面"],a:0,e:"在一項屬簡單合約的保險上，代價必須由被保險人\n及保險人雙方付出"},{c:"2.1.3(c)",s:"甚麼是代價?",o:["它必須由雙方在合約中訂定","這是合約的一方對另一方的承諾","這是合約的一方對另一方的義務","以上各項皆正確"],a:3,e:"代價是合約的一方就另一方的承諾所付出的代價。\n在一個簡單合約中，雙方必須訂出各自應付出的代\n價；否則合約屬無效。以上各項皆正確"},{c:"2.1.3(c)",s:"在一個保險合約中，被保險人所付出的代價是",o:["填受投保書","始初要約，其後續保","繳交保費","以上各項皆是"],a:2,e:"在一個保險合約中，被保險人所付出的代價是繳交\n保費"},{c:"2.1.3(c)",s:"安琪在登機前購買一份旅遊保險，保險人容許她在旅程後繳付保險\n費。安琪不幸在旅程中斷了一條腿，保險人拒絕賠付安琪有關的醫\n療費用，請問保險人有權這樣做嗎？",o:["沒有。根據承保商專業守則，保險人須就投保人合理的期望賠","沒有。一張旅遊保險合約已經生效","有。保險人若賠付只出於同情","有。安琪沒有交保費"],a:1,e:"如果所保事故在支付已承諾的保費以前已經發生，\n被保險人仍然享有索償權，而保險人則另外有權追\n討未繳清的保費，答案B正確"},{c:"2.1.3(c)",s:"蘇先生在電話要求一份機器全險保障，保險人承諾在一星期後發出\n保單。電話對話一小時後，該組機器在火災中被毀。請問有否一份\n有效的機器全險合約保障？",o:["沒有，因未曾出現承諾","沒有，因保單未發出","有，因保障在承諾一刻生效","有，追溯性保單保障機器損失"],a:2,e:"如果所保事故在支付已承諾的保費以前已經發生了\n，被保險人仍然享有索償權。在保險上，代價就是\n被保險人向保險人支付保費的承諾；及保險人依照\n保單條款的規定付款或給予補償的承諾。"},{c:"2.1.3(c)",s:"在保險上，保險人的代價是：\ni.被 保險人向保險人支付保費的承諾\nii.保 險人依照保單條款的規定給付賠償\niii.保 險人依照保單條款的規定收取款項\niv.保 險人依照保單條款的規定給予補償的承諾",o:["ii,iv","只有ii","只有i","只有iii"],a:0,e:"在保險上，代價就是：保險人依照保單條款的規定\n付款或給予補償的承諾。"},{c:"2.1.3(c)",s:"保險人於保險合約所付的代價是",o:["填寫投保書","提出要約後並承諾續保","依照保單條款的規定支付索償的承諾","以上各項皆不正確"],a:2,e:"保險人於保險合約所付的代價是依照保單條款的規\n定支付索償的承諾"},{c:"2.1.3(d)",s:"在簡單合約中，「訂約的行為能力」是指訂立合約的能力。在保險\n合約中，這項要求適用於",o:["投保人和保險人","未達成年歲數的投保人","投保人，但不一定適用於保險人","保險人，但不一定適用於投保人"],a:0,e:"「訂約的行為能力」是指訂立合約的能力。在保險\n合約中，這項要求適用於投保人和保險人"},{c:"2.1.3(d)",s:"有關「立約行為能力」，下列哪項陳述是正確的？\ni) 未成年者的立約能力受到限制\nii) 是指訂立合約的法律能力\niii) 精神病者的立約能力受到限制\niv) 是指有關業務開展的合法授權",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii ,iii, iv"],a:3,e:"訂約的行為能力是指訂立合約的法律能力。精神錯\n亂或未成年的個人可以選擇推翻他們所訂立的合約\n。又以公司為例，它們不得超越其法律權力而行事\n。以上各項皆正確"},{c:"2.1.3(d)",s:"訂約的行爲能力解作",o:["可供選擇的再保險","預計投保金額","保險人承保大規模公司的能力","訂立合約的法律能力"],a:3,e:"訂約的行為能力是指訂立合約的法律能力。"},{c:"2.1.3(d)",s:"訂約的行爲能力是簡單合約其中一項要求，其意義是",o:["未成的人沒有能力訂立合約","其含義是指訂立合約的法律能力","精神錯亂的人完全沒有能力訂立合約","以上各項皆不是"],a:1,e:"訂約的行為能力是指訂立合約的法律能力。"},{c:"2.1.3(d)",s:"以下哪項不是簡單合約具備的元素？",o:["合法性","代價","訂約的行為能力","合理便宜的價格"],a:3,e:"合法性，代價，訂約的行為能力都屬六項「合約元\n素」的準則，答案D不正確"},{c:"2.1.3(e)",s:"「一份協議的內容必須是合法的」，此句子形容合約元素中的哪一\n項",o:["訂立的行為能力","代價","合法性","訂立法律關係意向"],a:2,e:"合約協定涉及的內容必須是合法的。例如，涉及\n殺人或其他犯罪行為的合約是無效的"},{c:"2.1.3(f)",s:"有簽訂保單時可能會出現誤解。在一份家居保單中，投保人想保障\n家居財物，但簽訂的保單卻保障樓宇結構，這種合約是無效的，這\n是基於合約的那個元素？",o:["代價","立約能力","合法性","各方意向"],a:3,e:"完整合約要素包括訂立法律關係的意向，合約如要\n有效，各方必須清晰地表示有意給有關合約具有法\n律效力，答案D正確"},{c:"2.1.3(f)",s:"簡單合約要素有多種，其中訂立協議雙方明確自己的目的，並知道\n有關條款具有法律效力，此要素稱為",o:["訂立法律關係的意向","合法性","要約及承約","代價"],a:0,e:"完整合約要素包括訂立法律關係的意向，合約如要\n有效，各方必須清晰地表示有意給有關合約具有法\n律效力，答案A正確"},{c:"2.1.3(f)",s:"一份協議是缺乏與另一方訂立法律關係的意向情況下訂立，因此",o:["技術上它是合約","技術上它是協議","不能是合約","受屈一方有權索取賠償"],a:2,e:"完整合約要素包括訂立法律關係的意向，合約如要\n有效，各方必須清晰地表示有意給有關合約具有法\n律效力"},{c:"2.1.3(f)",s:"以下哪幾項是構成有效合約的「合約元素」?\ni. 要約及承約\nii. 公平性\niii. 代價\niv. 訂立法律關係的意向",o:["i,ii,iii","i,ii,iv","i,iii,iv","i ,ii,iii,iv"],a:2,e:"公平性不是構成有效合約的「合約元素」，選項ii\n不正確"},{c:"2.1.4",s:"“非合約的一方第三者，便沒有責任履行該合約的條款”，這描述\n普通法中的哪一種?",o:["合約法","合約的相對性","訂約的行為能力","合法性"],a:1,e:'合約的相對性的其中一個原則是"非合約的一方第三\n者，便沒有責任履行該合約的條款"'},{c:"2.2",s:"根據代理法，下列哪項有關保險代理人的陳述是正確?",o:["保險代理人必代表被保險人","保險代理人對本身的委託人必負起轉承的責任","保險經紀不受代理法約束","保險代理人即如所有代理人，代表本身的委託人"],a:3,e:"代理人在這裏是指一名代表委託人的人，在代理法\n上，保險代理人或保險經紀，他們都屬於代理人。\n委託人對代理人的行為須負起轉承責任，只有答案D\n正確"},{c:"2.2",s:"保險代理人的委託人一般是?",o:["保險人","被保險人","既非保險人亦非被保險人","兩者皆是保險人及非保險人"],a:0,e:"保險代理人的委託人是保險人(亦即是委任該保險代\n理人的保險公司)"},{c:"2.2",s:"代理法",o:["只適用於保險中介人","適用於保險代理人而不是保險經紀","適用於保險經紀而不是保險代理人","適用的範圍比應用於保險為廣泛"],a:3,e:"代理法適用的範圍比它在保險代理人方面的應用廣\n泛得多"},{c:"2.2",s:"根據代理法",o:["保險代理人及保險經紀兩者都屬於「代理人」","保險代理人及保險經紀兩者都不屬於「代理人」","保險代理人屬於「代理人」，但保險經紀則不是","保險經紀屬於「代理人」，但保險代理人則不是"],a:0,e:"保險代理人及保險經紀兩者都屬於「代理人」"},{c:"2.2",s:"有關於本港的保險中介人",o:["根據定義，所有銀行都是保險中介人","它只包括保險代理人及其僱員","它包括保險公司及其僱員","它包括保險經紀和保險代理人"],a:3,e:"保險中介人包括保險經紀和保險代理人"},{c:"2.2",s:"以下哪項法律原則，某人受其代理人授權作為所約束？",o:["「買者自當」","「最高誠信」","「代理人不必為其授權作為承擔個人的法律責任」","「透過他人行事與自己親自執行並無分別」"],a:3,e:"代理法被一個法律原則支配着，「透過他人行事與\n親自執行並無分別」。代理人代表委託人行事，那\n麼無論其結果是好是壞，經授權的行為，或有時甚\n至是沒有授權的行為會對委託人產生約束力 。"},{c:"2.2",s:"「透過他人行事與自己親自執行並無分別」法律原則是來自",o:["合約法","代理法","侵權法","保險業條例"],a:1,e:"代理法律原則是「透過他人行事與親自執行並無分\n別」，代理人代表委託人行事，無論其結果好壞，\n經授權的行為或沒有授權的行為，都會對委託人產\n生約束力"},{c:"2.2",s:"轉承責任是指",o:["一種攤分的責任","一種刑事法律的責任","因基於一種與他人的關係對他人的行為責任","代理人對委託人的行為負上責任"],a:2,e:"轉承責任是指因基於一種與他人的關係對他人的行\n為責任"},{c:"2.2",s:"根據《保險業條例》，作爲保單持有人的代理人，經營在香港或從\n香港洽談或安排保險合約的業務的人，稱爲保險",o:["中間人","代理人","經紀","顧問"],a:2,e:"根據《保險業條例》，作爲保單持有人的代理人，\n經營在香港或從香港洽談或安排保險合約的業務的\n人，稱爲保險代理人"},{c:"2.2",s:"在法律上「一種透過他人行事與自己親自執行並無分別」的原則稱\n為",o:["轉承責任","必要責任","替代責任","不容反悔代理權"],a:0,e:"在法律上「一種透過他人行事與自己親自執行並無\n分別」的原則稱為轉承責任"},{c:"2.2",s:"以下哪項對代理法的描述是正確的?\ni. 委託人受其代理人的行為所約束\nii. 代理人受其委託人的行為所約束\niii. 委託人受其代理人的行為而須負起轉承責任\niv.代理法只適用於保險代理人及經紀",o:["i,ii,iii","i,iii","ii,iii","i,ii,iii,iv"],a:1,e:"代理關係中的委託人，受其代理人的行為所約束，\n所以，委託人須就其代理人的作為或不作為負起轉\n承責任，另外，代理法適用的範圍，比保險代理人\n方面的應用廣泛得多，只有選項i,iii\n正確，正確答案是B"},{c:"2.2",s:"以下哪項對代理法的描述是正確的?\ni.保險人透過保險代理人行事與親自執行沒有分別\nii.委託人需對代理人行為負起轉承責任\niii.保險代理人及保險經紀有能力就保險人的行為負起轉承責任\niv.代理關係必須透過書面方式訂立而產生",o:["i , ii","i, ii, iii","ii,iii","i, ii, iii, iv"],a:0,e:"代理關係是指存在於委託人與其代理人之間的一種\n關係。它的出現是基於事實，而不一定經過一個精\n確的委任代理過程。委託人須對其代理人的行為負\n上轉承責任責任。"},{c:"2.2(a)(b)",s:"以下哪頂是代理法的描述是正確的?",o:["僅用於保險業務","根據代理法，保險經紀不屬代理人","委託人受代理人沒有授權的行為行為所約束","以上各項都不正確"],a:2,e:"代理人代表委託人行事，無論其結果是好是壞，經\n授權的行為，有時甚至是沒有授權的行為，都會對\n委託人產生約束力"},{c:"2.2.1",s:"保險代理人在安排一份保險時，為保險人行事，當中涉及兩份合約\n。其中一份存在於保險代理人與保險人之間，另一份則存在於",o:["保險代理人與第三者之間","保險人與保單持有人之間","保險代理人與保單持有人之間","保險人與保險經紀之間"],a:1,e:"保險代理人在安排一份保險時，為保險人行事，當\n中涉及兩份合約。其中一份存在於保險代理人與保\n險人之間，另一份則存在於保險人與保單持有人之\n間"},{c:"2.2.1",s:"要構成代理關係，下面哪項必須存在？",o:["該關係受代理合約所支配","訂約的行為能力","該關係必須通過法律認可的方式產生","代價"],a:2,e:"根據法律條文，某些特定的情況可以當作產生了代\n理關係。"},{c:"2.2.1",s:"一名母親指使其小孩到一家雜貨店購買雞蛋，意味著",o:["商店與該名母親之間訂立了一份銷售合約","小孩與該名母親之間訂立了一份銷售合約","小孩負上轉承責任","代理法約束著小孩的行為"],a:0,e:"商店與該名母親之間訂立了一份銷售合約，因為母\n親作為委託人承擔了支付貨款的法律責任 。"},{c:"2.2.2",s:"以下哪項是追認的正確描述？",o:["作出追溯性的授權批准一些事前沒有授權的行為","給予代理的一項明確的授權","出於緊急情況的授權行為","根據經蓋章的合約給予的權限"],a:0,e:"追認是指對某行為授予追溯權。即雖然代理人在行\n事時並未取得授權，但只要委託人事後確認該行動\n，就有效地產生了一種追溯性的授權。"},{c:"2.2.2",s:"雖然在行動時並未獲授權，但只要委託人事後確認該行動，就如同\n給予一種追溯性的授權。此種情況下產生之代理關係稱為",o:["通過協議","明示協議","追認","隱含授權"],a:2,e:"追認是指對某行為授予追溯權。即雖然\\代理人在行\n事時並未取得授權，但只要委託人事後確認該行動\n，就有效地產生了一種追溯性的授權。"},{c:"2.2.2",s:"追認是指",o:["代理人確認委託人","委託人確認代理人","委託人確認某代理的「過去」行動","委託人無須為代理人的行為負責任，除非代理人作出追認"],a:2,e:"追認是指對某行為授予追溯權。雖然代理人在行事\n時並未取得授權，但只要委託人事後確認該行動，\n就有效地產生了一種追溯性的授權。"},{c:"2.2.2",s:"由委託人追認而確認的代理關係是指",o:["委託人已有效地「追溯」他當時代理人的動作的批准","在代理人行動前委託人已經表明不授權","代理人曾在緊急情況下替委託人辦事","代理人進行類似過去曾被批准的未授權行動"],a:0,e:"追認是指對某行為授予追溯權。雖然代理人在行事\n時並未取得授權，但只要委託人事後確認該行動，\n就有效地產生了一種追溯性的授權。"},{c:"2.2.2",s:"代理的追認是指？",o:["代理人追認某次行動","代理人確認委託人","委託人追認代理人行動","委託人無須為代理負法律責任，除非代理作出追認"],a:2,e:"代理人在行事時並未取得授權，但只要委託人事後\n確認該行動，就有效地產生了一種追溯性的授權"},{c:"2.2.2",s:"代理關係可以透過以下哪些途徑產生?\ni.明 示協議\nii.隱 含協議\niii.追 認\niv.代 理人出錯",o:["i,ii","i,ii,iii","iii,iv","以上皆是"],a:1,e:"代理關係可以透過明示，隱含或追認方式產生"},{c:"2.2.2",s:"代理關係的產生必須存在以下哪項條件?",o:["該關係可以是通過代理協議產生的","訂約行為能力","該關係必須得到法律認可的關係","代價"],a:0,e:"代理關係是指存在於委託人與其代理人之間的一種\n關係。它的出現是基於事實，而不一定經過一個精\n確的委任代理過程。"},{c:"2.2.3",s:"必要代理人是指一名代理人",o:["替未成年人士行事(未滿18歲兒童)","一位按明確的指示行事的人","委託人事後確認該行動","當該名代理人於無可非議情況下代表委託人"],a:3,e:"在危急的情況下，必要地為前者採取行動的話，即\n使代理人沒有取得明示權限，卻持有必要權限作出\n該等行為，並透過該等行為成為必要代理人"},{c:"2.2.3",s:"有一日某人在街上發現了一條昂貴的純種狗，他很努力地尋找失主\n。幾天後，他尋找到失主，他在照顧這狗隻期間的狗糧費用、獸醫\n費用，涉及相當數量的金錢，他爭辯有權向失主取回這些相關費用\n。因為他在照顧狗隻期間可被稱為",o:["追認代理人","必要代理人","明示代理人","不容反悔代理人"],a:1,e:"如某人受着迫切的危害而不存在向他通報的機會，\n一名現有代理人在這個危急的情況下必地為該人採\n取行動的話，可以說該代理人持有必要權限作出該\n等行為，並透過該等行為成為必要代理人。"},{c:"2.2.3",s:"「必要代理人」指一名代理人，他",o:["替一名未成年人士行事(未滿18歲)","已經獲得明示(口頭或書面)指令","事後被有關委托人追認為代理人","因當時情況所需而無可非議地替另一人行事"],a:3,e:"「必要代理人」指一名代理人，他因當時情況所需\n而無可非議地替另一人行事"},{c:"2.2.3",s:"「明示權限」的中的明示是指",o:["與明示合約條款中的「明示」的意思相同","於迫切或危急情況發生後必要的授權","委託人對代理人已作出具體的指示","委託人對代理人的指示總是書面的"],a:2,e:"明示權限是指以口頭或書面方式故意授予的實際權\n限，最貼近這個定義的答案是C"},{c:"2.2.3",s:"代理人的權限包括：\ni) 實際權限\nii) 表面權限\niii) 非表面權限\niv) 必要權限",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"代理人的權限包括實際權限，表面權限，必要權限\n及不容反悔的代理權，只有選項 i, ii, iv正確"},{c:"2.2.3",s:"以下哪項是指「明示權限」?",o:["以口頭以外的形式發出","必須以書面的合約形式發出","以合約蓋章形式","明確說明代理人的責任"],a:3,e:"明示實際權限是以口頭或書面方式故意授予的實際\n權限。可明確說明代理人的責任"},{c:"2.2.3(a)",s:"委託人明示或隱含地向代理人表明同意代理人代表委託人或替其行\n事，是屬於下列哪項代理人的權限",o:["實際權限","表面權限","必要權限","不容反悔的代理權"],a:0,e:"委託人明示或隱含地向代理人表明同意代理人代表\n委託人或替其行事，屬於實際權限"},{c:"2.2.3(a)",s:"「明示權限」的明示是指",o:["與明示合約條款中的「明示」的意思相同","於迫切或危急情況發生後必要的授權","委託人已明確地指示代理人","委託人對代理人的指示必須是書面的"],a:2,e:"「明示權限」的明示是指委託人是以口頭或書面方\n式明確地指示代理人"},{c:"2.2.3(a)",s:"明示實際權限是代表",o:["得到書面的授權","僅得到一份書面的授權","可以是書面或口頭的授權","口頭以外的方式授權"],a:2,e:"明示實際權限是以口頭或書面方式故意授予的實際\n權限。可明確說明代理人的責任"},{c:"2.2.3(a)",s:"明示權限是",o:["由委託人迅速地給予的","談判經蓋章的合約的授權","祇可談判書面的合約的授權","委託人明確地以口頭或書面形式賦予的授權"],a:3,e:"明示權限是委託人明確地以口頭或書面形式賦予的\n授權"},{c:"2.2.3(a)",s:"保險人賦予「明示權限」給代理人，以下哪項有關的描述是正確？",o:["由被保險人而非保險人選出代理人","代理人的所有資料必須顯示於保單內","代表委託人替其行事","代理人須於指定時間內完成所有商議工作"],a:2,e:"明示實際權限是以口頭或書面方式故意授予的實際\n權限，代理人代表委託人替其行事"},{c:"2.2.3(b)",s:"就表面權限而言，權限問題與代理關係是有所相關及分別，以下哪\n些或哪項是正確的?",o:["局限在委託人與第三者之間的關係","代理人的權限是委託人對第三者表明同意產生的","在無授權情況之下，而幫助委託人訂立合約時，會令委託人受代\n理人行為約束","以上各項皆是"],a:3,e:"A,B及C的描述正是表面櫂限的正確描述"},{c:"2.2.3(b)",s:"以下哪項是對「表面授權」的正確描述?",o:["這個不可能的","法律上是不容許的","以口頭或書面形式作出授權","委託人以行為表明同意代理人已獲授權"],a:3,e:"表面權限，是當代理人被看似擁有授給他的實際權\n限還要大的時應用的，答案D正確"},{c:"2.2.3(b)",s:"以下哪個是表面權限的正確描述",o:["明示權限","沒有實際權限","是局限於委託人與第三者之間的關係","實際權限"],a:2,e:"表面權限是當一個代理人的權限是透過委託人對第\n三者表明同意而產生的，該權限便是表面而非實際\n。是局限於委託人與第三者之間的關係"},{c:"2.2.3(b)",s:"表面權限意味著",o:["授權不存在，而且代理人的行為會對委託人並沒有約束力","基於過去的交易，代理人的行為會對委託人產生約束力","權限是透過委託人表明同意而產生的，並可能會對委託人產生約\n束力","在緊急的情況下持有必要權限為委託人採取行動，並成為必要代\n理人"],a:1,e:"表面權限是當一個代理人的權限是透過委託人對第\n三者(不是委託人)表明同意而產生的，基於過去的\n交易，代理人的行為會對委託人產生約束力"},{c:"2.2.3(c)",s:"如果出於人道或其他合理的原因，某人承擔並支付代理另一人行事\n的開支，則即使他人沒有在產生開支期間或之後授權，此人也可以\n被認為是他的代理人，這種代理關係的成立是基於",o:["明示權限","不容反悔","必要權限","追認"],a:2,e:"如某人受着迫切的危害而不存在向他通報的機會，\n一名現有代理人在這個危急的情況下必地為該人採\n取行動的話，可以說該代理人持有必要權限作出該\n等行為，並透過該等行為成為必要代理人。"},{c:"2.2.3(c)",s:"有時，一個人替另一個人繳了款或辦了其他事，雖然事前未得到委\n託人的准許，如果作的事是合理及必要時，那付款/作事的人可能有\n的技術上權限",o:["一個明示代理人","不容反悔的代理人","必要的代理人","依據表面權限"],a:2,e:"如某人受着迫切的危害而不存在向他通報的機會，\n一名現有代理人在這個危急的情況下必地為該人採\n取行動的話，可以說該代理人持有必要權限作出該\n等行為，並透過該等行為成為必要代理人。"},{c:"2.2.3(c)",s:"必要權限可能在以下哪種情況產生？",o:["由委託人的明示權限而產生","如果委託人以追溯形式確認對代理人的授權","由一位假定委託人的行為而產生","如果代理人在緊急情況下必須代表委託人行事"],a:3,e:"必要權限是代理人在危急的情況下必須代表委託人\n行事"},{c:"2.2.3(c)",s:"某人在某時為他人的最佳利益而行事，雖然他事前並沒有獲得授權\n，但在法律上卻持有這種權限‧並被視為",o:["必要代理人","緊急情況下代理人","具有追溯性授權的代理人","自動獲授權的代理人"],a:0,e:"如某人受着迫切的危害而不存在向他通報的機會，\n一名現有代理人在這個危急的情況下必地為該人採\n取行動的話，可以說該代理人持有必要權限作出該\n等行為，並透過該等行為成為必要代理人。"},{c:"2.2.3(c)",s:"在沒有獲授權的情況下，為另一方作了某些事情，而該行為是基於\n合理及必要，在此情況下，這人便成為了",o:["不容反悔代理人","明示權限代理人","必要代理人","實際權限代理人"],a:2,e:"如某人受着迫切的危害而不存在向他通報的機會，\n一名現有代理人在這個危急的情況下必地為該人採\n取行動的話，可以說該代理人持有必要權限作出該\n等行為，並透過該等行為成為必要代理人。"},{c:"2.2.3(c)",s:"第三者根據一名〈假定）委託人的行為，覺得一名〈假定）代理人\n為委託人的代理〈其實並沒有授權），這類代理關係稱為",o:["明示代理","不容反悔代理","必要代理","追索代理"],a:1,e:"不容反悔的代理權是當一名據稱代理人，在完全沒\n被授權，但卻被容許看似獲授權時應用的。"},{c:"2.2.3(c)",s:"如果需要或出於人道或其他合理的原因，某人代理另一人行事的開\n支，即使沒有獲授權，此人也可以被認為是他的代理人，這種代理\n關係的成立是基於以下那項？",o:["實際權限","表面權限","必要權限","不容反悔"],a:2,e:"必要權限是:當一名現有委託人的財產或權益受着迫\n切的危害，而有一名現有代理人在這個危急的情況\n下，必要地採取行動，即使沒有取得明示權限，透\n過該等行為成為必要代理人。"},{c:"2.2.3(d)",s:"不容反悔的代理權是來自",o:["明示權限","法定條文","事後對代理人的行為所作的明確指示","據稱的委託人的行為"],a:3,e:"不容反悔的代理權的其中一項法則，是當據稱代理\n人完全沒被授權，但卻被容許看似獲委託人授權時\n應用的。"},{c:"2.2.3(d)",s:"若保險人根據被保險人的行為，合理地判斷一位（其實沒有被授權\n的）事務律師具備授權來替被保險人行事，那麼根據以下哪項原則\n，被保險人受該事務律師的行為所約束？",o:["明示權限","不容反悔的代理權","追認代理","必要權限"],a:1,e:"如果有人允許他人表示另一人是他的代理人，而他\n不能否定該代理人的權限。這代理權法則稱為不容\n反悔的代理權"},{c:"2.2.3(d)",s:"如果有人允許他人表示另一人是他的代理人，而他不能否定該代理\n人的權限。這代理權法則稱為",o:["實際權限","必要權限","表面權限","不容反悔的代理權"],a:3,e:"如果有人允許他人表示另一人是他的代理人，而他\n不能否定該代理人的權限。這代理權法則稱為不容\n反悔的代理權"},{c:"2.2.4",s:"以下哪項不屬於代理人對委託人的責任？",o:["遵從指示","親自執行","所有帳目必須以電腦形式記錄","必須保存與代理業務有關的足夠紀錄"],a:2,e:"所有帳目必須以電腦形式記錄不屬於代理人對委託\n人的責任"},{c:"2.2.4",s:"如果一名代理人在履行職責時沒具有「應有的謹慎及技巧」，而最\n後令委託人蒙受損失，該名委託人",o:["擁有向該名代理人要求賠償的權利","沒有向該名代理人要求賠償的權利","只有在構成欺騙行為時才可向該名代理人要求賠償","只能追索該名代理人所引致損失的50%,因為均衡才是公平"],a:0,e:"委託人可以就代理人欠缺謹慎的行為引致的損失反\n過來向代理人要求賠償"},{c:"2.2.4",s:"有關代理人必須對委託人所收取金錢進行「報帳」，意思是",o:["只能間中提供回佣","代理人對代表委託人所收取的金錢或其他物件報帳，必須確定保\n存足夠的記錄以反映其代理業務的狀況","代理人必須書面紀錄與委託人的認真溝通","代理人以委託人的名義收取的所有的物品必須在3天之內交回委託\n人"],a:1,e:"「報帳」，意思是代理人對代表委託人所收取的金\n錢報帳，確定保存足夠的記錄以反映其代理業務的\n狀況"},{c:"2.2.4",s:"以下那項代理人對委託人的責任的描述是不正確的",o:["遵從委託人的合法指示","只向委託人介紹有利可圖的生意","不能下放權力，除非獲得明示授權","要有適當的謹慎及技巧"],a:1,e:"向委託人介紹有利可圖的生意不屬代理人對委託人\n的責任"},{c:"2.2.4",s:"一名代理人在下列哪種情況，可以把他的權限及責任下放給一位分\n代理人？",o:["任何時候，只要他願意便可","只當他具備這方面的權限","只要他認為合理才可","他可以這樣做，並有權從委託人收取雙份佣金"],a:1,e:"代理人不能把取得的代理權及承擔上的職責，下放\n給他人(分代理人），除非他具有這樣做的權限。"},{c:"2.2.5",s:"以下哪項不是委託人對代理人的責任",o:["給予代理人協定的報酬","給予代理人協定的正當的開支","給予代理人合理的報酬","保證代理人的報酬會因價格不同而有所調整"],a:3,e:"保證代理人的報酬會因價格不同而有所調整不是委\n託人對代理人的責任"},{c:"2.2.5",s:"有關向代理人支付的報酬及開支，以下哪一項或哪些是正確的?",o:["需按照之前的協定支付佣金","如無任何協議，應支付合理的金額","受託人必須於指定或合理期內支付","以上所有各項皆是"],a:3,e:"代理人有權收取經雙方協定的佣金或其他報酬，委\n託人須於合理時間或任何指定的期限內支付。以上\n所有各項皆正確"},{c:"2.2.5",s:"有關向代理人支付的開支，以下哪一項或哪些是正確的？",o:["按照之前的協定支付佣金","確保按照市場規定支付報酬","按照協定支付正當地招致的開支","A 和 C 都正確"],a:3,e:"代理人有權收取經雙方協定的佣金或其他報酬，委\n託人須於合理時間或任何指定的期限內支付。A 和\nC 都正確"},{c:"2.2.5",s:"除非代理人協議另有訂明，否則委託人必須替代理人支付以下哪類\n開支？",o:["代理人替委託人所引致的所有合理開支","代理人之行政開支","代理人之任何種類開支","開支以代理人替委託人收回款項的50%為上限"],a:0,e:"在符合代理協定的任何明示條件下，委託人必須對\n代理人代表其行事時適當及合理地招致的費用及開\n支，予以償還。例如理賠代理人支付的法律辯護費\n用。"},{c:"2.2.5",s:"代理人代表委託人行事時招致的費用，委託人應",o:["只支付與交通有關的費用","只支付委託人事前同意的費用","向代理人報銷行事時適當及合理地招致的費用及開支","只支付在符合代理協定條件下的費用"],a:2,e:"在符合代理協定的任何明示條件下，委託人必須對\n代理人代表其行事時適當及合理地招致的費用及開\n支， 予以償還。"},{c:"2.2.6",s:"下列哪項或哪些屬於保險代理協議终止的途徑?",o:["撤銷","衝突或沒有達成協議","不忠誠","以上所有各項"],a:0,e:"撤銷屬於代理協議终止的其中一項途徑"},{c:"2.2.6",s:"代理人可於下列哪种情況終止合約？",o:["委託人已達退休年齡","委託人實在地違反了合約","委託人成立有限公司","以上各項都符合"],a:1,e:"如果委託人和代理人的任何一方基本地違反了合約\n，另一方便可以終止合約"},{c:"2.2.6",s:"雙方終止代理關係",o:["是絕對可以","除非合約上附帶有關條例，否則不可以","需對保險代理作出金錢上的賠償","足以令與第三者所定立的現存合約無效"],a:0,e:"所有協議均可通過雙方的協商同意而終止"},{c:"2.2.6",s:"假如一方為法人團體的公司，它一旦清盤，協議將會",o:["立即終止","自動傳予清盤人購買","自動傳予董事局購買","自動傳予股東購買"],a:0,e:"假如任何一方為法團體公司，它一旦清盤，協議將\n會同樣地終止。"},{c:"2.2.6",s:"需要甚麼規定才能延續一份為期一年的協議?",o:["只需委託人同意便可","只需代理人同意便可","需在委託人及代理人雙方同意下才可延續","自動延續"],a:2,e:"如果協議只在特定的時間內生效，那麼期限一到\n便告終止。"},{c:"2.2.6",s:"如果代理協議在生效六個月後變成非法，以下哪項有關該協議的描\n述是正確的?",o:["即時終止","必須待至期限終結","其中一方提出便可終結","雙方同意便可終結"],a:0,e:"如果代理關係或代理協議的履行不再為法律所容許\n的話，協議便會自動終止，需在委託人及代理人雙\n方同意下才可延續"},{c:"2.2.6",s:"在給予通知及/或代價補償的合約條文下，協議可在何時撤銷?",o:["在協議生效時間前","在協議生效時間內","在協議生效的頭七天內取消","協議在任何時間都不能取消"],a:1,e:"如果該項協議只在特定的時間內生效，那麼期限一\n到便告終止，答案B正確"},{c:"2.2.6",s:"於合約條款中，哪方可在協議有效期間內撤銷協議?",o:["委託人，不是代理人","代理人，不是委託人","委託人或代理人","不是委託人；也不是代理人"],a:2,e:"於合約條款中，委託人或代理人可在協議有效期間\n內撤銷協議"},{c:"2.2.6",s:"下列哪種情況下，代理人可以撤銷協議？",o:["這未被明文禁止","包含一項取消條文","委託人沒有在合理時間內支付報酬","委託人已經精神錯亂"],a:1,e:"在符合合約中有關給予通知或補償的條款下，委託\n人和代理人的任何一方都可以在協議有效期間撤銷\n取消"},{c:"2.2.6",s:"若委託人對其代理人作出違反責任的行為，下列哪項情況被視為正\n確?",o:["此乃屬於刑事罪行","在法律上，代理人沒有追討權","代理人可以運用其法律權利向委託人採取行動","所有經此代理人而辦理的保單變為失效"],a:2,e:"如果委託人和代理人的任何一方基本地違反了合約\n，另一方便可以終止合約，並有權要求賠償"},{c:"2.2.6",s:"以下哪一方或多方精神錯亂可構成終止保險代理合約理由",o:["委託人(自然人)","(法團)代理人的董事","保險公司的常務董事","以上任何一方"],a:0,e:"如果委託人和代理人的任何一方因精神錯亂而不再\n能夠履行協議，則協議會自動終結。"},{c:"2.2.6",s:"以下哪一項是代理人精神錯亂的處理方法？",o:["可以終止合約","由代理人的最近親代替成為代理","維持代理合約直至代理人康復","確保繼續支付佣金給代理人"],a:0,e:"精神錯亂屬於代理協議终止的其中一項途徑"},{c:"2.2.6",s:"以下哪項或哪些關於一份法律開支保險合約是不正確的？",o:["不是所有協議都具有法律效力","必須是經蓋章的","是一份可強制執行的協議","嚴格來說，合約是無形的"],a:1,e:"事實上，絕大部分的保險合約都屬於「簡單」合約\n。技術上，保險合約無需書面證明也能生效，答案B\n不正確"},{c:"2.2.6",s:"如果一項代理協議年期為一年，該年期屆滿時協議便",o:["必須繼續，因為代理人覺得需要","必須繼續，因為委託人覺得需要","便告終止，除非雙方另作安排","自動繼續，除非雙方另作安排"],a:2,e:"如果代理關係或代理協議的履行不再為法律所容許\n的話，協議便會自動終止，需在委託人及代理人雙\n方同意下才可延續"},{c:"2.2.6",s:"以下哪項或哪些有關由於精神錯亂而導致代理人關係的終止的描述\n是正確的？",o:["只有代理人可終止而不能是委托人","只有委托人一方可終止而不能是代理人","代理人和委托人（自然人）均可終止","代理人和委托人均沒有權力終止"],a:2,e:"如果委託人和代理人的任何一方因精神錯亂不再能\n夠履行協議，則協議會自動終結"},{c:"3.1",s:"就一項保險的標的，於法律上擁有權利，這是",o:["最高誠信","可保權益","轉讓權益","以上各項皆不是"],a:1,e:"就一項保險的標的，於法律上擁有權利，這是可保\n權益"},{c:"3.1",s:"就標的物的法律認可關係，給予某人購買保險的權利，這是",o:["最高誠信","可保權益","彌償","代位"],a:1,e:"就標的物的法律認可關係，給予某人購買保險的權\n利，這是可保權益"},{c:"3.1",s:"彌償及可保權益這兩項保險原則",o:["在財務利益方面存在著密切關聯","完全沒有共通之處","各自有完全相反的用意","尋求確立損失的有效原因"],a:0,e:"「權益」一詞是指一種與某物件或與某人之間的財\n務關係。"},{c:"3.1",s:"以下哪項是對可保權益的不正確陳述?",o:["適用於所有類型保險","通常形容與保險標的有財務上的關係","如保單持有人作為保險標的之人壽保險時，並不適用","與保險標的的關係必須為法律上可認可的"],a:2,e:"每個人對自己的生命、肢體等均享有可保權益，同\n樣也對自己的配偶的生命享有可保權益。答案C不正\n確"},{c:"3.1",s:"以下哪項不符合可保權益所要求的條件",o:["有可受保的東西","有關保險標的必須是有形的","該東西為有關保險的標的","對保險標的必須是一種法律認可的關係"],a:1,e:"可保權益可以在不同的情況下產生，例責任保險及\n其他合法權利保險是無形的"},{c:"3.1",s:"以下哪項不是可保權益的先決條件?",o:["對保險標的一種法律認可關係","保險標的是屬於可受保的","保險標的是屬於法律責任，財產或法律權利","物件必須是保險的標的"],a:2,e:"可保權益可以在不同的情況下產生，除了法律責任\n，財產或法律權利，還有人身保險，答案C不正確"},{c:"3.1",s:"於一般保險中，理賠時不需考慮下列哪項?",o:["分擔","計算未償還的保單貸款","代位","比例分攤"],a:1,e:"於一般保險中，理賠時不需考慮計算未償還的保單\n貸款"},{c:"3.1",s:"以下哪項不是可保權益必須符合條件?",o:["必須先有可被保的","必須是該保險的標的","就財產保險而言，投保人必須所屬國家的公民","投保人與保險標的之間必須存在法律認可的關係"],a:2,e:"投保人必須所屬國家的公民不是可保權益必須符合\n條件"},{c:"3.1.1",s:"一種作為保險標的，屬於可以受保的事物，是屬於產生下列哪項原\n則的準則?",o:["彌償","可保權益","代位","最高誠信的原則"],a:1,e:"可保權益的產生，必須先有可被保的人身、財產、\n法律責任或法律權利"},{c:"3.1.1",s:"一種賦予某人可為自己的財務產品，購買保險的是?",o:["代位","分擔","可保權益","彌償"],a:2,e:"一種賦予某人可為自己的財務產品，購買保險的是\n可保權益"},{c:"3.1.1",s:"就標的的法律認可關係，給予某人購買保險的權利，這是",o:["最高誠信","可保權益","彌償","代位"],a:1,e:"就標的的法律認可關係，給予某人購買保險的權利\n，這是可保權益"},{c:"3.1.2",s:"以下哪項有關沒有可保權益的說明是正確?",o:["該份保險屬於無效","在任何情況下，不能退回已繳的保費","一般情況下，在不知道保險無效的情況下繼續支付的保費是可退\n回的","A 和 C 都正確"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效，一般\n情況下，在不知道保險無效的情況下繼續支付的保\n費是可退回的，A 和 C 都正確"},{c:"3.1.2",s:"以下哪項有關沒有可保權益的說明正確?",o:["該份保險合約從索償產生時被視為無效","該份保險屬可使無效","只有涉及沒有可保權益導致的損失時才無效","一般情況下，在不知道保險無效的情況下繼續支付的保費是可退\n回的"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效，一般\n情況下，在不知道保險無效的情況下繼續支付的保\n費是可退回的"},{c:"3.1.2",s:"沒有可保權益的情況下，以下哪項處理是不正確的?",o:["已繳交的保費一定不獲退還","保單合約無效","有關損失不獲賠償","在不知悉無效情況下支付的保費可獲退回"],a:0,e:"缺乏可保權益的話，有關保險協議便屬無效，一般\n情況下，在不知道保險無效的情況下繼續支付的保\n費是可退回的，答案A不正確"},{c:"3.1.2",s:"下列哪項有關沒有可保權益的保險的陳述是正確的?",o:["可以宣佈該項保險從索償產生時開始無效","保險人不須根據該份保險合約承擔賠償責任","只是那些由缺乏可保權益導致的損失才不獲賠償","該項保險屬於可使無效"],a:1,e:"缺乏可保權益的話，有關保險協議便屬無效"},{c:"3.1.2",s:"以下哪項對可保權益的描述是不正確?",o:["必須先有可被保的","必須是該保險的標的","如對該保單的保單所有人生命購買保險是無須擁有","投保人與保險標的之間存在被法律認可的關係"],a:2,e:"缺乏可保權益的話，有關保險協議便屬無效"},{c:"3.1.2",s:"下列哪項有關缺乏可保權益的保險的陳述是不正確的?",o:["該項保險屬於可使無效","涉及保費是否退還等的法律問題","所有損失不獲賠償","該份保險合約從索償產生時被視為無效"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效，而退\n還保費的相關規則，則因所屬險種而異，相關規則\n例如《保險業條例》和《海上保險條例》的相關條\n文，答案D不正確"},{c:"3.1.3",s:"以下其中三項擁有可保權益，那麼哪一項是沒有可保權益的?",o:["使用非法抄錄電腦軟件的人(「全險」保險)","借入銀行按揭貸款的人(火險)","單位的業權人(家居保險)","把生命投保的被保險人的丈夫(人壽保險)"],a:0,e:"可保權益關係必須是合法的，盜賊並沒有權利就其\n管有 的贓物購買保險。"},{c:"3.1.3",s:"在香港，下列哪項可構成可保權益(為自己的利益而購買保險)",o:["自己","自己的配偶","自己精神錯亂的配偶","以上各項皆是"],a:3,e:"以上各項皆是在香港可構成可保權益的。"},{c:"3.1.3",s:"以下哪項可保權益的陳述不正確？",o:["所有保險都必須有的","存在者與保險標的之間是一種財務關係","與保險標的之間的關係必須法律認可","以上各項皆不是"],a:3,e:"以上各項皆是可保權益的正確陳述"},{c:"3.1.3",s:"下列哪項或哪些例子符合可保權益所要求的條件？",o:["一名盜賊希望替自己偷竊得來的財物投買保險","一名男子希望替自己擁有的汽車投買保險","一名男子為了自己的利益，希望替他那位粗心大意的朋友的手錶\n投買保險","上述所有各項"],a:1,e:"財產保險明顯的例子是在絕對擁有權的情況下產生\n可保權益 。答案B正確"},{c:"3.1.3",s:"可保權益需要符合什麼條件？",o:["需要先有可受保的人","有關的人和物必須為保險的標的","當投保事件發生時，對打算投買保險的人必須構成財務損失","以上各項都是"],a:3,e:"以上各項都是可保權益需要符合的條件"},{c:"3.1.3",s:"在香港，每一名對下列哪項人士的生命不具有可保權益？﹝為個人\n本身的利益購買人壽保險﹞",o:["個人的妹夫","個人的配偶","個人的本身","上述各項均存在可保權益"],a:0,e:"上述各項關係均存在可保權益"},{c:"3.1.3",s:"可保權益除必須先有可被保的人身、財産、責任或法律權利外，某\n人身等必須是該保險的標的，第二個條件是",o:["財物必須有明確的價值","保險標的必須是或屬於受保人的","投保人與保險標的必須具有法律認可的關係","以上各項都不是"],a:2,e:"可保權益除必須先有可被保的人身、財産、責任或\n法律權利外，某人身等必須是該保險的標的，第二\n個條件是，投保人與保險標的必須具有法律認可的\n關係"},{c:"3.1.3",s:"在香港，個人對下列哪項人士的生命不具有可保權益？",o:["其本身","其未婚妻","其商業夥伴","其貸款借款人"],a:1,e:"每個人對自己的生命、肢體等均享有可保權益，同\n樣也對自己的配偶的生命享有可保權益。此外，每\n個人均可就未滿十八歲的子 女 、或\n受其監護而未滿十八歲的人監護人關係的生命購買\n保險，未婚妻不具有可保權益。"},{c:"3.1.3",s:"對一架飛機的可保權益是來自",o:["該部飛機的財務價值","一種購買該部飛機的意欲","一種對該部飛機的法律認可的關係","交付保費的能力"],a:2,e:"可保權益是某人對某項保險標的在法律上被認可的\n一種關係， 這種關係賦予他對該保險標的 購\n買保險的權利。"},{c:"3.1.3",s:"一種作為投保保險標的屬於可受保的事物，是屬於產生下列哪項原\n則的準則?",o:["彌償","可保權益","分擔","最高誠信的原則"],a:1,e:"要具有可保權益必須符合以下條件，必須先有可被\n保的人身、財產、法律責任或法律權利，例如，對\n債務人要求償還債務的權利"},{c:"3.1.3",s:"以下哪項不符合可保權益所要求的條件?",o:["有可受保的東西","有關保險標的必須是有形的","該東西為有關保險的標的","對保險標的必須是一種法律認可的關係"],a:1,e:"有關保險標的必須是有形的，不是可保權益所要求\n的必要條件"},{c:"3.1.3",s:"以下哪項不太可能屬於可保權益的先決條件?",o:["與保險標的的一種法律認可關係","有可保的標的","標的是可受保的","被保險人與保險標的之間的一種法律擁有權"],a:3,e:"可保權益是投保人與保險標的之間必須被法律認可\n的關係，答案D不正確"},{c:"3.1.3",s:"在香港，個人對下列哪項人士的生命不具有可保權益？",o:["自己","其貸款借款人","自己的配偶","未婚夫"],a:3,e:"未婚夫不具有可保權益"},{c:"3.1.3",s:"以下哪項可保權益的陳述不正確？",o:["對保險標的必須存在一種法律認可的關係","有可受保的東西","只適用於自身及自身的財物","該東西為有關保險標的"],a:2,e:"財產保險可保權益最明顯的例子是在絕對擁有權的\n情況下產生可保權益。遺囑執行人、遺產管理人、\n信託人、承按人等持有次於絕對擁有權，分別為遺\n產、信託財產、按揭財產投保。受託保管人都可以\n對所保管的貨品進行投保。答案C不正確"},{c:"3.1.3",s:"以下哪項是債權人對債務人的生命購買保險，具有可保權益必須符\n合的必要條件?",o:["財務關係一直存在","僅適用於抵押一直存在","沒有任何必要條件","償還債務的金額"],a:0,e:"在法律上假定有可保權益的存在，須提出財務關係\n的證據"},{c:"3.1.3",s:"以下哪項可保權益的陳述是正確？",o:["盜賊可以替自己偷竊得來的賊贓物投購保險","可保權益只適用於人壽保險","某人與保險標的之間必須存在被法律認可的關係","以上各項皆不正確"],a:2,e:"可保權益是某人對某項保險標的在法律上被認可的\n一種關係，這種關係賦予他對該保險標的購買保險\n的權利。這種關係必須是合法的，盜賊並沒有權利\n就其管有的贓物 購買保險"},{c:"3.1.4",s:"以下哪項所投保的財產保險不具有可保權益?",o:["破產案中破產者擁有的財產的受託人","遺囑執行人打算投保已去世者的建築物","一部數碼相機的擁有者的父親","承按人打算投保的按揭財產"],a:2,e:"財產保險明顯的例子是在絕對擁有權的情況下產生\n可保權益，除此以外，遺囑執行人、遺產管理人、\n信託人、承按人等持有次於絕對擁有權的權利。受\n託保管人亦可以對所保管的貨品進行投保。答案C不\n正確"},{c:"3.1.4",s:"構成財產保險可保權益的是",o:["在擁有人同意下管有該項財產","需對保管的財產的損失負責","絕對擁有該項財產","以上各項皆是"],a:3,e:"構成財產保險可保權益的條件，可以是持有次於絕\n對擁有權的權利，分別為遺產、信託財產、按揭財\n產投保。"},{c:"3.1.4",s:"在香港，就以下哪項的生命投保的人壽保險不具備可保權益？",o:["個人的母親","個人本身","個人15歲的子女","個人的貸款欠款人"],a:0,e:"每個人對自己的生命、肢體等均享有可保權益，同\n樣也對自己的配偶的生命享有可保權益。此外，每\n個人均可就未滿十八歲的子女、或受其監護而未滿\n十八歲的人監護人關係的生命購買保險。個人的母\n親不具備可保權益。"},{c:"3.1.4",s:"針對香港的人壽保險，以下那項具有可保權益?",o:["就自己配偶的生命投買保險","就自己繼父(或後父)的生命投買保險","就自己年屆10歲的孫女的生命投買保險","以上各項皆正確"],a:0,e:"每個人對自己的生命、肢體等均享有可保權益，同\n樣也對自己的配偶的生命享有可保權益。此外，每\n個人均可就未滿十八歲的子女、或受其監護而未滿\n十八歲的人監護人關係的生命購買保險。"},{c:"3.1.4",s:"以下哪項購買財產保險的關係中會出現可保權益？",o:["手錶的受託保管人","遺囑執行人打算投保已逝者的建築物","承按人打算投保按揭保障","以上各項均可購成可保權益"],a:3,e:"以上各項都是受託保管人持有次於絕對擁有權，可\n以對所保管的貨品進行投保的例子，均可購成可保\n權益"},{c:"3.1.4",s:"以下哪項不構成法律責任的可保權益？",o:["自己的疏忽","自己僱員的疏忽","自己代理人的疏忽","盜賊駕駛被盜人士的汽車的疏忽"],a:3,e:"可保權益關係必須是合法的，盜賊並沒有權利就其\n管有的贓物購買保險。"},{c:"3.1.4",s:"彌償及可保權益兩個原則的關係",o:["均與財務利益有密切關係","兩者完全沒有共通之處","意向完全不同","尋求真正造成損失且具有影響力的原因"],a:0,e:"可保權益是對某項保險標的財務「權益」，其價值\n多少，就應在全損的情況下賠付多少錢，才能讓保\n單持有人完全的得到補償，所以彌償及可保權益兩\n個原則均與財務利益有密切關係"},{c:"3.1.4",s:"以下哪項所投保的財產保險不具備有可保權益？",o:["遊艇擁有者的母親","承按人打算投保的按揭財產","遺囑執行人打算投保已去世者的建築物","破產案中破產者擁有的財產的受託人"],a:0,e:"遊艇擁有者的母親次並非持有絕對或次於絕對擁有\n權，亦非受託保管人的身份，不具有財產保險的可\n保權益"},{c:"3.1.4",s:"以下哪項或哪幾項是符合可保權益所需要之條件？",o:["一男子希望幫助他偷竊回來的財物投買保險","一男子希望幫助他一員工之不忠實投買保險","一男子希望幫助他伯父的生命購買保險","以上各項皆是"],a:1,e:"因自身的合法權利可能受到侵犯、或可能喪失未來\n的收入，而面臨潛在損失的威脅的任何人，都有權\n對這種風險購買保險，答案B正確"},{c:"3.1.4",s:"構成財產保險可保權益的條件是",o:["單單管有該財產不構成可保權益","與保險標的之間存在法律認可的關係","構成可保權不一定擁有該財產","以上各項皆是"],a:3,e:"構成財產保險可保權益的條件，可以是持有次於絕\n對擁有權的權利，分別為遺產、信託財產、按揭財\n產投保。"},{c:"3.1.4",s:"以下哪項可保權益的陳述正確?\ni.每人對自己的肢體都有保險利益\nii.承按人不可以對按揭財產投保\niii.又可稱為保險標的\niv.保險人與被保險人之間法律認可的關係",o:["i","i,ii,iii","ii,iv","i, ii,iv"],a:0,e:"可保權益是投保人與保險標的之間必須存在被法律\n認可的關係，承按人是持有次於絕對擁有權的權利\n，可以對按揭財產投保，只有選項(i)是正確"},{c:"3.1.4",s:"以下哪項可保權益的陳述正確?",o:["適用於計算保費融資利率","又可稱為保險標的","又可稱為保險標的","沒有保權益，有關保險協議便屬無效"],a:3,e:"缺乏可保權益的話，有關保險協議便屬無效"},{c:"3.1.4(a)",s:"在香港，每一名個人對下列哪項或哪些人士具有可保權益？",o:["個人的本身","個人的配偶","個人十八歲以下的子女或受監護人","上述所有各項"],a:3,e:"每個人對自己的生命、肢體等均享有可保權益，同\n樣也對自己的配偶的生命享有可保權益。此外，每\n個人均可就未滿十八歲的子女、或受其監護而未滿\n十八歲的人監護人關係的生命購買保險"},{c:"3.1.4(a)",s:"在香港，每一名人士對以下哪項或哪些人士的生命不具有可保權益(\n為個人本身的利益購買人壽保險)？",o:["個人的本身","個人的配偶","個人17歲的妻子","以上所有各項均存在可保權益"],a:3,e:"人身保險：每個人對自己的生命、自己的配偶的生\n命享有可保權益"},{c:"3.1.4(a)",s:"以下哪項關係可構成可保權益關係",o:["大過18歲的子女","我的母親","法院裁定下的被監護人關係(大於18歲)","法定夫婦關係"],a:3,e:"每個人對自己的生命、肢體等均享有可保權益，同\n樣也對自己的配偶的生命享有可保權益。此外，每\n個人均可就未滿十八歲的子女、或受其監護而未滿\n十八歲的人監護人關係的生命購買保險"},{c:"3.1.4(a)",s:"在香港，每一名人士對以下哪項人士的生命不具有可保權益？",o:["個人的本身","個人的配偶","個人的兄弟及父母","個人十八歲以下的子女或受監護人"],a:2,e:"在香港，有血緣的家庭關係一般不可構成可保權益\n，例如兄弟及父母"},{c:"3.1.4(b)",s:"以下哪項對於財產上的可保權益是並非必要的?",o:["與該財產必須有法律認可關係","必須對該財產有擁有權","購買的保險必須是與該財產有關的","與該財產必須要有財務上的關係"],a:1,e:"財產保險明顯的例子是在絕對擁有權的情況下產生\n可保權益，除此以外，遺囑執行人、遺產管理人、\n信託人、承按人等持有次於絕對擁有權的權利。受\n託保管人亦可以對所保管的貨品進行投保。答案Ｂ\n不正確"},{c:"3.1.4(b)",s:"以下哪些財產可投買保險?\ni)從偷竊中得來之財產\nii)以持有人名義投買的財產\niii)信託人保管的財產\niv)遺囑執行人保管的財產",o:["i，ii，iii","ii，iii，iv","i，ii，iv","以上各項皆是"],a:1,e:"可保權益關係必須是合法的，盜賊並沒有權利就其\n管有的贓物購買保險。財產保險明顯的例子是在絕\n對擁有權的情況下產生可保權益，除此以外，遺囑\n執行人、遺產管理人、信託人、承按人等持有次於\n絕對擁有權的權利。受託保管人亦可以對所保管的\n貨品進行投保。選項i不正確"},{c:"3.1.4(b)",s:"一份恰當地安排的財產保險，於被保險的全損出現時，應可獲完全\n補償。這項補償代表該名被保險人在有關保險上的權益，顯示彌補\n與以下哪些或哪項的原則相連",o:["近因","可保權益","最高誠信","以上各項"],a:1,e:"可保權益是對某項保險標的財務「權益」，其價值\n多少，就應在全損的情況下賠付多少錢，才能讓保\n單持有人完全的得到補償"},{c:"3.1.4(b)",s:"阿倫給予他的朋友玫瑰一個他所擁有的單位免費住兩個月，請問玫\n瑰有權為該單位購買保險?理由何在?",o:["有，合法地佔有某單位的任何人有權以所有人的代理人的身份就\n該單位購買保險","沒有，因為她沒有付出代價","有，她是以單位託管人的身份人對該單位具有權益的","沒有，因為她並非擁有該單位"],a:2,e:"受託保管人持有次於絕對擁有權，在得到某貨品的\n擁有人或其代理人的同意下，管有該貨品的人可以\n對所保管的貨品進行投保。"},{c:"3.1.4(b)",s:"於所有保險合約中，被保險人必需在投保時對標的物有可保權益，\n以下哪項保險項目在索償時需要有可保權益？\ni任何型式的責任保險\nii) 車險\niii)人壽保險\niv) 船上的貨物保險",o:["i, ii, iii","i, iii, iv","i, ii, iv","i, ii, iii, iv"],a:2,e:"在人壽保險中，可保權益只須在保單起保時存在。\n於其他類型的彌償保險的保權益只須在損失時（即\n是索償時存在）"},{c:"3.1.4(b)",s:"以下哪三種具有可保權益屬於不是自己絕對擁有的財產？\ni) 受託人(以信託形式托管財產)\nii) 戶主的兒子(母親的房屋)\niii) 遺產執行人(死者遺下的物業)\niv) 一家銀行借錢給按揭人(按揭建築物)",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:3,e:"選項ii不屬受託保管人持有次於絕對擁有權，可以\n對所保管的貨品進行投保的例子，正確答案是D"},{c:"3.1.4(b)",s:"以下哪項或哪些對財產可保權益的描述是正確的?",o:["投保人需為財產擁有人","投保人需實質擁有該財產","投保人不一定需要是財產擁有人","以上所列各項皆是"],a:2,e:"除了在絕對擁有權的情況下產生可保權益，受託保\n管人持有次於絕對擁有權，在得到某貨品的擁有人\n或其代理人的同意下，管有該貨品的人可以對所保\n管的貨品進行投保，答案C正確。"},{c:"3.1.4(b)",s:"於所有保險合約中，以下哪項保險項目在索償時需要有可保權益？\ni.責 任保險\nii.汽 車保險\niii.船 上貨物保險\niv.人 壽保險",o:["i,ii,iii","ii, iii, iv","i,ii,iv","i,iii,iv"],a:0,e:"在水險或其他類型的彌償保險，可保權益只須損失\n時存在，所以選項i,ii,iii是正確。"},{c:"3.1.4(c)",s:"以下哪項或哪幾項是符合可保權益所需要之條件",o:["一男子希望幫助他偷竊回來的財物投買保險","一男子希望幫助他一員工之不忠實投買保險","一男子因為自己的利益,希望幫助他粗心大意的朋友的手錶投買保\n險","以上各項皆是"],a:1,e:"每個人對他人的作為或不作為負上的轉承責任投保\n，例如僱主可以對其僱員的疏忽等行為所導致對公\n眾的法律責任購買保險"},{c:"3.1.4(c)",s:"有關責任上出現的可保權益包括",o:["自己行為的責任","自己的代理人行為的責任","自己的僱員行為的責任","以上各項皆是"],a:3,e:"除了「直接責任」或「首要責任」的潛在法律責任\n，也可以為轉承責任投保，例如僱主可以對其僱員\n的疏忽等行為所導致對公眾的法律責任購買保險，\n以上各項皆是責任上出現的可保權益。"},{c:"3.1.4(c)",s:"以下哪項對首要責任及轉承責任的描述是正確的？\ni)首要責任是個人對他人的作為或不作為負上責任\nii)首要責任是個人本身的作為或不作為所引致的法律責任\niii)轉承責任經常在代理關係上產生\niv)轉承責任可能在僱傭關係上產生",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:2,e:"每個人對自身的作為或不作為都負有一種稱為「直\n接責任」或「首要責任」的潛在法律責任，另一方\n面，他們也可以為轉承責任投保，例如僱主可以對\n其僱員的疏忽行為所導致對公眾的法律責任購買保\n險。只有選項ii, iii, iv正確"},{c:"3.1.4(c)",s:"以下哪項構成法律責任的可保權益?\ni) 自己本身的疏忽\nii) 第三者的疏忽\niii) 承擔某人的僱員的疏忽\niv) 承擔某人的代理的轉承責任",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"除了「直接責任」或「首要責任」的潛在法律責任\n，也可以為轉承責任投保，例如僱主可以對其僱員\n的疏忽等行為所導致對公眾的法律責任購買保險，\n以上各項皆是責任上出現的可保權益"},{c:"3.1.4(c)",s:"以下哪項有關直接責任及轉承責任之陳述是不正確的?",o:["直接責任是指由個人本身的行為的法律責任","直接責任是個人對別人的行為的法律責任","轉承責任在僱傭關係中產生","轉承責任是在委託人/代理人關係中產生"],a:1,e:"每個人對自身的作為或不作為都負有一種稱為「直\n接責任」或「首要責任」的潛在法律責任，答案Ｂ\n不正確"},{c:"3.1.4(c)",s:"一間育兒院要求每一位家長必須簽署一份協議書，當中訂明其孩子\n在育兒院內所受之傷害，家長不得向育兒院追究。儘管如此，育兒\n院營運人就其所照顧的孩子在其處所所受之傷害的潛在法律責任購\n買了一入責任保險。請問育兒院是否布權購買此份保險，理由何在?",o:["他不必購買此份保險，因政府註冊的育兒院不須承擔責任","保險無效；因大部份的責任保險將「受保處所之傷害」列為除外\n責任","保險有效；育兒院營運人需為其作為或不作為負擔其潛在的法律\n責任","保險無效；因沒有法律責任，在欠缺可保權益下不能購買保險"],a:2,e:"育兒院營運人可以對其僱員的疏忽等行為所導致的\n法律責任購買保險。"},{c:"3.1.4(d)",s:"符合法律認可關係的可保權益，以下哪項為非人身、財物或法律責\n任的可保權益?",o:["為酒樓電力中斷後，營業利潤損失購買保險","為自己的建築物購買火險","債主為自己的債務購買保險","僱主為受僱職員的損傷購買保險"],a:0,e:"可保權益亦可透過其他合法權利保險產生。因自身\n的合法權利可能受到侵犯、或可能喪失未來的收入\n，而面臨潛在損失的威脅的人，都有權對這種風險\n購買保險。"},{c:"3.1.4(d)",s:"以下哪項構成可保權益的關係中，不屬於財產上、個人上及責任上?",o:["貨主為船上貨品購買水險","債主為負債人購買人壽保險","業主為其所收租金購買租金保險","僱主為僱員購買僱傭保險"],a:2,e:"除了財產上、人身上及責任上情況下產生可保權益\n，還有其他合法權利保險，是因自身的合法權利可\n能受到侵犯、或可能喪失未來的收入，而面臨潛在\n損失的威脅的任何人，都有權對這種風險購買保險\n。例如房東有權對火災後租金的損失購買保險。"},{c:"3.1.4(d)",s:"可保權益的產生，可以是因本身的合法權利受到侵犯或當費用損失\n因受保範圍間接引致的，以下哪項屬於該範圍?",o:["房東因火災後損失租金","汽車意外引致另行租用其他車輛的費用","商鋪爆炸以引致利潤的損失","以上各項皆正確"],a:3,e:"以上各項皆是其他合法權利保險的受保範圍(因自身\n的合法權利可能受到侵犯、或可能喪失未來的收入\n，而面臨潛在損失的風險購買保險"},{c:"3.1.4(d)",s:"可保權益可以在合法權利受到侵犯或當損失/開支間接產生的情況下\n形成，以下哪一項或哪些屬於此類?",o:["酒樓經營者就供電中斷後產生的利潤損失購買保險","汽車意外後而需租用另一輛汽車的租金","酒樓經營者就禽流感爆發後產生的利潤損失購買保險","以上所有各項"],a:3,e:"其他合法權利保險，是因自身的合法權利可能受到\n侵犯、或可能喪失未來的收入，而面臨潛在損失的\n威脅的任何人，都有權對這種風險購買保險。以上\n所有各項都是例子"},{c:"3.1.4(d)",s:"以下哪項是在法律權利受到侵犯或當損失/開支間接產生的情況下形\n成，而不是人身、財産或責任？",o:["僱主為員工在工作時的意外受傷購買保險","酒樓經營者就禽流感爆發後產生的利潤損失購買保險","車主為自己對第三者所造成的損失購買保險","以上所有各項"],a:1,e:"其他合法權利保險，是因自身的合法權利可能受到\n侵犯、或可能喪失未來的收入，而面臨潛在損失的\n威脅的任何人，都有權對這種風險購買保險。酒樓\n經營者就禽流感爆發後產生的利潤損失購買保險就\n是例子"},{c:"3.1.4(d)",s:"就可保權益的定義而言，一家物業管理公司可否就所管理的大廈投\n買火險？為什麼？",o:["不可以。因為物業管理公司對該大廈不存在可保利益","不可以。因為物業管理公司不是大廈業主","可以。因為物業管理公司有法律責任購買","可以。只要獲大廈業主的授權替委託物業購買保險，便會構成可\n保權益"],a:3,e:"受託保管人持有次於絕對擁有權，可以對所保管的\n貨品進行投保。"},{c:"3.1.5",s:"哪一類保險保障只需在保單開始時存在可保權益便可以",o:["汽車保險","家居保險","人壽保險","醫療保險"],a:2,e:"人壽保險只需在保單開始時存在可保權益"},{c:"3.1.5",s:"人壽保險與其他保險一樣要求可保權益的存在，但對人壽保險而言\n可保權益必須存在於",o:["只是索償出現的時候","只是保單開始的時候","只是保單可能轉讓的時候","保單開始及索償出現的時候"],a:1,e:"人壽保險而言可保權益必須存在於保單開始的時候"},{c:"3.1.5",s:"以下哪項保險只有在合約辦妥時(保單開始)才需要可保權益？",o:["火險","人壽保險","水險","航空保險"],a:1,e:"人壽保險只有在合約辦妥時(即保單開始)才需要可\n保權益"},{c:"3.1.5",s:"下列哪項是有關人壽保險的特性?\ni)被保險人在這類保險中被視為擁有期未利益\nii)它是一種長期業務\niii)保險人不能取消人壽保險單\niv)可保權益只在保單開始時需要",o:["i，ii，iii","i，ii，iv","ii，iii，iv","i，ii，iii，iv"],a:3,e:"以上各項皆是有關人壽保險的特性"},{c:"3.1.5",s:"不同類型的保單會於不同時間需要具有可保權益，下列哪項保單會\n於索償出現時需要具有可保權益?\ni)人壽保險\nii)鐵路車輛保險\niii)任何形式的責任保險\niv)海上貨物保險",o:["i，ii","ii，iii","i，ii，iii","ii，iii，iv"],a:3,e:"在人壽保險中，可保權益只須在保單起保時存在。\n於其他類型的彌償保險的保權益只須在損失時（即\n是索償時存在）選項ii，iii，iv正確"},{c:"3.1.5",s:"以下哪項或哪些情況出現之損失或索償，在沒有構成可保權益下，\n都不會形成拒絕損失索償的理由",o:["人壽保險(被保險人為前配偶，現已離婚)","火險，由「前承按人」購買(欠款已於火災前清還)","車險(汽車於意外摧毀前己賣出)","以上各項"],a:0,e:"在人壽保險中，可保權益只須在保單起保時存在。\n提出索賠時缺乏可保權益不會喪失索取死亡利益的\n資格"},{c:"3.1.6",s:"以下哪項對轉讓的陳述是正確的?\ni)人壽保險可以不經保險人同意自由轉讓\nii)海上貨物保險可以不經保險人同意自由轉讓\niii)商業「全險」保單不可以沒有保險人同意便轉讓\niv)人壽保險不可以沒有保險人同意便轉讓",o:["i，ii，iii","i，ii，iv","i，iii，iv","ii，iii，iv"],a:0,e:"人壽保險可以沒有保險人同意便轉讓，描述iv不正\n確"},{c:"3.1.6",s:"有兩種保險合約被視為可以自由轉讓的，它們是",o:["人壽與火險","人壽與水險","水險與公眾責任","水險與忠實保險"],a:1,e:"在實務上，人壽保險單和海上貨物保險單，可以不\n經保險人的同意而予以轉讓。"},{c:"3.1.6",s:"實際上，哪項或哪些必須在保險人的同意下轉讓？",o:["人壽保險","財產保險","海上貨物保險","以上所有各項"],a:1,e:"實務上，財產保險是須要在保險人同意下可以進行\n轉換的。"},{c:"3.1.6",s:"「將根據合約所需給付的金額，轉付予保單持有人以外的人。」此\n句子是指",o:["代位","權益轉讓","委付","保單收益轉讓"],a:3,e:"「將根據合約所需給付的金額，轉付予保單持有人\n以外的人。」此句子是指保單收益轉讓"},{c:"3.1.6",s:"保單轉讓是指以相同的保險標的物，轉至另一被保險人，通常哪類\n險種需要保險人的批淮？",o:["盜竊險","財產險","車險","以上各項皆是"],a:3,e:"在實務上，人壽保險單和海上貨物保險單，可以不\n經保險人的同意而予以轉讓。至於其他類型的非人\n壽保險單，例如財產保險是須要在保險人同意下可\n以進行轉換的"},{c:"3.1.6",s:"收取保險金的轉讓，意思是指",o:["必須把保單應該支付的金錢轉付予指定的第三者","把保單轉讓予另一保險公司","把保單的擁有權轉讓予他人","讓另一個人替代原本的被保險人"],a:0,e:"收取保險金的轉讓，意思是把保單應該支付的金錢\n轉付予指定的第三者"},{c:"3.1.6",s:"保單轉讓是把附於合約的權利轉移，令另一人成為了同一保險標的\n的保單持有人，以下哪項或哪些保險類型需要得到保險人同意下轉\n讓?",o:["僱員補償保險","盜竊保險","汽車保險","以上各項皆是"],a:3,e:"只有人壽保險及海上貨物保險是不需要保險人同意\n下可以進行轉換，其他類型的保險，例如財產保險\n及責任保險，需要得到保險人同意下轉讓"},{c:"3.1.6",s:"下列哪項屬於轉讓保險合約所帶來的影響？",o:["承讓人會成為保單的保管人","承讓人會成為保單收益的受托人","不論轉讓人或是承保人所作的違法行為不會對承讓人構成影響","保險合約從此保障承讓人可能遭受的損失"],a:3,e:"當保單有效地從轉讓人身上轉讓到承讓人的身上，\n表示轉讓人在合約中的權益已完全轉移到承讓人的\n身上，因此，當所保事故其後發生時，保險人就有\n義務向承讓人就其損失作出賠付。"},{c:"3.1.6",s:"實務上，有兩類保險是不需要保險人同意下可以進行轉換的。",o:["壽險；全險","海上保險；忠誠保證保險","海上保險；公衆責任保險","壽險；海上貨物保險"],a:3,e:"實務上，人壽保險及海上貨物保險是不需要保險人\n同意下可以進行轉換的。"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["承讓人承諾支付未來的保費","保單轉讓人只會把在合約中的權益轉移到承讓人的身上","保單轉讓人只會把在合約中的的責任轉移到承讓人的身上","保單轉讓人在合約中的權益和責任均完全轉移到承讓人的身上"],a:1,e:"保單「轉讓」通常是指權利的轉移。轉讓是不會讓\n轉讓人在保險合約的責任轉移到承讓人的身上的"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?",o:["轉讓人不會把保險合約中的責任轉移到承讓人的身上","承讓人將取得收款人的權利，而非訴訟權","承讓人承讓人承諾支付未來的保費","承讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費"],a:0,e:"保單「轉讓」通常是指權利的轉移。轉讓是不會讓\n轉讓人在保險合約的責任轉移到承讓人的身上的"},{c:"3.1.6",s:"以下哪一項有關保單轉讓的描述是正確的?\ni.承 讓人承諾支付未來一切保費\nii.轉 讓人不會把保險合約中的責任轉移到承讓人的身上\niii.承 讓人承諾支付未來的保費，包括保單轉讓時未有支付的保費\niv.如 將保單的責任轉移到第三者，須得到保險人的同意",o:["i , ii, iii","ii,iv","ii,iii,iv","i,ii,iii,iv"],a:1,e:"轉讓是不會讓轉讓人在保險合約的責任轉移到承讓\n人的身上的 。 這類轉移須得到保險人的同意\n。只有選項ii,iv 正確"},{c:"3.1.6",s:"以下哪項不屬保險合約轉讓的後果?",o:["在人壽保險而言，轉讓保險合約將會承保新的受保生命","轉讓人在合約中的權益已完全轉移到承讓人的身上","在壽險中，轉讓是決不會換入一個新的受保生命","保險人於保險合約轉讓後停止承保轉讓人的損失"],a:0,e:"在人壽保險而言，轉讓保險合約將會承保新的受保\n生命"},{c:"3.1.6(b)",s:"以下哪項有關一般誠信的描述是不正確?\ni.合約各方所提供的資訊必須是實質上真實，而且沒有主動披露的\n責任\nii.合約各方所提供的資訊可以真實或虛假，不可以信賴\niii.合約各方所提供的資訊必須是百分百真實\niv.合約各方必須主動披露可能影響是否訂立合約的一切重要資訊",o:["i,ii,iii","ii,iii,iv","i,ii","iii,iv"],a:1,e:"一般誠信意思是合約各方必須本着誠實的態度行事\n，所提供的資訊必須是實質上真實的，但他們沒有\n責任確保對方取得可能影響他是否訂立合約的一切\n重要資訊。選項ii,iii,iv都不正確"},{c:"3.1.6(b)",s:"以下哪項就轉讓收取保險金的權利的權利描述是正確的?",o:["轉讓收取保險金的權利必須取得保險人的同意，視乎保險合約性\n質","不論任何保險合約性質，轉讓收取保險金的權利無需取得保險人\n的同意","轉讓水險合約的收取保險金的權利，必須取得保險人的同意","只有A及C是正確"],a:1,e:"不論相關保險合約的性質如何，轉讓收取保險金的\n權利無需取得保險人的同意"},{c:"3.2",s:"最高誠信的責任適用於",o:["被保險人而非保險人","保險人而非被保險人","任何情況下的被保險人及保險人","被保險人及保險人，但只限於保單有這要求"],a:2,e:"可以說，最高誠信是對投保人或被保險人定下一項\n披露資訊的責任。技術上，保險人須負同樣的責任\n。"},{c:"3.2.1",s:"保險合約的契約各方______",o:["必須披露所有已知的重要事實","無需披露所有已知的重要事實","確保將要提供給對方的資料在實質上真實","確保向合約另一方披露所有重要事實，無論保單上是否有相關的\n問題"],a:3,e:"最高誠信的原則意思是，不論另一方是否要求有關\n的資料，各方必須向另一方披露所有重要事實，即\n使投保單上並沒有相關的問題例如，投保人仍須向\n保險人披露"},{c:"3.2.1",s:"有別於最高誠信，一般誠信是指由各方提供的資料必須",o:["必須大致真實","必須絕對真實且沒有遺漏任何重要事實","可以是真實或虛假，所以不應信賴","必須實質上真實，但沒有主動的責任披露每項事實"],a:3,e:"一般誠信適用於大部分商業合約，在普通法上，合\n約各方必須本着誠實的態度行事，所提供的資訊必\n須是實質上真實的，但他們沒有責任確保對方取得\n可能影響他是否訂立合約或可能影響他以怎麼樣的\n條件訂立合約的一切重要資訊。"},{c:"3.2.1",s:"有別於最高誠信，一般誠信要求有關各方",o:["保證他們作出的每項陳述均是百分百真實","不論有否被問及也要披露所有重要事實","擔保他們沒有遺漏任何對有關合約的重要事實","忠誠及確保將要提供給對方的資料在實質上真實"],a:3,e:"在普通法上，一般誠信要求有關各方必須本着誠實\n的態度行事，所提供的資訊必須是實質上真實的"},{c:"3.2.1",s:"有別於最高誠信，一般誠信的意思是",o:["不論有否問及必需披露重要事實","所披露的必須確保百分百真實","所提及的需承諾及保證完全真實","本著誠信的態度的行事，而資訊必須是實質上真實"],a:3,e:"一般誠信原則適用於大部分商業合約，合約各方必\n須本着誠實的態度行事，所提供的資訊必須是實質\n上真實的，但他們沒有責任確保對方取得可能影響\n他是否訂立合約條件的一切重要資訊。"},{c:"3.2.1",s:"以下哪項有關「一般誠信」一詞是正確的描述",o:["是常識範圍内的事實","不論對方是否問及有關的資料，各方必須向他方披露所有重要的\n資料","各方向他方披露的資料可以是真實或虛假，所以不可信","訂立合約時，本著誠實態度行事，所提供的資訊是實質上真實的\n，而對於另一方沒有詢問的事情保持緘默"],a:3,e:"一般誠信意思是合約各方必須本着誠實的態度行事\n，所提供的資訊必須是實質上真實的，但他們沒有\n責任確保對方取得可能影響他是否訂立合約的一切\n重要資訊。答案D正確"},{c:"3.2.1",s:"一般誠信是",o:["廣泛性披露的責任","不說謊的消極責任","披露所有資料的積極責任","以上皆不是"],a:1,e:"一般誠信是合約各方必須本着誠實的態度行事，屬\n不說謊的消極責任"},{c:"3.2.1",s:"正面回答所有被問及的問題並保證作出的回答是真實的，這屬於",o:["一般誠信","最高誠信","內在誠信","合約誠信"],a:0,e:"一般誠信是本着誠實的態度行事，所提供的資訊必\n須是實質上真實的"},{c:"3.2.2",s:"最高誠信在普通法中，要求投保人所提供的資料是",o:["百分百事實","大部份真實","百分之九十真實","比嚴謹"],a:0,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。保險人有時把普通法中的最高\n誠信責任加以延伸，要求投保人聲明或保證，無論\n是否與「重要」事件有關連，所有經披露的資料都\n必須完全真實的。"},{c:"3.2.2",s:"誠實行事指一名人士在問及有關問題時要真實回答所有的問題，這\n是",o:["最高誠信","一般誠信","在內誠信","合約誠信"],a:1,e:"一般誠信原則下，合約各方必須本着誠實的態度行\n事，所提供的資訊必須是實質上真實的，但他們沒\n有責任確保對方取得可能影響他是否訂立合約條件\n的一切重要資訊。"},{c:"3.2.2",s:"以下哪項或哪些有關最高誠信和保險在香港的情況是不正確的？",o:["最高誠信只要求就所發問的問題提供合理的答案","最高誠信只在保單條款有規定的情況下才適用","所有保單內包含某些條款，更改最高誠信責任","以上所有各項都不正確"],a:3,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。保險人有時把普通法中的最高\n誠信責任加以延伸，要求投保人聲明或保證，無論\n是否與「重要」事件有關連，所有經披露的資料都\n必須完全真實的。例如，即使投保單上並沒有相關\n的問題，火險投保人仍須向保險人披露有關損失的\n紀錄。以上所有各項都不正確"},{c:"3.2.2",s:"以下關於最高誠信的陳述，哪三項是正確的 ?\ni)它是一項主動的披露責任\nii)最高誠信責任的關鍵不在於另一方的主動要求\niii)這是一項原則來自普通法，但合約條款是可以修改它的\niv)保險人必定不可能就違反最高誠信承擔法律責任",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii , iii , iv"],a:0,e:"最高誠信是對投保人／被保險人定下一項披露資訊\n的責任。技術上，保險人須負同樣的責任。選項iv\n不正確，正確答案是A"},{c:"3.2.2",s:"以下哪項是對最高誠信應用於保險是不正確描述",o:["只就所發問的問題以誠實及實質上真實的態度處理","在保單條款上必定是可以寬免的","只有在保單條款上規定才須遵守","以上所有各項均不正確"],a:3,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。保險人有時把普通法中的最高\n誠信責任加以延伸，要求投保人聲明或保證，無論\n是否與「重要」事件有關連，所有經披露的資料都\n必須完全真實的。例如，即使投保單上並沒有相關\n的問題，火險投保人仍須向保險人披露有關損失的\n紀錄。以上所有各項都不正確"},{c:"3.2.2",s:"以下哪項是商業合約的要求？",o:["一般誠信","最高誠信","重要誠信","合約誠信"],a:0,e:"一般誠信原則適用於大部分商業合約，合約各方必\n須本着誠實的態度行事，所提供的資訊必須是實質\n上真實的，但他們沒有責任確保對方取得可能影響\n他是否訂立合約條件的一切重要資訊。"},{c:"3.2.3",s:"下列哪項或哪些毋須在人壽保險合約的最高誠信責任下披露?",o:["健康紀錄","年齡及性別","準受保人是非抽煙者","以上所有各項"],a:2,e:"準受保人是非抽煙者不屬於必須披露的重要事實"},{c:"3.2.3",s:"影響一名審慎的保險人是否決定承擔風險的一項資料稱為",o:["陳述","重要事實","核保保證","無須披露的事實"],a:1,e:"重要事實是在訂定保費或決定是否承擔風險方面會\n影響一名審慎的保險人的判斷的任何情況"},{c:"3.2.3",s:"以下哪項屬於必須披露的重要事實？",o:["任何過去的入屋犯法行為﹝盜竊保險﹞","載貨船的名稱﹝海上貨物保險﹞","投保貨物的高度可燃性﹝火險﹞","上述所有各項"],a:3,e:"上述所有各項都屬增加風險的事實，必須予以披露"},{c:"3.2.3(a)",s:"重要事實指",o:["填寫投保書是要求申報的事實","影響一名審慎保險人決定是否承保的事實","購買財產保險時要求申報的事實","屬於常識一類的事實"],a:1,e:"重要事實的定義是「在訂定保費或決定是否承擔風\n險方面會影響一名審慎的保險人的判斷的任何情況\n。」"},{c:"3.2.3(b)",s:"根據最高誠信的原則，下列哪項屬於無須揭露的事實?\ni)近期健康狀況\nii)與常識有關的事件\niii)保險人已知的事實\niv)增加風險的事實",o:["i，ii","i，iii","ii，iii","iii，iv"],a:2,e:"與常識有關的事件及增加風險的事實根據最高誠信\n的原則，屬於無須揭露的事實"},{c:"3.2.3(b)",s:"以下哪一項是重要事實的陳述?",o:["保險人已知的事實","改善風險狀況的事實","水是生命之源","在五年前得知患有癌症"],a:3,e:"常識範圍内的事實，保險人已知已知的事實及減低\n風險狀況的事實屬於無須披露的事實"},{c:"3.2.3(b)",s:"於行使最高誠信時, 下列哪項不需予以披露",o:["關於戰爭的狀況","保險人已知悉或當作已知的事實","改善風險狀況的事實","上述各項皆無須披露"],a:3,e:"常識範圍内的事實，保險人已知的事實及減低風險\n狀況的事實都屬無須披露的事實，於行使最高誠信\n時, 不需予以披露"},{c:"3.2.3(b)",s:"以下哪項是投保人須披露",o:["與常識有關的資料","保險人已知或會影響是否承保風險的事實","投保人過往的索償紀錄","以上所有各項"],a:2,e:"投保人過往的索償紀錄屬增加風險的事實，必須予\n以披露。"},{c:"3.2.3(b)",s:"以下哪項不會影響保險合約存在與否或保險條款?",o:["重要事實","非重要事實","可保權益","以上各項皆不是"],a:1,e:"非重要事實對保險人來說是不會影響保險合約存在\n與否或保險條款"},{c:"3.2.4",s:"如果保險人要求保證所有披露資料，不論重要與否，均需完全真實\n，這表示",o:["違反法例並不能強制執行","延伸普通法中的最高誠信的要求","這合約受制於而非最高誠信","這合約受制於最高誠信"],a:1,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。"},{c:"3.2.4",s:"最高誠信的要求有時會改變，以下哪項是正確描述？",o:["這是法律不容許的","普通法要求在保單任何時間都需要","所有保險都是要求只在保單開始時需要","可以因為雙方的協議而修改"],a:3,e:"如果在保單有效期內要求更改合約，最高誠信的責\n任便適用於這些更改事項上"},{c:"3.2.4",s:"如果保險人要求保證所有披露資料，不論重要與否，均需完全真實\n，這表示",o:["違反法例並不能強制執行","延伸普通法中的最高誠信的要求","這合約受制於而非最高誠信","這合約受制於最高誠信"],a:1,e:"如果保險人要求保證所有披露資料，不論重要與否\n，均需完全真實，這表示延伸普通法中的最高誠信\n的要求"},{c:"3.2.4",s:"保險人有時會把普通法中有關最高誠信的要求延伸，要求投保人在\n保單上作出特定聲明，原因是",o:["通過這聲明，投保人保證無論是否涉及重要事件，所提供的事實\n必須實質上真實","通過這聲明，投保人保證所提供的重要事實，必須完全真實","通過聲明，投保人保證，無論是否與重要事件有關連，所有提供\n的資料都必須完全真實","以上各項皆不是"],a:2,e:"保險受到一種更為嚴格、在普通法中常被稱為最高\n誠信的原則所約束。它的意思是，不論另一方是否\n要求有關的資料，各方必須向另一方披露所有「重\n要事實」。例如，即使投保單上並沒有相關的問題\n，火險投保人仍須向保險人披露有關損失的紀錄。"},{c:"3.2.4",s:"以下哪項屬於本港的一般保險單經常包括的條款？",o:["把最高誠信責任應用局限於具體提出的問題","把最高誠信申延至整段合約生效期","取消最高誠信","把最高誠信責任限制於一段時間內"],a:1,e:"一些非人壽保單要求，在整段保險期限內如有風險\n上的變更，例如買了人身意外保險後轉職，必須予\n以披露。答案B正確"},{c:"3.2.4",s:"如在保險保障期間，風險上有重大的轉變",o:["很明顯地對保險人極其重要","某些保險合約可能要求被保險人作出披露","普通法要求在續約時方須要提出","以上各項皆正確"],a:3,e:"一些非人壽保單要求，在保險期限內有風險上的變\n更，例如買了人身意外保險後轉職，必須予以披露\n。不過，在普通法中，構成風險增加的狀況，只須\n在續保時通知保險人就足夠。以上各項皆正確。"},{c:"3.2.4",s:"在保單有效期內若在風險上出現的重大轉變，以下哪項或哪些對於\n這些轉變的評論是正確的？",o:["這些轉變顯然對保險人來說是重要的","在普通法中，在續保前都無須披露這些轉變","可能因保單條款的要求而需要披露這些轉變","以上所有各項皆是正確評論"],a:3,e:"一些非人壽保單要求，在保險期限內有風險上的變\n更，例如買了人身意外保險後轉職，必須予以披露\n。不過，在普通法中，構成風險增加的狀況，只須\n在續保時通知保險人就足夠。以上各項皆正確。"},{c:"3.2.4",s:"在非人壽保險單續保時，最高誠信的責任",o:["要再履行","無須履行","不再適用","只對保險人適用"],a:0,e:"一些非人壽保單要求，在保險期限內\n如有風險上的變更或續保時，例如買了人身意外保\n險後轉職，必須予以披露。"},{c:"3.2.4",s:"在合約有效期內，下列哪項是正確的?",o:["在普通法中，風險的轉變只須續約時予以知會","當保單續保時，最高誠信的責任不適用","在合約有效期內，要求披露重要資料是一種特殊做法","以上各項皆是"],a:0,e:"在普通法中，構成風險增加的狀況，只須在續保時\n通知保險人就足夠。答案A正確"},{c:"3.2.4",s:"以下哪項發生時不會延伸或恢復履行最高誠信",o:["保單續保時","索償有問題時","合約條款更改時","以上所有各項"],a:1,e:"保單續保或保單有效期內要求更改合約，須再履行\n最高誠信的責任。"},{c:"3.2.4",s:"保險人有時會把普通法中有關最高誠信責任加以延伸，要求投保人\n在保單上作出特定聲明，原因是",o:["沒有該項聲明，投保人就沒有最高誠信披露重要事實的責任","投保人僅就已提供的重要事實必須完全真實","投保人保證無論是否涉及重要事件，所提供的事實必須實質上真\n實","以上各項原因皆不是"],a:3,e:"保險人有時把普通法中的最高誠信責任加以延伸，\n要求投保人聲明或保證，無論是否與「重要」事件\n有關連，所有經披露的資料都必須完全地，不僅是\n實質地真實的。以上各項原因皆不正確"},{c:"3.2.4",s:"投保人於投保時遵守最高誠信以披露重要事實的期限",o:["只有保單持有人特別提出要求時予以延伸","法律並不容許予以延伸","一直至合約具約束力結束為止，並無例外","有時通過相互協議予以延伸"],a:3,e:"在普通法中，於保險合約訂立後，投保人才得知的\n重要事實，不必予以披露。所以，保險人有時通過\n相互協議予以延伸最高誠信以披露重要事實的期限"},{c:"3.2.4",s:"根據香港法律，投保人需要遵守最高誠信責任",o:["涉及整段保單有效期內","一直至保險人接受投保申請為止","一直至保險人交付保單為止","一直至簽署簽署及呈交投保書止"],a:1,e:"根據香港法律，投保人需要遵守最高誠信責任一直\n至保險人接受投保申請為止"},{c:"3.2.4",s:"以下哪一項是保單延伸最高誠信的根據?",o:["法定下","保單屬長期保單","欺詐性索償","以上各項皆不是"],a:3,e:"保單可能透過條款延伸最高誠信的要求，以上各項\n都不正確"},{c:"3.2.4",s:"根據普通法，投保人需要遵守最高誠信責任的期限",o:["直至索償為止","直至該合約生效為止","涉及整段合約生效時","僅至簽署投保書時為止"],a:1,e:"在普通法中，於保險合約訂立後，投保人才得知的\n重要事實，不必予以披露。"},{c:"3.2.4",s:"在保單有效期內若在風險上出現的重大轉變，以下哪項或哪些對於\n這些轉變的評論是正確的？",o:["在合約有效期內，要求披露重要資料是一種特殊做法","在普通法中，在保險期限內如有風險上的變更，必須予以披露","可能因保單條款的要求而需要披露這些轉變","以上所有各項皆是正確評論"],a:2,e:"在保單有效期內若在風險上出現的重大轉變，可能\n因保單條款的要求而需要披露這些轉變"},{c:"3.2.5",s:"欺詐性不披露，非欺詐性不披露、非欺詐性失實陳述及欺詐性失實\n陳述被視為違反",o:["一般誠信","普通誠信","至高誠信","最高誠信"],a:3,e:"欺詐性不披露，非欺詐性不披露、非欺詐性失實陳\n述及欺詐性失實陳述被視為違反最高誠信的類別"},{c:"3.2.5",s:"以下哪項不被視爲違反最高誠信原則？",o:["欺詐性不披露","非欺詐性失實陳述","非欺詐性不披露","以上各項皆不是"],a:3,e:"以上各項皆是被視爲違反最高誠信原則，答案D正確"},{c:"3.2.5",s:"以下哪三項通常被認為違反最高誠信的責任 ?\ni)真正忘記了以前的被爆竊事件﹝盜竊險﹞\nii)蓄意地隱瞞一個過去不良的索償記錄﹝火險﹞\niii)有意地提供良好健康證明,但明知事實與其相反﹝人壽保險﹞\niv)沒有披露一個自己完全不知情的健康情況﹝人身意外保險﹞",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii , iii , iv"],a:0,e:"沒有披露一個自己完全不知情的健康情況不會被被\n認為違反最高誠信的責任，選項iv不正確，正確答\n案是A"},{c:"3.2.5",s:"沒有披露以下哪項資料屬於違反最高誠信原則？",o:["入屋爆竊記錄﹝盜竊險﹞","某地方的戰爭事件﹝水險﹞","發泡膠相當易燃﹝火險﹞","已安裝自動灑水系統﹝火險﹞"],a:0,e:"入屋爆竊記錄屬增加風險的重要事實，沒有披露的\n話屬於違反最高誠信，正確答案是A"},{c:"3.2.5",s:"投保人蓄意在投保書上省略某項資訊，因為他認為該項資訊可能令\n保險人不給予他保障，就最高誠信而言，以上涉及?",o:["欺詐性不披露","非欺詐性不披露","非欺詐性失實陳述","欺詐性失實陳述"],a:0,e:"欺詐性不披露是欺詐性地不向另一方披露重要事實"},{c:"3.2.6",s:"假如被保險人違反最高誠信，保險人可作出以下哪項的補救行動",o:["可拒絕作出賠償，並於剩餘的保險期內把保單視為有效","保單開始日起取消保單","可提出侵權法訴訟要求損害賠償","以上各項皆是"],a:2,e:"如果屬於欺詐性或疏忽性失實陳述的情況，原則上\n還可以額外提出侵權法訴訟以索取損害賠償"},{c:"3.2.6",s:"如果被保險人違反最高誠信，保險人可使用以下哪些補救方法？\ni) 就該項索償拒賠\nii) 在剩餘的保險期限內把保單視為有效\niii) 保留部分已繳保費\niv) 保留全部已繳保費",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各項皆不是"],a:3,e:"受最高誠信違反所屈的保險人不能選擇就某項索償\n或保險金要求拒絕作出賠償或保險金給付，於剩餘\n的保險期限內把保單視為有效，並保留部分或全部\n已繳保費；這是因為只撤銷合約的一部分並不屬於\n可以執行的補救，以上各項皆不是被保險人違反最\n高誠信保險人可使用的補救方法"},{c:"3.2.6",s:"某投保人在投保火險保單時忘記披露某些重要事實，該保單的保費\n為港幣一萬二千元，而保險人在保單起保一個月後發現這件事，以\n下哪項為受屈的保險人可享用的補救",o:["保險人可選擇推翻保單，並保留保單的所有保費","保險人可選擇推翻保單，但須將已付的保費退回","保險人可選擇推翻保單，並保留一個月的保費(即港幣一千元)","保險人可選擇取消合約，並保留一個月的保費(即港幣一千二百元\n)"],a:1,e:"一般情況下，在不知道保險無效的情況下繼續支付\n的保費是可退回的"},{c:"3.2.6",s:"在保險合約中，下列哪項不屬於最高誠信的補救？",o:["受屈一方可推翻合約","受屈的保險人可以追回不知該項違反情況支付的賠償","受屈的一方可向另一方展開刑事檢控","如果涉及詐騙，受屈一方便可提出侵權法追求賠償"],a:2,e:"如果屬於欺詐性或疏忽性失實陳述的情況，保險人\n可以額外提出侵權法訴訟以索取損害賠償；侵權是\n一種民事錯誤，犯錯者可能被申索。"},{c:"3.2.6",s:"如果投保人違反了最高誠信",o:["只要牽涉詐騙的情況下，保險人可得到補救","保險人可以從起保日開始推翻有關合約","詐騙或疏忽的情況下，保險人可得到補救","該份保單會自動失效"],a:1,e:"從起保日開始推翻有關合約屬於投保人違反了最高\n誠信保險人的補救方法"},{c:"3.2.6",s:"如果投保人違反最高誠信",o:["保險人可不作追究","除非牽涉詐騙成份的情況下，保險人才可得到補救","除非牽涉詐騙或疏忽成份的情況下，保險人才可得到補救","保險保單會自動取消"],a:0,e:"只撤銷合約的一部分，並不屬於可以執行的投保人\n違反最高誠信補救措施，可行的是對違反不予追究"},{c:"3.2.6",s:"如果違反最高誠信，保險人可以",o:["拒絕賠償這次損失，合約在餘下時期內將被視為有效，可以索償","不再追究","如果已經錯誤賠償，可向被保險人提出刑事檢控要求損害賠償","以上所有各項"],a:1,e:"不追究是受屈的保險人針對違反最高誠信一方的其\n中一種補救方法"},{c:"3.2.6",s:"違反最高誠信的形式分別有欺詐性失實陳述，非欺詐性失實陳述，\n欺詐性不披露，非欺詐性不披露的四個類別，當中非欺詐性不披露\n是",o:["蓄意地提供虛假重要事實給另一方","無意地或疏忽地向另一方提供虛假重要事實","無意地或疏忽地漏了向另一方披露重要事實","蓄意地或疏忽地漏了向另一方披露重要事實"],a:2,e:"非欺詐性不披露是無意地或疏忽地漏了向另一方披\n露重要事實"},{c:"3.2.6",s:"就保單而言，非欺詐性不披露",o:["投保人無意地違反了保險條款","該保險人可以推翻保單","受屈的保險人僅可以訴訟提出損害賠償申索","投保人對重要事實作出失實陳述"],a:1,e:"非欺詐性不披露是無意地或疏忽地漏了向另一方披\n露重要事實，受屈的保險人可在合理時間内自始推\n翻整個合約"},{c:"3.2.6",s:"假如被保險人違反最高誠信，保險人可作出以下哪項的補救行動",o:["保險人可選擇推翻保單","可作出特定賠償，並於剩餘的保險期內把保單視為有效","可提出侵權法訴訟要求損害賠償","A&C"],a:3,e:"作出特定賠償，並於剩餘的保險期內把保單視為有\n效，並不是被保險人違反最高誠信，保險人可作出\n的補救行動，只有選項A&C正確"},{c:"3.3.1",s:"在保險中，近因是重要的，因為",o:["它找出購買保險的原因","需要確定被保險物的價值","並不是每一個引起損失的原因都是受保單保障的","根據情況保險人可能必須通知警方"],a:2,e:"一項損失或事件可以是數個成因合起來的力量所造\n成的。因為不是每一項成因都是受保的，為着保險\n索償或保險金要求的目的，必須於每一個案中抽出\n一個主導的成因。答案C正確"},{c:"3.3.1",s:"理解一項損失的主導及有效的原因",o:["彌償","近因","可保權益","比例分攤條件"],a:1,e:"近因是理解一項損失的主導及有效的原因"},{c:"3.3.1",s:"一種理解為「一項對損失最顯著及最具效力的理由」的保險原則為",o:["近因","分擔","最高誠信","可保權益"],a:0,e:"一種理解為「一項對損失最顯著及最具效力的理由\n」的保險原則為近因"},{c:"3.3.1",s:"因為幾乎所有保單都有除外責任，所以確定什麼是有效導致損失的\n原因是非常重要的，這類調查與下列哪項最有關係？",o:["分擔","近因","可保權益","最高誠信"],a:1,e:"一項損失或事件可以是數個成因合起來的力量所造\n成的。因為不是每一項成因都是受保的，為着保險\n索償或保險金要求的目的，必須於每一個案中抽出\n一個主導的成因。"},{c:"3.3.1",s:"近因在保險中非常重要，因為",o:["它確定了保險的存在","需要它確定投保物件的價值","不是所有引致的損失均受到保障","視乎情況，保險人可考慮通知警察"],a:2,e:"近因在保險中非常重要，因為不是所有引致的損失\n均受到保障"},{c:"3.3.1",s:"以下哪項有關近因原則的陳述是正確的",o:["它在所有保險類型中均屬重要","嘗試推斷一項損失的有效理由","它是一項與索償極其重要的原則","以上各項皆正確"],a:3,e:"一項損失或事件可以是數個成因合起來的力量所造\n成的。因為不是每一項成因都是受保的，為着保險\n索償或保險金要求的目的，必須於每一個案中抽出\n一個主導的成因。以上各項皆正確"},{c:"3.3.1",s:"近因",o:["對人壽保險來說從不重要","對所有索償情況來說均屬重要","從不被保單措詞所更改","符合以上各項的陳述"],a:1,e:"近因即是造成損失的原因，對所有索償情況來說均\n屬重要"},{c:"3.3.1",s:"以下哪項屬於近因中的”危險”?",o:["電單車","身體受傷","受傷僱員","盜竊"],a:3,e:"有關危險，意思是造成有關損失的成因，盜竊造成\n有關損失可以是其中例子"},{c:"3.3.1",s:'以下哪項屬於近因中被視為"危險"?',o:["地震","身體嚴重受傷","火警警報器故障","以上各項皆是"],a:0,e:"有關危險即是有關損失的成因，地震造成的損失"},{c:"3.3.1",s:'以下哪項屬於近因中被視為"危險"',o:["閃電","第三者財產損壞","珠寶被盜竊","木造建築"],a:0,e:"有關危險，意思是造成有關損失的成因，閃電造成\n有關損失可以是其中例子"},{c:"3.3.1",s:"下列哪項有關近因的陳述是正確的？",o:["它僅適用於財產保險","由一個以上的成因引致的損失，只有涉及保險風險引致的損失得\n到保障","由單一成因引致的損失是一項不保危險，便不能就所引致的損失\n得到保障","由一系列的事故引致的損失，只有首個的成因能構成近因"],a:2,e:"近因原則適用於所有保險類型，由一系列的事故引\n致的損失，首個或最後的成因不一定構成近因。如\n果只有單一成因，假如它是不保或除外危險便不受\n保，答案C正確"},{c:"3.3.2",s:"下列哪三種屬於決定一項損失的近因時，須予考慮的危險種類？\ni) 受保危險\nii) 不保危險\niii) 額外危險\niv) 除外危險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"額外危險是近因原則須予考慮的危險種類，選項iii\n不正確"},{c:"3.3.2",s:"就危險的種類而言，風險可被分類為三大風險，除了",o:["受保風險","除外風險","不保風險","純粹風險"],a:3,e:"純粹風險不是危險的三大種類"},{c:"3.3.2",s:"在考慮「近因」時，如果一項特定損失涉及一項單一成因，那麼",o:["如果該成因是一項受保危險，被保險人便能就所引致的損失得到\n保障","如果該成因是一項不保危險，被保險人便不能就所引致的損失得\n到保障","如果該成因是一項除外危險，被保險人便不能就所引致的損失得\n到保障","上述所有各項陳述均屬正確"],a:3,e:"如果只有單一成因，只有受保危險所引起的損失是\n受保的。如果涉及一項以上的危險，涉及除外危險\n的發生一般會令保險索償或保險金要求失敗，上述\n所有各項陳述均屬正確"},{c:"3.3.2",s:"構成損失近因時，有三種危險需要考慮，它們是除外危險、不保危\n險和",o:["受保危險","可保危險","不可保危險","因為保證而得不獲承保的危險"],a:0,e:"構成損失近因時，有三種危險需要考慮，它們是除\n外危險、不保危險和受保危險"},{c:"3.3.2",s:"就近因而言，描述相關承保風險所引致損失的成因稱為",o:["風險","危險","投機風險","事故"],a:1,e:"為了找出損失的近因，我們經常須要分析在整個引\n致該損失的過程中，所涉及的成因，這種分析很大\n程度上視乎有關危險(亦即有關損失的成因)的識別\n。"},{c:"3.3.2",s:"假設火險保單只保障火災或雷電帶來的損失或損壞。如果雨水透過\n開敞窗戶而進入室內而造成的損失是得不到保障的，因為其近因是",o:["除外危險","不保危險","外來危險","不可保危險"],a:1,e:"火險保單中，單單因為雨水造成損失屬不保危險"},{c:"3.3.2",s:"被保單條款明顯地剔除的保障範圍的損失原因稱為",o:["除外危險","不保危險","不受保危險","不被接受的危險"],a:0,e:"被保單條款明顯地剔除的保障範圍的損失原因稱為\n除外危險"},{c:"3.3.2",s:"除外危險_____________",o:["保單不承保的危險","與不保危險有相同的對待","除超額保障以外，將承保的危險","例如各種天災，地震等"],a:0,e:"除外危險是被除外責任條款豁免承保的"},{c:"3.3.2",s:'以下哪項屬於近因中被視為"危險"',o:["合約責任","金錢","職員盜竊","汽車損壞"],a:2,e:"危險，即是造成有關損失的成因，職員盜竊是造成\n財務有關損失的成因。"},{c:"3.3.2",s:"除外危險_____________",o:["也稱排除危險","與不保危險相同對待","除非保單分限額，否則將獲承保","自然災害等例如颱風"],a:3,e:"自然災害等屬基本風險，這些災害影響到整個社會\n或人類，對商業保險人來說基本風險，一般是不可\n保的除外危險"},{c:"3.3.2(c)",s:"就提供非全險形式的財產保險，既未被保單具體地承保或具體地豁\n免承保的損失原因屬於",o:["受保危險","不保危險","除外危險","非除外危險"],a:1,e:"就提供非全險形式的財產保險，既未被保單具體地\n承保或具體地豁免承保的損失原因屬於不保危險"},{c:"3.3.2(c)",s:"不保危險_____________",o:["依照近因原則可以是受保或除外危險","意思與除外危險等同","政策上被列為除外危險","包括自然災害，例如地震"],a:0,e:"不保危險既非受保的，也不是除外的，如果以一連\n串事故形式發生，引發不保危險的是某項受保危險\n，所引致的損失或事件可獲賠償或給付保險金"},{c:"3.3.3",s:"近因原則對於保險索償來說是一項非常重要的原則，它在保險索償\n的應用於",o:["人身意外保險","海上貨物保險","責任保險","以上全部皆是"],a:3,e:"近因原則對於保險索償來說是一項非常重要的原則\n，它在保險索償的應用於所有保險類別"},{c:"3.3.3",s:"近因原則在保險中極為重要，理由是",o:["並非所導致損失的起因都可得到保障","政府要求導致損失起因的數字","如屬被保險人的疏忽，保險人便毋須負責","如屬天災導致的損失或損害，保險人絕對毋須負責"],a:0,e:"近因原則在保險中極為重要，理由是並非所導致損\n失的起因都可得到保障"},{c:"3.3.3",s:"下列哪項或哪些有關近因的陳述是正確的？",o:["必須涉及一項受保危險；否則損失不可獲賠償","一項損失如果要受保障，其單一成因必須既不屬於除外危險，也\n不屬於不保危險","如果有一項除外危險引發了一連串事故，索償將會無效","以上所有各項"],a:3,e:"如果涉及一項以上的危險，視乎危險是否以一連串\n事故的形式發生或同時發生，若要索償有效，當中\n必須涉及一項受保危險，損害由一項除外危險所引\n致一般會令保險索償或保險金要求失敗"},{c:"3.3.3",s:"有一項索償個案，是關於由一宗﹝受火險保單所保障的﹞意外火災\n所導致的損失。火災發生的過程中，消防員為了獲取進入建築物的\n通道，以及用水撲救大火，引致進一步的損害。按照近因規則，因\n消防員所作努力而導致的損害",o:["只得到50%的保障，因為真正的成因是該宗火災","並非一項受保危險導致，所以得不到保障","是一項由受保危險導致的不保危險，因此得到保障","只能於火險保單已經伸延至保障這項風險時，才會得到保障"],a:2,e:"由受保危險直接引發的不保危險，所引致的損失可\n獲賠償，以火險單為例，水浸損失（不保危險）是\n由意外火災（受保危險）引起的是得到保障，答案C\n正確"},{c:"3.3.3",s:"近因適用於",o:["人壽保險而已","水險而已","責任保險而已","所有類型的保險"],a:3,e:"近因適用於所有類型的保險"},{c:"3.3.3",s:"以下哪些或哪項屬於應用近因原則的普遍規定?",o:["若要索償有效，必須涉及一項受保危險","若不屬意外責任，由不保危險導致的損害必會得到保障","損害由一項除外危險所引致，然而受保危險緊隨其後發生的話，\n仍可受到保障","以上各項皆是"],a:0,e:"如果涉及一項以上的危險，視乎危險是否以一連串\n事故的形式發生或同時發生，若要索償有效，當中\n必須涉及一項受保危險，損害由一項除外危險所引\n致一般會令保險索償或保險金要求失敗，只有答案A\n正確"},{c:"3.3.3",s:"就近因法則而言，以下哪項或哪些是正確的?",o:["如果損失的近因獲賠償；這一定不會是除外危險","損失的單一成因只涉及不保危險是不獲賠償的","損失是由不保危險引起的除外危險可得到保障","以上各項皆是"],a:1,e:"如果只有單一成因，假如該成因是受保危險所引起\n的損失是受保的，假如它是不保或除外危險便不受\n保。"},{c:"3.3.3",s:"就近因而言，以下哪項或哪些陳述是正確的?",o:["要構成有效的索償，近因不能屬於不保危險","如非單一成因引起，危險必須既不是不保危險，也不是除外危險\n，便可得到保障","由自然地來自除外危險導致的損害是不受到保障的","以上各項皆正確"],a:2,e:"如果涉及一項以上的危險，由受保危險直接引發的\n不保危險所引致的損失或事件可獲賠償，而除外危\n的發生，一般會令保險索償或保險金要求失敗。只\n有答案C描述正確"},{c:"3.3.3",s:"根據近因的一般原則，當雷電導致火警的話，以下哪類的損毀可按\n商業火險得到保障?\ni)電極造成的損毀\nii)有關火警對建築物造成的損毀\niii)濃煙對存貨造成的損毀，然而未有被火燒毀\niv)因嘗試以水救火而對建築物造成的損毀",o:["i，ii","ii，iii","ii，iii，iv","i，ii，iii，iv"],a:3,e:"如果損失是受保危險直接引發的不保危險，所引致\n的損失或事件可獲賠償或給付保險金，以火險單為\n例，水浸損失或濃煙對存貨造成的損毀等，是由意\n外火災引起的話會受到保障"},{c:"3.3.3",s:"以下哪項是描述「既不是受保也不是除外責任的危險，而是在保單\n保障的範圍以外」？",o:["受保危險","除外危險","不保危險","非受保特定危險"],a:2,e:"不保危險是「既不是受保也不是除外責任的危險，\n而是在保單保障的範圍以外」"},{c:"3.3.3",s:"某些受商業火險保障的存貨因火警的濃煙而毀於一旦，這項損失︰",o:["是不受保障的，因為濃煙並非受保危險","是不受保障的，因為濃煙必然屬於除外危險","是受保障的，因為有關摧毀是由受保危險引致的","必然可獲保險人的賠償，但只能是同情的顯示"],a:2,e:"濃煙造成的損失是由受保的，因為有關摧毀是由火\n警這類受保危險引致的"},{c:"3.3.3",s:"一個單位購買火險後，鄰居發生火警，在必要情況下，消防員需要\n破壞此單位某些設施進入鄰居救火，有關這些設施的損失",o:["因為受保危險引致不保危險，故此可得到賠償","因為不保危險引致受保危險，故此得不到賠償","屬於不保危險，故此得不到賠償","屬於受保危險，故此得到賠償"],a:0,e:"如果涉及一項以上的危險，由受保危險直接引發的\n不保危險 ，所引致的損失可獲賠償保險金"},{c:"3.3.3(iii)",s:"如果索償涉及______________，該項索償很有可能被拒",o:["不保危險","除外危險","自然災害造成的損失","人為錯誤"],a:1,e:"除外危險的發生一般會令保險索償或保險金要求失\n敗，但複雜的例外情況是存在的。"},{c:"3.3.4",s:"保險單",o:["從不更改近因原則","通常排除應用近因原則","可能包含更改應用近因原則的短句","符合以上各項陳述"],a:2,e:"很通常保險人借助某些保單措詞，更改近因法則的\n應用"},{c:"3.3.4",s:"在保險索償中，近因法則是",o:["不可以由保單條款來修改","往往可以由保單條款來修改","有時可以透過保單條款來修改","是絕對性的，不可經私人協議而修改"],a:2,e:"很通常保險人借助某些保單措詞，更改近因法則的\n應用"},{c:"3.3.4",s:"就保單的除外責任所採用的字眼規定某指明成因「直接或間接」所\n引致的損失皆是除外的，哪以下那幾項是正確?\ni)以上採用的字眼不能用於修改近因這項原則的應用\nii)與除外危險關係疏遠的損失也可能是除外的損失\niii)這有利於被保險人\niv)直接由除外成因引致的損失也是不受保障",o:["i, ii","ii, iii","ii, iv","i, iv"],a:2,e:"很通常保險人借助某些保單措詞，更改近因法則的\n應用，例如「直接或間接」引致的損失的保單除外\n條款，即使該除外危險的運作只構成一個疏遠近因\n，有關損失都將不獲賠償。選項ii， iv正確"},{c:"3.3.4",s:'由於在賠償過程中通常都會牽涉"近因"的運用，所以',o:["要視乎保險人的決定","可以由保單持有人提出證據便可以","運用時可能會受到某些限制及頗為複雜","需交由法院判決"],a:2,e:"如果損失涉及一項以上的危險，情況就比較複雜，\n視乎危險是否以一連串事故的形式發生或同時發生\n，而須引用不同的近因法則，答案C正確"},{c:"3.3.4",s:"一項保險原則，尋求保險人將受保財物恢復到其受毀或受損以前那\n一刻所處的狀況，這是甚麼原則?",o:["彌償","代位","最高誠信","可保權益"],a:0,e:"財產保險單通常訂明保險人可透過恢復原狀作為提\n供彌償的一種方法，它意指使受保財物恢復到其受\n毀或受損以前那一刻所處的狀況"},{c:"3.4",s:"以下哪兩項保險原理有相當密切的關係 ?\ni) 彌償\nii)分擔\niii)近因\niv)最高誠信",o:["i，ii","ii，iii","iii，iv","i，iii"],a:0,e:"只有當彌償出現時，分擔才會適用。所以該兩項保\n險原理有相當密切的關係"},{c:"3.4",s:"以下哪項保險原則與彌償沒有「直接」或「間接」的關係？",o:["代位","分擔","可保權益","最高誠信"],a:3,e:"彌償原則對於最高誠信沒有「直接」或「間接」的\n關係"},{c:"3.4.2",s:"人壽與人身意外保險都不受彌償的原則約束，因為",o:["人命是可以財務計算價值","不可能以財務方法精確計算人命的","保險人不願意作出十足的財務補償","以上所以各項"],a:1,e:"壽險及個人意外保險是提供利益的保單，而不是提\n供彌償的保單。因人命的損失不可能以財務方法精\n確計算，壽險及個人意外保險能辦到的僅是按照死\n亡或損傷訂明的數額支付利益"},{c:"3.4.2",s:"一名男子在撞車意外中死亡。他有意外死亡保單的保障，同時他的\n汽車保單提供死亡權益。在這情況下",o:["兩份保單均需作出賠償","只由最先生效的保單才需支付","只由保額較大的保單才需支付","由於是汽車意外，因此由汽車保單提供權益"],a:0,e:"壽險及個人意外保險是提供利益的保單，而不是彌\n償的保單。不適用彌償原則，所以它們僅是按照其\n就死亡或有關損傷訂明的數額支付利益，所有生效\n中的保單均需作出賠償"},{c:"3.4.2",s:"一男子在人身意外保單和汽車意外保單中投保了意外死亡利益。如\n他在駕駛自己的汽車發生了意外而死亡",o:["每份保單必須賠償死亡利益全數","僅僅首先生效的保單必須支付死亡利益","僅僅提供較大保額的保單必須賠償","既然死亡是由汽車意願導致，僅僅汽車保單須賠付"],a:0,e:"壽險及個人意外保險是提供利益的保單，而不是提\n供彌償的保單。因人命的損失不可能以財務方法精\n確計算，壽險及個人意外保險能辦到的僅是按照死\n亡或損傷訂明的數額支付利益，答案A正確"},{c:"3.4.2",s:"利益保險不適用於彌償的原則，因為",o:["利益的定義是可大可細難以確定","這是保險公司所定的法定條例","利益保單是涉及人壽及人身意外故此是不適用","彌償與利益保單是完全談不上"],a:2,e:"利益保險不適用於彌償的原則，因人命的損失不可\n能以財務方法精確計算，壽險及個人意外保險能辦\n到的僅是按照死亡或損傷訂明的數額支付利益"},{c:"3.4.2",s:"人壽及人身意外保單有時稱為「利益保單」，這是由於它們",o:["屬於人身保險，因此不受比例分攤的約束","在正常情況下都能提供補償","所提供的多於財務補償","按本身支付的金錢，無須繳稅"],a:0,e:"利益保險不適用於彌償的原則，因人命的損失不可\n能以財務方法精確計算，壽險及個人意外保險能辦\n到的僅是按照死亡或損傷訂明的數額支付利益，不\n受彌償原則下的比例分攤所約束"},{c:"3.4.2",s:"彌償是一項重要的保險原理，它通常應用於以下哪種業務類別？",o:["人壽保險","火險","人身意外保險","以上所有各項"],a:1,e:"彌償不能應用於一切保險類別。有些險種在計算損\n失時，無法確地用財務方法去量度，尤其是人壽保\n險及人身意外保險，彌償保險原則只適用於人壽保\n險及人身意外保險以外的其他類型的保險類型，例\n如火險"},{c:"3.4.2",s:"彌償原則一般不適用於以下哪項或哪些保險？",o:["醫療開支保險","汽車(本身損害保險)","人身意外死亡利益保險","以上各項皆是"],a:2,e:"彌償不能應用於一切保險類別。有些險種在計算損\n失時，無法確地用財務方法去量度，尤其是人壽保\n險及人身意外保險"},{c:"3.4.2",s:"如果一名持有多於一份人壽保險單的人士辭世，分擔是不適用於這\n些保單之間的，原因是",o:["它們並不保障相同的權益","它們不受彌償的約束","索償的近因相同","這些保單可能由同一名保險人簽發"],a:1,e:"壽險及個人意外保險是些提供利益的保單，它們不\n受彌償的約束。正因為這些保單不適用彌償原則，\n所以保單能辦到的，僅是按照其就死亡或有關損傷\n訂明的數額支付利益"},{c:"3.4.2",s:"下列哪項最能解釋彌償？",o:["補償","精確賠償","保單的實際保額","保險標的實際價值"],a:1,e:"彌償是指對損失作出既不多也不少的精確財務補償"},{c:"3.4.2",s:"彌償只能出現於",o:["人壽保險保單之間","提供收益的保單之間","非提供彌償的保單之間","提供彌償的保單之間"],a:3,e:"彌償只能出現於提供彌償的保單之間"},{c:"3.4.2",s:"以下關於彌償說明，哪一項是不正確的？",o:["它通常適用於非人壽保險的大多數險種","它僅僅適用於所謂的「利益保單」","它通常不適用於人身意外保險","從根本上說，它意味著對承保損失的準確補償"],a:1,e:"彌償是指對損失作出不多也不少的精確財務補償，\n與利益保單意思完全不相同"},{c:"3.4.2",s:"以下哪幾項關於彌償原則的描述是正確的？\ni.它通常不適用於人身意外及人壽保險保險\nii.從根本上說，它意味著對承保損失的精確財務補償\niii.人身意外及人壽保險保險不受彌償原則所約束\niv.根據保險業條例，普通法下的彌償原則往往可以通過私人協議予\n以修改",o:["i,ii,iii","i,ii,iv","i,iii,iv","i ,ii,iii,iv"],a:0,e:"人壽保險及人身意外保險所針對的都是人的傷亡，\n根本沒有任何方法可以把人命損失精確地用金錢來\n量度出來，所以這些類型的業務一般不適用彌償原\n則 。只有選項i,ii,iii正確"},{c:"3.4.2",s:"彌償原則合適用以上甚麼保險項目類型?",o:["人壽保險","醫療保險","人身意外保險","以上各項皆是"],a:1,e:"醫療保險於彌償原則合適用"},{c:"3.4.2",s:"人壽與保險不受彌償的原則約束，原因是",o:["無法精確計算人命價值","無限額的可保權益","無論支付多少錢不能精確地作出彌償","以上各項皆成立"],a:3,e:"人壽保險及人身意外保險所針對的都是人的傷亡，\n根本沒有任何方法可以把人命損失精確地用金錢來\n量度出來，所以這些類型的業務一般不適用彌償原\n則 。以上各項皆成立"},{c:"3.4.3",s:"作為在保險上的一項的重要原則，彌償同時與下列哪項或哪些保險\n原則有重要關聯？",o:["代位","分擔","可保權益","上述所有各項"],a:3,e:"可保權益是對某項標的的財務「權益」，就全損的\n情況下賠付多少錢才能讓保單持有人得到完全的彌\n償。另外，分擔及代位是彌償原則的引伸，上述所\n有各項都是與彌償有重要關聯"},{c:"3.4.3",s:"彌償和可保權益這兩項保險原則",o:["在財務上有密切的關係","兩項原則完全沒有關連","在意向上完全相反","是涉及損失的有效原因"],a:0,e:"可保權益是對某項標的的財務「權益」，其價值多\n少，就應在全損的情況下賠付多少錢，才能讓保單\n持有人完全的得到補償。所以，彌償和可保權益這\n兩項保險原則在財務上有密切的關係"},{c:"3.4.3",s:"一份恰當地安排的財產保險，於被保險的全損出現時，應可提供完\n全的補償。這項補償代表該名被保險人在有關財產上的權益，顯示\n彌償與以下哪一項的原則相連?",o:["近因","可保權益","最高誠信","以上所以各項"],a:1,e:"可保權益是對某項標的的財務「權益」，就全損的\n情況下賠付多少錢才能讓保單持有人得到完全的彌\n償。所以可保權益與彌償有重要關聯，答案B正確"},{c:"3.4.3",s:"以彌償原則而言，在某些情況下可容許賠償的金額可超過實際損失\n，而並不包括",o:["人壽保險","重置保險","以新代舊保障","約定價值保單"],a:0,e:"壽險及個人意外保險是提供利益的保單，而不是提\n供彌償的保單。因人命的損失不可能以財務方法精\n確計算，因人壽保險及人身意外保險一般可視為涉\n及價值無限的可保權益而不適用彌償原則"},{c:"3.4.3",s:"彌償與可保權益這兩項保險原則",o:["是完全相同的","是毫不相干的","與近因原則的關係非常密切","皆有共同的基礎，因爲他們均涉及被保險人的財務權益"],a:3,e:"可保權益是對某項標的的財務「權益」，就全損的\n情況下賠付多少錢才能讓保單持有人得到完全的彌\n償，所以彌償與可保權益這兩項保險原則，皆有共\n同的基礎，因爲他們均涉及被保險人的財務權益"},{c:"3.4.3",s:"「彌償」這項保險原則對以下哪項關係最為密切？",o:["可保權益","分擔","代位","以上全部皆是"],a:3,e:"分擔，代位是彌償原則的引伸，可保權益與「彌償\n」關係最為密切，以上各項皆是答案"},{c:"3.4.3",s:"以下哪項與彌償關係最小的保險原則？",o:["代位","分擔","最高誠信","可保權益"],a:2,e:"分擔，代位是彌償原則的引伸，可保權益與「彌償\n」關係最為密切，最高誠信保險原則與彌償關係最\n小"},{c:"3.4.3",s:"以下哪項與彌償保險原則沒有關係？",o:["可保權益","分擔","代位","退還財產"],a:3,e:"退還財產不屬保險原則"},{c:"3.4.4",s:"最為普遍，甚至在某些情況下是唯一的彌償方法?",o:["以現金支付","更換受保物品","維修受破壞的受保物品","將受保資產恢復原狀"],a:0,e:"以現金支付少對保險人而言，這是最方便的方法"},{c:"3.4.4",s:"以下哪項/哪幾項屬於提供彌償的方法？",o:["恢復原狀","更換","現金支付","以上各項皆是"],a:3,e:"以上各項皆是提供彌償的方法"},{c:"3.4.4",s:"更換一件受摧毀或失掉的受保物件時，可以作為一種提供彌償的形\n式，這種安排適合以下哪項情況?",o:["每類型的索償","僅限於汽車保險","完全沒有或只有少許折舊的物件","只有在盜竊是損失的近因時"],a:2,e:"就全新的、不受或幾乎不受折舊影響的物件而言，\n給被保險人一件替換物件可以是一種非常合適的彌\n償方法"},{c:"3.4.4",s:"以下哪項或哪些適用於修理受損財物作為提供彌償的方法？",o:["玻璃保險","法律責任保險","非全損汽車賠償","以上各項皆是"],a:2,e:"在部分損失的汽車險索償中，直接向修理者支付修\n理費是慣用的做法"},{c:"3.4.4",s:"如何支付彌償?\ni)支付現金\nii)修理\niii)更換\niv)恢復原狀",o:["i，iii，iii","i，iii，iv","ii，iii，iv","i，ii，iii，iv"],a:3,e:"以上各項皆是現金支付之外最常提供彌償最通常的\n方法"},{c:"3.4.4",s:"彌償最通常的方式是現金支付，其他方式包括？",o:["更換","修理","恢復原狀","以上各項皆是"],a:3,e:"以上各項皆是現金支付之外最常提供彌償最通常的\n方法"},{c:"3.4.4",s:"彌償最通常的方式是現金支付，其他方式包括？\ni更換\nii.修理\niii.續保\niv. 恢復原狀",o:["i,ii","ii,iv","i,ii,iv","i,ii,iii,iv"],a:2,e:"續保不是彌償的方法，選項iii不正確"},{c:"3.4.5",s:"作為計算彌償時予以考慮的一環，「損餘」應解作",o:["維修受損害物件時應付的金錢","搶救涉及索償的物件的成本","受到摧毀的保險標的剩餘部分","剛出現損害前該物件的價值"],a:2,e:"「損餘」應解作受到摧毀的保險標的剩餘部分"},{c:"3.4.5",s:"損餘在保險公司運作上，通常",o:["保險人是用作量度損失的準確金額時特別留下部份","與海上所指的救援費用同屬同一意思","只限汽車殘駭上的應用","無論任何情況下保險人只付一半賠償"],a:0,e:"保險標的在受損後留下剩餘部分，例如被火損壞的\n存貨 、 車輛的殘骸等 。 這些剩餘部分稱為損餘"},{c:"3.4.5",s:"在多數的財產保險索償中標的有時還有剩餘價值，該價值應於賠償\n給付中計算在內，稱為",o:["損餘","分擔","比例分攤","代位"],a:0,e:"在多數的財產保險索償中標的有時還有剩餘價值，\n該價值應於賠償給付中計算在內，稱為損餘"},{c:"3.4.5",s:"以下哪項對損餘的描述是不正確的?",o:["向保險人交出標的，以索取全部損失賠償金額的慣例","部分損失","損毀標的的剩餘部分","金額以下的任何損失，被保險人都得不到保障"],a:3,e:"當損餘由保險人收回並自行處理，保險人就會以全\n額賠償予被保險人，答案D不正確"},{c:"3.4.5",s:"以下哪項不是Salvage一詞的定義?",o:["在海商法中，有關財物擁有人向救助人支付的”救助賞金”","於非海上保險中，指保險標的受損後的殘餘價值","懲罰不足投保額","以上各項皆不是"],a:2,e:"懲罰不足投保額的比例分攤原則的英文名稱是Avera\nge。"},{c:"3.4.5",s:"以下哪項對Salvage一詞的定義不正確?",o:["保險標的在受損後會留下剩餘部分稱為 「損餘 」","在提供彌償時，必須把該價值考慮在內","在海商法中，“Salvage”一詞帶有截然不同的 意思","只有在懲罰投保額不足時適用"],a:3,e:"懲罰投保額不足的限制彌償原則是比例分攤(Averag\ne)，答案D不正確"},{c:"3.4.6",s:"以下哪項形容委付是正確的?",o:["大多數出現在水險中","於火險單中，通常剔除委付","將損餘交付保險人","以上各項皆正確"],a:3,e:"這個詞大多數出現在水險中，它是指在某些情況下\n向保險人交出保險標的，作為索取全損的賠償金額\n的條件。在水險中，這是一種十分標準的做法。不\n過在其他類別的財產保單中，通常明確地列明不容\n許委付。以上各項描述皆正確"},{c:"3.4.6",s:"當被保險人提出索償時，將損餘部份交予保險人以換取索取全數賠\n償。可能在機緣巧合下，在出售損餘後的款項高於實質賠償的金額\n，那麼",o:["保險人便可賺取不俗的利潤","盈餘須與被保險人以五五分賑形式分享","這項事宜須呈予法庭解決","盈餘須歸予被保險人"],a:0,e:"委付是保險標的或它的殘餘部分必須完全地移交給\n保險人，致使保險人可從中獲取利益"},{c:"3.4.6",s:"把保險標的委付給保險人，作為換取全損的賠償，一般多見於下列\n哪項保險?",o:["人壽保險","火險","水險","汽車保險"],a:2,e:"這個詞大多數出現在水險中，它是指在某些情況下\n向保險人交出保險標的，作為索取全損的賠償金額\n的條件。在水險中，這是一種十分標準的做法。答\n案C正確"},{c:"3.4.6",s:"以下哪項或哪些對「委付」一詞的評論是準確的？",o:["它在水險中較為普遍","在多數火險保單中，它通常被明確列明不予考慮","它是指向保險人交出保險標的","上述所有各項"],a:3,e:"這個詞大多數出現在水險中，它是指在某些情況下\n向保險人交出保險標的，作為索取全損的賠償金額\n的條件。在水險中，這是一種十分標準的做法。不\n過在其他類別的財產保單中，通常明確地列明不容\n許委付。以上各項描述皆正確"},{c:"3.4.6",s:"把受保財產的所有權交給保險人，以取得全損賠款的慣例稱為",o:["損餘","轉讓","代位","委付"],a:3,e:"這個詞大多數出現在水險中，它是指在某些情況下\n向保險人交出保險標的，作為索取全損的賠償金額\n的條件。在水險中，這是一種十分標準的做法"},{c:"3.4.6",s:"將某一損餘委付保險人，以取得全部的款項，這通常見於",o:["人壽保險","海上保險","火險","汽車保險"],a:1,e:"將某一損餘委付保險人，以取得全部的款項，這通\n常見於汽車保險"},{c:"3.4.7",s:"有些保單條款允許多於嚴格彌償的賠償，以下哪項不屬於這個範圍\n之內?",o:["比例分攤","約定價值保單","重置保險",'"以新代舊"保單'],a:0,e:"比例分攤屬限制彌償的保單條文，條款意味着它們\n規定的賠償金額比彌償金額為低，保單未能承諾向\n被保險人提供彌償"},{c:"3.4.7",s:"以下哪項對保單起賠額或免賠額的描述是正確的?\ni)兩種保單均減少瑣碎的索償\nii)兩種保單意味著相同的運作方式\niii)保單起賠額之保單會賠償全數損失如損失超過起賠額\niv)對少於起賠額的損失是不受保單的保障",o:["i，ii","i，iii","i，iii，iv","i，iv"],a:2,e:"保單起賠額與免賠額的作用相似，都是為了消除小\n額償。但不同之處是，當損失的金額超逾或達到起\n賠額時該損失時，便可全數獲賠償。免賠額是須要\n從每宗索償中扣除。選項ii不正確，正確答案是C"},{c:"3.4.7",s:"在水險中，術語「海損」的意思是",o:["部分(非全部)的損失","對不足額保險的懲罰","吸引標準保費率的風險","損失後標的的殘餘價值"],a:0,e:"在水險中，「海損」的意思所指的是部分損失，即\n不屬全損的損失。"},{c:"3.4.7",s:"以下哪項或哪些情況，限制彌償的法則的應用？",o:["保單免賠額","比例分攤的情況","保單起賠 (賠償額低於起賠額)","以上各項皆是"],a:3,e:"以上各項皆是限制彌償的保單條文"},{c:"3.4.7",s:"於香港處理財產保險的保險中介人，需盡力地確保客戶釐定投保額\n時最低限度代表財產價值。以下哪一項是出現投保額不足導致的後\n果?",o:["令該次索償無效","投保人需支付額外保費","賠償金額將可能受到比例分攤原則所約束","保險人將拒絕續保"],a:2,e:"大部分類型的非水險財產保險，均明文受比例分攤\n的限制。它的意思是保險人預期受保財產會以其全\n額的價值投保。否則，當出現損失時，賠付金額便\n會按不足額投保的比率遞減。"},{c:"3.4.7(a)",s:"多種財產保險中的保單條款都規定，如果發生損失時不足額保險存\n在，保險人的責任便會按不足額的保險價值的百分比遞減，這一項\n條款通常稱為？",o:["代位","分擔","比例分攤","保單免賠額"],a:2,e:"保險人預期受保財產會以其全額的價值投保。否則\n，當出現損失時，賠付金額便會按不足額投保的比\n率遞減。這是比例分攤的限制彌償的保單條文"},{c:"3.4.7(a)",s:"如果一份財產保險單被稱為「受比例分攤條件約束」，那麼它的意\n思是",o:["所代表的是一種標準風險，因此標準保費適用於該風險","不足額保險是不重要的","在任何情況下均不會對損失提供十足的支付","如果保額足夠的話，便會對損失提供十足的支付"],a:3,e:"大部分類型的非水險財產保險均受比例分攤的限制\n，保險人預期受保財產會以其全額的價值投保。否\n則，當出現損失時，賠付金額便會按不足額投保比\n率遞減。"},{c:"3.4.7(a)",s:"保險中介人在建議客戶購買保險時，當提醒客戶應就投保額與標的\n物價值相若，因為",o:["若保額不足會引致拒賠","確保保費物有所值","賠償時，數額會受比例分攤所約束","上述各項皆是"],a:2,e:"大部分類型的非水險財產保險均受比例分攤的限制\n，保險人預期受保財產會以其全額的價值投保。否\n則，當出現損失時，賠付金額便會按不足額投保比\n率遞減。"},{c:"3.4.7(a)",s:"在水險中，「海損(Average)」的含義是",o:["部分損失(全損以外的損失)","不足保障額的懲罰","超額賠償","上述各項皆不是"],a:0,e:"在水險中，「海損」(average)的意思截然不同，它\n所指的是部分損失，即不屬全損的損失。"},{c:"3.4.7(a)",s:"在香港處理財產保險的保險中介人，應該盡力確保客戶將要釐定的\n保額最低限度代表該財產的價值，因為如果有不足額保險出現的話",o:["該保額便告無效","有關的被保險人須支付額外的保費","任何索償相當可能受到比例攤分條款約束","有關保險人在續保時可以拒絕繼續提供保險"],a:2,e:"大部分類型的非水險財產保險均明文受比例分攤的\n限制。它的意思是，保險人預期受保財產會以其全\n額的價值投保。否則，當出現損失時，賠付金額便\n會按不足投保的比率遞減，稱為比例分攤"},{c:"3.4.7(a)",s:"損失$6,000，有關保單保額$1,000,000，該保單包含比例分攤及保\n單限額為$8,000，如受保物件實質價值為$3,000,000。保險人賠償\n多少？保險人在賠償後出售損餘價值為$300，請問就損餘部分之價\n值分配多少被保險人？",o:["$2,000；$0","$2,000；$200","$6,000；$0","$2,000；$600"],a:1,e:"價值300萬的財物，如果只投保100萬，不足額投保\n出現了比例分攤，被保險人只能夠收取三分之一的\n賠償金額，損失$6000元時只能賠付$2000元。\n另外，保險公司賠償三分之一的損失，就$300元損\n餘可分享三分之一的價值，即是$100元，餘下$200\n元損餘價值由被保險人收取。所以答案是B"},{c:"3.4.7(a)",s:"一件意外發生，損失財產金額為4,000元，受火險的保額為1,000,00\n0元並加入比例分攤條件及起賠額1,000元，實際的財產價值為4,000\n,000元，賣掉損毀的財產後得800元，被保險人可向保險人取得多少\n的賠償額？殘餘的餘額被保險人向保險人取回多少?",o:["1000元，600元","1000元，0元","4000元，0元","4000元，800元"],a:0,e:"價值400萬的財物，如果只投保100萬，不足額投保\n出現了比例分攤，被保險人只能夠收取四分之一的\n賠償金額，損失$4000元時只能賠付$1000元。\n另外，保險公司賠償四分之一的損失，就$800元損\n餘可分享四分之一的價值，即是$200元，餘下$600\n元損餘價值由被保險人收取。所以答案是A"},{c:"3.4.7(a)",s:"以下哪項對保險術語「比例分攤」的描述是不正確的？",o:["在火險中，它是對不足額的懲罰","在水險中，它的涵義與火險截然不同","它是對保險額不足的懲罰，應用於各種類型的保險","以上所有陳述皆不正確"],a:2,e:"「比例分攤」是對保險額不足的懲罰。只有大部分\n類型的非水險財產保險均明文受比例分攤的限制。\n答案C描述不正確"},{c:"3.4.7(a)",s:"以下哪項對保險術語「Average」的描述是正確的？\ni.在 大部分的海上保險中「Average」是部分損失的意思\nii.普 通法下，比例分攤自動應用於每一份保單\niii.在 香港，大部分非水險財產保險均應用到比例分攤\niv.比 例分攤原則用以懲罰投保額的不足",o:["i,ii,iii","i,iii,iv","ii,iii,iv","i,ii,iii,iv"],a:1,e:"只有大部分類型的非水險(財產保險)明文受比例分\n攤的限制，保險人預期受保財產會以其全額的價值\n投保，選項ii不正確，正確答案是B"},{c:"3.4.7(b)",s:"如果保單受x金額免賠額條約所約束，這就意味著",o:["如果損失超過x金額，得不到任何賠償","除非損失超過x金額，否則得不到任何賠償","超過x元的損失保險人全額賠償","保單保額受x元限制"],a:1,e:"免賠額規定損失超過免賠額金額，被保險人就可以\n得到扣除免賠額後的賠償金額，除非損失超過x金額\n，否則得不到任何賠償"},{c:"3.4.7(b)",s:"假設保單的免賠額是X，下列哪項有關的陳述是正確的？",o:["被保險人的首X損失將不獲保障","索償時會獲得最高X的賠償","索償超越X時，將獲全數賠償","被保險人需付額外X保費"],a:0,e:"免賠額規定損失超過免賠額金額，被保險人就可以\n得到扣除免賠額後的賠償金額"},{c:"3.4.7(b)",s:"免賠額與起賠額的分別，在於超過(或不低於)x損失的金額時",o:["超過x的免賠額，保險人支付十足的保障","超過x的起賠額，保險人支付十足的保障","超過x的免賠額，保險人收取額外x保費的要求","超過x的起賠額，保險人收取額外x保費的要求"],a:1,e:"免賠額規定損失超過免賠額金額，被保險人就可以\n得到扣除免賠額後的賠償金額，除非損失超過x金額\n，否則得不到任何賠償。起賠額不同之處是，當損\n失的金額超逾或達到起賠額時，該損失便可全數獲\n賠償。答案B正確"},{c:"3.4.7(b)",s:"在彌償中，下列哪些條件有時意味著比應予賠償為少的金額?\ni)保單免賠額\nii)保單起賠額\niii)約定價值保單\niv)水險保單",o:["i，ii","i，iii","ii，iii","iii，iv"],a:0,e:"保單免賠額及保單起賠額屬限制彌償的保單條文"},{c:"3.4.7(b)",s:"保單的免賠額是$1000元，哪麼意味著",o:["如果損失超過$1000元，將不獲任何賠償","如果損失$1000元以下，將不獲任何賠償","保額減去$1000元","賠償金額以$1000元為上限"],a:1,e:"免賠額是規定了低於某指定金額的任何損失，被保\n險人都不獲賠償。\n即是說，該金額將從每宗索償中扣除。"},{c:"3.4.7(b)",s:"以下哪項阻止了保單作出彌償?\ni.起 賠額\nii.免 賠額\niii.起 賠期限\niv.重 複保險",o:["i,ii","i,ii,iii","iii,iv","以上皆是"],a:1,e:"分擔適用於理賠時遇上重複保險的情況，更有效地\n達到彌償效果。選項(iv)不正確"},{c:"3.4.7(b)",s:"以下哪項阻止了保單為被保險人作出彌償?\ni.比 例分攤\nii.多 於二人有可保權益\niii.免 賠額\niv.起 賠額",o:["i,ii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"比例分攤，免賠額，起賠額屬限制彌償的保單條文\n，意味着規定的賠償金額 比彌償金額為低"},{c:"3.4.7(c)",s:"如果把水險保單描述為具有5%的起賠額，這意味著",o:["每項受保損失的5%全額賠償","受保損失是保額的6%即全額賠償","損失超過保額的5%，那麼5%是免賠的","超過起賠額5%的損失得不到保單保障"],a:1,e:"當損失的金額超逾或達到起賠額時，該損失便\n可全數獲賠償。答案B正確"},{c:"3.4.8",s:"下列哪項及哪些保單的保障，可以提供超越彌償的索償結清",o:["定值保單 (水險)","重置保單 (火險)","約定價值保單 (非水險)","以上所有各項"],a:3,e:"提供超額彌償的保單有約定價值保單，水險保單，\n重置保險及「 以新代舊 」 的保險保障"},{c:"3.4.8",s:"有些保單條款允許多於嚴格彌償的補償，以下哪項是不涉及範圍之\n內?",o:["比例分擔條件","約定價值保單","重置保險","以新代舊的保單保障"],a:0,e:"比例分擔條件,不屬於提供超額彌償的保單條文"},{c:"3.4.8",s:"一部電視機受火災損害時已經使用五年之久，損失維修費用$5,000\n，有關家居保險人全數支付，由此可推斷該保險由以下哪項訂立？",o:["「以新代舊」方式","商業重置保險","恢復原狀方式","約定價值方式"],a:0,e:"「以新代舊」的保險保障不會就損耗、折舊等因素\n扣減賠償金額，這詞一般較多用於家居風險單和船\n體保險單。"},{c:"3.4.8",s:"重置保險，「以新代舊」保障，約定價值保單及水險保單之共通點\n是",o:["不受彌償限制","同樣提供超越彌償","同樣適用於所有業務","跟彌償沒有關係"],a:1,e:"重置保險，「以新代舊」保障，約定價值保單及水\n險保單同樣提供超越彌償保單"},{c:"3.4.8",s:"保單的賠償額已決定，當損失出現時，保單就會承擔這個金額，這\n種賠償方式稱為",o:["重置保險","以新化舊","約定價值","水險保單"],a:2,e:"在非水險中，定值保單承諾在全損的情況下將支付\n這保額而不考慮損失時的實質價值，答案C描述正確\n。"},{c:"3.4.8",s:"下列哪項有關約定價值保單是正確的？\ni)折舊是最大的考慮因素\nii)保額視乎專家的估價\niii)這類保單可以用於價值較高的物件上，例如藝術作品\niv)當出現全損時，保單就會承擔專家估價的保額再扣除當時的折舊\n率",o:["i, ii","i, iii","ii, iii","iii, iv"],a:2,e:"約定價值保單或稱「定值保」的應用範圍包括價值\n高，並且不大可能顧及折舊因素，例如藝術作品、\n珠寶等。保額是基於專家的估值而釐定的，選項ii,\niii正確"},{c:"3.4.8",s:"大部分水險為「定值」保單，當發生事故時，賠償額是怎樣介定的?",o:["貶值，磨損貶值，折舊及損耗往往被扣除","於索償的被保險人必須提出財產的價值証明","如果財產如其價值，可以得到十足的賠償","不論財產是否如其價值，都可以得到約定金額的賠償"],a:3,e:"水險保單是以定值方式提供保險保障的，作為部分\n損失理賠和全損理賠這兩個目的，約定價值一律被\n視為損失時的實質價值。"},{c:"3.4.8",s:"一份海上船體保單的承保表是這樣寫的：「保額$1,000,000；約定\n價值$1,000,000」，意味着",o:["當一項損失發生時，保額是賠償金額","該約定價值將被視為損失時的實際價值，但只限於全損索償目的","約定價值一律被視爲損失時的實際價值","這是一份重置保險"],a:2,e:"水險保單和海上貨物保單是以定值方式提供保險保\n障的，約定價值一律被視為損失時的實質價值"},{c:"3.4.8",s:"一幢樓宇在地震倒塌時已使用二十年，它受到一份火險及其他附加\n條款保障，得到保險人賠付樓宇重建的成本，而不扣減損耗，此類\n屬於哪種保險",o:["「以新代舊」形式","不扣減形式","約定價值","重置保險"],a:3,e:"一幢樓宇在地震倒塌時已使用二十年，它受到一份\n火險及其他附加條款保障，得到保險人賠付樓宇重\n建的成本，而不扣減損耗，此類屬於重置保險"},{c:"3.4.8",s:"海上貨物保單是以定值方式提供保險保障，當出現全損索償時",o:["任何情況下均不會對損失提供十足的支付","索償時要求被保險人提供價值證明","受保財產必須以十足的價值投保","約定價值一律被視為損失時的實質價值"],a:3,e:"水險保單例如船體保單和海上貨物保單是以定值方\n式提供保險保障的，作為部分損失理賠和全損理賠\n這兩個目的，約定價值一律被視為損失時的實質價\n值。"},{c:"3.5",s:"代位和分擔有近似的目標，它們都是",o:["它們都有兩份保單","每份保單都有共同的保障","保險人向引致疏忽的人作出追討賠償","賠償額不能大於彌償"],a:3,e:"分擔及代位是彌償原則的引伸，由於人壽保單屬利\n益保單，不適用於彌償原則，正確答是D。"},{c:"3.5",s:"以下哪種情況，分擔原則不大可能被保單條款修改",o:["限制保單按特定比例支付金額","刪除更具體受保物件的保障","取消分擔按金額全數支付","有其他保單提供彌償，取消保障"],a:3,e:"比率之數條款或分擔條款把保險人的責任限於損失\n的某個比率份額。在重複保險的情況下，被保險人\n就不再可以單靠一個保險人而獲全額賠償。答案D不\n正確"},{c:"3.5",s:"分擔屬於下列哪項的重要原則之一?",o:["代位","彌償","委付","損餘"],a:1,e:"分擔屬彌償原則之引伸"},{c:"3.5",s:"代位及分擔有近似的目標，它們都是",o:["它們都有兩份保單","每份保單都有共同的保障","保險人向引致疏忽的人作出追討賠償","賠償額不可能大於彌償"],a:3,e:"分擔及代位是彌償原則的引伸，由於人壽保單屬利\n益保單，不適用於彌償原則，正確答是D。"},{c:"3.5.1",s:"如果發現保單持有人持有兩份保單來保障自已的財產(例如:盜竊)，\n合法的情況應該是",o:["他有權接受兩份賠償","因為這可能是欺詐，他將得不到任何賠償","僅僅是他投保的第一個保險人必須賠償損失","兩個保險人將得到最終分擔提供彌償的責任"],a:3,e:"當有兩份或以上被保險人自行購買的保單，遇上重\n複保險情況，並保障了相權益的保單，便會應用分\n擔原則，任何一位保險人將得到最終分擔提供彌償\n的責任，答案Ｄ正確"},{c:"3.5.1",s:"在「海上保險條款」中，關於「重覆保險」一項術語，這一項普通\n法的原則，並與以下哪項原則 有關",o:["彌償","代位","分擔","可保權益"],a:2,e:"在重複保險的情況下，如果每份保單均包含分擔條\n款的話，被保險人就不再可以單靠一個保險人而獲\n全額賠償。"},{c:"3.5.1",s:"如果被保險人投買了兩份保障相同損失的火險保單，對賠償分配的\n有關原則為",o:["分擔","可保權益","最高誠信","彌償"],a:0,e:"當有兩份或以上被保險人自行購買的保單，遇上重\n複保險情況，並保障了相權益的保單，便會應用分\n擔原則，任何一位保險人將得到最終分擔提供彌償\n的責任，答案Ａ正確"},{c:"3.5.1",s:"在重複保險上，以下哪項不應出現分擔原理？",o:["火險","盜竊保險","人身意外保險中的人壽利益部份","以上各項皆是"],a:2,e:"只有當彌償出現時，分擔才會適用。所以，假如一\n名購買了兩份或兩份以上獨立的人壽保險單的被保\n險人死亡，每份保單均因人壽保險不適用彌償原則\n，而須全額賠付。"},{c:"3.5.1",s:'假設銀行借錢給"A"購買物業，不尋常地，該銀行對該物業的權益購\n買保險保障，而"A"亦按照其意志投買保險，如果投保損失發生',o:["按照分擔原則，兩名保險人各自賠償50%","分擔原則不適用，因不是保險相同的權益","A的保單將作出賠償，因他是物業的真正擁有者","銀行的保單將作出賠償，因為借貸協定給它優先權"],a:1,e:"分擔原則不適用，因業主A與銀行所購買的保險所保\n障的權益不相同"},{c:"3.5.1",s:"以下哪項是標準火險保單理賠時遇上重複保險運用到的條款？",o:["保單限額","比率之數","比例分攤","以上各項皆不是"],a:1,e:"比率之數條款是在重複保險的情況下，如果有關的\n保單包含了這項條款，被保險人就不再可以單靠一\n個保險人而獲全額賠償"},{c:"3.5.3",s:"分擔的產生，必需符合以下哪項條件？",o:["每份保單都保障了受影響的權益","每份保單都保障了那個引致了損失的危險","每份保單都保障了受影響的保險標的","以上各項皆是"],a:3,e:"以上各項皆是分擔原則必須符合以下那些條件"},{c:"3.5.3",s:"A向X保險人購有汽車第三者保險，B向Y保險人購有汽車第三者保險\n，當 A 車撞 B 車，分擔原則並不適用，是因為",o:["兩者不是保障相同的標的物","兩者是由不同的保險人發出的保單","這是違法的","B不希望損失「無索償折扣」"],a:0,e:"分擔原則在此情況下並不適用，是因為兩份單分別\n地保障著不同的標的物"},{c:"3.5.3",s:"分擔必須符合以下那些條件：\ni. 每張保單必須對有關損失提供彌償\nii. 每張保單必須保障相同的保險標的\niii. 每張保單必須保障相同危險所導致的損失\niv. 每張保單必須保障相同的財務利益",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上各項皆是分擔原則必須符合的條件"},{c:"3.5.4",s:"保單持有人購買了一份意外死亡保險及汽車意外保險。若保單持有\n人在一次汽車意外中死亡，以下哪項索償是正確的？",o:["僅僅是首先生效的保單","僅僅是最大保額的保單","兩份保單也會作出賠償","由於是在汽車意外死亡，故只有汽車意外保險作出賠償"],a:2,e:"壽險及個人意外保險是些提供利益的保單，按照被\n保險人死亡或有關損傷訂明的數額支付利益"},{c:"3.5.4",s:"分擔的原則只會應用在",o:["人壽保險合約之間","提供利益的合約之間","非提供彌償的保險合約之間","提供彌償的保險合約之間"],a:3,e:"分擔的原則只會應用在提供彌償的保險合約之間"},{c:"3.5.4",s:"人壽及人身意外保單有時稱為「利益保單」，這是由於它們",o:["在正常情況下不能提供彌償","所提供的多於財政補償","按本身支付的金錢毋須繳稅","屬於人身保險，因此不受比例分攤的約束"],a:3,e:"壽險及個人意外保險提供利益的保單，而不是提供\n彌償的保單。正因為這些保單不適用彌償原則，亦\n不會受比例分攤的約束"},{c:"3.5.4",s:"如果發現保單持有人有兩份保險提供財產上的保障(例如:盜竊)，以\n下哪情況是正確的？",o:["保單持有人可以得到雙賠的賠償","因為可能涉及詐騙，兩份保單都不會作出賠償","第一份購買的保單會承擔所有的賠付","兩份保單會以共同分擔賠付"],a:3,e:"人壽及人身意外保單有時稱為「利益保單」，假如\n一名購買了兩份或兩份以上獨立的人壽保險單，被\n保險人死亡，每份保單均因人壽保險不適用彌償而\n須全額賠付。"},{c:"3.5.5",s:"一份有分擔成份的保單，保險人可以怎樣更改此分擔條款？",o:["在保單中，加入免分擔條款","限制個別保險人在損失上的分擔比例,例如：某個百分比","讓保險人向其他保險人尋找分擔機會","以上各項皆正確"],a:3,e:"以上各項皆有關分擔條款的正確陳述"},{c:"3.5.5",s:"當發生一項$1,000,000的財產損失，當中出現重複保險。此保單的\n全損為$30,000,000，另設有單一物件限制$5,000。這次總賠償金額\n為$995,000，這顯示以下哪項所述是正確的?",o:["所有其他有關保單都有分擔條款","這份保單有分擔條款","這份保單有比例分攤條款","所有有關保單均有比率之數條款"],a:1,e:"分擔條款又稱比率之數條款，把保險人的責任限於\n損失的某個比率份額。在重複保險的情況下，如果\n每份有關的保單均包含了這項條款的話，被保險人\n就不再可以單靠一個保險人而獲全額賠償。"},{c:"3.5.5",s:"衡平法中的分擔法則，可以利用保單條文按照以下哪項或哪幾項來\n修改？",o:["保單中加入免分擔法則","使任何其他現存保險毋須為有關損失賠償","保險人的總額限制在有關損失的一個份額比例","A 和 C 也正確"],a:3,e:"在衡平法中的分擔法則的情況下，任何一個保險人\n毋須顧及其他保單的存在，而按照自身的保單的規\n定進行賠付。答案A 和 C 正確"},{c:"3.5.5",s:"非海上保單的分擔條件",o:["該保單不適用分擔","把保險人的法律責任限制於他在損失中的比率之數","如果涉及重複保險，該保單便可使無效","該保單不可以尋求其他保單進行分擔"],a:1,e:"當有兩份或以上被保險人自行購買的保單，遇上重\n複保險情況，並保障了相權益的保單，便會應用分\n擔原則，分擔應用時，任何一位保險人對被保險人\n的損失應負的最終部分，被稱為該保險人的「比率\n之數」，只有答案Ｂ描述正確"},{c:"3.5.5",s:"一個家居保險可能有「更具體受保」的物件，是以下那個例子",o:["保証條款","免分擔條款","分擔條件","隱含保單條件"],a:1,e:"如果有架照相機單獨受一份“全險”保單承保，家\n居物件保單可把「更具體地受保」的物件列為除外\n責任，這就是免分擔條款的應用，令損失只由其他\n保險單賠償，答案Ｂ正確"},{c:"3.5.5",s:"購買火險中，可能包含一項海上條款，其含意是",o:["受到水險的保障下，不可與火險單作出分擔賠償","貨物在近水的倉庫儲存均受到保障","水險保單均可與火險保單共同作出賠償","上述所有各項皆不是"],a:0,e:"標準火險保單中的「海上條款」規定，如果在水險\n單與火險單之間存在潛在的分擔，火險單將不分擔\n損失"},{c:"3.5.5",s:"一份商業火險保險單含有所謂的「海上條款」，這條款的主要目的\n是",o:["豁免承保儲存在碼頭旁邊倉庫裡的財產","避免和任何足額水險分擔","確保任何承保了有關財產的現有水險無效","如果有水險保單也承保了有關財產，就可以完成避開火險保單"],a:1,e:"標準火險保單中的所謂「海上條款」規定，如果在\n水險單與火險單之間存在潛在的分擔，火險單將不\n分擔損失，答案Ｂ正確"},{c:"3.5.5",s:"以下那項條款是指「把保險人的責任限於它對損失的比率份額」？",o:["免分擔條款","比率之數條款/分擔條款","代位權","更具體受保條款"],a:1,e:"比率之數條款或分擔條款是把保險人的責任限於損\n失的某個比率份額。"},{c:"3.6",s:"容許已提供彌償的保險人，為本身的利益承繼並使用其被保險人對\n第三者的權利的保險原則為",o:["代位","分擔","重複保險","最高誠信"],a:0,e:"代位原則容許已提供彌償的保險人，為本身的利益\n承繼並使用其被保險人對第三者的權利"},{c:"3.6",s:"以下哪種情況會在第三者一方的疏忽後，出現代位的權利 ?",o:["被保人的辭世 (人壽保單)","被保險的建築物受到損害 (火險)","被保險人遭受嚴重傷害 (人身意外保單)","以上所有各項"],a:1,e:"與分擔的情況相似，只於彌償出現時，\n代位才能產生。火險單中被保險的建築物受到損害\n的情況可應付代位權原則"},{c:"3.6.1",s:"一宗撞車意外因為第三者疏忽而引起，在此情況下，請問「代位」\n在下列哪一項保險適用?",o:["人壽保險","意外保險","汽車保險","以上所以各項"],a:2,e:"與分擔的情況相似，只有彌償出現時，代位才能產\n生，人壽保險及人身意外保險屬利益保單，不適用\n於彌償原則。只有答案C正確"},{c:"3.6.2",s:"在下列哪項或哪些中，可以出現代位權",o:["侵權法下","損餘下","法規上","以上任何一種途徑"],a:3,e:"以上各項情況都是產生代位權"},{c:"3.6.2",s:"代位權的出現，是由第三者疏忽地對受保財產造成損毀，並且該財\n產的保險人承繼對疏忽人士行使法律權利。技術上，此代位權是來\n自",o:["侵權法","法規下","分攤","因他人的行為疏忽而負上責任"],a:0,e:"一般情況因第三者疏忽而引致了損失，這是在侵權\n法上產生的代位權"},{c:"3.6.2",s:"當第三者一方出現疏忽後，下列哪項情況不會產生代位？",o:["被保險人辭世﹝壽險保單﹞","受保財產的損害﹝火險保單﹞","受保汽車的摧毀﹝汽車保險單﹞","上述所有各項"],a:0,e:"與分擔的情況相似，只有彌償出現時，代位才能產\n生，人壽保險及人身意外保險屬利益保單，不適用\n於彌償原則。"},{c:"3.6.2",s:"一名僱員補償保險人巳向受害僱員作出賠償，在一項條款下可向疏\n忽的第三者索償，這是基於",o:["在侵權法上產生的代位權","在合約上產生的代位權","在法規下產生的代位權","在損餘中產生的代位權"],a:2,e:"一名僱員補償保險人巳向受害僱員作出賠償，在一\n項條款下可向疏忽的第三者索償，這是基於在法規\n下產生的代位權"},{c:"3.6.2",s:"代位如何出現?\ni) 在侵權法上\nii) 在合約上\niii) 在法規下\niv) 在損餘中",o:["i，ii，iii","i，ii，iv","ii，iii，iv","i，ii，iii，iv"],a:3,e:"代位權可透過以下多種方式產生，以上各項都是正\n確答案"},{c:"3.6.2",s:"代位的出現，大部份由於第三者疏忽地對受保財產造成損毀，並且\n該財產的保險人相繼向疏忽的人士行使法律權利。技術上，這意味\n著代位來自",o:["侵權法","法規","分擔","因他人行為而須負上的責任"],a:0,e:"代位的出現，大部份由於第三者疏忽地對受保財產\n造成損毀，並且該財產的保險人相繼向疏忽的人士\n行使法律權利。技術上，這意味著代位來侵權法"},{c:"3.6.4",s:"在普通法中，只有在給予彌償之後才可取得代位權，而保單的條件\n通常",o:["說明要在理賠後才可取得代位權","說明保險人可即時取得代位權","說明任何時候不可取得代位權","說明只有被保險人可擁有代位權"],a:1,e:"在普通法中，只有在給予彌償之後才可取得代位權"},{c:"3.6.4",s:"在委付及給予彌償後，保險人應如何處理售賣損餘中得到的利潤？",o:["將利潤歸還保單持有人","保險人和保單持有人五五分帳","利益歸保險人","保險人不可售賣損餘"],a:2,e:"在被保險人將投保財產委付給保險人之後，附於這\n財產的一切權利都屬於保險人，包括「從中牟利」\n的權利"},{c:"3.6.4",s:"在代位的補償上，如何處置因向第三者索取的多餘款項?",o:["屬於被保險人","屬於保險人","運用比例分攤","由保險人及被保險人平均分享有"],a:0,e:"保險人通過行使代位權而取得的補償，不能多於其\n支付的彌償金額。保險人只能保留相當於自己已賠\n付的金額，任何餘額則歸被保險人所有"},{c:"3.6.4",s:"就保險而言，普通法規定當提提供彌償後，可取得代位權。非水險\n保單條件",o:["從不可改變普通法的規定","在法律上不得更改普通法的規定","只當就索償結清達成後方給予保險人代位權","通常即時給予保險人代位權，以便馬上展開追償行動"],a:3,e:"在普通法中，只有在給予彌償以後，才可取得代位\n權，非水險保單通常規定，即使還沒作出彌償，保\n險人也能行使代位權。"},{c:"3.6.4",s:"對於一隻購買了全險的指環，在遺失後按照保額的5萬元如數結清。\n該指環稍後時間尋回並以6萬元售出。在代位的原則下，該1萬元的\n利潤",o:["屬於保險人","屬於被保險人","由保險人及被保險人平均分享","給付由保險人指明的慈善機構"],a:1,e:"在這情況下，保險人只能保留相當於自己已賠付的\n金額，任何餘額則歸被保險人所有。"},{c:"3.6.4",s:"建築商就一意外向一架私家車擁有人支付$13,000,000。因為一項每\n宗責任事故限額的應用，該名私家車司機只有向其責任保險人取得\n保險金$12,000,000。如果保險人後來向第三者追回$7,000,000，請\n問誰有權取得這筆錢?又怎樣分這筆金額?",o:["保險人佔 $7,000,000，被保險人沒有份兒","保險人沒有份兒，被保險人 $7,000,000","保險人佔 $6,000,000，被保險人 $1,000,000","保險人佔十三分之十二，被保險人佔十三分之一"],a:2,e:"因為保單限額的應用，被保險人尚欠100萬的賠償，\n如果保險人後來向第三者追回700萬，被保險人可分\n享100萬代位益，保險人則享餘下600萬"},{c:"4.1",s:"下列哪項業務較可能與產品開發部有關?\ni) 公共關係\nii) 產品研究\niii) 產品組合開發\niv) 個別產品開發",o:["i, ii","iii, iv","i, ii, iii","ii, iii, iv"],a:3,e:"公共關係不是與產品開發部有關，只有選項ii,iii,\niv正確"},{c:"4.1",s:"產品研究應將焦點放在",o:["本身的產品而已","競爭對手的產品而已","本身及競爭對手的產品","本身及競爭對手的產品，以及市場的趨勢"],a:3,e:"產品研究可從三個方面來考慮包括原有產品，競爭\n對手的產品及市場趨勢"},{c:"4.1",s:"以下哪項有關全新產品「具有競爭力的壽命」的描述是正確的？",o:["非常短，通常只有幾個星期或幾個月","大約一年","在競爭對手把焦點集中在新的保險產品之前， 至少兩年時間","非常之長"],a:0,e:"全新產品「具有競爭力的壽命」非常短，通常只有\n幾個星期或幾個月"},{c:"4.1",s:"市場上以「組合」形式推出的產品很多，這是屬於產品發展的什麼\n過程?",o:["個別產品的開發","產品組合的開發","產品的研究","獨立產品的開發"],a:1,e:"產品組合的開發以「組合」形式出現的產品，其中\n尤以大型的客戶為對象"},{c:"4.1",s:"以一籃子形式出現的保險開發，尤其針對大型客戶而設的，可以理\n解為",o:["產品開發","產品集體開發","團體開發","產品組合開發"],a:3,e:"產品組合的開發以「組合」形式出現的產品，其中\n尤以大型的客戶為對象，目的是維持競爭優勢"},{c:"4.1",s:"對於保險人，產品的開發",o:["是一種延續不斷的過程","對大型保險人來說是沒有必要的","對強制性的業務來說是沒有必要的","在敲定了保單的用字後便不再需要"],a:0,e:"對於保險人，產品的開發是一種延續不斷的過程"},{c:"4.1",s:"產品開發部門的主要功能可以是：\ni. 公共關係\nii. 個別產品的開發\niii. 產品組合的開發\niv. 產品的研究",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:2,e:"公共關係不是產品開發部門的主要功能，選項i不正\n確"},{c:"4.1",s:"產品開發是保險公司的重要功能，原因是",o:["產品開發有助於確保公司的財務穩定","香港有着競爭激烈的營商環境","可以看出，由於在過去幾年中保險監管框架的迅速變化，保險產\n品很快就過時了","必須根據不斷變化的法規要求對強制性保險單進行頻繁的修訂"],a:1,e:"由於香港有著開放又競爭激烈的營商環境，保險人\n在設計準備銷售的產品時，必須做到 高效而有活力"},{c:"4.1",s:"產品開發是保險公司的重要功能，原因是",o:["產品開發有助於確保公司的財務穩定","由於信息技術出現，保險產品很快就過時了","客戶對保險的需求不斷改變","新產品往往被競爭對手完全複製，因保險產品並沒擁有知識產權"],a:3,e:"個別產品的開發是一個延續不停的過程。由於競爭\n對手樂於倣效及抄襲別人的新產品，全新產品具有\n競爭力的壽命極為短暫，答案D正確"},{c:"4.1",s:"哪句說話最可以形容產品開發部的功能?",o:["針對小客戶而設","對維持保險公司的競爭力至為重要","為應付法規要求而設","純粹為行銷目的而設"],a:1,e:"由於競爭對手樂於倣效及抄襲別人的新產品，全新\n產品具有競爭力的壽命極為短暫，可能只有數個星\n期而已。"},{c:"4.10",s:"下列哪項屬於會計及投資部門的工作?\ni)紀錄保存\nii)款項收集\niii)付款\niv)投資",o:["i，ii，iii","i，ii，iv","ii，iii，iv","以上各項皆是"],a:3,e:"紀錄保存，款項收集，付款，投資都屬於會計及投\n資部門的工作。"},{c:"4.10",s:"保存記錄，收回保險人應收款項及繳付帳款應屬於以下哪一個範圍\n的責任?",o:["會計","核保","精算支援","培訓及發展"],a:0,e:"保存記錄，收回保險人應收款項及繳付帳款應屬會\n計部門的責任"},{c:"4.10",s:"下列哪項是保險公司的會計及投資部所負責的工作？",o:["保存準確及可靠的財務紀錄","確保收回保險人的應收款項","確保帳單及債項迅速及有效地繳付","以上所述各項"],a:3,e:"以上所述各項都是保險公司會計及投資部所負責的\n工作"},{c:"4.10",s:"以下哪項或哪些就會計及投資部對其投資組合須特別留意？",o:["安全性","流動性","收益性","以上所有各項"],a:3,e:"以上所有各項計及投資部對其投資組合須特別留意\n我地方"},{c:"4.11",s:"下列哪項有關培訓部的工作是正確？\ni) 同時培訓內勤，外勤人員\nii) 兼顧公司長遠發展\niii) 只有內部員工負責培訓\niv) 不斷更新個人培訓紀錄",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"不論由本身職員當導師，或由外界機構替本公司職\n員安排培訓，培訓與發展均是公司培訓人員的重要\n職責，選項iii不正確"},{c:"4.11",s:"不論培訓及發展部門主理或安排，當考慮培訓及教育時",o:["兩者所指的含義相同","永不會由公司內部的職員提供培訓","培訓的目的主要是預備公開考試","教育所涉及的，屬於對較為廣博知識的學習"],a:3,e:"教育這方面可視為對較為廣博知識的學習，及考取\n專業或有關資格，培訓可視可視為對現在的或未來\n的工作所作的準備，答案C正確"},{c:"4.11",s:"培訓及發展部門培訓對象是",o:["所有內部人員及外勤人員","外勤人員而非內部人員","非外勤人員是內部人員","既非內部人員也非外勤人員"],a:0,e:"培訓對於公司內部人員和外勤職員同樣必要。兩者\n在教育及培訓方面的需要實在不容忽視。"},{c:"4.11",s:"對於培訓及發展部門，以下哪項的描述是正確的？\ni.培訓對於內勤及外勤的員工同樣重要\nii.它必須與公司的需要配合\niii.它必須由非職員提供\niv.資源及紀錄對提高該部門的運作效率是非常重要的",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:1,e:"保險公司培訓工作可由本身職員當導師，或由外界\n機構替本公司職員安排培訓，選項iii不正確"},{c:"4.12",s:"關於管控要員，以下哪項陳述是正確的？",o:["由保險人委任","須取得保險業監管局的認可","為適當人選","以上各項皆是"],a:3,e:"管控要員在保險人的公司管治結構中扮演重要的角\n色。保險人在委任任何管控要員之前，必須先取得\n保險業監管局的認可，而保險業監管局只會認可其\n認為屬於適當人選的人被委任為管控要員。以上各\n項皆正確"},{c:"4.12",s:"保險中介人相當可能與擔當保險中介管理管控職能的管控要員互動\n，而所謂中介管理管控職能不包括",o:["管理相關保險人所委任的保險代理人","跟進保險代理人業績","監督保險代理人遵守《保險業條例》的情況","確保保險業務合規"],a:1,e:"跟進保險代理人業績不屬中介管理管控職能"},{c:"4.12",s:"保險人必須先取得保險業監管局的認可，方可委任＿＿＿＿？",o:["管控要員","公司的財務經理或財務行政人員","精算部門的職員","理賠部門的職員"],a:0,e:"保險人必須先取得保險業監管局的認可，方可委任\n管控要員"},{c:"4.2",s:"以下哪三方面有可能屬於客戶服務部門的職能範圍？\ni) 文件的提供\nii) 公共關係\niii) 索償的談判\niv) 一般的聯絡",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"索償的談判不屬於客戶服務部門的職能範圍，選項i\nii不正確"},{c:"4.2",s:"投訴、溝通、文件的提供及公共關係工作相當可能屬於以下哪個部\n門的職責?",o:["保險銷售部","客戶服務部","產品開發部","市場分銷及促銷部"],a:1,e:"投訴、溝通、文件的提供及公共關係工作屬客戶服\n務部部門的職責"},{c:"4.2",s:"以下哪項或哪些較可能屬於客戶服務的職能？",o:["對索償作出調查","與客戶聯絡","加強銷售計劃","以上各項皆是"],a:1,e:"客戶聯絡較可能屬於客戶服務的職能"},{c:"4.2",s:"處理投訴屬於客戶服務部的重要職責之一，這是因為下列哪項或哪\n些原因?",o:["投訴可能引起公眾的高度關注","投訴最可能達到公司內部的高層","處理投訴的方法，對客戶造成的影響","以上所有各項"],a:3,e:"以上所有各項都是處理投訴屬於客戶服務部重要職\n責的原因"},{c:"4.2",s:"客戶服務部若以職能界定來說也稱為",o:["顧客服務部","客戶投訴部","客戶諮詢中心","顧客溝通及投訴"],a:0,e:"客戶服務部若以職能界定來說也稱為顧客服務部"},{c:"4.2",s:"客戶服務是保險公司的主要功能，建立公司形象屬於哪種職責範圍?",o:["聯絡","公共關係","文件的提供","投訴"],a:1,e:"公共關係屬於市場行銷人員的職責範圍，然而接待\n客戶的方式，對於公司在大眾心目中的地位，起着\n深遠的影響。"},{c:"4.3",s:"以下哪一個部門負責有關廣告、公共關係及宣傳等工作？",o:["保單銷售","客戶服務","保單處理","市場行銷及促銷"],a:3,e:"市場行銷及促銷部門負責有關廣告、公共關係及宣\n傳等工作"},{c:"4.3",s:"市場行銷及促銷部主要負責哪項或哪些職務?",o:["協調對外的聯繫","協調媒介的查詢及採訪","準備新聞稿及副本予工商界及其他雜誌報章","以上各項皆是"],a:3,e:"以上各項皆是市場行銷及促銷部主要負責的職務"},{c:"4.3",s:"對於應告的工作，挑選公司以外的機構，採用其他媒介的深入程度\n，廣告活動的協調工作，很大可能是以下哪個部門的工作？",o:["客戶服務部","核保部門","市場行銷及促銷部","保險銷售部"],a:2,e:"對於應告的工作，挑選公司以外的機構，採用其他\n媒介的深入程度，廣告活動的協調工作，屬市場行\n銷及促銷部的職責"},{c:"4.3",s:"市場行銷部不斷地監察當前及潛在市場，這過程稱為",o:["宣傳","市場調查","監察","服務提昇"],a:1,e:"市場行銷部不斷地監察當前及潛在市場，這過程稱\n為市場調查"},{c:"4.3&4.4",s:"哪句說話最可以形容市場行銷及保險的銷售部門的關係?",o:["他們可以完全獨立運作","他們的工作出現高度重疊","他們向不同的管理層匯報","他們面對著不同的客戶群"],a:1,e:"保險銷售與市場行銷之間有着十分密切的關聯\n。在活動範圍上， 可能出現重大重疊"},{c:"4.4",s:"以下哪項不大可能屬於保險銷售部門的職能 ?",o:["產品各環節的聯繫","對索償作出調查","監察結果及趨勢","加強銷售計劃"],a:1,e:"對索償作出調查不屬於保險銷售部門的職能"},{c:"4.4",s:"下列哪項或哪些較可能屬於保險銷售部的工作範圍 ?",o:["産品聯絡","監察進度或趨勢","進行加強銷售計劃","以上各項皆是"],a:3,e:"以上各項皆是保險銷售部的工作範圍"},{c:"4.4",s:"保險銷售部門對結果和趨勢小心關注，這一個過程通常被稱為",o:["監察","審慎","市場調查","進度提升"],a:0,e:"保險銷售部門對結果和趨勢小心關注，這一個過程\n通常被稱為監察"},{c:"4.4",s:"下列哪一個部門與銷售部門關係最為密切?",o:["市場推廣","核保","保單服務","精算"],a:0,e:"部門與銷售部門與市場推廣關係最為密切"},{c:"4.4",s:"以下哪項是保險銷售部門的職能範圍?\ni.與 產品各環節建立緊密的聯繫\nii.加 強銷售計劃\niii.監 察銷售成果和趨勢\niv.印 制產品單張及宣傳刊物",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:0,e:"印制產品單張及宣傳刊物不是保險銷售部門的職能\n範圍"},{c:"4.5",s:"核保的職責是",o:["製備核保手冊、訂費指引","製備拒絕名單","界定承保的風險","以上皆是"],a:3,e:"以上皆是核保的職責"},{c:"4.5",s:"在人壽保險這個類別，核保顯得十分重要，因為",o:["被保險的對像是人類","保險人不能取消保單","通常人壽保險涉及大額的保費","人壽保險能為保險代理人提供較高的佣金"],a:1,e:"在人壽保險這個類別，核保顯得十分重要，因為保\n險人不能單方面取消保單"},{c:"4.5",s:"以下哪項屬於核保的範疇?\ni) 評估風險的可保性\nii) 釐定可保風險的條款\niii) 製備核保手冊和保費率指南\niv) 製備「拒絕名單」",o:["只有 i 及 ii","只有 ii 及 iii","只有 i, ii 及 iii","i, ii, iii, iv"],a:3,e:"以上各項都是保單核保須考慮的範疇"},{c:"4.5",s:"對於保險公司的運作來說，核保可解作",o:["銷售行動","對任何未能出售的股票承擔責任","作為保險目的而進行的風險評估","保單和其他合約文件私實際簽署"],a:2,e:"對於保險公司的運作來說，核保可解作為保險目的\n而進行的風險評估"},{c:"4.5",s:"以下哪項不大可能屬於核保部門的職能範圍?",o:["製備「拒絕名單」(不可接受的風險)","製備核保手冊","決定哪些是目標風險","處理涉及索償的投訴"],a:3,e:"處理涉及索償的投訴不屬於核保部門的職能範圍"},{c:"4.5",s:"壽險保單核保工作很重要，以下哪項原因是正確的",o:["保險標的是人類","保險人不能單方取消保單","壽險保單的保額通常巨大","壽險保單牽涉的佣金較大"],a:1,e:"壽險保單核保工作很重要，原因是保險人不能單方\n取消保單"},{c:"4.5",s:"以集中形式處理的核保最有可能出現在以下哪項或哪些中？",o:["人壽保險","旅遊保險","汽車保險","以上各項皆正確"],a:0,e:"以集中形式處理的核保最有可能出現在人壽保險"},{c:"4.5",s:"一項保險，保險人於其後時間不能取消，而且只可能對每項風險進\n行一次核保，此保險為",o:["人壽保險","汽車保險","海上船體保險","公眾責任保險"],a:0,e:"人壽保險一經生效可存在數十年，所以人壽保險核\n保機會只有一次。"},{c:"4.5",s:"以下哪項或哪些陳述有關一般保險核保是正確的?",o:["它們會集中在總部核部","它們涉及保障類型多不勝數","在每一份保單只能發生一次","包括以上各項"],a:1,e:"一般保險的保障類型多不勝數，答案B正確"},{c:"4.5",s:"以下哪項為一般保險業務的特點?\ni)它們會收集於總部處理\nii)它們的處理保障類型多不勝數\niii)保單在續保時，條件可以檢討，在必要時保單甚至可以取消\niv)它們只能每年處理理賠一次",o:["i，ii","ii，iii","iii，iv","i，iv"],a:1,e:"一般保險的保障類型多不勝數。核保過程中出現的\n錯誤並不是永久性的，保單在續保的時候，條件可\n以檢討，必要時保單甚至可以取消，核保權限可以\n較為分散。只有選項ii，iii描述正確。"},{c:"4.5",s:"以下哪項或哪些陳述有關一般保險核保是正確的？",o:["它們會集中在總部核保","它們涉及廣泛保障範圍的考慮","在每一份保單只能發生一次","包括以上各項"],a:1,e:"一般保險的保障類型多不勝數。核保過程中出現的\n錯誤並不是永久性的\n，在續保的時候，條件可以檢討，必要時保單甚至\n可以取消，因此核保權限可以較為分散。"},{c:"4.5",s:"下列哪一項有關一般保險業務的陳述是錯誤？",o:["核保會採取較較為分散的處理方式","業務範圍十分廣泛","涉及之業務風險甚高","其賠償涉及複雜的紅利計算"],a:3,e:"只有人壽保險才涉及複雜的紅利計算"},{c:"4.5",s:"人壽保險核保部門眼中的「目標風險」，較可能屬於以下哪類風險\n？",o:["極高保額的風險","保險人尤其願意承保的風險","保險人尤不願意承保的風險","有關保險代理人可得到較高佣金率的風險"],a:1,e:"目標風險在人壽保險中可以解釋為極為合意的業務\n類型"},{c:"4.5",s:"對人壽保險人是極為合意的業務類型，或在非壽險中有時指廣泛，\n危險性高的風險術語？",o:["純粹風險","目標風險","特定風險","基本風險"],a:1,e:"對人壽保險人是極為合意的業務類型，或在非壽險\n中有時指廣泛，危險性高的風險術語是目標風險"},{c:"4.5",s:"在非人壽保險中的目標風險是",o:["保額低的指定風險","保險人極為合意的業務類型","保險人極不合意的業務類型","給予中介人佣金率最高的風險"],a:2,e:"在非人壽保險中的目標風險是保險人極不合意的業\n務類型"},{c:"4.5",s:"對於長期業務保險人而言，「目標風險」是指",o:["涉及高死亡率的風險","保險人願意承保的風險","保險人不願意承保的風險","足夠令保險代理人應付年度保單數額的風險"],a:1,e:"對於長期業務保險人而言，「目標風險」是指保險\n人願意承保的風險"},{c:"4.5",s:"火災保險中，「目標風險」一詞指",o:["沒有什麼價值的投保物件","一項大的，很高的風險","一項普遍的風險","很低的保險費率"],a:1,e:"火災保險中，「目標風險」一詞指一項大的，很高\n的風險"},{c:"4.5",s:"對於核保部門而言，「拒絕名單」涉及︰",o:["應予鼓勵接受更多的風險","不應予鼓勵接受風險或應拒風險","代理人在該年度內無須接受更多業務的指示","直到繳交保費前無須接受新業務的指示"],a:1,e:"對於核保部門而言，「拒絕名單」涉及不應予鼓勵\n接受風險或應拒風險"},{c:"4.5",s:"對於保險公司的運作來說，核保可解作",o:["銷售行動","對任何未能出售的股票承擔責任","作為保險目的而進行的風險評估","保單和其他合約文件實際簽署"],a:2,e:"對於保險公司的運作來說，核保可解作作為保險目\n的而進行的風險評估"},{c:"4.5(b)",s:"在一般保險承保中，以下哪項是出現錯誤的優勢?",o:["錯誤從不可犯","保單在續保時，條件可以檢討，在必要時保單甚至可以取消","錯誤可用計算機自動修正","錯誤有特別的保單承保"],a:1,e:"一般保險的核保過程中出現的錯誤並不是永久性的\n，保單在續保的時候，條件可以檢討，必要時保單\n甚至可以取消 。正確答案是B"},{c:"4.6",s:"保單處理包括",o:["簽發保單","處理誤差","預備文件簽署","上述各項皆是"],a:3,e:"上述各項皆是保單處理包括的程序"},{c:"4.6",s:"對很多險種來說，通常在收到保費之前保障已經開始生效，但是，\n以下哪業務種類幾乎總是根據第一筆保費才能確定合約的存在",o:["人壽保險","火災保險","人身意外保險","以上各項皆是"],a:0,e:"對於人壽保險，首次保費的實際繳付的重要性是不\n容忽視的。"},{c:"4.6",s:"查核保單的準確程度及續保，相當可能屬於以下哪個部門的工作?",o:["理賠","核保","保單處理","市場行銷及促銷"],a:2,e:"查核保單的準確程度及續保，相當可能屬保單處理\n部門的工作"},{c:"4.6",s:"實際保單文件對於以下哪種保險業務是最重要的",o:["責任保險","人壽保險","火險","汽車保險"],a:1,e:"比起一般保險業務，人壽保單内容出錯，所引起的\n後果嚴重得多，實際保單文件對人壽保險業務是最\n重要的"},{c:"4.6",s:"蘇先生致電保險公司投保一份火險，而保險公司承諾可在事後發出\n保單，但蘇先生未繳付保單的保費，但1小時後貨物被火災損毀，請\n問這份保單有效嗎？",o:["否，要約沒有存在","否，保單還沒出","是，代理人在對話中一承認保單，保單已經有效","一份有追溯性的保單合約，在付保費時生效"],a:2,e:"人壽保險以外的其他類型的業務，合約可於還未收\n到保費時便開始生效，答案C正確"},{c:"4.6",s:"就保單處理方面，一般保險及人壽保險的區別是",o:["一般保險提出索償時須要出示保單文件的正本","壽保險單屬可選文件","人壽保險單提出索償時必須出示人壽保單，一般保險就不需要","一般保險更複雜"],a:2,e:"就保單處理方面，一般保險及人壽保險的區別是人\n壽保險單提出索償時必須出示人壽保單，一般保險\n就不需要"},{c:"4.6(d)",s:"以下哪項人壽保險支付保費的獨特之處?",o:["保費只可以按年繳方式支付","保費可以於保單生效的何時間支付","合約生效取決於是否實際繳付首次保費","保費只可以整付方式支付"],a:2,e:"人壽保險合約生效取決於是否實際繳付首次保費"},{c:"4.6(d)",s:"人壽保險合同的保費支付有著獨特之處，以下哪項描述是正確?",o:["總是每月形式支付","人壽保險的保費較一般保險為低","合同存在與否是看是否收到第一期保費","保費可於保險期內任何時間支付"],a:2,e:"人壽保險合同存在與否是看是否收到第一期保費"},{c:"4.7",s:"以下哪項不是一般業務的處理範圍",o:["計算彌償","運用比例分攤","計算及處理保單抵押貸款","應用代位"],a:2,e:"計算及處理保單抵押貸款是屬人壽保險業務處理範\n圍"},{c:"4.7",s:"一般保險的理賠部門，不大考慮以下哪項?",o:["分擔","尚未償還私貸款","代位權的可能性","比例分攤的應用"],a:1,e:"尚未償還私貸款不屬一般保險的理賠部門的職責"},{c:"4.7",s:"在處理死亡索償時，有些要特別注意的地方，包括賠償利益及",o:["權益的轉讓","紅利","保單中未清償的保單貸款的貸款數額","以上所有各項"],a:3,e:"以上所有各項是在處理死亡索償時需要處理的程序"},{c:"4.7",s:"以下哪項可能對人壽保險理賠造成一定的影響?\ni)還未清償的保費貸款\nii)與受益人有關的複雜事項\niii)轉讓保單予第三者的可能性\niv)對死者死亡的真確性或身份存在不確定因素",o:["i，ii","ii，iii","i，iii，iv","i，ii，iii，iv"],a:3,e:"以下各項都可能對人壽保險理賠造成一定的影響"},{c:"4.7",s:"人壽保險中的理賠部不會處理以下哪項?",o:["運用比例分攤","分紅/不分紅","轉讓","繳清的保單貸款"],a:0,e:"運用比例分攤不是人壽保險中的理賠部會處理的事\n項"},{c:"4.7",s:"對於一般保險理賠部門來說，以下哪項有關的陳述是不正確的?",o:["非集中形式處理索償是頗為普遍的","責任索償可能涉及大額款項","可能出現的理賠範圍比人壽保險要大","在支付紅利的情況下，必須小心核對有關的保單"],a:3,e:"計算保單紅利不是一般保險理賠部門會處理的事項"},{c:"4.7",s:"在作出人壽保險理賠時，理賠人員需要考慮以下哪些問題？",o:["可能出現還未清償的保單貸款","對於實際死亡的界定或死者的身分存在不確定的因素","對於分紅／分利保單之紅利／股息的考慮","以上各項皆是"],a:3,e:"以上各項皆是在作出人壽保險理賠時，理賠人員需\n要考慮的問題"},{c:"4.7",s:"以下哪一項商業保險的理賠工作以非集中形式進行的可能性最小",o:["人壽保險","旅遊保險","汽車保險","家居保險"],a:0,e:"人壽保險一項商業保險的理賠工作以集中形式進行\n的，而一般保險的理賠工作以非集中形式進行的"},{c:"4.7",s:"對大多數非人壽保險索償，保險人支付數額均經過認真核實，用以\n描述索償支付數額的名詞為",o:["數額","數量","可追回金額","保險人的分擔"],a:0,e:"保險人支付數額均經過認真核實，用以描述索償支\n付數額的名詞為數額"},{c:"4.7",s:"對於保險理賠，應該注意的包括數額(索償時的賠付)及",o:["被保險人所承擔的法律責任","保險人對索償人的法律責任","保險人及被保險人共同負上的法律責任","保險人及被保險人均不須負上任何法律責任"],a:2,e:"對於保險理賠，應該注意的包括索償時的賠付數額\n及保險人及被保險人共同負上的法律責任"},{c:"4.7",s:"在處理人壽和非人壽保險賠償時有兩項共通特點，就是數額及",o:["如何提供彌償的問題","代位權的問題","責任問題","分擔問題"],a:2,e:"在處理人壽和非人壽保險賠償時有兩項共通特點，\n就是數額及責任問題"},{c:"4.7",s:"處理人壽及非人壽索償時有的共同特性是數額的問題及",o:["如何處理彌償的問題","分擔的問題","責任的問題","代位權的問題"],a:2,e:"處理人壽及非人壽索償時有的共同特性是數額的問\n題及責任的問題"},{c:"4.7",s:"以下哪項不是人壽保險理賠部所考慮的範圍？",o:["退休策劃","紅利因素","保單轉讓","有否未清還之保單貸款"],a:0,e:"退休策劃不是人壽保險理賠部所考慮的範圍"},{c:"4.7",s:"人壽保險中的理賠部不會處理以下哪項？",o:["運用比例分攤","分紅/不分紅","轉讓","未繳清的保單貸款"],a:0,e:"人壽保險中的理賠部不會運用比例分攤處理索償"},{c:"4.7(a)",s:"以下哪項不屬人壽保險的理賠樣須考慮的問題?",o:["對於死亡的真確性或死者的身份","驗證最大賦值","可能有還未清償的保單貸款","分紅保單涉及紅利／股息的因素"],a:1,e:"驗證最大賦值不屬人壽保險的理賠樣須考慮的問題"},{c:"4.7",s:"所有的保險索償須驗證甚麼?",o:["投保人當前的地址","保費最近支付日期","保險人對保單承擔的責任","代理人佣金結構"],a:2,e:"處理任何保險賠案時，保險人應該承擔的賠償責任\n及給付數額都是必須解決的共同問題。"},{c:"4.8",s:"如果保險人覺得他的潛在責任高得難以接受，他可能把自己的部份\n風險向另外的保險人投保，這一過程稱之為︰",o:["再保險","重複保險","重複彌償","輔助保險"],a:0,e:"保險人根據一個或以上的保險合約所承擔的風險，\n可以完全或部分地通過保險轉移到其他保險人身上\n，這種保險稱為再保險"},{c:"4.8",s:"就再保險而言，以下哪些或哪項是保險人再保險的理由?",o:["《保險業條例》中，保險人必須有足夠的再保險","購買再保險是為了穩健，降低保險人的風險","提高再保險人的「承保能力」","以上各項皆是"],a:3,e:"以上各項皆是保險人購買再保險的理由"},{c:"4.8",s:"下列哪項關於再保險的陳述是正確的？",o:["這是當認為某風險的現有保單不能提供足夠的保障時多買一張保\n單的過程","大客戶一般會要求保險人購買再保險，原因是再保險會對他們產\n生直接的影響","保險人有時會利用再保險來把變現風險降低，可以想像發生災禍\n後，可能在短時間內需要大量現金","由於再保險的費用高昂，再保險的使用只限於恐怖襲擊和核事故\n風險上"],a:2,e:"個別索償要在短時間內預備大量現金，可能引起不\n便，再保險的重要原因是為了提高保險人的「承保\n能力」，再保險對於保單持有人沒有直接的影響，\n亦無權知道，只有答案C陳述正確。"},{c:"4.8",s:"下列哪項有關「再保險」的陳述是正確的？",o:["對投保人沒有直接影響","分擔保險人災難性的保障","提高保險人承保能力的一種方法","上述各項皆是"],a:3,e:"再保險的重要原因是為了提高保險人的「承保能力\n」，再保險對於保單持有人沒有直接的影響，亦無\n權知道，以上各項陳述正確。"},{c:"4.8",s:"以下哪項描述再保險是正確的?",o:["當保險人分出再保險後，不用知會被保險人","再保險人需要承擔某程度的風險損失","為大規模的風險提供分擔賠償","以上所列各項"],a:3,e:"再保險的重要原因是為了提高保險人的「承保能力\n」，再保險對於保單持有人沒有直接的影響，亦無\n權知道，以上各項陳述正確。"},{c:"4.8",s:"再保險的目是",o:["因擔心一份保險不能提供足夠賠償而另外再多買一份保險","協助保險人可能突然需要增加的變現能力，可以預期一旦出現天\n災等引致的索償倍增，再保險人可為保險人提供額外的賠償能力","再保險成本高昂，只應用於可能有恐怖分子襲擊或核設施等項目\n作出再保險","為保險人提供資本上的回報"],a:1,e:"個別索償要在短時間內預備大量現金，可能引起不\n便，再保險的重要原因是為了提高保險人的「承保\n能力」，答案B正確"},{c:"4.8",s:"以下哪項有關再保險的陳述是正確的？",o:["再保險是當某風險的保障不足時購買再保險","大客戶要求其中小保險人購買再保險","再保險的費用很高，所以只限於恐怖襲擊及核事故","保險通過一個或以上的保險合約，把他已經受保的風險的部分或\n全部轉移至另一保險人"],a:3,e:"保險人根據一個或以上的保險合約所承擔的風險，\n可以完全或部分地通過保險轉移到其他保險人身上\n，這種保險稱為再保險"},{c:"4.9",s:"最可能涉及訂定保費率，計算儲備及債務估值的專業人士為",o:["損失公估人","精算師","會計師","核保人"],a:1,e:"涉及訂定保費率，計算儲備及債務估值的專業人士\n為精算師"},{c:"4.9",s:"保險業條例要求所有從事長期業務的保險人，委派一名合資格的精\n算師，並要求",o:["每年呈交一份屬於該保險人的獨立死亡率報告","對該保險人的所有資產及負債進行最少一年一次的評估","每年呈交一份索償報告","以上所列各項要求均要達致"],a:1,e:"險業條例要求所有從事長期業務的保險人，委派一\n名合資格的精算師，並要求對該保險人的所有資產\n及負債進行最少一年一次的評估"},{c:"4.9",s:"一種要經過一段時間後，索償才會出現或形成的保險，精算師可說\n是居功不少，以下哪個是正確的。",o:["長期責任業務","短期責任業務","長期保單","長期業務"],a:0,e:"在長期責任業務在計算所需未決申索儲備金，尤其\n需要精算師的專業知識"},{c:"4.9",s:"最可能協助保費率，儲蓄及債務估值方面計算的部門是",o:["精算支援","保單處理","培訓及發展","會計及投資"],a:0,e:"協助保費率，儲蓄及債務估值方面計算的部門是精\n算支援"},{c:"4.9",s:"以下哪項就精算支援的描述是正確的?\ni.《 保險業條例》要求所有獲授權保險人必須委任一名合資格並被\n保監局接納的精算師\nii.精 算師的主要職責是對所有資產及負債進行評估\niii.只 有人壽保險需要精算支援\niv.精 算支援負責估算所需的未決申索儲備金",o:["ii,iv","i,ii,iv","ii,iii,iv","i,iv"],a:0,e:"《保險業條例》要求所有從事長期業務的保險人，\n委任一名合資格並被保險業監管局接納的精算師。\n人壽保險及一般保險需要精算支援。所以選項ii\n及iv才正確。"},{c:"4.9(b)",s:"在一般保險中，以下哪項是「長尾業務」的特點?",o:["索賠可以在短時間內結清","保單承保時間較長","索賠時間很長，例如長至保單終期後五年甚至更長的時間","保單支付的時間很長"],a:2,e:"在長期責任業務 (long-tail business)，\n這類業務的索償過程，從產生到之後的發展往往經\n歷一段長時間，例如長至保單終結後五年甚\n更長的時間"},{c:"5.1.1",s:"按照《保險業條例》對業務的分類方式，以下哪項或哪些屬一般保\n險的分類",o:["意外","陸上車輛","船舶 (法律責任)","以上各項皆是"],a:3,e:"以上各項皆是一般保險的分類"},{c:"5.1.1",s:"根據《保險業條例》的分類，以下哪項或哪些保險屬於長期保險的\n業務範圍?",o:["火險","人壽及年金","財產損壞","以上所有各項"],a:1,e:"人壽及年金屬於長期保險的業務範圍"},{c:"5.1.1",s:"按照《保險業條例》的分類方法，以下哪項或哪些屬於長期保險的\n業務範圍",o:["貨運","一般法律責任","永久健康","以上所有各項"],a:2,e:"永久健康屬於長期保險的業務範圍"},{c:"5.1.1",s:"以下哪項是保險法定類別中長期保險業務所包括的保障",o:["疾病","擔保","資本贖回","財產損壞"],a:2,e:"資本贖回屬於長期保險的業務範圍"},{c:"5.1.1",s:"因意外喪失能力或健康欠佳提供利益的長期保單是？",o:["意外","永久健康","意外及疾病","永久喪失能力"],a:1,e:"永久健康是因意外喪失能力或健康欠佳提供利益的\n長期保單，屬一般保險業務"},{c:"5.1.1",s:"根據《保險業條例》以下哪項為一般而非長期業務？",o:["人壽及年金","永久健康","資本贖回","財產損壞"],a:3,e:"財產損壞屬於一般保險的業務範圍"},{c:"5.1.1",s:"根據《保險業條例》的保險類別分類，以下哪項保險屬於一般保險\n而非包括在長期業務的業務範圍內",o:["信貸","相連長期","永久健康","資本贖回"],a:0,e:"信貸承保因債務人不能償還債務而使債權人遭受損\n失，屬一般保險業務"},{c:"5.1.1",s:"根據《保險業條例》的事務分類法則，僱員補償保險",o:["未能成為一項獨立的類別","屬於《一般業務》的分類","屬於《一般法律責任》的類別","以上各項皆符合"],a:2,e:"僱員補償保險屬於一般保險的業務範圍的《一般法\n律責任》的類別"},{c:"5.1.1",s:"保險業條例把保險業務分為兩類",o:["長期業務及短期業務","長期業務及一般業務","財產保險及非財產保險","水險及非水險"],a:1,e:"法定保險業務分類，是為保險業監管機構授權及監\n察而設，《保險業條例》把保險分為長期業務及一\n般業務兩類"},{c:"5.1.1",s:"保險業務種類可分為法定的、實務的及學術的，然而法定的是為著\n什麼而設立",o:["為公司內部組織而設","為專業進修而設","為保險業監管機構授權及監察而設","以上各項皆是"],a:2,e:"法定保險業務分類，是為保險業監管機構授權及監\n察而設，《保險業條例》把保險分為長期業務及一\n般業務兩類"},{c:"5.1.1",s:"根據《保險業條例》的分類，保證合約稱為",o:["疾病","擔保","資本贖回","財產損壞"],a:1,e:"擔保保證合約，包括忠實保證及履約保證，屬一般\n保險業務"},{c:"5.1.1",s:"按照《保險業條例》的分類方法，以下哪項或哪些屬於長期保險的\n業務範圍?",o:["疾病","擔保","婚姻及出生","財產損壞"],a:2,e:"婚姻及出生屬於長期保險的業務範圍"},{c:"5.1.2",s:"根據保險的實務類別，保險分類有四個類別，包括人壽，水險，火\n災及意外，這屬於以下哪項的分類？",o:["法定式","功能式","部門式","業務式"],a:2,e:"保險分類以人壽，水險，火災及意外分類，這屬於\n英國部門式分類的制度"},{c:"5.1.2",s:"根據英國部門式分類的制度，主要分為四大類(意外險、火險、壽險\n及海上保險)。美國制度下，則分為兩大類，包括人壽和非人壽。後\n者亦經常進一步劃分為",o:["財產及非財產","火險及其他","海上保險，火險，保證及意外險","汽車及責任"],a:2,e:"保險分類以人壽，水險，火災及意外分類，這屬於\n英國部門式分類的制度"},{c:"5.1.2",s:"保險業務的其中一種分類是按客戶分類的，以下哪項是正確的",o:["私人和業務","個人和非個人","個人和商業","業務和非業務"],a:2,e:"保險業務的其中一種分類是按客戶分類的可分為個\n人和商業"},{c:"5.1.3",s:"以下哪項或哪些屬於保險的學術分類？",o:["責任保險","一籃子保單","工程保險","以上各項皆是"],a:0,e:"為學術及專業考試的目的，保險往往按照保險標的\n或保險的功能分為人身保險，財產保險，責任保險\n，經濟權益保險"},{c:"5.1.3",s:"以下哪項屬於保險的學術上類別的分類?",o:["火災保險","財產保險","僱傭保險","以上各項皆是"],a:1,e:"財產保險屬於保險的學術上類別的分類"},{c:"5.1.3",s:"以下哪項或哪些是保險業中的學術分類?",o:["工程保險","經濟權益保險","一籃子保險","以上各項都是"],a:1,e:"保險的學術類別可分為人身，財產，責任及經濟權\n益保險"},{c:"5.1.3",s:"為學術及專業考試的目的，保險往往按照保險標的或保險的功能分\n為",o:["人身保險","財產保險","經濟權益保險","以上各項皆是"],a:3,e:"學術及專業考試目的，保險往往按照保險標的或保\n險的功能分為人身保險，財產保險\n，責任保險及經濟權益保險"},{c:"5.1.4",s:"專業再保險人",o:["已取得專業評審資格","對大而危險的風險具備經驗","只經營單一類別的保險業務","只提供再保險"],a:3,e:"只提供再保險人稱為專業再保險人"},{c:"5.1.4",s:"對於特定的保險公司，「分出再保險」與「分入再保險」的分别是",o:["分入再保險只涉及香港的再保險人","分出再保險只涉及非香港的再保險人","分入再保險以該公司作為再保險人","分出再保險以該公司作為再保險人"],a:2,e:"對於特定的保險公司，「分出再保險」與「分入再\n保險」的分别是分入再保險以該公司作為再保險人\n，分出再保險是保險人向其他保險人／再保險人購\n買保險"},{c:"5.1.4",s:"對於特定的保險公司，「分出再保險」與「分入再保險」",o:["它們含有相同的意思","分出再保險以該公司作為再保險人","分入再保險為購買再保險的公司","以上所有各項皆不是"],a:3,e:"對於特定的保險公司，「分出再保險」與「分入再\n保險」的分别是分入再保險以該公司作為再保險人\n，分出再保險是保險人向其他保險人／再保險人購\n買保險，以上所有各項皆不正確"},{c:"5.1.4",s:"只經營再保險業務的保險人稱為？",o:["保險公司","保險代理商","專業再保險人","專屬自保保險人"],a:2,e:"只經營再保險業務的保險人稱為專業再保險人"},{c:"5.1.4",s:"以下哪一項是有關再保險的正確描述?",o:["當保險人發現某保單保額不足的時，以再保險方式購買多一份保\n險以彌補賠償損失","保險人以再保險降低賠償時的變現風險，尤其於重大事故發生巨\n額賠償時，保險人可能即時需要大量現金","再保險只適用於核事故或天災的大型風險","再保險是保險人增加資本的方法"],a:1,e:"購買再保險的最主要原因是為求穩健。個別索償或\n保險金要求相當可能是利用保險人的資產支付的，\n不過要在短時間內預備大量現金，可能引起不便"},{c:"5.1.4",s:"保險人承保一些已被其他保險人／再保險人承保的風險，此稱為",o:["分入再保險","分出再保險","分擔","代位"],a:0,e:"保險人承保一些已被再保險人承保的風險，此稱為\n分入再保險"},{c:"5.1.4",s:"再保險的目是",o:["拒絕承保","增加保費","提高承保能力","公共關係"],a:2,e:"再保險的目是提高承保能力"},{c:"5.11",s:"根據《保險業條例》，以下哪項屬於一般業務類別涵蓋營業中斷?",o:["一般法律責任","雜項財務損失","財產損壞","信貸"],a:1,e:"根據《保險業條例》，雜項財務損失屬於一般業務\n類別涵蓋營業中斷"},{c:"5.2",s:"以下哪項就獲授權的保險人的描述是不正確的?",o:["獲授權保險人可以是從事「 純 」 長期業務","獲授權保險人可以是從事「 純 」 一般業務","獲授權保險人不可以是專業再保險人","獲授權保險人可以是綜合業務保險人"],a:2,e:"獲授權保險人可以是專業再保險人，所以答案C不正\n確"},{c:"5.2.1",s:"在香港獲授權的保險人，劃分為純一般業務保險人、純長期業務保\n險人及",o:["綜合業務保險人","雙重業務保險人","兩險種保險人","多險種保險人"],a:0,e:"在香港獲授權的保險人，劃分為純一般業務保險人\n、純長期業務保險人及綜合業務保險人"},{c:"5.2.1",s:"「綜合」一詞，指從事什麼業務性質？",o:["多於一種類型業務","長期及一般業務","是強制性業務，而非選擇性業務","多於一種核保的業務"],a:1,e:"「綜合」一詞，指同時經營長期及一般業務業務"},{c:"5.4(a)",s:"除非取得特定豁免，進行任何受規受規管活動必須獲得保險業監管\n局授予________",o:["證書","許可證","一個帳戶","會員資格"],a:1,e:"從2019年9月23日起，其所有保險中介人都必須獲得\n保險業監管局的直接許可。"},{c:"5.5",s:"過去曾經營辦保險代理登記委員會的自我規管團體是",o:["香港保險業聯會","香港保險業監管局","香港保險顧問聯會","香港專業保險經紀協會"],a:0,e:"香港保險業聯會過去曾經營辦保險代理登記委員會\n的自我規管團體"},{c:"5.5",s:"香港保險業聯會的成立，其使命宣言是鼓勵會員達到最高道德標準\n及",o:["專業水平","效率","能力","索償標準"],a:0,e:"香港保險業聯會的成立，其使命宣言是鼓勵會員達\n到最高道德標準及專業水平"},{c:"5.5,3(b)",s:"香港汽車保險局會在甚麼情況下向無辜傷亡的交通意外受害人提供\n補償?",o:["法定保險無效","保費過高","索償金額有爭議","免賠額過高"],a:0,e:"如果與車輛道路意外有關的法定保險並不存在、無\n效或有關保險人正進行清盤時，香港汽車保險局便\n會謀求向無辜傷亡的交通意外受害人提供補償。"},{c:"5.5.1",s:"以下哪項關於香港保險業聯會的陳述是正確的?",o:["它的目標之一是要推廣在香港經營業務的保險人的共同利益","多年來,所有在香港成立為法團或經營業務的保險人都是其會員","它是保險代理登記委員會所成立","它存在的目的就是為香港及世界其他地方推廣保險信息"],a:0,e:"香港保險業聯會它的目標之一是要推廣在香港經營\n業務的保險人的共同利益"},{c:"5.5.1",s:"以下哪項有關保險業聯會的正確描述？",o:["香港保險業聯會的成立的目的是保障及提升保險人及保險代理人\n的利益","香港保險業聯會的成立的目的是保障及提升保險人及再保險人的\n利益","香港保險業聯會是由保險代理登記委員會成立的","香港保險業聯會的成立目的是向香港及世界各地宣傳保險訊息"],a:1,e:"香港保險業聯會的成立的目的是保障及提升保險人\n及再保險人的利益"},{c:"5.5.1",s:"以下哪項關於香港保險業聯會的陳述是正確的?",o:["它是由保險代理登記委員會成立的","它是保險人及保險代理人的認可規管團體","提供素質認證","除了香港保險人，它亦提升及推廣香港再保險人的共同利益"],a:3,e:"香港保險業聯會除了香港保險人，它亦提升及推廣\n香港再保險人的共同利益"},{c:"5.5.1&5.5.3",s:"以下哪項屬於強制性保險?\ni.僱 員補償保險\nii.汽 車保險\niii.家 居保險\niv.意 外保險",o:["i, ii","ii, iii, iv","i,ii,iv","i,ii,iii,iv"],a:0,e:"僱員補償保險及汽車保 屬於強制性保險"},{c:"5.5.1(c)",s:"保監局於2019年從3個自律規管機構接管了",o:["保險監理處的功能","保險人的監管","保險中介人的規管","香港保險監督聯會的功能"],a:2,e:"保監局於2019年從3個自律規管機構接管保險中介人\n的規管"},{c:"5.5.3",s:"香港汽車保險局的工作包括",o:["維護汽車車主","售賣車險","維護公平保費","向無辜死傷的交通意外受害人提供補償"],a:3,e:"香港汽車保險局的工作包括向無辜死傷的交通意外\n受害人提供補償"},{c:"5.5.3",s:"香港汽車保險局的經費是來自",o:["政府資助","私人損獻","汽車保險保費的附加徵費","香港保險業聯會"],a:2,e:"香港汽車保險局的經費是來自汽車保險保費的附加\n徵費"},{c:"6.1.1e",s:"《與有關公司安排再保險的指引》之所以重要，原因是",o:["當再保險人與某保險人有關連的時候，所作出某項再保險安排不\n足時，會如何處理","保險人對其再保險安排作出審慎監控","當再保險人與某保險有關連的時候，保險人對其再保險安排時須\n向保監局提出報告","當再保險人與某保險有關連的時候，保險人對其再保險安排時須\n得到保監局批准"],a:0,e:"《與有關公司安排再保險的指引》之所以重要，原\n因是當再保險人與某保險人有關連的時候，所作出\n某項再保險安排不足時，會如何處理"},{c:"6.1",s:"立法會已制定什麼法例，改革保險業的規管制度?",o:["2015年保險公司（修訂）條例","2015年保險業監管局條例","2015年保險從業員條例","2015年保險業（修訂）條例"],a:0,e:"《保險公司條例》在《2015年修訂條例》的相關條\n文於2017年6月26日生效後，已重新命名為《保險業\n條例》，涵蓋保險人及保險中介人的規管，答案A正\n確"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，保險業監管局成立的政策\n目標是甚麽？",o:["確保保險業的規管架構與時並進，促使保險業的高速增長","確保保險業的規管架構與時並進，促進保險業的穩健發展","建立一個保險中介人的法定發牌制度，補充自律規管制度","以上皆不是"],a:1,e:"保監局有下列任務(i)透過發牌制度，規管保險中介\n人的操守(ii)提高保單持有人和潛在保單持有人對\n保險產品和保險業的了解(iii)制訂規管保險業的有\n效策略、促進保險業市場的可持續發展，並提升保\n險業界在環球保險業市場的競力(iv)就影響保險業\n的事宜，進行研究；及(v)就保險業採取適當措施，\n以協助財政司司長維持香港金融穩定。 答案B正確"},{c:"6.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["制訂規管保險業的有效策略","對保單持有人提供直接保障","促進保險業市場的高速發展","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從\n業員"],a:0,e:"制訂規管保險業的有效策略，屬於保險業監管局根\n據保險業條例承擔的職能或任務"},{c:"6.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["對保單持有人和潛在保單持有人提供直接保障","促進保險業市場的高速增長","提高保單持有人和潛在保單持有人對保險產品和保險業的了解","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從\n業員"],a:2,e:"保監局有下列任務(i)透過發牌制度，規管保險中介\n人的操守(ii)提高保單持有人和潛在保單持有人對\n保險產品和保險業的了解(iii)制訂規管保險業的有\n效策略、促進保險業市場的可持續發展，並提升保\n險業界在環球保險業市場的競力(iv)就影響保險業\n的事宜，進行研究；及(v)就保險業採取適當措施，\n以協助財政司司長維持香港金融穩定。 答案C正確"},{c:"6.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["對保單持有人和潛在保單持有人提供直接保障","促進保險業市場的高速增長","透過新的發牌制度，規管保險中介人的操守","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從\n業員"],a:2,e:"保監局有下列任務(i)透過發牌制度，規管保險中介\n人的操守(ii)提高保單持有人和潛在保單持有人對\n保險產品和保險業的了解(iii)制訂規管保險業的有\n效策略、促進保險業市場的可持續發展，並提升保\n險業界在環球保險業市場的競力(iv)就影響保險業\n的事宜，進行研究；及(v)就保險業採取適當措施，\n以協助財政司司長維持香港金融穩定。 答案C正確"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不是保險業監管\n局成立的政策目標？\ni.確 保保險業的規管架構與時並進，促使保險業的高速發展\nii.確 保保險業的償付準備金與國際慣例看齊\niii.就 保險業採取適當措施，穩固香港的國際保險中心地位\niv.為 保單持有人提供更佳的保障",o:["i,ii,iii","i,iii","iii,iv","ii,iii,iv"],a:0,e:"保監局有下列任務(i)透過發牌制度，規管保險中介\n人的操守(ii)提高保單持有人和潛在保單持有人對\n保險產品和保險業的了解(iii)制訂規管保險業的有\n效策略、促進保險業市場的可持續發展，並提升保\n險業界在環球保險業市場的競力(iv)就影響保險業\n的事宜，進行研究；及(v)就保險業採取適當措施，\n以協助財政司司長維持香港金融穩定。\n選項i,ii,iii不正確"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項是保險業監管局\n成立的政策目標？\ni.就 影響保險業的事宜，進行研究\nii.提 升保險業界在環球保險業市場的競爭力\niii.協 助特區行政長官維持香港金融穩定\niv.提 高保單持有人對保險產品和保險業的了解",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:1,e:"保險業監管局其中一項成立的政策目標是協助財政\n司司長維持香港金融穩定。"},{c:"6.1",s:"以下哪一項就《保險業條例》的描述是正確的?",o:["《保險業條例》原稱《保險公司規管條例》","《保險業條例》涵蓋對保險人及保險中介人的監察和規管","《保險業條例》於2015年經修訂後由保險業監理處執行","《保險業條例》2017年6生效後，已重新命名為《保險公司條例》"],a:1,e:"《保險業條例》涵蓋對保險人及保險中介人的監察\n和規管，其他選項都不屬《保險業條例》的正確描\n述"},{c:"6.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不是保險業監管\n局成立的政策目標？\ni.為 保單持有人提供經濟援助\nii.確 保保險業的規管架構與時並進，促使保險業的高速發展\niii.確 保保險業的償付準備金與國際慣例看齊\niv.與 國際慣常做法看齊，監管機構在財政上和運作上獨立於政府",o:["i, iv","i, ii, iii","i, ii","ii, iii, iv"],a:1,e:"由此描述iv是屬於保險業監管局成立的政策目標，\n選項i,ii,iii則不是保險業監管局成立的政策目標\n，詳細參閱研習資料手冊6.1.1"},{c:"6.1.1",s:"保險業條例由以下哪個機構負責執行?",o:["保險業監管局","香港保險業聯會","證券及期貨事務監督委員會","保險行業本身自律監督"],a:0,e:"保險業條例由保險業監管局負責執行"},{c:"6.1.1",s:"以下哪項關於保險業條例的描述是正確的?",o:["保險業條例原稱保險投訴條例","於2015年獲保監局通過","2017年5月改稱為保險公司條例","涵蓋保險人及保險中介人的規管"],a:3,e:"《保險公司條例》在《2015年修訂條例》的相關條\n文於2017年6月26日生效後，已重新命名為《保險業\n條例》，涵蓋保險人及保險中介人的規管，答案D正\n確"},{c:"6.1.1",s:"根據《2015年保險公司（修訂）條例》，下列哪項不屬保險業監管\n局成立的政策目標？\ni.為 保單持有人提供更佳的保障\nii.建 立一個直接規管保險中介人的制度，以補充舊有的自律規管制\n度\niii.確 保保險業的規管架構與時並進，促使保險業的高速發展\niv.就 保險業採取適當措施，鞏固香港的國際保險中心地位",o:["i,ii","i,ii,iii","ii,iii,iv","iii,iv"],a:2,e:"只有選項(i)為保單持有人提供更佳的保障屬保險業\n監管局成立的政策目標，其他都不是，詳細請參閱\n研集資料手冊6.1.1"},{c:"6.1.1",s:"下列那項屬於保險業監管局根據保險業條例承擔的職能或任務？",o:["制訂規管保險業的有效策略","透過新的發牌制度，規管保險保險公司運作","對保單持有人和潛在保單持有人提供直接保障","擴大先前所制定的監管制度從而覆蓋所有每天聯繫客戶的保險從\n業員"],a:0,e:"只有制訂規管保險業的有效策略屬於保險業監管局\n根據保險業條例承擔的職能或任務"},{c:"6.1.1(d)",s:"《 獲授權保險人的公司管治指引 》的目的是",o:["須備有足夠的再保險安排","誠實的保險計算","保障投保大眾的利益","有效的公司治理"],a:3,e:"《獲授權保險人的公司管治指引》的目的是，訂明\n期望獲授權保險人在公司管治這方面所能達到的最\n低標準，有效的公司治理"},{c:"6.1.1a",s:"根據《保險業條例》就獲得授權的最低要求，當中包括：\ni.董 事及控權人\nii.實 繳股本\niii.利 潤率\niv.足 夠的投資保險安排",o:["i, ii","i, iii","i,iii,iv","ii,iii,iv"],a:0,e:"i利潤率及足夠的投資保險安排不屬《保險業條例》\n保險人獲授權的最低要求"},{c:"6.1.1a",s:"在香港或從香港經營保險業務以前，任何「人」必先_____________\n___",o:["具備2000萬港元的實收資本","應對有關的保險中介人資格考試","獲得保險業監管局的授權","成為保險業聯會的會員"],a:2,e:"在香港或從香港經營保險業務以前，任何「人」必\n先獲得保險業監管局的授權"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項有關最低實繳股本的要求是正確的\n?\ni)專屬自保保險公司為港幣200萬元\nii)只從事相連長期保險業務的保險人為港幣1,000萬元\niii)同時從事一般業務及長期業務為港幣2,000萬元\niv)從事一般業務的保險人﹝包括法定保險業務﹞為港幣2,000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"四個最低實繳股本的要求描述都正確，詳細請參閱\n研習資料手冊 6.1.1b"},{c:"6.1.1b",s:"根據《保險業條例》，保險人若要獲得授權，必須符合哪項實繳股\n本要求？",o:["經營任何法定（或強制）保險業務，不論有否經營其他保險業務\n，最低要求為HK$5,000,000","經營任何法定（或強制）保險業務，不論有否經營其他保險業務\n，最低要求為HK$10,000,000","只經營一般業務或只經營長期業務，而非任何法定（或強制）保\n險業務，最低要求為HK$10,000,000","同時經營一般及長期業務，最低要求為HK$10,000,000"],a:2,e:"只經營一般業務或只經營長期業務，而非任何法定\n（或強制）保險業務，最低要求為一千萬港元，只\n有答案C正確"},{c:"6.1.1b",s:"專屬自保保險人的實繳股本最低要求為",o:["200萬港元","500萬港元","800萬港元","1000萬港元"],a:0,e:"專屬自保保險人的實繳股本最低要求為200萬港元"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是正確的？",o:["實繳股本是保險人獲得授權其中一項最低要求","實繳股本的管控人必須符合適當人選要求","同時經營一般及長期業務實繳股本要求最高為2000萬港元","實繳股本可按保費收入計算"],a:0,e:"不同的規定實繳股本數額是保險人獲得授權其中一\n項最低要求"},{c:"6.1.1b",s:"有關保險人的獲授權要求，以下哪一項描述是正確的?",o:["《承保商專業守則》規定了保險人獲得授權的最低要求","同時經營一般及長期業務的實繳股本最高為2000萬港元","足夠再保險是保險人獲的授權的最低要求","《承保商專業守則》規定了“適當人選 ”的相關要求"],a:2,e:"《保險業條例》就有關的事宜，定明獲得授權的最\n低要求，當中包括：實繳股本；償付準備金；董事\n及控權人及足夠的再保險安排。"},{c:"6.1.1b",s:"根據《保險業條例》，實繳股本的最低要求為200萬港元適用於？",o:["綜合保險業務","專屬自保保險人","只經營一般業務","只經營長期業務"],a:1,e:"根據《保險業條例》，實繳股本的最低要求為200萬\n港元適用於專屬自保保險人"},{c:"6.1.1b",s:"根據《保險業條例》，以下哪項就實繳股本要求是不正確的？",o:["專屬自保保險人為3000萬港元","法定或強制性的一般保險業務一般業務為1000萬港元","同時經營一般及長期業務為2000萬港元","只經營長期業務為1000萬港元"],a:0,e:"專屬自保保險人為200萬港元"},{c:"6.1.1c",s:"經營長期業務的保險人，最低的償付準備金為",o:["二百萬港元","一千萬港元","根據保費收益的數額而訂","根據保費收益及準賠償數額兩者而訂"],a:0,e:"經營長期業務的保險人，最低的償付準備金為二百\n萬港元"},{c:"6.1.1c",s:"保險公司必須持有至少相當於「有關數額」的最低償付準備金額。\n就一般保險業務，當中的計算準則是根據「未決申索」數額，及以\n下哪一項數額計算，以較大者為準?",o:["已付索償","保費收入","未賺保費","已賺保費"],a:1,e:"一般業務的償付準備金根據「保費收入」及「未決\n申索」準則計算，並以數額較大者為準。並且不能\n少於一千萬港元（如經營法定保險業務則不能少於\n二千萬港元）。答案B正確"},{c:"6.1.1c",s:"以下哪幾項有關保險公司的償付準備金規定的描述是正確的?\ni.償 付準備金至少相當於 「有關數額」\nii.經 特別申請及批准後，可以降低償付準備金額\niii.一 般業務及長期業務保險人有不同的計算準則\niv.專 屬自保保險人有另一套適用的計算準則",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"償付準備金規定是保險公司獲授權的最低要求，選\n項ii不正確，正確答案是C"},{c:"6.1.1c",s:"以下哪幾項有關保險公司的償付準備金規定的描述是正確的?\ni.償 付準備金至少相當於 「有關數額」\nii.一 般業務及長期業務保險人有相同的最低償付準備金額要求\niii.一 般業務及長期業務保險人有不同的計算準則\niv.專 屬自保保險人有另一套適用的計算準則",o:["i,ii,iii","i, iii,iv","ii,iii,iv","i,iii"],a:1,e:"從究一般業務不能少於一千萬港元，如經營法定保\n險業務則不能少於二千萬港元，長期業務保險人最\n低償付準備金額總額不能少於二百萬港元，選項ii\n不正確"},{c:"6.1.1d",s:"根據《保險業條例》的條文，須事先取得保險業監管局認可才可委\n任的是︰",o:["公司精算師","保險人的管控要員","保險公司的任何一位財務總監","保險公司的理賠經理"],a:1,e:"保險人的管控要員須事先取得保險業監管局認可才\n可委任"},{c:"6.1.1d",s:"良好的公司管治，有助促進公司的業務和加強其問責性。保險業監\n管局發出了《獲授權保險人的公司管治指引》旨在",o:["防止獲授權保險人出現行政上的出錯","防止獲授權保險人管理層作出欺詐行為","董事局應該優先考慮投保人利益","獲授權保險人建立高水平的公司管治，加強投保人香港保險業的\n信心"],a:3,e:"《獲授權保險人的公司管治指引》旨在建立獲授權\n保險人高水平的公司管治，加強投保人香港保險業\n的信心"},{c:"6.1.1d",s:"保險業監管局發出了《獲授權保險人的公司管治指引》旨在",o:["加強投保人的信心和促進香港保險市場的穩健和長遠發展","防止獲授權保險人的高級管理人員作出欺詐行為","防止獲授權保險人的高級管理人員作出欺詐行為，及行政出錯","確保獲授權保險人的董事局優先考慮保單持有人的利益"],a:0,e:"保險業監管局發出了《獲授權保險人的公司管治指\n引》旨在加強投保人的信心和促進香港保險市場的\n穩健和長遠發展"},{c:"6.1.1d",s:"以下哪一項是《獲授權保險人的公司管治指引》的內容涵蓋獲範圍?",o:["除保險公司的管理層外，還涵蓋兩項職能包括（風險管理及承保\n)","只涵蓋風險管理及承保兩項職能","涵蓋所有職能包括（風險管理及核保 )","除保險公司的管理層外，還涵蓋兩項職能包括(風險管理、承保、\n理賠)"],a:3,e:"《獲授權保險人的公司管治指引》的內容涵蓋獲授\n權保險人在管理和功能方面的各個層面（風險管理\n、承保、理賠、顧客服務、審計等）。"},{c:"6.1.1d",s:"根據保險業條例的條文，需事前取得保險業監管局認可才可委任",o:["獲授權⾧期業務保險人的精算師","任何保險中介人","精算部門的職員","理賠部門的職員"],a:0,e:"獲授權⾧期業務保險人的精算師需事前取得保險業\n監管局認可才可委任"},{c:"6.1.1d",s:"根據保監局之要求，獲授權之保險人的管控要員須符合其擔任職位\n之適當人選的要求，就判斷該人是否適當人選，有多項考慮因素，\n包括",o:["該人是否有能力理解最高誠信之原則","該人是否有能力公正行事","該人經營的任何其他業務（保險業務除外）的狀況","任何當局針對該人的任何訴訟"],a:1,e:"該人是否有能力公正行事屬於判斷該人是否適當人\n選，有多項考慮因素，"},{c:"6.1.1e",s:"對保險人的財政穩健，再保險安排起着極為重要作用，有關再保險\n安排的數量及素質，會影響保險人的",o:["有用價值","真實價值","收回應收賬款的能力","實際價值"],a:2,e:"有關再保險安排的數量及素質，會影響保險人的收\n回應收賬款的能力"},{c:"6.1.1e",s:"《保險業條例》對獲授權保險人有關再保險安排的規管有何要求?",o:["規定了最低和最高標準","只適用於一般業務而已","刻意訂得較有彈性（只描述為「足夠的」）","根據上一年度保費收入而變化"],a:2,e:"《保險業條例》規定，獲授權保險人須備有足夠的\n再保險安排。在監察保險人的整體財務狀況時，已\n安排的再保險的數量及素質（影響其「收回應收賬\n款的能力」)會是重要的考慮因素。"},{c:"6.1.1e",s:"《與有關公司安排再保險的指引》很重要，因為",o:["該指引令核數師很頭痛","高級管理人員會疏於管理","當再保險人與某保險人有關連的時候，姊妹公司 會私相授授","當再保險人與某保險人有關連的時候，相關公司會對其再保險安\n排應行的審慎監控可能會流於鬆懈"],a:3,e:"《與有關公司安排再保險的指引》原因是：當再保\n險人與某保險人有關連的時候，保險人對其再保險\n安排應行使的審慎監控可能會流於鬆懈；如果容許\n鬆懈地監管這情況，會對投保公眾帶來風險。"},{c:"6.1.1f",s:"保險業條例要求所有保險人根據其要求呈交準備好的財務報表，呈\n交的頻率是",o:["每月","每年","每季度","每三年"],a:1,e:"根據《保險業條例》的要求，每年向保監局\n呈交其財務報表"},{c:"6.1.1f",s:"《保險業條例》要求參與一般業務的保險人定期繳交甚麼報表?\ni) 經審計的一般業務報表\nii) 經審計的資產負債表\niii) 經審計的精算報告表\niv) 經審計的長期業務報表",o:["i，ii","i，iii","ii，iii，iv","i，ii，iii"],a:0,e:"《保險業條例》要求參與一般業務的保險人定期繳\n交經審計的一般業務報表及經審計的資產負債表"},{c:"6.1.1f",s:"在某種情況下，保險業監管局可以披露某些財務和統計資料，但不\n能披露任何有關個別保險人的事務的資料，除非",o:["涉嫌詐騙","指明的法律程序","於投保人去世後","當保單持有人宣佈破產"],a:1,e:"保險業監管局可以披露某些財務和統計資料，但不\n能披露任何有關個別保險人的事務的資料，除非指\n明的法律程序下"},{c:"6.1.1f",s:"《保險業條例》准許保險業監管局在認為符合保單持有人或公眾利\n益的情況下，披露個別保險人和勞合社的財務和統計資料被稱為",o:["透明度","反洗錢過程","公開度","干預權力"],a:0,e:"《保險業條例》准許保險業監管局在認為符合保單\n持有人或公眾利益的情況下，披露個別保險人和勞\n合社的財務和統計資料被稱為透明度"},{c:"6.1.1f",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（修\n訂）條例》所授予，對獲授權保險人施予的紀律處分？\ni. 將保險人清盤\nii. 限制投資\niii. 非公開譴責\niv. 罰款",o:["i, ii","i, ii, iii","iii，iv","ii，iii，iv"],a:2,e:"非公開譴責及罰款屬於《2015年保險公司（修訂）\n條例》所授予保險業監管局新增的監管權力，答案C\n正確"},{c:"6.1.1f",s:"《保險業條例》列明經營一般業務的保險人必須就其從香港保險業\n務所產生的負債在香港維持資產，用來釐定這一數據的方法之一，\n是計算有關數額與以下之總和",o:["毛負債額（不扣除再保險部分）的80%","净負債額（扣除不保部分）的80%","净負債額（扣除再保險部分及可爭議負債）的80%","净負債額（扣除再保險部分）的80%"],a:3,e:"經營一般業務的保險人，必須就其從香港保險業務\n所產生的負債在香港維持資產，所需數額以訂明的\n兩種匯算方法之一計算，其一所要求的數額不能少\n於兩項的總和:(i)淨負債額（即已經扣除再保險所\n保的那部分）的百分之八十 ；及(ii) 有關數額。"},{c:"6.1.1f",s:"根據《保險業條例》的要求，所有保險人必須每年向保險業監管局\n呈交？",o:["財務報表","資產負債表","損益表","以上皆不是"],a:0,e:"根據《保險業條例》的要求，所有保險人必須每年\n向保險業監管局呈交財務報表"},{c:"6.1.1f",s:"經營一般業務的保險人，須每年就香港有關的業務向保險業監管局\n呈交?",o:["經營香港及海外業務的保險人：須呈交一份經審計的一般業務報\n表，及一份經審計的資產產負債表","經營香港業務的保險人：須呈交一份經審計的一般業務報表，及\n一份經審計的資產產負債表，除非經營該業務少於兩年","經營香港業務的保險人：須呈交一份經審計的一般業務報表，及\n一份經審計的損益表","經營香港業務的保險人：須呈交一份經審計的一般業務報表，及\n一份經審計的資產產負債表"],a:3,e:"經營一般業務的保險人，須每年就香港有關的業務\n向保險業監管局呈交須呈交一份經審計的一般業務\n報表，及一份經審計的資產產負債表"},{c:"6.1.1f",s:"保險業監管局發出的《有關僱員補償及汽車保險業務保險負債的精\n算檢討指引》 要求",o:["要求經營僱員補償及／或汽車保險業務的保險人，須每年就法定\n業務類別而為未來索償作撥備的儲備金進行精算檢討","要求經營僱員補償及／或汽車保險業務的保險人(包括再保險人）\n，須每年就法定業務類別而為未來索償作撥備的儲備金進行精算檢\n討","須每六個月一次就其業務的財政狀況進行精算調查","須每十二個月一次就其業務的財政狀況進行精算調查"],a:1,e:"保險業監管局發出的《有關僱員補償及汽車保險業\n務保險負債的精算檢討指引》要求經營僱員補償及\n／或汽車保險業務的保險人(包括再保險人），須每\n年就法定業務類別而為未來索償作撥備的儲備金進\n行精算檢討"},{c:"6.1.1f",s:"根據《保險業條例》，以下哪一項是關於條例的其他重要條文？",o:["呈報規定","維持在香港的資產","資產及負債的估值基準","以上各項皆是"],a:3,e:"以上各項皆是《保險業條例》的其他重要條文"},{c:"6.1.1f",s:"於香港的一般業務保險人必須就其從香港保險業務所產生的負債在\n香港維持資產，以下哪項就所需數額計算的描述是正確的?\ni.計 算保險人的淨負債額（即已經扣除再保險所保的那部分）\nii.必 須根據香港精算學會3種訂明匯算方法的其中一種方法計算\niii.計 算保險人的淨負債額（即已經扣除不保損失的部分）的80%\n及有關數額加起來\niv.所 需數額以訂明的兩種匯算方法之一計算",o:["i, ii,iii","ii,iv","ii,iii,iv","i,iv"],a:3,e:"經營一般業務的保險人，必須就其從香港保險業務\n所產生的負債在香港維持資產，所需數額以訂明的\n兩種匯算方法之一計算，其一所要求的數額不能少\n於兩項的總和，(i)淨負債額（即已經扣除再保險所\n保的那部分）的百分之八十；及(ii)有關數額有關\n數額。只有選項i， iv正確"},{c:"6.1.1f",s:"為更有效規管保險人名保單持有人的利益，以下哪項是《2015年修\n訂條例》下保監局獲賦予新增的規管權力?",o:["進行查察、展開調查及向獲授權保險人施加罰款的權力","命令一個保險集團的每個成員委任獨立審計師的權力","命令保險人以審計署作為審計師的權力","進行查察及對未應健全承保政策的保險人展開調查及向獲授權保\n險人施罰款的權力"],a:0,e:"進行查察、展開調查及向獲授權保險人施加罰款的\n權力是《2015年修訂條例》下保監局獲賦予新增的\n規管權力"},{c:"6.1.1f",s:"於香港的一般業務保險人必須就其從香港保險業務所產生的負債在\n香港維持資產，以下哪項就所需數額計算的描述是正確的?\ni.計 算與淨負債額的80%有關\nii.與 淨負債額 （即已經扣除再保險所保的那部分）成正比\niii.必 須根據香港精算學會訂明匯算方法的其中一種方法計算\niv.計算保險人的淨負債額 （不扣除具爭議的債務）的80%\n及有關數額加起來",o:["i,ii","i,ii,iv","ii,iii","ii,iii,iv"],a:0,e:"只有選項i,ii才是一般業務保險人所需數額計算的\n正確描述"},{c:"6.1.1f(d)",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（修\n訂）條例》所授予，對獲授權保險新增的規管權力？",o:["罰款","限制保費收入","對新業務的限制","特定的精算調查"],a:0,e:"《2015年修訂條例》下新增的規管權力：保監局可\n以施加的紀律處分包括：撤銷暫時撤銷給予保險人\n的授權、禁止申請經營某類別保險業務的授權、公\n開或非公開的譴責、罰款等。"},{c:"6.1.1f(d)",s:"根據《保險業條例》的要求，所有保險人每年向保監局呈交",o:["資產負債表","一般業務報表","財務報表","以上各項皆是"],a:2,e:"根據《保險業條例》的要求，所有保險人每年須向\n保監局呈交其財務報表"},{c:"6.1.1f(e)",s:"在某些情況下，保險業監管局現在可以披露某些財務和統計資料，\n然而，不得披露個別保單持有人的這種資料，除非",o:["在涉及欺詐時","在明確的法律程序下","在有關保單持有人死亡之後","在保單持有人被宣佈破產時"],a:1,e:"在某些情況下，保險業監管局現在可以披露某些財\n務和統計資料，然而，不得披露個別保單持有人的\n這種資料，除非在明確的法律程序下"},{c:"6.1.1f(f)",s:"以下哪些新增的監管權力是保險業監管局就《2015年保險公司（修\n訂）條例》所授予，對獲授權保險人施予的紀律處分？\ni. 公開譴責\nii. 對新業務的限制\niii. 罰款\niv. 限制保費收入",o:["i, ii","i, ii, iii","i，iii","ii，iii，iv"],a:2,e:"《2015年修訂條例》下新增的規管權力：保監局可\n以施加的紀律處分包括：撤銷暫時撤銷給予保險人\n的授權、禁止申請經營某類別保險業務的授權、公\n開或非公開的譴責、罰款等。"},{c:"6.1.1f(iii)",s:"償付準備金的計算方法為",o:["保險人的流動資產除以流動負債","保險人的流動資產減去流動負債","保險人的資產減去負債","以上都不是"],a:2,e:"償付準備金的計算方法為保險人的資產減去負債"},{c:"6.1.1g",s:"根據《保險業條例》及相關法例，以下哪項或哪些屬於保險業監管\n局的干預權力",o:["嚴重情況下將保險人清盤","指令保單持有人退回過多的保費","指令提高法定保險保費","以上各項皆是"],a:0,e:"嚴重情況下將保險人清盤屬於保險業監管局的干預\n權力，只有答案A正確"},{c:"6.1.1g",s:"根據《保險業條例》及相關法例，以下哪項屬於保險業監管局的干\n預範圍：\ni) 限制保費收入\nii) 將保險人清盤\niii) 特定的精算調查\niv) 行使對保險人的管理權",o:["只有 i, ii","只有 ii, iii","只有 i, ii, iii","i, ii, iii, iv"],a:3,e:"以上各項都屬保險業監管局的干預權力，詳細請參\n閱研習資料手冊 6.1.1g"},{c:"6.1.1g",s:"《保險業條例》中所指的干預權力指",o:["投資限制：對投資種類及地點作出限制","特定的精算調查：當對保險人應付債務的能力值得關注時，便需\n要去進行此項調查","將保險人清盤：在極嚴重的情況時適用","以上各項皆是"],a:3,e:"以上各項皆是《保險業條例》中所指的干預權力"},{c:"6.1.1g",s:"以下哪一項是《2015年修訂條例》賦予保監局的干預權力?\ni.限 制海外股本\nii.總 投資佔股本最高比率必須由保監局指明\niii.限 制保費收入\niv.將 保險人清盤",o:["i , ii , iii","i, ii, iv","iii, iv","ii, iii, iv"],a:2,e:"選項i,ii則不是《2015年修訂條例》賦予保監局的\n干預權力，詳細參閱研習資料手冊6.1.1g"},{c:"6.1.1g",s:"以下哪些《2015年保險公司（修訂）條例》就保險業監管局新增的\n年修訂條例》下新增的規管權力？",o:["對新業務的限制","撤銷保險人的授權","限制保費收入","以上各項皆是"],a:1,e:"《2015年修訂條例》下新增的規管權力，保監局可\n以施加的紀律處分包括：撤銷暫時撤銷給予保險人\n的授權、禁止申請經營某類別保險業務的授權、公\n開或非公開的譴責、罰款等。"},{c:"6.1.2",s:"由保險業聯會執行的《承保商專業守則 》適用於",o:["保險業聯會會員所發出之保單","保險業聯會會員所發出之商業保單","以香港居民個人作保單持有人的保單","以非香港居民個人作保單持有人的保單"],a:2,e:"由保險業聯會執行的《承保商專業守則》適用於以\n香港居民個人作保單持有人的保單"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["由香港保險業聯會執行","列明保險中介人八大操守原則","保險人的資本規定","以上皆是"],a:0,e:"承保商專業守則由香港保險業聯會執行，列明保險\n代理管理的優良保險做法"},{c:"6.1.2",s:"有關承保商專業守則，誰有責任令保險代理人遵守其法律?",o:["保險監管局","保險業聯會","保險監管機構","委任代理人的保險人"],a:3,e:"有關承保商專業守則，委任代理人的保險人有責任\n令保險代理人遵守其法律"},{c:"6.1.2",s:"以下哪項是承保商專業守則的描述是正確的?",o:["列明保險中介人八大操守原則","由香港保險監管局執行","列明保險代理管理的優良保險做法","以上各項皆是"],a:2,e:"承保商專業守則由香港保險業聯會執行，列明保險\n代理管理的優良保險做法"},{c:"6.1.2",s:"以下哪項是《承保商專業守則》的描述是正確的?",o:["前稱《保險業條例》","規定了保險人獲得授權的最低要求","接管保監處規管香港保險業的法定職能","訂立符合標準的優保險做法"],a:3,e:"《承保商專業守則》是由保險業聯會執行，訂立符\n合標準的優保險做法，與保險業條例無關，只有答\n案D正確。"},{c:"6.1.2",s:"以下哪項是《承保商專業守則》提供建議及處理事宜?",o:["保單","銷售資料","投保書","以上各項皆是"],a:3,e:"以上各項皆是《承保商專業守則》提供建議及處理\n事宜"},{c:"6.1.2(d)",s:"以下哪項不是承保商專業守則第四部分關於保險代理人管理需加強\n注意的?",o:["對保險代理人提供的酬勞","建立機制處理對保險代理人的投訴","確保保險代理人在職務上得到足夠的支援","以上各項皆是"],a:0,e:"以上各項皆是承保商專業守則第四部分關於保險代\n理人管理需加強注意的要點"},{c:"6.1.2a",s:"《承保商專業守則》旨在訂立應有水平的優良保險慣例，包括：\ni) 產品分析\nii) 保險合約下的顧客權益及須負的責任\niii) 廣泛的顧客權利及權益\niv) 提高行業的公眾形象以作為優秀企業公民",o:["i, ii, iii","i, ii, iv","ii, iii,iv","以上所有各項"],a:3,e:"以上所有各項都是《承保商專業守則》所訂立的優\n良保險慣例"},{c:"6.1.2a",s:"以下哪項的目的是在訂立與核保、索償、產品分析相關的符合標準\n的優良保險做法?",o:["標準營業員合約","承保商專業守則","保險業條例","保險業監管局發出指引"],a:1,e:"承保商專業守則目的是在訂立與核保、索償、產品\n分析相關的符合標準的優良保險做法"},{c:"6.1.2a",s:"《承保商專業守則》的目的是對核保、索償產品分析等訂立",o:["銷售做法","優良保險做法","投保的優良做法","索償做法"],a:1,e:"《承保商專業守則》的目的是對核保、索償產品分\n析等訂立優良保險做法"},{c:"6.1.2b",s:"以下哪項不屬於《承保商專業守則》對提供建議及銷售詳情的要求?",o:["提供最新的資料","不會誤導公眾","用淺白易明的文字","把所有競爭對手的產品資料詳細列出"],a:3,e:"把所有競爭對手的產品資料詳細列出不屬於《承保\n商專業守則》對提供建議及銷售詳情的要求"},{c:"6.1.2b",s:"根據《承保商專業守則》，以下哪項是使用投保書/申請表的部份意\n見？\ni) 它應以淺白語言表達\nii) 它應小心解釋最高誠信原則要求的重要性\niii) 它應以清晰的問題提問重要事實\niv) 它必須小心解釋任何附帶問卷的重要性",o:["i, ii","iii, iv","ii, iii, iv","i, ii ,iii, iv"],a:3,e:"根據《承保商專業守則》，以上各項都是使用投保\n書/申請表的建議"},{c:"6.1.2b",s:"《承保商專業守則》要求保單合約",o:["應該力求清晰及易於理解","提供合約條款可見的證據","於續保時需要披露重要事實的最高誠信原則要求，都應予以小心\n地解釋","以上各項部都是"],a:3,e:"以上各項部都是《承保商專業守則》中對保單合約\n的建議"},{c:"6.1.2b",s:"保險合約之完整條款的書面憑證，通常最可能在哪裏出現？",o:["投保單","保單","保險憑證","在相關的保險法例上出現"],a:1,e:"保險合約之完整條款的書面憑證，通常最可能在保\n單出現"},{c:"6.1.2b",s:"根據《承保商專業守則》，以下哪一項是關於保單方面的要求描述\n是正確的?",o:["保單應該力求清晰","保單應該易於明白及理解","對於續保時須要披露重要事實的最高誠信原則的要求，應予以詳\n盡的解釋","以上各項皆是"],a:3,e:"以上各項皆是《承保商專業守則》關於保單方面的\n正確陳述"},{c:"6.1.2b",s:"根據《承保商專業守則》，以下哪項是就保單所提出的建議？",o:["重要事實應以清晰的問題作出提問","對於續保時須要披露重要事實的最高誠信原則的要求，應予以詳\n盡的解釋","索償時解釋最高誠信原則要求的重要性","小心解釋任何附帶問卷的重要性"],a:1,e:"只有答案B是根據《承保商專業守則》就保單所提出\n的建議"},{c:"6.1.2c",s:"根據《承保商專業守則》，假如符合兩項條件，即使違反保證亦不\n會在索償時被拒絕，其中是包括以下哪項？",o:["損失不超過2,000元","被保險人承認違反保證","損失與違反保證兩者並無因果關係","以上各項皆不是"],a:2,e:"根據《承保商專業守則》的索償建議，沒有涉及欺\n詐成分違反了保證，而且該違反沒有引致有關損失\n，保險人不應拒絕賠償 或支付保險金"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求\n描述是正確的?",o:["代表保險人的理賠師須具備一定程度的經驗","代表保險人的理賠師須具備一定程度的經驗，以及相關專業資格","不得委派理賠師以外第三者處理索償","代表保險人的理賠師應該具備的專業資格"],a:3,e:"根據《承保商專業守則》代表保險人的第三者（理\n賠師等），在任何情況下都應當合理地行事，並且\n應該具備專業資格。"},{c:"6.1.2c",s:"根據《承保商專業守則》，以下哪一項是關於理賠索償方面的要求\n描述是正確的?",o:["代表保險人的第三者，應該具備相關經驗","代表保險人的第三者，應該相關經驗及具備專業資格","不得委派律師或理賠師以外第三者","代表保險人的第三者，在任何情況下都應當合理地行事，並且應\n該具備專業資格"],a:3,e:"根據《承保商專業守則》代表保險人的第三者（理\n賠師等），在任何情況下都應當合理地行事，並且\n應該具備專業資格。"},{c:"6.1.2d",s:"有關承保商專業守則，誰有責任令保險人的代理人遵守?",o:["保險監管局","保險公司監管處","保險人的高級行政人員","相關保代理人的委託人的保險人"],a:3,e:"通常情況下，保險人負責確保它的保險代理人遵守\n所有適用的法律，答案D正確"},{c:"6.1.3",s:"保險投訴局成員包括",o:["本港所有獲授權的保險人","本港獲授權一般業務的保險人而已","本港獲授權長期業務的保險人而已","本港所有承保個人壽險的獲授權保險人"],a:3,e:"所有在香港從事個人保險業務的獲授權保險人均必\n須繼續申請成為保險投訴局的會員"},{c:"6.1.3",s:"以下哪項是保險投訴局的描述是正確的?\ni)會員是在香港從事個人保險業務的獲授權保險人\nii)涉及的投訴個案保單須屬個人保單\niii)保險投訴委員會兩名委員必須來會計，法律或精算等業界\niv)保險投訴委員會兩名委員來自保險業界",o:["i,ii,iii","i,ii,iv","iii, iv","i. ii, iii, iv"],a:1,e:"投訴委員會的其餘四位委員中，兩位是來自保險業\n的，其餘兩位則為業外人士。只有選項i,ii,iv正確"},{c:"6.1.3",s:"以下哪項是保險投訴局的描述是正確的?\ni)會員是在香港從事個人保險業務的獲授權保險人\nii)投訴委員會是由一位主席、四位委員組成\niii)涉及的投訴個案保單須屬個人保單\niv)保險投訴局會代為處理理賠及索償",o:["i,ii,iii","i,ii,iv","iii, iv","i. ii, iii, iv"],a:0,e:"處理理賠及索償不屬保險投訴局職務範圍，選項iv\n不正確"},{c:"6.1.3",s:"以下哪項是保險投訴局的描述是正確的?\ni)保險投訴局成立目的是代表會員處理及支付索償\nii)會員是在香港從事個人保險業務的獲授權保險人\niii)涉及的投訴個案保單須屬個人保單\niv)投訴委員會的委員中有兩位來自保險業",o:["i,ii,iii","ii,iii,iv","iii, iv","i. ii, iii, iv"],a:1,e:"處理及支付索償不是保險投訴局的成立目的及職權\n範圍，選項(i)不正確"},{c:"6.1.3",s:"以下哪項是保險投訴局的描述是正確的?",o:["2018年成立取代保險索償投訴局","處理保單屬非金錢性質的投訴個案","只能處理保單屬非索償相關的投訴個案","所有在香港從事個人保險業務的獲授權保險人可自願申請成為保\n險投訴局的會員"],a:0,e:"所有在香港從事個人保險業務的獲授權保險人均必\n須成為保險投訴局的會員，並會受理索償相關及非\n索償相關的金錢性質保險糾紛投訴個案，保險投訴\n局於2018年1月16日成立，旨在取代保險索償投訴局\n，正確答案是A"},{c:"6.1.3",s:"以下哪項是保險投訴局(ICB)的描述是正確的?",o:["於2018年被保險索償投訴局取代","可以解決非金錢性質的保險糾紛","不能處理保單屬非索償相關的投訴個案","以上各項皆不是"],a:3,e:"保險投訴局就索償相關及非索償相關的金錢性質保\n險糾紛投訴個案都會受理，保險投訴局於2018年1月\n16日成立，旨在取代保險索償投訴局，以上各項皆\n不是正確答案"},{c:"6.1.3",s:"以下哪項是保險投訴局服務的必要條件?\ni.相關中介人必須是保險投訴局會員\nii.投訴個案不可以與索償無關\niii.投訴人必須為被保險人或保單持有人\niv.保單為商業保險保單",o:["iii","i,ii,iii","ii,iv","以上各項皆是"],a:0,e:"所有在香港從事個人保險業務的獲授權保險人均必\n須成為保險投訴局的會員，涉及商業或第三者保險\n索償投訴個案不屬保險投訴局(ICB)，並會受理索償\n相關及非索償相關的金錢性質保險糾紛投訴個案，\n只有選項iii正確，正確答案是A"},{c:"6.1.3",s:"以下哪項是保險投訴局(ICB)的描述是正確的?\ni)在 香港所有從事個人保險業務的獲授權保險人均為保險投訴局的\n會員\nii)涉 及的投訴個案保單須屬個人保單\niii)投 訴委員會的委員中有兩位是來自保險業界\niv)投 訴個案可涉及商業或第三者保險索償",o:["i,ii","i,ii,iii","ii,iv","iii,iv"],a:1,e:"涉及商業或第三者保險索償投訴個案不屬保險投訴\n局處理範圍"},{c:"6.1.3",s:"以下哪項是保險投訴局(ICB)的描述是正確的?\ni)涉 及的投訴個案保單須屬個人保單\nii)投 訴委員會是由一位主席、四位委員組成\niii)投 訴委員會的委員中有兩位是來自保險業界\niv)它 是由所有在香港的獲授權保險人所組成",o:["i,ii,iii","i,iv","ii,iii","ii,iii,iv"],a:0,e:"所有所有在香港從事個人保險業務的獲授權保險人\n均必須申請成為保險投訴局的會員，選項iv不正確"},{c:"6.1.3a",s:"保險索償投訴委員會成員是由以下哪個團體所委派",o:["保險投訴局","保險業聯會","保險監督","壽險業協會"],a:0,e:"保險索償投訴委員會成員是由保險投訴局所委派"},{c:"6.1.3a",s:"保險索償投訴委員會屬於一個獨立組織，由一名主席及多少名委員\n組成?",o:["兩名委員","三名委員","四名委員","五名委員"],a:2,e:"保險索償投訴委員會屬於一個獨立組織，由一名主\n席及四名委員委員組成"},{c:"6.1.3a",s:"投訴索償委員會由5人組成，當中有幾人來自保險業？",o:["無1人","2人","3人","4人"],a:1,e:"投訴委員會的委員中，只有兩位是來自保險業的，\n其餘兩位則為業外人士。"},{c:"6.1.3a",s:"委派保險索償投訴委員會的是",o:["保險業監管局","政府","保險業聯會","保險投訴局"],a:3,e:"委派保險索償投訴委員會的是保險投訴局"},{c:"6.1.3b",s:"下列哪項較可能是保險投訴局的職權範圍？",o:["保費退還糾紛","一項火災的損失，拒絕的300萬的索償","第三者聲稱他人對他做成的損害","一項意外的損失，保險人拒絕的30萬的索償"],a:3,e:"保險投訴局有權處理的投訴，必須涉及個人保單，\n投訴個案的索償金額／爭議金額不超過100萬港元，\n投訴個案不涉及商業、工業或第三者保險，答案D正\n確"},{c:"6.1.3b",s:"以下哪項最有可能屬於保險投訴局的特權範圍?",o:["涉及續保保費的糾紛","第三者聲稱因被保險人的疏忽而導致他受傷","保險人聲稱因被保險人縱火，拒絕一項300萬港元的火險索償","因違反家居保單中的條件，保險人拒絕一項兩萬港元的索償"],a:3,e:"保險投訴局有權處理的投訴，必須涉及個人保單，\n投訴個案的索償金額／爭議金額不超過100萬港元，\n投訴個案不涉及商業、工業或第三者保險，答案D正\n確"},{c:"6.1.3b",s:"要投訴獲得受理，下列哪項附合保險投訴局的條件",o:["索償金額不超過一百萬港元","涉案的保險人乃保險投訴局的會員","涉案的保單乃個人保單","以上各項皆是"],a:3,e:"以上各項皆是保險投訴局投訴個案受理條件"},{c:"6.1.3b",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["在保險人作出最後決定後9個月的投訴","一宗涉及個人保險價值為HK$300,000 的汽車失竊賠償","保險人以不符合保單條件，拒絕一宗$20,000的家具保險索償","有關「全保」汽車保險中，價值$10,000的擋風玻璃損壞索償"],a:0,e:"在保險人作出最後決定後9個月的投訴，不屬於保險\n投訴局的職務範圍，在保險人作出最後決定後6個月\n的投訴作出的投訴才可受理"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有\n保證價值此事實\nii.保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗 證其真實年齡\niii.客人投訴保險人服務差，從而令客人有損失\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單\n是屬於「抗通脹保單」",o:["i , ii , iv","ii , iii","ii ,iii ,iv","iii ,iv"],a:0,e:"投訴個案與保險人的服務水平或核保決定無關"},{c:"6.1.3b",s:"以下哪幾項是保險投訴局有權處理的個案:\ni.發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有\n保證價值此事實\nii.投保人訴在核保結果為次標準風險\niii保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗證其真實年齡\niv.對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單\n是屬於「抗通脹保單」",o:["i,ii,iii","i,iii,iv","iii,iv","i,ii,iii,iv"],a:1,e:"保險投訴局受理的投訴個案與保險人的服務水平或\n核保決定無關"},{c:"6.1.3b",s:"以下哪項有關索償投訴是屬於保險投訴局的職務範圍？\ni)10萬港元家居保險索償\nii)30萬港元個人保單索償\niii)年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值\n，導致損失了有關的保單利息\niv)投資表現相關的個案",o:["i , ii , iii","ii, iv","i, iii, iv","i ,ii, iii, iv"],a:0,e:"投資表現相關的個案不屬索償投訴是屬於保險投訴\n局的職務範圍選項(iv)不正確"},{c:"6.1.3b",s:"保險索償投訴委員會能處理以下的個案",o:["投訴人於保險人通知最終賠償決定的日期起計九個\n月後提出的投訴","有關無索償折扣的投訴","十萬港元的個人財產保險索償（全險）","正在進行中的仲裁索償"],a:2,e:"投訴個案的爭議金額不超過100萬港元，投訴個案並\n非正在進行法律程序或仲裁，投訴人須於接獲保險\n人發出的最終決定的六個月內，向保險投訴局作出\n書面投訴，投訴個案不涉及商業、工業或第三者保\n險，只有答案C正確"},{c:"6.1.3c",s:"保險投訴局提供與索償無關調解服務，以下哪些描述正確？",o:["服務費用由保險業監管局負責","爭議雙方可從保險投訴局所備存具相關經驗和資格的調解員中，\n選擇調解員進行調解","無論勝訴與否，保險人須負擔80%服務費用","爭議雙方使用保險投訴局的調解服務前，須已通過仲裁程序並未\n能從中成功解決紛爭"],a:1,e:"儘管保險投訴局會鼓勵爭議雙方達成和解，但一旦\n無法達成和解，他們可從保險投訴局所備存具相關\n經驗和資格的調解員名單中，選擇調解員以進行調\n解，受理金額上限為100萬港元投訴人不用付費，答\n案B正確"},{c:"6.1.3c",s:"以下哪項無權享有向保險投訴局提出爭議個案有關的投訴?",o:["提供保費融資的銀行保單持有人","保單共同所有人","保單受益人","合法索償人（如承讓人）"],a:0,e:"有權向保險投訴局的投訴人必須為保單持有人、保\n單受益人、受保人或合法索償人（如承讓人）"},{c:"6.1.3c",s:"保險人與保單持有人發生爭議，儘管保險合約中可能設有仲裁條款\n，保單持有人仍可向保險投訴局尋求調解服務，以下哪一項是該服\n務需要滿足的條件？\ni. 爭議屬索償無關的投訴個案\nii. 爭議賠償金額為80萬港元以下\niii.雙方必要放棄仲裁權利\niv 涉案保險人已對索償或爭議作出了最終決定",o:["i, ii","ii,iii,iv","iii, iv","i, iv"],a:3,e:"投訴個案的索償金額／爭議金額不超過100萬港元，\n投訴個案並非正在進行法律程序或仲裁。只有選項i\n,iv正確"},{c:"6.1.3c",s:"以下哪一項是保險投訴局提供與索償無關的調解服務的先決條件?",o:["儘管鼓勵爭議雙方達成和解，但和解無法達成","服務要求必須6個月內提出","受理金額上限為 95萬港元","儘管鼓勵爭議雙方簽訂協議，但雙方無法簽訂"],a:0,e:"儘管保險投訴局會鼓勵爭議雙方達成和解，但一旦\n無法達成和解，他們可從保險投訴局所備存具相關\n經驗和資格的調解員名單中，選擇調解員以進行調\n解，受理金額上限為 100萬港元投訴人不用付費。"},{c:"6.1.3c",s:"以下哪一項與索償無關的個案肯定不屬保險投訴局的職權範圍?",o:["年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，\n導致損失了有關的保單利息","人壽保險申請人投訴保險公司對吸煙者及非吸煙者按相同的保費\n率收取保費屬不公平做法","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗證其真實年齡","對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單\n是屬於「抗通脹保單」"],a:1,e:"保險投訴局受理的投訴個案與保險人的服務水平或\n核保決定無關"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有\n保證價值此事實","保單持有人投訴保險人花上一個月才批出保單，導致他未能及時\n交給所屬銀行","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗 證其真實年齡","年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，\n導致損失了有關的保單利息"],a:1,e:"保險投訴局受理的投訴個案與保險人的服務水平或\n核保決定無關"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，\n導致損失了有關的保單利息","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗證其真實年齡","投保人不滿投保申請出乎意料被拒絕","對保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單\n是屬於「抗通脹保單」"],a:2,e:"保險投訴局受理的投訴個案與保險人的服務水平或\n核保決定無關"},{c:"6.1.3c",s:"以下哪項與索償無關的個案屬保險投訴局的職權範圍?\ni.一 項涉及100,000港元的保單爭議金額\nii.已 就該糾紛個案進入法律程序\niii.保 險人收取過高保費，猶如比客人實際年齡大了10歲，客人投\n訴於銷售的過程中沒有驗證其真實年齡\niv.對 保險人派發紅利金額的投訴，客人聲稱銷售過程中承諾該保單\n是屬於「抗通脹保單」",o:["i, ii","i,ii,iv","ii,iii","i,iii,iv"],a:3,e:"保險投訴局受理的投訴個案不可以正在進行法律程\n序或仲裁。"},{c:"6.1.3c",s:"以下哪項有關索償投訴是不屬於保險投訴局的職務範圍？",o:["發現沒有保證退保價值，客人投訴保險人於銷售過程中隱瞞沒有\n保證價值此事實","保險人未有及時將續保條款及時通知保單持有人的投訴","保險人收取過高保費，猶如比客人實際年齡大了10歲，客人投訴\n於銷售的過程中沒有驗證其真實年齡","年金購買人投訴該保險人，根據錯誤計算支付較低的退保價值，\n導致損失了有關的保單利息"],a:1,e:"與服務水平有關的投訴個案，不屬於保險投訴局的\n職務範圍"},{c:"6.1.3c",s:"保險人與保單持有人發生爭議，保險合約可能包含仲裁條款，保單\n持有人可向保險投訴局尋求調解服務，保險投訴局解釋以下哪項條\n件先需要滿足？\ni. 投訴個案透過仲裁未能達成協議\nii. 爭議雙方已盡力但仍無法達成和解\niii.未能滿足保險投訴局的裁決條件\niv 涉案保險人已對涉案保險人已對索償爭議作出了最終決定",o:["ii,iv","i,ii,iv","i, iii","ii, iii, iv"],a:0,e:"保險投訴局有權處理的投訴，必須符合若干條件，\n投訴個案並非正在進行法律程序或仲裁。詳細參閱\n研習資料手冊6.1.3b"},{c:"6.11f",s:"於香港的一般業務保險人必須就其從香港保險業務所產生的負債在\n香港維持正資產，以下哪項就所需數額計算的描述是正確的?\ni.淨 負債額 （即已經扣除再保險所保的那部分）的80%\nii.計 算保險人的淨負債額 （即已經扣除不保損失的部分）的80%\n及有關數額加起來\niii.所 需數額以訂明的兩種匯算方法之一計算\niv.計 算保險人的淨負債額 （即已經扣除具爭議的債務）的80%\n及有關數額加起來",o:["i, iii","ii,iv","i,ii,iv","i, iii,iv"],a:0,e:"經營一般業務的保險人，在香港維持資產，所需數\n額以訂明的兩種匯算方法之一計算，其中一項是淨\n負債額即已經扣除再保險所保的那部分）的百分之\n八十，所以描述ii及iv不是答案"},{c:"6.2",s:"《持牌保險代理人操守守則》一般原則4–勝任提供意見，提及持牌\n保險代理人只可進行該代理人所勝任的受規管活動，以及",o:["行事誠實、有道德及持正","應具備適當程度的專業知識和經驗","應一直公平對待客戶，並以其最佳利益行事","應盡其最大努力避免利益衝突"],a:1,e:"《持牌保險代理人操守守則》一般原則4–勝任提供\n意見，提及持牌保險代理人只可進行該代理人所勝\n任的受規管活動，以及應具備適當程度的專業知識\n和經驗"},{c:"6.2",s:"有關《持牌保險代理人操守守則》，以下哪項描述是正確的?\ni.該守則由保監局頒布\nii.該守則列明八項持牌保險代理人應遵守的基本操守原則的一般原\n則\niii.為《保險業條例》提供指引，考慮持牌保險中介人是否屬繼續\n持牌的適當人選\niv.該守則保險業條例的附屬法例及有法律效力",o:["i, ii","i, ii, iii","ii, iv","ii, iii, iv"],a:1,e:"《持牌保險代理人操守守則》不是保險業條例的附\n屬法例，以及沒有法律效力"},{c:"6.2",s:"《持牌保險代理人操守守則》一般原則4–勝任提供意見，持牌保險\n代理人應",o:["向客戶提供準確及充足的資料，使客戶得以作出知情的決定","具備所需特定技巧或知識的事宜進行受規管活動","應以合理標準的謹慎、技巧和努力進行受規管活動","應盡其最大努力避免利益衝突"],a:1,e:"《持牌保險代理人操守守則》一般原則 4 –\n勝任提供意見:持牌保險代理人應具備適當程度的專\n業知識和經驗，及只可進行該代理人所勝任的受規\n管活動。"},{c:"6.2.1",s:"以下哪項關於保險代理人的陳述是不正確的",o:["與保險經紀不同，代理人對提供意見不當的風險略為較輕","代理人在執行職務時的不當行為，會負上法律責任","代理人執行職務時必須謹慎","代理人合約中必須要備有專業彌償保險"],a:3,e:"保險代理人無須要備有專業彌償保險"},{c:"6.2.1",s:"違反《保險業條例》中的保險中介人條文",o:["只是民事過失","可以被判入獄，但不會判罰款","可以被判罰款，但不會判入獄","可以判罰款及入獄"],a:3,e:"違反《保險業條例》中的保險中介人條文可以判罰\n款及入獄"},{c:"6.2.1",s:"根據法定規定， 以下哪些需要至少一名負責人?\n(i) 持牌保險機構\n(ii) 持牌保險代理\n(iii) 持牌保險代理機構\n(iv) 持牌保險經紀公司",o:["(i)及 (ii) 而已","(i)及 (iii) 而已","(ii)及 (iv) 而已","(iii)及 (iv) 而已"],a:3,e:"條例就受規管人士中的“負責人”，規定每個持牌\n保險代理機構和持牌保險經紀公司最少有一個負責\n人，而所有負責人必須是持牌業務代表（代理人）\n或持牌業務代表（經紀）"},{c:"6.2.1",s:"在新的牌照制度下，已獲保監局發出作為任何持牌保險代理機構進\n行一個或多於一個業務系列的受規管活動的牌照的個人，屬於以下\n哪一個牌照類別?",o:["持牌業務代表（代理人）","持牌業務代表（經紀）","持牌保險代理機構","以上皆不是"],a:0,e:"已獲保監局發出作為任何持牌保險代理機構進行一\n個或多於一個業務系列的受規管活動的牌照的個人\n，屬持牌業務代表（代理人）"},{c:"6.2.1",s:"凡有意在經營業務或受僱過程中或為報酬而進行“受規管活動”必\n須首先獲得保監局發出的牌照，以下哪一項不屬於五類持牌人?",o:["持牌個人保險代理","持牌保險經紀公司","持牌業務代表（代理人 ）","持牌保險業務機構"],a:3,e:"持牌保險業務機構不屬於五類持牌人"},{c:"6.2.1",s:"在新的牌照制度下，已獲保監局發出作為任何持牌保險經紀公司進\n行一個或多於一個業務系列的受規管活動的牌照的個人，屬於以下\n哪一個牌照類別?",o:["持牌業務代表（代理人）","持牌業務代表（經紀）","持牌保險代理機構","以上皆不是"],a:1,e:"已獲保監局發出作為任何持牌保險經紀公司進行一\n個或多於一個業務系列的受規管活動的牌照的個人\n，屬於持牌業務代表（經紀）"},{c:"6.2.1",s:"以下哪一項是保險業條例下不能與受監管意見許可的豁免?",o:["律師","會計師","理財策劃師","精算師"],a:2,e:"理財策劃師不能與受監管意見許可的豁免"},{c:"6.2.1",s:"以下哪一項是保險業條例下不能與受監管意見許可的豁免?",o:["專屬自保保險公司的僱員","會計師","保險經紀","律師"],a:2,e:"從2019年9月23日起，其所有保險中介人都必須獲得\n保險業監管局的直接許可。"},{c:"6.2.1",s:"以下哪項為保監局施行的發牌制度的描述是正確的?",o:["作出任何“關鍵決定”必須首先獲得保監局發出的牌照","沒有就保險合約作出建議，只從事受規管活動則無須首先獲得保\n監局發出的牌照","獲授權保險人的職員，從事受規管活動則無須首先獲得保監局發\n出的牌照","邀請某人作出“關鍵決定”必須首先取得個人保險代理牌照"],a:3,e:"邀請或誘使，或企圖邀請或誘使任何人作出“關鍵\n決定”均屬為施行發牌制度而指明的受規管活動，\n便須首先取得個人保險代理牌照"},{c:"6.2.1",s:"根據保險業條例，以下哪項是持牌保險經紀公司個負責人的委任條\n件?\ni.負 責人可以是持牌業務代表（經紀人）\nii.負 責人必須是適當人選\niii.委 任負責人之前，必先獲得保監局的認可\niv.負 責人可以是持牌經紀人",o:["i,ii,iii","i,ii,iv","ii,iv","以上各項皆正確"],a:0,e:"持牌經紀人不屬保險業條例五類牌照類別，選項iv\n不正確"},{c:"6.2.1",s:"根據保險業條例，以下哪一項是屬於五類持牌人士??",o:["持牌個人經紀","持牌負責人","持牌業務代表（經紀）","持牌保險代理公司"],a:2,e:"只有選項iii屬於五類持牌人士，根據條例五類持牌\n人士包括持牌個人保險代理，持牌業務代表(代理人\n)，持牌保險代理機構，持牌業務代表(經紀)及持牌\n保險經紀公司"},{c:"6.2.2",s:"《保險業條例》對獲授權保險人就其委任的保險代理人(受委人)，\n就其向該客戶就發出保險合約或關乎該合約的相關保險業務有所往\n來的作為須負上 __________。",o:["罰款","轉承責任","最高誠信","牌照"],a:1,e:"《保險業條例》對獲授權保險人就其委任的保險代\n理人(受委人)，就其向該客戶就發出保險合約或關\n乎該合約的相關保險業務有所往來的作為須負上轉\n承責任"},{c:"6.2.2",s:"《保險業條例》第68條對_______________就其委任的保險代理人的\n作為須負上 轉承責任。",o:["保單持有人","受保人","獲授權保險人","獲授權被保險人"],a:2,e:"《保險業條例》第68條對獲授權保險人就其委任的\n保險代理人的作為須負上轉承責任"},{c:"6.2.4",s:"下列哪項不是保險經紀的「適當人選」測試?",o:["遵照最高誠信而行事","以客人的利益為首位","本著適當的謹慎及克盡本能而行事","選擇最低保費的產品介紹給客人"],a:3,e:"選擇最低保費的產品介紹給客人不是保險經紀的「\n適當人選」的要求"},{c:"6.2.4",s:"以下哪項屬於持牌個人保險代理的主要發牌條件？",o:["申請人屬適當人選","獲最少一名保險人委任","並非持有其他牌照","以上皆是"],a:3,e:"以上皆是持牌個人保險代理須符合的發牌條件"},{c:"6.2.4",s:"商業實體有否足夠擁有清晰責任及權限的組織架構，涉及以下哪領\n域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:1,e:"商業實體有否足夠擁有清晰責任及權限的組織架構\n，涉及“適當人選”勝任能力的要求"},{c:"6.2.4",s:"以下哪項是持牌保險代理機構有放的管控及程序?\ni.合 規\nii.投 訴處理\niii.保 存紀錄\niv.向 保監局報告事件",o:["i,ii","i,iii","ii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是持牌保險代理機構有放的管控及程序"},{c:"6.2.4",s:"以下哪項是持牌保險代理機構的主要發牌條件?",o:["申請人不可以是獨資經營","申請人並非持有個人保險代理牌照","申請人獲最少4名獲授權保險人委任為代理人","申請人不可以是合夥經營"],a:1,e:"申請人並非持有個人保險代理牌照屬其中一項是持\n牌保險代理機構的主要發牌條件"},{c:"6.2.4",s:"以下哪項是持牌保險代理人根據《持牌保險代理人操守守則》進行\n受規管活動時採取及遵從的行為準則?",o:["持牌保險代理人只可以現金方式支付的保費款項","持牌保險代理人只可以收取已經逾期的保費","持牌保險代理人須獲得其客戶授權才可以收取保費款項","以上各項皆不是"],a:3,e:"以上各項皆不是行受規管活動時採取及遵從的行為\n準則"},{c:"6.2.4",s:"保監局評估某人是否屬於適當人選時，就保險公司的控權人、合夥\n人、董事或負責人以及獲委任精算師有甚麼考慮因素?\ni.該 人的學歷、或其他資歷或經驗\nii.是 否有能力稱職地、誠實地並公正地進行受規管活動\niii.該 人的信譽、品格、可靠程度和誠信\niv.該 人的財政狀況或償付能力",o:["i,ii","i,iii,iv","iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是保監局評估某人是否屬於適當人選時\n，就保險公司的控權人、合夥人、董事或負責人以\n及獲委任精算師有甚麼考慮因素"},{c:"6.2.4",s:"持牌個人保險代理應就其可能進行受規管活動的各類保險產品的性\n質及主要特點，以及所承保及其相關的風險有充分了解，屬於哪個\n領域?",o:["產品知識","合適性","清楚其知識的局限性","利益衝突"],a:0,e:"持牌個人保險代理應就其可能進行受規管活動的各\n類保險產品的性質及主要特點，以及所承保及其相\n關的風險有充分了解，《持牌保險代理人操守守則\n》中產品知識要求"},{c:"6.2.4",s:"個人持牌人承擔並非與進行受規管活動有關的責任，該等責任是否\n將會引致利益衝突，涉及甚麼領域?",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:1,e:"個人持牌人承擔並非與進行受規管活動有關的責任\n，屬於適當人選中勝任能力的範疇"},{c:"6.2.4",s:"《持牌保險經紀操守守則》提及經紀操守守則的兩個目標，其中一\n項是",o:["頒布持牌保險經紀應遵守的操守原則及相關的標準及常規","監管保險公司及保障消費者","制定定價準則及規管市場行為","訂立持牌保險經紀的培訓標準"],a:0,e:"《持牌保險經紀操守守則》提及經紀操守守則的兩\n個目標，其中一項是頒布持牌保險經紀應遵守的操\n守原則及相關的標準及常規。"},{c:"6.2.4",s:"以下哪頂就《持牌保險代理人操守守則》的陳述正確?",o:["於2019年9月由保險業聯會所頒布","列明八項基本操守原則的一般原則","作為附屬法例，頒布於通常情況下期望持牌保險代理人在進行受\n規管活動時應遵守的操守原則及相關的標準及常規","以上各項皆是"],a:1,e:"《持牌保險代理人操守守則》列明八項保監局認為\n屬持牌保險經紀在進行受規管活動時應採納並遵守\n的基本操守原則的一般原則，守則”不具法律效力\n，也不是附屬法例，只有答案B正確。"},{c:"6.2.4(a)",s:"如申請人屬於獨資經營人、合夥和公司，其所有控權人、合夥人和\n董事必須屬於與進行該等業務系列的受規管活動有聯繫的適當人選\n。控權人被定義為直接或間接地擁有或控制（包括透過信託或持票\n人股份持有）該公司已發行股本的不少於X %， 哪麼X %是多少?",o:["15%","20%","25%","30%"],a:0,e:"申請人屬於獨資經營人、合夥和公司，其所有控權\n人、合夥人和董事必須屬於與進行該等業務系列的\n受規管活動有聯繫的適當人選。控權人被定義為直\n接或間接地擁有或控制（包括透過信託或持票人股\n份持有）該公司已發行股本的不少於15%"},{c:"6.2.4(b)",s:"以下哪一項是根據《保險業條例》批準負責人的條件?",o:["必須是持牌業務代表（代理人）或持牌業務代表（經紀）","適當人選","有充分權限，並獲得充足資源及支援","以上各項皆是"],a:3,e:"以上各項皆是根據《保險業條例》批準負責人的條\n件"},{c:"6.2.4(c)",s:"負責人須最少具有多少年保險業管理經驗？",o:["2年","5年","10年","15年"],a:0,e:"負責人須最少具有兩年保險業管理經驗"},{c:"6.2.4(c)",s:"評估商業實體有否識別出主要風險，及制訂策略以減低該等風險。\n涉及以下哪領域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:1,e:"就“適當人選”的斷定，詳細參閱研習資料手冊\n6.2.4(c)"},{c:"6.2.4(c)",s:"曾在香港或其他地方被任何專業團體、行業公會或監管機構譴責、\n紀律處分或公開批評。涉及以下哪領域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:0,e:"就“適當人選”的斷定，詳細參閱研習資料手冊\n6.2.4(c)"},{c:"6.2.4(c)",s:"該人士須是香港永久性居民；或持有不限制該人在香港進行受規管\n活動的適當入境簽證或許可的人士。涉及以下哪領域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:3,e:"該人士須是香港永久性居民；或持有不限制該人在\n香港進行受規管活動的適當入境簽證或許可的人士\n，涉及“適當人選”其他事宜的要求"},{c:"6.2.4(c)",s:"商業實體就遵守與其進行的業務系列的受規管活動相關的所有法律\n、規則、規例、守則、指引及其他規管規定設立足夠及有效的政策\n、程序及管控，涉及甚麼領域?",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:1,e:"屬於商業實體:稱職地並公正地進行受規管活動的能\n力(勝任能力)範疇就“適當人選”的斷定，詳細參\n閱研習資料手冊 6.2.4(c)"},{c:"6.2.4(c)",s:"個人持牌人曾在香港或其他地方被法院撤銷擔任公司董事的資格，\n是以下哪個範疇？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:0,e:"個人持牌人曾在香港或其他地方被法院撤銷擔任公\n司董事的資格，屬適當人選中可靠程度要求"},{c:"6.2.4(c)",s:"沒有按照法院的頒令償還任何判定債務，這未能滿足哪項發牌條件?",o:["實繳股本","適當人選","足夠的再保險安排","以上各頂皆是"],a:1,e:"沒有按照法院的頒令償還任何判定債務，這未能滿\n足適當人選發牌條件"},{c:"6.2.4(c)",s:"負責人最低限度的經驗是",o:["最少2行業經驗，其中包括2年管理經驗","最少5行業經驗，其中包括2年管理經驗","最少10行業經驗，其中包括5年管理經驗","最少10行業經驗，其中包括10年管理經驗"],a:1,e:"負責人最低限度的經驗是最少5行業經驗，其中包括\n2年管理經驗"},{c:"6.2.4(c)(iii)",s:"個人持牌人曾在香港或其他地方被法院撤銷擔任公司董事的資格，\n涉及以下哪領域？",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:0,e:"個人持牌人曾在香港或其他地方被法院撤銷擔任公\n司董事的資格，涉及涉及“適當人選”可靠程度的\n要求"},{c:"6.2.4(f)",s:"以下哪項就《持牌保險經紀操守守則》八大原則的描述是不正確?",o:["頒布於通常情況下期望持牌保險經紀在進行受規管活動時應遵守\n的操守原則及相關的標準及常規","告知並解釋適用於持牌保險經紀的《保險業條例》第90及第92條\n的法定操守規定","凡持牌保險經紀沒有遵從經紀操守守則”，此事本身會令該經紀\n可在任何司法律程序中被起訴","載列保險購買人在與持牌保險經紀往來時有權期望的專業操守之\n基本原則"],a:2,e:"凡任何持牌保險中介人沒有遵從操守守則，此事本\n身不會令該中介人可在任何司法或其他法律程序中\n被起訴。\n不過，在為《保險業條例》任何條文的目的而考慮\n持牌保險中介人是否屬繼續持牌的適當人選時，可\n顧及該中介人沒有遵從操守守則一事"},{c:"6.2.4(i)",s:"以下哪項是持牌保險代理機構的發牌條件?",o:["獨資經營者不可以申請牌照","最少獲得4名獲授權的保險人委任成為代理人","並非持有持牌業務代表（代理人）牌照","只可以合夥公司才可申請牌照"],a:2,e:"持牌保險代理機構的發牌條件，其中一個要求是並\n非持有持牌業務代表（代理人）牌照"},{c:"6.2.4(iv)",s:"以下哪項是持牌保險經紀公司的發牌條件?",o:["最少獲得1名獲授權的保險人委任","最少獲得4名獲授權的保險人委任","申請人並非持有保險代理機構牌照","申請人持有保險代理機構牌照"],a:2,e:"持牌保險經紀公司的其中一個發牌條件是申請人並\n非持有保險代理機構牌照"},{c:"6.2.4c",s:"一名保險代理人必須年滿幾多歲",o:["18歲","21歲","25歲","30歲"],a:0,e:"一名保險代理人必須年滿幾多歲18歲"},{c:"6.2.5",s:"銷售長期業務保單時，有關保險代理人必須就下列哪項或哪些作出\n解釋？",o:["保證及預計利益的分別","將來紅利可能會高於或低於現時水平","合約的長遠性質及提早中止合約的後果","上述所有各項"],a:3,e:"上述所有各項都是銷售長期業務保單時，保險代理\n人必須作出解釋的事項"},{c:"6.2.5",s:"根據《保險業條例》，以下哪些是對保險代理許可的行動?\ni) 發出譴責\nii) 暫停該代理人的委任\niii)終止該代理人的委任\niv)命令該人繳付罰款",o:["i ，ii","i ，ii，iii","iii，iv","i ，ii，iii，iv"],a:3,e:"以下各項皆是根據《保險業條例》，可對保險代理\n許可的行動"},{c:"6.2.5",s:"持牌保險經紀須遵守任何適用於保險經紀的法律，這是關於哪個領\n域？",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","勝任提供意見"],a:1,e:"持牌保險經紀須遵守任何適用於保險經紀的法律，\n屬持牌保險經紀操守守則合規要求"},{c:"6.2.5",s:"商業實體是否正涉及接管、管理、清盤或其他類似的法律程序，屬\n甚麼領域?",o:["可靠程度","勝任能力","財政狀況","其他事宜"],a:2,e:"商業實體是否正涉及接管、管理、清盤或其他類似\n的法律程序，屬適當人選發牌條件中可靠程度要求"},{c:"6.2.5",s:"持牌保險代理人應向其客戶提供有關該代理人推薦或安排的各保險\n產品之主要特點的所有相關資料，屬甚麼領域?",o:["有關保險產品披露","公平、公正及以客戶的最佳利益行事","以謹慎、技巧和努力行事","保存記錄"],a:0,e:"持牌保險代理人應向其客戶提供有關該代理人推薦\n或安排的各保險產品之主要特點的所有相關資料，\n屬持牌保險代理人操守守則中有關保險產品披露要\n求"},{c:"6.2.5(a)",s:"任何代理人最多可以代表",o:["四間保險公司","一間保險公司","兩間保險公司","任何數目的保險公司"],a:0,e:"任何代理人最多可以代表四間保險公司"},{c:"6.2.5(a)",s:"一個保險代理人希望代表一個綜合保險人的一般及長期業務，根據\n《保險業條例》中的規則是",o:["不能同時代表兩間保險公司","當作代表單一保險公司","當作代表兩間不同的保險公司","在保險業監管局同意下，允許代表兩間公司"],a:2,e:"任何人最多可獲4名獲授權保險人委任為“持牌人士\n”—持牌保險代理或持牌個人代理—進行受規管活\n動，其中獲授權經營長期業務的保險人不得超過2名\n。如果一個保險代理人希望代表一個綜合保險人的\n一般及長期業務，則當作代表兩間不同的保險公司"},{c:"6.2.5(a)",s:"根據規則3，任何人最多可獲4名獲授權保險人委任為“持牌人士”\n—持牌保險代理或持牌個人代理—進行受規管活動，其中獲授權經\n營__________________不得超過2名。",o:["一般業務的保險人","長期業務的保險人","綜合業務保險人","以上各項皆不是"],a:1,e:"任何人最多可獲4名獲授權保險人委任為“持牌人士\n”—持牌保險代理或持牌個人代理—進行受規管活\n動，其中獲授權經營長期業務的保險人不得超過2名"},{c:"6.2.5(a)(i)",s:"持牌保險經紀應遵守所有適用於該經紀的法律涉及以下哪領域？",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","勝任提供意見"],a:1,e:"持牌保險經紀應遵守所有適用於該經紀的法律涉及\n合適當人選合規要求"},{c:"6.2.5(f)",s:"持牌保險中介人應就進行受規管活動之任何相關事宜與其他相關監\n管機構合作，涉及以下哪領域?",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","防止賄賂"],a:1,e:"持牌保險中介人應就進行受規管活動之任何相關事\n宜與其他相關監管機構合作，涉及合適當人選合規\n要求"},{c:"6.2.5(f)(i)",s:"如從客戶取得的資料合理明顯地屬不完整或不準確，持牌保險代理\n人應作出合理的跟進查詢，以取得完整而準確的資料。涉及以下哪\n領域？",o:["保障客戶的私隱","以謹慎、技巧和努力行事","公平行事並符合客戶的最佳利益","保存紀錄"],a:2,e:"從客戶取得的資料合理明顯地屬不完整或不準確，\n持牌保險代理人應作出合理的跟進查詢，以取得完\n整而準確的資料。涉及《持牌保險代理人操守守則\n》公平行事並符合客戶的最佳利益要求"},{c:"6.2.5(f)(i)",s:"如持牌保險代理人受到金融管理專員、證券及期貨事務監察委員會\n或強制性公積金計劃管理局紀律處分。涉及以下哪領域？",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","防止賄賂"],a:1,e:"持牌保險代理人受到金融管理專員、證券及期貨事\n務監察委員會或強制性公積金計劃管理局紀律處分\n。涉及合適當人選合規要求"},{c:"6.2.5(f)(ii)",s:"若持牌保險經紀公司自行製作廣告或營銷材料以用於進行受規管活\n動，則應確保該等材料只含有準確的資料及並無貶低、誤導或欺騙\n成分。涉及以下哪領域？",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","勝任提供意見"],a:0,e:"若持牌保險經紀公司自行製作廣告或營銷材料以用\n於進行受規管活動，則應確保該等材料只含有準確\n的資料及並無貶低、誤導或欺騙成分。涉及《持牌\n保險經紀操守守則》準確的陳述及介紹要求"},{c:"6.2.5(f)(ii)",s:"持牌保險經紀在推薦保險產品予客戶前，應從充足範圍的不同保險\n人處，尋找及選擇充足範圍並可供選擇的保險產品，而該等產品是\n適合其客戶情況屬哪一項領域?",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","公正、客觀及公平"],a:3,e:"持牌保險經紀在推薦保險產品予客戶前，應從充足\n範圍的不同保險人處，尋找及選擇充足範圍並可供\n選擇的保險產品，而該等產品是適合其客戶情況屬\n《持牌保險經紀操守守則》公正、客觀及公平要求"},{c:"6.2.5(f)(ii)",s:"《持牌保險經紀操守守則》一般原則5，持牌業務代表（經紀）如為\n進行受規管活動的目的而派發名片，應確保該名片上正確地顯示出\n以哪幾項資料?\ni.其 香港身份證或護照上所示的姓名\nii.牌 照號碼\niii.牌 照類別\niv.其 委任持牌保險經紀公司的名稱",o:["i , ii, iii","ii, iii","ii,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是持牌業務代表（經紀）如為進行受規\n管活動的目的而派發名片，應確保該名片上正確地\n顯示的資料"},{c:"6.2.5(f)(ii)",s:"以下哪項有關《持牌保險經紀操守守則》一般原則 2\n–以符合客戶的最佳利益行事並公平對待客戶的描述是正確的？",o:["在推薦保險產品予客戶前，應從充足範圍的不同保險人處，尋找\n及選擇充足範圍並可供選擇的保險產品，而該等產品是適合其客戶\n情況","應採取合理步驟，準確及時地執行客戶的指示","應就其進行的受規管活動保存妥善的紀錄，以遵守所有適用的法\n律","應有足夠的管控及保障，以防止未經授權存取客戶資產"],a:0,e:"詳細參閱研習資料手冊6.2.5(f)(ii)《持牌保險經\n紀操守守則》"},{c:"6.2.5(f)(ii)",s:"根據《持牌保險經紀操守守則》一般原則 7 –\n持牌保險經紀應盡其最大努力避免利益衝突，持牌保險經紀應披露\n以下哪項以避免潛在利益衝突？",o:["保險人收取的保費","保險人支付的報酬","保險人的其他產品","保險人的償付準備金"],a:1,e:"根據《持牌保險經紀操守守則》一般原則 7\n，持牌保險經紀應披露保險人支付的報酬以，避免\n潛在利益衝突"},{c:"6.2.5(f)2.1(a)",s:"《持牌保險代理人操守守則》，一般原則 2 –\n公平行事並符合客戶的最佳利益，保險代理人推薦保險產品是時應\n該",o:["保險公司強烈推薦的保險產品","符合客戶利益的保險產品","最經濟的保險產品","最近期推廣的保險產品"],a:1,e:"《持牌保險代理人操守守則》，一般原則 2 –\n公平行事並符合客戶的最佳利益，保險代理人推薦\n保險產品是時應該符合客戶利益的保險產品"},{c:"6.2.5(g)",s:"保險經紀所須備有的專業彌償保險的最低彌償限額多樣化,但不會低\n於",o:["1百萬","2百萬","3百萬","4百萬"],a:2,e:"保險經紀所須備有的專業彌償保險的最低彌償限額\n多樣化,但不會低於3百萬"},{c:"6.2.5(g)",s:"每一個獲授權的保險經紀必須備存的繳足款股本為?",o:["250,000港元","500,000港元","1,000,000港元","2,000,000港元"],a:1,e:"每一個獲授權的保險經紀必須備存的繳足款股本為5\n00,000港元"},{c:"6.2.5(g)",s:"保險經紀備存的妥善簿冊及帳目，所需保留的最低限期為",o:["一年","三年","五年","七年"],a:3,e:"保險經紀備存的妥善簿冊及帳目，所需保留的最低\n限期為七年"},{c:"6.2.5(g)",s:"有關保險經紀必須備有的專業彌償保險，以下哪項或哪些項目正確?",o:["最低金額是三百萬","不必高於七千五百萬","過去12個月內佣金收入總額的兩倍","以上各項均是"],a:3,e:"以上各項皆是有關保險經紀必須備有的專業彌償保\n險的要求"},{c:"6.2.5(g)",s:"保險經紀必須備有「專業彌償保險」，最低的賠償限額為",o:["港幣10萬元","港幣200萬元","港幣300萬元","港幣400萬元"],a:2,e:"保險經紀必須備有「專業賠償保險」，最低的賠償\n限額為港幣300萬元"},{c:"7.1",s:"保險代理人及保險經紀對保單持有人的共同責任為",o:["所有行動必須合法","行為必須合理及公平","不應向客戶加諸不必要的影響","以上各項皆是"],a:3,e:"以上各項皆是保險代理人及保險經紀對保單持有人\n的共同責任"},{c:"7.1.1",s:"以下哪項或哪些屬於保險經紀的特點 ?",o:["被視為保險業中的專家","必須獨立於任何一位保險人","保單持有人期望取得經紀不偏不倚的建議","以上所有各項"],a:3,e:"以上所有各項保險經紀的特點"},{c:"7.1.1",s:"以下哪項有關保險經紀的錯誤及遺漏的陳述是正確?",o:["保險經紀有可能被裁定專業疏忽","保險經紀受到專業彌償保險的保障","他們的委託人及有關的被保險人可能有權向他們提出訴訟","以上所有各項"],a:3,e:"以上所有各項都是因保險經紀的錯誤及遺漏需承擔\n的責任及後果"},{c:"7.1.2",s:"以下哪一項就保險代理人的描述是不正確?",o:["因執行業務的疏忽行為所須承擔侵權法律責任的機會並非較高","因疏忽而對保單持有人提供不當的保險意見，須承擔侵權法律責\n任的機會並非較高","因疏忽而對保單持有人提供錯誤的保險意見，須承擔侵權法律責\n任的機會並非較高","保險代理人完全不用承擔任何侵權法律責任風險之中"],a:3,e:"一個保險代理人如果在為顧客承擔進行某項活動時\n，他因不當履行責任而被判須負法律責任的機會，\n相對經紀來說是比較小，但並不代表保險代理人完\n全不用承擔任何侵權法律責任風險之中"},{c:"7.2.1",s:"保護個人資料這方面的安全，由以下哪個全盤監察法例的執行",o:["私人(資料)個人專員","私隱(資料)個人專員","個人(資料)私人專員","個人(資料)私隱專員"],a:3,e:"保護個人資料這方面的安全，由個人(資料)私隱專\n員全盤監察法例的執行"},{c:"7.2.1",s:"《個人資料(私隱)條例》，「資料」定義包括？",o:["任何方式表示的資訊","意見的表達","個人的特徵","以上各項皆是"],a:3,e:"以上各項皆是《個人資料(私隱)條例》，「資料」\n的定義"},{c:"7.2.1",s:"《個人資料(私隱)條例》，有關「個人資料」的定義包括？",o:["直接或間接地與活著的個人有關","藉此可以直接或間接地核實某人的身分","有方法利用某種方式接觸或處理該等資料","以上各項皆是"],a:3,e:"以上各項皆是《個人資料(私隱)條例》，「資料」\n的定義"},{c:"7.2.1",s:"《個人資料(私隱)條例》中的「資料」的定義包括以下哪項或哪些\n因素?",o:["個人特徵","任何文件中之任何訊息的方式","表示訊息的方式可能包括意見的表達","以上所有各項"],a:3,e:"以上各項皆是《個人資料(私隱)條例》，「資料」\n的定義"},{c:"7.2.1",s:"《個人資料(私隱)條例》中有關「個人資料」的定義不包括以下哪\n項？",o:["直接或間接地與活着的個人資料有關","直接或間接地與一個法團的資料有關","有方法利用某種方式接觸或處理該等資料","藉此可以直接或間接地核實某人的身分"],a:1,e:"直接或間接地與一個法團的資料有關不是《個人資\n料(私隱)條例》中有關「個人資料」的定義"},{c:"7.2.1",s:"香港的《個人資料(私隱)條例》包括以下哪些資料保護原則？\ni ) 合法地收集個人資料\nii ) 公平地收集個人資料\niii ) 資料只能按照收集時的目的使用\niv ) 資料所屬人有權更正他們自己的個人資料",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上各項都是《個人資料(私隱)條例》資料保護原\n則內容"},{c:"7.2.1",s:"個人資料(私隱)條例中的第 1 原則",o:["資料應是準確的","當資料使用者收集某人的個人資料時，必須向該資料當事人提供\n的訊息","個人資料應是準確的、最新的","個人資料應是準確的、最新的，其保留期限不 應超過所需時間"],a:1,e:"保障資料第1原則:收集個人資料的目的及方式，描\n繪如何合法和公平地收集個人資料，及當資料使用\n者收集某人的個人資料時，必須向該資料當事人提\n供的訊息"},{c:"7.2.1",s:"《個人資料﹝私隱﹞條例》在某些情況容許保險公司透露保單持有\n人的資料，以下哪項或哪些是合法的情況？",o:["向保單持有人的親屬透露保障的詳情","向保單持有人發出繳付續保保費通知","向知名的報紙透露保單持有人的詳細資料","以上所有各項"],a:1,e:"向保單持有人發出繳付續保保費通知屬於在《個人\n資料﹝私隱﹞條例》下容許保險公司透露保單持有\n人的資料的合法情況"},{c:"7.2.1",s:"《個人資料﹝私隱﹞條例》中的私隱並不是絕對的，它容許在一些\n範圍下獲得豁免。這些豁免包括以下哪頂或哪些項目",o:["一些代表合法公眾利益的主題","為家居或娛樂目的持有的個人資料","所屬人接觸某些和僱傭關係有關的個人資料","以上所有各項"],a:3,e:"以上所有各項都是《個人資料﹝私隱﹞條例》中獲\n得豁免的範圍"},{c:"7.2.1",s:"根據《個人資料（私隱）條例》保障資料第1原則，若資料使用者收\n集個人資料時",o:["個人資料應是準確的,最新的，其保留期限不應超過所需時間","合法和公平地收集個人資料","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資\n料處理者的個人資料的保存時間超過處理該資料所需的時間","資料使用者須採取合約規範方法或其他方法，以防止轉移予該資\n料處理者的個人資料的保存時間超過30天"],a:1,e:"保障資料原則第1原則:收集個人料的目的及方式，\n此原則描繪如何合法和公平地收集個人資料"},{c:"7.2.1",s:"以下哪項對《個人資料(私隱)條例》範圍的陳述是正確的?：\ni. 自動化操作資料\nii.只適用於人手操作資料\niii. 只適用香港永久居民\niv. 它既涉及公營機構及私營機構",o:["i,ii,iii","i,iii,iv","i,iv","i,ii,iii,iv"],a:2,e:"個人資料是指自動化操作資料，以及涉及公營機構\n及私營機構"},{c:"7.2.1",s:"根據《個人資料﹝私隱﹞條例》容許在一些範圍下獲得豁免。這些\n豁免包括以下哪頂或哪些項目 ?\ni. 涉及防止罪案的事宜\nii. 涉及公眾健康的事宜\niii. 涉及國家安全的事宜\niv. 涉及風險管理的事宜",o:["i ，ii","iii，iv","i ，ii，iii","i ，ii，iii， iv"],a:2,e:"涉及風險管理的事宜不屬《個人資料﹝私隱﹞條例\n》獲得豁免"},{c:"7.2.1",s:"個人資料（私隱）條例》列明的六項保障資料原則，\n以下哪一項就第 1 原 則的描述正確?",o:["個人資料保留期限不應超過所需時間","個人資料應是準確的、最新的，其保留期限不應超過所需時間","採取適當的保安措施，以確保個人資料受保障而不受未獲准或意\n外的查閱","描繪如何合法和公平地收集個人資料"],a:3,e:"保障資料第1原則:收集個人資料的目的及方式，此\n原則描繪如何合法和公平地收集個人資料，及當資\n料使用者收集某人的個人資料時，必須向該資料當\n事人提供的訊息。"},{c:"7.2.1",s:"《個人資料 （私隱 條例》 由哪個機構執行?",o:["個人資料私隱專員公署","保險業監管局","資訊科技監控辦公室","以上各項皆不是"],a:0,e:"《個人資料（私隱條例》由個人資料私隱專員公署\n執行"},{c:"7.2.1",s:"根據《個人資料（私隱）條例》，以下哪項「個人資料」的定義是\n正確的?\ni.直接或間接地與活 着的資料當事人有關\nii.任何資料包括意見的表達\niii.未被任何形式記錄的資料，口頭方式描述的資料不屬「個人資\n料」\niv. 以上各項皆正確",o:["i,iii","ii,iii","i,ii","iv"],a:2,e:"直接或間接地與活着的資料當事人有關及任何資料\n包括意見的表達屬「個人資料」的定義，答案C正確"},{c:"7.2.1",s:"根據《個人資料(私隱)條例》，資料當事人有權查閱及更正其個人\n資料，屬於哪項資料使用原則?",o:["第1原則:收集個人資料的目的及方式","第2原則:個人資料的準確性及保留期限","第5原則:資訊須在一般情況下可提供","第6原則:查閱個人資料"],a:3,e:"根據《個人資料(私隱)條例》，資料當事人有權查\n閱及更正其個人資料，屬於第6原則:查閱個人資料"},{c:"7.2.1",s:"資料使用者透過制定服務合約，對資料處理者施加的責任是:\ni.資 料使用者有權審核及視察資料處理者如何處理和儲存個人資料\nii.不 再需要就受託目的處理有關個人資料時，\n必須適時交還、銷毀或刪除有關資料\niii.須 採取的保安措施，以保障受託的個人資料，並要求資料處理\n者遵從保障資料原則\niv.資 料處理者必須居於香港",o:["i.ii","ii,iii,iv","iii,iv","i.ii.iii"],a:3,e:"資料處理者必須居於香港不是對資料處理者施加的\n責任"},{c:"7.2.1(c)(i)",s:"向客戶提供一份「收集個人資料聲明」，應包括些甚麼?\ni.清 楚説明收集資料的目的\nii.資 料可能會轉移給什麽類別的人\niii.不 提供資料所須承受的後果\niv.要 求查閲及改正資料的權利",o:["i,ii,ii","i,ii,iv","i,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是「收集個人資料聲明」包括的內容"},{c:"7.2.2",s:"以下哪項會受到《個人資料(私隱)條例》所限制？",o:["索償時調查的資料","投保時所提及的個人資料","個人驗身報告的資料","包括以上各項"],a:3,e:"以上各項受到《個人資料(私隱)條例》所限制的個\n人資料"},{c:"7.2.2",s:"在《個人資料（私隱）條例》涉及範圍中，就保險人所擁有保單持\n有者的資料使用上，以下哪項是合法的？",o:["向保單持有人的親屬透露其壽險保單資料","向保單持有人發出續保通知","向著名的報紙出賣被保險人資料","以上所有各項"],a:1,e:"向保單持有人發出續保通知在《個人資料（私隱）\n條例》涉及範圍中是容許的"},{c:"7.3.1",s:"在香港成立平等機會委員會的目的，是要執行為針對不公平歧視而\n制訂的各項條例，所要針對的歧視，涉及到受害人的下列哪項或哪\n些項目",o:["性別","婚姻狀況","身體殘疾","以上所以各項"],a:3,e:"以上所以各項都是針對歧視法例包括的項目"},{c:"7.3.1",s:"以下哪項不是與香港不公平歧視有關法規？",o:["性別歧視條例","年齡歧視條例","殘疾歧視條例","家庭崗位歧視條例"],a:1,e:"香港針對歧視有關法規並沒有年齡歧視"},{c:"7.3.1",s:"香港現有的4條歧視條例，當中包括性別、殘疾、種族及",o:["宗教","年齡","家庭崗位","身高體重"],a:2,e:"香港現有的4條歧視條例，當中包括性別、殘疾、種\n族及家庭崗位"},{c:"7.3.1",s:"香港成立的平等機會委員會負責執行消除各種歧視但不包括以下哪\n項或哪些？",o:["性別","年齡","婚姻狀況","以上各項皆是"],a:1,e:"香港成立的平等機會委員會負責執行消除各種歧視\n但不包括年齡歧視"},{c:"7.3.2",s:"對保險業而言，以下哪項屬於公平歧視(即合法)的情況",o:["向女性取較低的人壽保險保費","向男性付出年金款項比同一年齡的女性較多","向殘疾人士的保單加設特定條款","以上各項皆是"],a:3,e:"答案選項A,B及C都屬於保險中的公平歧視"},{c:"7.3.2",s:"以下哪三項較為被保險人視為「公平歧視」？\ni) 為女性提供較低的年金\nii) 向男性收取較高的人壽保險保費\niii)向女性收取較高的汽車保險保費\niv)在提供人身意外保險時向殘疾人仕收取較高保費",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"女性收取較高的汽車保險保費不屬保險人的「公平\n歧視」，只有選項i,ii,iv正確"},{c:"7.3.2",s:"《保險業條例》規定不能對不同的投保人給予不同的對待，除非：\ni)有關的待遇涉及宗教\nii)有關待遇是參照可合理依據的來源所得的精算數據給予的\niii)以該等數據而言，有關待遇屬於合理的\niv)有關的待遇不涉及保費",o:["i, ii, iv","i, ii, iii","ii, iii","i, ii, iii, iv"],a:2,e:"《保險業條例》規定不能對不同的投保人給予不同\n的對待，除非有關待遇是參照可合理依據的來源所\n得的精算數據給予的，以及就該等數據而言，有關\n待遇屬於合理的"},{c:"7.3.2",s:"以下哪項有關保險人對投保人給予性別差別對待是法律容許的，並\n不觸犯歧視條例？",o:["有關待遇是藉參照可合理依據的來源所得的精算數據","有關待遇是藉參照可合理依據的來源所得的精算數據或其他數據\n而給予的","就有關因素而言屬於合理","一切參照可合理依據的來源所得的精算數據"],a:1,e:"保險人對投保人給予性別差別對待是藉參照可合理\n依據的來源所得的精算數據或其他數據而給予的"},{c:"7.3.3",s:"以下哪項或哪些是保險中的不公平歧視?",o:["向女性徵收比同一年齡、健康狀況等的男性較低的人壽保險保費\n率","向男性比同一年齡、健康狀況等的女性付出較高的年金款項","向女性駕駛者收取較高的保費","以上全部皆是"],a:2,e:"向女性駕駛者收取較高的保費是保險中的不公平歧\n視"},{c:"7.3.3",s:"以下哪項屬於保險中的公平歧視(合法)的歧視",o:["向女性收取較高的汽車保險保費","向女性加設較苛刻的汽車保險條款","向有眼疾的人徵收較高的人身意外保費率","拒絕為離婚婦女提供家居保險"],a:2,e:"向身體殘疾人士徵收較高的人身意外保費率屬於保\n險中的公平歧視"},{c:"7.4.4",s:"以下哪項屬於洗錢的階段?\ni.整 合\nii.投 資\niii.分 層交易\niv.轉 化交易",o:["i,ii,iii","i, iii,iv","ii,iii,iv","i,iii"],a:3,e:"洗錢通常分為3個階段，按次序是存放，分層交易及\n整合。"},{c:"7.4.5",s:"容易被利用作為進行洗錢或恐怖份子籌資活動工具的長期保險合約\n包括",o:["單位相連或可分紅的整付保費合約","固定及變額年金","(二手)儲蓄壽險保單","以上各項皆正確"],a:3,e:"以上各項都是容易被利用作為進行洗錢或恐怖份子\n籌資活動工具的長期保險合約"},{c:"7.4.6",s:"在香港，與洗錢／恐怖分子資金籌集有關的法例為:\ni.《 有組織及嚴重罪行條例》\nii.《 販毒（追討得益）條例》\niii.《 防止賄賂條例》\niv.《 保險業條例》",o:["i, ii, iii","i, ii","i, iv","i, ii, iii, iv"],a:1,e:"《保險業條例》及《防止賄賂條例》不是在香港，\n與洗錢／恐怖分子資金籌集有關的法例"},{c:"7.4.6",s:"在香港，與洗錢／恐怖分子資金籌集有關的法例為:\ni.《有組織及嚴重罪行條例》\nii.《販毒（追討得益）條例》\niii.《聯合國制裁條例》\niv.《大規模毀滅武器（提供服務的管制）條例》\nv.《打擊洗錢及恐怖分子資金籌集條例》",o:["i, ii, iii","i, ii","i, iv","以上所有皆是"],a:3,e:"以上所有皆是在香港，與洗錢／恐怖分子資金籌集\n有關的法例"},{c:"7.4.6",s:"以下哪項是《防止賄賂條例》的立法精神?\ni.協 助商界維持一個有利於效率和公平競爭的營商環境\nii.吸 引外商投資，並持續投資於香港\niii.保 障不同持份者的利益，並保護主事人免受代理人以權謀私所\n損害\niv.消 除社會就性別、殘疾 、家庭崗位、種族 的歧視",o:["i,iii","iii,iv","i,iv","以上全部皆是"],a:0,e:"《防止賄賂條例》協助商界維持一個有利於效率和\n公平競爭的營商環境，以保障不同持份者的利益，\n並保護主事人免受代理人以權謀私所損害。只有選\n項 i,iii是正確"},{c:"7.4.7",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）由下列哪個機構發\n出？",o:["香港金融管理局","保險業聯會","保險業監管局","以上各項皆正確"],a:2,e:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）由\n保險業監管局發出"},{c:"7.4.7",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）不適用於",o:["再保險公司","銀行業條例下成立的金融機構","持牌保險經紀公司","持牌個人保險代理"],a:1,e:"《打擊洗錢及恐怖分子資金籌集指引》（指引3）不\n適用於銀行業條例下成立的金融機構"},{c:"7.4.7",s:"《販毒（追討得益）條例》及《有組織及嚴重罪行條例》都有著保\n險人關心的共同原則，並應用於",o:["洗錢活動","適當人選","違反對保險人的最高誠信","避免對索償職員做用暴力"],a:0,e:"《販毒（追討得益）條例》及《有組織及嚴重罪行\n條例》都有著保險人關心的共同原則，並應用於洗\n錢活動"},{c:"7.4.7",s:"保險業監管局發出《打擊洗錢及恐怖分子資金籌集指引》，此《指\n引》的目的在於",o:["介紹有關洗錢及恐怖分子資金籌集的背景","概述在香港有關打擊洗錢及恐怖分子資金籌集的主要法律條文","提供實務指引以協助保險機構及其高級管理層制定及實施相關政\n策、程序及管控措施","以上各項皆是"],a:3,e:"以上各項皆是保險業監管局發出《打擊洗錢及恐怖\n分子資金籌集指引》的目的"},{c:"7.4.7b",s:"基於風險為本的關鍵原則是",o:["正確釐定保費","所有交易應用相同措施","根據風險級別分配資源","遵循標準慣例"],a:2,e:"基於風險為本的關鍵原則是根據風險級別分配資源"},{c:"7.4.7c",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3），保險機構的高級\n管理層有責任實施有效的打擊洗錢及恐怖分子資金籌集制度，所制\n訂的管控措施應涵蓋的範疇包括﹕",o:["限制接受外幣","委任一名法律主任","委任一名合規主任","成立一個情報單位"],a:2,e:"《打擊洗錢及恐怖分子資金籌集指引》（指引3），\n保險機構的高級管理層有責任實施有效的打擊洗錢\n及恐怖分子資金籌集制度，所制訂的管控措施應涵\n蓋的範疇包括委任一名合規主任"},{c:"7.4.7c",s:"《打擊洗錢及恐怖分子資金籌集指引》（指引3），保險機構的高級\n管理層有責任實施有效的打擊洗錢及恐怖分子資金籌集制度，所制\n訂的管控措施應涵蓋的範疇包括﹕",o:["限制接受外幣","委任一名高級職員擔任洗錢報告主任","成立一個情報單位","以上各項皆不是"],a:1,e:"打擊洗錢及恐怖分子資金籌集指引》（指引3），保\n險機構的高級管理層有責任實施有效的打擊洗錢及\n恐怖分子資金籌集制度，所制訂的管控措施應涵蓋\n的範疇包括委任一名高級職員擔任洗錢報告主任"},{c:"7.5",s:"以下哪項是貪污，必須避免觸犯？",o:["個人為謀取私利，從而引至社會利益受損","個人為謀取私利，濫用職權，從而引至他人利益受損","個人未經準許謀取私利，從而引至他人利益受損","個人挪用屬於他人的財產"],a:1,e:"貪污是指個人為謀取私利，濫用職權，從而引至他\n人利益受損"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項並非條例所指的利益？",o:["款待","借貸","職位","服務"],a:0,e:"款待不屬利益"},{c:"7.5",s:"根據《防止賄賂條例》，利益的限額是",o:["100元或以上","500元或以上","1000元或以上","沒設最低金額"],a:3,e:"根據《防止賄賂條例》，利益的限額是沒設最低金\n額"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項並非條例所指的利益？",o:["價值二十元的利是","價值一百元的百貨公司折扣券","價值五百元的貸款","米芝蓮餐廳套餐"],a:3,e:"即場享用之美食屬款待不是利益"},{c:"7.5",s:"根據《防止賄賂條例》，以下哪項屬於利益?\ni.客 戶送贈的禮物\nii.團 隊隊員給予的佣金\niii.百 貨公司折扣禮劵\niv.保 險公司職位",o:["i","i,ii","i,ii,iv","以上各項皆是"],a:3,e:"「利益」的定義廣泛，包括金錢、饋贈、貸款、報\n酬、佣金、職位、任何職位、受僱工作或合約、服\n務、優待及任何有價證券或任何種類的其他財產或\n財產權益"},{c:"7.5.1",s:"以下哪一項是《防止賄賂條例》下僱員應該遵守或避免的行為?",o:["僱員從事有關業務或事務時，如未經僱主同意，不得創業","僱員從事有關業務或事務時，如未經僱主同意，不得在其關係終\n止5年內創業","僱員從事有關業務或事務時，如未經僱主同意，不得索取或接受\n任何利益","僱員從事有關業務或事務時，如未經僱主同意，不得委任分代理\n人"],a:2,e:"根據《條例》第9(1)條的規定，代理人在處理其主\n事人的業務或事務時，如未經主事人的允許，不得\n索取或接受任何利益"},{c:"7.5.1",s:"當遇上賄賂行為，代理人應該",o:["接受行賄，並保留賄款作為證據","堅決拒絕，並應立刻向廉署舉報","接受行賄，但不協助其貪污行為","與行賄者協商賄款金額"],a:1,e:"當遇上賄賂行為，代理人應該堅決拒絕，並應立刻\n向廉署舉報"},{c:"7.5.1",s:"以下哪項不會觸犯《防止賄賂條例》第9條?",o:["持牌個人保險代理收受客戶提供的利益，以協助對方在購買人壽\n保險時隱瞞已存在的疾病投保","持牌業務代表（經紀）間中宴請客戶，以維持與客戶良好關係","持牌個人保險代理為取得公司客戶的員工團體保險合約，私下向\n公司客戶的人事部經理提供利益以換取簽訂員工團體保險合約","持牌業務代表(代理人)利用偽造的保險申請書來騙取持牌保險代\n理機構的佣金"],a:1,e:"款待（即當場享用之飲食）則不是利益。"},{c:"7.5.1",s:"以下哪項觸犯了《防止賄賂條例》第9(三)條?",o:["一名持牌個人保險代理人意圖利用偽造的保險申請書來騙取保險\n公司的佣金","保險公司的採購人員提交虛假文件，令採購合約判給與該名採購\n人員有關連的公司","一名持牌業務代表(代理人)偽造培訓紀錄以騙取培訓津貼","以上各項皆是"],a:3,e:"以上各項皆是觸犯了《防止賄賂條例》第9(三)條的\n例子"},{c:"7.5.1",s:"以下哪項是《防止賄賂條例》的描述是正確的?\ni.防 止主事人免受代理人濫用職權所損害\nii.持 牌個人保險代理是作為保險經紀公司委任的業務代表\niii.行 賄目的未達可作為賄賂的辯護理由\niv.以 上皆是",o:["i.","i,ii","ii,iii","v"],a:0,e:"《防止賄賂條例》目的是防止主事人免受代理人濫\n用職權所損害，行賄目的未達不可作為賄賂的辯護\n理由，只有選項i正確，答案是A"},{c:"7.5.1(b)(iii)&(iv)",s:"以下哪項不能作為貪污的辯解理由?\ni 收賄是行業或事業的習慣\nii受賄者和行賄者已達成口頭協議，但受賄者無意圖辦理行賄者要\n求的事\niii 透過第三者收賄\niv 貪污目的未達",o:["i & iii","ii & iv","ii, iii & iv","i, ii, iii & iv"],a:3,e:"以上各項都不能作為貪污的辯解理由"},{c:"7.5.1b(iii)",s:"根據《防止賄賂條例》，款待不是利益，以下哪項屬款待的定義?",o:["酒店住宿","歌舞節目表演","即場享用之美食","海外公幹"],a:2,e:"即場享用之美食屬款待不是利益"},{c:"7.5.2",s:"以下哪一項是廉政公署24小時舉報熱線？",o:["999","25 266 366","1823","24 266 366"],a:1,e:"以下哪一項是廉政公署24小時舉報熱線是25 266\n366"},{c:"7.6",s:"保險事宜上的詐騙",o:["可循多種途徑發生，不論是否與索償有關","只會於涉及索償時發生","從來不會於人壽保險上發生","只會於涉及財產損害的索償時發生"],a:0,e:"保險事宜上的詐騙可循多種途徑發生，不論是否與\n索償有關"},{c:"7.6",s:"協助保單持有人向保險人作詐騙性索償的保險中介人",o:["在該項行動中沒有任何法律責任","總被視為代表保險人的代理人","將被視為代表該保單持有人的代理人","因這項行動而需向該保單持有人承擔法律責任"],a:2,e:"協助保單持有人向保險人作詐騙性索償的保險中介\n人將被視為代表該保單持有人的代理人，「不作為\n的參與」及「作為的參與」同樣地有罪。"},{c:"7.6",s:"保險中介人挪用了代保險人收取的保費後，會被控以下哪項罪名？",o:["挪用金錢罪","盜竊罪","不誠實罪","故意偷竊罪"],a:1,e:"保險中介人挪用了代保險人收取的保費後，會被控\n盜竊罪罪名"},{c:"7.6",s:"對保險代理人而言，以下哪項或哪些技術性地構成詐騙？",o:["建議客戶不要透露某些重要事實","在詐騙索償中，沒有將明確的資料交給保險人","在安排保險過程中，故意隱瞞一些不良影響的資料","以上各項皆是"],a:3,e:"以上各項皆是技術性地構成詐騙的罪行"},{c:"7.6",s:"在各種防止詐騙的實際方法中，保險業職員值得考慮的其中最重要\n一項為",o:["保持警覺，它可以在任何情況下出現","對任何索償人士投以極大懷疑","瞭解到它只會於大額索償時出現","對每一極小的細節均要求嚴格的證明及確認"],a:0,e:"在各種防止詐騙的實際方法中，保險業職員值得考\n慮的其中最重要一項為保持警覺，它可以在任何情\n況下出現"},{c:"7.6",s:"有甚麼實際步驟可以防止詐騙?",o:["對每位客戶應存有懷疑","盡量減少與保險人聯絡","保持警覺","以上各項都是"],a:2,e:"防止詐騙的實際步驟包括保持警覺，勤勉地防範詐\n騙，時刻與保險人保持緊密溝通，以及保持誠信，\n答案C正確"},{c:"7.6.1",s:"犯罪者不是以主犯的身份犯罪就是以那麼的身份犯罪?",o:["次犯","從犯","助犯","刑事代替犯"],a:1,e:"犯罪者不是以主犯的身份就是以從犯的身份參與犯\n罪。一項刑事罪的從犯是指一名協助、教唆、慫使\n或促致犯該罪行的人"},{c:"7.6.2",s:"以下哪碰項有關保險詐騙的陳述是正確的?",o:["舉報保險詐騙是中介人的責任","失實地陳述投保資料 ，即屬詐騙","失實地陳述投保資料，即屬詐騙","以上各項皆正確"],a:3,e:"以上各項皆是有關保險詐騙的正確陳述"},{c:"7.6.2(b)",s:"就保險詐騙性索償，保險中介人有以下哪項責任?\ni.拒 絕索償\nii.執 行相關法律\niii.舉 報可疑事件或提供證據\niv.協 助保險人揭露詐騙行為",o:["i,iii,iv","i,ii,iv","iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是就保險詐騙性索償，保險中介人須要\n負上責任"}],"paper3-mock-09":[{c:"1.1",s:"以下哪項為人壽保險最初的基本目的?",o:["為退休提供一筆資金","儲蓄","應付暫時的需要","退休安排"],a:2,e:"最初，保險單有效期較短，只為暫時性的風險情況"},{c:"1.1",s:"人壽保險最初的目的為",o:["為退休後支付每個月的生活費","向被保險人的家屬提供幫助","為一名海上死亡的船員提供保障","應付短期債務之用"],a:1,e:"人壽保險的最初及最基本目的是，\n在被保險人或稱受保人去世後，尤其在早逝的情況\n下，很大可能會給受養人帶來經濟困難，人壽保險\n利益可向被保險人的家人或其他人提供幫助。"},{c:"1.1",s:"以下哪項不是人壽保險的功能?",o:["逃稅","儲蓄","為退休生活做好準備","以防早逝"],a:0,e:"逃稅不是人壽保險的功能"},{c:"1.1",s:"人壽保險的最初目的是",o:["為某人在某段時間內死亡提供整筆金錢","為英年早逝死亡提供整筆金錢","為退休人士提供金錢的儲蓄","為某人早逝死亡時為其家人提供一筆金錢"],a:3,e:"人壽保險的最初目的是為某人早逝死亡時為其家人\n提供一筆金錢"},{c:"1.1",s:"下列哪項購買壽險的動機是這類保障的最初目的?",o:["作為儲蓄的安排","投資","為退休作出安排","暫時需要/威脅"],a:3,e:"最初，保險單有效期較短，只為暫時性的風險情況\n提供保障"},{c:"1.1",s:"最初,人壽保險保單是",o:["並非保障因意外引致之死亡","均屬長期性之死亡賠償安排","祗限於被保生命於特定期限內生存時支付金額","為期短,於特定期限內支付利益"],a:3,e:"最初,人壽保險保單是為期短,於特定期限內支付利\n益"},{c:"1.1",s:"「保險公司承諾當被保險人死亡時支付保險金的保險。」這段引述是",o:["完全不正確","完全描述了所有人壽保險合約","未能完全描述所有人壽保險合約","令人完全誤解並且內容不實"],a:2,e:"現代人壽保險可以滿足其他需求。包括：儲蓄，投\n資，或退休收入"},{c:"1.1",s:"人壽保險最初及最基本的目的，在現代社會也有這樣的保障保險(定期壽險)是什麼？",o:["死亡(尤其在早逝的情況下)","為受保人在生的每一年提供生活收入","儲蓄","在餘下生命裏提供保障"],a:0,e:"最初，保險單有效期較短，只為暫時性的風險情況"},{c:"1.1",s:"人壽保險合約最初類型",o:["本質上屬於短暫的，以保障早逝情況","本質上屬於長久的，即直至死亡","與物業抵押貸款有關","屬單位相連的安排"],a:0,e:"最初，保險單有效期較短，只為暫時性的風險情況"},{c:"1.1",s:"人壽保險定義為：「保險公司承諾當受保保單持有人死亡時給付保險金的保險」這段引\n述是",o:["有限制的，在可能的情況下是可行的","這是最初及最基本的目的","這未能完全描述現代的人壽保險","以上所列各項都是正確的"],a:3,e:"人壽保險的最初及最基本目的是，在被保險人或稱\n受保人去世後，向被保險人的家人或其他人提供幫\n助。。隨着人壽保險的逐步完善，，在許多情況下\n人壽保險都是一種非常有用的工具。以上所列各項\n都是正確"},{c:"1.2",s:"壽險索償理據需要根據以下哪項保險原則？",o:["彌償","代位","近因","可保權益"],a:2,e:"在人壽保險中，死亡的原因並不十分重要。除非在\n自殺除外責任條款或意外死亡保險利益附約適用的\n情況下，被保險人死亡的近因就顯得非常重要。"},{c:"1.1.1",s:"下列哪項可被稱為人壽保險中的「商業需求」而非「個人需求」？\ni) 關鍵人物\nii) 企業擁有人\niii) 退休收入\niv) 僱員福利",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"退休收入屬個人需求"},{c:"1.1.1",s:"考慮可供選擇的人壽保險的類型時，以下哪三項可被視為人壽保險中的個人而非商業要\n求?\ni) 關鍵人物\nii) 教育經費\niii) 退休收入\niv) 受贍養者的生活開支",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii , iii , iv"],a:3,e:"關鍵人物是屬於人壽保險的商業需求"},{c:"1.1.1",s:"下列哪項為壽險保單商業需求而非個人需求？",o:["合夥人","教育經費","應急資金","受養者生活開支"],a:0,e:"關鍵人物人壽保險就某公司員的生命購買保險，以\n補償公司由於該要員的死亡而帶來的損失。生意合\n夥人就是其中例子"},{c:"1.1.1",s:"下列哪項在人壽保險中不屬於「個人需求」？",o:["應急資金","關鍵人物","教育經費","受養人的生活開支"],a:1,e:"關鍵人物人壽保險就某公司員的生命購買保險，以\n補償公司由於該要員的死亡而帶來的損失。屬商業\n需求"},{c:"1.1.1",s:"選擇可供購買的人壽保險的合適度，最常用的方法",o:["保險合約的發出地點","可賺取的英式紅利和紅利","迎合個人及商業需要的程度","保險合約的貨幣選擇"],a:2,e:"現代觀點傾向從個人及商業需求的角度去了解現有\n的人壽保險産品。"},{c:"1.1.1",s:"人壽保險在現代觀點上看，可滿足哪項需求？",o:["商業及個人","售賣地點","售賣貨幣","紅利利益"],a:0,e:"現代觀點傾向從個人及商業需求的角度去了解現有\n的人壽保險産品。"},{c:"1.2(e)",s:"就人壽保險而言，由兩個或以上保險人共同承擔同一賠償似乎不太可能。但在一般保險\n而言，(例如醫療保險)，以下哪項保險原則會導致共同承擔補償?",o:["代位","分擔","彌償","可保權益"],a:1,e:"在大多數一般保險類別中，如果某人偶然就同一損\n失擁有多於一份保單，他不會收到重複賠償。每份\n保單會按比例分擔損失。"},{c:"1.2(h)(ii)",s:"債權人可就其債務人的生命投保。在債務得到償還後，會出現以下哪個情況？",o:["保單必定立即終止","債權人必須轉讓保單給債務人才繼續有效","仍然維持該保單的有效性，並在適當時候「再次得到償付」","以上答案均不正確"],a:2,e:"人壽保險的可保權益只有在合約開始時才需要，在\n債務得到償還後，仍然維持該保單的有效性"},{c:"1.2.1",s:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係要求的描述是正確的？\ni. 就某人的生命購買保險，對該受保生命必須具有可保權益。但透過轉讓程序購買別人\n的現有保單，對該受保生命無須具有可保權益\nii. 保單所有人不能將壽險合約轉讓予第三者，即使該第三者對受保生命具有可保權益\niii. 保單所有人可以把正當地安排的壽險合約轉讓予第三者，即使該第三者對受保生命\n缺乏可保權益\niv. 保單所有人只可將壽險合約轉讓予對該受保生命有可保權益的第三者",o:["i, iii","i, ii","i, iii, iv","ii, iii, iv"],a:0,e:"保單所有人可把正當地安排的人壽保險合約轉讓給\n第三者，即使該第三者對受保生命缺乏可保權益"},{c:"1.2.1",s:"就可保權益而言，以下哪些情況下才可以作出轉讓;",o:["只可轉讓給個人的雙親及配偶","只可轉讓給一個關係親密的家庭成員","只可轉讓給只有可保利益的承讓人","可轉讓給任何沒有可保利益的人"],a:3,e:"人壽保險可轉讓給任何沒有可保利益的人"},{c:"1.2.1",s:"以下哪項保險原則是彌償的引伸?",o:["披露責任","代位權","A&B","以上皆不正確"],a:1,e:"彌償有兩個引伸，即分擔及代位權。"},{c:"1.2.1",s:"下列哪項正確描述可保權益",o:["它不是普通法的條款","在香港的法定條文中已擴闊了它的範圍","壽險保單中承讓人必須具有可保權益","它只能由家庭或婚姻關係中出現"],a:1,e:"可保權益在香港的法定條文中已擴闊了它的範圍，\n例如根據判例法，\n若對其他人具備可以用金錢來估值的權益，都可具\n有保權益"},{c:"1.2.1",s:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係的陳述是正確的?\ni. 為某人的生命購買保險，必須具有可保權益。但購買別人的現有保單，則無須可保權\n益\nii. 壽險合約轉讓予第三者無須可保權益\niii. 保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者\niv. 保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者",o:["i, ii","i, iii","i, iii, iv","ii, iii, iv"],a:0,e:"保 單 所 有 人 可 把 正當地安排的人壽保險合約轉讓給\n第三者，即使該第三者對受保生命缺乏可保權益"},{c:"1.2.1",s:"下面有關人壽保險中可保權益的法律的陳述正確的是?",o:["每一個男子對自己的生命具有無限的可保權益","一個人對自己生命所具有的可保權益限於該人的資產值","一個人對自己生命所具有的可保權益限於該人的收入","一個人對自己生命所具有的可保權益與該人就其他人的生命所具有的可保權益相同"],a:0,e:"我們都對自己的生命及對其配偶具有無具有無限金\n額的可保權益。"},{c:"1.2.1",s:"一名人士對另一人的生命具有一項權益，這權益在法律上賦予法定權利可就該人物的生\n命購買保險，這稱為",o:["可保權益","最高誠信","家庭保險權益","特別權益"],a:0,e:"可保權益是某人對某項保險標的在法律上被認可的\n一種關係，這種關係賦予他對該保險標的購買保險\n的權利。"},{c:"1.2.1",s:"以下哪兩項具有有效的可保權益?\ni)為自身債務人的生命購買人壽保險\nii)為自身年屆二十五歲的兒子的生命購買人壽保險\niii)為現時的生意伙伴的生命購買人壽保險\niv)為前配偶(已離婚)的生命購買人壽保險",o:["i, ii","ii, iii","iii, iv","i, iii"],a:3,e:"父母對已成年的子女，以及已離婚夫婦之間是沒有\n可保權益。只有選項i, iii正確"},{c:"1.2.1",s:"如果某人對他人的生命具有一項權益，可讓前者享有法律上的權利就後者的生命投保，\n這類權益稱為",o:["彌償","最高誠信","法定權益","可保權益"],a:3,e:"某人對他人的生命具有一項權益，可讓前者享有法\n律上的權利就後者的生命投保，這類權益稱為可保\n權益"},{c:"1.2.1",s:"以下哪項是對可保權益的法律權利定義的正確描述?",o:["我們對自己的生命具有無限金額的可保權益","任何人對其配偶具有無限金額的可保權益","債權人有權就欠債人的生命購買保險，保額為貸款金額另加合理利息","以上各項皆是"],a:3,e:"我們都對自己的生命及對其配偶具有無具有無限金\n額的可保權益。債權人可就債務人生命購買壽險，\n保額為貸款金額另加應計利息，以上各項都正確"},{c:"1.2.1",s:"在香港，以下哪項有關人壽保險的可保權益的說明是不正確的？",o:["配偶對另一方都具有可保權益","根據法例，父母對於任何一個子女具可保權益","血緣關係能構成可保權益","監護人對未成年的受監護人足可構成可保權益"],a:1,e:"在香港，根據《保險業條例》第64A條，未成年人\n（未滿18歲的人）的父母或監護人就該年輕人享有\n可保權益。這類關係是在配偶關係以外，唯一構成\n可保權益的血緣或家庭關係。答案B不正確"},{c:"1.2.1",s:"可保權益是指某人與「標的」之甚麼關係？",o:["最高誠信","法律認可","合約","血緣"],a:1,e:"可保權益是指某人與「標的」(受保人或被保險人)\n之間法律認可的關係"},{c:"1.2.1",s:"根據可保權益，一個人可為以下哪三項人仕購買保險？\ni) 配偶\nii) 自己十歲的子女\niii) 欠自己錢的人(債仔)\niv) 自己欠他錢的人(債主)",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],a:0,e:"如果某人欠你錢，你可就債務人(債仔)的生命購買\n壽險，保額為貸款金額另加應計利息，反而債務人\n(債仔)就債權人(債主)是沒有可保權益的"},{c:"1.2.1(b)",s:"根據《保險業條例》第64b條指出，任何對受保生命沒有可保權益的保單均屬",o:["可使無效","無效","得不到保障的","正常的"],a:1,e:"根據《保險業條例》第64b條指出，任何對受保生\n命沒有可保權益的保單均屬無效的"},{c:"1.2.1(c)",s:"對個人及其配偶的可保權益保額是怎樣釐定的？",o:["夫婦總資產為上限","兩人的總保費","保額是無限的","配偶的收入"],a:2,e:"對個人及其配偶的可保權益保額是保額是無限的"},{c:"1.2.1(c)&(d)",s:"投保人對以下哪些人士沒有可保權益？",o:["負債人","債主","合伙人","配偶"],a:1,e:"如果某人欠你錢，你可就債務人(債仔)的生命購買\n壽險，保額為貸款金額另加應計利息，反而債務人\n(債仔)就債權人(債主)是沒有可保權益的"},{c:"1.2.1(c)&(f)",s:"根據《保險業條例》第64a條指出，下列哪項關係可構成可保權益？",o:["父母及其未滿18歲的子女","監護人及其未滿18歲的被監護人","丈夫及其妻子","以上各項皆是"],a:3,e:"我們都對自己的生命，以及對其配偶具有無限金額\n的，另外，在香港，根據《保險業條例》第64A條\n，未成年人（未滿18歲的人）的父母或監護人就該\n年輕人享有可保權益。這類關係是在配偶關係以外\n，唯一構成可保權益的血緣或家庭關係。以上各項\n皆正確"},{c:"1.2.1(d)",s:"就可保權益而言，按照法律要求，如要對其他人（即本身及其配偶以外的人）擁有可保\n權益， 以下那項描述是正確的？",o:["法律要求兩者之間必須存在法律上有僱傭關係","法律要求兩者之間必須存在某種血緣關係","法律要求兩者之間必須不可以存在某種財務關係","法律要求兩者之間必須存在某種財務關係"],a:3,e:"除了對自己的生命及對其配偶具有無具有無限金額\n的可保權益，並可對其他人存在某種財務關係，也\n存在有限的可保權益"},{c:"1.2.1(d)",s:"下列哪項關係構成可保權益？",o:["債務關係","合約關係","僱傭關係","以上各項皆是"],a:3,e:"可保權益亦可以用金錢來估值的權益\n。常見的例子有：債務人生命，生意合夥人及合約\n關係"},{c:"1.2.1(d)",s:"債權人對債務人具有可保權益，當中的金額限於",o:["貸款和應付及預計利息","只限於貸款金額","貸款和應付利息","貸款和預期可賺取利息"],a:2,e:"債權人對債務人具有可保權益，當中的金額限於貸\n款和應付及預計利息"},{c:"1.2.1(d)(iii)",s:"以下哪項屬於關鍵人物？",o:["自己","自己的配偶","一名重要僱員","在家族中最富有的成員"],a:2,e:"關鍵人物人壽保險又稱關鍵僱員人壽保險，僱主就\n某重要僱員的生命購買保險，以補償公司由於該僱\n員的死亡而帶來的損失。"},{c:"1.2.1(e)",s:"在美國及美洲，家庭關係本身可構成可保權益，在香港",o:["情況一樣","其中家庭成員構成可保權益只限於配偶","任何情況下均不可能","家庭成員構成可保權益是受到更多的限制"],a:3,e:"例如只有未成年人（未滿18歲的人）的父母或監護\n人就該年輕人享有可保權益。這類關係是在配偶關\n係以外，唯一構成可保權益的血緣或家庭關係。"},{c:"1.2.1(e)",s:"根據香港法例，任何人士對以下人士皆有可保權益，除了",o:["自己","自己與十七歲的配偶","自己與年屆十七歲的兒女","自己與年屆十七歲的兄弟"],a:3,e:"在香港，家庭關係。任何基於其他血緣或家庭關係\n（兄弟、姐妹、父母、子女、祖父母、孫等）所訂\n立的保險在技術上都是無效的"},{c:"1.2.1(f)",s:"在香港，有血緣關係的家庭成員不存在可保權益，根據《保險業條例》第64a條指出，唯\n一可以具有可保權益的血緣和家庭關係，下列哪項關係可構成可保權益？",o:["配偶","外祖父","債務人","子女(未成年)"],a:3,e:"在香港，未成年人（未滿18歲的人）的父母或監護\n人就該年輕人享有可保權益。這類關係是在配偶關\n係以外，唯一構成可保權益的血緣或家庭關係。任\n何基於其他血緣"},{c:"1.2.1(g)",s:"根據香港法律，如果一個人(甲)對另一個人(乙)的生命享有可保權益，而甲就乙的生命\n安排一份保險，那麼",o:["該份保單便屬無效","甲的姓名必須於該保單內註明","利益必須給付乙","該份保單必屬不分紅的"],a:1,e:"對受保生命具有權益的人、有關合約是為其使用或\n利益而訂立的人、或有關合約是為其訂立的人的名\n字必須寫在該合約中"},{c:"1.2.1(h)",s:"在人壽保險中，只有在合約開始時才需要可保權益，以下哪項情況會出現有效索償?",o:["夫妻於離婚前，為其配偶的生命購買人壽保單","債務清還前，就債務人的生命購買人壽保單","關鍵人物人壽保單，受保僱於保單起保數天後離職","以上各項例子"],a:3,e:"人壽保險的可保權益只有在合約開始時才需要，就\n以上的關係轉變，仍然維持該保單的有效性"},{c:"1.2.1(h)",s:"丈夫為其妻子的生命投保了一份整付保費壽險保單，後來妻子離世，當時雙方已離婚，\n結果",o:["丈夫只可取回已邀保費，加上利息","丈夫無權就妻子的死亡索償","丈夫只可取回已邀保費","丈夫有權就妻子的死亡索償"],a:3,e:"人壽保險的可保權益只有在合約開始時才需要，就\n以上的關係轉變，仍然維持該保單的有效性，即使\n雙方已離婚，丈夫有權就妻子的死亡索償"},{c:"1.2.1(h)",s:"丈夫為自己生命投買了一份保險，保單的受益人為其妻子。兩年後，他們離婚，但丈夫\n仍有繼續供款。後來丈夫離世，妻子可否獲得賠償？",o:["不可以，因為離婚後，妻子對丈夫的生命沒有可保權益","可以索取全部保額","可以取回已交保費","可以索取一半保額的賠償"],a:1,e:"人壽保險只有在合約開始時才需要可保權益，夫妻\n中任何一方為其配偶的生命投保後，即使離婚，仍\n可維持保單的有效性，而且完全有權在適當時候收\n取利益。"},{c:"1.2.1(h)",s:"歐先生為歐太太購買了一份整付保費壽險，三年後將保單轉讓給他們的女兒。再過兩年\n後，歐太太離世，而歐先生與歐太太經已離婚，請問根據這份保單索償時可能出現哪些\n問題？",o:["歐太太對自己具有可保權益？","歐先生什麼時候對歐太太具有可保權益？","歐太太對自己具有多少可保權益？","這份保單屬於違法嗎？"],a:1,e:"人壽保險只有在合約開始時才需要可保權益，夫妻\n中任何一方為其配偶的生命投保後，即使離婚，仍\n可維持保單的有效性，而且完全有權在適當時候收\n取利益。只要人壽保險開始生效時，他們是夫妻關\n係就可以。"},{c:"1.2.1(h)",s:"就可保權益而言，人壽保險轉讓中，承轉人",o:["可與轉讓人沒有可保權益","必須為轉讓人父母","必須為轉讓人配偶","必須為轉讓人兄弟姊妹"],a:0,e:"保單所有人可把正當地安排的人壽保險合約轉讓給\n第三者，即使該第三者對受保生命缺乏可保權益。"},{c:"1.2.1(h)(ii)",s:"法律上，可以就債務人的生命投保，在債務得到償還後，該份保險",o:["立即取消","即時支付利益","盡快變為無效","然維持保單的有效性，並在適當時候得到償付"],a:3,e:"法律上，你可就你的債務人的生命投保，在債務得\n到償還後，仍然維持該保單的有效性，並在適當時\n候「再次得到償付」。"},{c:"1.2.1(h)(iii)",s:"以下哪項有關壽險保單轉讓與可保權益法律規定的關係的陳述是正確？",o:["保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者","保單所有人一般可以將正當地安排的人壽保險合約轉讓給第三者，即使該第三者對受\n保生命缺乏可保權益","保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者","準保單所有人意圖向一受保生命購買一份壽險合約，但卻與受保生命缺乏可保權益，\n他大可以安排後者購買保單自保生命後轉讓給他，而成為轉讓保單的合法所有人"],a:1,e:"保單所有人一般可以將正當地安排的人壽保險合約\n轉讓給第三者，即使該第三者對受保生命缺乏可保\n權益仍可作出保單轉讓"},{c:"1.2.1(h)(iii)",s:"就可保權益而言，人壽保單可以在下列哪種情況下轉讓？",o:["只能轉讓予個人的配偶或雙親","只能轉讓予一名關係密切的家庭成員","只能轉讓予具有可保權益的承讓人","無論承讓人是否具有可保權益均可進行轉讓"],a:3,e:"保單所有人可把正當地安排的人壽保險合約轉讓給\n第三者，即使該第三者對受保生命缺乏可保權益。"},{c:"1.2.2",s:"以下哪項為最高誠信的正確描述？\ni. 任何人不可能被期望披露不可能知道的情況\nii.就免健康核保的申請，保險中介人必需嚴謹制定一份建議書\niii.最高誠信的原則是主動披露，並不會因投保人已獲得保險人安排合資格的醫療團隊\n的體檢而影響\niv.重要資料是在「訂定保費方面會影響一名保險人的判斷的任何情況」",o:["i, ii","i, iii","i, iii, iv","ii, iii, iv"],a:2,e:"就免體檢的投保，一份小心設計的投保單未必很重\n要，只有選項i, iii, iv正確"},{c:"1.2.2",s:"大多數人壽保單條款規定，除非有證據證實保單所有人的欺騙行為，否則，在保單生效\n了一段時間之後，保險人不會對該份保單提出異議或質疑，該條款稱為",o:["不可撤銷條款","不能作廢條款","不可異議條款","不可失效條款"],a:2,e:"在保單生效了一段時間(例如兩年)之後，保險人不\n會對該份保單提出異議或質疑，該條款稱為不可異\n議條款"},{c:"1.2.2",s:"下列哪項肯定屬於投保人必須披露的重要事實",o:["與實質物件(財產)的保險有關的事實","會影響一名審慎的保險人訂定保費或決定是否承擔風險方面判斷的事實","可能影響一名審慎的核保人就一項特定風險釐定保費的判斷的事實","被保險人向保險人披露的重要事實"],a:1,e:"重要事實是會影響一名審慎的保險人訂定保費或決\n定是否承擔風險方面判斷的事實"},{c:"1.2.2",s:"下列哪項是有關最高誠信的描述最恰當的說法",o:["必須披露保單所有人所知的事實","必須披露所有保險人要知的事實","投保人必須披露已知的所有重要事實","必須完美地披露保險人問及的所有問題"],a:2,e:"最高誠信要求投保人披露所有重要事實不管保險人\n有沒有提出要求。"},{c:"1.2.2",s:"一名男子安排免體檢保單,他無意誤導保險人其健康狀況,如果詳述其健康真相,保險人並\n不提供保單保障,其後該男子死去並真相大白,以下那項描述並不正確?",o:["不論任何時間死亡,保險人可推翻保險合約","死亡發生予保單生效2年內,保險人可推翻保險合約","死亡發生予保單生效2年後,保險人不可異議","沒有涉及欺詐,保險人不能推翻保險合約"],a:0,e:"香港的大多數壽險保單都包含了一項名為不可異議\n條款，除非有證據證實保單所有人的欺騙行為，否\n則，在保單生效了一段時間（可異議期）之後，保\n險人不會對該份保單提出異議或質疑\n，答案A不正確"},{c:"1.2.2",s:"假若保險人不把投保人正感到胃痛一事列作重要事實，其原因必定是",o:["胃痛是可以透過身體檢查發覺的","這與投保人的健康狀況沒有關係","收取附加保費就可以接受這項投保","這事實不會影響投保人決定是否接受投保或釐定保費"],a:3,e:"保險人認為投保人感到胃痛一事不會影響承保決定\n或釐定保費"},{c:"1.2.2",s:"以下哪項為最高誠信的正確描述？\ni)不期望被保人披露有理由不可能知道的情況\nii)人壽保險只要求投保人回答保險人問題時具有最高誠信\niii)免體檢的保單，投保人不用披露體檢表格內沒有問及的事情\niv)沒有欺詐而違反最高誠信，超過可異議期後可得到豁免",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],a:1,e:"最高誠信要求投保人披露所有重要事實不管保險人\n有沒有提出要求，選項ii不正確，正確答案是B"},{c:"1.2.2(b)",s:"就最高誠信原則，在免體檢的投保的前題下，以下哪項不屬違反最高誠信的情況?",o:["沒有披露未被驗出的腦瘤","沒有披露近日收到高利貸債主的死亡恐嚇","隱瞞自己從驗身得知的癌症","隱瞞自己意外導致嚴重受傷"],a:0,e:"有些疾病對合資格醫生而言可能很容易察覺，但是\n不能期望一般人也能夠進行自我診斷並作披露。"},{c:"1.2.2(b)",s:"就人壽保險而言，如果未有披露以下哪種情況，則被視為違反最高誠信?",o:["未被驗出的腦瘤","投保人的體檢醫生未能驗出投保人的心跳不正常","沒有披露投保人於兒時多次罹患輕微的兒童疾病","以上各項皆不是"],a:2,e:"就最高誠信而言，保險人希望瞭解投保人所有已知\n的重要事實"},{c:"1.2.2(d)",s:"在現行的法律及慣例下，如果需要就某一人壽保險投保單進行特殊的身體檢查，投保人\n有權知道下列哪項或哪些資料？",o:["進行什麼檢查","需要有關資料的目的","任何檢查的結果","以上所有各項"],a:3,e:"以上各項皆是投保人在進行身體檢查時有權知道的\n資料"},{c:"1.2.2(e)",s:"以下哪項為最高誠信的正確描述？\ni. 就某些不可異議條文，保險人不得在保單生效了一段時訂明時間內對該份保單提出異\n議或質疑\nii. 就免體檢的投保，一份小心設計的投保單是很重要\niii. 在不構成欺詐的情況下，若受保生命違反最高誠信在可異議期間後才可獲得寬宥\niv. 要求投保人披露所有重要事實，不管保險人有沒有提出要求",o:["ii,iii,iv","i,ii,iv","i,ii","iii,iv"],a:3,e:"就不可異議條文，保險人可以在保單生效了的兩年\n內對該份保單提出異議或質疑，就免體檢的投保，\n一份小心設計的投保單未必很重要，只有選項iii,\niv正確"},{c:"1.2.2(e)",s:"若違反人壽保險合約的最高誠信責任通常會令該合約變為可使無效。就香港的壽險保單\n而言",o:["這種情況在任何時候也適用","最高誠信的原則並不適用","違反最高誠信便會自動令該合約變為無效","保單的不可異議條款可能改變這種情況"],a:3,e:"就不可異議條文，保險人可以在保單生效了的兩年\n內對該份保單提出異議或質疑"},{c:"1.2.3",s:"賠償雙倍賠償利益保單時，確定受保人的死亡原因很重要，所以以下哪種保險原則是適\n用",o:["彌償","近因","可保權益","最高誠信"],a:1,e:"在人壽保險中，意外死亡保險利益附約(又稱雙倍\n賠償利益保單)及自殺除外責任條款適用的情況下\n，確定受保人死亡原因變得十分重要"},{c:"1.2.3",s:"若一名保單所有人在兩年前購買一份人壽保單(有分紅性質)，而事隔兩年後，他再購買\n另一份為期5年的定期壽險計劃。在半年後，該投保人身亡。若以上兩份保單仍生效的話",o:["只賠償保額較高的一份保單的保額","兩張保單全數賠償","視乎保險公司當時的決定","只賠償有分紅性質的一份"],a:1,e:"人壽保險亦稱為利益保單，人壽保險一般不受彌償\n原則所規限，一個人擁有多於一份人壽保單是很正\n常的。在受保事件發生後，每份保單都必須全額賠\n償。"},{c:"1.2.3",s:"在死亡的索償中，以下哪種或哪些原因，死因可能屬於重要事項",o:["該保單可能設有意外死亡保險利益附約","自殺條款可能仍然生效","受益人可能謀殺該受保生命","以上所有各項"],a:3,e:"在人壽保險中，除非在自殺除外責任條款或意外死\n亡保險利益附約適用的情況下，否則，死亡的原因\n並不十分重要，另外，如果證實殺人犯是受益人的\n話，法律「公共政策」是不會容許殺人犯本人獲益\n的。以上各項情況下，確定死亡原因屬重要事項"},{c:"1.2.3(a)",s:"以下哪三項有關人壽保險的近因原則的應用的描述是正確的?\ni. 不保危險不大可能是重要原則\nii. 由於所有死亡原因都受保，近因原則不適用\niii. 如果懷疑受保人自殺是死亡原因，近因原則的應用是很重要\niv. 如果雙倍賠償利益附約適用，近因原則的應用是很重要",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"如果受保生命在該免責期內(通常為保單發出後一\n年內)自殺，保險人無須支付死亡保險金，構成人\n壽保險的除外責任，所以選項(ii)不正確"},{c:"1.2.3(a)",s:"人壽保險近因原則",o:["從不適用於人壽保險","絕對適用於人壽保險","有時適用，尤其懷疑自殺的死亡原因","只有意外死亡利益附約時才適用"],a:2,e:"近因原則是確定死亡是否由自殺導致的重要工具，\n因為自殺僅於一段期限自殺免責期內構成除外責任"},{c:"1.2.3(a)",s:"近因對下列哪項不是十分重要？",o:["雙重賠償","意外","火險","快將到期的定期壽險"],a:3,e:"定期壽險於特定期間或時期提供保障，因此假若受\n保生命在特定期間內死亡，保單利益將會支付支付\n，即使快將到期的定期壽險，仍存在效性，所以與\n近因原則關係最少"},{c:"1.2.3(a)(ii)",s:"下列哪項關於彌償的陳述是正確的？",o:["除非由法律隱含，否則彌償不存在於人壽保險","法律不容許人壽保險作出彌償","不可能對喪失生命作出超額彌償","五十年前，彌償普遍存在於人壽保險"],a:2,e:"人壽保險亦稱為利益保單，不可能超額賠償，因為\n人壽保險可保權益在大多數情況下是無限的"},{c:"1.2.3(b)",s:"當發現死者就其生命購買了多於一份人壽保單，而每一份保單仍然生效，當作出賠付時",o:["只有最先購買的保單作出賠付","只有最高保額的保單作出賠付","每份保單對賠償都必須負責","應付保額為最高保額，而所有保險人分擔責任"],a:2,e:"人壽保險亦稱為利益保單，不可能超額賠償，因為\n人壽保險可保權益在大多數情況下是無限的，當作\n出賠付時每份保單對賠償都必須負責"},{c:"1.2.3(b)",s:"下列哪項對彌償的描述是正確的？",o:["除非法律顯示，否則人壽不受彌償約束","人壽保險不可能超額賠償可保生命","保險利益支付超越實際損失金額","不適用於人壽保險任何形式"],a:1,e:"人壽保險是利益保單，不可能超額賠償可保生命，\n因為人壽保險可保權益在大多數情況下是無限的"},{c:"1.2.3(b)",s:"如一名被保險人已購買了三份人壽保單，當作出賠付時",o:["須以最先購買的保單作出賠付","須以最高保額的保單作出賠付","在計算保單的責任時，須猶如沒有其餘兩份保單的存在","應付保額為最高保額，而保額則由保險人分擔"],a:2,e:"人壽保險一般不受彌償原則所規限，因此，在受保\n事件發生後，每份保單都必須全額賠償。"},{c:"1.2.3(c)",s:"下列哪項關係不具有可保權益?",o:["17歲兒女","17歲的受監護人","17歲妹妹","以上各項皆有可保權益"],a:2,e:"在香港，未成年人（未滿18歲的人）的父母或監護\n人就該年輕人享有可保權益。這類關係是在配偶關\n係以外，唯一構成可保權益的血緣或家庭關係。（\n兄弟、姐妹、父母、子女、祖父母、孫等）本身不\n可構成可保權益。"},{c:"1.2.3(c)",s:"以下哪項保險原則是彌償的引伸?",o:["代位","近因","A&B","以上皆不正確"],a:0,e:"只有代位是彌償原則的引伸"},{c:"1.2.3(c)",s:"分擔與代位權",o:["不適用於人壽保險，除非保單以彌償方式訂立","絕不適用於人壽保險","只適用於一般保險","只適用於超額賠償保單"],a:1,e:"保險收益絕不可能構成人命的精確財務補償。亦稱\n為利益保單而非彌償保單，引伸自彌償的次原則，\n分擔及代位權亦不會適用"},{c:"1.2.3(c)",s:"在人壽保險中，保險人就追討一筆賠償給付原屬被保險人向第三者提出索償權利的罕見\n情況，以上情況屬哪一項保險原則下發生?",o:["彌償","分擔","代位","可保權益"],a:2,e:"代位是彌償的引伸原則。人壽保險是利益保單，彌\n償原則不適用。"},{c:"1.2.3(c)",s:"分擔與代位權",o:["不適用於人壽保險","對人壽保險的索償很重要","其重要性在人壽保險索償與一般保險索償一致","以上所有皆是"],a:0,e:"分擔與代位權是彌償原則的引伸，不適用於人壽保\n險"},{c:"1.2.3(c)",s:"在人壽保險中，近因這個保險原則",o:["是適用的","並不適用","可能重要(當自殺免責期後自殺)","只在不可異議期內重要"],a:0,e:"近因這個保險原則是適用的所有保險類型"},{c:"1.2.3",s:"近因與不同類型的危險關係密切，而對於以下哪一項的描述是正確的？",o:["人壽保險中包含指明的受保危險","人壽保險中除外危險並不適用","人壽保險不受到不保危險的限制","各類危險於人壽保險的應用是有限的"],a:3,e:"在人壽保險中，除非在自殺除外責任條款或意外死\n亡保險利益附約適用的情況下，否則，死亡的原因\n並不十分重要，各類危險於人壽保險的應用是有限\n的"},{c:"1.2.3",s:"如果受保生命的死亡是由已證實的自殺引致",o:["只須支付一半的保額","根據保單，保險人絕對不用負責","索償的有效性視乎保單已經生效多久","保險人若支付有關索償，便屬違法"],a:2,e:"自殺只會於自殺免責期(一般為保單生效一年內)構\n成除外責任，答案C正確"},{c:"1.3.1",s:"釐定人壽保險保費的傳統標準是",o:["可負擔的","合理的","可計算的","公平的"],a:3,e:"釐定人壽保險保費的傳統標準是公平(公正)的，及\n充足的"},{c:"1.3.1",s:"釐定人壽保險保費的傳統標準中，其中一項標準是「公正」的，其意味著",o:["保證保費是市場上最優惠的","繳納的保費對保單所有人而言是不偏不倚的","保費低至保單所有人可以支付的","以上各項皆是"],a:1,e:"公平公正的釐定人壽保險保費，即是每位保單所有\n人繳納的保費須反映有關的風險及約定利益"},{c:"1.3.1",s:"按照壽險傳統保費計算方法，保費應該可應付所有有關成本，並可反映有關之風險，描\n述有關之保費標準為",o:["公平及公正的","公平及足夠的","充足及公平（公正）的","充足及合適的"],a:2,e:"按照壽險傳統保費計算方法有關之保費標準為充足\n及公平（公正）的"},{c:"1.3.1",s:"釐定人壽保險保費的傳統標準中，包括「公平」一項，其意思是",o:["提供最平宜的保費","反映有關的風險及約定利益","年紀愈小愈要負擔高的保費","維護保險公司利益"],a:1,e:"釐定人壽保險保費的傳統標準中「公平」一項，其\n意思是保費應該能公平地反映有關的風險及約定利\n益"},{c:"1.3.1a",s:"以下哪項不是用以計算壽險保費考慮的因素?",o:["死亡率","開支","利息","性別"],a:3,e:"性別不是用以計算壽險保費考慮的因素"},{c:"1.3.1a",s:"以下哪項關於死亡表的描述是正確的?\ni. 顯示不同年齡的預期死亡比率的計算表\nii. 應付所有預期及可能出現的營運開支\niii. 考慮某種新疾病或其他災難引起異常死亡率的可能性\niv. 只應付正常風險和正常預期的死亡率",o:["i, iii","i,iv","ii,iv","以上各項皆是"],a:1,e:"死亡表或稱生命表顯示不同年齡的預期死亡比率的\n計算表，在保險行業中十分通用。利用死亡表釐定\n費率，只是應付正常風險和正常預期。所以只有選\n項i及iv是正確"},{c:"1.3.1a",s:"人壽保單中的毛保費等於淨保費加附加保費，哪麼淨保費即是",o:["利息而已","死亡率而已","死亡率及開支","死亡率加利息"],a:3,e:"淨保費即是包括死亡率加利息"},{c:"1.3.1a",s:"在人壽保險保費的一般計算中，在正常統計預期下足夠支付死亡索償所需，向保單所有\n人收取的金額是以下哪一種保費",o:["實收保費","淨保費（純保險費）","毛保費","充足及公平的保費"],a:1,e:"在正常統計預期下足夠支付死亡索償所需向保單所\n有人收取的金額是淨保費（又叫純保險費）"},{c:"1.3.1a",s:"用以計算壽險保費的三大因素為死亡率，開支及",o:["保險人利潤","目前投資利率","預期利息收入","淨邊際利潤"],a:2,e:"用以計算壽險保費的三大因素為死亡率，開支及利\n息(預期利息收入)"},{c:"1.3.1a",s:"用以計算壽險保費的三大因素為死亡率，開支及",o:["利息","性別","年齡","居住的國家"],a:0,e:"用以計算壽險保費的三大因素為死亡率，開支及息"},{c:"1.3.1a",s:"釐定壽險保單保費的其中一個標準是其應當是「充足的」，在這大前提下，這意味著保\n費應該是",o:["不高於所需要的金額","有能力與市場上的保費率競爭的","是以為保險人提供利潤","足夠支付保險金及履行合約中的其他責任"],a:3,e:"釐定壽險保單保費的其中一個標準是其應當是「充\n足的」，意味著保費應該是足夠支付保險金及履行\n合約中的其他責任"},{c:"1.3.1a(b)",s:"一般計算人壽保險保費的三大因素是死亡率、開支及",o:["保險人的利潤","目前投資率","預期利息所得","淨邊際利潤"],a:2,e:"一般計算人壽保險保費的三大因素是死亡率、開支\n及利息所得"},{c:"1.3.1a(c)",s:"在人壽保險中，淨保費加開支後的總保費稱為",o:["最後的保費","毛保費","公平的保費","純保險費"],a:1,e:"在人壽保險中，淨保費加開支後的總保費稱為毛保\n費"},{c:"1.3.1a",s:"用以計算壽險「毛保費」的因素，哪項加上附加保費後組成？",o:["淨保費","利息","開支及死亡率","利息、開支及死亡率"],a:0,e:"當淨保費加上附加保費就成為了毛保費，答案A正\n確"},{c:"1.3.1a",s:"淨保費(純保險費)包括",o:["利息而已","死亡率而已","死亡率及利息","利息，死亡率及開支"],a:2,e:"淨保費(純保險費)包括死亡率及利息"},{c:"1.3.1b",s:"影響保費的計算是死亡率、利息、開支及",o:["保單的分紅/不分紅","保險公司目標","經濟變化","以上所有各項"],a:3,e:"以上所有各項都是影響保費的計算其他因素"},{c:"1.3.1b(a)",s:"英式「有利潤」的壽險保單不獲「紅利」取而代之，它們往往將英式紅利附加於保單應\n付的保額，並於到期時一併支付，這種英式紅利稱為？",o:["延期紅利","未來現金","復歸紅利","非即時紅利"],a:2,e:"英式紅利又稱為復歸紅利"},{c:"1.3.1b",s:"採用英國式慣例的保險人，稱意義與分紅保單相同的保單為",o:["公平保單","有利潤保單","賺取利潤保單","賺取紅利保單"],a:1,e:"採用英國式慣例的保險人稱意義與分紅保單相同的\n保單為有利潤保單，英式紅利通常是復歸的，即只\n於支付保單利益時一起支付"},{c:"1.3.1b",s:"在香港的分紅人壽保險單通常跟隨美國方式派發紅利(dividend)，在英式的人壽保險中\n，與紅利相近的用語為",o:["利潤 (profit)","英式紅利 (bonus)","可分配盈餘 (divisible surplus)","利潤分紅 (profit participation)"],a:1,e:"英國保險人簽發的有利潤保單，與紅利相近的用語\n為英式紅利"},{c:"1.3.1b",s:"在英式慣例的保險產品中，有利潤保單通常會支付「期末紅利」。下列哪項陳述有關「\n期末紅利」是正確的？",o:["等於現金紅利","可即時支付","在退保時才可支付","在支付保險金時才可支付"],a:3,e:"採用英國式慣例的保險人稱意義與分紅保單相同的\n保單為有利潤保單，英式紅利通常是復歸的，即只\n於支付保單利益時一起支付"},{c:"1.3.2(a)",s:"以下哪項不是影響保費率的主要因素？",o:["死亡率","利息","開支","發病率"],a:3,e:"發病率是影響保費率的其他因素"},{c:"1.3.2(b)",s:"以下哪一項不是均衡保費制度的特點？",o:["經過初期的年數，保單會累積一個現金退保價值","保費(根據相同的死亡利益不會每年增加","保費會按照被保險人到達之年齡而增加","較早的保單保費高於死亡風險所需要的金額"],a:2,e:"自然保費（釐定）制度下，保費才會按照被保險人\n到達之年齡而增加"},{c:"1.3.2a",s:"下列哪項屬於自然保費制度的特點？",o:["保費隨年齡增長而增加","會產生逆選擇","大部份保險公司已不採用","以上各項皆正確"],a:3,e:"以上各項都屬於自然保費制度的特點"},{c:"1.3.2a",s:"保單有效期內保費並非固定，而是於每個保單週年日獨立計算，此保費制度稱為",o:["自然保費釐定制度","均衡保費釐定制度","平均保費釐定制度","遞增保費釐定制度"],a:0,e:"保單有效期內保費並非固定，而是於每個保單週年\n日獨立計算，此保費制度稱為自然保費釐定制度"},{c:"1.3.2a",s:"以下哪項就自然保費釐定制度的描述不正確?",o:["保險人已不再使用自然保費制度","該制度會出現不利於保險人的逆選擇","保費會隨年齡增長而增加","以上各項皆不是"],a:3,e:"以上各項都是自然保費釐定制度的正確的描述，所\n以答案D正確"},{c:"1.3.2a",s:"下列哪項不是自然保費制度的特性？",o:["隨著年齡的增長增加保費","對保險人有不利影響","續保時，對保單所有人帶來實際問題","隨著年齡的增長而減少保費"],a:3,e:"自然保費制度的特性是隨著受保人的年齡的增長而\n增加保費"},{c:"1.3.2b",s:"以下哪一項是均衡保費（釐定）制度對保單的短期後果?\ni.保單有效期內保費並非固定，而是於每個保單週年日\n獨立計算，以準確反映在每個續保期內受保生命的自然風險（例如年齡等）\nii.早年保費相對風險而言可能「太高」而晚年保費相對風險而言則可能「太低」\niii.吸收了最初設立該保單時的各項有關開支及成本，早年的「超額」保費上其利息收\n入將形成一個儲備 ，以應付未來的責任\niv.均衡保費制度考慮到壽險屬於長期合約，不變的年保費實際上會在整個受保期內有效\n地達致平均",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii, iii, iv"],a:3,e:"保單有效期內保費並非固定，而是於每個保單週年\n日獨立計算，屬自然保費制度，選項(i)不正確"},{c:"1.3.2b&c(ii)",s:"可作為保單抵押貸款的抵押物是",o:["銀行中的存款","保單的現金價值","保單所有人所持有的財產","以上各項都是"],a:1,e:"可作為保單抵押貸款的抵押物是保單的現金價值"},{c:"1.3.2b(a)",s:"人壽保險費率的均衡保費制度是指在保險期內，每年所繳的保費相同， 並假設",o:["利率沒有大幅度下降","死亡保險金維持不變","經濟環境保持合理平穩","保險人的賠償經驗仍可接受的"],a:1,e:"人壽保險費率的均衡保費制度是指在保險期內，保\n費不變，同時死亡保險金亦維持不變。"},{c:"1.3.2b(c)",s:"一名已持有一份終身壽險多年被保險保單所有人，因被裁員而失去工作，現想終止保單\n。保險人/代理人應",o:["解釋不能作廢條款","解釋清繳保險","提議利用保單抵押貸款，以解燃眉之急","解釋以上各項並協助他作出抉擇"],a:3,e:"以上皆是均衡保費制度下由早期「盈餘」保費而產\n生的特性，保單所有人可以在以上各項作出選擇"},{c:"1.3.2b(c)",s:"以下哪些是由均衡保費直接或間接產生？\ni) 現金價值\nii) 保單貸款\niii) 不能作廢條款\niv) 清繳保險",o:["i, ii","ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上各項都是均衡保費制度下直接或間接產生的後\n果"},{c:"1.3.2b(iv)",s:"一份完全清繳保單通常是指︰",o:["所有過往到期的保費已付清","保費由第三者(例如顧主)支付","保單一經生效便必須支付所有保費","無須再繳付未來的保費，而保單仍可維持有效"],a:3,e:"清繳保險即是以現金價值作為整付保費，利用淨現\n金價值作為整付保費，購買與原保單所提供的計劃\n相同但保額較低的人壽保險，於無須再繳付未來的\n保費下，保單仍可維持有效"},{c:"1.3.2c",s:"下列哪項可以歸因保單於均衡保費釐定制度下多繳的「剩餘」保費?\ni. 現金價值\nii. 保單抵押貸款\niii. 清繳保險\niv. 不能作廢條文",o:["i, ii, iii","ii, iii, iv","i,ii,iv","i,ii,iii,iv"],a:3,e:"以上皆是均衡保費釐定制度下多繳的「剩餘」保費\n導致的長期後果"},{c:"2(a)",s:"我們預期人壽保險的基本形式或保障不會出現以下哪項?",o:["只就指定時期內發生的死亡支付保險利益","就任何時候發生的死亡都支付保險利益","就指明的疾病導致的死亡給付保險利益","在某一特定日期 或 在那日期前發生的死亡支付保險利益"],a:2,e:"就指明的疾病導致的死亡給付保險利益不是預期人\n壽保險的基本形式"},{c:"2(a)",s:"下列哪一項較不可能出現於人壽保險合約的基本形式功能範圍？",o:["為特定時間內發生死亡給付死亡金","為指定時期內發生死亡給付死亡金","為特定原因內發生死亡給付死亡金","於某一特定日子或以前發生死亡給付死亡金"],a:2,e:"人壽保險合約一般不會為特定原因發生的死亡給付\n死亡金"},{c:"2(a)",s:"下列哪項保險產品的索償是無可避免的？\ni) 定期壽險\nii) 儲蓄壽險\niii) 終身壽險\niv) 團體壽險",o:["i, ii","ii, iii","i, iii","i, ii, iii, iv"],a:1,e:"儲蓄壽險可以現期滿，及死亡索償，終身壽險保障\n受保生命任何時候身故，所以都屬索償是無可避免\n的保險產品"},{c:"2(a)&(b)",s:"以下哪項並不屬於人壽保險的變化？",o:["分享保險人的利潤","保單所有人有權選擇轉換另一個不同的 計劃","保險公司解散時，可以分享其剩餘資產","加入各種附加條款附約，即批單"],a:2,e:"分享其剩餘資產不屬於人壽保險的變化"},{c:"2(b)",s:"普通壽險保單的基本變數可以是以下哪幾項?\ni. 普通保單可轉化為保證保單\nii. 最初只保障有限期間的壽險單可以續保\niii.保單所有人可以選擇將保單紅利轉換為公司股份\niv.可在保單中加入附加條款以獲取更多保障",o:["i, ii","iii, iv","i, ii, iv","ii, iv"],a:3,e:"可續保的及在基本保單中加入各種附加條款附約\n是人壽保險的基本變數"},{c:"2(b)",s:"下列哪項屬於基本形式之壽險保單的常見變化？\ni)保單所有人可以選擇將保單紅利轉換為公司股份\nii)如果最初只投保一段有限時間，可能可以續保\niii)保單所有人可以選擇將保單紅利轉換為公司優先股\niv)保單可加入各種附約，用以改善所提供的保障",o:["i, ii","iii, iv","ii, iv","i, ii, iii, iv"],a:2,e:"可續保的及在基本保單中加入各種附加條款附約\n是人壽保險的基本變數"},{c:"2(b)",s:"保單中可加入甚麼以提供額外保障或某些附帶條件？",o:["附加保費","附加條款(附約)","額外購買另一份保單","以上各項皆不是"],a:1,e:"保單中可加入附加條款(附約)，以提供額外保障或\n某些附帶條件"},{c:"2(b)",s:"早期的基本壽險就死亡賠付一筆金額，當中這些基本計劃是可以存在變化的，這些是",o:["可參與及分享保險人的利潤","按保單持有人的選擇，轉換為另一類計劃的可轉換性","加以附約(批單)，以增加保障範圍","以上所有各項"],a:3,e:"可轉換及可續保等都是基本壽險可以存在變化"},{c:"2(b)(i)",s:"有一類的定期壽險的保單，容許保單所有人將保障更改為永久計劃，該類型的保單稱爲?",o:["可轉換的","可改變的","非永久的","可轉讓的"],a:0,e:"定期壽險的保單，容許保單所有人將保障更改為永\n久計劃，該類型的保單稱爲可轉換的"},{c:"2(c)",s:"向保單所有人提供意見時，保險中介人清晰地詢問向客戶能夠並且願意支付多少保費。\n對於一個負責及聲譽好的保險中介人來說，還會關注到問題是",o:["該保單的佣金率是多少","客人希望購買壽險能夠做些甚麽","朋友及其家屬是否有興趣買保險","客戶承諾在保單生效的首年不會提早終止保單"],a:1,e:"客人希望購買壽險能夠做些甚麽，對保險中介人來\n說是另一個值得關注的問題"},{c:"2(c)",s:"保險銷售過程中，以下哪一條問題常會由保險中介人去回答?",o:["你希望壽險為你做些甚麽?","你能夠並且願意支付多少保費?","你需要多少人壽保險保障?","家庭現有多少人壽保險保障?"],a:2,e:"需要多少人壽保險保障常會由保險中介人去回答"},{c:"2(c)",s:"在安排人壽保險保障的過程中，保險中介人必須向潛在保單所有人提出兩個基本問題，\n第一個是要釐定該名人士能夠負擔多少保費，第二個則是",o:["釐定向中介人繳付的最低佣金","詢問投保人屬已婚或單身","詢問是否按每年或每月繳付保費","詢問購買該份壽險的目的"],a:3,e:"詢問購買該份壽險的目的保險中介人必須向潛在保\n單所有人通常提出問題"},{c:"2.1",s:"以下哪三項壽險最有可能設有及提供退保現金價值?\ni) 定期壽險\nii) 儲蓄壽險\niii) 「分紅」終身壽險\niv) 「不分紅」終身壽險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii ,iii, iv"],a:3,e:"定期壽險沒有現金價值的，所以選項i不正確"},{c:"2.1",s:"如果對人壽保險有短暫的需求，所需的財務金額在該段時期都不會增加或減少，並且該\n需求會在指明的期間後便消失，就以保險成本為一重要的考慮因素，以下哪一項不太適\n合?",o:["定額定期壽險","非儲蓄定期壽險","分紅終身壽險","非分紅終身壽險"],a:2,e:"終身壽險的保費比定期壽險高，而分紅計劃的保費\n亦比非分紅計劃高，以保險成本為一重要的考慮因\n素，分紅終身壽險最不適合"},{c:"2.1.1",s:"定期壽險保單的利益，只於死亡時候保單仍屬有效及以下哪種情況下才給付？",o:["被保險人在整個保險期內仍然生存","被保險人患上危疾","於指明保單期限內死亡","於指明保單期限之後死亡"],a:2,e:"定期壽險保單的利益，只於死亡時候保單仍屬有效\n及於指明保單期限內死亡情況下才給付"},{c:"2.1.1",s:"下列哪項有關定期壽險的陳述是正確的？",o:["索償是無可避免的","在大多數情況下，定期壽保險期仍沒有出現索償下屆滿","最少存在10年保險期","保單往往被保險人取消，並退回保費"],a:1,e:"定期壽險保障期短，在大多數情況下，定期壽保險\n期仍沒有出現索償下屆滿"},{c:"2.1.1",s:"下列哪項有關定期壽險的陳述是正確的？",o:["索償是無可避免的","在大多數情況下，定期壽險到期時仍沒有出現索償","長達很久的保險期","保單往往被保險人取消，並退回保費"],a:1,e:"定期壽險因為保障期短，在大多數情況下，定期壽\n險到期時仍沒有出現索償"},{c:"2.1.1",s:"下列哪項有關定期壽險的陳述是錯誤的？",o:["只會就於指明的保險期內死亡之索償作出理賠","一般而言，這是一種最便宜的人壽保險","只會就因意外導致死亡索償作出理賠","大部份定期保險保單均會在沒有賠償的情況下到期"],a:2,e:"定期壽險於受保生命在指定保險期內死亡，就可就\n死亡索償作出理賠"},{c:"2.1.1",s:"假設該保單持續有效或生效，所有壽險保單均不能避免索償的出現，除了以下哪項？",o:["定期壽險","儲蓄壽險","分紅終身壽險","不分紅終身壽險"],a:0,e:"定期壽險因為保障期短，在大多數情況下，定期壽\n險到期時仍沒有出現索償"},{c:"2.1.1",s:"定期壽險的另一名稱為",o:["短期人壽保險","有條件保險","可終於人壽保險","期限保險"],a:0,e:"定期壽險的另一名稱為:短期人壽保險"},{c:"2.1.1",s:"就人壽保險而言,「短期保險」更一般地被稱為?",o:["定期壽險","儲蓄壽險","可轉換的壽險","暫時性的壽險"],a:0,e:"就人壽保險而言,「短期保險」更一般地被稱為定\n期壽險"},{c:"2.1.1",s:"傳統的壽險產品中，以下哪項不包括有現金價值的?",o:["定期壽險","終身壽險","不分紅儲蓄壽險","分紅儲蓄壽險"],a:0,e:"定期壽險沒有現金價值的"},{c:"2.1.1",s:"定期壽險保單的利益，只於死亡時候保單仍屬有效時情況，以下哪種或哪些情況下才給\n付？",o:["被保險人在整個保險期內仍然生存","被保險人患上危疾","於指明保單期限內死亡","於指明保單期限之後死亡"],a:2,e:"定期壽保單利益只限於受保生命在特定期間或時期\n內死亡；及死亡發生時保單是有效的。"},{c:"2.1.1",s:"以下哪種保險最不大可能索償？",o:["定期壽險","終身壽險","儲蓄壽險","純生存保險"],a:0,e:"在大多數情況下，定期壽險計劃到期時仍沒有出現\n索償。"},{c:"2.1.1",s:"根據定期人壽保險的有效索償是需要符合以下哪些或哪項？",o:["可保權益在保障生效時已經存在","在死亡發生時，保單仍然生效","死亡在指定時間內發生","以上各項皆是"],a:3,e:"以上各項皆是定期人壽保險的有效索償是需要符合\n的條件"},{c:"2.1.1",s:"假設有一項對壽險之要求為於某段期間內須提供一項不多也不少的保障額，而低保險費\n用為首要要求，以下哪項最為適用？",o:["儲蓄壽險","定期壽險","分紅終身壽險","不分紅終身壽險"],a:1,e:"定期壽險是保費最便宜，在整個保險期內，死亡保\n險金均維持定額不變"},{c:"2.1.1",s:"以下哪項屬於儲蓄壽險合約的特點？",o:["於香港十分普遍","儲蓄壽險是不分紅的","它包含一項重大的儲蓄成份","只會於保單期滿時仍然生存才支付保額"],a:2,e:"儲蓄壽險合約它包含一項重大的儲蓄成份，並有機\n會出現死亡或期滿索償"},{c:"2.1.1",s:"以下哪項不屬於儲蓄壽險合約的特點？",o:["保險於指明期限過後便告期滿","保單可以是分紅的或不分紅的","它包含一項重大的儲蓄成份","只會於保單期滿時仍然生存才支付保額"],a:3,e:"受保生命在該期間內死亡，或者保險期限期滿後受\n保生命還活着的話，則即時給付保額"},{c:"2.1.1&1.3.2b(c)",s:"以下哪項定期壽險的描述不正確？",o:["通常不具有分紅成份","不大可能具有現金價值","好似終身壽險，是純保障產品","它是最便宜的人壽計劃"],a:2,e:"定期壽險保單的利益，只於死亡時候保單仍屬有效\n及於指明保單期限內死亡情況下才給付"},{c:"2.1.1&2.1.2",s:"以下哪一項是定期壽險及儲蓄壽險的主要分別?",o:["儲蓄壽險的保費較定期壽險為低","儲蓄壽險的保險利益申索較定期壽險容易","定期壽險續保需提供可保性證明，儲蓄壽險就沒有這項規定","儲蓄壽險提供期滿時給付保額，而定期壽險則沒有"],a:3,e:"只有儲蓄壽險提供期滿時給付保額，而定期壽險則\n沒有"},{c:"2.1.1(b)",s:"定期壽險保險期最短為",o:["1年","10年","20年","30年"],a:0,e:"定期壽險保險期最短為1年"},{c:"2.1.1a",s:"作為一種定期壽險，定額定期壽險",o:["以分紅形式簽發","於指定數目的學期內支付學費","是一種非常有效的儲蓄工具","受保生命在保險期內死亡，才可以獲得按保單的保額支付的保險利益"],a:3,e:"定額定期壽險是沒有現金價值，固定的死亡保險金\n額，並不會分紅形式簽發，只有選項iv是正確"},{c:"2.1.1a",s:"以下哪項有關遞減定期壽險的描述是不正確？",o:["這是定期壽險其中一種變化","現有人壽保險種類中最便宜的","適合於逐漸減少的短暫保障需求","支付的利益按保單持有人的實際需要而變化"],a:3,e:"支付的利益按保單持有人的實際需要而變化，不是\n遞減定期壽險的描述"},{c:"2.1.1a",s:"遞減定期壽險尤其適合",o:["支付遺產稅","個人退休生活支出","以分期方式償還的抵押貸款","以上各項皆是"],a:2,e:"遞減定期壽險尤其適合遂漸減少的保險需求，例如\n以分期方式償還的抵押貸款"},{c:"2.1.1a",s:"相比於終身壽險及儲蓄壽險，以下哪項有關定期壽險的描述是正確的？",o:["保費是最便宜的","大多數情況下，在保單到期時仍未出現索償","只提供短暫的保障","上述所有各項"],a:3,e:"上述所有各項都是定期壽險的正確的描述"},{c:"2.1.1a",s:"以下哪項屬於儲蓄壽險的不正確描述 :\ni 它可以建立在分紅／不分紅的基礎上\nii 它有退保現金價值\niii 它必須於期滿才可索償（例如 20 年）\niv 保額隨著受保生命何時離去有所不同",o:["i 及 ii","ii 及 iii","i 及 ii","iii 及 iv"],a:3,e:"儲蓄壽險可以建立在分紅／不分紅的基礎上，及有\n退保現金價值，只有選項iii,iv是不正確描述。"},{c:"2.1.1a",s:"以下哪一項是定額定期壽險的受保事件?",o:["保險期限屆滿後受保生命仍然生存","受保生命在指定保險期內死亡","受保生命任何時間死亡","以上各項皆不正確"],a:1,e:"定額定期壽險，只有受保生命在指定保險期內死亡\n才可就死亡索償作出理賠"},{c:"2.1.1a",s:"下列哪項不屬於遞減定期壽險的典型應用例子?",o:["信用壽險","家庭收入壽險","萬用壽險","抵押贖回壽險"],a:2,e:"萬用壽險不屬於遞減定期壽險的典型應用例子"},{c:"2.1.1a",s:"如果對於人壽保險有短暫的需求，而所需求的財務金額於有關期內不會增加或減少，該\n需求亦會該段指明期限告終後便告消失，那麼最經濟的壽險保障形式應是",o:["定額定期壽險","遞減定期壽險","分紅儲蓄壽險","不分紅儲蓄壽險"],a:0,e:"定額定期壽險保費比儲蓄壽險低，但遞減定期壽險\n保額會隨時間而減少，所以最經濟的壽險保障形式\n，而且維持保不變保額應是定額定期壽險。"},{c:"2.1.1a",s:"定額定期壽險最適合以下哪個情況？",o:["被保險人的退休儲備","作為指定年齡後的年金","一份沒有以分期形式償還的貸款","為到期時而繳交的學費"],a:2,e:"如果受保生命在保險期內死亡，定額定期壽險可以\n獲得按保單的保額支付的保險利益。適合例如：一\n項不以分期付款形式償還的 貸款"},{c:"2.1.1a",s:"有一種保單，它就指定有效期內出現的死亡給付利益，並為該保單每年相同的利益設定\n相同的保費，這種保單稱為",o:["終身壽險","定額定期壽險","固定限期壽險","不變動定期壽險"],a:1,e:"只在指定有效期內出現的死亡給付利益並設定相同\n的保費，屬於定額定期壽險"},{c:"2.1.1a",s:"以下哪種保險種類是為借款人在未完全償還欠款之前死亡，直接向投保人支付保險欠款\n？",o:["儲蓄壽險","信用壽險","萬用壽險","抵押贖回壽險"],a:1,e:"信用壽險是為借款人在未完全償還欠款之前死亡，\n直接向投保人支付保險欠款，屬遞減定期壽險其中\n一種"},{c:"2.1.1a",s:"下列哪三項屬於遞減定期壽險的典型例子？\ni) 信用壽險\nii) 家庭收入壽險\niii) 萬用壽險\niv) 抵押贖回壽險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"萬用壽險不屬於遞減定期壽險，選項iii不正確"},{c:"2.1.1a",s:"以下哪項是定期壽險的類別?\ni) 定額定期壽險\nii) 遞增定期籌險\niii) 可轉換定期壽險\niv) 遞減定期壽險",o:["i, ii, iv","i, iii, iv","ii, iii, iv","i,ii, iii, iv"],a:0,e:"可轉換定期壽險不屬定期壽險的類別，只屬定期壽\n險的變化"},{c:"2.1.1a",s:"遞減定期壽險尤其適合",o:["一項逐漸減少的短期需要","一項逐漸增加的短期需要","一項保費維持不變的短期需要","以上各項皆不適合"],a:0,e:"遞減定期壽險尤其適合一項逐漸減少的短期需要"},{c:"2.1.1a",s:"遞減定期壽險適合應付以下哪個或哪些情況？",o:["以分期方式償還的抵押貸款","以5年分期方式支付的租賃合約","若雙親早逝的學費負擔","符合以上所有各項"],a:3,e:"符合以上所有各項都屬遞減定期壽險適合應付的情\n況"},{c:"2.1.1a",s:"遞減定期壽險指",o:["利益每年遞減","保險費每年遞減","利益與保險費每年遞減","付給代理人的佣金每年遞減"],a:0,e:"遞減定期壽險指計劃，死亡保險金按年或其他特定\n周期遞減。在整個保險期內，年保費的水平通常維\n持不變。"},{c:"2.1.1a",s:"當受保人去世時，賠償會直接向貸款人償還貸款餘額，這是什麼類型的保險？",o:["遞增定期壽險","信用壽險","家庭收入壽險","抵押贖回壽險"],a:1,e:"如果借款人在未完全償還欠款之前死亡，信用壽險\n直接向貸款人支付貸款結欠"},{c:"2.1.1a(a)",s:"下列哪項或哪些有關定額定期壽險的陳述是正確的？",o:["有關年度保費在保單期內通常固定不變","有關利益的水平在保單期內維持不變","這類保單通常不會按分紅形式簽發","以上所有各項"],a:3,e:"以上所有各項都是定額定期壽險的正確陳述"},{c:"2.1.1a(a)",s:"下列哪項有關定額定期壽險的陳述是不正確的？",o:["它是人壽定期保險種類中保費最便宜的","有關年度保費在保險期內通常固定不變","有關利益的水平在保險期內維持不變","通常不會按分紅形式簽發"],a:0,e:"遞減定期壽險才是保險種類中保費最便宜的"},{c:"2.1.1a(b)",s:"以下哪類保險的特色是保險額可按需求而遞減的？\ni 信用壽險\nii 遞減定期壽險\niii 抵押贖回保險\niv 家庭收入壽險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上皆是遞減定期壽險的種類，滿足逐漸減少的短\n暫保障需求。"},{c:"2.1.1a(b)",s:"某人供錢購買一個住宅單位。根據貸款的安排，他於十年內每年支付利息及部份本金，\n十年後便可還清該筆貸款。他打算購買最便宜的人壽保險計劃，以確保假如他在該十年\n內死亡的時候，便可由保險金支付貸款結欠。這種保險形式可能是",o:["終身壽險","定額定期壽險","儲蓄壽險","遞減定期壽險"],a:3,e:"遞減定期壽險指計劃，死亡保險金按年或其他特定\n周期遞減。它特別適合於逐漸減少的短暫保障需求\n。一些典型實例包括抵押贖回保險，目的是提供一\n筆與一項抵押貸款的遞減結欠相符的死亡保險"},{c:"2.1.1a(b)",s:"以下哪項有關遞減定期壽險的描述是不正確？",o:["年保費逐年遞減","現有人壽保險種類中最便宜的","適合於逐漸減少的短暫保障需求","死亡保險金按年或其他特定周期遞減"],a:0,e:"遞減定期壽險是保額隨時遞減，而不是保費逐年遞\n減"},{c:"2.1.1a(b)",s:"遞減定期壽險適合應付以下哪個或哪些情況？",o:["繳付遺產稅","為個人作退休資本","清繳抵押貸款的結欠","以上所有各項皆是"],a:2,e:"清繳抵押貸款的結欠時，貸款餘額會隨時間減少，\n遞減定期壽險最適合應付這類需求"},{c:"2.1.1a(b)",s:"以下哪類壽險，也許是與其他提供一筆過賠償的保單相結合的，而賠償時是按月支付保\n險利益的？",o:["信用壽險","家庭收入壽險","抵押贖回壽險","儲蓄壽險"],a:1,e:"家庭收入計劃也許會與其他於死亡時提供一筆過付\n款的保單計劃互相結合的。承諾在指定期限的剩餘\n部分內，每月向受益人支付指定金額的死亡保險金"},{c:"2.1.1a(b)",s:"以下哪項描述抵押贖回保險是不正確的？",o:["保障形式與按揭賠償保險相同","可以聯名(例如：夫婦)形式為基礎","用來繳付未清還的貸款結欠","保障形式是為個人而設，並非銀行及貸款給銀行"],a:0,e:"按揭賠償保險並不屬遞減定期壽險，與抵押贖回保\n險不相同"},{c:"2.1.1a(b)",s:"遞減定期壽險是因為",o:["所繳保費隨時間減少","所需給付保險金額隨時間減少","客戶所需繳付的年期不斷減少","給予保險中介人的佣金每年遞減"],a:1,e:"遞減定期壽險保額會隨時間而減少"},{c:"2.1.1a(b)",s:"丈夫和妻子以聯名形式購買了抵押贖回保險保單，丈夫不幸去世後，賠償金會給付",o:["妻子","銀行","他們的子女","貸款機構"],a:0,e:"以聯合壽險方式提供保障的壽險保單承保兩人夫婦\n兩人的生命， 不論哪一位最先或最後死亡\n，保單於此 時支付保險利益。"},{c:"2.1.1a(b)(ii)",s:"一種也許會與其他壽險於死亡時提供一筆死亡利益的計劃互相結合，還在指明期間的剩\n餘時間每月支付利益，這種壽險產品稱為",o:["家庭收入壽險","萬用壽險","抵押贖回壽險","遞減定期壽險"],a:0,e:"家庭收入壽險是一種也許會與其他壽險於死亡時提\n供一筆死亡利益的計劃互相結合，還在指明期間的\n剩餘時間每月支付利益，屬於其中一種遞減定期壽\n險"},{c:"2.1.1a(b)(iii)",s:"以下哪項正確描述抵押贖回保險?\ni) 保障形式與抵押賠償保險是相同的\nii) 可以夫婦聯名形式為基礎\niii)用來補償死亡時未繳付的貸款餘額\niv) 保障額按月遂步增加",o:["i","i,ii","i,iv","ii,iii"],a:3,e:"抵押贖回保險是一種遞減定期保險，目的是提供一\n筆與一項抵押貸款的遞減結欠相符的死亡保險金，\n開始時的保額和其後的遞減額，是在投保時按照償\n還的計劃而設定的。這樣的計劃可以用聯合壽險方\n式訂立，例如夫婦。"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言，以下哪項的說明是不正確？",o:["保險利益和保費按年或其他認可方式隨時間遞增","保費可按某百分比增加，也可按某個約定指數","不適用於殘疾收入附加保障利益","遞增定期壽險的目的是要抵銷通貨膨脹"],a:2,e:"就遞增定期壽險尤其適用於殘疾收入附加保障利益"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言，以下哪項的描述是正確的？",o:["這是一項目的為抵銷通貨膨脹的條款","保險利益和保費按年或其他協訂方式隨時間遞增","保費按所保利益水平的增加的比例增加","以上各項皆正確"],a:3,e:"以上各項皆是遞增定期壽險的正確描述"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言，以下哪項的說明是不正確？",o:["保險利益和保費按年或其他認可方式隨時間遞增","保費可按某百分比增加，也可按某個約定指數","續保時需要提供良好的健康証明，保額才可以增加","遞增定期壽險的目的是要抵銷通貨膨脹"],a:2,e:"遞增定期壽險所保的死亡保險金按年或按其他相隔\n期間遞增，可以按固定百分比增加，或按某個約定\n的指數，例如：綜合消費物價指數增加，答案C不\n正確"},{c:"2.1.1a(c)",s:"哪三項是遞增定期壽險的正確陳述：\ni)有關保費與利益水平一致遞增\nii)有關利益按年或其協定方法遞增\niii)保費的保險金額均保持不變，保險期限遞增\niv)本意是要讓利益與貨幣價格保持一致",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"遞增定期壽險的保費通常按所保利益水平的增加的\n比例增加，保險期限,不會遞增，選項iii不正確"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言",o:["保險利益和保費按年或其他認可方式隨時間遞增","保險利益遞增，保費不變","保費遞增，保險利益不變","只有當保單所有人提出要求時才遞增保費或保額"],a:0,e:"就遞增定期壽險保險利益和保費按年或其他認可方\n式隨時間遞增"},{c:"2.1.1b",s:"就可續保定期壽險而言，以下哪一個說法不正確?",o:["保費將會隨受保生命的年齡的增長而增加","新保費是按照到達年齡來計算","續保的權利已存在毋須提交可保性證明","以上各項皆不是"],a:3,e:"因為以上各項皆是可續保定期壽險的正確描述，所\n以答案D是正確答案。"},{c:"2.1.1b(a)",s:"下列哪項對於可續保定期壽險的描述是正確的?\ni. 在續保時，其保費增加以反映其年齡之提高\nii. 在續保時，其保額只可相同或小於其原有保障額\niii. 於續保時，無須提供可保性證明\niv. 只有保險期不少於一年的定期壽險才可續保",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:0,e:"只要是可續定期壽險就可提供續保機會，與保險期\n無關"},{c:"2.1.1b(a)",s:"以下哪項或哪些是可續保定期壽險可能涉及防止逆選擇的方法？",o:["不接受續保時高於原來的保額","可能限制允許的續保次數","保險費率可能高於不可續保保單的費率","以上各項皆是"],a:3,e:"以上各項皆是可續保定期壽險可能涉及防止逆選擇\n的方法"},{c:"2.1.1b(a)",s:"下列哪項對於可續保定期壽險的描述是正確的?",o:["在續保時,其保費增加以反映其年齡之提高","在續保時,其保額只可相同或小於其原有保障額","於續保時,無須提供可保性證明","以上所列各項"],a:3,e:"以上各項皆是可續保定期壽險可續保定期壽險的正\n確描述"},{c:"2.1.1b(b)",s:"可轉換定期壽險可能會導致逆選擇. 下列哪項是為防止逆選擇而設置的限制?\ni. 超過某一年齡(例如55 歲)之後,可能不准轉換\nii. 新計劃(長期保險)保額必須高於目前保單\niii.保單實施若干年後,不可轉換\niv. 新計劃(長期保險)保額不得高於目前保單",o:["i,ii","i,ii, iii","i,iii, iv","ii,iii,iv"],a:2,e:"可轉換定期壽險新計劃保額不可以高於目前保單，\n選項ii不正確"},{c:"2.1.1b(b)",s:"可轉換定期壽險可能會設置某些限制。但是，下列哪一項並不包括其中",o:["超過某年齡後，不允許轉換","轉換時一般需要可保性證明","就計劃保額的上限不能高於原有計劃","只有在所述年期內才允許轉換"],a:1,e:"可轉換定期壽險給保單所有人提供一個轉換特權，\n在毋須提供可保性健康證明的情況下，將保單轉換\n為永久計劃的權利，但轉換的保額不可高於原有保\n額，否則就需提供可保性證明"},{c:"2.1.1b(b)",s:"人壽保險中可轉換的特權，是將保單轉換為永久計劃，而永久計劃的保費",o:["與原有的保險保費相同","以受保生命的原本年齡的保費率計算","以受保生命的到達年齡的保費率計算","按同類保險計劃的標準保費率及一種指明的特定折扣計算"],a:2,e:"人壽保險中可轉換的特權，是將保單轉換為永久計\n劃，而永久計劃的保費以受保生命的到達年齡的保\n費率計算"},{c:"2.1.1b(b)",s:"人壽保險中賦予保單所有人權利，在毋須提供可保性證明的情況下，將保單改變為永久\n計劃，這稱為",o:["可轉換","可續保","可轉讓","非永久"],a:0,e:"人壽保險中賦予保單所有人權利，在毋須提供可保\n性證明的情況下，將保單改變為永久計劃，這稱為\n可轉換。"},{c:"2.1.1b(b)",s:"駱先生大學畢業不久，沒多少錢可以用於買人壽保險，然而將於明年結婚。為什麼你認\n為他應該考慮購買可轉換定期壽險？",o:["可轉換定期壽險的保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情\n況下把保單轉為永久計劃","可轉換定期壽險給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單轉換\n為更便宜的計劃","可轉換定期壽險保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情況\n下把保單轉換為聯合壽險計劃","對年不過三十的人來說，可轉換定期壽險最適合不過"],a:0,e:"可轉換定期壽險保單所有人提供一個轉換特權，在\n毋須提供可保性健康證明的情況下將保單轉換為永\n久計劃的權利"},{c:"2.1.1b(b)",s:"如果一般人壽保險中標明「可轉換的」則表示",o:["保單可隨時被保險人結束","保險人可更改為另一種計劃","保單持有人可更改為另一種計劃","保單持有人可自由選擇以那一種貨幣繳費"],a:2,e:"可轉換定期壽險保單所有人提供一個轉換特權，在\n毋須提供可保性健康證明的情況下將保單轉換為永\n久計劃的權利"},{c:"2.1.2",s:"以下哪項儲蓄壽險的特點？",o:["保費比較不貴","只有儲蓄成份","以儲蓄為主","以上各項皆正確"],a:2,e:"儲蓄壽險的特點是以儲蓄為主"},{c:"2.1.2",s:"儲蓄壽險並不便宜，以下哪項是正確的描述",o:["索償不一定出現","索償只會在保單期滿時出現","索償會在保單期滿時或之前出現","索償會在保單期滿前出現及期滿後再次出現"],a:2,e:"儲蓄壽險並不便宜，索償會在保單期滿時或之前，\n即受保命在該期間內死亡時出現"},{c:"2.1.2",s:"下列哪類索償只出現於儲蓄壽險?",o:["死亡索償","期滿索償","退保索償","以上各項皆是"],a:1,e:"期滿索償只出現於儲蓄壽險"},{c:"2.1.2",s:"黃先生希望他的兒子在20年後得到最大的保險利益.若不考慮保費的因素,以下哪項可提\n供最大的利益予其兒子?",o:["定期壽險","終身壽險","儲蓄壽險","分紅儲蓄壽險"],a:3,e:"儲蓄壽險可指定於20年後取得期滿保險利益，分紅\n儲蓄壽險，分紅儲蓄壽險可提供最大的利益予其兒\n子"},{c:"2.1.2",s:"如果保單所有人同是受保人,以下哪項壽險他最有可能且期待索償的?",o:["定期壽險","儲蓄壽險","分紅終身壽險","不分紅終身壽險"],a:1,e:"儲蓄壽險索償會在保單期滿時或之前，即受保命在\n該期間內死亡時出現"},{c:"2.1.2",s:"儲蓄壽險的概念是指純生存保險加上",o:["定期壽險","終生壽險","家居保險","商業保險"],a:0,e:"儲蓄壽險的概念是指純生存保險加上定期壽險"},{c:"2.1.2",s:"儲蓄壽險並不便宜，以下哪項是正確的描述：\ni) 它可以是分紅或不分紅\nii) 它亦稱純生存保險\niii) 保單利益在期滿前或期滿時支付\niv) 一般情況，保費供款至期滿",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"儲蓄壽險是定期壽險及純生存保險的結合，並不是\n儲蓄壽險的別稱"},{c:"2.1.2",s:"純生存保險是一種有別於普通形式的人壽保險，唯一可以得到利益的要求是受保人",o:["在意外中逝世","在保險期間內仍然生存","是一位在保險期限內去世的兒童","在保險期滿時仍是一項可保因素"],a:1,e:"純生存保險是一種只在受保生命在保險期結束時仍\n然生存的情況下，才支付死亡保險金的合約"},{c:"2.1.2",s:"就儲蓄保險而言，下列哪三項是正確的？\ni) 死亡時才會支付保額\nii) 保單可以是分紅或不分紅\niii) 保額於保單期滿或早逝時支付\niv) 保單利益可向受保生命本人支付",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii, iii , iv"],a:3,e:"儲蓄壽險索償會在保單期滿時或之前，即受保命在\n該期間內死亡時出現，選項i不正確"},{c:"2.1.2",s:"以下哪項產品，受保生命自行取回保險利益是正常的？",o:["儲蓄壽險","定額定期壽險","遞減定期壽險","終身壽險"],a:0,e:"儲蓄壽險可以出現期滿索償，受保生命自行取回保\n險利益是正常的"},{c:"2.1.2",s:"在二十年的儲蓄壽險裏，若受保人士在第十年不久之後逝世，賠償會",o:["面額的50%","全數保額一次過即時支付","在十年後才支付","在意外死亡後才支付"],a:1,e:"儲蓄壽險承諾於受保生命活到指定期間結束時給付\n保額，但萬一受保生命在該期間內死亡，則即時給\n付保額"},{c:"2.1.2(b)",s:"一份罕見人壽保險產品，這產品只有在受保生命在保障期間結束時仍然生存才支付保險\n利益，這份壽險是",o:["儲蓄壽險","定期壽險","延期年金","純生存保險"],a:3,e:"純生存保險一份罕見人壽保險產品，這產品只有在\n受保生命在保障期間結束時仍然生存才支付保險利\n益"},{c:"2.1.2(d)",s:"儲蓄壽險在香港並不流行，你認為原因何在？",o:["佣金率比較低","對於投保的普羅大眾，這種壽險一般較難了解","它比較貴","其實儲蓄壽險比定期壽險和終身壽險更流行"],a:2,e:"儲蓄壽險在香港並不流行，因為保費較貴，這是跟\n實務知識不相同。"},{c:"2.1.2(d)",s:"儲蓄壽險並不便宜，以下哪項是正確的描述",o:["索償只會在保單期滿時出現","索償會在保單期滿時或之前出現","索償會在受保人早逝時，或保單期滿時出現","索償不一定出現"],a:2,e:"儲蓄壽險的索償會在受保人早逝時，或保單期滿時\n出現"},{c:"2.1.2a",s:"當其他條件相同，最便宜的現有人壽保險種類是",o:["定額定期壽險","遞減定期壽險","儲蓄壽險","儲蓄壽險"],a:1,e:"當其他條件相同，最便宜的現有人壽保險種類是遞\n減定期壽險"},{c:"2.1.3",s:"如果對人壽保險有短暫需求，而需求的財務金額在該相關期間內不會增加或減少，而需\n求會在指定期限內便會告終結，以保險成本為一項重的考慮原因，以下哪一項是最不可\n取的壽險保障方式?",o:["定額定期壽險","可轉換定額定期壽險","分紅終身壽險","不分紅終身壽險"],a:2,e:"終身壽險保費比定期壽險高，分紅保單保費又比不\n分紅保單為高，以保險成本為一項重的考慮原因，\n分紅終身壽險最最不可取"},{c:"2.1.3",s:"關於終身壽險，下述哪三項不正確?\ni) 可支付的死亡保險金每年遞減\nii)只有在受保生命去世時，才可支付死亡保險金\niii)只有經過固定年數之後，才可支付死亡保險金\niv)經過固定年數或者早逝的時候，便支付死亡保險金",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"終身壽險於受保生命任何時候去世是便會即支付保\n額。只有選項ii是正確描述。選項i,iii,iv是終身\n壽險不正確的描述"},{c:"2.1.3",s:"以下哪項或哪些就終身壽險的描述不正確?\ni. 保單不可以是分紅形式\nii. 保單保額按特定周期逐漸減少\niii. 保單可以在保險期內終身繳付保費\niv. 保單利益限於受保生命在特定期間或時期內死亡情況下支付",o:["i,ii","i,ii,iv","i,iii,iv","i,ii,iii,iv"],a:1,e:"只有選項iii是終身壽險正確的描述，選項i,ii,iv\n都不正確"},{c:"2.1.3",s:"某人欲於身故後捐出一筆不多及不少於100萬元給予其母校，您會建議他以最少的保費購\n買哪類保險呢？",o:["分紅儲蓄壽險","不分紅儲蓄壽險","分紅終身壽險","不分紅終身壽險"],a:3,e:"不分紅終身壽險的死亡保險利益是固定的，不管受\n保生命\n何時去世，保單將會於此時支付保額，答案D是正\n確"},{c:"2.1.3",s:"以下哪項不是終身壽險的繳付保費方法？",o:["終身繳付","按指定年數","指定年齡前繳付","可按年遞減保費"],a:3,e:"可按年遞減保費不是終身壽險的繳付保費方法"},{c:"2.1.3",s:"一名有意購買一份人壽的準保單持有人，希望有關保險在自己逝世時提供一筆不超過事\n前聲明的金額，而該筆金錢的用途並不會在投保人逝世前出現，而保險成本並非為重要\n考慮因素。以下哪保險類型可以獲得最高的收益?",o:["定額定期壽險","終身壽險","分紅儲蓄壽險","非分紅儲蓄壽險"],a:1,e:"終身壽險其基本特性是，不管受保生命何時去世，\n保單將會於此時支付保額，該種類型可以獲得最高\n的收益"},{c:"2.1.3",s:"下列哪項或哪些是一份由保單所有人維持有效的終身壽險的特點？",o:["索償遲早都會出現","該份保單可能會維持有效達數十年之久","該份保單應可取得一個退保價值","以上所有各項"],a:3,e:"以上所有各項皆是終身壽險的特點"},{c:"2.1.3",s:"終身壽險的特點為",o:["只對指定時期內的死亡支付賠償","任何時候受保生命去世,即支付保額","在某一特定日期前死亡支付賠償","保險人按月支付補償給投保人"],a:1,e:"終身壽險於受保生命任何時候去世是便會即支付保\n額"},{c:"2.1.3",s:"下列哪項或哪些關於終身壽險保單的陳述是正確的?",o:["保單不可能建立在有分紅的基礎上","有時需終身繳付保費","保費可以繳付到一定年齡，到時侯保單便期滿","以上所有各項"],a:1,e:"終身壽險須終身繳付保費，保單可以稱為純粹壽險\n單，或 連續繳費終身壽險單"},{c:"2.1.3",s:"一名有意購買一份人壽的準保單持有人，希望有關保險在自己逝世時提供一筆不超過事\n前聲明的金額，而該筆金錢的用途並不會在投保人逝世前出現，以下哪種最合適情況",o:["定期保險","延期年金","終身壽險","分紅儲蓄壽險"],a:2,e:"終身壽險其基本特性是，不管受保生命何時去世，\n保單將會於此時支付保額，，終身壽險最合適這種\n情況"},{c:"2.1.3",s:"如一份沒有指明期限，而且只能在受保人死亡時才支付保額的保單是",o:["定期壽險","終身壽險","儲蓄壽險","純生存保險"],a:1,e:"終身壽險於受保生命任何時候去世是便會即支付保\n額"},{c:"2.1.3",s:"以下哪項不大可能是終身壽險保費的各種變化？",o:["終身繳付保費","於限定期間內支付","於指定年數之後，停止繳付","保單生效時，以一筆過方式支付"],a:3,e:"終身壽險保費是維持於固定水平的，但可根據不同\n條款而定，包括須終身繳付保費，於限定期間內繳\n付保費，或繳付保費到達某個指定年齡，答案D不\n正確"},{c:"2.1.3",s:"一份不分紅終身壽險",o:["只會於指定期間結束時才給付保單利益","就不論甚麼時間出現的死亡，均會給付保額","於受保生命仍然在世期間給付指定的利益","只會就指定期間內出現的死亡給付保單利益"],a:1,e:"一份不分紅終身壽險就不論甚麼時間出現的死亡，\n均會給付保額"},{c:"2.1.3",s:"以下哪項或哪些關於終身壽險的描述是不正確的？\ni 保額按年不斷減少\nii 保單不可選擇分紅成份\niii 保單可終身繳付保費\niv 只可在合理時限內死亡才支付保險利益",o:["i, ii","i, iii","i, ii, iv","i, ii, iii, iv"],a:2,e:"保單可終身繳付保費，可選擇分紅或不分紅，終身\n壽險於受保生命任何時候去世是便會即支付保額。\n只有選項iii是正確描述。選項i,ii,iv是終身壽險\n不正確的描述"},{c:"2.1.3(a)",s:"終身壽險的保費可以下列哪種或哪些形式繳交",o:["在達致一定年齡後便無須再繳交","只須在一指定年數內繳交","於受保生命仍然在世的整段期間繳交","視乎情況，可以採用上述任何一種形式繳交"],a:3,e:"以下都是終身壽險的保費繳交方法"},{c:"2.1.3(a)",s:"以下哪項不是終身壽險的繳付保費方法？",o:["終身繳付","按指定年數","指定年齡前繳付","保險人低息貸款支付保費"],a:3,e:"保險人低息貸款支付保費不是終身壽險的繳付保費\n方法"},{c:"2.1.3(a)",s:"有一種終生壽險於投保人在生時一直繳付保費直至死亡，這種保單稱為連續繳費終生壽\n險保單或",o:["純粹壽險","永久終生壽險","連續終生壽險","不固定保費保險"],a:0,e:"有一種終生壽險於投保人在生時一直繳付保費直至\n死亡，這種保單稱為連續繳費終生壽險保單或純粹\n壽險"},{c:"2.1.3(a)",s:"一份人壽保險單如稱為「連續繳費終身壽險單」，則意味著",o:["受保人只需繳付一份保費","在保險期內保費不變","在限定期間受保人在去世後，仍需繳付保費","受保人須終身繳付保費"],a:3,e:"純粹壽險是指受保生命在世期間終身繳付保費，亦\n可稱為「連續繳費終身壽險單，亦是終身壽險的別\n稱，"},{c:"2.1.3(a)(i)",s:"一份人壽保險保單被描述為連續繳費終身壽險，意味著",o:["只需在保單開始時，繳付一份保費","整段保險期間，保費固定不變","受保生命仍然在生的時間内，需要終身繳付保費","受保人需在一定期限内繳付保費，受保生命已經死亡也一樣"],a:2,e:"終身壽險，又稱連續繳費終身壽險，受保生命仍然\n在生的時間内，需要終身繳付保費"},{c:"2.1.3(a)(i)",s:"純粹壽險是指",o:["保單不適用附約或其他保障","保額在意外死亡時才支付","受保生命在世期間終身繳付保費","受保生命被評估為可按標準保費及屬標準風險"],a:2,e:"純粹壽險是指受保生命在世期間終身繳付保費，亦\n是終身壽險的別稱"},{c:"2.1.3(c)",s:"有一種終身壽險的變化，容許保費按一定的規律(例如每三年增加)，而面值則維持不變\n，這終身壽險是",o:["等級保費保險","等級終身壽險","分級終身壽險","遞增終身壽險"],a:0,e:"終身壽其中一種的變化是等級保費保險"},{c:"2.1.3(c)",s:"有一種壽險名為等級保費保險，容許保費按一定規律(例如每三年增加)，而保額則",o:["按一定規律調整","每三年向下調整","每三年向上調整","維持不變"],a:3,e:"有一種壽險名為等級保費保險，容許保費按一定規\n律(例如每三年增加)，而保額則維持不變"},{c:"2.1.3(c)",s:"人壽保險中的等級保費保險是指",o:["保費會按指定周期定期增加","保費應反映不正常風險而增加","有關的中介人有權取得特殊的佣金率","保額定期增加"],a:0,e:"有一種壽險名為等級保費保險，容許保費按一定規\n律增加，而保額則維持不變"},{c:"2.2.1",s:"萬用壽險的年報會送交",o:["保險監管局","有關保單所有人","保險人的董事局","香港金融管理局"],a:1,e:"萬用壽險的年報會送交有關保單所有人"},{c:"2.2.1",s:"下列哪項不屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","披露因營運開支而徵收的附加保費","在無須可保性證明情況下，調整的保單利益"],a:3,e:"萬用壽險就任何增加保險利益的情況都可能須要提\n供可保性證明"},{c:"2.2.1",s:"以下哪項屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","「分別列示各定價因素」","以上各項皆是"],a:3,e:"以上皆是萬用壽險的特點"},{c:"2.2.1",s:"有一種壽險保單，設有靈活保費，並且被保人可選擇一種以保額加上現金價值作為死亡\n保險金或單單以保額作為死亡保險金，這種壽險稱為",o:["終身壽險","儲蓄壽險","萬用壽險","遞減定期壽險"],a:2,e:"這種壽險稱為萬用壽險"},{c:"2.2.1",s:"下列哪項屬萬用壽險的特點？\ni. 年報會給保單所有人\nii. 死亡保險金不可以增加或減少\niii. 死亡保險金可以增加或減少\niv. 保險成本會分別獨立地列示出來",o:["ii, iv","i,ii,iii","i,iii,iv","ii,iii,iv"],a:2,e:"萬用壽險的死亡保險金可以增加或減少，選項ii不\n正確，正確描述只有i,iii,iv"},{c:"2.2.1",s:"下列哪項或哪些不屬於萬用壽險的特點？",o:["它具有可調整的保險利益","它從不累積現金價值","靈活的保費","上述所有各項都不屬於萬用壽險的特點"],a:1,e:"萬用壽險是具有累積的現金價值"},{c:"2.2.1",s:"下列哪項關於萬用壽險的陳述是不正確的?",o:["具有分別列示各定價因素的定價","保費靈活,可以於某一年完全不繳付保險費","一種非常複雜的產品,它為保單所有人提供極大的自由度","無須要提供可保性證明,可要求增加或減少保險利益"],a:3,e:"萬用壽險就任何增加保險利益的情況都可能須要提\n供可保性證明"},{c:"2.2.1",s:"萬用壽險的保單所有人，每年均會收到一份說明保單狀況的年報，內容不包括",o:["選定的死亡保險金選擇","已加入現金價值的保證利息及額外利息","已扣除的保險純成本","基金價格"],a:3,e:"萬用壽險的保單所有人，每年均會收到一份說明保\n單狀況的年報，內容不包括基金價格"},{c:"2.2.1(a)",s:"具靈活保費，可調整利益，分別列示各定價單位的定價結構等特點的壽險，是以下哪一\n種?",o:["年金","儲蓄壽險","定額定期壽險","萬用壽險"],a:3,e:"具靈活保費，可調整利益，分別列示各定價單位的\n定價結構等特點的壽險，屬萬用壽險"},{c:"2.2.1(a)",s:"以下哪項不屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","披露因營運開支而徵收的附加保費","自動按年增加的保額"],a:3,e:"萬用壽險不會自動按年增加的保額"},{c:"2.2.1(b)",s:"萬用壽險增加或減少保額",o:["必需提交可保性證明","如增加保額，需提供可保性證明","如減少保額，需提供可保性證明","如增加保額後第二年後提出索償，該次索償則屬無效"],a:1,e:"萬用壽險如增加保額，需提供可保性證明"},{c:"2.2.1(b)",s:"以下哪項正確描述萬用壽險?",o:["當保額向上調整時須提交可保性証明","無論何時都無須提交可保性証明","當保額向下調整時須提繳可保性証明","當保額向上或向下調整時須提交可保性証明"],a:0,e:"萬用壽險當保額向上調整時須提交可保性証明"},{c:"2.2.1(c)",s:"在萬用壽險的年報中，分別獨立地向保單持有人披露三個主要的定價方式(即保障的純成\n本，投資收益，公司開支)這特點稱為",o:["透明度","最高誠信","「分別列示各定價因素」","分項開列項目"],a:2,e:"萬用壽險具有「分別列示各定價因素」的定價結構\n，在萬用壽險的年報中，分別獨立地向保單持有人\n披露三個主要的定價方式(即保障的純成本，投資\n收益，公司開支)"},{c:"2.2.1(e)",s:"有一種保單，可用保額加現金價值作為死亡金或單單以保額作為死亡金計劃，這保單可\n以是",o:["儲蓄壽險","終身壽險","萬用壽險","遞減定期壽險"],a:2,e:"萬用壽險可用保額加現金價值作為死亡金或單單以\n保額作為死亡金計劃"},{c:"2.2.1(f)",s:"萬用壽險的保單所有人每年均會收到一份年報，下列哪項是年報內的資料？",o:["選定死亡金選擇","指定的有效保額","已加入現金價值的保證以及額外的利息","以上各項皆是"],a:3,e:"以上各項皆是萬用壽險的保單所有人每年均會收到\n的內列示的資料"},{c:"2.2.2",s:"以下哪項是單位相連保單的不正確描述?",o:["它可以與股票基金掛勾","全部或部份保費用以購買基金單位","它只可以與定期壽險或儲蓄壽險相連","保單價值會隨投資表現而變動"],a:2,e:"單位相連保單理論上是可以跟所有保險險種相連，\n最常見的是與定期壽險或儲蓄壽險相連"},{c:"2.2.2",s:"以下哪一項是「投資相連長期保單」的正確描述?",o:["總是有最低保單價值保證","保單的價值從不會隨所掛鈎的基金單位的價值變動而波動","保單的價值會隨所掛鈎的基金單位的價值變動而波動","以上都不正確"],a:2,e:"投資相連長期保單並沒有最低保單價值保證，保單\n的價值會隨所掛鈎的基金單位的價值變動而波動"},{c:"2.2.2",s:"單位相連長期保單的保單價值，可與人壽保險人經營的特殊單位化基金的單位正式掛鈎\n，或與",o:["除此以外，並無它法","任何指數表現掛勾","單位信託的單位掛鈎","與美元匯率掛勾"],a:2,e:"單位相連長期保單的保單價值，可與人壽保險人經\n營的特殊單位化基金的單位正式掛鈎，或與單位信\n託的單位掛鈎"},{c:"2.2.2",s:"以下哪項不適用於投資相連保險？",o:["部分或全部保費用於購買基金","普遍地應用於終身壽險或儲蓄壽險","總是在退休時以一整筆款項償還","有關基金包括股票或定期利息投資"],a:2,e:"投資相連保險的保單價值與單位信託基金的資産的\n價值而波動，沒有保證的保單價值，不可保證在退\n休時以一整筆款項償還"},{c:"2.2.2",s:"就本質上屬於投資形式的壽險產品而言,其中最值得注意的一點,就是要確保消費者明白\n下列哪項或哪些?",o:["必須盡早繳付保費","保單價值可升亦可跌","保險人必然保証最低的投資回報","上述所有各項"],a:1,e:"單位相連長期保單/投資相連長期保單的價值與組\n成基金或單位信託基金的資産的價值有直接關連。\n因為這相連，保單價值很自然會隨着這些資產的總\n值的移動而波動，保單價值可升亦可跌"},{c:"2.2.2",s:"保單的價值將因此隨所掛鈎的基金單位的價值變動而波動是指",o:["單位相連長期保單","分紅保單","非供款團體保單","與投資掛鈎保單"],a:0,e:"單位相連長期保單/投資相連長期保單的價值將因\n此隨所掛鈎的基金單位的價值變動而波動"},{c:"2.2.2",s:"(投資)相連保單通常指人壽保險與有關保險人經營的特殊單位化基金的單位掛鈎及",o:["單位信託的單位掛鈎","恒生指數掛鈎","上市公司股票掛鈎","美元掛鈎"],a:0,e:"(投資)相連保單通常指人壽保險與有關保險人經營\n的特殊單位化基金的單位掛鈎及單位信託的單位掛\n鈎"},{c:"2.2.2",s:"以下哪項是單位相連長期保單的基礎？",o:["保費與單位基金表現掛鈎","保額與單位基金表現掛鈎","保單價值與單位基金表現掛鈎","保額是單位的基本"],a:2,e:"單位相連長期保單的保單價值與單位基金表現掛鈎"},{c:"2.2.2(a)",s:"下列哪項是單位相連保單的說明是不正確？",o:["有關單位須與股票基金掛鈎","全部或部份保費用作購買基金單位","有關保險人必須保證最低的單位價格","保單的投資回報與基金的表現掛鈎"],a:2,e:"單位相連長期保單/投資相連長期保單的價值將因\n此隨所掛鈎的基金單位的價值變動而波動，保險人\n不會保證最低的單位價格"},{c:"2.2.2(a)",s:"下列哪項是單位相連保單的說明是正確？",o:["保單的投資回報與基金的表現掛鈎","主要涉及終身壽險及儲蓄壽險","有關投資可以與股票及固定利息投資掛鈎","以上各項皆是"],a:3,e:"以上各項皆是單位相連保單正確陳述"},{c:"2.2.2(a)",s:"下列哪項是單位相連保單的共同原則？",o:["有關保單通常有分紅成分","有關單位須與股票基金掛鈎","有關保險人必須保證最低的單位價格","全部或部份保費用作購買基金單位"],a:3,e:"單位相連保單的共同原則是全部或部份保費用作購\n買基金單位，沒有保證最低的單位價格及與分紅無\n關"},{c:"2.2.2(c)",s:"絕大部分的單位相連保單是終身壽險和下列哪種",o:["定期壽險","儲蓄壽險","純生存壽險","遞減定期壽險"],a:1,e:"絕大部分的單位相連保單是終身壽險和儲蓄壽險"},{c:"2.3",s:"年金利益款項給付予?",o:["收款人","保單受益人","保單持有人","年金購買人"],a:0,e:"年金利益款項給付予收款人"},{c:"2.3",s:"以下哪項對年金的描述是正確的？",o:["女性不可以購買年金","女性的保費比相同情況下的男性保費為低","向男性支付年金金額低於向女性支付的年金金額","向女性支付年金金額低於向男性支付的年金金額"],a:3,e:"因為女性的預期壽命比同齡男性長，所以向女性支\n付年金金額低於向男性支付的年金金額"},{c:"2.3(a)",s:"一種由人壽保險公司提供的合約，涉及向保險人作出一筆過的付款﹝或一連串付款﹞，\n以換取在他/她餘下有生之年內，定期取得款項。這種合約稱為",o:["年金","儲蓄壽險","分紅保險","不分紅保險"],a:0,e:"涉及向保險人作出一筆過的付款﹝或一連串付款﹞\n，以換取在他/她餘下有生之年內，定期取得款項\n。這種合約稱為年金合約"},{c:"2.3(a)",s:"週期性地領取年金的人士稱為",o:["收款人","年金購買人","年金持有人","保單所有人"],a:0,e:"週期性地領取年金的人士稱為收款人"},{c:"2.3(b)",s:"為已退休人士按月或其他周期領取收入，直至去世的產品稱為",o:["終身支付年金","退休金","儲蓄壽險","公積金"],a:1,e:"為已退休人士按月或其他周期領取收入，直至去世\n的產品稱為退休金"},{c:"2.3.1",s:"合資格延期年金保費及強積金可扣稅自願性供款合計可享的扣除金額是",o:["3萬","5萬","6萬","8萬"],a:2,e:"合資格延期年金保費及強積金可扣稅自願性供款合\n計可享的扣除金額是6萬"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額\n增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"延期年金計劃在累積期內，保單持有人在一段時間\n內定期繳付保費，讓保險人通過投資令已付金額增\n長"},{c:"2.3.1",s:"以下哪項不是年金合約的常見變化?",o:["在退休時以一整筆金額支付利益","保證在指定年數內支付利益款項","由即期開始支付利益款項直到年金標的人逝世","延期至指明日期支付利益款項"],a:0,e:"年金合約不會在退休時以一整筆金額支付利益"},{c:"2.3.1",s:"以下哪項為年金的正確描述?\ni.年金利益付款開始時的年齡越高,每一期年金利益付款便越高\nii. 年金核保與傳統人壽保險核保完全不同\niii.男性收取的定期年金高於相同年齡的女性\niv. 相同年齡男性的保費低於女性",o:["i,ii","ii, iii","i,ii,iii","i,ii,iii ,iv"],a:3,e:"以上各項皆是年金的正確描述"},{c:"2.3.1(a)",s:"香港的年金計劃是",o:["延期終身年金計劃","退休延期終身年金計劃","即期終身年金計劃","以上皆不是"],a:2,e:"香港的年金計劃是即期終身年金計劃"},{c:"2.3.1(a)",s:"香港的年金計劃是",o:["延期終身年金計劃","退休延期終身年金計劃","經稅務局批准的即期終身年金計劃","以上皆不是"],a:3,e:"香港的年金計劃是即期終身年金計劃，以上皆不正\n確"},{c:"2.3.1(a)",s:"香港年金計劃是",o:["延期終身年金計劃","退休人士即期終身年金計劃","退休人士延期終身年金計劃","以上皆不是"],a:3,e:"香港的年金計劃是即期終身年金計劃，以上皆不是\n香港年金計劃的歸類"},{c:"2.3.1(a)",s:"香港年金計劃是由哪機構推出的？",o:["香港金融有限公司","香港年金有限公司","香港按揭中心","香港金融中心"],a:1,e:"香港年金計劃是由香港年金有限公司推出的"},{c:"2.3.1(a)",s:"以下哪一項是「香港年金計劃」申請人可選擇支付的最高整付保費金額?",o:["港幣100萬","港幣200萬","港幣300萬","港幣500萬"],a:2,e:"「香港年金計劃」申請人可選擇支付的最高整付保\n費金額為港幣300萬"},{c:"2.3.1(a)",s:"一種以整付方式購入，並且於一個年金期間屆滿後便開始支付年金利益款項的年金合約\n稱為；",o:["即時年金","特快年金","即期年金","連續年金"],a:2,e:"即期年金是一種以整付方式購入，並且於一個年金\n期間屆滿後便開始支付年金利益款項的年金合約"},{c:"2.3.1(a)(b)(iv)",s:"香港年金計劃容許保單持有人可於保證期內，申請提取特別款項以支付以下哪一項開支?",o:["按揭支出","醫療或牙科開支","稅務貸款","葬禮費用"],a:1,e:"香港年金計劃容許保單持有人可於保證期內，申請\n提取特別款項以支付醫療或牙科開支"},{c:"2.3.1(b)",s:"根據《合資格延期年金保單指引》（指引19），以下哪一項是的合資格延期年金保設計\n特點?\ni. 年金保費 的總額 不得少於 $180,000 ，最短保費 繳付期為 5年\nii. 最短 年金期不得少於 10年\niii. 年金款項須定期向年金領取人支付，最低限度為每半年一次\niv. 年金 期 最早由 年金領取人年滿 50歲開始",o:["i,ii","i,ii,iv","iii,iv","i,iii"],a:1,e:"參考章節2.3.1(b)合 資格延期年金保單年金款項須\n定期向年金領取人支付，最低限度為每年一次"},{c:"2.3.1(b)",s:"合資格延期年金保費容許夫婦合共申請扣除總額上限是多少?",o:["60000","80000","120000","200000"],a:2,e:"合資格延期年金保費容許夫婦合共申請扣除總額上\n限是12萬"},{c:"2.3.1(b)",s:"以下哪一項是香港年金的特色?",o:["最高保證年金總額","最低保證年金總額","最高年金總額","最低年金總額"],a:1,e:"香港年金的其中一項特色是提供最低保證年金總額"},{c:"2.3.1(b)",s:"保險人須在課稅年度（ 即 3月 31日）結束後的\n____天內，向保單持有人就其每張保單各別發出合資格延期年金保單的年度摘要。",o:["40","30","50","45"],a:0,e:"保險人須在課稅年度結束後的40天內，向保單持有\n人就其每張保單各別發出合資格延期年金保單的年\n度摘要。"},{c:"2.3.1(c)",s:"被描述為「確定期間終身年金」與下列哪項相關？",o:["確定年金","延期年金","即期年金","保證年金"],a:3,e:"「確定期間終身年金」又稱保證年金"},{c:"2.3.1(d)",s:"以下哪項是年金的核保特色?\ni. 女性收取的定期年金高於相同年齡的男性\nii. 年金核保以生存率為基礎\niii. 年金核保須要驗身報告\niv. 年金利益付款開始時的年齡越高，毎一期年金利益付款便越高",o:["i,ii","ii,iv","i,ii,iii","i,iii,iv"],a:1,e:"因為女性預期壽命比男性長，女性所收取的定期年\n金低於相同年齡的男性，年金核保並無提及必須要\n提供驗身報告"},{c:"2.3.1(d)",s:"以下哪項是年金的描述是正確的?\ni. 年金利益付款開始時的年齡越高，毎一期年金利益付款便越高\nii.在相同年齡下男性收取的定期年金高於相同年齡的女性\nii. 相同年齡下，女性的年金保費高於男性\niii. 人壽保險與年金核保原則有頗大分別",o:["i,ii","ii, iii","ii,iii,iv","i,ii,iii ,iv"],a:3,e:"以上各項皆是年金的正確描述"},{c:"2.3.1(d)",s:"下列哪項是對「年金核保」與「人壽保險核保」的正確描述？",o:["年金與人壽保險核保相同","年金與人壽保險核保完全不同","就男性方面不同；而女性則相同","就女性方面不同；而男性則相同"],a:1,e:"「年金核保」以生存率為基礎，「人壽保險核保」\n是以死亡率為基礎，是完全不相同的"},{c:"2.3.1",s:"以下哪項不是年金的變化?",o:["年金利益於年金購買後的第一個年金期，如一個月完結時開始支付","於規定年期內定期支付年金利益，不論年金標的人在此期間內是否已死亡","於退休時一整筆支付年金利益","如果年金標的人在年金期完結後還活着，年金更會終身支付利益"],a:2,e:"根據年金合約，保險人承諾「年金標的人\n」生前或一約定期限內向「收款人」週期性地支付\n一連串款項稱為「年金利益款項」，年金利益不會\n以整付形式支付的。"},{c:"2.3.1b",s:"根據《合資格延期年金保單指引》，合資格延期年金保費的總額不得少於",o:["100000","150000","180000","200000"],a:2,e:"合資格延期年金保費的總額不得少於18萬元"},{c:"2.3.2",s:"有一種於退休或指明時間給僱員一筆過款項的安排,需要僱主供款,僱員有時亦可供款,這\n安排是",o:["延期年金","保證年金","供款退休金","公積金計劃"],a:3,e:"有一種於退休或指明時間給僱員一筆過款項的安排\n,這安排是公積金計劃"},{c:"2.4",s:"團體保險保單又稱為",o:["綜合團體保險合約","總團體保險合約","主要員工保險合約","總保險合約"],a:1,e:"團體保險保單又稱為總團體保險合約"},{c:"2.4",s:"下列哪項正確描述團體保險計劃?",o:["所有僱員不能從團體保單轉換為個人保險保單","每個受保僱員須詳細審核","保費相等於個別受保僱員保費之總和","團體保險計劃可以是僱員福利計劃的其中一種"],a:3,e:"團體保險計劃可以是僱員福利計劃的其中一種，計\n劃通常不會要求詳細的個人資料，某些計劃允許個\n人從團體保險保單轉為個人保單，並且通常不會要\n求提供可保性證明 。"},{c:"2.4&5.4.1(b)",s:"準備團體保單文件時，有關的技術系統通常會印製下列哪份或哪些文件?",o:["總保單","每名受保人的保險憑證","每名受保人的成員登記卡","以上所有各項"],a:3,e:"以上所有各項都是準備團體保單文件時，通常會印\n製的保單文件"},{c:"2.4(a)",s:"團體壽險有時也被稱為",o:["綜合壽險 （blanket life insurance)","集成保險合約 (collective insurance contract)","總團體保險合約 (master group insurance contract)","多個個人壽險合約 (multi-person life insurance contract)"],a:2,e:"團體壽險有時也被稱為總團體保險合約"},{c:"2.4(b)",s:"團體保險內的被保人又稱",o:["團體受保生命","團體被保險人","受保人","以上各項皆是"],a:3,e:"以上各項皆是團體保險內的被保人的別稱"},{c:"2.4(c)",s:"下列哪項是非供款式團體保險計劃之特點？",o:["僱員無須供款","僱主無須供款","僱員及僱主分擔供款","僱員及僱主無須分擔供款"],a:0,e:"非供款式團體保險計劃僱員無須供款"},{c:"2.4(c)",s:"以下哪項有關供款式團體保險計劃是正確的？",o:["僱員無須分擔保費","僱主無須分擔保費","僱主及僱員無須分擔保費","僱主及僱員雙方須分擔保費"],a:3,e:"供款式團體保險計劃是僱主及僱員雙方須分擔保費"},{c:"2.4(d)",s:"由多個僱主參加獨立團體壽險計劃為其各自的僱員提供保障是",o:["綜合團體 (combined group）","多個僱主的團體 (multiple-employer group)","獨立僱主團體 (independent-employer group)","多過一個僱主團體 (more-than-one-employer group)"],a:1,e:"由多個僱主參加獨立團體壽險計劃為其各自的僱員\n提供保障是多個僱主的團體"},{c:"2.4(d)",s:"以下哪個團體有權組成團體保險合約？",o:["同一僱主之僱員","同一工會之會員","同一體育協會之成員","以上各項皆是"],a:3,e:"以上各項皆是團體有權組成團體保險合約的合約各\n方"},{c:"2.4(e)",s:"以下有關團體壽險保單在核保的審核正確的是？",o:["團體計劃通常不會要求詳細的個人資料","團體計劃通常要求詳細的家族病歷","團體計劃通常要求詳細的個人核保","團體計劃的個人保費通常高於個人保險的累積保費"],a:0,e:"團體計劃通常不會要求詳細的個人資料"},{c:"2.4(e)",s:"核保團體壽險保單",o:["與核保個人保單完全相同","往往需要詳細個人資料","一般不需要詳細個人資料","把受保成員分作個別受保計算保費"],a:2,e:"團體計劃以集體核保形式核保。通常不會要求詳細\n的個人資料"},{c:"2.4(e)",s:"核保以下哪類保單，一般不用個人詳細健康資料？",o:["定期壽險","團體壽險","終身壽險","儲蓄壽險"],a:1,e:"團體壽險一般不用個人詳細健康資料"},{c:"2.4(f)",s:"團體保險的在職工作條款",o:["在受僱期間死亡才可得到保障","在受僱期間因工受傷才可得到保障","在保單保障生效時，實際當值工作","在保單保障生效時，當值工作或生病"],a:2,e:"團體保險的在職工作條款是在保單保障生效時，實\n際當值工作"},{c:"2.4(f)",s:"參加團體保險的「在職工作條款」的定義是",o:["保險生效後，個別受保險人士必須受僱並當值","保險生效後，個別受保險人士可以是受僱及放假","保險生效後，個別受保險人士可以是受僱及生病","保障範圍必須與工作有關"],a:0,e:"參加團體保險的「在職工作條款」的定義是保險生\n效後，個別受保險人士必須受僱並當值"},{c:"2.4(g)",s:"就團體人壽保險而言，其中一位合資格被保險人起初拒絕參加保險計劃，後來又想加入\n，以上的情形是？",o:["沒有可能加入","不需任何手續就可加入","只有繳付己過期但未繳清的保費才可","可以加入，但有可能需要出示可保性證明"],a:3,e:"就團體人壽保險而言，其中一位合資格被保險人起\n初拒絕參加保險計劃，後來又想加入，是可以的，\n但有可能需要出示可保性證明"},{c:"2.4(h)",s:"當一個人離開已購買團體保險的團體(例如:他已經不離職不再是僱員身份)，哪麼他",o:["可獲得過往已支付保費的退款","已不再受團體保險的保險人保障","即時取得團體保險的保險額賠償","可選擇體該保單轉為個人保單，並無需提供可保性證明"],a:1,e:"當一個人離開已購買團體保險的團體，他已不再受\n團體保險的保險人保障"},{c:"2.4(h)",s:"對於個別僱員離職，以下哪項關於其團體保險保單是正確的",o:["僱員可以取回就其過往已繳交的保費","僱員不可以再接受該公司提供的保障","僱員可取回過往保障的保額","團體壽險可以轉換成個人保險保單，並且通常不會要求提供可保性證明"],a:3,e:"團體壽險受保僱員離職可以轉換成個人保險保單，\n並且通常不會要求提供可保性證明"},{c:"3",s:"就保險人放棄某種權利的專業術語，會稱為",o:["放棄","豁免","優惠","免費"],a:1,e:"豁免是個自願放棄某項權利或取消某項規則的條件\n的行為"},{c:"3.1",s:"以下哪些情況令殘疾豁免保費附約仍然有效?",o:["保單生效前既存的狀況","在從事違法活動時導致的殘疾","因不小心對自己造成的傷害","戰爭時服兵役導致的殘疾"],a:2,e:"因不小心對自己造成的傷害令殘疾豁免保費附約仍\n然有效，可以得到保障"},{c:"3.1",s:"在基本計劃內提供某些附約或作出某些指定的規定，會以下列哪種形式出現？",o:["分紅保單","現金價值","附約","以上所列各項皆是"],a:2,e:"在基本計劃內提供某些附約或作出某些指定的規定\n，會以附約出現"},{c:"3.1.1",s:"以下那項是「豁免保費附約」的正確描述？",o:["保單所有人完全殘疾，殘疾期間豁免保費","當保單生效一段期間後保單所有人完全殘疾，殘疾期間豁免保費","當保單所有人失業時豁免保單所有人之保費","當市場上競爭對手保費低廉，保險人便退還保費"],a:0,e:"「豁免保費附約承諾在受保保單所有人完全傷殘時\n放棄其收取續保保費的權利。這並不代表保單被中\n止，保單將依然有效，"},{c:"3.1.1",s:"殘疾豁免保費附約可附加於",o:["定期壽險保單而已","分紅保單而已","終身壽險和儲蓄壽險保單","事實上適用於各類型的壽險保單"],a:3,e:"殘疾豁免保費附約可附加於幾乎所有類型的壽險"},{c:"3.1.1",s:"「殘疾豁免保費」附約規定？",o:["如果受保保單所有人完全傷殘，保險人會豁免傷殘期間的保費","如果在受保保單生效6個月以上，保單所有人完全傷殘，保險人會豁免傷殘期間的保費","失業期間豁免支付保費","如其他保險人提供較低的保費率，保險人便會退回保費"],a:0,e:"殘疾豁免保費附約承諾在受保保單所有人完全傷殘\n時放棄其收取續保保費的權利。這並不代表保單被\n中止，保單將依然有效，因此，保單將會繼續產生\n現金價值及紅利，猶如保單所有人已如期支付了保\n費 。"},{c:"3.1.1",s:"殘疾豁免保費附約規定被保人年齡限制,例如15至65歲之間,若被保人完全傷殘是發生於1\n5之65 歲範圍之內,則",o:["此附約並不適用","由保險人自行決定是否適用","不會得到附約保障","可獲豁免保費(根據保單條款)"],a:3,e:"殘疾豁免保費附約規定被保人年齡限制,例如15至6\n5歲之間,若被保人完全傷殘是發生於15之65歲範圍\n之內,則可獲豁免保費(根據保單條款)"},{c:"3.1.1",s:"以下哪項或哪些是「豁免保費」附約支付利益的準則描述是正確?",o:["受保保單所有人必須死於他生前引致完全傷殘的那項成因","受保保單所有人在保單有效期內變成完全傷殘,而且已持續一段指明時間(稱為等侯期)","當受保保單所有人完全傷殘時,之前最少已經部分傷殘達到某段時間(稱為等侯期)","以上各項均不屬於該附約支付利益的準則"],a:1,e:"受保保單所有人在保單有效期內變成完全傷殘,而\n且已持續一段指明時間(稱為等侯期，一般為為3或\n6個月)"},{c:"3.1.1",s:"「殘疾豁免保費附約」的意思是",o:["讓有關保險合約豁免首年保費","讓受保保單所有人於完全殘疾期間豁免保費","讓該有關保險合約是有利潤的(即分紅保單)","當受保保單所有人意外死亡時提供雙倍利益"],a:1,e:"「殘疾豁免保費附約」的意思是讓受保保單所有人\n於完全殘疾期間豁免保費"},{c:"3.1.1",s:"以下哪項不是(WP)附約的描述？",o:["(WP)是”waiting period”的縮寫，意指「等候期」","(WP)是”waiver of premium”的縮寫，意指「殘疾豁免保費附約」","被保險保單所有人須要完全傷殘，才可獲權益","受到特定年齡所限制"],a:0,e:"(WP)是Waiver of\nPremium的縮寫，意指「殘疾豁免保費附約」，而\n不是waiting period”「等候期」的意思"},{c:"3.1.1",s:"以下哪項或哪些有關豁免保費附約的描述是正確的？",o:["(WP)即代表「無利潤」","在完全傷殘時，保險人放棄收取保費的權利","保險利益通常須通過相等於保險期限的百分之十的「等候期」","以上各項"],a:1,e:"保險人根據此項附約承諾在受保保單所有人完全傷\n殘時放棄其收取續保保費的權利。這並不代表保單\n被中止，保單將依然有效"},{c:"3.1.1&3.1.2",s:"豁免保費附約與殘疾收入附約比較時",o:["兩者並無分別","只有豁免保費附約才會受等候期限制","只有殘疾收入附約才會在完全殘疾時提供收入","只有豁免保費附約才會在完全殘疾時提供收入"],a:2,e:"殘疾收入附約如名稱所示，則在完全殘疾期間提供\n收入。"},{c:"3.1.1(a)",s:"以下哪項或哪些有關「豁免保費」附約的支付利益準則描述是正確的？",o:["受保保單所有人在變成完全傷殘時必須維持達到某段時間然後死亡","受保保單所有人在變成完全傷殘時必須已經有部份殘疾達到某段時間","受保保單所有人必須在保單有效期內完全傷殘且達到某段時間, 稱為 「等候期」","以上所有各項均不屬於豁免保費附約支付利益的準則"],a:2,e:"受保保單所有人一旦根據保單的定義完全傷殘達最\n低期限（通常為三或六個月）他將獲豁免支付續保\n保費。一經開始，豁免會於保單的有效期內繼續下\n去，一直到相關傷殘結束為止。"},{c:"3.1.1(a)",s:"下列那兩項對殘疾豁免保費的描述是不正確的？\ni.從保單所有人遭受到殘疾起計至等候期完結後，保費才開始被豁免\nii.從保單所有人遭受到殘疾之時計起，保費才開始被豁免\niii. 等候期通常是三個月或六個月\niv. 保單所有人的年齡是沒有限制的",o:["i 及 ii","ii 及 iv","iii 及 iv","i 及 iv"],a:1,e:"豁免一般只限於指明年歲範圍內開始的傷殘，比如\n15至65歲。受保保單所有人一旦根據保單的定義完\n全傷殘達最低期限（通常為三或六個月）他將獲豁\n免支付續保保費。選項ii 及 iv不正確"},{c:"3.1.1(a)",s:"WP是附加條款，其意思是",o:["代表等候期意思","代表 with profit，有利潤意思","被保險人必須變成重大傷殘始可獲得豁免","豁免保費"],a:3,e:"殘疾豁免保費即是豁免保費附約 (WP Benefit )"},{c:"3.1.1(a)",s:"就豁免保費附約中的等候期而言，下列哪項不正確？",o:["該時期可以是3個月","只會在等候期內獲得豁免保費","等候期可能屬於也可能不屬於起賠期限","如果殘疾於等候期內康復，便不會獲得豁免保費"],a:1,e:"受保保單所有人一旦根據保單的定義完全傷殘達最\n低期限\n（通常為三或六個月）後他將獲豁免支付續保保費\n，選項ii不正確"},{c:"3.1.1(a)",s:"豁免保費附約通常設有「等候期」條文。這條文是要︰",o:["為容許過期繳付保費而提供的一指明的「寬限期」","給予保險人一定的時間限制去支付保險利益","延至殘疾情況維持一段時間之後才豁免保費","「等候期」內豁免保費"],a:2,e:"豁免保費附約的「等候期」是指被保險人的殘疾情\n況須維持一段時間之後才豁免保費，等侯期一般為\n3或6個月"},{c:"3.1.1(a)",s:"根據豁免保費附約，受保保單所有人的殘疾在「等候期」後持續，有些保險人會退還殘\n疾期內付的保費。這情況下「等候期」是",o:["起賠期限","時間性超賠額","保單限額","延期保單利益"],a:0,e:"這情況中的等候期屬於 「 起賠期限 」 或 「\n起賠期 間 」"},{c:"3.1.1(a)",s:"殘疾豁免保費的等候期是指",o:["容許保險人在該段時間內作出賠償","等候期內作出賠償","超過等候期開始豁免保費","即寬限期,又稱為寬限日期"],a:2,e:"殘疾豁免保費的等候期是指受保保單所有人根據保\n單的定義完全傷殘達最低期限（通常為三或六個月\n他將獲豁免支付續保保費。(超過等候期開始豁免\n保費)"},{c:"3.1.1(a)",s:"下列哪項或哪些對豁免保費附約的陳述是正確的?",o:["在受保保單所有人失業期間,保險人豁免有關保險","在完全殘疾的情況下豁免有關保費,而保障取消","在受保保單所有人完全殘疾期間,保險人豁免有關保費","以上所有各項"],a:2,e:"殘疾豁免保費是指受保保單所有人根據保單的定義\n完全傷殘達最低期限（通常為三或六個月）他將獲\n豁免支付續保保費。(超過等候期開始豁免保費)，\n答案C正確"},{c:"3.1.1(a)",s:"在受保保單所有人成為完全殘疾後，有關「豁免保費」附約尚未負上賠付責任前的時期\n稱為?",o:["等候期","除外期","非給付期","保險免賠期"],a:0,e:"有關「豁免保費」附約尚未負上賠付責任前的時期\n稱為等候期， 又稱「 起賠期限 」 或 「\n起賠期間 」"},{c:"3.1.1(a)",s:"以下哪項或哪些有關豁免保費附約的支付利益準則的描述是正確的？",o:["保單受保人變成完全傷殘時必須維持達到某段時間之後死亡","保單受保人變成完全傷殘時必須已經有部份殘疾達到某段時間",'保單受保人必須在保單有效期內完全傷殘且達到某段時間(稱為"等候期")',"以上所有各項均不屬於豁免保費附約支付利益的準則"],a:2,e:"殘疾豁免保費的等候期是指受保保單所有人根據保\n單的定義完全傷殘達最低期限\n（通常為三或六個月）他將獲豁免支付續保保費。\n(超過等候期開始豁免保費)，答案C正確"},{c:"3.1.1(a)",s:"若一份人壽保單附有豁免保費附約，受保人在完全殘疾時，保險人會怎樣處理？",o:["豁免等候期內的保費","若受保人在等候期後仍未康復，便由完全殘疾日期開始豁免保費，直至完全康復為止","由完全殘疾日期開始，豁免以後的保費","除豁免保費外，更支付賠償金"],a:1,e:"若一份人壽保單附有豁免保費附約，受保人在完全\n殘疾時，受保人在等候期後仍未康復，便由完全殘\n疾日期開始豁免保費，直至完全康復為止"},{c:"3.1.1(a)",s:"WP是附加條約，其意思是",o:["代表等候期意思","代表 with profit，有利潤意思","被保險人必須變成重大傷殘始可獲得豁免","得到豁免前有一段等候期"],a:3,e:"殘疾豁免保費(WP Benefit\nRider)是指受保保單所有人根據保單的定義完全傷\n殘達最低期限(通常為三或六個月)他將獲豁免支付\n續保保費。(超過等候期開始豁免保費)，答案D正\n確"},{c:"3.1.1(b)",s:"一般應用於「豁免保費」附約的年齡限制，意思是指這種保障通常只提供予下列哪項受\n保保單所有人?",o:["15歲以下人士","65歲以上人士","18歲以上人士","年齡介乎15至65歲人士"],a:3,e:"一般應用於「豁免保費」附約的年齡限制，意思是\n指這種保障通常只提供予年齡介乎15至65歲人士"},{c:"3.1.1(c)",s:"關於保費繳付頻率的更改，豁免保費附約的規定",o:["在任何時候，都可以要求更改","在任何情況下，更改是不允許的","在殘疾保險生效期間，更改是不允許的","在殘疾保險生效期間，從按月繳費更改到按年繳是允許的"],a:2,e:"就豁免保費而言，每年支付保費模式會自動轉換為\n每月支付模式。另一做法是明確規定不得在殘疾期\n間變更支付保費的頻率。"},{c:"3.1.1(c)",s:"就變更支付保費頻率，殘疾豁免保費附約的規定是",o:["在任何時候，所有更改都不允許","在任何情況，所有更改也允許","在傷殘保險期間，不得更改保費頻率","在傷殘保險期間，按月繳保費頻率可轉為年繳保費頻率"],a:2,e:"就變更支付保費頻率，殘疾豁免保費附約的規定在\n傷殘保險期間，不得更改保費頻率"},{c:"3.1.1(d)",s:"下列哪三項較可能是豁免保費(WP)附約的除外責任？\ni. 保單生效前既存的狀況\nii. 在從事違法活動時導致的殘疾\niii.因受僱用及其過程導致的殘疾\niv. 戰爭時服兵役導致的殘疾",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"選項iii因受僱用及其過程導致的殘疾不屬是豁免\n保費(WP)附約的除外責任，只有i,ii,iv選項正確"},{c:"3.1.1(d)",s:"以下哪項是殘疾豁免保費附約的描述是正確的?\ni. 保險人放棄收取本來應收保費的權利\nii. 代表保單將會終止\niii. 保單紅利仍然累積\niv. 可附加於不同類型的壽險",o:["i, ii","i, iii","i, iii, iv","ii, iii, iv"],a:2,e:"殘疾豁免保費附約一經開始，豁免會於保單的有效\n期內繼續下去，一直到相關傷殘結束為止，選項ii\n不正確"},{c:"3.1.1(d)",s:"殘疾豁免保費附約受到某些保單條款的限制，這些限制包括下列哪項或哪些 ?",o:["有關受保保單所有人的年齡限制","完全殘疾期間不能改變繳付保費的頻率","因某些原因(例如從事違法活動)造成的殘疾","以上所有各項"],a:3,e:"以上所有各項皆是殘疾豁免保費附約受到某些保單\n條款的限制"},{c:"3.1.1(d)",s:"下列哪項不是殘疾豁免保費的除外責任？",o:["蓄意傷害自己身體造成的殘疾","在從事違法活動時導致的殘疾","保單生效前既存的狀況","第三者的刑事責任而引致的損害"],a:3,e:"第三者的刑事責任而引致的損害不是殘疾豁免保費\n的除外責任"},{c:"3.1.1(d)",s:"下列哪項或哪些不屬於因完全殘疾而(豁免保費)附約的除外責任？",o:["因企圖自殺而導致完全殘疾","因駕駛電單車發生意外的完全殘疾","從事違法活動時所引致的完全殘疾","以上所有各項"],a:1,e:"因駕駛電單車發生意外的完全殘疾不屬於因完全殘\n疾而(豁免保費)附約的除外責任"},{c:"3.1.2",s:"以下哪項不是殘疾收入附約的常用條款?",o:["並非貸款或預繳","應付金額","等侯期","性別限制"],a:3,e:"性別限制不是殘疾收入附約的常用條款"},{c:"3.1.2",s:"以下哪項不是殘疾收入附約的常用條款?",o:["年齡限制","應付金額","等侯期","並非貸款或預繳"],a:0,e:"年齡限制不是殘疾收入附約的常用條款"},{c:"3.1.2",s:"以下哪項不是殘疾收入附約的常用條款?",o:["預期健康狀況","應付金額","等候期","並非貸款或預繳"],a:0,e:"預期健康狀況不是殘疾收入附約的常用條款"},{c:"3.1.2",s:"殘疾收入保險利益附約可以附加到",o:["只可以附加於定期壽險保單","只可以附加於終身壽險","只可以附加於分紅儲蓄壽險","實際上可以附加於任何類型的人壽保險"],a:3,e:"殘疾收入保險利益附約實際上可以附加於任何類型\n的人壽保險"},{c:"3.1.2",s:"以下哪項是對殘疾收入的正確描述?",o:["這附加契約可附加於所有類型的保險上","等候期訂為一個月至六個月不等","已收取的收入保險利益於未來的死亡保險金中扣除","以上各項皆正確"],a:1,e:"殘疾收入等候期訂為一個月至六個月不等"},{c:"3.1.2",s:"如果人壽保單收到殘疾收入附約約束,並且受保生命遭遇殘疾,而現正提供收入",o:["該收入通常以每月形式支付","其基本保障會暫時停止","所支付金額會於死亡保障額中扣除","此類保障通常並不設有等候期"],a:0,e:"殘疾收入等候期由一個月至六個月不等，所支付的\n利益並非貸款或預繳，不會於死亡保障額中扣除，\n殘疾收入附約如名稱所示，則在完全殘疾期間提供\n收入"},{c:"3.1.2",s:"把「豁免保費附約」及「殘疾收入附約」比較時",o:["兩者皆無分別","豁免保費附約受等候時間所限","豁免保費附約在完全殘疾期間提供一項收入","殘疾保險利益在完全殘疾期間提供一項收入"],a:3,e:"把「豁免保費附約」及「殘疾收入附約」比較時，\n殘疾保險利益在完全殘疾期間提供一項收入"},{c:"3.1.2",s:"如果保單受到殘疾收入附約的約束，並且因為受保生命遭受殘疾，正在支付收入保險利\n益",o:["收入保險利益通常每月給付","在這段時間內，保單的基本保障予以暫停","已經支付的保險利益將從保單保額中扣除","開始支付保險利益前，這類殘疾不受任何「等候期」的約束"],a:0,e:"殘疾收入等候期由一個月至六個月不等，所支付的\n利益並非貸款或預繳，不會於死亡保障額中扣除，\n完全殘疾期間，基本保單依然完全有效。殘疾收入\n附約如名稱所示，則在完全殘疾期間提供收入"},{c:"3.1.2",s:"根據「殘疾收入附約」所支付的收入保險利益",o:["會從最後的死亡保險金扣除","不會從最後的死亡保險金扣除","會從未來的紅利扣除","實質上是一種利用額外保費償還的貸款"],a:1,e:"「殘疾收入附約」所支付的收入保險利益不是預繳\n或貸款，不會從最後的死亡保險金扣除"},{c:"3.1.2(a)",s:"根據殘疾收入附約的條款，「完全殘疾」是指受保保單所有人沒有能力履行其本身固定\n職業的主要任務",o:["而已","或其他任何職業的基本任務","或不能從事任何按照其以往所受教育、訓練及經驗在合理程度上勝任的職業","或其他最少提供相同薪金的職業的基本任務"],a:2,e:"「完全傷殘」一詞可指：受保生命因患病或身體受\n傷而無法執行其工作中，或基於其學校教育、培訓\n或經驗而適合他的任何其他工作 中\n任何必要行為及職責 。"},{c:"3.1.2(b)",s:"根據殘疾收入附約，收入保險利益通常與該保單的保額掛鈎，並且支付的頻密程度為",o:["每週","每月","在保單年度終結的時候","在殘疾期間結束的時候"],a:1,e:"根據殘疾收入附約，收入保險利益通常與該保單的\n保額掛鈎，並且支付的頻密程度為每月"},{c:"3.1.2(c)",s:"殘疾收入附約有一個等候期，該等候期",o:["總是3個月","1個月至6個月不等","持續時間不少於6個月","由3個月至6個月不等﹝跟豁免保費附約一樣﹞"],a:1,e:"殘疾收入等候期由一個月至六個月不等"},{c:"3.1.2(d)",s:"以下哪項描述殘疾收入附約中的收入保險利益是正確的？",o:["保險利益會在保額中扣除","保險利益不會在保額中扣除","保險利益會在保單未來紅利中扣除","保險利益其實是未來保費的保單貸款"],a:1,e:"殘疾收入所支付的利益並非貸款或預繳，不會於死\n亡保障額中扣除"},{c:"3.1.2(d)",s:"下列哪項是「殘疾收入附約」的特性？",o:["已給付的收入不會從保險利益中扣除","完全殘疾後，只需繳交50%的保費","等候期通常為期三個月或六個月","給付的收入只是貸款"],a:0,e:"殘疾收入所支付的利益並非貸款或預繳，不會於死\n亡保障額中扣除"},{c:"3.1.2(d)",s:"根據殘疾收入附約，支付的殘疾收入保險利益",o:["會在最後的保險金扣除","不會在最後的保險金扣除","在未來的保單紅利中扣除","實質上是從保單中的現金價值貸款"],a:1,e:"殘疾收入保險利益不是預繳或貸款，不會在死亡保\n險金扣除"},{c:"3.2",s:"意外死亡及喪失肢體(AD&D)附約，近因原則對這種附約顯得非常重要，原因是",o:["不適用於危疾保單","只有被保險人因意外死亡才有會給付雙倍賠償利益","每索償賠付，都會是保單基本保單保額的兩倍","就一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付"],a:1,e:"就意外死亡及喪失肢體(AD&D)附約而言，只有被保\n險人因意外死亡才有會給付雙倍賠償利益，所以近\n因原則(死亡原因)對這種附約顯得非常重要"},{c:"3.2",s:"以下哪項不是意外死亡及喪失肢體 (AD&D)的常用條款?",o:["吸煙者限制","應付金額","等候期","不是預繳或貸款"],a:0,e:"吸煙者限制不是意外死亡及喪失肢體(AD&D)的常用\n條款"},{c:"3.2",s:"AD & D附約就下列哪項提供了額外利益？",o:["只限於意外死亡","意外死亡及殘疾 (每月支付)","意外死亡或列明的疾病而導致死亡","意外喪失肢體及死亡(按照有關定義)"],a:3,e:"意外保險利益通常附加於與意外死亡及喪失肢體有\n關的任何種類的壽險保單。它們通常被歸納為一個\n單一的附約，稱之為意外死亡及喪失肢體\n(AD&D)附約，答案D正確"},{c:"3.2",s:"AD & D英文全名為",o:["意外死亡及傷殘 accidental death & disablement","意外死亡及喪失肢體 accidental death & dismemberment","預計死亡及傷殘 anticipated death & disablement","預計死亡及喪失肢體 anticipated death & dismemberment"],a:1,e:"AD & D英文全名為意外死亡及喪失肢體\naccidental death & dismemberment"},{c:"3.2.1",s:"在意外死亡保險利益的先決條件下，死亡必須發生於意外後的一段時間，該段時間通常\n指",o:["即時","24小時内","保單期限額滿前","受傷後指定期間"],a:3,e:"意外死亡保險利益附約支付利益的準則，死亡必須\n由意外身體受傷而直接引起，並與所有其他原因無\n關並於該受傷的一年之內發生"},{c:"3.2.1",s:"以下哪項對意外死亡及喪失肢體的描述是正確的?\ni) 又稱為雙倍賠償利益\nii)與基本保障同樣受到一年的自殺免責期約束\niii)發生意外而引致死亡時可得到額外利益\niv) 正常情況下得到相等於保額的兩倍金額",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，選項ii不正確"},{c:"3.2.1",s:"以下哪一項雙倍賠償利益 (Double Indemnity Benefit)的描述不正確?",o:["它只適用於第三者保單","使用「彌償」一詞技術上並不準確","發生由意外導致的死亡，保單將額外支付相等於保單保額的保險利益","此類保險利益亦稱為意外死亡保險利益"],a:0,e:"雙倍賠償利益不適用於第三者保單"},{c:"3.2.1",s:"以下哪項是意外死亡及喪失肢體 (AD&D)附約中支付的意外死亡保險利益?",o:["保單保額的50%","保單保額的100%","額外支付一筆與基本保單的保額相等的保險利益","只涉及汽車意外而死亡才會給付保險利益"],a:2,e:"意外死亡及喪失肢體(AD&D)附約此類附約，一般承\n諾，於意外導致死亡的情況下，額外支付一筆與基\n本保單的保額相等的保險利益。"},{c:"3.2.1",s:"意外死亡保險利益附約支付利益的準則,死亡必須於?",o:["意外身體受傷後一段指定時間內發生","有關基本計劃須包含豁免保費附約","在受保保單所有人昏迷時死亡","即時死亡"],a:0,e:"意外死亡保險利益附約支付利益的準則，死亡必須\n由意外身體受傷而直接引起，\n並與所有其他原因無關並於該受傷的一年之內發生"},{c:"3.2.1",s:"根據意外死亡及喪失肢體附約，在以下哪情況可以得到一筆相等於意外死亡保險金的金\n額？",o:["喪失一肢或單目失明","喪失兩肢或多個肢體，或雙目失明","由多個指明的情況的其中一項導致的死亡","持續殘廢的情況超過兩年"],a:1,e:"根據意外死亡及喪失肢體附約，當喪失兩肢或多個\n肢體，或雙目失明情況下，可以得到一筆相等於意\n外死亡保險金的金額"},{c:"3.2.1",s:"根據意外死亡及喪失肢體附約，在以下哪項原因導致死亡的情況下，才得到意外死亡保\n險利益?",o:["任何原因","意外身體受傷","自殺以外一切原因","謀殺以外一切原因"],a:1,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關"},{c:"3.2.1",s:"「意外死亡保險利益附約」向受保保單所有人提供雙倍賠償利益，以下哪個死亡原因受\n保保單所有人可得到該賠償？",o:["車禍","游泳時，遭受鯊魚襲擊","旅行時，受持械搶劫的人槍擊","以上所有各項"],a:3,e:"以上所有各項情況下都可以向受保保單所有人提供\n雙倍賠償利益「意外死亡保險利益附約」"},{c:"3.2.1(a)",s:"以下哪項是意外死亡保險利益附約的正確描述？\ni. 此類屬「重複保險」\nii. 與基本保單條款相若，第一年為自殺免責期\niii. 受保死亡由意外事故導致\niv. 一般情況下，死亡保險金與保單保額相同",o:["i, ii, iv","i, ii, iii","iii, iv","ii, iii, iv"],a:2,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與保單的保額相等的保險\n利益。不過受保生命死亡必須由意外身體受傷而直\n接引起，並與所有其他原因無關，並於該受傷的一\n年之內發生，只有選項iii, iv正確"},{c:"3.2.1(a)",s:"在意外發生後身體喪失多個肢體，隨後更因此而死亡，根據意外死亡及喪失肢體的條款\n，可獲得的賠償是",o:["死亡保險金的總數","並不獲得任何賠付","相等於死亡保險金再加上一倍的賠付金額","相等於死亡保險金再加上雙倍的賠付金額"],a:0,e:"保單會規定：在同一次意外事故同時引致喪失肢體\n和死亡的情況下，保單只須支付喪失肢體保險利益\n或死亡保險利益，而非同時支付兩項利益。"},{c:"3.2.1(a)",s:"在意外死亡保險利益附約中，下列哪項死因一般是受到保障？",o:["一名人士被謀殺","一名被警察開槍擊斃的賊人","一名正接受飛行訓練的人士，死於撞機意外","一名乘坐飛機人士，是購票的普通乘客，死於撞機意外"],a:3,e:"作業一名乘坐飛機人士，是購票的普通乘客，死於\n撞機意外，不屬除外責任。"},{c:"3.2.1(a)",s:"在意外死亡保險利益附約中，下列哪項死因一般是受到保障？",o:["自殺","一名被警察開槍擊斃的賊人","作為一名艙務員的時候，死於撞機意外","一名死於撞機意外，普通購票的乘客"],a:3,e:"死於撞機意外，普通購票的乘客不屬意外死亡保險\n利益附約中的除責任"},{c:"3.2.1(a)",s:"近因原則的應用在於決定索償的原因。於人壽保單中，這項原則在以下哪項情況下是十\n分重要?",o:["只適用於分紅性質保單","保單所有人於保單生效5年後，懷疑因自殺而身故","適用有雙倍補償條款的保單","提供人身意外保險利益的保單，保單生效不久或因自殺而身故"],a:3,e:"自殺免責期長通常為保單發出後一年，證實受保人\n在自殺免責期自殺屬除外責任"},{c:"3.2.1(a)",s:"雙倍賠償利益是指意外死亡由身體受傷而引起",o:["保單保額雙倍賠償","保額意外的殮葬費","現金紅利的兩倍","以繳交保費兩倍的退保費"],a:0,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，這種保險利益經常被稱\n為雙倍賠償利益 (Double Indemnity Benefit)"},{c:"3.2.1(a)",s:"就意外保險而言，近因的應用為何這樣重要？",o:["死亡及喪失兩肢時，會作出雙倍賠償","意外事故導致受保生命喪失單肢或單目失明，會作出雙倍賠償","喪失兩肢時，會作出雙倍賠償","因為只有意外死亡，才會作出雙倍賠償利益"],a:3,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，近因對這種附約顯得非\n常重要，因為只有意外死亡，才會作出雙倍賠償利\n益"},{c:"3.2.1(a)",s:"在意外死亡保險利益附約中，下列哪項死因是受到保障",o:["自殺(保單生效有4年)","企圖入屋行劫時被戶主開槍擊斃的賊人","乘坐飛機的購票乘客，死於撞機意外中身亡","駕駛自己的私人飛機，死於撞機意外中身亡"],a:2,e:"乘坐飛機的購票乘客，死於撞機意外中身亡，在意\n外死亡保險利益附約中是受到保障"},{c:"3.2.1(a)",s:"在意外死亡保險利益附約中，下列哪項死因是除外的",o:["遭搶劫的歹徒殺害","橫過馬路時死於一宗交通意外","作為一名乘客的時候，死於撞機意外","作為一名艙務員的時候，死於撞機意外"],a:3,e:"只有乘坐飛機的購票乘客，死於撞機意外中身亡，\n在意外死亡保險利益附約中是受到保障，作為一名\n艙務員的時候，死於撞機意外是意外死亡保險利益\n附約中屬除外責任"},{c:"3.2.1(a)",s:"下列哪項或哪些關於意外死亡保險利益附約的陳述是正確的？",o:["不存在任何除外責任","意外死亡，可在本計劃上所支付的金額之上多獲支付一筆款項","它提供彌償性的支付","以上所有各項"],a:1,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，這種保險利益經常被稱\n為雙倍賠償利益 (Double Indemnity Benefit)"},{c:"3.2.1(a)",s:"意外死亡保險利益亦稱為",o:["雙倍賠償利益","意外賠償利益","雙倍意外利益","額外死亡利益"],a:0,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，這種保險利益經常被稱\n為雙倍賠償利益 (Double Indemnity Benefit)"},{c:"3.2.1(a)",s:"在人身意外保險中，被保險人喪失肢體，惟以下3項均得不到賠償：\ni) 企圖自殺\nii) 在服役期間戰爭引致傷殘\niii) 參予危險活動時引致傷殘\niv) 在銀行劫案中被傷害引致傷殘",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:0,e:"參與違法活動時造成的傷殘及參與危險運動時造成\n的傷殘均得不到賠償。選項i, ii, iii正確"},{c:"3.2.1(a)",s:"意外死亡保險利益，受傷而導致死亡必須在下列的指定時期內發生？",o:["即時發生","24小時內發生","1星期內發生","於該受傷的一年之內發生"],a:3,e:"死亡必須由意外身體受傷而直接引起，並與所有其\n他原因無關並於該受傷的一年之內發生"},{c:"3.2.1(a)(ii)",s:'一個人喪失兩肢，他擁有"意外死亡及喪失肢體(AD&D)附約"。在甚麼情況下，他不被獲\n取賠償？\ni 因蓄意傷害自己身體\nii 因在戰爭中喪失肢體\niii 因參與高危之項目\niv 在打劫情況下被劫掠者傷害的無辜人仕',o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:1,e:"在打劫情況下被劫掠者傷害的無辜人仕，不屬意外\n死亡及喪失肢體(AD&D)附約的除外責任"},{c:"3.2.1(a)(ii)",s:"意外死亡及喪失肢體附約的除外責任包括下列哪項或哪些？",o:["自殺","與戰爭有關的傷殘","作為非購票乘客於空難中導致的傷殘","以上所有皆是"],a:3,e:"以上所有皆是意外死亡及喪失肢體附約的除外責任"},{c:"3.2.1(a)",s:"意外保險中，「雙倍賠償利益」在技術上不適用於人壽保險，因為",o:["導致意外的原因可能是不保事項","彌償只適用於財產保險","此利益不適用於自然死亡","給付保額實際上不是彌償，是屬於利益"],a:3,e:"這種保險利益經常被稱為雙倍賠償利益(Double\nIndemnity\nBenefit)。在這裏使用字面意思為「彌償」一詞技\n術上並不準確，因為人壽保險一般不適用彌償原則"},{c:"3.2.1(a)",s:"以下哪項有關雙倍賠償利益附約(double Indemnity benefit)的陳述是不正確的？",o:["只適用於第3者保險","引起死亡的近因對這附約很重要","嚴格來說，它的英文術語在技術上是不正確","它是意外保險利益附約的另一名稱"],a:0,e:"雙倍賠償利益附約與第3者保險無關"},{c:"3.2.1(a)",s:"經常被稱爲雙倍賠償利益(double Indemnity benefit)。\n“Indemnity”這英文詞彙，技術上並不準確，因為",o:["人壽保險不受彌償原則所限制","人壽保險並不屬於賠償保險(insurance of indemnity)","賠償不一定是保額的兩倍","死亡必須由意外而引發才可獲賠償"],a:0,e:"經常被稱爲雙倍賠償利益(double Indemnity\nbenefit)。“Indemnity”這英文詞彙，技術上並\n不準確，因為人壽保險屬利益保單，不受彌償原則\n所限制"},{c:"3.2.1(a)",s:"壽險保單中的雙倍補償利益，如果死亡由意外身體受傷引致",o:["保險人會支付相當於保單保額兩倍的金額","在保額以外再支付殮葬費用","支付一筆相等於現存紅利兩倍的金額","支付一筆相等於已繳保費兩倍的退保費"],a:0,e:"壽險保單中的雙倍補償利益，如果死亡由意外身體\n受傷引致，保險人會支付相當於保單保額兩倍的金\n額"},{c:"3.2.1(a)",s:"意外導致死亡時，意外死亡保險利益附約會支付一筆與保單保額相等的額外款項。因此\n這亦稱為",o:["雙倍利益附約","雙倍賠償利益","意外死亡紅利","意外死亡增值安排"],a:1,e:"意外導致死亡時，意外死亡保險利益附約會支付一\n筆與保單保額相等的額外款項。因此這亦稱為雙倍\n賠償利益"},{c:"3.2.1(a)",s:"在決定是否支付雙倍賠償利益時，由於必須確定受保生命死亡的原因，下列哪項保險原\n則變得很重要",o:["彌償","近因","可保權益","最高誠信"],a:1,e:"在決定是否支付雙倍賠償利益時，由於必須確定受\n保生命死亡的原因，確定死亡近因變得很重要"},{c:"3.2.1(a)",s:"以下哪項或哪些在人壽保險所附帶的「其他意外保險利益」中，其他利益包括?",o:["嚴重燒傷","每日住院津貼","殘疾期間的每週津貼","以上各項皆是"],a:3,e:"以上各項皆是「其他意外保險利益」中，其他利益\n包括的保障"},{c:"3.2.1(b)",s:"根據意外死亡及喪失肢體附約，因意外事故引致意外死亡或喪失兩肢可獲得的賠償為",o:["死亡或喪失兩肢的保險利益是一樣的","死亡的賠償高於喪失兩肢","喪失兩肢的賠償高於死亡","死亡及喪失兩肢的保險利益不一樣"],a:0,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項"},{c:"3.2.1(b)",s:"下列哪項屬於意外及喪失肢體附約中，「喪失肢體」部份的一般特點？\ni) 喪失肢體是指肢體的實質斷離及失去其功能\nii) 其他保障不包括喪失單肢\niii)經修訂的保障為喪失單肢支付死亡保險金的規定比率\niv)對方因一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付",o:["i , ii","iii , iv","i, iii","i, ii, iii, iv"],a:2,e:"若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷給付額通常相等於意外\n死亡保險金的規定比率"},{c:"3.2.1(b)",s:"下列哪項不屬於意外及喪失肢體附約中，「喪失肢體」部份的一般特點？\ni) 喪失肢體是指肢體的實質斷離及失去其功能\nii) 其他保障不包括喪失單肢\niii)經修訂的保障為喪失單肢支付死亡保險金的50%\niv)對方因一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付",o:["i , ii","i,ii,iii","ii,iv","ii, iii, iv"],a:2,e:"在意外死亡及喪失肢體附約中，「喪失肢體」包括\n喪失肢體肢體或功能，以及喪失視力的意思，給付\n額通常相等於意外死亡保險金的規定比率，在同一\n次意外事故同時引致喪失肢體和死亡的情況下，不\n會同時支付兩項利益。只有選項ii,iv正確。"},{c:"3.2.1(b)",s:"若意外事故導致受保生命喪失單肢或單目失明，或遭受其他較輕微的指明受傷，給付額\n為",o:["意外死亡賠償金額的100%","相等於意外死亡保險金的規定比率","扣減自負額後的保險金的規定比率","扣減醫療費用後的保險金的規定比率"],a:1,e:"若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷，給付額為相等於意外\n死亡保險金的規定比率"},{c:"3.2.1(b)",s:"喪失肢體附約定義為",o:["某些保險人可能會將定義延至整條手臂或臀部以下部位","保障涉及喪失該肢體功能","喪失一個手指關節也可得到賠償","附有每周住院津貼保障"],a:1,e:"在意外死亡及喪失肢體附約中，「喪失肢體」包括\n喪失肢體及喪失視力的意思"},{c:"3.2.1(b)",s:"意外死亡及喪失肢體附約受保生命在意外事故中可得到一筆與死亡保險金相等的賠償金,\n經修改後受保人可收取50%保險金若意外事故導致",o:["喪失一腿","喪失一目","喪失一手","以上各項皆是"],a:3,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項。\n若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷，給付額通常相等於意\n外死亡保險金的規定比率，例如喪失單肢或單目失\n明可收取50%保險金"},{c:"3.2.1(b)",s:"意外死亡及喪失肢體保險附約使保險人在受保人意外中喪失肢體時給付賠償,提供經修改\n後的保障,則需",o:["喪失一肢或一目失明,提供賠償為保額雙倍","喪失一手指或腳指,提供賠償為保額全數","喪失一腿部或臂部,提供賠償為保額某個百分比","喪失一肢或一目失明,提供賠償為保額一半"],a:3,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項。\n若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷，給付額通常相等於意\n外死亡保險金的規定比率，例如喪失單肢或單目失\n明可收取50%保險金"},{c:"3.2.1(b)",s:"根據意外死亡及喪失肢體附約，經修改的保障意外死亡保險收益，保險人亦可以包括以\n下情況",o:["喪失手指或腳趾會賠償保障金額","臂部斷離會賠償保障金額","喪失單肢會賠償保障金額的一半/規定比率","單目失明會賠償兩倍保障金額"],a:2,e:"若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷給付額通常相等於意外\n死亡保險金的規定比率"},{c:"3.2.1(b)",s:"根據意外死亡及喪失肢體附約中，「喪失肢體」是指?",o:["嚴格地指喪失雙臂","必須喪失一雙肢體(雙臂或雙腿)","往往適用於單目失明(同時適用於喪失肢體)","可用於雙目失明"],a:2,e:"在意外死亡及喪失肢體附約中，「喪失肢體」包括\n喪失肢體及喪失視力的意思"},{c:"3.2.1(b)",s:"下列哪項屬於意外及喪失肢體附約中，「喪失肢體」部份的一般特點:\ni)喪失肢體是指肢體的完全斷離或喪失肢體的功能\nii)喪失單肢給付額等於意外死亡保險金的規定比率\niii)喪失視力\niv)對方因一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付",o:["只有 i, ii","只有 iii, iv","只有 i, ii, iii","i, ii, iii, iv"],a:2,e:"一般來說，保單會規定在同一次意外事故同時引致\n喪失肢體和死亡的情況下，保單只須支付喪失肢體\n保險利益或死亡保險利益，而非同時支付兩項利益\n，選項iv不正確"},{c:"3.2.1(b)",s:"在意外死亡保險收益，喪失肢體在於實際喪失由手腕或足踝關節處以上完全斷離作定義\n。但保險人亦可以包括以下情況",o:["臂部及肩斷離開始才作賠償","一根手指或腳指之斷離也作賠償","包括喪失肢體功能","喪失任何2肢才作出賠償"],a:2,e:"喪失一肢可以描述為實際喪失肢體，或喪失肢體的\n功能"},{c:"3.2.1(b)",s:"下列哪項與意外死亡及喪失肢體(AD&D)附約有關的評論是正確的？\ni) 喪失一肢可解釋作實際失去，或失去其功能\nii) 喪失一肢，則給付相當於死亡金的數額\niii) 喪失兩肢，則給付相當於死亡金的數額\niv) 喪失肢體利益也適用於意外引致的失明",o:["i, ii","i, iii","i, iii, iv","ii, iii, iv"],a:2,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，才會支付一筆與意外死亡保險金\n相等的款項。選項ii不正確"},{c:"3.2.1(b)(iv)",s:"某人因一宗嚴重的交通意外而死亡。初時，傷勢只是失去兩個肢體，但該名受害人一星\n期後因傷重而死亡，如果他的人壽保單加有意外死亡及喪失肢體附約，保單將會支付",o:["保額而已","保額的2倍","保額的3倍","保額的4倍"],a:0,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項，在同一次意外事故同時引致喪失肢體\n和死亡的情況下，保單只須支付喪失肢體保險利益\n或死亡保險利益，而非同時支付兩項利益。"},{c:"3.2.1",s:"意外死亡保險利益(ADB)被稱為雙倍賠償利益(Double Indemnity\nBenefit)，在這裡的英文名稱技術上並不準確，因為",o:["彌償只應用於定期壽險","人壽保險不受彌償所限制","在正常情況下須額外支付兩倍的保險利益","唯有是由意外引致死亡才會賠償"],a:1,e:"在這裏使用Indemnity字面意思為「彌償」一詞技\n術上並不準確，因為人壽保險是利益保單，一般不\n適用彌償原則"},{c:"3.2.2",s:"附加於人壽保單的意外死亡及喪失肢體附約，有時會賠付超出意外死亡保險利益及其他\n保險利益，以下哪項是適用的保障範圍?\n(i) 嚴重燒傷，可獲支付指明金額\n(ii) 每周津貼，最長為52周\n(iii) 住院津貼，每日津貼上限為 1,000日\n(iv) 因乘搭一般公共交通工具引果傷殘可獲「雙倍賠償」",o:["i,ii","ii,iii","ii,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是意外死亡保險利益附約所提供的其他\n保險利益"},{c:"3.2.2(a)",s:"在意外死亡保險利益有關「喪失肢體」的條款內,受保保單所有人在意外中喪失甚麼,保\n險人才會給付一筆與死亡賠償相等的金額?",o:["喪失一肢","一目失明","喪失一肢或一目失明","喪失一肢及一目失明"],a:3,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項"},{c:"3.2.2(a)",s:"附加於人壽保險的「其他意外保險利益」的意外身體損傷利益給付表，通常列出下列哪\n項或哪些情況下應付的利益？",o:["死亡而已","死亡及喪失視力的受傷而已","死亡、喪失視力及喪失主要肢體的受傷而已","上述所有各項，連同各種指定的較輕程度的傷殘"],a:3,e:"在意外死亡及喪失肢體附約中，於意外導致死亡的\n情況下額外支付一筆與基本保單的保額相等的保險\n利益。若意外事故導致受保生命喪失單肢或單目失\n明，或遭受其他較輕微的指明受傷給付額通常相等\n於意外死亡保險金的規定比率"},{c:"3.2.2(b)",s:"意外保險利益的其他利益包括：\ni) 嚴重燒傷\nii) 每週津貼\niii) 住院津貼\niv) 雙倍賠償",o:["i, ii","ii, iii","i, ii, iii","以上各項都是"],a:3,e:"以上各項都是意外保險利益的其他利益"},{c:"3.2.2c",s:"附加於人壽保險的˹其他意外保險利益˼之除外責任,以下哪項並不包括",o:["被保險人被謀殺","自殺","參加違法活動時造成的傷殘","疾病(除非由意外引致)"],a:0,e:"被保險人被謀殺不屬其他意外保險利益之除外責任"},{c:"3.2.2c",s:"以下哪項並不屬於其它意外保險利益的除外責任？",o:["被搶劫時引致的受傷","自殺","自殘身體","疾病(並非由意外引致)"],a:0,e:"被搶劫時引致的受傷不屬其他意外保險利益之除外\n責任"},{c:"3.3",s:"以下哪項就提前支付死亡保險利益附約的陳述是正確的?\ni. 此附約亦稱為生前支付保險利益附約\nii. 此附約只適用於如癌症般的嚴重疾病\niii. 於極度悲傷或生命受到威脅情況下可提取\niv. 該支付可能會影響受益人的期望",o:["i, ii, iii","i, ii, iv","i,iii,iv","ii,iii,iv"],a:2,e:"兩種提前支付死亡保險利益有兩種，分別是危疾和\n長期護理保險利益。選項ii不正確"},{c:"3.3",s:"要符合哪些條件，保單所有人可獲得危疾賠償?\ni. 受保人被診斷患上指明疾病；\nii. 受保人被診斷患上終末疾病並只有6個月或更短的壽命\niii. 受保人過去一年未曾接受外科手術\niv. 受保人他有必要接受指明的醫療程序",o:["i,iv","i, ii,iv","i,iii,iv","ii,iii,iv"],a:0,e:"只有選項i,iv及是危疾賠償的條件"},{c:"3.3",s:"提前支付死亡保險利益還可提供預先支付死亡保險金的一項附加保險，以下哪種情況可\n行使此項權利",o:["保險金可以支付給受保保單所有人","會影響受益人的期望","在極度悲傷的生命受到威脅情況下可提取","以上各項皆是"],a:2,e:"支付提前支付死亡保險利益的基本原因，是在極度\n精神緊張、悲哀和生命受威脅的情況下發放保險利\n益，可以幫助當事人應付有關開支，向當事人提供\n部分援助以解決新增的財務困擾。兩種提前支付死\n亡保險利益，分別是危疾和長期護理保險利益，答\n案C正確"},{c:"3.3",s:"容許全部或部分死亡保險金支付給仍然在生的保單所有人的條文為",o:["意外死亡及喪失肢體附約","生前支付保險利益附約","死前補償附約","特許死亡保險金附約"],a:1,e:"容許全部或部分死亡保險金支付給仍然在生的保單\n所有人的條文為生前支付保險利益附約"},{c:"3.3",s:"提前支付死亡權益附約可附加在人壽保險單中，以下哪項描述是正確的？",o:["只適用於分紅保單","只適用於保障額較少的保單","只適用於保障額較大的保單","在是次申請，必須經過第二次體檢"],a:2,e:"為了降低行政成本，這種附約往往只准附加於保額\n相當大的保單。"},{c:"3.3",s:"一份保單包含提前提前支付死亡保險利益附約,這代表",o:["這份保單可轉換為儲蓄壽險","這份保單已加入殘疾利益","受保保單所有人可於生命結束前支取保險利益","受保保單所有人年屆100歲時,可支取保險利益"],a:2,e:"一份保單包含提前提前支付死亡保險利益附約,這\n代表受保保單所有人可於生命結束前支取保險利益"},{c:"3.3",s:"「提前支付死亡保險利益」又稱為",o:["生前支付保險利益","快捷給付保險利益","儲蓄保險","死前給付保險利益"],a:0,e:"「提前支付死亡保險利益」又稱為生前支付保險利\n益"},{c:"3.3",s:"有時候壽險保單會加上生前支付保險利益附約，這種附約較普通的名稱稱為",o:["保費退還計劃","死亡前利益計劃","純生存形式保險利益","生前支付保險利益附約"],a:3,e:"有時候壽險保單會加上生前支付保險利益附約，這\n種附約較普通的名稱，稱為生前支付保險利益附約"},{c:"3.3",s:"一份保單包含提前支付死亡保險利益附約,這代表",o:["這份保單可轉換為儲蓄壽險","這份保單已加入殘疾利益","受保保單所有人可於生命結束前支取保險利益","受保保單所有人年屆100歲時,可支取保險利益"],a:2,e:"一份保單包含提前支付死亡保險利益附約,這代表\n受保保單所有人可於生命結束前支取保險利益"},{c:"3.3(c)",s:"根據提前支付死亡保險利益條款，在某些嚴重的情況下，縱使死亡並未發生，保單所列\n明的死亡金是可以支付給保單所有人，但",o:["受益人/承讓人必須簽署棄權聲明","受益人同樣可以取回所有索償","受益人如果在受保人死後兩年內便可獲取所有索償","受益人只可取回保費"],a:0,e:"由於向在世的受保保單所有人發放保險利益會對保\n單受益人的期望造成一定的影響，因此有些保險人\n會於處理此類附約的給付申請時，要求受益人簽署\n一份棄權聲明或稱解除責任憑證，同意提前支付的\n保險利益數額會從將來的死亡保險金中扣除。"},{c:"3.3(d)",s:"某份保險單附加了提前支付死亡利益保障，當保險人支付提前支付死亡利益時，發現該\n份保單已轉讓給承讓人，那麼",o:["不可給付任何保單利益","承讓人需要簽署棄權聲明，方可提前支付死亡保險利益","承讓人可從利益獲得者處得到補償","與提前支付死亡保險利益的支付無關"],a:1,e:"如果保單已被轉讓，承讓人必須簽署同樣的棄權聲\n明 保單才會作出給付"},{c:"3.3.1",s:"以下哪項是危疾保險利益的賠償限制?\ni. 被診斷患上指明疾病\nii. 被診斷患上終末疾病並只有18個月或更短的壽命\niii. 有必要接受指明的醫療程序\niv. 僅適用60歲或以下的受保人",o:["i,ii","i,iii","ii,iii,iv","i,iii,iv"],a:1,e:"危疾保險利益的賠償限制被診斷患上終末疾病並只\n有12個月或更短的壽命，危疾保障僅適用於某歲數\n（如 80歲）或以下的人，只有選項i,iii是正確"},{c:"3.3.1",s:"以下哪些不是危疾保險利益附約的正確陳述？",o:["某些保險人可能選擇每月支付保險利益","危疾保障僅適用於某歲數或以下的人","受保事件發生後，受保保單所有人有時獲給付部分的死亡保險金","受保事件發生後，受保保單所有人總是須要繼續繳交保費"],a:0,e:"每月支付保險利益不屬危疾保險利益附約的選擇，\n受保事件發生後，危疾保險利益的受保保單所有人\n將獲給付死亡保險金的載明部分，若所界定喪失工\n作能力發生了三個月後，才會豁免保費所有續保保\n費，答案A不是危疾保險利益附約的正確陳述"},{c:"3.3.1",s:"危疾保險利益附約經常指明的疾病是︰",o:["中風","心臟病","肺癌","以上所有各項"],a:3,e:"以上都是危疾保險利益附約經常指明的疾病的例子"},{c:"3.3.1",s:"以下哪項正確描述危疾保險利益附約支付利益?",o:["賠償金額不可能涉及全數的保障額","醫療證明指只剩1年以下的預期壽命","醫療人員要發出醫療證明指明身體狀況及預期壽命","受保人死亡時才支付賠償"],a:2,e:"受保保單所有人將獲給付死亡保險金的其中一個\n條件，是必須有主診醫生發出的報告，以確認患者\n的\n健康狀況和（如屬終末疾病）其評估的預期壽命。"},{c:"3.3.1",s:"危疾保險利益附約支付利益的支付方法，會因為不同的保險人而有所不同。但一般往往\n是",o:["一整筆支付","按年分期支付","一連串的按月分期支付","在受保人死亡時一整筆支付"],a:0,e:"危疾保險利益附約支付利益的支付方法，一般往往\n是一整筆支付"},{c:"3.3.1",s:"壽險保單可能附加有一種附約，它向罹患/終末疾病，預期壽命只有12個月或以下的被保\n險保單所有人，支付預先定下的一部分死亡金。這類附約稱為﹕",o:["提前保額給付","死亡前利益","危疾保險利益","不治附約"],a:2,e:"當受保生命罹患/終末疾病，預期壽命只有12個月\n或以下的被保險保單所有人，支付預先定下的一部\n分死亡金。這類附約稱為危疾保險利益"},{c:"3.3.1",s:"人壽保險在以下哪種情況下會根據危疾保險利益附約支付利益?",o:["受保保單所有人罹患末期疾病，預計壽命只剩下十二個月或以下","受保保單所有人罹患不可痊癒疾病，預計壽命只剩下十二個月或以下","受保保單所有人罹患末期疾病或不可識別疾病，壽命期只剩下十二個月或以下","受保保單所有人在患上末期疾病六月內死於該病"],a:0,e:"當受保保單所有人罹患末期疾病，預計壽命只剩下\n十二個月或以下，會根據危疾保險利益附約支付利\n益"},{c:"3.3.1",s:"危疾附約",o:["診斷患上指明疾病","診斷患上終末疾病並只有12個月或更短的壽命","必要接受指明的醫療程序","以上各項皆是"],a:3,e:"以上各項皆是危疾附約給付死亡保險金的條件"},{c:"3.3.1",s:'危疾保險利益中"指明疾病"指:\ni. 傷殘\nii. 心臟相關疾病\niii.癌症\niv. 重要器官相關疾病',o:["i,ii, iii","ii,iii, iv","i,ii, iv","i,ii,iii ,iv"],a:3,e:'以上都可以是危疾保險利益中"指明疾病"'},{c:"3.3.1",s:"危疾保險利益，在下列情況不會獲得賠償？",o:["有關多重疾病和復發疾病(某一類疾病或屬例外)","受保人80歲之後","投保人為次標準風險","以上各項皆是"],a:3,e:"以上各項皆是危疾保險利益的保障限制，不會獲得\n賠償"},{c:"3.3.1(e)",s:"以下哪些不是危疾保險利益附約設定的保障限制？\ni) 危疾保障生效僅適用於某歲數以下的人\nii) 不適用於次標準風險；\niii) 一般可以長達5年的等候期\niv) 必須累積一定的現金價值",o:["i,ii","i,ii,iii","iii,iv","i,iii"],a:2,e:"危疾保險利益附約等候期是3個月或6個月，必須累\n積現金價值不是危疾保險利益附約的限制，選項(i\nii)及(iv)不正確"},{c:"3.3.1(e)",s:"以下哪些是危疾保險利益附約設定的保障限制？\ni)必須累積某數額或以上的現金價值\nii)危疾保障生效僅適用於某歲數以下的人\niii)多重疾病和復發性的疾病可能不會獲得給付，某一兩類疾病或屬例外\niv) 遂漸減少的自負額",o:["i,ii","ii,iii","i,iii,iv","i,iii"],a:1,e:"必須累積現金價值及自負額都不是危疾保險利益附\n約的限制，只有選項(ii)及(iii)正確"},{c:"3.3.1(e)",s:"以下哪些是危疾保險利益附約設定的保障限制？\ni) 可長達5年的可異議期\nii) 逐年減少的免賠額\niii) 等候期\niv) 危疾保障生效僅適用於某歲數以下的人",o:["i,ii","i,ii,iii","iii,iv","i,iii"],a:2,e:"可長達5年的可異議期及逐年減少的免賠額都不是\n危疾保險利益附約的限制，只有選項(iii)及(iv)\n正確"},{c:"3.3.1(e)",s:"一般而言，危疾保險利益附約的基本限制不包括",o:["適用於任何歲數人士","僅適用於標準風險","多重疾病和復發性的疾病可能不會獲得給付","以上所有各項"],a:0,e:"危疾保障僅適用於某歲數（如80歲）或以下的人，\n答案A不正確"},{c:"3.3.2",s:"以下哪項就長期護理利益的陳述正確?\ni. 通常設有180日的等候期\nii. 受保保單所有人在接受長期護理利益的期間，通常獲得豁免保費\niii. 已接受長期護理利益的受保保單所有人死亡，將支付全數的死亡保險金\niv. 受保保單所有人可選擇在家中由正式註冊的護理員護理",o:["i, iii","ii,iv","i,ii,iii","i,ii,iii,iv"],a:1,e:"通常在給付長期護理保險利益之前有一個為期90日\n的等候期。每月在護理院護理的利益為死亡保險金\n的某個百分比，正確描述只有ii,iv, 正確答案是B"},{c:"3.3.2",s:"以下哪項描述不適用於長期護理附約?\ni. 等候期一般是一至九個月\nii. 會扣除部分死亡保險金支付長期護理利益\niii. 在接受長期護理利益的期間會獲得豁免保費\niv. 必須在醫院接受護理",o:["i,ii","i,ii,iii","i,iv","ii,iii,iv"],a:2,e:"長期護理附約等候期一般是一至九個月"},{c:"3.3.2",s:"長期護理的等候期是",o:["30日","60日","90日","120日"],a:2,e:"長期護理的等候期是90日"},{c:"3.3.2",s:"在長期護理附約下，保險人要求被保人證明失去某些稱為(ADLs)，ADLs是指",o:["所有日常起居活動需要","任何日常活動需要","日常起居活動能力","債務的援助"],a:2,e:"受保保單所有人必須已經失去指定數目的日常起居\n活動能力 (activities of daily\nliving(ADLs)，才能確立長期護理的必要性 。"},{c:"3.3.2",s:"以下哪項對長期護理附約的描述是不正確?",o:["等候期一般是一至六個月","所支付的金額將會在保險金中扣除","在接受護理期間,通常保費會被豁免","必須在認可的護理院或在家中由正式註冊護理員護理"],a:0,e:"給付長期護理保險利益之前有一個為期90日的等候\n期。答案A不正確"},{c:"3.3.2",s:"當保險人按長期護理保險利益附約支付利益時，其原本的基本保費和附約保費將會？",o:["提高","暫停，但要在較後的時間繳還或扣除","於保險人支付利益時期豁免保費","減少百分之五十，並於康復後回復正常"],a:2,e:"受保保單所有人在接受長期護理利益的期間，通常\n都會獲得豁免保費，包括附約的保費及基本保險計\n劃的保費。"},{c:"3.3.2",s:"附加壽險保單的長期護理附約規定",o:["於死亡時支付雙賠保額","提供的付款與可予支付的保單毫無關係","由保險人支付認可護理院的費用","支付保單死亡保險金的某所述部份作長期護理的費用"],a:3,e:"長期護理附約利益屬預繳性質，已支付的保單利益\n會在死亡保險金扣除"},{c:"3.3.2",s:"在長期護理附約下，保險人要求被保人證明失去某些日常活動能力(ADLs)，ADLs是指",o:["日常起居活動能力 activities of daily Living","日常起居調整能力 adjustments of daily Living","日常起居囤積能力 accumulations of daily Living","囤積工作名單 accumulations of doing List"],a:0,e:"在長期護理附約下，保險人要求被保人證明失去某\n些日常活動能力(ADLs)，ADLs是指日常起居活動能\n力activities of daily Living"},{c:"3.3.2",s:"受保保單所有人何時可獲得長期護理(LTC)附約的利益？",o:["已證實為完全殘廢","失去日常起居活動能力","預期壽命不足兩年","受保保單所有人在家中由護理員護理"],a:1,e:"當受保保單所有人失去日常活動能力(ADLs)，可獲\n得長期護理(LTC)附約的利益"},{c:"3.3.2",s:"當受保保單所有人在接受長期護理期間，保險人通常在保費上作出什麼安排？",o:["增加保費","豁免保費","減少保費","利用現金價值繳交保費"],a:1,e:"當受保保單所有人在接受長期護理利益的期間，通\n常都會獲得豁免保費，包括附約的保費及基本保險\n計劃的保費。"},{c:"3.3.2",s:"受保保單所有人唯有在下列哪種情況下才可取得長期護理保險利益附約的條款 ?",o:["在昏迷期間","終身癱瘓","因為身體某種狀況而需要接受長期護理","罹患終末疾病，且預期壽命只有一年或以下"],a:2,e:"如因某些疾病而須接受長期護理的受保保單所有人\n，可獲支付死亡保險金的規定部分作為長期護理保\n險利益，在認可的護理院接受護理或在受保保單所\n有人的家中由正式註冊的護理員護理"},{c:"3.4",s:"如果一間人壽險公司打算提供醫療保險利益保障作為獨立的保單",o:["這在任何情況都不可能","這種做法必須透過另一間保險公司來完成","只有在該公司同時簽發壽險保單時這種做才可能","這公司必須獲得經營有關一般保險險種的授權"],a:3,e:"獨立形式發售的醫療保險單屬一般保險類別，這公\n司必須獲得經營有關一般保險險種的授權"},{c:"3.4",s:"保險人可能希望在其一般保險業務內,而非在其人壽保險業務內,提供醫療保險利益保障,\n這種安排",o:["在法律上是不可能的","須向政府支付特別保費税款","要獲得保險業監管局的特別許可","意味著保險人必須獲得經營疾病業務的授權"],a:3,e:"獨為一張醫療保險利益保障屬一般保險保單，保險\n人須獲保險業監管局授權經營有關險種業務"},{c:"3.4",s:"一份典型的醫療保險，不大可能接受以下哪項原因的「醫療開支」?",o:["道路交通意外導致的住院醫療","出院後一個月內的門診病人跟進護理","由主診醫生建議的私人護理","除去先天性面部皮膚疤痕的整容手術"],a:3,e:"除去先天性面部皮膚疤痕的整容手術不大可能接受\n以下哪項原因的「醫療開支」"},{c:"3.4",s:"以下哪項不可能為醫療保險利益基本計劃保障之內",o:["住院病人專科醫生費用","住院病人麻醉師及手術室費用","遭謀殺及遭強姦之受害人的家庭所接受的心理輔導費用","出院後6週內的跟進護理費用"],a:2,e:"精神病醫療費用大可能接受以下哪項原因的「醫療\n開支」"},{c:"3.4",s:"一份典型的醫療保險中，以下哪一種情況所引致的醫療開支最可能受到保障？",o:["保單生效前既有的疾病","懷孕及生育","因交通意外事故引致的受傷","因愛滋病或免疫力系統不全引致的治療費用"],a:2,e:"因交通意外事故引致的受傷引致的醫療開支最可能\n受到保障"},{c:"3.4",s:"一間保險公司將醫療保險利益納入一般保險保單而非人壽保險保單內，則",o:["這在法律上是不可能的","需要支付特別保費稅款","需持有相關的經營牌照授權","需由保險業監管局特別許可"],a:2,e:"一間保險公司將醫療保險利益納入一般保險保單而\n非人壽保險保單內，則需持有相關的經營牌照授權"},{c:"3.4(a)",s:"如果保險人發出一個獨立的醫療保險保單,該保單的保障範圍包括:\ni. 住院費用\nii.私人護理\niii.外科醫生ˑ麻醉師及手術室費用\niv. 人壽保險",o:["i,ii, iii","i,ii, iv","ii,iii, iv","以上各項都是"],a:0,e:"人壽保險不是醫療保險保單的保障範圍，只有i,ii\n, iii正確"},{c:"3.4(b)",s:"下列哪項是「自選醫療計劃」的特點？",o:["它屬於一般保險保單","為保障提高限額","需要繳付額外的保費","以上各項皆是"],a:3,e:"以上各項皆是醫療保險保單的「自選醫療計劃」的\n特點"},{c:"3.4(b)",s:"醫療保障可以是基本計劃的附約，也可為自選醫療計劃；相對前者，後者的保障範圍",o:["額外增加保障","提高保障之金額上限","撤消附加利益所定的除外責任","包括以上各項"],a:1,e:"醫療保障可以是基本計劃的附約，也可為自選醫療\n計劃，提高保障之金額上限"},{c:"3.4(c)",s:"一份醫療保險利益一般保障範圍包括",o:["保單生效前已患的疾病","涉及吸毒或其他濫用藥物","先天性畸形的治療","因為意外而造成的醫療開支"],a:3,e:"一份醫療保險利益一般保障範圍包括因為意外而造\n成的醫療開支"},{c:"3.4(c)",s:"下列哪項是醫療保險利益之除外責任？\ni) 保單生效前既存的狀況\nii) 生育的開支\niii) 因道路意外而引致的醫療費用\niv) 因愛滋病而有關的症狀",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"因為意外而造成的醫療開支不屬醫療保險利益之除\n外責任，選項iii不正確"},{c:"3.4(c)",s:"如果人壽保險人簽發一份醫療保險利益附約，該份保單便會受到某些除外責任的約束，\n下列哪項不大可能屬於這類除外責任?",o:["保單生效前既存的狀況","交通意外中受傷","濫用藥物或其他物質","與懷孕或生育有關的開支"],a:1,e:"因交通意外事故引致的受傷引致的醫療開支是受到\n保障"},{c:"3.4.1",s:"自願醫保計劃認可產品下標準計劃必須包括的保障項目?",o:["基本保障","額外保障","其他保障","以上所有各項"],a:0,e:"自願醫保計劃認可產品下標準計劃必須包括基本保\n障"},{c:"3.4.1",s:"以下哪一項不是《自願醫保計劃下保險公司的實務守則》的涵蓋範圍?",o:["轉移安排","保障條款","銷售及推廣","售後服務"],a:1,e:"保障條款不是《自願醫保計劃下保險公司的實務守\n則》的涵蓋範圍"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自\n願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願\n選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民\n自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認可的個人償款\n住院保險產品，供消費者自願選購，團體保險並不\n適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫療服務的消費\n者提額外的保險計劃選擇"},{c:"3.4.1(b)",s:"湯姆在自願醫保計劃下，一共購買了3份保單，受保人分別是自己，妻子及兒子，繳付的\n認可產品的合資格保費，可作薪俸稅和個人入息課稅的稅務扣減。湯姆的合資格保費的\n全年稅務扣減上限為多少?",o:["4000","8000","12000","24000"],a:3,e:"自願醫保每名受保人稅務扣減上限為8000元,為4名\n指明親屬購買自願醫保，最高可獲8000x3=24000元\n稅務扣減"},{c:"3.4.1(b)",s:"湯姆在自願醫保計劃下，一共購買了4份保單，受保人分別是自己，妻子及兒子，繳付的\n認可產品的合資格保費，可作薪俸稅和個人入息課稅的稅務扣減。湯姆的合資格保費的\n全年稅務扣減上限為多少?",o:["8000","16000","24000","32000"],a:3,e:"自願醫保每名受保人稅務扣減上限為8000元,\n為4名指明親屬購買自願醫保，最高可獲8000x4=32\n000元稅務扣減"},{c:"3.4.1(c)(iv)",s:"根據《自願醫保計劃下保險公司的實務守則》，以下哪項不屬該守則的要求?",o:["自願醫保的產品提供者應根據政府公布的稅項扣減細節，在銷售過程中及接獲查詢時\n，讓消費者知道認可產品的稅項扣減資格。","自願醫保的產品提供者在銷售過程中及接獲查詢時，應向消費者解釋，不同計劃的病\n房級別選擇的限制。","自願醫保的產品提供者在銷售過程中及接獲查詢時，應向消費者解釋，不同計劃的保\n障地域範圍限制的，並解釋所有保障均不適用於全球","自願醫保的產品提供者應確保所有銷售及推廣資料，均為準確及非誤導性、備有中英\n文版本、用字淺白及完整。"],a:2,e:"自願醫保的不同計劃的保障地域範圍限制，所有保\n障是適用於全球的"},{c:"3.4.1(iii)(7)",s:"以下哪項是自願醫保計劃下標準計劃靈活計劃中，基本保障，額外保障及其他保障的定\n義原則?\n1. 標準計劃 - 基本保障:必須包括，額外保障:不可包括，其他保障 : (1)\n2. 靈活計劃 - 基本保障:必須包括，額外保障: (2)，其他保障 : (3)",o:["(1)不可包括,(2)必須包括,(3)可選擇包括或不包括","(1)必須包括,(2)必須包括,(3)可選擇包括或不包括","(1)可選擇包括或不包括,(2)必須包括,(3)可選擇包括或不包括","(1)可選擇包括或不包括, (2)必須包括, (3)不可包括"],a:2,e:"詳細可參閱研習資料手冊參考章節\n3.4.1(iii)(7)自願醫保標準計劃和靈活計劃定義\n原則說明表格"},{c:"3.4.2",s:"以下哪項屬醫療保險業務指引的目的適用範圍?",o:["個人及團體業務","自願醫保認可產品","其他種類醫療保險業務","以上各項皆是"],a:3,e:"所有醫療保險業務指引適用於所有醫療保險業務"},{c:"3.4.2",s:"醫療保險業務指引 (指引 31)",o:["具有法律效力","不具有法律效力","可能具有法律效力","視乎情況才具有法律效力"],a:1,e:"醫療保險業務指引 (指引 31)是不具有法律效力"},{c:"3.5",s:"為人壽保險的緣故,判斷一項風險的可保性的基本因素是",o:["投保金額","準受保生命的年齡","準受保生命的健康狀況","準受保生命的性別"],a:2,e:"準受保生命的健康狀況為人壽保險的緣故,判斷一\n項風險的可保性的基本因素"},{c:"3.5",s:"為人壽保險的緣故,判斷一項風險的可保性的基本因素是",o:["投保金額","準受保生命的年齡","準受保生命的健康狀況","準受保生命的性別"],a:2,e:"判斷人壽保險一項風險的可保性的基本因素是準受\n保生命的健康狀況"},{c:"3.5.1",s:"以下哪項是保證可保選擇的特點?",o:["限制","非自動獲得","指定事件","以上各項皆是"],a:3,e:"以上各項皆是保證可保選擇的特點"},{c:"3.5.1",s:"保證可保利益的附約特點",o:["限制","指定事件","暫時的保障","以上各皆是"],a:3,e:"以上都是保證可保利益的附約特點"},{c:"3.5.1",s:"以下哪兩項是對保證可保利益的陳述是正確的?\ni. 增額保險的金額不能超過原有保單的面額\nii. 保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明\niii. 保單所有人必須提供持續良好的健康證明\niv. 該項權利於在受保生命達到40歲之後才可行使",o:["i,ii","i iii","ii,iii,iv","iii,iv"],a:0,e:"保證可保利益的保單所有人毋須提供持續良好的健\n康證明，該項權利也可能限於在受保生命達到某一\n年齡，一般為40歲之前才可行使。選項iii及iv不\n正確"},{c:"3.5.1",s:"保證可保利益在某些情況下亦稱為",o:["終身保證利益","預批購買選擇","終身可保選擇","保證受保利益"],a:1,e:"保證可保利益在某些情況下亦稱為預批購買選擇"},{c:"3.5.1",s:"以下哪項是一種權利，保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保\n證明?",o:["不可異議可保選擇","延期保險選擇","增加保險選擇","保證可保利益"],a:3,e:"保證可保利益即是保單所有人有權在指定的備擇日\n期購買增額保險，無需遞交可保證明"},{c:"3.5.1",s:"壽險保單容許保單持有人，在指定的日期購買增額保險，而毋須提供可保證明，稱為",o:["可保性選擇 (Insurability Option)","保證可保利益 (Guaranteed Insurability Benefit)","保證保險選擇 (Guaranteed Insurance Option)","不可拒絕可保選擇 (Non-rejected Insurability Option)"],a:1,e:"壽險保單容許保單持有人，在指定的日期購買增額\n保險，而毋須提供可保證明，稱為保證可保利益又\n稱預批購買選擇"},{c:"3.5.1",s:"壽險保單受GIB的條文所限制，是以下哪項的縮寫?",o:["授權保險選擇 (Granted Insurance Option)","全能保險選擇 (General Insurance Option)","保證保險選擇 (Guaranteed Insurance Option)","保證可保利益 (Guaranteed Insurability Benefit)"],a:3,e:"壽險保單受GIB的條文所限制是保證可保利益\n(Guaranteed Insurability Benefit)的縮寫"},{c:"3.5.1",s:"保證可保利益在某些情況下亦稱為",o:["終身保證利益","預批購買選擇","終身可保選擇","保證受保利益"],a:1,e:"保證可保利益又稱預批購買選擇"},{c:"3.5.1",s:"有關保證可保選擇，容許受保人作出購買增額保障的選擇，以下那項描述是不正確的?",o:["自動獲得增額保障的選擇","如不及時作出選擇，便會喪失權利","部分保險人於備擇日期內提供定期壽險","只可在指定限期內作出選擇"],a:0,e:"保單所有人如果錯過了行使已觸發的選擇權以購買\n增額保障的話，就會喪失該次權利，答案A不正確"},{c:"3.5.1",s:"壽險保單容許保單持有人，在指定的日期購買增額保險，而毋須提供可保證明，稱為",o:["可保性選擇 (Insurability Option)","保證可保利益 (Guaranteed Insurability Benefit)","保證保險選擇 (Guaranteed Insurance Option)","不可拒絕可保利益 (Non-rejected Insurability Benefit)"],a:1,e:"壽險保單容許保單持有人，在指定的日期購買增額\n保險，而毋須提供可保證明，稱為保證可保利益"},{c:"3.5.1(a)",s:"保證可保利益的定義為",o:["保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明","保單所有人有權在任何時候購買增額保險，無需遞交可保證明","保單所有人有權在指定的備擇日期購買增額保險，必需遞交可保證明","保單所有人有權在任何時候購買增額保險，必需遞交可保證明"],a:0,e:"保證可保利益的保單所有人有權在指定的備擇日期\n購買增額保險，無需遞交可保證明"},{c:"3.5.1(a)",s:"保證可保利益有時附加於人壽保險單中,意思是",o:["附加保費以接受次標準風險","付款以符合索償時的限制保額","於特定日期時自動提供保險","毋須提供可保性證明下購買增額保險"],a:3,e:"保單所有人有權在指定的備擇日期或稱行權日期購\n買增額保險，而毋須提供可保證明"},{c:"3.5.1(b)",s:"以下哪項是保證可保利益的附約限制?",o:["到期而未行使的選擇權將作廢","只可在備擇的日期中行使有關權力","超額保險不能超過原有的保險","以上皆是"],a:3,e:"以上皆是保證可保利益的附約限制"},{c:"3.5.1(c)",s:"已購買保證可保利益的保單所有人在指定的備擇日期沒有作出增額的選擇，會",o:["喪失未來所獲保證增額的權利","喪失有關增額的權利","可於任何時間再行使權利","自動行使權利"],a:1,e:"保單所有人如果錯過了行使已觸發的選擇權以購買\n增額保障的話 ，就會喪失該次權利"},{c:"3.5.1(c)",s:"保證可保利益",o:["保單所有人有權在指定的備擇日期購買增額保險","備擇日期沒有作出購買增額保障的選擇，就會喪失該項約定的權利","增額保險的金額不能超過原有保單的面額","以上各項皆是"],a:3,e:"以上各項皆是保證可保利益的限制"},{c:"3.5.1(d)",s:"已購買預批購買選擇的保單所有人，可在以下哪個或哪些指定的備擇日期作出增額的選\n擇？",o:["結婚","子女的出生","特定的日子或特定的事件","以上各項皆是"],a:3,e:"以上各項皆是保證可保利益的限制"},{c:"3.5.1(e)",s:"保證可保權益是指保單所有人在指定時間內可提高保險金額而毋須提供可保證明。在行\n使期間保單所有人若不幸死亡",o:["保險金額立即增加","取回保單原有保額","部份保險人會自動提供定期壽險額外保障","死者親人可於三十天內向保險公司辦理手續"],a:2,e:"部分保險人在受保保單所有人有權行使購買增額保\n險選擇權的期間，自動提供定期壽險。如果後者在\n完成有關行權手續前死亡，也可得到額外的\n定期保險 保障。"},{c:"3.5.1(f)",s:"如保險已加有豁免保費及預批購買選擇附約，而保單所有人在可以行使購買權時發現遭\n致傷殘，在此情況下，下列哪項為正確？",o:["預批購買選擇會被取消","豁免保費附約會被取消","豁免保費及保證可保利益附約會被取消","可自動獲得該額外保障，豁免保費附約也可以豁免所有保費"],a:3,e:"受保保單所有人在有權行使購買增額保險選擇權時\n已經成了殘疾人，他將會自動獲得該項額外保障。\n並豁免保費，直至受保保單所有人康復或死亡"},{c:"3.5.1(f)",s:"如果一項保單有「保證可保權益」附約，被保險人可選擇增額的保障，而且保證接納；\n如果該份保單同時附帶「豁免保費支付」附約，而被保險人在決定行使該選擇權時，遭\n致殘障，那麼",o:["有關「保證可保權益」會取消","增額的保障會自動生效","直至被保險人康復，才會提供增額的保障","被保險人可要求增額的保障，但可能獲拒絕"],a:1,e:"受保保單所有人在行使購買增額保險選擇權時已經\n成了殘疾人，他將會自動獲得該項額外保障。\n豁免保費附約也規定可以豁免所有保費，直至受保\n保單所有人 康復或死亡為止。"},{c:"3.6",s:"通貨膨脹足以降低貨幣的購買力，以下哪項人壽保險計劃類型需要嚴加注意?",o:["只有儲蓄壽險","只有終身壽險","只有殘疾收入保險利益附約","所有人壽保險計劃"],a:3,e:"通貨膨脹足以降低貨幣的購買力，因此，它是任何\n指明保額的長期保險必須考慮的一個重要因素。"},{c:"3.6",s:"通貨膨脹可能會重大的降低壽險利益的購買能力，為了解決這個難題而設的特定條文或\n獨立的附約稱為",o:["購買能力條文","生活指數調整利益利益","通脹條文","通脹調整條文"],a:1,e:"生活指數調整利益利益條文是抵銷將來因通貨膨脹\n可能會重大的降低壽險利益的購買能力"},{c:"3.6",s:"通貨膨脹對下列哪項保單的實質價值帶來負面影響？\ni) 保額\nii) 保費\niii) 利益\niv) 現金價值",o:["i , iv","i , iii","i, ii , iii","i, iii , iv"],a:1,e:"通貨膨脹足以降低貨幣的購買力，它是任何指明保\n額長期保險必須考慮的一個重要因素。選項i ,\niii正確"},{c:"3.6",s:"由於通貨膨脹關係，受保保單所有人擔心保額會受影響，他可以怎樣辦？",o:["購買一份與綜合消費者物價指數掛鈎的保險計劃","購買附有保證可保權益的保險計劃","購買分紅保單以加大將來的保額","預先購買高保障的保險計劃"],a:0,e:"由於通貨膨脹關係，受保保單所有人擔心保額會受\n影響，他可以購買一份與綜合消費者物價指數掛鈎\n的保險計劃"},{c:"3.6",s:"通貨膨脹會降低貸幣的購買力，哪類保險應對此嚴加注意？",o:["終身壽險","儲蓄壽險","殘疾收入保險","所有指定保額的長期保險"],a:3,e:"通貨膨脹足以降低貨幣的購買力，因此\n，它是任何指\n明保額的長期保險必須考慮的一個重要因素。"},{c:"3.6.1",s:"以下哪項是「生活指數調整利益」附約的正確描述",o:["對抗經濟周期的影響","被保險人身故後提供一筆過的保險利益","紅利派發低於一般水平時，保險人將提供補充紅利","以上都不正確"],a:3,e:"「生活指數調整利益」附約增加的數目是跟綜合消\n費物價指數掛鈎的，只會按通漲調整，通縮情況下\n不會下降。"},{c:"3.6.1",s:"生活指數調整利益附約，會定期增加保險賠償的利益，以下哪項是正確的？",o:["按照指定的方式增加","每年增加保額的5%","跟隨特定指數或獨立指數(例如綜合消費者物價指價)掛鈎","按照保險公司的保費的百分比增加"],a:2,e:"生活指數調整利益附約，會定期增加保險賠償的利\n益，並跟隨特定指數或獨立指數(例如綜合消費者\n物價指價)掛鈎"},{c:"3.6.1",s:"稱為生活指數調整利益的附約的原意是",o:["對抗經濟週期的影響","對抗通貨膨脹和通貨收縮兩者的影響","為罹患終末疾病的人發放部份保額","上面各項都不是答案"],a:3,e:"對抗經濟週期的影響及通貨收縮，為罹患終末疾病\n的人發放部份保額等，都不是生活指數調整利益的\n附約的原意，以上各項都不是答案"},{c:"3.6.1",s:"包含了生活指數調整利益(COLA)的保單條款,為遭致殘疾的受保保單所有人提供周期性增\n加的殘疾收入保險利益,而增加的數目一般相等於",o:["每年增加百分之五","通貨膨脹","綜合消費者物價指數","受保保單所有人薪金調整的幅度"],a:2,e:"生活指數調整利益(COLA)的保單條款,為遭致殘疾\n的受保保單所有人提供周期性增加的殘疾收入保險\n利益,而增加的數目一般相等於綜合消費者物價指\n數"},{c:"3.6.1",s:"遭致殘疾的受保保單所有人之日常醫療費用會因通貨膨脹而不斷增加,哪項保單條款可抵\n銷這項影響?",o:["意外死亡保險利益","豁免保費利益","生活指數調整利益","保證可保權益"],a:2,e:"遭致殘疾的受保保單所有人之日常醫療費用會因通\n貨膨脹而不斷增加,生活指數調整利益條款可抵銷\n這項影響"},{c:"3.6.1",s:"以下哪三項是對生活指數調整利益附約的正確描述？\ni)等候期相等於1至6月不等\nii)它提供對被保人的殘疾收入增加的保障\niii)當被保人遭致殘疾期間，其殘疾收入會隨特定指數(例如綜合消費者物價指數)增加\niv)被保險保單持有人於殘疾後，其殘疾收入會定期增加",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:3,e:"生活指數調整利益附約沒有等候期，選項i不正確"},{c:"3.6.1",s:"稱為生活指數調整利益的附約的原意是",o:["對抗物價通脹及物價通縮","對罹患終末疾病的人支付部份保額","於保險人盈利低於一般水平時，當補充紅利","以上各項皆不是"],a:3,e:"生活指數調整利益利益條文只會按通漲增加保險利\n益，所以以上情況都不正確"},{c:"3.6.1",s:"COLA的英文全寫是",o:["壽險成本調整 Cost of Life Insurance Adjustment","壽險/年金合同的補償 Compensation of Life / Annuity Contract","壽險利益補償 Compensation of Life Assurance Benefit","生活指數調整利益 Cost of Living Adjustment"],a:3,e:"COLA的英文全寫是生活指數調整利益 Cost of\nLiving Adjustment"},{c:"4",s:"在死亡索償中,在哪種情況下,死因對索償來說屬於重要事項?",o:["該份保單設有意外死亡保險利益附約","自殺條款可能仍然生效","受益人謀殺受保生命","以上所有各項"],a:3,e:"在死亡索償中,在以上所有各項情況下,死因對索償\n來說屬於重要事項"},{c:"4.1",s:"人壽保險單是一份重要的合約，該合約是一份完整合約，以下哪項有關完整合約的描述\n是正確的?\ni.完整的合約包括保險單、任何夾附的附約及夾附的投保單複印本\nii.保險公司某些指定的高級職員才有權改保險合約\niii.必須得到保單所有人的同意才可修改合約內容\niv.保單合約已經是一份完整的合約，並無需要附加其他的檔案",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保單複印本構成，選項iv不正確"},{c:"4.1",s:"以下哪項關於「完整合約」條款的描述是正確的？",o:["在人壽保險索償時毋需出示保單的正本","除非得到保單所有人的同意，否則不能對保險合約作出任何修改","保險公司的指定高級職員有權對保單作出更改","保單的內容已是一份完整的合約，並不包括其他文件"],a:1,e:"「完整合約」條款其中一個定義是，除非得到保單\n所有人的同意，否則不能對保險合約作出任何修改"},{c:"4.1",s:"以下哪項就人壽保險保單文件的描述是正確的?",o:["索償出現時，死亡保險金只可以支付給保單所有人","只有在索償時才適用","完整的保險合約由保險單、任何夾附的附約及夾附的投保單複印本構成","以上各項皆正確"],a:2,e:"完整的保險合約由保險單、任何夾附的附約\n及夾附的投保單複印本構成，只有答案C描述正確"},{c:"4.1",s:"除非得到保單所有人的同意，否則不能修改該合約，這是包括在人壽保險合約的哪一項\n條款?",o:["不可異議條款","完整合約條款","不能作廢條款","寬限期條款"],a:1,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保複印本構成，又稱為封閉式合約，確保投保資料\n無誤"},{c:"4.1",s:"一個典型的人壽保險中「完整合約」條款，以下哪項是正確?",o:["保險公司提出便可修改","只有保單持有人同意才可修改","須在14天內提交保單","必須全份合約修改"],a:1,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保單複印本構成。「完整合約」條款是非常重要的\n，因為除非得到保單所有人的同意，否則保險人不\n能修改該合約。"},{c:"4.1",s:"以下哪項關於「完整合約」條款的描述是不正確的？",o:["完整合約包括保單正本、任何夾附的附約及投保單的複印本","只有在保單所有人同意下才可更改保單","只有保險公司的指定高級職員才有權對保單作出更改","保單的內容已是一份完整的合約，並不包括其他文件"],a:3,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保單複印本構成。"},{c:"4.1",s:"下列哪一項有關香港典型壽險保單「完整合約」條款的陳述是不正確的？",o:["一份完整的合約包括保險單、任何夾附的附約以及夾附的投保單的複印本","除非得到保單所有人同意，否則不能對合約作出任何修改","儘管保險人不同意，保單所有人仍有權利輕微地修改合約","只有保險公司中指明的高級職員才有權更改合約"],a:2,e:"「完整合約」條款規定：除非得到保單所有人的同\n意，否則保險人不能修改該合約。答案C不正確"},{c:"4.1",s:"根據人壽保單「完整合約」的條款中，除以下情況外，均不得對保險合約作出任何的修\n改？",o:["任何情況下均不得修改","只可在保單持有人同意下","保單生效後首兩年內","除非有關保單被取消，並由另外一份保單取代"],a:1,e:"「完整合約」條款是非常重要的，因為除非得到保\n單所有人的同意，否則保險人不能修改該合約。"},{c:"4.1",s:"根據典型壽險保單的完整合約條款，唯一有權更改合約的人是",o:["保單所有人","高等法院的法官","保險中介人","保險公司指明的高級職員"],a:3,e:"只有保險公司中某些指定的高級職員才有權更改保\n險合約，除非得到保單所有人的同意，否則不能修\n改該合約。"},{c:"4.1",s:"一個典型的人壽保險中「完整合約」條款，以下哪項或哪些是正確?",o:["合約中包括保單、任何夾附的附約及夾附的投保單的複印版本","只有由指明保險公司高級職員才可修改合約","除非得保單持有人同意，否則不得更改合約條款","以上各項皆是"],a:3,e:"以上各項皆是人壽保險中「完整合約」條款的正確\n描述"},{c:"4.1",s:"在人壽保單中的完整合約條款下，更改合約",o:["是完全不可能的","在保險人同意下便可作出","要在保單所有人同意下才可作出","不論保險人是否同意都可隨意作出"],a:2,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保單複印本構成。「完整合約」條款是非常重要的\n，因為除非得到保單所有人的同意，否則保險人不\n能修改該合約。"},{c:"4.1",s:"下列哪項不是「完整合約」條款的特點？",o:["合約有效期可持續數十年","所有保險公司中的職員可獲權更改保險契約","指定的保險公司高級職員可獲權更改保險契約","完整保單合約包括保險單、任何夾附的附約及投保單的複印本"],a:1,e:"「完整合約」條款規定：只有保險公司中某些指定\n的高級職員才有權更改保險合約，答案B不正確"},{c:"4.1",s:"以下哪項屬於分紅保單的紅利選擇?\ni. 用以購買保險公司股份\nii. 以現金方式支付紅利\niii.如果保單所有人沒有作出紅利選擇，保單會採用「自動紅利選擇」 的做法\niv. 分紅保單於生效一段指定時間後可轉換成不分紅保單",o:["iii,iv","i,ii,iii","ii,iii","i,ii,iv"],a:2,e:"如果保單所有人沒有從上述各項中作出選擇，大多\n數保單會採用一種稱為「自動紅利選擇」的方式。"},{c:"4.1",s:"如果在一份保險合約中具有的權益形容成復歸 ，這表示",o:["權益在繳交所有保費後才支付","權益在事件是偶遇的情況下出現時才支付","權益在繳交最後一期的保費後才支付","以上各項都不是"],a:3,e:"如果在一份保險合約中具有的權益形容成復歸，例\n如英式紅利通常是復歸的，即只於支付保單利益時\n一起支付，以上所有皆不正確。"},{c:"4.1",s:"在人壽保單的分紅中，下列哪項是不常見的方法？",o:["以現金支取","購買增額保險","在保險公司中積存以賺取利息","購買有關保險公司之股份"],a:3,e:"購買有關保險公司之股份不是在人壽保單的分紅處\n理方法"},{c:"4.1",s:"分紅人壽保險下的現金紅利，通常何時須支付給保單所有人？",o:["即時","按照保險人決定的時間","如果他作出書面要求，便會即時成為可動用資產","只有在需要支付全部保單利益的時候"],a:0,e:"分紅人壽保險下的現金紅利，通常是即時支付給保\n單所有人"},{c:"4.1",s:"採用英式壽險方式而非美式壽險方式的保單，較有可能取以下兩種用詞：\ni) 保單紅利\nii) 有利潤保單\niii) 分紅保單\niv) 復歸紅利",o:["i, ii","ii, iii","iii, iv","ii, iv"],a:3,e:"採用英式壽險方式而非美式壽險方式的保單，較有\n可能取以下兩種用詞是有利潤保單及復歸紅利"},{c:"4.1",s:"一名保險單持有人在保單中持有擁有權，然而有某些權益只會在較後時間才可享有的，\n可稱之為",o:["遞延權益","延期權益","預期權益","復歸權益"],a:3,e:"一名保險單持有人在保單中持有擁有權，然而有某\n些權益只會在較後時間才可享有的，可稱之為復歸\n權益"},{c:"4.1",s:"如保單所有人沒有註明紅利的選擇，保險人會自動為保單所有人將紅利存放以賺取利息\n或",o:["以現金支付","用以繳付未來保費","用以購買清繳增額保險","購買一年期的定期壽險"],a:2,e:"購買清繳增額保險及紅利存放保險人以賺取利息屬\n自動紅利選擇"},{c:"4.1",s:"以下哪項對壽險保單的「自動紅利」選擇的陳述是正確的？",o:["保證紅利的分配方式","紅利分配方式總是得一種","所有保單所有人均沒有紅利分配方式的選擇權","除非保單所有人指明選擇，否則便會採用一項分配方式"],a:3,e:"如果保單所有人沒有從上述各項中作出選擇，大多\n數保單會採用一種稱為「自動紅利選擇」的方式項\n選擇，將紅利存放在保險人處以賺取利息，或購買\n一項清繳增額保險。"},{c:"4.1",s:"以下哪項關於紅利給付不正確？",o:["可以現金即時給付","存於保險人處以賺取利息",'如果沒有作出選擇,保險人會採用"自動紅利選擇"',"如果沒有作出選擇,保單所有人將會喪失該紅利"],a:3,e:"如果保單所有人沒有從上述各項中作出選擇，大多\n數保單會採用一種稱為「自動紅利選擇」的方式項\n選擇，將紅利存放在保險人處以賺取利息，或購買\n一項清繳增額保險。答案D不正確"},{c:"4.1",s:"保單所有人何時才可動用保單中之˹現金紅利˼？",o:["即時","由保險人決定","保單所有人以書面申請","提取保險金的時候"],a:0,e:"保單所有人即時可動用保單中之˹現金紅利˼"},{c:"4.2",s:"以下有關不可異議條款，哪項陳述是不正確的？",o:["保單生效兩年後即不可異議","保單生效首兩年為可異議期","根據香港法律，即使是有欺詐的情況存在都不可以推翻該條款","該條款規定了一段可異議期"],a:2,e:"無論保單生效多久，存在欺詐的情況都可以推翻保\n單"},{c:"4.2",s:"一項典型的「不可異議」條款，為其目的訂下兩年的期限，該期限稱為",o:["無訴訟期","不可異議期","可異議期","超出期"],a:2,e:"可異議期是根據「不可異議」條款，訂下兩年的期\n限，保險人可在此期間內對保單提出質疑或反對"},{c:"4.2",s:"按照香港普遍採用的「不可異議條款」，儘管違反「最高誠信原則」(假設按照香港法律\n)，保險人對以下哪項仍不可能拒絕有關之死亡索償？",o:["保單生效了只有一年","保單生效了20個月,但死亡6個月後才向保險人索償","保單生效了4年，違反最高誠信原則涉及故意隱瞞有重要意義的的醫療資料","保單生效了4年，違反最高誠信原則涉及到沒有披露重要資料，而投保人真誠地認為此\n資料是無關的"],a:3,e:"不可異議條款規定，保險合約於受保生命在世時從\n保單發出日起計已生效了兩年後，保險人不會對該\n合約提出異議或質疑，答案D的情況保險人仍不可\n能拒絕有關之死亡索償"},{c:"4.2",s:"一款典型的不可異議條款，為其目的訂下兩年的限期，該限期稱為",o:["無訴訟期","不可異議期","可異議期","超出期"],a:2,e:"一款典型的不可異議條款，為其目的訂下兩年的限\n期，該限期稱為可異議期"},{c:"4.2",s:"一名男子以免體驗的方式安排一份人壽保險單，並無意地誤導了保險人其健康狀況，如\n當時披露這些事實，保險人是不會提供保險。這名男子死去及真相被發現，在此情況下\n，下列哪項是不正確的？",o:["無論死亡何時出現,保險人有權推翻合約","如死亡於兩年內發生,保險人可推翻合約","如死亡於兩年後發生,保險人便不可異議","如不涉及欺詐,保險人很難不承認保單"],a:0,e:"不可異議條款規定，保險合約於受保生命在世時從\n保單發出日起計已生效了兩年後，保險人不會對該\n合約提出異議或質疑，除非沙及欺詐行為，答案A\n不正確"},{c:"4.2",s:"根據香港法律，下列哪項有關不可異議條款的陳述是正確的？",o:["壽險保單生效兩年便變為不可異議","被保險人的欺詐行為可推翻該項不可異議條款","受保生命必須在異議期內仍然生存","以上所有各項"],a:3,e:"以上所有各項皆是不可異議條款的正確陳述"},{c:"4.2",s:"下列有關不可異議條款陳述不正確的是？",o:["保單過兩年變不可異議","保單在首兩年仍是不可異議","如投保人違法最高誠信，保單過兩年仍不可異議","若保單生效不足兩年，保險人可使保單無效"],a:1,e:"保單在首兩年仍是屬可異議期，保險人可以對合約\n提出異議。答案B不正確"},{c:"4.2",s:"不可異議條款規定保險人不能對保單有效性提出異議，該可異議期為",o:["十二個月","三個月","二年","一個月"],a:2,e:"不可異議條款規定保險人不能對保單有效性提出異\n議，該可異議期為兩年"},{c:"4.2",s:"某項保單條文規定受保生命仍然生存期間，保單已經生效最少兩年的話，不涉及任何欺\n詐行為的情況下，保險人不能以違反最高誠信原則為理由而推翻合約 ，稱為",o:["復效條款","不能作廢條款","不可異議條款","完整合約"],a:2,e:"某項保單條文規定受保生命仍然生存期間，保單已\n經生效最少兩年的話，不涉及任何欺詐行為的情況\n下，保險人不能以違反最高誠信原則為理由而推翻\n合約，稱為不可異議條款"},{c:"4.2",s:"假設一份人壽保險保單的被保人仍然生存，保險合約生效的2年後，如投保人沒有涉及任\n何欺詐行為，保險人並不可以以違反最高誠信的規則，推翻有關合約，這是基於",o:["不可作廢條款","不可異議條款","復效條款","超越期條款"],a:1,e:"保險合約生效的2年後，如投保人沒有涉及任何欺\n詐行為，保險人並不可以以違反最高誠信的規則，\n推翻有關合約，這是基於不可異議條款"},{c:"4.2",s:"由保單生效至不可異議期是2年，2年後保單仍然可異議是因為",o:["死亡原因是意外事故","受保人死亡是由自殺引致","涉及欺詐","被保人在2年期間過去前已經死亡"],a:2,e:"根據香港法律，若證實索償人或被保險人曾作欺詐\n行為，他們便不能依賴不可異議條，保險人任何時\n候都可以對保險合約的有效性提出異議。"},{c:"4.2",s:"不可異議條款包括：\ni)保險合約生效2年後，保險人不能對合約的有效性提出爭議\nii)受保保單所有人必須在保險合約生效首2年內仍然生存\niii)按照香港法律：若證實存在欺詐行為，保險人便可對保險合約的有效性提出爭議\niv)按照香港法律：若證實存在欺詐行為，保險人亦不可對保險合約的有效性提出爭議",o:["i 及iii","i及iv","i, ii及iii","i, ii及iv"],a:2,e:"根據香港法律，若證實索償人或被保險人曾作欺詐\n行為，他們便不能依賴不可異議條，保險人任何時\n候都可以對保險合約的有效性提出異議。選項iv不\n正確"},{c:"4.2",s:"一個人購買免體檢保險，他無意地誤導了保險人，若將事實表明，他的身體狀況是得不\n到保障的，後來他死亡並被知道真相，下列哪項在此情況下為不正確呢？",o:["在任何情況下也不得異議","若保單生效不足兩年，保險人可使保單無效","若保單生效兩年，保險人便不可異議該保單","保單生效已兩年，因並非欺詐情況，保險人很難不承認保單"],a:0,e:"不可異議條款規定 ：保險合約發出日起計已\n生效了兩年可異議期內，保險人可以對該約提出異\n議或質疑，所以答案A不正確"},{c:"4.3",s:"以下哪兩項有關寛限期描述是正確的？\ni 寬限期一般為30日或31日\nii 適用所有保單，包括首期保費\niii就美式而言，除非繳清保費，否則保單會在寬限期後失效\niv就美式而言，如在寛限期未繳清保費，保單會在保費到期日失效",o:["i, ii","i, iii","ii, iii","ii, iv"],a:1,e:"寬限期不適用於保單的首期保費；就美式而言，如\n在寛限期未繳清保費，保單會在寬限期後失效，只\n有選項i, iii正確"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["它不適用於保單的首期保費","繳付的保費被視作準時繳付","寬限期一般為30日或31日","寬限期可長達60日"],a:3,e:"可長達60日寬限期不是寬限期條款的陳述"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["它不適用於保單的首期保費","繳付的保費被 視作準時繳付","這並非免費保險期","寬限期一般為14日"],a:3,e:"寬限期一般為30/31日，答案D不正確"},{c:"4.3",s:"通常保單條文指明一段的時間範圍，允許在保費到期日之後繳付而不受處罰，\n這樣的時間範圍通常稱為",o:["等候期","續保期","寬限期","不可異議期"],a:2,e:"允許在保費到期日之後繳付而不受處罰，\n這樣的時間範圍通常稱為寬限期"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["該期間一般最少30或31天","它不適用於保單的首期保費","於寬限期內繳付保費可維持保單的保障繼續有效","於寬限期內繳付保費須另外繳付利息"],a:3,e:"於寬限期內繳付保費須被視為準時繳交"},{c:"4.3",s:"在香港，壽險保單所容許的「寬限期」一般為",o:["最多7天","最多14天","最少30/31天","最少3個月"],a:2,e:"寬限期一般為期至少30或31日"},{c:"4.3",s:"對保險人來說,受保保單所有人在寬限期內繳交過期保費即表示",o:["準時繳付保費","受保保單所有人須額外繳付過期保費的利息","在未繳付保費的期間出現了保障真空期","續保時會收取所有未繳付之保費"],a:0,e:"對保險人來說,受保保單所有人在寬限期內繳交過\n期保費即被視為準時繳付保費"},{c:"4.3",s:"以下哪項或哪些有關「寬限期」描述是不正確的",o:["一般為期14天","是一個免費保險期","適用於保單的首期保費","以上全屬不正確"],a:3,e:"寬限期一般為期至少30或31日，寬限期不適用於保\n單的首期保費，寬限期內繳付的保費被視作準時繳\n付，這並非免費保險期，以上全屬不正確"},{c:"4.3",s:"以下哪項寬限期的說明是正確的？",o:["適用於保單的首期保費","保險人必須在賠償付款前的期限","保單所有人索償的一段時間","在保費到期日仍未繳交後，保單仍然有效的一段時間"],a:3,e:"寬限期又稱「寬限日期」，它指保費到期日之後保\n險保障仍然維持有效的一段時間。"},{c:"4.3",s:"對保險人來說，被保險人在寬限期內繳交過期保費，即表示",o:["須額外繳付過期保費的利息","當作準時繳付保費","續保時會收取所有未繳付之保費","在未繳付保費的期間出現了保障真空期"],a:1,e:"對保險人來說，被保險人在寬限期內繳交過期保費\n，即表示保費被視作準時繳付"},{c:"4.3",s:"下列哪兩項有關寬限期的陳述是正確的？\ni)寬限期一般為期至少三十或三十一日\nii)寬限期適用於所有保費，包括首期\niii)按照美式保單，除非已經繳清保費，否則保單便會於寬限期屆滿時失效\niv)按照美式保單，如果於寬限期內仍未繳清保費，那麼保單便會由保費到期即失效",o:["i, ii","i, iii","ii, iii","ii, iv"],a:1,e:"寬限期不適用於保單的首期保費，如果在寬限期結\n束時，受保生命還活着但到期保費尚未繳清，美式\n保單則會在寬限期屆滿時失效，只有選項i,\niii正確"},{c:"4.3",s:"按照英式保單處理方法，如寬限期內仍未繳清保費，而保單沒有現金價值，那英式保單\n會於何時開始失效?",o:["寬限期過後","寬限期後的十四天","保費到期日後的十四天","保費到期日開始"],a:3,e:"按照英式保單處理方法，如寬限期內仍未繳清保費\n，而保單沒有現金價值，保單會於保費到期日開始\n開始失效"},{c:"4.3",s:"通常保單條文指明一段的時間範圍，允許在保費到期日之後繳付而不受處罰，這樣的時\n間範圍通常稱為",o:["等候期","不作廢條款","續保期","寬限期"],a:3,e:"通常保單條文指明一段的時間範圍，允許在保費到\n期日之後繳付而不受處罰，這樣的時間範圍通常稱\n為寬限期"},{c:"4.3",s:"假設沒有不能作廢條款情況下，寬限期內沒有繳付保費，則保單便",o:["失效","被取消","變成不可異議","需要繳交較高保費，保單才可繼續生效"],a:0,e:"假設沒有不能作廢條款情況下，寬限期內沒有繳付\n保費，則保單便失效"},{c:"4.3",s:"以下哪項正確描述寬限期？",o:["寬限在15日以內","它不是免費保險期","保費可於寬限期滿及死亡前退還","以上各項皆是"],a:1,e:"寬限期不是免費保險期，如果受保生命在寬限期內\n死亡而保費還沒繳清，保險人會從應付死亡保險金\n中扣除到期保費"},{c:"4.3",s:"根據美式寬限期的規定，在於寬限期內死亡而保險保費尚未付清，以下哪項是採取的措\n施？",o:["不能獲取死亡保險金","死亡保險金可獲給付，但未繳清之保費可獲豁免","死亡保險金可獲給付，但未繳清之保費將會從中扣減","該保險合約屬於無效"],a:2,e:"根據美式寬限期的規定，它不是免費保險期，在於\n寬限期內死亡而保險保費尚未付清，死亡保險金可\n獲給付，但未繳清之保費將會從中扣減"},{c:"4.3",s:"如果於寬限期過後仍未繳交保費(假定沒有不能作廢條款保障)美式保單於何時開始失效\n？",o:["寬限期結束之日","保費到期後5日","保費到期後7日","保費到期日"],a:0,e:"如果在寬限期結束時，受保生命還活着但到期保費\n尚未繳清，美式保單則會在寬限期屆滿時失效"},{c:"4.4",s:"保單一般會指定受益人可能是一個群體，例如：「我的子女」，這種方式稱為",o:["概括式指定","次順位受益人","不可撤換受益人","團體保單"],a:0,e:"指定受益人可能是一個群屬體概括式指定"},{c:"4.4",s:"人壽保單通常允許保單所有人在保單有效時變更受益人的指定，在這情況下，該指定受\n益人稱為",o:["第一順位受益人","第二順位受益人","次順位受益人","可撤換受益人"],a:3,e:"人壽保單通常允許保單所有人在保單有效時變更受\n益人的指定，在這情況下，該指定受益人稱為可撤\n換受益人"},{c:"4.4",s:"一份典型的壽險保單中獲指名的(受益人)是",o:["該受保生命","該受保生命的配偶","保險金的準收款人","巳承讓該保單的人士"],a:2,e:"人壽保單的保單所有人一般會指示保險人把應付的\n死亡保險金支付受益人，被視為保險金的準收款人"},{c:"4.4",s:"以下哪項關於受益人的描述是正確的？",o:["所有受益人必須要有可保權益","只有第三者保單可用概括式的指定","除非保單特別指定，數位指定的受益人將平均分配保險金","如果受益人比受保保單所有人較早發生死亡，他的繼承人將於適當時候提取保險金"],a:2,e:"人壽保單的保單所有人一般會指示保險人把應付的\n死亡保險金支付受益人，付款的基本條件之一是受\n益人在受保生命去世時還活着。如果被指定的受益\n人超過一人，每人所得金額將相等，只有答案C正\n確"},{c:"4.4",s:"獲指定為收取壽險保單保險金的人士稱為",o:["被保險人","受益人","受保生命","保單持有人"],a:1,e:"獲指定為收取壽險保單保險金的人士稱為受益人"},{c:"4.4",s:"以下哪項不屬於受益人的「概括式指定」？",o:["「本人的妻子」","「本人的子女」","「本人的兄弟姊妹」","「本人第一段婚姻的子女」"],a:0,e:"「概括式指定」是即指定一組人為受益人，而非指\n名每個人，答案A不正確"},{c:"4.4",s:"保單中的指定受益人有第一順位受益人及次順位受益人。如果第一順位受益人死了，以\n下哪項對保險金的描述是正確？",o:["成為保單所有人的遺產","由次順位受益人所擁有","由保單所有人之繼承人所擁有","由次順位受益人及保單所有人之繼承人平均分配"],a:1,e:"當保單中的指定受益人有第一順位受益人及次順位\n受益人。如果第一順位受益人死了，死亡保險金應\n付給次順位受益人"},{c:"4.4",s:"某人在訂立某份人壽保險合約時，指定瑪莉為受益人。兩年後，他更改保單，致令萬一\n瑪莉比他早過世，莉莉便會成為受益人。莉莉在該份保險計劃中稱為",o:["後備受益人","次順位受益人","第二受益人","第一順位準受益人"],a:1,e:"受益人付款的基本條件之一是受益人在受保生命去\n世時還活着。可在第一順位受益人以外，指定一個\n或一個以上的次順位受益人，如果第一順位受益人\n早逝，死亡保險金會支付給次順位受益人"},{c:"4.4(b)",s:"保單中的指定受益人有第一順位受益人及次順位受益人。第一順位受益人於受保人在生\n期間過身，受保人過世時，次順位受益人仍然在生。那麼保險金將分配給",o:["成為保單所有人的遺產","由次順位受益人所擁有","由保單所有人之繼承人所擁有","由次順位受益人及保單所有人之繼承人平均分配"],a:1,e:"以防第一順位受益人不能比受保生命活得更久，可\n在第一順位受益人以外，指定一個或一個以上的次\n順位受益人"},{c:"4.4(b)",s:"如果已指定兩名受益人,但沒有顯示他們分別所佔的比例,在需要給付保單利益時",o:["會平均分配保險利益","第一順位受益人可取得兩倍的分配","第二順位受益人可取得兩倍的分配","第一順位受益人可取得所有保險利益"],a:0,e:"如果已指定兩名受益人,但沒有顯示他們分別所佔\n的比例,在需要給付保單利益時會平均分配保險利\n益"},{c:"4.4(b)",s:"假若受益人在保單受保人之前死亡，在需要給付利益時，保險金全數會給付",o:["繼任受益人","次順位準受益人","第二受益人","受益人"],a:3,e:"受益人付款的基本條件之一是受益人在受保生命去\n世時還活着。可在第一順位受益人以外，指定一個\n或一個以上的次順位受益人，如果第一順位受益人\n早逝，死亡保險金會支付給次順位受益人，答案D\n正確"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已\n婚者地位條例》，張先生的保單，將達到建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人壽保險人所發出","不會，除非張先生就其配偶及或子女的利益而購買壽險單","不會，除非該人身意外保險以附約形式加入於人壽保單"],a:2,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已\n婚者地位條例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非張先生就《已婚者地位條例》訂明，被保險人就自身生命購買保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.4(c)",s:"如某壽險單符合《已婚者地位條例》所指明的情況，將會產生以下甚麼的法律效用?",o:["所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的受託人","這是條例隱含的法定轉讓，並惠及保單所有人的指定受益人","信託效用自動產生，並惠及保單所有人的的其配偶及/子女等指定受益人","所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的實益擁有人，直至\n保單所有人更改受益人為止"],a:2,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.4(c)",s:"如某壽險單符合《已婚者地位條例》所指明的情況，將會產生以下甚麼的法律效用?",o:["所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的法定所有人","所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的受託人","所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的實益擁有人，直至\n保單所有人更改受益人為止","信託效用自動產生，並惠及保單所有人的的其配偶及/子女等指定受益人"],a:3,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.4(c)",s:"黃生就自身生命購買壽險保單，自己為受保人，並指明他最小的兒子為該保單受益人，\n根據《已婚者地位條例》，此舉起了甚麼的法律效用?",o:["該受益人成為該保單的法定保單所有人","該受益人成為該保單的法定保單所有人，直至黃先生修訂其他受益人為止","信託效用並不用適指定子女成為受益人","該受益人成為該保單的實益擁有人"],a:3,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.5",s:"以下哪項不屬於不能作廢條款的選擇?",o:["購買清繳保險","取回保費","購買展期保險以取代原有保單","取回現金價值"],a:1,e:"取回保費不屬於不能作廢條款的選擇"},{c:"4.5",s:"以下哪項不屬於人壽保險的不能作廢條款常見的選擇?",o:["減額清繳保險","支付全數的死亡保險金","展期保險","以上各項皆不是"],a:1,e:"支付全數的死亡保險金不屬於人壽保險的不能作廢\n條款常見的選擇"},{c:"4.5",s:"以下哪項不屬於人壽保險的不能作廢條款，保單的持有人可以作出的選擇?",o:["中止保單時獲付退保現金價值","取回已經支付的保費","利用淨現金價值作為整付保費購買減額清繳保險","以上各項皆不是"],a:1,e:"取回已經支付的保費不屬於人壽保險的不能作廢條\n款下的選擇"},{c:"4.5",s:"具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["保單所有人中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽\n保險","利用淨現金價值作為整付保費，購買與原保額相同的定期壽險，保險期則取決於該淨\n現金價值有多少","以上各項皆是"],a:3,e:"以上提及退保，減額清繳及展期保單，都是具有現\n金價值或紅利價值的保單，保單持有人決定不再繳\n付任何保費的選擇"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽\n保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保單，保單的持\n有人決定不再繳付任何保費有權選取的選擇"},{c:"4.5",s:"以下哪項是不能作廢條款的常規規定?",o:["保單所有人可中止保單時獲付退保現金價值","保單不會因為中斷繳付保費而失效，除非收到相反指示，否則保單的現金價值會被用\n作支付到期保費直至用完為止","利用淨現金價值作為整付保費，購買與原保額相同的定期壽險","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽\n保險"],a:1,e:"常規的不能作廢條款則規定是保單不會因為中斷繳\n付保費而失效。除非收到相反指示，否則保單的現\n金價值會被用作支付到期保費直至用完為止，以保\n持保單全額有效。"},{c:"4.5",s:"甚麼是「不能作廢」條款?",o:["當保單已生效超過兩年，保險人無權取消保單","當續保保費尚未繳交，現金價值可用以保持保單有效性","保單所有人在沒有保險人的同意下無權終止保單","當保單已全部索償，保單仍繼續生效"],a:1,e:"常規的不能作廢條款則規定是保單不會因為中斷繳\n付保費而失效。除非收到相反指示，否則保單的現\n金價值會被用作支付到期保費直至用完為止，以保\n持保單全額有效。"},{c:"4.5",s:"以下哪一項不是不能作廢條款下可作出的選擇?",o:["接受一份減額清繳保險","收回已支付的保費","退保以取回保單內的現金價值","以上各項皆不是"],a:1,e:"收回已支付的保費不是不能作廢條款下可作出的選\n擇"},{c:"4.5",s:"如果保單的持有人決定不再繳付任何保費，以下哪一項不是他有權選取的處理方法?",o:["減額清繳保險","退保取回現金價值","以現金價值購買定期壽險","要求保險人發放免息貸款支付保費"],a:3,e:"要求保險人發放免息貸款支付保費不是保單持有人\n有權選取的處理方法"},{c:"4.5",s:"保單條款指出可利用保單現金價值使保單維持有效，條款稱為「不能作廢」及",o:["續保保費貸款","自動保費貸款","自動保費透支","自動清繳貸款"],a:1,e:"部分保險人視不能作廢條款，為自動保費貸款條款\n或稱保費自動墊繳條款"},{c:"4.5",s:"很多壽險保單均有不能作廢條款，但它在以下哪項或哪些保險產品並不適用",o:["年金","定期壽險","未擁有現金價值的保單","以上所有各項"],a:3,e:"不能作廢條款對具有現金價值或紅利價值的保單關\n係非常密切，在中斷繳付保費的情況下，保單仍然\n有效。以上所有各項保險產品並不適用不能作廢條\n款"},{c:"4.5",s:"簡單來說，不能作廢條款規定",o:["雖然投保人未能到期支付保費，該保單亦不會作廢","除非該保單沒有取得現金價值，保險人不能取消該保單","保額不能調低","雖然投保人沒有能力償還貸款，該保單亦不會失效"],a:0,e:"不能作廢條款則規定是保單不會因為中斷繳付保費\n而失效。除非收到相反指示，否則保單的現金價值\n會被用作支付到期保費直至用完為止，以保持保單\n全額有效。"},{c:"4.5",s:"如未能及時繳交保費，某些保單有現金價值可以自動用作墊付保費以繼續保單運作稱為",o:["提前保費貸款","自動保費貸款","額外保費貸款","提供經濟援助"],a:1,e:"如未能及時繳交保費，某些保單有現金價值可以自\n動用作墊付保費以繼續保單運作稱為自動保費貸款"},{c:"4.5",s:"人壽保單中通常具有一些條文，把保單的現金價值即時用於支付尚未繳交的保費，從而\n避免保單失效，部分保險人不認為這是不能作廢條款，而稱之為?",o:["一筆強制性的保單貸款","一筆自動的保費貸款","一項延續保單條款","一項自動保單復效條款"],a:1,e:"把保單的現金價值即時用於支付尚未繳交的保費，\n部分保險人認為這是不能作廢條款，他們視之為一\n個獨立自動保費貸款條款或稱保費自動墊繳條款"},{c:"4.5",s:"對於停止供款的保單持有人，保單條文訂明了若干權力，以下哪項不正確？",o:["接受一份減額清繳保險","退保以取回保單內的現金價值","以現金價值購買一份定期壽險","要求保險人發放免息貸款以繳交保費"],a:3,e:"如果具有現金價值或紅利價值的保單，，要求保險\n人發放免息貸款以繳交保費，不是持有人決定不再\n繳付任何保費下，有權選取的選擇"},{c:"4.5",s:"壽險合約中，不能作廢條款的首要目的是",o:["不得扣減保額的價值","保險人無權取消保單","保單不會在沒有繳付保費的情況下失效","保單不會因為被保險人無法償還貸款而作廢"],a:2,e:"壽險合約中，不能作廢條款的首要目的是保單不會\n在沒有繳付保費的情況下失效"},{c:"4.5",s:"壽險保單中自動保費貸款",o:["貸款用途由保險人任意決定的","貸款在所有壽險保單中，都是常見的","貸款只可用作保單規定的指定用途","以上各項描述均不是"],a:2,e:"壽險保單中自動保費貸款只可用作保單規定的指定\n用途，例如繳交已過期保費"},{c:"4.5",s:"有些保險人指定某些保單條文(APL)。藉此，寬限期過後仍未繳交到期保費，保單便可利\n用該保單的現金價值支付保費。該APL的意思是",o:["輔助保單貸款(Assisted Policy Loan)","自動保單貸款(Automatic Policy Loan)","輔助保費貸款(Assisted Premium Loan)","自動保費貸款(Automatic Premium Loan)"],a:3,e:"APL的意思是自動保費貸款(Automatic Premium\nLoan)"},{c:"4.5",s:"自動保費貸款(APL)是以什麼作為繳交保費的一種貸款？",o:["以保單中的現金價值","以樓宇作為抵押之貸款","以私人貸款","以上各項皆是"],a:0,e:"不能作廢條款則規定，保單不會因為中斷繳付保費\n而失效。除非收到相反指示，否則保單的現金價值\n會被用作支付到期保費，直至用完為止，以保持保\n單全額有效。答案A正確"},{c:"4.5",s:"保單不會因為停止繳付保費而失效，這是指什麼條款？",o:["不可異議條款","不能作廢條款","代位權","彌償"],a:1,e:"不能作廢條款則規定，保單不會因為中斷繳付保費\n而失效。除非收到相反指示，否則保單的現金價值\n會被用作支付到期保費，直至用完為止，以保持保\n單全額有效。答案B正確"},{c:"4.5",s:"自動保費貸款的意思是?",o:["保險人自動地發放無抵押貸款,以付繳保費","保險人自動地發放貸款,以付尚未清繳的保費","保險人豁免首月保障的保費","被保險人可要求貸款,以繳付保費"],a:1,e:"自動保費貸款的意思是保險人自動地發放貸款,以\n付尚未清繳的保費，保單的現金價值會被用作支付\n到期保費，直至用完為止，以保持保單全額有效。"},{c:"4.5",s:"APL的英文全寫為",o:["自動保費貸款 Automatic Premium Loan","調整保費貸款 Adjusted Premium Loan","自動付款貸款 Automatic Payment Loan","調整付款貸款 Adjusted Payment Loan"],a:0,e:"部分保險人並不認為這是不能作廢條款，他們視之\n為一個獨立的保單條款，並稱之為自動保費貸款條\n款或稱保費自動墊繳條款(automatic premium\nloan (APL) provision)"},{c:"4.5",s:"根據壽險保單中常見的不能作廢條例，下列哪一項不屬於決定不再繳付任何保費的保單\n所有人的選擇?",o:["退保並收取保單現金價值","利用保單價值作為保費，接受一份減額清繳保險","利用現金價值購買與原本保單保額相同的定額壽險","暫停保障，但有權在任何時間恢復保險"],a:3,e:"暫停保障，但有權在任何時間恢復保險不屬於決定\n不再繳付任何保費的保單所有人的選擇"},{c:"4.5",s:"以下哪項不屬於不能作廢條款？",o:["得到退保現金價值","立即收回剛購買的清繳保障利益","以現金價值購買展期保險","以上各項皆是"],a:1,e:"立即收回剛購買的清繳保障利益，不屬於不能作廢\n條款下保單持有人可作出的選擇"},{c:"4.5",s:"一份完全清繳的保單是指",o:["以往所有到期保費已給支付","保費由第三者(如僱主)支付","保單一經生效必須支付所有保費","保單保費已全數支付，但保單仍然維持有效"],a:3,e:"一份完全清繳的保單是指保單保費已全數支付，保\n單仍然維持有效"},{c:"4.5(a)",s:"自動保費貸款(APL)是以什麼作為繳交保費的一種貸款？",o:["以保單中的現金價值","以樓宇作為抵押之貸款","以私人貸款","以上所有各項"],a:0,e:"常規的不能作廢條款則規定是保單不會因為中斷繳\n付保費而失效。除非收到相反指示，否則保單的現\n金價值會被用作支付到期保費直至用完為止，以保\n持保單全額有效。條款並稱之為自動保費貸款條款\n或稱保費自動墊繳條款"},{c:"4.5(a)",s:"保單不會因為停止繳付保費而失效，這是指什麼條款?",o:["不可異議條款","不能作廢條款","代位權","彌償"],a:1,e:"不能作廢條款則規定是保單不會因為中斷繳付保費\n而失效。除非收到相反指示，否則保單的現金價值\n會被用作支付到期保費直至用完為止，以保持保單\n全額有效。"},{c:"4.6",s:"向保險人借入款項，保單持有人可以利用以下哪樣作爲抵押？",o:["現金價值","現金","現金或其他有價值的實質資產","上述所有各項"],a:0,e:"保單抵押貸款唯一需要的抵押就是保單現金價值"},{c:"4.6",s:"以下哪項是對保單抵押貸款的正確描述？",o:["貸款用途由保單所有人決定","貸款通常是保險人任意決定的","唯一受到保單條款約束的是定期壽險","保單貸款的用途只能用作繳付未來保費之用"],a:0,e:"保單抵押貸款屬保單有人有權向保險人借入款項，\n貸款用途無任何限制，以及保單所有人自行決定還\n款多少和 何時償還，只有答案A正確"},{c:"4.6",s:"以下哪項對保單抵押貸款條款的描述是不正確的?",o:["貸款金額上限為現金價值（扣除一年貸款利息）","貸款用途必須經保險人許可","要求使用保單抵押貸款,是在保單上列名的保單所有人的權利","有關利息可在保單利益應付時償還"],a:1,e:"保單抵押貸款條款貸款用途並無限制，答案B不正\n確。"},{c:"4.6",s:"以下哪項或哪些有關保單抵押貸款的陳述不正確?",o:["沒有限定保單抵押貸款的用途","需要獨立的抵押品","貸款可於保額發放前償還或不償還","以上所有皆不正確"],a:1,e:"貸款唯一需要的抵押就是保單現金價值"},{c:"4.6",s:"哪一項是有關典型壽險保險的保單抵押貸款條款的正確陳述？",o:["借款用途無任何限制","保單持有人有權向保險人借入款項","貸款需要的抵押是保單的現金價值","以上各項皆是"],a:3,e:"以上各項皆是典型壽險保險的保單抵押貸款條款的\n正確陳述"},{c:"4.6",s:"以下哪項正確描述保單抵押貸款？\ni) 保單所有人有權向保險人借入款項\nii) 貸款的用途無一定限制\niii) 需要以保單現金價值作為抵押\niv) 貸款可於保單生效期內或外償還",o:["i, ii, iii","i, iii, iv","ii, iii, iv","以上各項都是"],a:3,e:"以上各項都是保單抵押貸款的正確陳述"},{c:"4.6",s:"關於人壽保單的保單抵押貸款",o:["貸款通常是保險人任意決定的","就任何種類的壽險而言，貸款都是常見的","貸款只獲允許用於保單指定的某些用途","以上所有各項均不正確"],a:3,e:"保單抵押貸款條款下，保單所有人有權向保險人借\n入款項，貸款用途無任何限制；以上各項均不是保\n單抵押貸款正確陳述"},{c:"4.6",s:"下列哪項或哪些屬於保單抵押貸款中慣用條文的特點",o:["該筆貸款用途無任何限制","該筆貸款唯一需要的抵押品就是保單現金價值","於保單生效期內可以償還或不償還該筆貸款","上述所有各項"],a:3,e:"以上各項都是保單抵押貸款的正確陳述"},{c:"4.6",s:"就合資格的壽險保單的保單貸款而言",o:["要求貸款是一種權利，而不是權益","貸款毋須在提供索償前償還","除保單價值以外，保單持有人毋須提供其他抵押","以上所有各項皆正確"],a:3,e:"以上都是保單抵押貸款的正確描述"},{c:"4.6",s:"以下哪項是對保單抵押貸款的不正確描述？",o:["還款與否全由保單所有人決定","貸款與否必須由保險公司單方面作出決定","此條款不適用於定期壽險保單","貸款之用途並沒有限制"],a:1,e:"保單抵押貸款條款下，保單所有人有權向保險人借\n入款項，答案B不正確"},{c:"4.6",s:"如果抵押貸款在投保生命死亡時仍未清還，那麼",o:["有關的死亡索償便會無效","有關的保險人可豁免該筆保費的償還","受益人於支付該保險利益前,要先繳清該筆貸款","有關的抵押貸款及相關的利息會在保單利益中扣減"],a:3,e:"如果抵押貸款在投保生命死亡時仍未清還，有關的\n抵押貸款及相關的利息會在保單利益中扣減"},{c:"4.6",s:"保單抵押貸款條款是",o:["貸款的用途必要用作繳交未來的保費","若不償還貸款，金額及其利息會在所給付的保險金中扣除","貸款金額須要在借貸後之一年內歸還","貸款金額須在續保時歸還"],a:1,e:"保單所有人自行決定還款多少和何時償還，\n未償還貸款額，包括任何未償還利息會從應付的死\n亡保險金或退保價值中扣除"},{c:"4.6",s:"下列哪項屬於保單抵押貸款中不大可能是正確的?",o:["該筆貸款用途無任何限制","該筆貸款唯一需要的抵押品就是保單的現金價值","若是意外死亡，不須償還該筆貸款","貸款金額須在受保生命死亡時在保額內扣除"],a:2,e:"保單抵押貸款貸款金額須在受保生命死亡時在保額\n內扣除，不論任何原因身故，答案C不正確。"},{c:"4.6",s:"下列哪項或哪些屬於保單抵押貸款中慣用條文的特點?",o:["該筆貸款必須用於繳交未來的保費","該筆貸款唯一需要的抵押品就是保單的定期保險","於保單生效期內可以償還或不償還該筆貸款","保單的貸款由保險人決定"],a:2,e:"保單所有人自行決定還款多少和何時償還，\n未償還貸款額，包括任何未償還利息會從應付的死\n亡保險金或退保價值中扣除"},{c:"4.6",s:"以下哪項關於保單抵押貸款的描述是正確的？",o:["貸款必須用作清繳保費之用","貸款必須於保單完結時償還","貸款必須於下個保單周年日前全數償還","貸款可於任何時間償還"],a:3,e:"保單所有人自行決定還款多少和何時償還，\n未償還貸款額，包括任何未償還利息會從應付的死\n亡保險金或退保價值中扣除"},{c:"4.6",s:"如果抵押貸款在投保生命死亡時仍未清還，以下哪項描述是正確的？",o:["有關的死亡索償便會無效","有關的保險人可豁免該筆貸款的償還","受益人必須先繳清該筆貸款才能獲得支付保險利益","有關的抵押貸款及利息會在保單利益中扣減"],a:3,e:"保單所有人自行決定還款多少和何時償還，\n未償還貸款額，包括任何未償還利息會從應付的死\n亡保險金或退保價值中扣除"},{c:"4.7",s:"要保單復效，保單所有人必須受到下列哪項或哪些條件限制？",o:["繳付一筆復效費用","補付已到期但未繳付的保費及利息","重新計算可異議期","以上皆是"],a:3,e:"以上皆是保單復效，保單所有人必須受到的條件限\n制"},{c:"4.7",s:"根據傳統人壽保險條文，保單復效可獲批準",o:["必須得到保險人的同意","被保險人身故之前的任何時間","被保險人的權利(受保單條文所約束)","保單生效不少於兩年"],a:2,e:"「復效」一詞在這種情況下關乎保單所有人可使已\n失效的保單重新生效的權利。"},{c:"4.7",s:"若要把已失效的人壽保單復效，以下哪項不是復效條件?",o:["繳一筆復效費","保險人書面同意","繳付已到期而未繳清的保費及利息","提供可保性證明"],a:1,e:"保險人書面同意不是人壽保單復效條件"},{c:"4.7",s:"要保單復效，以下哪一項不是保單所有人受到的條件限制？",o:["規定期間內提出復效要求","只適用於已失效保單","提供持續可保性","只有現金價值的保單才可復效"],a:3,e:"現金價值不是保單復效條件限制"},{c:"4.7",s:"英式人壽保險慣例中的「保單復效」(Policy revival)一詞，在香港通常被稱為",o:["續保 (Renewal)","不能作廢 (Non-forfeiture)","復效 (Reinstatement)","重新建立 (Pre-establishment)"],a:2,e:"「保單復效」一詞，在香港通常被稱為復效"},{c:"4.7",s:"一份壽險保單的復效",o:["是違法的","適用於已失效或退保的保單","有條件性的限制,是保單條文中的一項權利","只可在保險人於復效時同意的一刻進行"],a:2,e:"一份壽險保單的復效有條件性的限制,是保單條文\n中保單所有人的一項權利"},{c:"4.7",s:"一份壽險保單的復效",o:["是違法的","適用於已失效或退保的保單","有條件性的限制,是保單條文中的一項權利","只可在保險人於復效時同意的一刻進行"],a:2,e:"一份壽險保單的復效需符合某些條件性的限制,是\n保單條文中保單所有人的一項權利"},{c:"4.7",s:"若要把已失效的人壽保單復效，以下哪項或哪些是限制條件?",o:["繳一筆復效費","繳付已到期而未繳清的保費及利息","引入另一段可異議期","以上各項皆是"],a:3,e:"以上各項皆是保單復效的限制"},{c:"4.7",s:"受某些條件的限制下，一份已失效的壽險可以恢復有效，這個過程稱為",o:["續保","復原","復效","條件重訂"],a:2,e:"受某些條件的限制下，一份已失效的壽險可以恢復\n有效，這個過程稱為復效"},{c:"4.7",s:"跟據英式人壽保險的慣例，「復效」稱為?",o:["重新訂立合約","保單復效","不能作廢","保單續保"],a:1,e:"跟據英式人壽保險的慣例，「復效」稱為保單復效"},{c:"4.7",s:"有意復效保險單必須於規定時間內提出，一般為",o:["1年","2年","3年","5年"],a:3,e:"有意復效保險單必須於規定時間內提出，一般為5\n年"},{c:"4.7",s:"以下哪項不是有意復效保險單的條款？",o:["提供持續可保性的證明","保險人的書面同意","繳付一筆復效費","補付已到期但未繳清的保費及利息"],a:1,e:"在保險人與保單所有人雙方同意的情況下，保單復\n效這固然是可行的。答案B不正確"},{c:"4.7",s:"按照英式人壽保險慣例，在某些情況下，己失效的保單可以重獲「生命」，此稱為",o:["恢復保單","復效","轉保","生效"],a:1,e:"在某些情況下，己失效的保單可以重獲「生命」，\n此稱為復效"},{c:"4.7",s:"在什麼情況下，保單所有人已失效的保單有機會可以復效？",o:["保險人單方面同意下","補付未繳清的保費及利息","保單曾生效兩年或以上","任何時間都可以"],a:1,e:"復效其中一項條件限制是補付未繳清的保費及利息"},{c:"4.7",s:"當保單失效時，客人可申請「保單復效」，以下哪項描述是不正確的？",o:["退保的保單會自動重新生效","客人須提供連續可保性證明","客人須繳付任何未繳清的貸款及利息","保單復效是有條件性的申請"],a:0,e:"保單復效權利一般只適用於已失效的保單，而非已\n退保的保單"},{c:"4.7",s:"要保單復效，保單所有人必須受到下列哪些條件限制？\ni) 提供連續可保性證明\nii) 繳付任何未繳清貸款利息\niii) 從復效日計起的另一段自殺免責期\niv) 從復效日計起的另一段可異議期",o:["i及ii","i及iii","ii及iii","i, ii, iii 及 iv"],a:3,e:"以上各項皆是復效條件限制"},{c:"4.7",s:"以下哪項最不可能符合保單復效條件？",o:["保單兩年前已失效","保單五年前已失效","保單八年前已失效","以上所有皆不符合"],a:2,e:"保單復效有關期限可能因保險公司而異，但一般為\n5年，答案C不正確"},{c:"4.7(d)",s:"以保單條文而言，以下哪些或哪項對一個保單復效的要求很大可能不接納？",o:["一份已失效二十年的保單","一份在兩年前已失效的保單","一份在寬限期結束後兩個月内提出","以上各項皆是"],a:0,e:"有關保單復效期限可能因保險公司而異，但一般為\n5年\n，答案A不正確"},{c:"4.8",s:"就誤報年齡或性別方面，人壽保險單通常",o:["也適用於自願變性的情況","只容許保單利益向上調整","只容許保單利益向下調整","試圖改變保單條款至以符合應有情況"],a:3,e:"若事實與安排保險時所說明的年齡或性別不相同，\n這可能對保費及／或保險利益產生顯著影響。"},{c:"4.8",s:"因混淆外國人名字，人壽保單簽發一段時間後，才發現該保單將女性受保人誤以為是男\n性，經相討後，如果保單所有人願意支付相同的保費金額，保險人會作出以下哪項修改\n？",o:["退還由投保當日起計的所有保費","將保單保額調高","調低保單保額，以反映已繳付保費相符的正確保額","調高保費，以反映保單少付的保費"],a:1,e:"保單將女性受保人誤以為是男性，因女性保費率比\n男性為低，如果保單所有人願意支付相同的保費金\n額，保險人便會將保單保額調高"},{c:"4.8",s:"在香港，一般就誤報年齡或性別，若保險公司在發出保單後才發覺通常會如何處理",o:["不會作出任何調整","保單將會失效","只容許保單利益向下調整","利益或保費會向上或下調整"],a:3,e:"如果壽險索償發生之後才發現錯誤，保險公司須向\n上或向下調整應付保險利益的金額，以反映在根據\n正確的年齡／性別能獲得的利益金額"},{c:"4.8",s:"誤報年齡或性別資料的情況，如果保單於提出索償後才被發現，保險人會如何處理？",o:["不會作出任何調整","保單將會失效","退回全數已繳保費","向上或向下調整利益金額"],a:3,e:"誤報年齡或性別資料的情況，如果保單於提出索償\n後才被發現，保險人會向上或向下調整利益金額"},{c:"4.8",s:"如果保單於提出索償時，才發現有關受保生命的真實年齡較保單顯示的為高",o:["保單自動無效","調整利益，支付比保單較低的保額","調整利益，支付比保單較高的保額","維持保額不變，退回多繳的保費"],a:1,e:"如果保單於提出索償時，才發現有關受保生命的真\n實年齡較保單顯示的為高，即是出現少交保費的情\n況，保險人會調整利益，支付比保單較低的保額"},{c:"4.8",s:"大部分的香港保險公司簽發的保單，在誤報年齡或性別的情況下(根據美式慣例)，如果\n於提出索償後才被發現，保險人不會如何處理？",o:["不會調高保費亦不會退回保費","如果保單上顯示的年齡較真實為低，可能獲得的利益便調低","如果保單上顯示的年齡較真實為高，可能獲得的利益便調高","以上各項都有可能"],a:0,e:"根據美式慣例，如果於提出索償後才被發現，保險\n人調整應付保險利益的金額，以反映在根據正確的\n年齡／性別，應該能獲得的利益金額，不會調高保\n費亦不會退回保費"},{c:"4.8",s:"如果一份已簽發的壽險保單顯示受保人的年齡不正確,而該錯誤是於提出任何索償前發現\n,那麼以下哪項描述是正確的?",o:["必須取消該份保單而簽發一份新保單","其中一項選擇是支付任何差額保費(或獲退回多繳保費)","要更改保額或任何合約條款,實屬太遲","基於不可異議條款,不必有所作為"],a:1,e:"如果於提出索償前之前已發現錯誤，保單所有人通\n常可以選擇調整保險利益的金額，或調整應付保費\n，以反映在根據正確的年齡／性別"},{c:"4.8",s:"如果於保單簽發後數年(在出現索償前)發現有關受保生命的真實年齡較保單顯示的高",o:["有關保單便自動宣告無效","由於保單已是不可異議，因此無須作任何修改","便必須調整有關保額或保費的其中一項","便取消有關保單，並退回全部保費"],a:2,e:"如果在賠案發生之前已發現錯誤：保單所有人通常\n可以選擇調整有關保額或保費的其中一項"},{c:"4.8",s:"因為保單所有人外語名字，保單資料被誤將女性填寫為男性，此為終身壽險保單，當發\n現錯誤時，被保人堅持支付現時保費金額，保險人該如何處理？",o:["調整保單保額，以反映已繳付保費相符的正確保額","退回多收保費","撤銷保單","保單保額向下調整"],a:0,e:"保單將女性受保人誤以為是男性，因女性保費率比\n男性為低，如果保單所有人願意支付相同的保費金\n額，保險人便會將調整保單保額，以反映已繳付保\n費相符的正確保額"},{c:"4.8",s:"保險人對於誤報資料的保單，在索償前通常也有一些常規條款，下列哪項為正確的？",o:["不會收取增加之保費及退回保費","若年齡在保單上過輕，則降低保額","若年齡在保單上過大，則退回多交之保費連利息","以上各項均不成立"],a:1,e:"如果在賠案發生之前已發現錯誤，便必須調整有關\n保額或保費的其中一項，若在保單年齡教真實年齡\n為輕，則出現少交保費情況，會降低保額"},{c:"4.8",s:"人壽保險理賠時發現受保人年齡應較小，按美式保險傳統做法，會賠償較大的金額，同\n樣情況下，英式傳統做法為以下哪項？",o:["與美式並無分別","賠償死亡保險金額，不會退回多付保費","賠償死亡保險金額，退回多付的保費","由於違反最高誠信，沒有任何賠償"],a:2,e:"如果保險人在這項目上採用最常見的英式做法，任\n何對保險金額的調整只能是向下的。如果誤報的年\n齡／性別顯示已繳付的保費過高，保險人會退還超\n額繳付的保費"},{c:"4.8",s:"在美國，若處理索償時才發現受保人年齡不符，則",o:["保單無效","調整保費(收取或退保保費)","調整保險利益的金額","可收取50%保額"],a:2,e:"在美國，若處理索償時才發現受保人年齡不符，就\n誤報年齡或性別方面，人壽保險單通常調整保險利\n益以符合確定情況"},{c:"4.8",s:"就誤報年齡或性別方面，人壽保險單通常",o:["也適用於自願變性的情況","只容許保單利益向上調整","只容許保單利益向下調整","調整保險利益以符合確定情況"],a:3,e:"就誤報年齡或性別方面，人壽保險單通常調整保險\n利益以符合確定情況"},{c:"4.8",s:"如果保單於提出索償後，才被發現誤報年齡或性別資料，保險人會如何處理？",o:["向上或向下調整利益金額","不會作出任何調整","退回全數已繳保費","即時取消保單，並控告受保保單所有人"],a:0,e:"如果保單於提出索償後，才被發現誤報年齡或性別\n資料，保險人可以向上或向下調整利益金額"},{c:"4.8",s:"如果於保單簽發後數年(在出現索償前)發現有關受保生命的真實年齡較保單顯示的高",o:["有關保單便自動宣告無效","由於保單已是不可異議，因此無須作任何修改","便必須調整有關保額或保費的其中一項","便取消有關保單，並退回全部保費"],a:2,e:"如果於保單簽發後數年(在出現索償前)發現有關受\n保生命的真實年齡較保單顯示的高，保險人便必須\n調整有關保額或保費的其中一項"},{c:"4.8",s:"若受保保單所有人誤報年齡或性別，於索償前被發現，保額會被如何處理？",o:["保額或保費必須更正","保額及保費必須更正","經雙方同意後，可以決定更正或否","若年齡在保單上過輕，則退回多交之保費連利息"],a:0,e:"如果於保單簽發後數年(在出現索償前)發現有關受\n保生命的真實年齡較保單顯示的高，保險人便必須\n調整有關保額或保費的其中一項"},{c:"4.8",s:"在申請索償時發現被保人的性別及年齡誤報，那麼該份保險合約",o:["可能涉及罰款","通常變成無效","通常可於死亡保險金上作出調整以反映正確情況","假設被保人存在欺詐"],a:2,e:"在申請索償時發現被保人的性別及年齡誤報，通常\n可於死亡保險金上作出調整以反映正確情況"},{c:"4.8(a)",s:"如果保單於提出索償後，才被發現誤報年齡或性別資料，保險人會如何處理？",o:["向上或向下調整利益金額","不會作出任何調整","退回全數已繳保費","即時取消保單，並控告受保保單所有人"],a:0,e:"如果在賠案發生之後才發現錯誤：須向上或向下調\n整應付保險利益的金額"},{c:"4.9(e)(i)",s:"以下哪項對絕對轉讓的描述是不正確的?",o:["所有權益歸於新的保單所有人","轉讓是永久性的","要以抵押品作為貸款低押","新的保單所有人稱為承讓人"],a:2,e:"要以抵押品作為貸款低押不屬絕對轉讓的限制"},{c:"4.9(e)(ii)",s:"對於壽險保單之抵押轉讓",o:["這安排是永久性的","承讓人對該保單取得無限制的權利","該份保單仍可取得保單抵押貸款或退保","以上所有各項皆不是"],a:3,e:"對於壽險保單之抵押轉讓安排是暫時性的，通常以\n保單作為貸款的質押擔保，承讓人的利益限於貸款\n金額連利息，並賦予轉讓人復歸權，於完全還款之\n後取回權益。以上所有各項皆不是抵押轉讓的正確\n陳述"},{c:"4.9(e)(ii)",s:"一種屬於暫時性質的轉讓(例如利用保單作為一項貸款的抵押品)稱為？",o:["暫時性轉讓","絕對轉讓","抵押轉讓","附條件轉讓"],a:2,e:"抵押轉讓屬於暫時性質的轉讓"},{c:"4.9",s:"錢先生將他的人壽保單轉讓給ABC公司，ABC公司現在要求保險人支付紅利，卻遭保險人\n拒絕，保險人極可能拒絕的原因是",o:["ABC公司並不是合約的一方","保險人沒有收到就轉讓的書面通知","轉讓只限於支付死亡保險利益","錢先生並沒有更改受益人為ABC公司"],a:1,e:"典型的壽險單包含了一項轉讓條文，說明保險人在\n未收到書面通知之前，沒有義務按照有關轉讓行事"},{c:"4.9",s:"就可保權益，以下哪種情況可以進行轉讓？",o:["只可轉讓於配偶或雙親","只可轉讓一名關係密切的家庭成員","只可轉讓一名關係密切的朋友","無論承讓人是否具可保權益皆可進行轉讓"],a:3,e:"保單所有人可把正當地安排的人壽保險合約轉讓給\n第三者，即使該第三者對受保生命缺乏可保權益，\n無論承讓人是否具可保權益皆可進行轉讓"},{c:"4.9",s:"對於一個保單所有人來說，如果他對產權的權益是復歸的，那",o:["仍未取得該項權益","雖然對產權有獲得認可的權益，財產的享用將延遲至將來的某一天或某事發生時","肯定會在將來取得該權益","該權益屬於受益人權益"],a:1,e:"復歸的權益是指對產權有獲得認可的權益，財產的\n享用將延遲至將來的某一天或某事發生時"},{c:"4.9",s:"下列哪項不屬於壽險保單的轉讓限制？",o:["有關轉讓不能因為非法目的而安排","有關轉讓不以金錢為代價","有關轉讓不能選其他賠付選擇可能限於一次過整筆支付","不得侵犯任何不可撤換受益人的既得利益"],a:1,e:"有關保單轉讓限制，可能規定只能以一次過整筆保\n單利益支付承讓人，答案Ｂ不正確"},{c:"4.9",s:"對於一個保單所有人來說，對保險合約的權益也可形容為「復歸的」 ，即是說",o:["仍未取得該項權益","肯定會在將來取得該權益","保單所有人對該合約的權益獲得承認，但他尚未能實際享用該項權益","該權益可以轉讓給其他人"],a:2,e:"「復歸的」權益是指保單所有人對該合約的權益獲\n得承認，但他尚未能實際享用該項權益"},{c:"4.9",s:"下列哪項屬於壽險保單的轉讓限制？",o:["有關轉讓不能因為非法目的而安排","規定只能以一次過整筆支付保單利益","不得侵犯任何受益人的既得權利","以上各項皆是"],a:3,e:"以上各項皆是轉讓保單的限制"},{c:"4.9",s:"以下哪項就保單轉讓的描述是正確的?",o:["轉讓保單的人是承讓人","獲轉讓保單的人是轉讓人","轉讓保單涉及代價，是構成合約不能缺少的元素","以上各項都不是答案"],a:3,e:"以上各項都不是保單轉讓的正確描述"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許藉訂明手續來\n轉讓據法權產"},{c:"4.9",s:"以下哪項有關抵押轉讓的描述是正確的?",o:["它是永久性的轉讓安排","承讓人對保單擁有單的一切擁有權","保單仍可用作貸款","以上各項皆不是"],a:3,e:"抵押轉讓安排是暫時性的，轉讓條款把承讓人的利\n益限於貸款金額連利息並賦予轉讓人復歸權\n，於完全還款之後取回權益。"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，擬轉讓的據法\n權產須屬現時的，而非未來的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許藉訂明手續來\n轉讓據法權產，而對保險合約的權益屬於據法權產\n。"},{c:"4.9",s:"為什麼說一張壽險保單所有人只具有有限的權利轉讓該保單的產權？",o:["轉讓一張保單的權利屬該保單的受益人而非保單所有人所有","如果保單受益人已取得保單的權利，不得侵犯任何受益人既得的權利","轉讓壽險單必須保險人的批准","在典型壽險保單所規定的初段時間內轉讓保單必需保險人的批准"],a:1,e:"轉讓該保單的產權的其中一個限制，是不得侵犯任\n何受益人既得的權利"},{c:"4.9",s:"為什麼說一張壽險保單所有人只具有有限的權利轉讓該保單的產權？",o:["轉讓一張保單的權利屬該保單的受益人而非保單所有人所有","轉讓壽險單必須保險人的批准","不得侵犯任何受益人，尤其是任何不可撤換受益人的任何既得權利","在典型壽險保單所規定的初段時間內轉讓保單必需保險人的批准"],a:2,e:"保單轉讓共中一個限制，是有關轉讓不得侵犯任何\n受益人，尤其是任何不可撤換受益人的任何既得權\n利"},{c:"4.9",s:"如果進行壽險保單的轉讓，獲轉讓保單的人士是",o:["轉讓人","承讓人","被轉讓人","轉讓受益人"],a:1,e:"進行壽險保單的轉讓，獲轉讓保單的人士是承讓人"},{c:"4.9",s:"如果把一個人在一項保險合約中所具有的權益形容為復歸的,這表示",o:["該權益可能在未來某個時候出現","該權益在繳交所有保費後出現","在繳交最後一期保費後出現的合法權利","以上所有皆不是"],a:3,e:"如果對保險合約的權益被形容為復歸的，即表示保\n單所有人根據該合約的權利毫無疑問地獲得承認，\n但他尚未能實際享用該項保險，直到未來某日或某\n件事發生後，以上所有皆不正確"},{c:"4.9",s:"錢先生把他的人壽保單轉讓了給ABC有限公司，ABC有限公司現在要求保險人支付紅利，\n卻遭保險人拒絕。下面哪項是保險人這麼做的最可能原因？",o:["保險人沒有收過該轉讓發出的書面通知","轉讓通知書說明已把保單一切權益轉讓，但並沒有明確地提及紅利","錢先生沒有把受益人改成ABC有限公司","必須由錢先生提出這種要求，在合約被成功轉讓後他還是保險合約的一方"],a:0,e:"典型壽險單包含了一項轉讓條文，說明保險人在未\n收到書面通知之前，沒有義務按照有關轉讓行事"},{c:"4.9",s:"保單所有人將權益轉讓的方式為哪一項或哪些：\ni) 絕對轉讓\nii) 部分轉讓\niii) 抵押轉讓\niv) 有效轉讓",o:["i","i, ii, iv","i, iii","i, iv"],a:2,e:"人壽保險人把轉讓分為兩種：絕對轉讓及抵押轉讓"},{c:"4.9",s:"有一種轉讓是永久性的，而承讓人是新的保單持有人，這種轉讓是",o:["長遠的轉讓","絶對轉讓","不可取消的轉讓","永久性的轉讓"],a:1,e:"有一種轉讓是永久性的，而承讓人是新的保單持有\n人，這種轉讓是絶對轉讓"},{c:"4.9",s:"以下哪項或哪些有關人壽保險單的轉讓是不正確？",o:["轉讓保單的人稱為承讓人","獲轉讓保單的對象稱為轉讓人","所有轉讓必須涉及代價，這是合約元素之一","以上所有皆不正確"],a:3,e:"保險單的轉讓跟合約元素無關，轉讓保單的人稱為\n轉讓人，獲轉讓保單的對象稱為承讓人"},{c:"4.9",s:"抵押轉讓是暫時性的，可以以保單作為抵押，而承讓人可以在索償時可收回",o:["保額全數","貸款金額加利息","保險金扣除貸款額之後的餘額","以上各項都不正確"],a:1,e:"抵押轉讓是暫時性的，可以以保單作為抵押，轉讓\n條款把承讓人的利益限於貸款金額連利息"},{c:"4.9",s:"以下哪項對轉讓的評論並不正確？",o:["保單所有人是轉讓人","第三者是承讓人","保單可當作出售或作為禮物","必須獲得保險人的同意"],a:3,e:"保單轉讓無須獲得保險人的同意，但需要向保險人\n作出書面通知"},{c:"4.9",s:"保單轉承中的承讓人，只能得「淨保險金」，是指",o:["他沒有取得任何紅利或英式紅利","保險人有權扣減過期未清繳的保費和尚欠的貸款","退保時，他只能取回部分保額","保險人不用交付未來的保費的佣金"],a:1,e:"保單轉承中的承讓人，只能得「淨保險金」，是指\n保險人有權扣減過期未清繳的保費和尚欠的貸款"},{c:"4.9",s:"保單經過轉讓後，保險人持有優先收回欠款的權利。承讓人在索償時可收回",o:["凈保額","凈保單收益","保額餘款","扣除還款後的餘額"],a:1,e:"轉讓人任何未付的過期保費，和未償還的保單抵押\n貸款連利息，將從任何應向承讓人支付的保單利益\n中扣除，這情況可以承讓人收取保單的淨保單收益"},{c:"4.9",s:"人壽保險的轉讓方式分為兩大類其中一種稱為絕對轉讓，另一種則是?",o:["部分轉讓","抵押轉讓","有條件轉讓","優先轉讓"],a:1,e:"人壽保險人把轉讓分為兩種：絕對轉讓及抵押轉讓"},{c:"4.9",s:"下列哪一項關於絕對轉讓和抵押轉讓的陳述是不正確?",o:["絕對轉讓是永久性安排","如果抵押轉讓已經存在，保單抵押貸款或者退保是不可能的","在抵押轉讓中，承轉人就保單享有無限權益","抵押轉讓可能以保單作為貸款的抵押品"],a:2,e:"抵押轉讓條款把承讓人的利益限貸款金額連利息，\n所以選項C不正確"},{c:"4.9",s:"以下哪項絶對轉讓和抵押轉讓的描述不正確？",o:["兩者完全相同","抵押轉讓以保單為抵押品","絶對轉讓屬永久性轉讓","以上各項皆是"],a:0,e:"絕對轉讓是不可撤銷地轉讓對某份壽險單的一切擁\n有權，兩者完全不相同"},{c:"4.9",s:"壽險保單的絕對轉讓是指",o:["將保單轉給另一名保險人","有關保單即時變為不可異議","原有的保單所有人已被宣佈破產","不可撤銷地轉讓對某份壽險保單的一切擁有權"],a:3,e:"絕對轉讓屬永久性，不可撤銷地轉讓對某份壽險保\n單的一切擁有權，抵押轉讓安排是暫時性的，通常"},{c:"4.9",s:"當壽險保單轉讓時，保險人對下列哪項較承讓人擁有優先權?",o:["任何逾期未付的保費","任何尚欠的保單貸款","任何尚欠的貸款利息","以上所有各項"],a:3,e:"以上所有各項都是當壽險保單轉讓時，保險人較承\n讓人擁有優先權所作出的行動"},{c:"4.9",s:"以下哪項有關保單轉讓的描述是正確的？",o:["只可以轉讓保險保單價值","轉讓可能要付出代價（即付款）或作為禮物贈送","承讓人必須有可保權益","毋須通知保險人"],a:1,e:"人壽保險轉讓可以是永久性的絕對轉讓，即是不可\n撤銷地轉讓對某份壽險單的一切擁有權，可能規定\n只能以一次過整筆保單利益支付承讓人，答案Ｂ正\n確"},{c:"4.10",s:"如果保單所有人沒有作出選擇，“自動紅利選擇”是指",o:["以現金方式支付","儲存於保險人處以賺取利息或購買清繳增額保險","用以購買保險公司股份","用紅利繳付未來保費"],a:1,e:"“自動紅利選擇”是指儲存於保險人處以賺取利息\n或購買清繳增額保險"},{c:"4.10",s:"如果保單所有人沒有作出紅利選擇，大多數保單會採用一種稱為___________的方式。",o:["自動紅利選擇","現金紅利選擇","保單紅利選擇","以上皆不是"],a:0,e:"如果保單所有人沒有從上述各項中作出選擇，大多\n數保單會採用一種稱為 「 自動紅利選擇\n」的方式。"},{c:"4.11(c)",s:"有一種人壽保單的償付形式，在被保人生前制定好為指定收款人提供定期收益直至終身\n，這個安排意味著",o:["利益以公積金形式償付","用利益購買年金","把有關保單作出修改","把有關保單無限延期"],a:1,e:"在收款人在世時向其分期支付約定的保單收益及利\n息，這項選擇實際上是以該項保單收益作為整付保\n費，購買一份終身年金"},{c:"4.11(e)",s:"終身收益選擇，是分期支付約定的保單收益(及利息)，這項選擇實際上是以該項保單收\n益作為整付保費，購買了甚麼?",o:["儲蓄壽險","投資相連壽險","終身年金","終身壽險"],a:2,e:"這項選擇實際上是以該項保單收益作為整付保費，\n購買一份終身年金"},{c:"4.11",s:"人壽保險支付保險利益的方式",o:["必須是整筆支付","必須包含一項以現金方式一次性支付的選擇","總是以一連串的方式分期給付","可按照保單訂明方式，選擇其中一種方法支付"],a:3,e:"以上皆是人壽保險支付保險利益的方式"},{c:"4.11",s:"人壽保險可選取哪一項或哪些賠付的方式？",o:["整筆給付","固定的給付數額，直至終生","保單支付利息","以上各項皆是"],a:3,e:"以上各項皆是給付保單利益時，受益人或保單所有\n人可以作出的賠付選擇"},{c:"4.11",s:"支付保單利益有很多種方法，誰人可以選擇收取收益的方法?",o:["受益人","保單所有人","以上兩者其中一人","保險人可以選擇支付方法"],a:2,e:"可以選擇收取保險利益方法的可以是受益人及保單\n所有人"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["保險人有權選擇賠付方法","通常是整筆過支付","用利益購買年金","將收益保留在保險人處以賺取利息"],a:0,e:"只有保單持有人或受益人有權選擇賠付方法，答案\nA不屬於壽險保單的賠付選擇"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["通常是整筆過支付","將收益保留在保險人處以賺取利息","用以購買為期一年的定期壽險","保險人分期給付約定等額"],a:2,e:"用以購買為期一年的定期壽險不屬於壽險保單的賠\n付選擇"},{c:"4.11",s:"在傳統的保單條文，以下哪項是給付保單利益時，給受益人或保單所有人的賠付選擇?",o:["以保險公司的股份取代以現金方式支付保單利益","以保單利益購買一份定期壽險作替代壽險","在一段時期內，分期支付保單收益及利息","以上各項皆是"],a:2,e:"受益人收取死亡保險金時，除了一整筆獲支付之外\n，亦可以在一段時期內，分期支付保單收益及利息"},{c:"4.11",s:"除整筆支付保額及其他利益外，應當支持保險金時的賠付選擇包括以下哪項或哪些？",o:["投保人將保險金存於保險人處以賺取利息","將保險金和利息實際上以年金的方式支付","在固定限期內分期支付保險金和利息","以上各項皆是"],a:3,e:"以上各項皆是保險金時的賠付選擇"},{c:"4.11",s:"人壽保險可選取哪一項或哪些賠付的方式",o:["整數給付","固定的給付數額，直至終生","保單支付利息","以上各項皆是"],a:3,e:"以上各項皆是人壽保險可選取賠付的方式"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["即時整筆支付","存放在保險人處以賺取利息","投資於有關保險公司的股份","以上所有各項"],a:2,e:"投資於有關保險公司的股份不屬於壽險保單的賠付\n選擇"},{c:"4.11",s:"人壽保險保險金給付方式有很多種，而理賠給付選擇由以下哪人決定？",o:["受益人","保單所有人","上述兩者中一人","上述兩者均無權(由保險人決定)"],a:2,e:"給付保單利益時，受益人或保單所有人可以作出不\n同的賠付選擇"},{c:"4.11",s:"在理賠時，下列那種方法不是常用的？",o:["整筆支付","以定期定額支付","定額支付","以有關公司的股份支付"],a:3,e:"以有關公司的股份支付不是常用的理賠選擇"},{c:"4.12.1",s:"根據「自殺條款」，當受保人死因有可疑，",o:["舉證責任落在受益人身上","舉證責任落在保險人身上","舉證責任落在警方身上","可假定死亡是由自殺引起"],a:1,e:"根據「自殺條款」，當受保人死因有可疑，舉證責\n任落在保險人身上"},{c:"4.12",s:"由自殺引至死亡發生，如果保單在死亡前不久訂立，要知道死亡是否由自殺所引致，這\n工作由下列誰人負責？",o:["警察","保險人","受益人","保單所有人"],a:1,e:"作為保單的除外責任，證明死亡是由自殺引起的舉\n證責任便落在保險人身上"},{c:"4.12",s:"保險公司通常就索償提供的一種給付，出於善意或恩恤的目的，保險公司在法律上並沒\n有義務就這些索償提供給付，這給付稱為",o:["解除賠付","恩恤賠付","通融賠付","額外賠付"],a:2,e:"出於善意或恩恤的目的，保險公司在法律上並沒有\n義務就這些索償提供給付，這給付稱為通融賠付"},{c:"4.12",s:"以下哪項就自殺除外責任的描述是正確的?\ni. 自殺屬除外責任\nii. 保單生效初期，自殺被列為除外責任\niii. 證明受保人死亡是由自殺引起的責任便落在保險公司身上\niv. 受保人於自殺免責期自殺可能退還已付保費",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:2,e:"保單生效初期，通常為保單發出後一年內；自殺才\n會被列為除外責任。如果受保生命在該免責期之後\n自殺，保險人 會如常的支付 死亡保險金"},{c:"4.12",s:"壽險保單中常用的自殺條款",o:["列明任何時間發生的自殺為除外責任","列明保單生初期﹝通常一年的時間﹞發生的自殺為除外責任","發生這類事件時便會把該保單的保額減低百分之五十","將自殺視作意外處理，而雙倍賠償亦告適用"],a:1,e:"壽險保單中常用的自殺條款列明保單生初期﹝通常\n一年的時間﹞發生的自殺為除外責任"},{c:"4.12",s:"如果死亡是在壽險保單第一年內在可疑的情況下發生,但找不到自殺的證據",o:["法庭將視為自殺","保險人仍須作出全額賠付","保單所有人可得到保險金的50%","保險人很大可能作出通融賠付"],a:1,e:"如果死亡是在壽險保單第一年內在可疑的情況下發\n生,但找不到自殺的證據，保險人仍須作出全額賠\n付"},{c:"4.12",s:"若一份已生效四年的保單的索償是基於自殺,該索償",o:["保險人可拒絕該索償","不會被自殺成因影響","刑事法例不允許支付此索償","保險人只須支付50%死亡金"],a:1,e:"保單生效初期(通常一年)若受保生命自殺列為除外\n責任，一份已生效四年的保單的索償是基於自殺,\n該索償不會被自殺成因影響"},{c:"4.12",s:"壽險保單中的自殺條款目的在於?",o:["阻止人們自殺","把所有涉及自殺的索償無效","避免本著自殺的念頭而購買的人壽保險生效","杜絕所有涉及自殺的索償的可能性"],a:2,e:"自殺除外責任條款是為防止有人藉自殺來取得保險\n金賠償，保險人採取一些防範措施，也絕對是合理\n的。"},{c:"4.12",s:"當保單所有人同時是受保生命，而且被證實於保單生效三個月後自殺身亡，則",o:["這並不相關，而保險人須支付保額","須支付保額，但無須支付任何意外死亡保險賠償","無須支付保額","已證明是欺詐，該索償無效，而已繳保費作廢"],a:2,e:"保單生效初期(通常一年)若受保生命自殺列為除外\n責任，所以受保生命於保單生效三個月後自殺身亡\n，保險人無須支付保額"},{c:"4.12",s:"以下哪項是「自殺條款」的不正確描述？",o:["自殺被列為除外責任","此條款通常為期一年","保單生效初期被列為除外責任","保單生效首年自殺將獲退回所繳保費"],a:0,e:"壽險保單中常用的自殺條款列明保單生初期﹝通常\n一年的時間，發生的自殺為除外責任，答案A不正\n確"},{c:"4.12",s:"以下哪項是形容自殺條款的？",o:["任何時間自殺為除外責任","保單生效初期(通常一年)自殺列為除外責任","保單生效後自殺可取得50%死亡金","任何時間下自殺均不會影響死亡金給付"],a:1,e:"自殺條款保單生效初期(通常一年)自殺列為除外責\n任"},{c:"4.12",s:"在香港，自殺條款的免責期一般為",o:["一個月","一年","二年","十年"],a:1,e:"在香港，自殺條款的免責期一般為一年"},{c:"4.12",s:"由自殺引至死亡發生，如果保單在死亡前不久訂立，要知道死亡是不由自殺所引致，這\n工作由下列誰人負責？",o:["警察","保險人","受益人","保單所有人"],a:1,e:"證明死亡是由自殺引起的舉證責任便落在保險人身\n上"},{c:"5",s:"就人壽保險而言，判斷一項可保性的基本因素可能是",o:["準投保生命的性別","準投保生命的年齡","準投保生命的健康狀況","較大的投保額"],a:2,e:"就人壽保險而言，判斷一項可保性的基本因素可能\n是準投保生命的健康狀況"},{c:"5.1(a)",s:"相互保險公司指",o:["每年股東都只須負上有限負債","公司由股東擁有","所有保單所有人平均攤分利潤及紅利","公司在法律上由分紅保單所有人擁有"],a:3,e:"相互保險公司法律上由分紅保單所有人擁有"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni. 它的股東人數不超過50人\nii. 公司在法律上由分紅保單所有人擁有\niii. 由董事局及高級管理層控制\niv. 相互公司不能轉變成為營利公司",o:["i,ii","i,ii,iv","i,iii,iv","ii,iii"],a:3,e:"「相互」保險公司是沒有股東，世界各地的「相互\n公司」都陸續進行股份化營利公司，只有ii,iii是\n「相互公司」正確描述"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni. 它沒有股東\nii. 公司在法律上由分紅保單所有人擁有\niii. 由董事局及高級管理層控制\niv. 相互公司不能轉變成為營利公司",o:["ii,iii,iv","i,ii","ii,iii","i,ii,iii"],a:3,e:"相互公司並不代表不能轉變成為營利公司，選項iv\n不正確。"},{c:"5.1(a)",s:"以下哪項是指保險公司並沒有股東，而是由分紅保單持有人擁有的？",o:["相互保險公司","合資股份公司","營利公司","人壽保險公司"],a:0,e:"相互保險公司是指保險公司並沒有股東，而是由分\n紅保單持有人擁有的"},{c:"5.1(a)",s:"某些保險公司的名稱含有「相互」的字眼，而該公司是有股東的，該公司已進行了一個\n過程，稱為︰",o:["資本化","股份化","股份登記","不分紅成員確認"],a:1,e:"世界各地的「相互公司」都陸續進行股份化的轉變\n，並\n將其法定地位變成了營利公（或稱股份公司）"},{c:"5.1(a)",s:"相互保險公司的擁有人是",o:["它的股東","一名獨立人士","兩名或以上的合伙人","它的分紅保單所有人"],a:3,e:"相互保險公司的擁有人是分紅保單所有人"},{c:"5.1(a)",s:"相互保險公司在法律上由分紅保單所有人擁有，而其管理是由什麼人負責？",o:["股東","保單所有人","董事局及高級管理層","代理人"],a:2,e:"相互保險公司在法律上由分紅保單所有人擁有，擁\n有，由董事局及高級管理層控制"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni) 它沒有股東\nii) 它由分紅保單持有人共同擁有\niii) 它含有相互的字眼，故運作必然是相互的\niv) 由董事局及高級管理層控制",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"即使一間保險公司的名稱含有「相互」的字眼，也\n不能肯定它就是如上文所指的「相互」公司。選項\niii不正確"},{c:"5.1(a)",s:"如果一間公司已經進行股份化過程，其意思為",o:["該公司已經停止交易","該公司出現財政困難，將被清盤","該公司已不再打算設立股東","該公司已將其法定地位轉為營利公司"],a:3,e:"世界各地的「相互公司」都陸續進行股份化的轉變\n，並將其法定地位變成了營利公（或稱股份公司）"},{c:"5.1(b)",s:"以下哪種情況下，營利(或合資股份公司)，不能強迫股東就公司虧損或資本需求提供額\n外資金，如果",o:["已經向他們發出股票","股東已完全清繳股票價值","公司已有足夠資本並開始交易","某段期間會計紀錄經已完結"],a:1,e:"營利公司（或稱股份公司）：這是更普遍的公司結\n構，是由股東共同擁有的股份有限責任公司，一旦\n股東「完全清繳」他所擁有的股票的價值，便不必\n再為公司的虧損或資本需求提供任何額外的資金。"},{c:"5.1(b)",s:"營利股份保險公司中股東「完全清繳」是指",o:["營利公司可以進行交易","營利公司不能發行股份作進一步集資","營利公司的股東須要承擔未來的債務","營利公司的股東對未來債務再沒有責任"],a:3,e:"「有限責任」指：一旦股東「完全清繳」他所擁有\n的股票的價值，便不必再為公司的虧損或資本需求\n提供任何額外的資金。"},{c:"5.1(g)",s:"負責決定所需的再保險程度並針對個別風險情況，作出適當的再保險安排的部門是",o:["核保部","精算部","理賠部","市場行銷部"],a:0,e:"負責決定所需的再保險程度並針對個別風險情況，\n作出適當的再保險安排的部門是核保部"},{c:"5.1.1",s:"保險公司的會計部相當可能負責下列哪項或哪些部份 ?",o:["財務收入","財務支出","法例要求的財務報告","以上所有各項"],a:3,e:"以上所有各項都是保險公司的會計部相當可能負責\n的部份"},{c:"5.1.1(a)",s:"保險公司會計部的主要職能和責任包括：\ni) 記錄公司收入\nii) 監管公司支出\niii) 遵守(保費守則)\niv) 遵守(保險代理操守守則)",o:["i, ii","i, iii","iii,iv","ii,iii"],a:0,e:"遵守(保費守則)及遵守(保險代理操守守則)不屬保\n險公司會計部的職責，選項iii&iv不正確"},{c:"5.1.1(a)",s:"保險公司會計部的主要職能和責任包括：\ni) 記錄公司收入\nii) 監管公司支出\niii) 提交已審核的財務報告\niv) 處理電話投訴",o:["i, ii 及 iii","i, iii 及 iv","ii, iii 及 iv","以上各項都是"],a:0,e:"處理電話投訴不屬保險公司會計部的主要職能和責\n任"},{c:"5.1.1(a)",s:"下列哪一項通常不是人壽保險公司會計部的標準功能？",o:["監管由公司支付的所有款項","紀錄由公司支付及收取的所有款項","按相關法例要求提交經審核的財務報告","確定死亡及其他保單索償的實際應付金額"],a:3,e:"確定死亡及其他保單索償的實際應付金額不屬保險\n公司會計部的主要職能和責任"},{c:"5.1.1(b)",s:"保險公司的精算部很有可能負責以下那項",o:["產品定價","理賠及再保險","資產及負債估值","以上所有各項"],a:3,e:"以上所有各項皆是保險公司的精算部很有可能負責"},{c:"5.1.1(b)",s:"保險公司精算部的工作是以下哪項或哪種?",o:["產品定價","理賠及再保險","資產及負債估值","以上各項皆是"],a:3,e:"以上各項皆是保險公司精算部的工作"},{c:"5.1.1(c)",s:"以下哪項或哪些不屬代理培訓與管理部門的職能？",o:["代理隊伍的培訓需要","保險公司的定價策略","專業考試","事業發展中的資源和設施"],a:1,e:"保險公司的定價策略不屬代理培訓與管理部門的職\n能"},{c:"5.1.1(d)",s:"以下哪項較可能直接涉及理賠部門功能？",o:["監管由公司支付的所有款項","紀錄由公司支付及收取的所有款項","近因的調查核証工作","以上各項皆是"],a:2,e:"只有近因的調查核証工作較可能直接涉及理賠部門\n功能"},{c:"5.1.1(d)",s:"以下哪項較不可能直接涉及理賠部門功能？",o:["核保風險等技術性問題","日常理賠行政及處理","有關必需的索償調查","進行詳細查閱驗屍報告"],a:0,e:"核保風險等技術性問題屬理賠部責任"},{c:"5.1.1(e)",s:"下列哪項不大可能屬於保單所有人服務部的職能？",o:["通訊","收取保費","索償處理","權益管理"],a:2,e:"索償處理屬理賠部負責"},{c:"5.1.1(e)",s:"保險公司顧客服務部的一般工作包括",o:["通訊","文件整理","保單續保","以上各項都是"],a:3,e:"以上各項都是保險公司顧客服務部的工作"},{c:"5.1.1(f)",s:"壽險公司的典型市場行銷部的職責不可能包括以下哪項？",o:["公共關係","「次標準生命」的定義","產品研究","市場調查"],a:1,e:"「次標準生命」的定義不大可能是人壽保險公司市\n場行銷部的責任"},{c:"5.1.1(f)",s:"下列哪項不大可能是人壽保險公司市場行銷部的責任？",o:["市場調查","產品研究","理賠給付","推廣/宣傳"],a:2,e:"理賠給付不大可能是人壽保險公司市場行銷部的責\n任"},{c:"5.1.1(g)",s:"下列哪個部門決定就所需的再保險程度並針對特定風險情況，作出適當的再保險安排？",o:["風險管理","精算","核保","顧客服務"],a:2,e:"決定就所需的再保險程度並針對特定風險情況，作\n出適當的再保險安排的是核保部門"},{c:"5.1.1(g)",s:"下列哪項功能較不可能直接涉及核保部？",o:["安排並監督身體檢查","進行風險的選擇、評級以及按需要附加限制條款等技術性問題","安排驗屍報告工作","決定是否需要為投保進行再保險"],a:2,e:"安排驗屍報告工作較不可能直接涉及核保部"},{c:"5.2.1",s:"以下哪項是不大可能於投保單出現的資料?",o:["下一個生日年齡","職業、住址及家族病歷","保險代理的佣金率","保單所需的生效日期"],a:2,e:"保險代理的佣金率不屬投保單出現的資料"},{c:"5.2.1",s:"以下哪項對投保單的描述是不正確的？",o:["有些保險人稱之建議書","經修正或改動的投保單，保險人必定不會接受","它通常由投保人親自填寫","它是核保資料的來源"],a:1,e:"如可能的話，應儘量避免改動及修正投保單。任何\n不正確的地方必須清楚地刪除，同時經修正之處應\n由投保人簽名並註明日期，答案B不正確"},{c:"5.2.1(a)",s:"投保單應由誰負責填寫？",o:["投保人","代理人","顧客服務部職員","受益人"],a:0,e:"投保單應由投保人負責填寫"},{c:"5.2.1(a)",s:"以下哪項或哪些為填寫投保書的一般規則？",o:["必須披露所有重要事實","不得修改","必須見證","以上各項皆是"],a:0,e:"投保單是唯一的核保所需的資料來源，在填寫投保\n單時，保險中介人應該特別留意自己對客戶所提供\n的建議和幫助，提醒客戶提供所有重要事實"},{c:"5.2.1(b)",s:"以下哪項是處理人壽險保投保時是應注意的事項？\ni) 下一個(或上一個)生日年齡\nii) 投保人的身份\niii) 保單生效日期\niv) 投保人過去三年的職業紀錄",o:["i, iii","ii, iii","i,ii,iii","i,ii, iii, iv"],a:2,e:"投保人過去三年的職業不是處理人壽險保投保時是\n應注意的事項，選項iv不正確，正確答案是C。"},{c:"5.2.1(b)",s:"以下哪三項在進行核保時是應考慮？\ni) 下一個(或上一個)生日年齡\nii) 投保人的身份\niii) 保單生效日期\niv) 由誰人支付保費",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"由誰人支付保費,不是核保時是應考慮的重要因素"},{c:"5.2.1(b)",s:"以下哪項不大可能出現於壽險保單的投保單上？",o:["下一個(或上一個)生日年齡","投保人的身份","保單生效日期","將由投保人以外人士支付保費"],a:3,e:"由投保人以外人士支付保費不大可能出現於壽險保\n單的投保單上"},{c:"5.2.1(c)",s:"準受保保單所有人在投保時，除了要填寫投保書外，有時亦需要提供補充資料，以下哪\n一項不屬需要提供補充資料?\ni. 投保人的風險管理計劃\nii. 有否兼職\niii. 繳付保費方式\niv. 對某些疾病或其他事項填寫問卷提供額外資料",o:["i, ii","i, iii, iv","iii, iv","i, ii, iii, iv"],a:0,e:"投保人的風險管理計劃，以及有否兼職不屬投保時\n需要提供補充資料"},{c:"5.2.1(c)",s:"在投保的過程中，核實受保生命的身份資料是很重要的，下列哪些不屬於「補充要求」\n呢？",o:["代理人之核實証明","可保性證明","繳付保費方式","壽險代理人報告"],a:0,e:"代理人之核實証明不屬於投保單的「補充要求」"},{c:"5.2.1(c)",s:"準受保保單所有人在投保時，除了要填寫投保書外，有時亦需要提供補充資料，包括﹕",o:["繳付保費方式","核保問卷","可保性證明","以上各項都是"],a:3,e:"以上各項都是投保人投保時需要提供補充資料"},{c:"5.2.1(c)",s:"以下哪項不是投保時保險公司的補充要求？",o:["可保性證明","繳付保費方式","誰會繳付保單的保費","核保問卷"],a:2,e:"誰會繳付保單的保費不是投保時保險公司的補充要\n求"},{c:"5.2.10",s:"根據《重要資料聲明書-\n內地人士在港投購人身/壽險保單,內地客戶簽署時該聲明書必須為",o:["繁體中文版本","簡體中文版本","英文及繁體中文版本","沒有限制"],a:1,e:"根據《重要資料聲明書-\n內地人士在港投購人身/壽險保單,內地客戶簽署時\n該聲明書必須為簡體中文版本"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["提前提取保單費用","提前退保費用","紅利","冷靜期"],a:3,e:"參考章節5.2.10&附件M 冷靜期不屬《重要資料聲明\n書－內地人士在港投購人身╱壽險保單》涵蓋的部\n分，詳細 研集資料手冊附件M"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","投資風險","保險回報率"],a:2,e:"投資風險不屬《重要資料聲明書－內地人士在港投\n購人身╱壽險保單》涵蓋的部分，詳細參閱研集資\n料手冊附件M"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","回佣協議","政策改變","投資風險"],a:3,e:"投資風險不屬《重要資料聲明書－內地人士在港投\n購人身╱壽險保單》涵蓋的部分，詳細參閱研集資\n料手冊附件M"},{c:"5.2.10",s:"《重要資料聲明書－內地人士在港投購人身╱壽險保單》，以下哪些人須遵守？",o:["經營投資相連長期業務以外的長期業務的獲授權保險人","經營投資相連長期業務以外的長期業務的獲授權保險代理人及保險經紀","經營長期業務的獲授權保險人","提供人身及包括意外險在內的壽險的人士"],a:2,e:"《重要資料聲明書－內地人士在港投購人身╱壽險\n保單》，供經營長期業務的獲授權保險人遵守"},{c:"5.2.10&附件M",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","保險回報率","冷靜期"],a:3,e:"冷靜期不屬《重要資料聲明書－內地人士在港投購\n人身╱壽險保單》涵蓋的部分，詳細\n研集資料手冊附件M"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["公司抽獎","特定花紅","品牌建立禮品","網絡優惠劵"],a:3,e:"網絡優惠劵不屬指引25內指明的許可禮品"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["身體檢查服務","醫療咨詢服務","緊急救助支援","超市禮券"],a:3,e:"超市禮券，不屬（指引25）內指明的許可禮品"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["為客戶提供合規的支援","講座服務","就財務軟件提供支援","個人恩惠"],a:3,e:"個人恩惠，不屬（指引25）內指明的許可禮品"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["獲分配的基金單位花紅","獎勵計劃下累積的積分","為客戶提供 的贊助和支援","現金禮券"],a:3,e:"現金禮券，不屬（指引25）內指明的許可禮品"},{c:"5.2.2",s:"人壽保單投保人連同首期保費投保，人壽保險人已簽發保費收據。因詢問過程需時，剛\n巧在保險交付前投保人遇上交通意外身故，後來證實投保人按照標準條款是屬於可保的",o:["不論任何的保費收據類型索償均屬無效","不論任何的保費收據類型索償均屬有效","只有附條件保費收據索償有效","只有立約(不附條件) 保費收據索償有效"],a:1,e:"如果事故後能確定投保人在投保時乃屬按照標準條\n款並具有可保性的，不論附條件保費收據或立約保\n費收據的索償均屬有效"},{c:"5.2.2(a)",s:"人壽保險人透過簽發其中一種的保費收據，表示同意有關保險於投保時開始生效，但須\n於稍後證實投保人按照標準條款是屬於可保的。這種收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:2,e:"附條件保費收據須於稍後證實投保人按照標準條款\n是屬於可保的，有關保險於投保時開始生效"},{c:"5.2.2(b)",s:"就立約保費收據，以下哪項描述不正確?",o:["也稱為不附條件保費收據","可視為與保險人的臨時保險協議","保險人不可提前結束終止具有約束力的保險保單","保障具有約束力，保障期最長只限於指定的日數"],a:2,e:"就立約保費收據又稱暫保單，保險人可以提前結束\n終止具有約束力的保險保單"},{c:"5.2.2(b)",s:"就立約保費收據而言，下列哪幾項是正確的?\ni) 它們亦稱為不附條件保費收據\nii)它們構成一份獨立於任何其後簽發之保單的合約\niii)於投資相連投險業務普遍不適用\niv)是否提供保障並不以投保人的可保性為條件",o:["i, ii, iii","i, ii, iv","i, iii, iv","以上各項都是"],a:1,e:"就立約保費收據而言，沒有明文規定於投資相連投\n險業務普遍不適用，選項iii不正確"},{c:"5.2.2(b)",s:"在人壽保險中，保險人所簽發的保費收據，已具有可保性的，可於指定日期內提出終止\n保障，這種收據稱為",o:["立約保費收據","可撤銷保費收據","暫時性保費收據","附條件保費收據"],a:0,e:"人壽保險中，保險人所簽發的保費收據，已具有可\n保性的，可於指定日期內提出終止保障，這種收據\n稱為立約保費收據"},{c:"5.2.2(b)",s:"立約保費收據有另一名稱，其中TIA全名為",o:["定期被接納保險 Term Insurance accepted","臨時保險證明 Temporary Insurance acknowledge","臨時保險協議 Temporary Insurance agreement","定期保險申請 Term Insurance application"],a:2,e:"立約保費收據有另一名稱，其中TIA全名為臨時保\n險協議 Temporary Insurance agreement"},{c:"5.2.2(b)",s:"在非人壽保險的保單中，有類似文件以提供暫時性、不附帶條件、但可取消的保障稱爲\n暫保單。在人壽保險亦有一種類似這種的收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:1,e:"立約保費收據又叫不附帶條件保費收據、或可取消\n的保障稱爲暫保單。"},{c:"5.2.2(b)",s:"在人壽保險付款後所得的收據分為兩種，一種是立約保費收據，另一種是",o:["暫時性保費收據","附條件保費收據","不附條件保費收據","永久保費收據"],a:1,e:"在人壽保險付款後所得的收據分為兩種，一種是立\n約保費收據，另一種是附條件保費收據"},{c:"5.2.2(b)",s:"在非人壽保險中，有不附帶條件、具短暫時期但可取消的保障稱為暫保單，在人壽保險\n中亦有類似文件稱為",o:["立約保費收據","保險憑證","附條件保費收據","暫時憑證"],a:0,e:"在非人壽保險中，有不附帶條件、具短暫時期但可\n取消的保障稱為暫保單，在人壽保險中亦有類似文\n件稱為立約保費收據"},{c:"5.2.2(b)",s:"以下哪項正確描述「立約保費收據」？\ni) 又稱為不附條件保費收據\nii) 此收據是獨立於其後所發簽的任何保單\niii) 保障會以事後能否證明投保人可保為條件\niv) 保障可能在指定期的最後一天前提前終止",o:["i, ii, iii","i, ii, iv","i, iii, iv","以上各項都是"],a:1,e:"「立約保費收據」保障並不以事後能否證明投保人\n可保或已經具有可保性為條件，選項iii不正確"},{c:"5.2.2(b)",s:"在人壽保險付款後所得的收據分為兩種，一種是附條件保費收據，另一種是",o:["最後保費收據","立約保費收據","永久保費收據","無條件保費收據"],a:1,e:"在人壽保險付款後所得的收據分為兩種，一種是附\n條件保費收據，另一種是立約保費收據"},{c:"5.2.2(b)",s:"就立約保費收據而言，下列哪三項是正確的?\ni)它們亦稱為不附條件保費收據\nii)它們構成一份獨立於任何其後簽發之保單的合約\niii)是否提供保障並不以投保人的可保性為條件\niv)如果事後證明投保人為不可保，便可取消有關保障",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii , iii , iv"],a:0,e:"立約保費收據收據本身是一份合約，保障由投保人\n簽署投保單並繳清有關保費之日開始生效，選項iv\n不正確"},{c:"5.2.3",s:"以下哪項是提供優質顧客服務所考慮的因素?\ni. 提高客戶忠誠度\nii. 不得提供敏感資訊\niii. 不得承擔責任\niv. 提高生產及盈利能力",o:["i,ii","i,ii,iii","i,iv","ii,iii,iv"],a:2,e:"只有提高客戶忠誠度及提高生產及盈利能力是提供\n優質顧客服務所考慮的因素，選i,iv正確"},{c:"5.2.3a",s:"客戶忠誠度、客戶拓展、生產力及盈利能力為哪一個部門的主要功能？",o:["會計部","行政及管理部","顧客服務部","市場行銷部"],a:2,e:"客戶忠誠度、客戶拓展、生產力及盈利能力為顧客\n服務部的主要功能"},{c:"5.2.3b",s:"達致高素質的顧客服務的因素是?",o:["公司文化","權力下放","A&B","以上皆不正確"],a:2,e:"公司文化及權力下放是達致高素質的顧客服務的因\n素"},{c:"5.2.3b",s:"人壽保險業務達致高素質的顧客服務考慮的因素",o:["系統","培訓","A及B","以上各項皆不是"],a:2,e:"選項A及B都是人壽保險業務達致高素質的顧客服務\n考慮的因素"},{c:"5.2.3b",s:"以下哪項或哪些能夠提高客戶服務的效率",o:["以客戶為本的公司文化","把合理及適當的權力下放於前線僱員","設有監察客戶滿意程度的系統","以上各項都是"],a:3,e:"以上各項都是提高客戶服務的效率"},{c:"5.2.4",s:"投保人可就新購買的人壽保單更改購買意願，或取消保單並取回已繳保費，此做法是符\n合以下哪項規定？",o:["冷靜期","免保期","等候期","寬限期"],a:0,e:"投保人可就新購買的人壽保單更改購買意願，或取\n消保單並取回已繳保費，此做法是符合冷靜期規定"},{c:"5.2.4",s:"在冷靜期指引中，所有投資相連保單及非投資相連整付保費保單，保險人可從退還保費\n中減去市值調整。對於其他非投資相連保單，以下哪項是正確的描述﹕",o:["不允許退還已繳保費","可退還已繳保費的50%","可退還已繳保費的100%","所退還百分比按取消保單的日期而變動"],a:2,e:"在冷靜期指引中，所有投資相連保單及非投資相連\n整付保費保單，保險人可從退還保費中減去市值調\n整。對於其他非投資相連保單，可退還已繳保費的\n100%"},{c:"5.2.4",s:"投保人可就新購買的人壽保單改變主意，取消保單並取回已繳保費，此做法是符合以下\n哪項規定？",o:["香港保險業聯會發出的轉保守則","保險業監管局制訂 《冷靜期指引》 指引 29","證券及期貨事務監察委員會發出的市值調整","證券及期貨事務監察委員會發出的規定聲明"],a:1,e:"投保人可就新購買的人壽保單改變主意，取消保單\n並取回已繳保費，此做法是符合保險業監管局制訂\n《冷靜期指引》 指引 29規定"},{c:"5.2.4(c)",s:"冷靜期是指允許保單所人就新購或已申請的人壽保險保單，在一段時間內改變主意，但\n容許保險人對下列哪類保單從退還的保費中減去「市值調整」？",o:["所有類別人壽保單","儲蓄壽險保單","定期壽險保單","投資相連保單"],a:3,e:"投資相連或非投資相連整付保費人壽保單，於冷靜\n期內取消保單，須從退還的保費中減去「市值調整\n」"},{c:"5.2.5",s:"保單持有人於已購買人壽保險保單的情況下，可能在期後會考慮購買另一份人壽保險保\n單以取代（全部還是部分的）最初所購買的人壽保險保單，此行為稱為",o:["保單失效","轉保","不能作廢","以上各項皆不是"],a:1,e:"考慮購買另一份人壽保險保單以取代最初所購買的\n人壽保險保單，此行為稱為轉保"},{c:"5.2.5(a)",s:"以下哪項是誘導轉保的正確陳述",o:["作出誤導的言論或比較","為客戶轉換保費","透過不正當手法誘使取代現有壽險保單","為客戶轉換保單條款"],a:2,e:"誘導轉保是透過不正當手法誘使取代現有壽險保單"},{c:"5.2.5(a)",s:"「轉保」是以另一份保單代替現有保單",o:["這絕對是非法的","這是保險代理合約所禁止","它可能完全是合理及合法的","這往往是一種符合道德的商業手段"],a:2,e:"「轉保」是以另一份保單代替現有保單它可能完全\n是合理及合法的"},{c:"5.2.5(a)",s:"利用誤導性的陳述等使被保險人更改現有壽險安排，轉而投購另一份使被保險人利益遭\n受不良影響的人壽保險，這種活動稱為",o:["誘導轉保","作弊","貪污","轉換保單"],a:0,e:"利用誤導性的陳述等使被保險人更改現有壽險安排\n，轉而投購另一份使被保險人利益遭受不良影響的\n人壽保險，這種活動稱為誘導轉保"},{c:"5.2.5(a)",s:"如果代理人妄顧客人利益，將其現有保單轉投至其他保險公司，這稱為",o:["欺騙顧客","誘導轉保","合法轉保","欺詐顧客"],a:1,e:"誘導轉保是透過不正當手法誘使取代現有壽險保單"},{c:"5.2.5(a)",s:"利用誤導性陳述，不披露某些資料，錯誤陳述及對保單作出不詳實的比較，誘使投保人\n更改現有壽險安排，轉而投購其他壽險保單，即視為",o:["誘導轉保（Twisting）","回佣 (Rebating)","轉保 (Replacement)","客戶保障聲明 (cPd)"],a:0,e:"誘導轉保是透過不正當手法誘使取代現有壽險保單"},{c:"5.2.5(c)",s:"作為客戶的保障，客戶在同意購買或決定是否購買一份新的人壽保險前，必須填妥一份\n重要文件，這份文件是?",o:["冷靜期權益","抵押保障文件","《重要資料聲明書 --轉保》","消費者保障聲明書"],a:2,e:"作為客戶的保障，客戶在同意購買或決定是否購買\n一份新的人壽保險前，必須填妥一份重要文件，這\n份文件是《重要資料聲明書 --轉保》"},{c:"5.2.6",s:"就紅利金額派發，匯集基金在特定期間的業績情況與同一段期間三個因素關係密切。一\n般而言，以下哪項對紅利額有最大的影響？",o:["匯集基金的費用","匯集基金的賠付金","匯集基金的投資回報","證券市場的平均表現"],a:2,e:"一般來説，所宣佈及派發的紅利金額與相關的分紅\n保單的匯集基金的業績情況有直接的關係的。"},{c:"5.2.6",s:"以下哪項不是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨\n回報率?",o:["0","2%","4%","以上各項皆不是"],a:2,e:"投資壽險保單利益說明文件的具體規定獲授權保險\n人可選擇闡述的假設淨回報率是:0%,3%,6%,9%,或\n較低的0%, 2%,5%,7%"},{c:"5.2.6",s:"以下哪項是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨回\n報率?",o:["3%","8%","1%","以上各項皆是"],a:0,e:"投資壽險保單利益說明文件的具體規定獲授權保險\n人可選擇闡述的假設淨回報率是:0%,3%,6%,9%,或\n較低的0%, 2%,5%,7%"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","具現金價值的保單","展期保險保單"],a:3,e:"對於額清繳保險保單及展期保險保單，非分紅保單\n；及\n投資相連壽險計劃保單而言，可由保險人選擇是否\n發出有效利益說明"},{c:"5.2.6",s:"以下哪項是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨回\n報率?",o:["0%","1%","8%","以上各項皆是"],a:0,e:"投資壽險保單利益說明文件的具體規定獲授權保險\n人可選擇闡述的假設淨回報率是:0%,3%,6%,9%,或\n較低的0%, 2%,5%,7%"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","所有類別人壽保單","投資相連壽險計劃（“投連壽險”）保單"],a:3,e:"就保監局發出的指引28投資相連壽險計劃（“投連\n壽險”）保單可由獲授權保險人選擇是否發出有效\n利益說明"},{c:"5.2.6(a)",s:"根據投資壽險保單利益說明文件的具體規定，文件反映費用及收費必須",o:["只需包括基金經理收取的基金管理費用","包括所有保單層面的費用，包括基金經理收取的基金管理費用","反映所有保單層面的費用及收費(但不包括基金管理費用)","以上各項皆正確"],a:2,e:"根據投資壽險保單利益說明文件的具體規定，文件\n反映費用及收費必須反映所有保單層面的費用及收\n費(但不包括基金管理費用)"},{c:"5.2.6a",s:"以下哪項是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨回\n報率?",o:["2%","3%","7%","以下各項皆是"],a:3,e:"投資壽險保單利益說明文件的具體規定獲授權保險\n人可選擇闡述的假設淨回報率是:0%,3%,6%,9%,或\n較低的0%, 2%,5%,7%"},{c:"5.2.6a",s:"投資壽險保單利益說明文件須基於至少3個不同的「假設回報率」。對這些息率的要求是",o:["低者不應高於 0% 及高者不應高於 6%","高者不應高於9%，但低者可以是任何數值","低者不應高於5%，但高者可以是任何數值","除 0%外，可使用比 3%,6%較低的百分比來計算"],a:3,e:"就上述兩個選項而言，除 0%的假設年度淨回報率\n外，所有其他回報率（即 3%、 6%及 9%）為獲授\n權保險人可採用的最高回報率。獲授權保險人亦\n可選擇使用較低的假設年度淨回報率（如 0%、\n2%、5%及 7%）作闡述。"},{c:"5.2.6a",s:"保險計劃建議書根據甚麼預期保費抵銷?",o:["預期所有的現金紅利購買減額清繳保險","每年支付的均衡保費","對未來的投資表現有利","以上各項皆不是"],a:3,e:"保費抵銷預期將來的現金紅利存放於保險人那裏，\n保單持有人有權選擇停止繳付保費，但須注意是，\n未來利率水平可以下降的，到時客戶須要恢復掏錢\n付保費，否則可能導致保單失效，以上各項皆不是\n保費抵銷正確描述"},{c:"5.2.6a",s:"(投資)相連保單規定，回報率及投資該產品的退保發還金額需在退保現金價值計算表後\n列明，這規定名為",o:["規定聲明","保單所有人聲明","預防陳述","預防聲明書"],a:0,e:"投資)相連保單規定，回報率及投資該產品的退保\n發還金額需在退保現金價值計算表後列明，這規定\n名為規定聲明"},{c:"5.2.6a(a)",s:"非分紅保單利益說明文件的具體規定適用於?",o:["投資相連壽險","儲蓄壽險","終身壽險","在整個保單期內僅提供保證利益價值的非分紅保單"],a:3,e:"非分紅保單利益說明文件的具體規定適用於在整個\n保單期內僅提供保證利益價值的非分紅保單"},{c:"5.2.6a(a)",s:"指引十六規定必須就不同情景向客戶提供關乎保費抵銷的預期數字。保險還須警告客戶\n，保費抵銷的可持續性取決於",o:["已累積的紅利","現金紅利","將來宣佈的紅利","以上各項皆是"],a:2,e:"保費抵銷的可持續性取決於將來宣佈的紅利，但當\n利率水平下降，到時客戶須要恢復掏錢付保費，否\n則可能導致保單失效"},{c:"5.2.6a(b)(i)",s:"在投資壽險保單利益說明文件中，要求有關之保險公司必須說明「退保發還金額」，並\n要求說明該計劃在合約某些時段內預計可取回的金額，此等時段包括保單首5年的每個年\n度終結時與及其後的每個",o:["年度","3年","5年","10年"],a:2,e:"投資壽險保單利益說明文件的具體規定，說明文件\n應顯示首五個保單年度之每一個年末的預計退保發\n還金額及身故賠償額，並於其後至少每五年的期間\n顯示該等資料，直至保單年期屆滿或終結"},{c:"5.2.7",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni. 保險人一般會將紅利平均派發，以減低短期大幅波動\nii. 紅利金額是基於獲委任精算師的意見\niii. 紅利金額是基於獲委任財務總裁的意見，並經精算師批准而釐定\niv. 保險人一般保留釐定紅利金額的權利",o:["i,ii","ii,iii,iv","i,ii,iv","ii,iii"],a:2,e:"紅利派發金額視乎匯集基金的業績情況而定，保險\n人一般保留釐定紅利金額的權利。實務上，紅利金\n額是基於獲委任精算師的意見，並經各董事會批准\n而釐定的。選項iii不正確，正確答案是C"},{c:"5.2.7",s:"相對投資相連保單，以下哪項不是分紅保單的好處?\ni. 回報風險較投資相連保單低\nii. 高透明度保險制度\niii 保單價值由精算師監管\niv. 靈活性",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:3,e:"相對投資相連保單，分紅保單的好處是較投資相連\n保單風險低，選項ii,iii,iv都不是分紅保單的好\n處，正確答案是D"},{c:"5.2.7",s:"一名謹慎的保險人，只會在以下哪情況下宣佈發放紅利？",o:["保險人投資表現優於市場表現","保險人投資表現不差於市場表現","得知了實際的業績情況比其之前所作的精算和財務假設更有利後才宣佈保單紅利","期望匯集基金業績優於市場表現"],a:2,e:"一名謹慎的保險人，只會在得知了實際的業績情況\n比其之前所作的精算和財務假設更有利後才宣佈保\n單紅利"},{c:"5.2.7",s:"相對投資相連保單，分紅保單的好處是︰\ni. 有保證的現金價值及死亡利益\nii. 保單所有人所承受的投資風險較低\niii. 有獨立的精算師監管\niv. 分紅保單的回報一般是平均派發",o:["i, ii, iii","i, ii, iv","ii,iii,iv","i,iii,iv"],a:1,e:"有獨立的精算師監管不屬有獨立的精算師監管分紅\n保單的好處，只有選項i, ii, iv正確"},{c:"5.2.7a",s:"分紅保單是帶著保單紅利回報的期望而購買的，這些紅利來自？",o:["基金的投資回報","保險人的整體業務","匯集基金的投資回報","股票市場上的水平"],a:2,e:"一般來説，所宣佈及派發的紅利金額與相關的分紅\n保單的匯集基金的業績情況有直接的關係的。"},{c:"5.2.7a",s:"指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，必須以清晰及統\n一的計算方式及披露方式向客戶準確披露以下哪項的資料？",o:["非保證紅利／英式紅利實現率及過往派息率","承保長期保險的回報率及收益率","非保證預期紅利率及過往派息比率","承保分紅保單的預期紅利率及過往派息率"],a:0,e:"指引16的規定，銷售分紅（或有利潤）保單或萬用\n壽險保單的保險人，必須以清晰及統一的計算方式\n及披露方式向客戶準確披露非保證紅利／英式紅利\n實現率及過往派息率"},{c:"5.2.7a",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni.通貨膨脹期間保險人只會派發最低額的紅利\nii. 保險人一般保留釐定紅利金額的權利\niii.紅利金額是基於獲委任精算師的意見，並經董事會批准而釐定\niv.傳統分紅保單規定了上升的紅利率",o:["i , ii","ii, iii","ii,iv","i,ii,iii,iv"],a:1,e:"保險人一般保留釐定紅利金額的權利。紅利金額是\n基於各自的獲委任精算師的意見，並經各自的董事\n會批准而釐定的。只有選項ii,iii正確"},{c:"5.2.7a",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni.保險人一般會將紅利平均派發，以減低短期大幅波動\nii.紅利金額是基於獲委任精算師的意見而釐定的\niii.紅利金額是基於獲委任精算師的意見，並經董事會批准而釐定\niv.保險人一般保留釐定紅利金額的權利",o:["i,ii","ii,iii","i,iii,iv","i, iii"],a:2,e:"保險人一般保留釐定紅利金額的權利。紅利金額是\n基於獲委任精算師的意見，並經董事會批准而釐定\n的。保險人可因應政策決定平均派發的方法，選項\nii不正確"},{c:"5.2.7a",s:"一個謹慎的保險人會根據以下甚麼情況才宣佈保單紅利?",o:["保險人的投資表現優於市場表現","保險人的投資表現不差於市場表現","於滙集基金的表現優於市場表現","以上皆非"],a:3,e:"一個謹慎的保險人只會在得知了實際的業績情況比\n其之前所作的精算和財務假設更有利後才宣佈保單\n紅利的，以上各項都不正確"},{c:"5.2.7a",s:"就保單紅利額建議，精算師會考慮幾個因素，不包括︰",o:["國際市場因素","匯集基金業績","經濟展望","如何公平的對待匯集基金内並存的各類保單持有人及在不同時間投保的保單持有人"],a:0,e:"就保單紅利額建議，精算師會考慮因素，不包括國\n際市場因素"},{c:"5.2.7a",s:"就保單紅利的派發而言,什麼是匯集基金?",o:["它是指相關的保險人隨著提供了分紅保單而在其資產負債表上顯示出來的資產的全部,\n而之後保險人須為這些保單管理該等資產","它是指相關的保險人隨著經營一切類型的長期保險業務而在其資產負債表上顯示出來\n的資產的全部","它是指相關的保險人隨著提供了分紅保單而在其保費收入的全部顯示出來的資產的全\n部","它是指相關的保險人隨著提供了分紅保單而在已扣除日常開支的保費收入的全部顯示\n出來的資產的全部"],a:0,e:"所謂「匯集基金」是指相關的保險人隨着提供了分\n紅保單而在其資產負債表上顯示出來的資產的全部\n，而之後保險人須為這些保單管理該等資產"},{c:"5.2.7a",s:"就保單紅利的派發而言,什麼是匯集基金?",o:["它是指相關的保險人隨著經營一切類型的長期保險業務而在其資產負債表上顯示出來\n的資產的全部","它是指保險人的股本的全部","它是指相關的保險人隨著提供了分紅保單而在其資產負債表上顯示出來的資產的全部,\n而之後保險人須為這些保單管理該等資產","它是指相關的保險人隨著顯示出來的已扣除日常開支的保費收入的全部"],a:2,e:"供了分紅保單而在其資產負債表上顯示出來的資產\n的全部，而之後保險人須為這些保單管理該等資產"},{c:"5.2.7a",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？",o:["個別公司的紅利政策須遵守具體的自我規管政策","典型的分紅保單在首三個年度不會派發紅利","個別公司一般保留釐定紅利金額的權利","典型的分紅金額必然為持上升趨勢"],a:2,e:"紅利金額視乎匯集基金的業績情況而定的。也值得\n注意，保險人一般保留釐定紅利金額的權利。"},{c:"5.2.7a",s:"按照派發方式，保單紅利共有三種，包括",o:["延遲紅利","即時紅利","現金紅利","最後紅利"],a:2,e:"按照派發方式，保單紅利共有三種，包括現金紅利"},{c:"5.2.7b",s:"派發紅利方式共有三種，其中一種是",o:["即時紅利","期終額外紅利","延遲紅利","以上各項皆是"],a:1,e:"在香港，保單紅利一般是透過三種方式派發的，分\n別是派發現金紅利，復歸紅利及期終額外紅利"},{c:"5.2.7c",s:"以下哪些不是關於保費抵銷的正確描述？\ni) 將現金紅利存放於保險人\nii) 對未來業績表現有利\niii) 保單持有人有權選擇停止繳付保費\niv) 將來的保費開支特別低",o:["i,ii","i,ii,iii","ii,iv","i,iii"],a:2,e:"保費抵銷是假設所有預期的現金紅利\n存放於保險人那裏，當付了指定年期的保費後，這\n些紅利加上所生利息將足以抵銷一切未來的保費開\n支，讓保單持有人有權選擇停止繳付保費，選項ii\n,iv都不正確"},{c:"5.2.7c",s:"相對投資相連保單，分紅保單的好處是︰",o:["高透明度保險制度","保單價值由精算師監管","較投資相連保單風險低","靈活性"],a:2,e:"相對投資相連保單，分紅保單的好處是保單承受的\n風險較低"},{c:"5.2.7c",s:"以下哪項是分紅保單的好處？",o:["靈活性","高透明度保險制度","平均派發","保單價值由精算師監管"],a:2,e:"分紅保單的好處是平均派發"},{c:"5.2.7c",s:"《承保長期保險業務（類別 C業務除外）指引》 指引 16所涵蓋的主要範圍如下",o:["產品設計","合適性評估","給客戶提供的意見","以上各項皆是"],a:3,e:"以上各項皆是指引16所涵蓋 的主要範圍"},{c:"5.2.7d",s:"以下哪項是關於保費抵銷的正確描述？",o:["將來的現金紅利存放於保險人那裏","將來的紅利購買減額清繳保險","對未來業績表現有利","將來的紅利回報有利"],a:0,e:"保費抵銷預期將來的現金紅利存放於保險人那裏，\n保單持有人有權選擇停止繳付保費，但須注意是，\n未來利率水平可以下降的，到時客戶須要恢復掏錢\n付保費，否則可能導致保單失效，只有答案A正確\n。"},{c:"5.2.8",s:"《承保長期保險業務（類別 C業務除外）指引》 指引 16適用於",o:["銷售有利潤保單的獲授權保險人","銷售非保證保單的獲授權保險人","銷售儲蓄壽險的獲授權保險人","承保長期保險業務（類別C業務除外）的獲授權保險人"],a:3,e:"《承保長期保險業務（類別C業務除外）指引》指\n引16適用於承保長期保險業務（類別C業務除外）\n的獲授權保險人"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》根據以下哪項/些機構頒布的保險核心原則\n而制定？",o:["國際保險監督聯會","特區政府","保險監督聯合會","國際保險業聯會及國際保險監督聯會"],a:0,e:"《承保長期保險業務(類別C業務除外)指引》根據\n國際保險監督聯會頒布的保險核心原則而制定"},{c:"5.2.8",s:"根據《承保長期保險業務(類別C業務除外)指引》,銷售有關萬用壽險的保險人必需予以\n披露",o:["未來的預期派息率","過往派息率","非保證紅利的實現率","保險人所提供的保證息率"],a:1,e:"根據指引16,銷售有關萬用壽險的保險人必需予以\n披露過往派息率"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個\n近期曾發出新保單的產品系列的非保證紅利/英式紅利實現率是怎樣計算的?",o:["某個產品的實現率是指按「實際派發的保證紅利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「實際派發的非保證紅利/英式紅利」除以銷售時「利益說明\n所述數額」的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所承諾數額」\n的總額計算。"],a:1,e:"某個產品的實現率是指按「實際派發的非保證紅利\n/英式紅利」除以銷售時「利益說明所述數額」的\n平均數計算。"},{c:"5.2.8",s:"根據《承保長期保險業務類別C業務除外）指引》(指引16)，當銷售分紅（或有利潤）長\n期保單時，必須告知客戶",o:["過往的投資表現非分紅產品未來表現的指標","過往的紅利派發表現並非分紅產品未來表現的指標","過往的紅利派發表現僅指非分紅產品未來表現的指標","保險人不是承擔任何投資風險"],a:1,e:"根據指引16，當銷售分紅（或有利潤）長期保單時\n，必須告知客戶過往的紅利派發表現並非分紅產品\n未來表現的指標"},{c:"5.2.8",s:"《承保長期保險業務（類別C業務除外）指引》，對以下哪些作出披露規定?",o:["投資相連壽險","儲蓄壽險","新承保長期保險業務類別（類別C業務除外）","分紅保單"],a:3,e:"保險業監管局發布了《承保長期保險業務（類別C\n業務除外）指引》，針對分紅保單要求相關保險人\n及其董事會和獲委任精算師遵守若干規定"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個\n近期曾發出新保單的產品實現率是怎樣計算的?",o:["實現率是指按「實際派發的保證英式紅利」除以銷售時「利益說明所承諾數額」的平\n均數計算","實現率是指按「實際派發英式紅利」除以銷售時「利益說明所述數額」的平均數計算\n。","實現率是指按「實際派發的非保證英式紅利」除以銷售時「利益說明所述數額」的平\n均數計算","實現率是指按「實際派發的英式紅利」除以銷售時「利益說明所承諾數額」的平均數\n計算"],a:2,e:"某個產品的實現率是指按「實際派發的非保證紅利\n／英式紅利」除以銷售時「利益說明所述數額」的\n平均數計算"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》由哪個機構制訂?",o:["香港保險業聯會","國際保險業聯會","保險監督聯會","保險業監管局"],a:3,e:"《承保長期保險業務(類別C業務除外)指引》由保\n險業監管局制訂"},{c:"5.2.9",s:"黃先生現年五十五歲，計劃六十歲退休，他請你提供壽險和投資上的意見，你覺得投資\n相連長期保險適合他嗎？",o:["需要視乎他的目標及適合情況，這是他可以選擇的選項","投資風險對他來說屬於相當高，故不建議投資相連長期保險給他","以他的年齡來說，傳統壽險會較適合","不建議投資相連保險，因為它是靈活性不適合一位五十五歲的人士"],a:0,e:"持牌保險中介人就任何合適的人壽保險保單作出建\n議前，須確保對各客戶的情況，包括需要、財務狀\n況、支付保費的能力及意願等作適當評估，及所作\n出的建議是建基於該評估，答案A正確"},{c:"5.2.9",s:"以下哪個組織制訂了《財務需要分析指引》（指引30）,讓適用於所有經營長期保險業務\n或就長期保險業務提供意見的獲授權保險人遵從?",o:["壽險總會","保險代理登記委員會","香港專業保險經紀協會","保險業監管局"],a:3,e:"保險業監管局制訂了《財務需要分析指引》（指引\n30）,讓適用於所有經營長期保險業務或就長期保\n險業務提供意見的獲授權保險人遵從"},{c:"5.3",s:"人壽保險核保工作的重要性，遠高於一般保險風險的核保工作，主要原因是",o:["人壽保險涉及的風險的金額較高","人壽保險合約不可由保險人取消","人壽保險所面對的是生死存亡的重大問題","人壽保險的核保工作要求詳盡的醫學知識"],a:1,e:"的可保性。由於人壽保險涉及保險人不能取消的長\n期合約，通常人壽保險對個別風險的核保只能進行\n一次。所以，第一次就對風險進行正確的評核是非\n常重要的。"},{c:"5.3",s:"以下哪項的描述是正確的?",o:["人壽保險對個別風險的核保工作於每個保週年重新進行","核保工作只影響保費","人壽保險核保可以確定可保性及條款","以上全部皆正確"],a:2,e:"人壽保險核保可以確定可保性及條款，而且只有一\n次核保機會，除了影響保費，也會影響保險人承保\n決定，只有答案C是正確"},{c:"5.3",s:"風險評估、選擇、評級以及按需要附加限制條款。決定所需的再保險程度並針對個別保\n險情況,而作出適當的再保險安排,屬於哪個部門的活動?",o:["理賠部","核保部","保單條款制定部","精算部"],a:1,e:"核保部是對風險作出!評估、選擇、評級以及按需\n要附加限制條款的部門"},{c:"5.3",s:"以下哪項或哪些解釋是「核保」的合理(即使不是最完美的)定義?",o:["確定投保風險的可保性","為提供保險所進行的風險評估","決定所投買保險應採用的條款","以上各項皆是"],a:3,e:"以上各項皆是「核保」的合理定義"},{c:"5.3",s:"以下哪項或哪些說明是正確?",o:["壽險的核保工作是每個保單年度必須的工作","壽險的核保工作只涉及有關保費","核保涉及可保性和合約條款的修改","以上各項皆是"],a:2,e:"核保涉及可保性和合約條款的修改，通常人壽保險\n對個別風險的核保只能進行一次，只有答案C正確"},{c:"5.3",s:"為何在人壽保險保單中，正確地評核風險是非常重要呢？",o:["因為人壽保險保單的保額一般較高","因為人壽保險保單的風險核保只能進行一次","因為人壽保險保單的賠償一定會發生","因為受保人在保單更改前已死"],a:1,e:"通常人壽保險對個別風險的核保只能進行一次。所\n以，第一次就對風險進行正確的評核是非常重要的\n。"},{c:"5.3",s:"為了決定採用甚麼保險條款而進行的風險評估稱為",o:["理賠","核保","承保","投保"],a:1,e:"為了決定採用甚麼保險條款而進行的風險評估稱為\n核保部"},{c:"5.3",s:"保險公司對於特定風險，核保人不僅需留意該風險所代表的道德及實質危險，還需注意\n保險金額及有關個人對保險人有否任何累積影響，其中後者可被描述為",o:["財務性核保","額外危險核保","非技術性核保","外來因素核保"],a:0,e:"財務性核保預期保單所有人繳付保費責任的能力，\n及考慮就同一受保生命已累積購買的保額，是否超\n出與投保人 的年齡的通常水平"},{c:"5.3.1",s:"以下哪項或哪些解釋是「核保」的合理(即使不是最完美的)定義？",o:["確定投保風險的可保性","為提供保險所進行的風險評估","決定所投買保險應採用的條款","以上各項皆是"],a:3,e:"以上各項皆是釋「核保」的合理定義"},{c:"5.3.1",s:"核保的過程主要針對風險的評估，包括哪個或哪些風險程度？",o:["只有實際危險","只有道德危險","實質危險及道德危險","既非實際危險亦非道德危險"],a:2,e:"人壽保險核保人憑經驗可以確定投保的風險程度，\n包括確定實質危險及道德危險"},{c:"5.3.1",s:"與技術性核保相比，財務性核保較為著重保險的金額，尤其關於下列哪項或哪些?",o:["預期受保保單所有人繳付保費的能力","審慎保險人需安排再保險的可能性","就一個人已累積購買的保單計劃","以上各項均需考慮"],a:3,e:"以上各項都是財務性核保均需考慮的因素"},{c:"5.3.1",s:"核保的兩大主要階段，是確定風險程度，以及",o:["將建議風險分類","提供合適計劃","安排足夠再保險","建議次標準措施"],a:0,e:"核保的兩大主要階段，是確定風險程度，以及將建\n議風險分類"},{c:"5.3.1",s:"核保時需要考慮兩個部份，包括確定風險程度及",o:["將建議風險分類","適用的其他保險計劃","安排購買再保險","確定具有多少可保權益"],a:0,e:"核保時需要考慮兩個部份，包括確定風險程度及將\n建議風險分類"},{c:"5.3.1(a)",s:"以下哪項屬於人壽保險的核保考慮因素？原因何在？",o:["身體明顯過重是核保考慮因素，因可能與其他疾病有聯繫","在卡拉OK，酒吧或賭場工作並不屬於核保考慮因素，保險人不會就這些職業而收取\n較高的保費","體重過輕不屬於核保考慮因素，因這並不涉及任何其他疾病","經營香煙業務是核保考慮因素，他們可以平價買香煙"],a:0,e:"身體明顯過重是核保考慮因素，因可能與其他疾病\n有聯繫"},{c:"5.3.1(a)",s:"核保的過程主要針對風險的兩方面，其中一方面是道德危險，另一方面則是",o:["實際危險","實體危險","實質危險","非道德危險"],a:2,e:"核保的過程主要針對風險的兩方面，其中一方面是\n道德危險，另一方面則是實質危險"},{c:"5.3.1(a)",s:"人壽保險根據實質危險及道德危險核保確定有關風險程度，以下哪項因素是正確的描述?",o:["與實質危險相比，道德危險較難確定","實質危險涉及較主觀的因素，環繞準被保人的基本誠信或正直意向，道德危險主要考\n慮到可能增加受保事件發生率的","實質危險主要考慮誠信因素，道德危險主要考慮家族遺傳因素","實質危險主要考慮正直意向因素，道德危險主要考慮高危職業或消閒活動因素"],a:0,e:"道德危險涉及一些較主觀的因素，實質危險考慮死\n亡發生率的客觀因素。與實質危險相比，道德危險\n較難確定"},{c:"5.3.1(a)",s:"下列哪些或哪項可被視為影響一項風險的實質危險因素?",o:["明顯超重","中量吸煙者","飲酒者","以下各項皆是"],a:3,e:"以下各項皆是影響一項風險的實質危險因素"},{c:"5.3.1(a)",s:"有一類人壽保險核保的元素，與風險的主觀因素較為有關(尤其是準受保保單所有人的個\n人素質及態度)，這類元素稱為",o:["道德危險","實質危險","行為分析","人性因素評估"],a:0,e:"與風險的主觀因素較為有關(尤其是準受保保單所\n有人的個人素質及態度)，這類元素稱為道德危險"},{c:"5.3.1(a)",s:"下列哪項陳述是不正確的？",o:["核保過程評估實質及道德兩方面的危險","在一般情況下，道德危險的評估較實質危險的容易","在一般情況下，實質危險的評估較道德危險的容易","人壽保險的核保工作並不單與實質危險有關"],a:1,e:"實質危險主要考慮到可能增加受保事件死亡發生率\n的客觀因素。道德危險涉及一些較主觀的因素，環\n繞準被保險人的基本誠信或正直意向。與實質危險\n相比，道德危險更難以確定。答案B不正確"},{c:"5.3.1(a)",s:"以下哪項屬於或不屬於人壽保險的核保考慮因素?為什麼這樣說?",o:["體重過輕不屬於核保考慮因素，這並不涉及任何其他疾病","在卡拉OK，酒吧或賭場工作並不屬於核保考慮因素，保險人不會就這些職業收取較高\n的保費","體重過高是核保考慮因素，因可能與其他疾病有聯繫","經營香煙商務是核保考慮因素，這是定價因素"],a:2,e:"實質危險主要考慮到可能增加受保事件死亡發生率\n的客觀因素。體重過高是核保考慮因素，因可能與\n其他疾病有聯繫"},{c:"5.3.1(a)",s:"下列哪些或哪項可被視為影響一項風險的實質危險而非其道德危險的因素?",o:["吸煙","明顯超重","有關心臟問題的家族病歷","以上所有各項"],a:3,e:"實質危險主要考慮到可能增加受保事件死亡發生率\n的客觀因素。體重過高是核保考慮因素，因可能與\n其他疾病有聯繫"},{c:"5.3.1(b)",s:"以下哪幾種是人壽保險的風險類型︰\ni) 標準風險\nii) 次標準風險\niii) 拒保風險\niv) 優質風險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"優質風險不是人壽保險的風險類型，只有選項i,\nii, iii正確"},{c:"5.3.1(b)",s:"人壽保險傾向將建議風險分門別類，以便能夠確定公平的保費。以下哪項不屬將建議風\n險的類別?",o:["標準風險","次標準風險","優良風險","以上各項皆不是"],a:3,e:"以上各項皆是制定公平的保費，將建議風險的類別"},{c:"5.3.1(b)",s:"為確定公平的保費，保險人一般會將建議風險分為哪些類別？\ni. 違約風險\nii. 標準風險\niii. 次標準風險\niv. 優良風險",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:2,e:"違約風險不屬確定公平的保費的風險分類，選項i\n不正確"},{c:"5.3.1(b)",s:"保險人在核保時對某特定的風險，由於投保人的健康或其他因素使這些投保不可能被接\n受，此類核保稱為",o:["不承保風險","拒保風險","不可保風險","不接受風險"],a:1,e:"拒保風險是保險人不可能被接受"},{c:"5.3.1(b)",s:"大多數保險人愛將風險進行分類，目的是為訂立公平保費，以下那項不是風險類別？",o:["標準風險(沒有異常風險，收費標準)","次標準風險（風險較大，增加保費）","拒保風險（由於健康或其它因素使投保不可能被接受）","最高級風險（索償機會不大，保費極低）"],a:3,e:"最高級風險不是訂立公平保費的風險類別"},{c:"5.3.1(b)",s:"為確定公平的保費，保險人一般會將建議風險分為哪些類別？\ni) 標準風險\nii) 次標準風險\niii) 拒保風險\niv) 優良風險",o:["i, ii 及 iii","i, ii 及 iv","ii, iii 及 iv","以上各項都是"],a:3,e:"以上各項都是為確定公平的保費，保險人將建議風\n險分成的類別"},{c:"5.3.1",s:"核保包括兩類型。其一是技術性核保，這是將個別風險的潛在危機及預期危險進行評估\n。另一類是計算就同一受保生命已累積購買的保單金額及對建議的保險金額作出評估，\n此類核保稱為",o:["標準核保","實際風險核保","財務性核保","全面性核保"],a:2,e:"計算就同一受保生命已累積購買的保單金額及對建\n議的保險金額作出評估，此類核保稱為財務性核保"},{c:"5.3.1",s:"以下哪項屬於財務性的核保，而非技術性的核保",o:["身體健康狀況","受保生命的行為","保額明顯過高","以上各項皆是"],a:2,e:"計算就同一受保生命已累積購買的保單金額及對建\n議的保險金額作出評估，此類核保稱為財務性核保\n，答案C正確"},{c:"5.3.1",s:"有時候合資格醫務人員所有的資料要進一步調查，保險公司除了向主診醫生索取醫療資\n料外，還可以向哪位索取",o:["護理醫生","體檢醫生","保險公司指明醫生","非主診醫生"],a:1,e:"有時候合資格醫務人員所提供的進一步資料是有必\n要的。這類調查的來源可以是主診醫生或體檢醫生"},{c:"5.3.2",s:"以下哪項或哪些原因需要主診醫生的醫療報告?",o:["所要求的保額十分高","已超過某指明的年齡","就投保書上所披露的某些健康資料作進一步調查","以上各項皆是"],a:3,e:"以上各項皆是需要主診醫生的醫療報告"},{c:"5.3.2",s:"根據壽險核保的術語，「主診醫生」及「體檢醫生」兩項名稱均為經常採用的。以下哪\n項有關陳述是正確的？",o:["兩項名稱的意義完全相同","體檢醫生是指個人本身的醫生","主診醫生是指保險人委派的醫生","它們分別指個人醫生及保險人委任的醫生"],a:3,e:"「主診醫生」及「體檢醫生」它們分別指個人醫生\n及保險人委任的醫生"},{c:"5.3.2",s:"就人壽保險概念而言，保險人通常會透過那一類醫生索取有關醫療資料作核保及理賠時\n之應用：\ni) 主診醫生\nii) 體檢醫生\niii) 經法庭法官委任的醫務官\niv) 享有豐富醫學經驗之病理報告",o:["i, ii","i, iv","iii, iv","以上各項皆是"],a:0,e:"有時候合資格醫務人員所提供的進一步資料是有必\n要的。這類調查的來源可以是主診醫生及體檢醫生"},{c:"5.3.2",s:"通常或曾經對投保人提供醫療護理的醫生或其他合格醫務人員被稱為",o:["護理醫生","主診醫生","體檢醫生","機密醫生"],a:1,e:"主診醫生是通常或曾經對投保人提供醫療護理的醫\n生或其他合格醫務人員"},{c:"5.3.2",s:"保險人最常要求的醫療報告APS的全寫為",o:["輔助的醫療報告(Ancillary Physical Statement)","實質醫療的聲明(Acutal Physical Statement)","附加的醫療聲明(Additional Physical Statement)","主診醫生報告(Attending Physician's Statement)"],a:3,e:"APS的全寫為主診醫生報告"},{c:"5.3.2",s:"許多人壽保險是在免體檢的基礎上安排的。但保險人亦可以要求投保人作合理的身體檢\n查。而且投保人在進行身體檢查時有權知道",o:["進行什麼檢查","檢查資料的目的","任何檢查的結果","以上各項皆是"],a:3,e:"以上各項皆是投保人在進行身體檢查時有權知道的\n資料"},{c:"5.3.2",s:"在人壽保險中，以下哪項或哪些是與醫療報告相關的？",o:["涉及非常敏感的體檢問題","在某些特定的情況下有需要聽取另外的特別意見","人壽保險體檢報告的主要種類稱為主診醫生報告","上所有各項"],a:3,e:"上所有各項都是與醫療報告相關的陳述"},{c:"5.3.2",s:"經過保險人核保後，指一項拒絕有關風險的投保，而不能提供任何類型保障這種做法一\n般被稱為",o:["業務拒絶","拒保","取消","不可接受"],a:1,e:"經過保險人核保後，指一項拒絕有關風險的投保，\n而不能提供任何類型保障這種做法一般被稱為拒保"},{c:"5.3.2b",s:"保險人最常要求的醫療報告 APS 的全寫為",o:["輔助的醫療報告 (Ancillary Physical Statement)","實質醫療的聲明 (Acutal Physical Statement)","附加的醫療聲明 (Additional Physical Statement)","主診醫生報告 (Attending Physician's Statement)"],a:3,e:"主診醫生報告的英文名稱是 (Attending\nPhysician's Statement)簡稱APS"},{c:"5.3.3",s:"在處理一項次標準人壽的投保時，下列哪些屬於保險人的可能採取的核保措施?\ni) 拒絕提供保險\nii) 增加 (附加) 保費\niii) 提供其他保單計劃\niv) 在保單上設置一項按年遞減的「負債」",o:["i, ii","ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上各項皆是保險人的可能採取的核保措施"},{c:"5.3.3",s:"以下哪項或哪些是核保人評估一項次標準人壽投保時的可能選擇？",o:["拒保該項風險","要求額外保費","投資另一保險計劃","以上各項皆是"],a:3,e:"以上各項皆是核保人評估一項次標準人壽投保時的\n可能選擇"},{c:"5.3.3",s:"如果證實個別投保人的風險低於標準(Sub-standard)核保人可以",o:["選擇一些回應的核保措施","必須以正常保費率接受","拒絶提供任何保障情況下","延遲決定於一年後"],a:0,e:"證實個別投保人的風險低於標準(Sub-\nstandard)核保人可以選擇一些回應的核保措施"},{c:"5.4",s:"人壽保險保單的準備及交付十分重要，因為",o:["只適用於替配偶購買保單","以防競爭者將來有一套較有效律的制度","避免將來的麻煩","保單的更改需要保單所有人的同意，否則不可更改或取消"],a:3,e:"人壽保險保單的準備及交付十分重要，因為保單的\n更改需要保單所有人的同意，否則不可更改或取消"},{c:"5.4.1",s:"下列哪項人壽保險保單的簽發及交付的陳述是不正確的?",o:["保險人有良好的系統處理客戶紀錄","保險人能夠以極快的速度及極高的準確度製造保單文件","保單大多數都是根據有關類別和計劃以標準形式印製的","人壽保險核保人需查證是否已經收到首期保費"],a:3,e:"伙保險機構的內部系統應該建立客戶記錄，並查證\n是否已經收到首期保費。]答案D不正確"},{c:"5.4.1",s:"保險人在安排團體保險合約時，除了總保單外，還會為每名成員印製",o:["總保單複印本","保險憑證也許還有成員登記卡","總保單若干部分的複印本","核實成員身份的掛號信件"],a:1,e:"保險人在安排團體保險合約時，除了總保單外，還\n會為每名成員印製保險憑證也許還有成員登記卡"},{c:"5.4.1(a)",s:"保險人會提供保險憑證/登記卡予下列哪種產品的受保人呢？",o:["團體保單保險","儲蓄壽險","個人壽險","以上各項都是"],a:0,e:"保險人會提供保險憑證/登記卡予團體保單保險單"},{c:"5.4.1(b)",s:"以下哪項保險種類會提供「保險憑證」及「成員登記卡」？",o:["終身保險","儲蓄保險","團體保險","以上皆不是"],a:2,e:"團體保單文件涉及總保單，\n為每位受保人提供保險憑證 ，還有成員登記卡。"},{c:"5.4.1(b)",s:"發出團體保單文件時，保險公司通常會印製下列哪份或哪些文件給受保人?",o:["準備多份總團體保單的複印本","每名受保人的成員登記卡","準備多份保單的複印本","以上所有各項"],a:1,e:"發出團體保單文件時，保險公司通常會印製每名受\n保人的成員登記卡給受保人"},{c:"5.5",s:"下列哪項屬於保單所有人服務部的職能？",o:["索償處理","權益管理","市場推廣","以上各項皆是"],a:1,e:"只有權益管理屬於保單所有人服務部的職能"},{c:"5.5",s:"保單持有人服務(或英文縮寫‘POS’)，是下列哪一個部門的另一名稱",o:["對我們的服務為傲","保單所有人服務","優先辦公室服務","個人運作服務"],a:1,e:"保單持有人服務(或英文縮寫‘POS’)，是下列哪\n一個部門的另一名稱保單所有人服務"},{c:"5.5",s:"以下哪項為售後服務部的業務範圍?",o:["文件管理","通訊","權益管理","以上各項皆是"],a:3,e:"以上各項皆是售後服務部的業務範圍"},{c:"5.5",s:"以下哪項服務或程序，不大可能屬於保險所有人服務部(POS)的職能",o:["索償處理","文件整理，如複印保單","調整保單","聯絡顧客與溝通等工作"],a:0,e:"索償處理不大可能屬於保險所有人服務部(POS)的\n職能"},{c:"5.5",s:"保單所有人服務(或英文縮寫‘POS’)，是下列哪一個部門的另一名稱",o:["售後服務部","保單簽發部","保單交付部","行政及人事部"],a:0,e:"保單所有人服務(或英文縮寫‘POS’)，是售後服\n務部的另一名稱"},{c:"5.5",s:"售後服務是一個重要因素。它是由顧客服務部或下列哪個部門負責",o:["POS (Policyowner Service) 保單所有人服務","ASS (after-Sales Service) 售後服務","BCS (better customer Service) 更好客戶服務","ICO (Improve customer Service) 改善客戶服務"],a:0,e:"保單所有人服務售後服務是一個重要部門"},{c:"5.5.1",s:"一份壽險保單最常見的保單更改事宜包括",o:["保險保障種類","地址","保額","以上各項皆是"],a:3,e:"以上各項皆是壽險保單最常見的保單更改事宜"},{c:"5.5.1",s:"以下哪項是一份壽險保單最常見的保單更改事項?",o:["保險保障類型","保額","受益人","以上各項皆是"],a:3,e:"以上各項皆是壽險保單最常見的保單更改事項"},{c:"5.5.1",s:"在人壽保險合約中，以下哪項是不大可能是常見的更改",o:["保單保障的類型","受保生命的身份","受益人","以上沒有一項不大可能是常見更改"],a:1,e:"在人壽保險合約中，受保生命的身份不大可能是常\n見的更改"},{c:"5.5.1",s:"下列哪項或哪些關於更改壽險保單的陳述是正確的",o:["更改一般由保單所有人服務部職員處理","一些更改非常重要﹝如：受益人的更改﹞","有些要求的更改可能涉及核保考慮","上述所有各項"],a:3,e:"上述所有各項都是關於更改壽險保單的正確陳述"},{c:"5.5.1",s:"保單的更改事宜須小心處理，因為",o:["可能需要再保險","可能有重大的法律後果","可能涉及洗黑錢","以上各項皆有可能"],a:3,e:"保單的更改事宜須小心處理，因為以上各項皆有可\n能"},{c:"5.5.1",s:"一份壽險保單最常見的保單更改事宜包括",o:["更改地址","更改受益人","更改保單所有人","以上所有各項"],a:3,e:"以上所有各項都是一份壽險保單最常見的保單更改\n事宜"},{c:"5.5.1",s:"對於壽險保單來說，有多個協定的更改可於保單簽發後出現（透過雙方同意）。然而下\n列哪項較不可能屬於這類更改？",o:["更改受益人","更改有關受保生命","更改保單所有人地址","更改保單擁有權"],a:1,e:"對於壽險保單來說，更改有關受保生命較不可能更\n改"},{c:"5.5.1",s:"下列哪項功能較不可能直接涉及理賠部？",o:["就一份投保單進行核保的工作","日常理賠的行政和處理工作以及有關的查詢","核証近因的調查工作","審閱已去世受保保單所有人的驗屍報告"],a:0,e:"就一份投保單進行核保的工作較不可能直接涉及理\n賠部職責"},{c:"5.6",s:"下列哪項索償只會在儲蓄壽險中出現？",o:["期滿索償","死亡索償","退保索償","以上所有各項"],a:0,e:"期滿索償只會在儲蓄壽險中出現"},{c:"5.6.1",s:"對於儲蓄壽險保單的期滿索償，若保單到期日即將迫近，保險公司會﹕\ni) 通知保單所有人將利益付給受益人\nii) 提醒保單期滿的日期；\niii) 說明應付金額及列出支付保險金的條件；\niv) 附上適當形式的解除責任憑證 (release)",o:["i, ii, iii","i, iii","ii, iii, iv","i, ii, iii, iv"],a:2,e:"儲蓄壽險保單的期滿索償保險人須給保單所有人發\n信提醒他期滿的日期，而不是發信給受益人"},{c:"5.6.1",s:"對於大部份壽險保單而言，若保單到期日即將迫近，保險公司會﹕\ni) 提醒保單期滿的日期\nii) 說明應付金額\niii) 通知保單所有人將利益付給受益人\niv) 附上適當形式的解除責任憑證 (release)",o:["i, ii","ii, iii","i, ii, iv","ii, iii, iv"],a:2,e:"儲蓄保險期滿索償，益付給保單所有人，而不是受\n益人，選項iii不正確，正確答案是C。"},{c:"5.6.1",s:"期滿索償出現於下列哪類或哪些保險中？",o:["定期壽險","終身壽險","儲蓄壽險","以上所有各項"],a:2,e:"期滿索償出現於儲蓄壽險"},{c:"5.6.1",s:"以下哪項有關期滿索償的陳述是不正確的？",o:["確認索償人的指定權利","取得死亡証的副本","書面通知保單即將期滿","以上所有"],a:1,e:"取得死亡証的副本不是期滿索償須提供的文件"},{c:"5.6.1",s:"處理索償時，保險人會從保險金中扣除甚麼項目？",o:["保單抵押貸款","未繳清的保費","尚欠的利息","以上各項都是"],a:3,e:"以上各項都是處理索償時，保險人會從保險金中扣\n除的項目"},{c:"5.6.1",s:"對於大部份壽險保單而言，若保單到期日即將迫近，保險公司會﹕\ni) 通知客人到期日將到\nii) 通知客人到期日大約可領取的金額\niii) 通知客人到期滿後所須安排的手續及文件\niv) 附上適當形式的解除責任憑證 (release)",o:["i, ii, iii","i, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"對於大部份壽險保單而言，若保單到期日即將迫近\n，以上各項皆是保險公司會採取的行動"},{c:"5.6.2",s:"就死亡索償提出時，死亡證明方式為",o:["死亡證明書正本","死亡證明書副本","受益人簽署證明","以上任何一項"],a:0,e:"就死亡索償提出時，死亡證明方式為死亡證明書正\n本"},{c:"5.6.2",s:"在死亡索償中，因為下列哪項或哪些原因，死因可能屬於重要事項?",o:["該保單可能設有意外死亡保險利益附約","自殺條款可能仍然生效","受益人可能謀殺該受保生命","以上所有各項"],a:3,e:"以上所有各項都是在死亡索償中，死亡原因可能變\n得重要的事項"},{c:"5.6.2",s:"以下哪項是一項法律原則容許法庭對有損害公眾利益或公共秩序的傾向的行為或交易，\n可予以廢除或不接受?",o:["程序不當","政策公正","公共政策","以上各項皆不是"],a:2,e:"在大部分情況下，如果證實殺人犯是受益人的話，\n法律 「公共政策」是不會容許殺人犯本人獲益的"},{c:"5.6.2",s:"死亡日期對下列哪項保險計劃有重要的影響？",o:["遞減定期壽險","分紅壽險","快將到期的定期壽險","以上各項都是"],a:3,e:"死亡日期對所有人壽保險計劃都是重要的"},{c:"5.6.2",s:"某人生前為自己購買了一份人壽保險，受保人出現死亡索償，而受益人為其配偶，保險\n人賠付時會出現問題為",o:["被保險人是在夜總會打鬥中意外被刺身亡","被保險人是在銀行持械案中受害人","被保險人的妻子蓄意謀殺他，目的為保險利益","由於家人拒絕支付贖金，被保險人被綁匪撕票"],a:2,e:"如果證實殺人犯是 受益人 的話，法律\n「公共政策」是不會容許殺人犯本人獲益的。"},{c:"5.6.2",s:"就受保生命的死亡原因，可能會引起保險人的關注，除了一般查詢外，以下那種情況會\n軀使保險人作進一步調查？\ni) 受保人自殺身亡\nii) 受保人年屆80歲自然死亡\niii) 受保人可能被妻子(指名受益人)謀殺\niv) 保單生效後不久受保人便告死亡",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:2,e:"受保人年屆80歲自然死亡通常都不會軀使保險人作\n進一步調查"},{c:"5.6.2(d)",s:"某人壽保險單訂明由陳大民作為受託人，假如被保險人逝世後保險金將全數支付給他，\n最終被保人被陳大民所殺害，請問陳大民可獲得保險金賠償嗎?",o:["會，保險條款中訂明受託人可得到賠償","不會，基本法不容許殺人犯本人獲益","不會，香港法律不容許殺人犯成為受益人","以上各項皆不是"],a:3,e:"在大部分情況下，如果證實殺人犯是 受益人\n的話，法律「公共政策」是不會容許殺人犯本人獲\n益的。以上各項皆不正確"},{c:"5.6.2(d)",s:"近因指某一索償個案中造成損失的主要有效原因。以下哪項索償不會受近因所影響？",o:["一份壽險保單生效五年後，被保人自殺","一份受雙倍賠償利益約束的保單","死因有可或保單生效不足（兩個月）便自殺的索償","一份壽險包含有意外死亡及喪失肢體附加保障利益"],a:0,e:"自殺只會於自殺免責期(一般為保單生效一年內)構\n成除外責任"},{c:"5.6.2(d)",s:"某人壽保險單訂明由陳大民作為受託人，假如被保險人逝世後保險金將全數支付給他，\n最終被保人被陳大民所殺害，請問陳大民可獲得保險金賠償嗎?",o:["殺人犯會喪失對所有人的權利，故此不能提出申索","保險業條例某項條文訂明殺人犯不能提出申索","人壽保險賠償只會賠付予受益人，並非受託人，故此不能提出申索","以上各項皆不正確"],a:3,e:"在大部分情況下，如果證實殺人犯是受益人的話，\n法律 「公共政策」是不會容許殺人犯本人獲益的"},{c:"5.6.2(d)",s:"就死亡索償而言，就下列哪項受保生命的死亡情況，可能會引起保險人的特別關注，或\n在例行詢問時需要進一步調查?\ni. 受保生命遭鎗擊死亡\nii. 受保生命於保單簽發後不久便死亡\niii. 受保生命80歲的自然死亡\niv. 受保生命可能遭妻子(指名受益人)謀殺",o:["i, ii, iii","ii, iii, iv","i,ii,iv","i,ii,iii,iv"],a:2,e:"受保生命80歲的自然死亡對死亡索償而言普遍都不\n需要進一步調查。"},{c:"5.6.2(d)",s:"某人壽保險單訂明由陳大民作為受託人，假如被保險人逝世後保險金將全數支付給他，\n最終被保人被陳大民所殺害，請問陳大民可獲得保險金賠償嗎?",o:["會，保險條款中訂明受託人可得到賠償","不會，人壽保險保險金祗會賠付予受益人，並不是受託人","不會，跟據公律(公共政策)是不容許殺人本人獲益","不會，賠償金將被充公"],a:2,e:"如果證實殺人犯是受益人的話，根據法律的公共政\n策，是不會容許殺人犯本人獲益"},{c:"5.6.2(d)(i)",s:"如果證實殺人犯是受益人的話，以下哪項法律是不會容許殺人犯本人獲益？",o:["合約法","公共政策","衡平法","人權法"],a:1,e:"如果證實殺人犯是受益人的話，根據法律的公共政\n策，是不會容許殺人犯本人獲益"},{c:"5.6.2(d)(iv)",s:"如果一名客戶暗示，他正在考慮將本身的保單退保，保險中介人應採取以下哪項或哪些\n行動？",o:["有禮地詢問為何作出這個決定","小心地解釋保單退保的權利或影響","略述各種其他的可能選擇(如保單抵押貸款，清繳保障等)","以上各項皆是"],a:3,e:"以上各項皆是保險中介人處理保單退保時應採取的\n行動"},{c:"5.6.3",s:"下列哪項或哪些正確描述「保單退保」的索償處理應該注意的地方?",o:["計算未繳清的保費、貸款及利息","所有權證明","對承讓人或受益人的利益","以上各項皆是"],a:3,e:"以上各項皆是「保單退保」的索償處理應該注意的\n地方"},{c:"5.6.3",s:"以下哪一項不大可能屬於退保索償時考慮之因素?",o:["所有權證明","死亡證","照顧任何受益人的權益","調整未清繳的保費"],a:1,e:"死亡證屬死亡索償需考慮之因素"},{c:"5.6.3",s:"以下哪三項對於退保索償來說是最重要的？\ni) 所有權證明\nii) 死亡證明書的正本\niii)合適的解除責任憑證及給付證明文件\niv)就任何尚未繳清的保費、保單抵押貸款及利息作出調整",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:3,e:"死亡證明書的正本不屬退保索償來說是最重要的文\n件"},{c:"5.6.3",s:"處理退保索償時最重要是證明索償人具有收取退保現金價值的法定權利，這證明的通過\n通常被稱為",o:["遺囑認證","所有權證明","退保證明","授予所有權的憑證"],a:1,e:"處理退保索償時最重要是證明索償人具有收取退保\n現金價值的法定權利，這證明的通過通常被稱為所\n有權證明"},{c:"5.6.3",s:"下列哪項或哪些正確描述「保單退保」的索償處理應該注意的地方?",o:["計算未繳清的保費、貸款及利息","所有權證明","對承讓人或受益人的利益","以上各項皆是"],a:3,e:"以上皆是「保單退保」的索償處理應該注意的地方"}],"paper3-2025-10":[{c:"1.2.2(b)",s:"就最高誠信原則，在免體檢的投保的前題下，以下哪項不屬違反最高誠信的情況?",o:["沒有披露未被驗出的腦瘤","沒有披露近日收到高利貸債主的死亡恐嚇","隱瞞自己從驗身得知的癌症","隱瞞自己意外導致嚴重受傷"],a:0,e:"有些疾病對合資格醫生而言可能很容\n易察覺，但是不能期望一般人也能夠\n進行自我診斷並作披露。"},{c:"1.3.2b(a)",s:"人壽保險費率的均衡保費制度是指在保險期內，每年所繳的保費相同， 並假設",o:["利率沒有大幅度下降","死亡保險金維持不變","經濟環境保持合理平穩","保險人的賠償經驗仍可接受的"],a:1,e:"人壽保險費率的均衡保費制度是指在\n保險期內，保費不變，同時死亡保險\n金亦維持不變。"},{c:"1.3.1a",s:"以下哪項關於死亡表的描述是正確的?\ni. 顯示不同年齡的預期死亡比率的計算表\nii. 應付所有預期及可能出現的營運開支\niii. 考慮某種新疾病或其他災難引起異常死亡率的可能性\niv. 只應付正常風險和正常預期的死亡率",o:["i, iii","i,iv","ii,iv","以上各項皆是"],a:1,e:"死亡表或稱生命表顯示不同年齡的預\n期死亡比率的計算表，在保險行業中\n十分通用。利用死亡表釐定費率，只\n是應付正常風險和正常預期。所以只\n有選項i及iv是正確"},{c:"1.2.1(h)",s:"在人壽保險中，只有在合約開始時才需要可保權益，以下哪項情況會出現有效索償?",o:["夫妻於離婚前，為其配偶的生命購買人壽保單","債務清還前，就債務人的生命購買人壽保單","關鍵人物人壽保單，受保僱於保單起保數天後離職","以上各項例子"],a:3,e:"人壽保險的可保權益只有在合約開始\n時才需要，就以上的關係轉變，仍然\n維持該保單的有效性"},{c:"1.2.1(h)(iii)",s:"以下哪項有關壽險保單轉讓與可保權益法律規定的關係的陳述是正確？",o:["保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者","保單所有人一般可以將正當地安排的人壽保險合約轉讓給第三者，即使該第三者對受保生命缺乏\n可保權益","保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者","準保單所有人意圖向一受保生命購買一份壽險合約，但卻與受保生命缺乏可保權益，他大可以安\n排後者購買保單自保生命後轉讓給他，而成為轉讓保單的合法所有人"],a:1,e:"保單所有人一般可以將正當地安排的\n人壽保險合約轉讓給第三者，即使該\n第三者對受保生命缺乏可保權益仍可\n作出保單轉讓"},{c:"1.2.2",s:"下列哪項肯定屬於投保人必須披露的重要事實",o:["與實質物件(財產)的保險有關的事實","會影響一名審慎的保險人訂定保費或決定是否承擔風險方面判斷的事實","可能影響一名審慎的核保人就一項特定風險釐定保費的判斷的事實","被保險人向保險人披露的重要事實"],a:1,e:"重要事實是會影響一名審慎的保險人\n訂定保費或決定是否承擔風險方面判\n斷的事實"},{c:"1.1",s:"人壽保險最初及最基本的目的，在現代社會也有這樣的保障保險(定期壽險)是什麼？",o:["死亡(尤其在早逝的情況下)","為受保人在生的每一年提供生活收入","儲蓄","在餘下生命裏提供保障"],a:0,e:"最初，保險單有效期較短，只為暫時\n性的風險情況"},{c:"1.3.1b(a)",s:"英式「有利潤」的壽險保單不獲「紅利」取而代之，它們往往將英式紅利附加於保單應付的保額，\n並於到期時一併支付，這種英式紅利稱為？",o:["延期紅利","未來現金","復歸紅利","非即時紅利"],a:2,e:"英式紅利又稱為復歸紅利"},{c:"1.3.2b&c(ii)",s:"可作為保單抵押貸款的抵押物是",o:["銀行中的存款","保單的現金價值","保單所有人所持有的財產","以上各項都是"],a:1,e:"可作為保單抵押貸款的抵押物是保單\n的現金價值"},{c:"2.1.3",s:"以下哪項或哪些就終身壽險的描述不正確?\ni. 保單不可以是分紅形式\nii. 保單保額按特定周期逐漸減少\niii. 保單可以在保險期內終身繳付保費\niv. 保單利益限於受保生命在特定期間或時期內死亡情況下支付",o:["i,ii","i,ii,iv","i,iii,iv","i,ii,iii,iv"],a:1,e:"只有選項iii是終身壽險正確的描述，\n選項i,ii,iv都不正確"},{c:"2.1.1(b)",s:"定期壽險保險期最短為",o:["1年","10年","20年","30年"],a:0,e:"定期壽險保險期最短為1年"},{c:"2.1.2a",s:"當其他條件相同，最便宜的現有人壽保險種類是",o:["定額定期壽險","遞減定期壽險","儲蓄壽險","儲蓄壽險"],a:1,e:"當其他條件相同，最便宜的現有人壽\n保險種類是遞減定期壽險"},{c:"2.1.1&2.1.2",s:"以下哪一項是定期壽險及儲蓄壽險的主要分別?",o:["儲蓄壽險的保費較定期壽險為低","儲蓄壽險的保險利益申索較定期壽險容易","定期壽險續保需提供可保性證明，儲蓄壽險就沒有這項規定","儲蓄壽險提供期滿時給付保額，而定期壽險則沒有"],a:3,e:"只有儲蓄壽險提供期滿時給付保額，\n而定期壽險則沒有"},{c:"2.1.3",s:"一名有意購買一份人壽的準保單持有人，希望有關保險在自己逝世時提供一筆不超過事前聲明的金\n額，而該筆金錢的用途並不會在投保人逝世前出現，而保險成本並非為重要考慮因素。以下哪保險\n類型可以獲得最高的收益?",o:["定額定期壽險","終身壽險","分紅儲蓄壽險","非分紅儲蓄壽險"],a:1,e:"終身壽險其基本特性是，不管受保生\n命何時去世，保單將會於此時支付保\n額，該種類型可以獲得最高的收益"},{c:"2.1.2(d)",s:"儲蓄壽險並不便宜，以下哪項是正確的描述",o:["索償只會在保單期滿時出現","索償會在保單期滿時或之前出現","索償會在受保人早逝時，或保單期滿時出現","索償不一定出現"],a:2,e:"儲蓄壽險的索償會在受保人早逝時，\n或保單期滿時出現"},{c:"2.2.1",s:"下列哪項不屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","披露因營運開支而徵收的附加保費","在無須可保性證明情況下，調整的保單利益"],a:3,e:"萬用壽險就任何增加保險利益的情況\n都可能須要提供可保性證明"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"年金計劃在累積期內，保單持有人在\n一段時間內定期繳付保費，讓保險人\n通過投資令已付金額增長"},{c:"2.3.1(b)",s:"以下哪一項是香港年金的特色?",o:["最高保證年金總額","最低保證年金總額","最高年金總額","最低年金總額"],a:1,e:"香港年金的其中一項特色是提供最低\n保證年金總額"},{c:"2(a)",s:"下列哪一項較不可能出現於人壽保險合約的基本形式功能範圍？",o:["為特定時間內發生死亡給付死亡金","為指定時期內發生死亡給付死亡金","為特定原因內發生死亡給付死亡金","於某一特定日子或以前發生死亡給付死亡金"],a:2,e:"人壽保險合約不會為特定原因發生的\n死亡給付死亡金"},{c:"2.1.1",s:"以下哪項不屬於儲蓄壽險合約的特點？",o:["保險於指明期限過後便告期滿","保單可以是分紅的或不分紅的","它包含一項重大的儲蓄成份","只會於保單期滿時仍然生存才支付保額"],a:3,e:"受保生命在該期間內死亡，或者保險\n期限期滿後受保生命還活着的話\n，則即時給付保額"},{c:"2.1.1a",s:"如果對於人壽保險有短暫的需求，而所需求的財務金額於有關期內不會增加或減少，該需求亦會該\n段指明期限告終後便告消失，那麼最經濟的壽險保障形式應是",o:["定額定期壽險","遞減定期壽險","分紅儲蓄壽險","不分紅儲蓄壽險"],a:0,e:"定額定期壽險保費比儲蓄壽險低，但\n遞減定期壽險保額會彌時間而減少，\n所以最經濟的壽險保障形式，而且維\n持保不變保額應是定額定期壽險。"},{c:"2.1.1a",s:"當受保人去世時，賠償會直接向貸款人償還貸款餘額，這是什麼類型的保險？",o:["遞增定期壽險","信用壽險","家庭收入壽險","抵押贖回壽險"],a:1,e:"如果借款人在未完全償還欠款之前死\n亡，信用壽險直接向貸款人支付貸款\n結欠"},{c:"2.1.1a(b)",s:"以下哪類壽險，也許是與其他提供一筆過賠償的保單相結合的，而賠償時是按月支付保險利益的？",o:["信用壽險","家庭收入壽險","抵押贖回壽險","儲蓄壽險"],a:1,e:"家庭收入計劃也許會與其他於死亡時\n提供一筆過付款的保單計劃互相結合\n的。承諾在指定期限的剩餘部分內，\n每月向受益人支付指定金額的死亡保\n險金"},{c:"2.1.1a(b)",s:"遞減定期壽險是因為",o:["所繳保費隨時間減少","所需給付保險金額隨時間減少","客戶所需繳付的年期不斷減少","給予保險中介人的佣金每年遞減"],a:1,e:"遞減定期壽險保額會彌時間而減少"},{c:"2.1.1a(c)",s:"哪三項是遞增定期壽險的正確陳述：\ni)有關保費與利益水平一致遞增\nii)有關利益按年或其協定方法遞增\niii)保費的保險金額均保持不變，保險期限遞增\niv)本意是要讓利益與貨幣價格保持一致",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"遞增定期壽險的保費通常按所保利益\n水平的增加的比例增加"},{c:"2.1.2",s:"儲蓄壽險的概念是指純生存保險加上",o:["定期壽險","終生壽險","家居保險","商業保險"],a:0,e:"儲蓄壽險的概念是指純生存保險加上\n定期壽險"},{c:"2.1.3(c)",s:"有一種終身壽險的變化，容許保費按一定的規律(例如每三年增加)，而面值則維持不變，這終身壽\n險是",o:["等級保費保險","等級終身壽險","分級終身壽險","遞增終身壽險"],a:0,e:"終身壽其中一種的變化是等級保費保\n險"},{c:"2.2.2",s:"以下哪項不適用於投資相連保險？",o:["部分或全部保費用於購買基金","普遍地應用於終身壽險或儲蓄壽險","總是在退休時以一整筆款項償還","有關基金包括股票或定期利息投資"],a:2,e:"投資相連保險的保單價值與單位信託\n基金的資産的價值而波動，沒有保證\n的保單價值"},{c:"2.3(a)",s:"週期性地領取年金的人士稱為",o:["收款人","年金購買人","年金持有人","保單所有人"],a:0,e:"週期性地領取年金的人士稱為收款人"},{c:"3.2.2",s:"附加於人壽保單的意外死亡及喪失肢體附約，有時會賠付超出意外死亡保險利益及其他保險利益，\n以下哪項是適用的保障範圍?\n(i) 嚴重燒傷，可獲支付指明金額\n(ii) 每周津貼，最長為52周\n(iii) 住院津貼，每日津貼上限為 1,000日\n(iv) 因乘搭一般公共交通工具引果傷殘可獲「雙倍賠償」",o:["i,ii","ii,iii","ii,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是意外死亡保險利益附約\n所提供的其他保險利益"},{c:"3.2",s:"意外死亡及喪失肢體(AD&D)附約，近因原則對這種附約顯得非常重要，原因是",o:["不適用於危疾保單","只有被保險人因意外死亡才有會給付雙倍賠償利益","每索償賠付，都會是保單基本保單保額的兩倍","就一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付"],a:1,e:"就意外死亡及喪失肢體(AD&D)附約而\n言，只有被保險人因意外死亡才有會\n給付雙倍賠償利益，所以近因原則(死\n亡原因)對這種附約顯得非常重要"},{c:"3.2.1(a)",s:"近因原則的應用在於決定索償的原因。於人壽保單中，這項原則在以下哪項情況下是十分重要?",o:["只適用於分紅性質保單","保單所有人於保單生效5年後，懷疑因自殺而身故","適用有雙倍補償條款的保單","提供人身意外保險利益的保單，保單生效不久或因自殺而身故"],a:3,e:"自殺免責期長通常為保單發出後\n一年，證實受保人在自殺免責期自殺\n屬除外責任"},{c:"3.5.1",s:"以下哪兩項是對保證可保利益的陳述是正確的?\ni. 增額保險的金額不能超過原有保單的面額\nii. 保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明\niii. 保單所有人必須提供持續良好的健康證明\niv. 該項權利於在受保生命達到40歲之後才可行使",o:["i,ii","i iii","ii,iii,iv","iii,iv"],a:0,e:"保證可保利益的保單所有人毋須提供\n持續良好的健康證明，該項權利也可\n能限於在受保生命達到某一年齡，一\n般為40歲之前才可行使。選項iii及iv\n不正確"},{c:"3.1.1(a)",s:"以下哪項或哪些有關「豁免保費」附約的支付利益準則描述是正確的？",o:["受保保單所有人在變成完全傷殘時必須維持達到某段時間然後死亡","受保保單所有人在變成完全傷殘時必須已經有部份殘疾達到某段時間","受保保單所有人必須在保單有效期內完全傷殘且達到某段時間, 稱為 「等候期」","以上所有各項均不屬於豁免保費附約支付利益的準則"],a:2,e:"等候期即是受保保單所有人一旦根據\n保單的定義，完全傷殘達最低期限（\n通常為三個月或六個月），他將獲豁\n免支付續保保費。"},{c:"3.1.1(d)",s:"下列哪三項較可能是豁免保費(WP)附約的除外責任？\ni. 保單生效前既存的狀況\nii. 在從事違法活動時導致的殘疾\niii.因受僱用及其過程導致的殘疾\niv. 戰爭時服兵役導致的殘疾",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"選項iii因受僱用及其過程導致的殘疾\n不屬是豁免保費(WP)附約的除外責任\n，只有i,ii,iv選項正確"},{c:"3.2.1(b)",s:"若意外事故導致受保生命喪失單肢或單目失明，或遭受其他較輕微的指明受傷，給付額為",o:["意外死亡賠償金額的100%","相等於意外死亡保險金的規定比率","扣減自負額後的保險金的規定比率","扣減醫療費用後的保險金的規定比率"],a:1,e:"若意外事故導致受保生命喪失單肢或\n單目失明，或遭受其他較輕微的指明\n受傷，給付額為相等於意外死亡保險\n金的規定比率"},{c:"3.3.1(e)",s:"以下哪些不是危疾保險利益附約設定的保障限制？\ni) 危疾保障生效僅適用於某歲數以下的人\nii) 不適用於次標準風險；\niii) 一般可以長達5年的等候期\niv) 必須累積一定的現金價值",o:["i,ii","i,ii,iii","iii,iv","i,iii"],a:2,e:"危疾保險利益附約等候期是3個月或6\n個月，必須累積現金價值不是危疾保\n險利益附約的限制，選項(iii)及(iv)\n不正確"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認\n可的個人償款住院保險產品，供消費\n者自願選購，團體保險並不適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫\n療服務的消費者提額外的保險計劃選\n擇"},{c:"3.4.2",s:"醫療保險業務指引 (指引 31)",o:["具有法律效力","不具有法律效力","可能具有法律效力","視乎情況才具有法律效力"],a:1,e:"醫療保險業務指引 (指引\n31)是不具有法律效力"},{c:"3.6.1",s:"以下哪項是「生活指數調整利益」附約的正確描述",o:["對抗經濟周期的影響","被保險人身故後提供一筆過的保險利益","紅利派發低於一般水平時，保險人將提供補充紅利","以上都不正確"],a:3,e:"「生活指數調整利益」附約增加的數\n目是跟綜合消費物價指數掛鈎的，只\n會按通漲調整，通縮情況下不會下降\n。"},{c:"3.1.1",s:"以下哪項或哪些是「豁免保費」附約支付利益的準則描述是正確?",o:["受保保單所有人必須死於他生前引致完全傷殘的那項成因","受保保單所有人在保單有效期內變成完全傷殘,而且已持續一段指明時間(稱為等侯期)","當受保保單所有人完全傷殘時,之前最少已經部分傷殘達到某段時間(稱為等侯期)","以上各項均不屬於該附約支付利益的準則"],a:1,e:"受保保單所有人在保單有效期內變成\n完全傷殘,而且已持續一段指明時間(\n稱為等侯期，一般為為3或6個月)"},{c:"3.1.1",s:"以下哪項不是(WP)附約的描述？",o:["(WP)是”waiting period”的縮寫，意指「等候期」","(WP)是”waiver of premium”的縮寫，意指「殘疾豁免保費附約」","被保險保單所有人須要完全傷殘，才可獲權益","受到特定年齡所限制"],a:0,e:"(WP)是Waiver of\nPremium的縮寫，意指「殘疾豁免保費\n附約」，而不是waiting\nperiod”「等候期」的意思"},{c:"3.1.2",s:"如果人壽保單收到殘疾收入附約約束,並且受保生命遭遇殘疾,而現正提供收入",o:["該收入通常以每月形式支付","其基本保障會暫時停止","所支付金額會於死亡保障額中扣除","此類保障通常並不設有等候期"],a:0,e:"殘疾收入等候期由一個月至六個月不\n等，所支付的利益並非貸款或預繳，\n不會於死亡保障額中扣除，殘疾收入\n附約如名稱所示，則在完全殘疾期間\n提供收入"},{c:"3.1.2",s:"根據「殘疾收入附約」所支付的收入保險利益",o:["會從最後的死亡保險金扣除","不會從最後的死亡保險金扣除","會從未來的紅利扣除","實質上是一種利用額外保費償還的貸款"],a:1,e:"「殘疾收入附約」所支付的收入保險\n利益不是預繳或貸款，不會從最後的\n死亡保險金扣除"},{c:"3.1.2(b)",s:"根據殘疾收入附約，收入保險利益通常與該保單的保額掛鈎，並且支付的頻密程度為",o:["每週","每月","在保單年度終結的時候","在殘疾期間結束的時候"],a:1,e:"根據殘疾收入附約，收入保險利益通\n常與該保單的保額掛鈎，並且支付的\n頻密程度為每月"},{c:"3.3",s:"「提前支付死亡保險利益」又稱為",o:["生前支付保險利益","快捷給付保險利益","儲蓄保險","死前給付保險利益"],a:0,e:"「提前支付死亡保險利益」又稱為生\n前支付保險利益"},{c:"3.3.1",s:'危疾保險利益中"指明疾病"指:\ni. 傷殘\nii. 心臟相關疾病\niii.癌症\niv. 重要器官相關疾病',o:["i,ii, iii","ii,iii, iv","i,ii, iv","i,ii,iii ,iv"],a:3,e:'以上都可以是危疾保險利益中"指明疾\n病"'},{c:"3.5.1",s:"以下哪項是一種權利，保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明?",o:["不可異議可保選擇","延期保險選擇","增加保險選擇","保證可保利益"],a:3,e:"保證可保利益即是保單所有人有權在\n指定的備擇日期購買增額保險，無需\n遞交可保證明"},{c:"3.5.1(f)",s:"如保險已加有豁免保費及預批購買選擇附約，而保單所有人在可以行使購買權時發現遭致傷殘，在\n此情況下，下列哪項為正確？",o:["預批購買選擇會被取消","豁免保費附約會被取消","豁免保費及保證可保利益附約會被取消","可自動獲得該額外保障，豁免保費附約也可以豁免所有保費"],a:3,e:"受保保單所有人在有權行使購買增額\n保險選擇權時已經成了殘疾人，他將\n會自動獲得該項額外保障。並豁免保\n費，直至受保保單所有人康復或死亡"},{c:"3.6.1",s:"包含了生活指數調整利益(COLA)的保單條款,為遭致殘疾的受保保單所有人提供周期性增加的殘疾\n收入保險利益,而增加的數目一般相等於",o:["每年增加百分之五","通貨膨脹","綜合消費者物價指數","受保保單所有人薪金調整的幅度"],a:2,e:"生活指數調整利益(COLA)的保單條款,\n為遭致殘疾的受保保單所有人提供周\n期性增加的殘疾收入保險利益,而增加\n的數目一般相等於綜合消費者物價指\n數"},{c:"4.11",s:"支付保單利益有很多種方法，誰人可以選擇收取收益的方法?",o:["受益人","保單所有人","以上兩者其中一人","保險人可以選擇支付方法"],a:2,e:"可以選擇收取保險利益方法的可以是\n受益人及保單所有人"},{c:"4.9",s:"下列哪項屬於壽險保單的轉讓限制？",o:["有關轉讓不能因為非法目的而安排","規定只能以一次過整筆支付保單利益","不得侵犯任何受益人的既得權利","以上各項皆是"],a:3,e:"以上各項皆是轉讓保單的限制"},{c:"4.5",s:"以下哪項不屬於人壽保險的不能作廢條款，保單的持有人可以作出的選擇?",o:["中止保單時獲付退保現金價值","取回已經支付的保費","利用淨現金價值作為整付保費購買減額清繳保險","以上各項皆不是"],a:1,e:"取回已經支付的保費不屬於人壽保險\n的不能作廢條款下的選擇"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保\n單，保單的持有人決定不再繳付任何\n保費有權選取的選擇"},{c:"4.8",s:"就誤報年齡或性別方面，人壽保險單通常",o:["也適用於自願變性的情況","只容許保單利益向上調整","只容許保單利益向下調整","試圖改變保單條款至以符合應有情況"],a:3,e:"若事實與安排保險時所說明的年齡或\n性別不相同，這可能對保費及／或保\n險利益產生顯著影響。"},{c:"4.10",s:"以下哪項屬於分紅保單的紅利選擇?\ni. 用以購買保險公司股份\nii. 以現金方式支付紅利\niii.如果保單所有人沒有作出紅利選擇，保單會採用「自動紅利選擇」 的做法\niv. 分紅保單於生效一段指定時間後可轉換成不分紅保單",o:["iii,iv","i,ii,iii","ii,iii","i,ii,iv"],a:2,e:"如果保單所有人沒有從上述各項中作\n出選擇，大多數保單會採用一種稱為\n「自動紅利選擇」的方式。"},{c:"4.1",s:"以下哪項關於「完整合約」條款的描述是正確的？",o:["在人壽保險索償時毋需出示保單的正本","除非得到保單所有人的同意，否則不能對保險合約作出任何修改","保險公司的指定高級職員有權對保單作出更改","保單的內容已是一份完整的合約，並不包括其他文件"],a:1,e:"「完整合約」條款其中一個定義是，\n除非得到保單所有人的同意，否則不\n能對保險合約作出任何修改"},{c:"4.2",s:"以下有關不可異議條款，哪項陳述是不正確的？",o:["保單生效兩年後即不可異議","保單生效首兩年為可異議期","根據香港法律，即使是有欺詐的情況存在都不可以推翻該條款","該條款規定了一段可異議期"],a:2,e:"無論保單生效多久，存在欺詐的情況\n都可以推翻保單"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已婚者地位條\n例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非張先生就《已婚者地位條例》訂明，被保險人就自身生命購買保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有\n人如為其配偶及或其任何子女的利益\n而購買壽險單，將達到建立一個（法\n定信託的效用，從而令該配偶及或子\n女成為該保單的實益擁有人。"},{c:"4.4(c)",s:"黃生就自身生命購買壽險保單，自己為受保人，並指明他最小的兒子為該保單受益人，根據《已婚\n者地位條例》，此舉起了甚麼的法律效用?",o:["該受益人成為該保單的法定保單所有人","該受益人成為該保單的法定保單所有人，直至黃先生修訂其他受益人為止","信託效用並不用適指定子女成為受益人","該受益人成為該保單的實益擁有人"],a:3,e:"根據《已婚者地位條例》，保單持有\n人如為其配偶及或其任何子女的利益\n而購買壽險單，將達到建立一個（法\n定信託的效用，從而令該配偶及或子\n女成為該保單的實益擁有人。"},{c:"4.7",s:"若要把已失效的人壽保單復效，以下哪項不是復效條件?",o:["繳一筆復效費","保險人書面同意","繳付已到期而未繳清的保費及利息","提供可保性證明"],a:1,e:"保險人書面同意不是人壽保單復效條\n件"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許\n藉訂明手續來轉讓據法權產"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，\n擬轉讓的據法權產須屬現時的，而非\n未來的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許\n藉訂明手續來轉讓據法權產，而對保\n險合約的權益屬於據法權產。"},{c:"4.9",s:"為什麼說一張壽險保單所有人只具有有限的權利轉讓該保單的產權？",o:["轉讓一張保單的權利屬該保單的受益人而非保單所有人所有","如果保單受益人已取得保單的權利，不得侵犯任何受益人既得的權利","轉讓壽險單必須保險人的批准","在典型壽險保單所規定的初段時間內轉讓保單必需保險人的批准"],a:1,e:"轉讓該保單的產權的其中一個限制，\n是不得侵犯任何受益人既得的權利"},{c:"4.9",s:"對於一個保單所有人來說，如果他對產權的權益是復歸的，那",o:["仍未取得該項權益","雖然對產權有獲得認可的權益，財產的享用將延遲至將來的某一天或某事發生時","肯定會在將來取得該權益","該權益屬於受益人權益"],a:1,e:"復歸的權益是指對產權有獲得認可的\n權益，財產的享用將延遲至將來的某\n一天或某事發生時"},{c:"4.5",s:"人壽保單中通常具有一些條文，把保單的現金價值即時用於支付尚未繳交的保費，從而避免保單失\n效，部分保險人不認為這是不能作廢條款，而稱之為?",o:["一筆強制性的保單貸款","一筆自動的保費貸款","一項延續保單條款","一項自動保單復效條款"],a:1,e:"把保單的現金價值即時用於支付尚未\n繳交的保費，部分保險人認為這是不\n能作廢條款，他們視之為一個獨立自\n動保費貸款條款或稱保費自動墊繳條\n款"},{c:"4.6",s:"以下哪項對保單抵押貸款條款的描述是不正確的?",o:["貸款金額上限為現金價值（扣除一年貸款利息）","貸款用途必須經保險人許可","要求使用保單抵押貸款,是在保單上列名的保單所有人的權利","有關利息可在保單利益應付時償還"],a:1,e:"保單抵押貸款條款貸款用途並無限制\n，答案B不正確。"},{c:"4.6",s:"下列哪項或哪些屬於保單抵押貸款中慣用條文的特點?",o:["該筆貸款必須用於繳交未來的保費","該筆貸款唯一需要的抵押品就是保單的定期保險","於保單生效期內可以償還或不償還該筆貸款","保單的貸款由保險人決定"],a:2,e:"保單抵押貸款於保單生效期內可以償\n還或不償還"},{c:"4.7",s:"有意復效保險單必須於規定時間內提出，一般為",o:["1年","2年","3年","5年"],a:3,e:"有意復效保險單必須於規定時間內提\n出，一般為5年"},{c:"4.9",s:"下列哪一項關於絕對轉讓和抵押轉讓的陳述是不正確?",o:["絕對轉讓是永久性安排","如果抵押轉讓已經存在，保單抵押貸款或者退保是不可能的","在抵押轉讓中，承轉人就保單享有無限權益","抵押轉讓可能以保單作為貸款的抵押品"],a:2,e:"抵押轉讓條款把承讓人的利益限\n貸款金額連利息，所以選項C不正確"},{c:"4.10",s:"如保單所有人沒有註明紅利的選擇，保險人會自動為保單所有人將紅利存放以賺取利息或",o:["以現金支付","用以繳付未來保費","用以購買清繳增額保險","購買一年期的定期壽險"],a:2,e:"購買清繳增額保險及紅利存放保險人\n以賺取利息屬自動紅利選擇"},{c:"4.11",s:"人壽保險可選取哪一項或哪些賠付的方式",o:["整數給付","固定的給付數額，直至終生","保單支付利息","以上各項皆是"],a:3,e:"以上各項皆是人壽保險可選取賠付的\n方式"},{c:"4.12",s:"壽險保單中的自殺條款目的在於?",o:["阻止人們自殺","把所有涉及自殺的索償無效","避免本著自殺的念頭而購買的人壽保險生效","杜絕所有涉及自殺的索償的可能性"],a:2,e:"自殺除外責任條款是為防止有人藉自\n殺來取得保險金賠償，保險人採取一\n些防範措施，也絕對是合理的。"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["公司抽獎","特定花紅","品牌建立禮品","網絡優惠劵"],a:3,e:"網絡優惠劵不屬指引25內指明的許可\n禮品"},{c:"5.5",s:"下列哪項屬於保單所有人服務部的職能？",o:["索償處理","權益管理","市場推廣","以上各項皆是"],a:1,e:"只有權益管理屬於保單所有人服務部\n的職能"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni. 它的股東人數不超過50人\nii. 公司在法律上由分紅保單所有人擁有\niii. 由董事局及高級管理層控制\niv. 相互公司不能轉變成為營利公司",o:["i,ii","i,ii,iv","i,iii,iv","ii,iii"],a:3,e:"「相互」保險公司是沒有股東，世界\n各地的「相互公司」都陸續進行股份\n化營利公司，只有ii,iii是「相互公\n司」正確描述"},{c:"5.2.1",s:"以下哪項是不大可能於投保單出現的資料?",o:["下一個生日年齡","職業、住址及家族病歷","保險代理的佣金率","保單所需的生效日期"],a:2,e:"保險代理的佣金率不屬投保單出現的\n資料"},{c:"5.3",s:"以下哪項的描述是正確的?",o:["人壽保險對個別風險的核保工作於每個保週年重新進行","核保工作只影響保費","人壽保險核保可以確定可保性及條款","以上全部皆正確"],a:2,e:"人壽保險核保可以確定可保性及條款\n，而且只有一次核保機會，除了影響\n保費，也會影響保險人承保決定，只\n有答案C是正確"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni. 它沒有股東\nii. 公司在法律上由分紅保單所有人擁有\niii. 由董事局及高級管理層控制\niv. 相互公司不能轉變成為營利公司",o:["ii,iii,iv","i,ii","ii,iii","i,ii,iii"],a:3,e:"相互公司並不代表不能轉變成為營利\n公司，選項iv不正確。"},{c:"5.2.6",s:"以下哪項是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨回報率?",o:["3%","8%","1%","以上各項皆是"],a:0,e:"投資壽險保單利益說明文件的具體規\n定獲授權保險人可選擇闡述的假設淨\n回報率是:0%, 3%,6%,9%,或較低的0%,\n2%,5%,7%"},{c:"5.2.7",s:"相對投資相連保單，分紅保單的好處是︰\ni. 有保證的現金價值及死亡利益\nii. 保單所有人所承受的投資風險較低\niii. 有獨立的精算師監管\niv. 分紅保單的回報一般是平均派發",o:["i, ii, iii","i, ii, iv","ii,iii,iv","i,iii,iv"],a:1,e:"有獨立的精算師監管不屬有獨立的精\n算師監管"},{c:"5.1.1(a)",s:"保險公司會計部的主要職能和責任包括：\ni) 記錄公司收入\nii) 監管公司支出\niii) 遵守(保費守則)\niv) 遵守(保險代理操守守則)",o:["i, ii","i, iii","iii,iv","ii,iii"],a:0,e:"遵守(保費守則)及遵守(保險代理操守\n守則)不屬保險公司會計部的職責，選\n項iii&iv不正確"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》根據以下哪項/些機構頒布的保險核心原則而制定？",o:["國際保險監督聯會","特區政府","保險監督聯合會","國際保險業聯會及國際保險監督聯會"],a:0,e:"《承保長期保險業務(類別C業務除外)\n指引》根據國際保險監督聯會頒布的\n保險核心原則而制定"},{c:"5.2.7a",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni.保險人一般會將紅利平均派發，以減低短期大幅波動\nii.紅利金額是基於獲委任精算師的意見而釐定的\niii.紅利金額是基於獲委任精算師的意見，並經董事會批准而釐定\niv.保險人一般保留釐定紅利金額的權利",o:["i,ii","ii,iii","i,iii,iv(cid:9)","i, iii"],a:2,e:"保險人一般保留釐定紅利金額的權利\n。紅利金額是基於獲委任精算師的意\n見，並經董事會批准而釐定的。保險\n人可因應政策決定平均派發的方法，\n選項ii不正確"},{c:"5.2.8",s:"根據《承保長期保險業務(類別C業務除外)指引》,銷售有關萬用壽險的保險人必需予以 披露",o:["未來的預期派息率","過往派息率","非保證紅利的實現率","保險人所提供的保證息率"],a:1,e:"根據指引16,銷售有關萬用壽險的保險\n人必需予以披露過往派息率"},{c:"5.2.8",s:"根據《承保長期保險業務類別C業務除外）指引》(指引16)，當銷售分紅（或有利潤）長期保單時\n，必須告知客戶",o:["過往的投資表現非分紅產品未來表現的指標","過往的紅利派發表現並非分紅產品未來表現的指標","過往的紅利派發表現僅指非分紅產品未來表現的指標","保險人不是承擔任何投資風險"],a:1,e:"根據指引16，當銷售分紅（或有利潤\n）長期保單時，必須告知客戶過往的\n紅利派發表現並非分紅產品未來表現\n的指標"},{c:"5.3.1",s:"與技術性核保相比，財務性核保較為著重保險的金額，尤其關於下列哪項或哪些?",o:["預期受保保單所有人繳付保費的能力","審慎保險人需安排再保險的可能性","就一個人已累積購買的保單計劃","以上各項均需考慮"],a:3,e:"以上各項都是技術性核保均需考慮的\n因素"},{c:"5.4.1(b)",s:"以下哪項保險種類會提供「保險憑證」及「成員登記卡」？",o:["終身保險","儲蓄保險","團體保險","以上皆不是"],a:2,e:"團體保單文件涉及總保單，\n為每位受保人提供保險憑證\n，還有成員登記卡。"},{c:"5.1.1(e)",s:"下列哪項不大可能屬於保單所有人服務部的職能？",o:["通訊","收取保費","索償處理","權益管理"],a:2,e:"索償處理屬理賠部負責"},{c:"5.2.2(a)",s:"人壽保險人透過簽發其中一種的保費收據，表示同意有關保險於投保時開始生效，但須於稍後證實\n投保人按照標準條款是屬於可保的。這種收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:2,e:"附條件保費收據須於稍後證實投保人\n按照標準條款是屬於可保的，有關保\n險於投保時開始生效"},{c:"5.2.2(b)",s:"立約保費收據有另一名稱，其中TIA全名為",o:["定期被接納保險 Term Insurance accepted","臨時保險證明 Temporary Insurance acknowledge","臨時保險協議 Temporary Insurance agreement","定期保險申請 Term Insurance application"],a:2,e:"立約保費收據有另一名稱，其中TIA全\n名為臨時保險協議 Temporary\nInsurance agreement"},{c:"5.2.8",s:"《重要資料聲明書-內地人士來港投購人身/壽險保單》這項監管措施，規定由誰來遵守？",o:["提供投資相連長期業務以外的長期業務的保險人","提供經營長期業務的獲認可保險人","提供經營一般及長期業務的獲認可保險人","提供經營長期業務的獲授權保險人"],a:3,e:"《重要資料聲明書-\n內地人士來港投購人身/壽險保單》這\n項監管措施，規定由提供經營長期業\n務的獲授權保險人遵守"},{c:"5.2.7a",s:"按照派發方式，保單紅利共有三種，包括",o:["延遲紅利","即時紅利","現金紅利","最後紅利"],a:2,e:"按照派發方式，保單紅利共有三種，\n包括現金紅利"},{c:"5.3",s:"保險公司對於特定風險，核保人不僅需留意該風險所代表的道德及實質危險，還需注意保險金額及\n有關個人對保險人有否任何累積影響，其中後者可被描述為",o:["財務性核保","額外危險核保","非技術性核保","外來因素核保"],a:0,e:"財務性核保預期保單所有人繳付保費\n責任的能力，及考慮就同一受保生命\n已累積購買的保額，是否超出與投保\n人 的年齡的通常水平"},{c:"5.5",s:"售後服務是一個重要因素。它是由顧客服務部或下列哪個部門負責",o:["POS (Policyowner Service) 保單所有人服務","ASS (after-Sales Service) 售後服務","BCS (better customer Service) 更好客戶服務","ICO (Improve customer Service) 改善客戶服務"],a:0,e:"保單所有人服務售後服務是一個重要\n部門"},{c:"5.6.1",s:"期滿索償出現於下列哪類或哪些保險中？",o:["定期壽險","終身壽險","儲蓄壽險","以上所有各項"],a:2,e:"期滿索償出現於儲蓄壽險"},{c:"5.6.2",s:"死亡日期對下列哪項保險計劃有重要的影響？",o:["遞減定期壽險","分紅壽險","快將到期的定期壽險","以上各項都是"],a:3,e:"死亡日期對所有人壽保險計劃都是重\n要的"},{c:"5.6.2",s:"就受保生命的死亡原因，可能會引起保險人的關注，除了一般查詢外，以下那種情況會軀使保險人\n作進一步調查？\ni) 受保人自殺身亡\nii) 受保人年屆80歲自然死亡\niii) 受保人可能被妻子(指名受益人)謀殺\niv) 保單生效後不久受保人便告死亡",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:2,e:"受保人年屆80歲自然死亡通常都不會\n軀使保險人作進一步調查"}],"paper3-2025-11":[{c:"1.2.3(c)",s:"下列哪項關係不具有可保權益?",o:["17歲兒女","17歲的受監護人","17歲妹妹","以上各項皆有可保權益"],a:2,e:"在香港，未成年人（未滿18歲的人）\n的父母或監護人就該年輕人享有可保\n權益。這類關係是在配偶關係以外，\n唯一構成可保權益的血緣或家庭關係\n。（兄弟、姐妹、父母、子女、祖父\n母、孫等）本身不可構成可保權益。"},{c:"1.3.1a",s:"以下哪項不是用以計算壽險保費考慮的因素?",o:["死亡率","開支","利息","性別"],a:3,e:"性別不是用以計算壽險保費考慮的因\n素"},{c:"1.2.3(a)",s:"以下哪三項有關人壽保險的近因原則的應用的描述是正確的?\ni. 不保危險不大可能是重要原則\nii. 由於所有死亡原因都受保，近因原則不適用\niii. 如果懷疑受保人自殺是死亡原因，近因原則的應用是很重要\niv. 如果雙倍賠償利益附約適用，近因原則的應用是很重要",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"如果受保生命在該免責期內(通常為保\n單發出後一年內)自殺，保險人無須支\n付死亡保險金，構成人壽保險的除外\n責任，所以選項(ii)不正確"},{c:"1.3.2a",s:"下列哪項屬於自然保費制度的特點？",o:["保費隨年齡增長而增加","會產生逆選擇","大部份保險公司已不採用","以上各項皆正確"],a:3,e:"以上各項都屬於自然保費制度的特點"},{c:"1.3.1a",s:"以下哪項關於死亡表的描述是正確的?\ni. 顯示不同年齡的預期死亡比率的計算表\nii. 應付所有預期及可能出現的營運開支\niii. 考慮某種新疾病或其他災難引起異常死亡率的可能性\niv. 只應付正常風險和正常預期的死亡率",o:["i, iii","i,iv","ii,iv","以上各項皆是"],a:1,e:"死亡表或稱生命表顯示不同年齡的預\n期死亡比率的計算表，在保險行業中\n十分通用。利用死亡表釐定費率，只\n是應付正常風險和正常預期。所以只\n有選項i及iv是正確"},{c:"1.2.1(h)(iii)",s:"以下哪項有關壽險保單轉讓與可保權益法律規定的關係的陳述是正確？",o:["保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者","保單所有人一般可以將正當地安排的人壽保險合約轉讓給第三者，即使該第三者對受保生命缺乏\n可保權益","保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者","準保單所有人意圖向一受保生命購買一份壽險合約，但卻與受保生命缺乏可保權益，他大可以安\n排後者購買保單自保生命後轉讓給他，而成為轉讓保單的合法所有人"],a:1,e:"保單所有人一般可以將正當地安排的\n人壽保險合約轉讓給第三者，即使該\n第三者對受保生命缺乏可保權益仍可\n作出保單轉讓"},{c:"1.2.1(h)",s:"丈夫為其妻子的生命投保了一份整付保費壽險保單，後來妻子離世，當時雙方已離婚，結果",o:["丈夫只可取回已邀保費，加上利息","丈夫無權就妻子的死亡索償","丈夫只可取回已邀保費","丈夫有權就妻子的死亡索償"],a:3,e:"人壽保險的可保權益只有在合約開始\n時才需要，就以上的關係轉變，仍然\n維持該保單的有效性，即使雙方已離\n婚，丈夫有權就妻子的死亡索償"},{c:"1.3.2a",s:"以下哪項就自然保費釐定制度的描述不正確?",o:["保險人已不再使用自然保費制度","該制度會出現不利於保險人的逆選擇","保費會隨年齡增長而增加","以上各項皆不是"],a:3,e:"以上各項都是自然保費釐定制度的正\n確的描述，所以答案D不正確"},{c:"1.1",s:"人壽保險合約最初類型",o:["本質上屬於短暫的，以保障早逝情況","本質上屬於長久的，即直至死亡","與物業抵押貸款有關","屬單位相連的安排"],a:0,e:"最初，保險單有效期較短，只為暫時\n性的風險情況"},{c:"1.2.1(d)",s:"就可保權益而言，按照法律要求，如要對其他人（即本身及其配偶以外的人）擁有可保權益，\n以下那項描述是正確的？",o:["法律要求兩者之間必須存在法律上有僱傭關係","法律要求兩者之間必須存在某種血緣關係","法律要求兩者之間必須不可以存在某種財務關係","法律要求兩者之間必須存在某種財務關係"],a:3,e:"除了對自己的生命及對其配偶具有無\n具有無限金額的可保權益，並可對其\n他人存在某種財務關係，也存狂有限\n的可保權益"},{c:"1.2.3(a)(ii)",s:"下列哪項關於彌償的陳述是正確的？",o:["除非由法律隱含，否則彌償不存在於人壽保險","法律不容許人壽保險作出彌償","不可能對喪失生命作出超額彌償","五十年前，彌償普遍存在於人壽保險"],a:2,e:"人壽保險亦稱為利益保單，不可能超\n額賠償，因為人壽保險可保權益在大\n多數情況下是無限的"},{c:"1.2.3(c)",s:"分擔與代位權",o:["不適用於人壽保險","對人壽保險的索償很重要","其重要性在人壽保險索償與一般保險索償一致","以上所有皆是"],a:0,e:"分擔與代位權是彌償原則的引伸，不\n適用於人壽保險"},{c:"1.3.1",s:"按照壽險傳統保費計算方法，保費應該可應付所有有關成本，並可反映有關之風險，描述有關之保\n費標準為",o:["公平及公正的","公平及足夠的","充足及公平（公正）的","充足及合適的"],a:2,e:"按照壽險傳統保費計算方法有關之保\n費標準為充足及公平（公正）的"},{c:"1.3.2b(c)",s:"一名已持有一份終身壽險多年被保險保單所有人，因被裁員而失去工作，現想終止保單。保險人/\n代理人應",o:["解釋不能作廢條款","解釋清繳保險","提議利用保單抵押貸款，以解燃眉之急","解釋以上各項並協助他作出抉擇"],a:3,e:"以上皆是均衡保費制度下由早期「盈\n餘」保費而產生的特性，保單所有人\n可以在以上各項作出選擇"},{c:"2.3.1(d)",s:"以下哪項是年金的描述是正確的?\ni. 年金利益付款開始時的年齡越高，毎一期年金利益付款便越高\nii.在相同年齡下男性收取的定期年金高於相同年齡的女性\nii. 相同因素下，年齡女性的年金保費高於男性\niii. 人壽保險與年金核保原則有頗大分別",o:["i,ii(cid:9)","ii, iii(cid:9)","ii,iii,iv(cid:9)","i,ii,iii ,iv"],a:3,e:"以上各項皆是年金的正確描述"},{c:"2.1.1",s:"下列哪項有關定期壽險的陳述是正確的？",o:["索償是無可避免的","在大多數情況下，定期壽保險期仍沒有出現索償下屆滿","最少存在10年保險期","保單往往被保險人取消，並退回保費"],a:1,e:"定期壽險保障期短，在大多數情況下\n，定期壽保險期仍沒有出現索償下屆\n滿"},{c:"2.1.1a",s:"作為一種定期壽險，定額定期壽險",o:["以分紅形式簽發","於指定數目的學期內支付學費","是一種非常有效的儲蓄工具","受保生命在保險期內死亡，才可以獲得按保單的保額支付的保險利益"],a:3,e:"定額定期壽險是沒有現金價值，固定\n的死亡保險金額，並不會分紅形式簽\n發，只有選項iv是正確"},{c:"2.1.1a",s:"以下哪項有關遞減定期壽險的描述是不正確？",o:["這是定期壽險其中一種變化","現有人壽保險種類中最便宜的","適合於逐漸減少的短暫保障需求","支付的利益按保單持有人的實際需要而變化"],a:3,e:"支付的利益按保單持有人的實際需要\n而變化，不是遞減定期壽險的描述"},{c:"2(b)",s:"下列哪項屬於基本形式之壽險保單的常見變化？\ni)保單所有人可以選擇將保單紅利轉換為公司股份\nii)如果最初只投保一段有限時間，可能可以續保\niii)保單所有人可以選擇將保單紅利轉換為公司優先股\niv)保單可加入各種附約，用以改善所提供的保障",o:["i, ii","iii, iv","ii, iv","i, ii, iii, iv"],a:2,e:"可續保的及可轉換的是人壽保險的基\n本變數"},{c:"2.2.2",s:"以下哪項是單位相連保單的不正確描述?",o:["它可以與股票基金掛勾","全部或部份保費用以購買基金單位","它只可以與定期壽險或儲蓄壽險相連","保單價值會隨投資表現而變動"],a:2,e:"單位相連保單理論上是可以跟所有保\n險險種相連，最常見的是與定期壽險\n或儲蓄壽險相連"},{c:"2.2.2",s:"單位相連長期保單的保單價值，可與人壽保險人經營的特殊單位化基金的單位正式掛鈎，或與",o:["除此以外，並無它法","任何指數表現掛勾","單位信託的單位掛鈎","與美元匯率掛勾"],a:2,e:"單位相連長期保單的保單價值，可與\n人壽保險人經營的特殊單位化基金的\n單位正式掛鈎，或與單位信託的單位\n掛鈎"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"年金計劃在累積期內，保單持有人在\n一段時間內定期繳付保費，讓保險人\n通過投資令已付金額增長"},{c:"2.3.1(b)",s:"保險人須在課稅年度（ 即 3月 31日）結束後的\n____天內，向保單持有人就其每張保單各別發出合資格延期年金保單的年度摘要。",o:["40","30","50","45"],a:0,e:"保險人須在課稅年度結束後的40天內\n，向保單持有人就其每張保單各別發\n出合資格延期年金保單的年度摘要。"},{c:"2.1",s:"如果對人壽保險有短暫的需求，所需的財務金額在該段時期都不會增加或減少，並且該需求會在指\n明的期間後便消失，就以保險成本為一重要的考慮因素，以下哪一項不太適合?",o:["定額定期壽險","非儲蓄定期壽險","分紅終身壽險","非分紅終身壽險"],a:2,e:"終身壽險的保費比定期壽險高，而分\n紅計劃的保費亦比非分紅計劃高，以\n保險成本為一重要的考慮因素，分紅\n終身壽險最不適合"},{c:"2.1.1b(b)",s:"駱先生大學畢業不久，沒多少錢可以用於買人壽保險，然而將於明年結婚。為什麼你認為他應該考\n慮購買可轉換定期壽險？",o:["可轉換定期壽險的保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單\n轉為永久計劃","可轉換定期壽險給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單轉換為更便宜的\n計劃","可轉換定期壽險保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單轉\n換為聯合壽險計劃","對年不過三十的人來說，可轉換定期壽險最適合不過"],a:0,e:"可轉換定期壽險保單所有人提供一個\n轉換特權，在毋須提供可保性健康證\n明的情況下將保單轉換為永久計劃的\n權利"},{c:"2.1.1b(b)",s:"如果一般人壽保險中標明「可轉換的」則表示",o:["保單可隨時被保險人結束","保險人可更改為另一種計劃","保單持有人可更改為另一種計劃","保單持有人可自由選擇以那一種貨幣繳費"],a:2,e:"可轉換定期壽險保單所有人提供一個\n轉換特權，在毋須提供可保性健康證\n明的情況下將保單轉換為永久計劃的\n權利"},{c:"2.1.3",s:"終身壽險的特點為",o:["只對指定時期內的死亡支付賠償","任何時候受保生命去世,即支付保額","在某一特定日期前死亡支付賠償","保險人按月支付補償給投保人"],a:1,e:"終身壽險於受保生命任何時候去世是\n便會即支付保額"},{c:"2.1.3(a)(i)",s:"純粹壽險是指",o:["保單不適用附約或其他保障","保額在意外死亡時才支付","受保生命在世期間終身繳付保費","受保生命被評估為可按標準保費及屬標準風險"],a:2,e:"純粹壽險是指受保生命在世期間終身\n繳付保費，亦是終身壽險的別稱"},{c:"2.2.1",s:"以下哪項屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","「分別列示各定價因素」","以上各項皆是"],a:3,e:"以上皆是萬用壽險的特點"},{c:"2.2.2(a)",s:"下列哪項是單位相連保單的共同原則？",o:["有關保單通常有分紅成分","有關單位須與股票基金掛鈎","有關保險人必須保證最低的單位價格","全部或部份保費用作購買基金單位"],a:3,e:"單位相連保單的共同原則是全部或部\n份保費用作購買基金單位"},{c:"2.3",s:"年金利益款項給付予?",o:["收款人","保單受益人","保單持有人","年金購買人"],a:0,e:"年金利益款項給付予收款人"},{c:"2.3.1(c)",s:"被描述為「確定期間終身年金」與下列哪項相關？",o:["確定年金","延期年金","即期年金","保證年金"],a:3,e:"「確定期間終身年金」又稱保證年金"},{c:"2.4&5.4.1(b)",s:"準備團體保單文件時，有關的技術系統通常會印製下列哪份或哪些文件?",o:["總保單","每名受保人的保險憑證","每名受保人的成員登記卡","以上所有各項"],a:3,e:"以上所有各項都是準備團體保單文件\n時，通常會印製的保單文件"},{c:"2.4(e)",s:"以下有關團體壽險保單在核保的審核正確的是？",o:["團體計劃通常不會要求詳細的個人資料","團體計劃通常要求詳細的家族病歷","團體計劃通常要求詳細的個人核保","團體計劃的個人保費通常高於個人保險的累積保費"],a:0,e:"團體計劃通常不會要求詳細的個人資\n料"},{c:"3.3.1",s:"以下哪些不是危疾保險利益附約的陳述正確？",o:["某些保險人可能選擇每月支付保險利益","危疾保障僅適用於某歲數或以下的人","受保事件發生後，受保保單所有人有時獲給付部分的死亡保險金","受保事件發生後，受保保單所有人總是須要繼續繳交保費"],a:0,e:"每月支付保險利益不屬危疾保險利益\n附約的選擇，受保事件發生後，危疾\n保險利益的受保保單所有人將獲給付\n死亡保險金的載明部分，若所界定喪\n失工作能力發生了三個月後，才會豁\n免保費所有續保保費"},{c:"3.3.2",s:"以下哪項就長期護理利益的陳述正確?\ni. 通常設有180日的等候期\nii. 受保保單所有人在接受長期護理利益的期間，通常獲得豁免保費\niii. 已接受長期護理利益的受保保單所有人死亡，將支付全數的死亡保險金\niv. 受保保單所有人可選擇在家中由正式註冊的護理員護理",o:["i, iii","ii,iv","i,ii,iii","i,ii,iii,iv"],a:1,e:"通常在給付長期護理保險利益之前有\n一個為期\n90日的等候期。每月在護理院護理的\n利益為死亡保險金的某個百分比，正\n確描述只有ii,iv, 正確答案是B"},{c:"3.5.1",s:"以下哪項是保證可保選擇的特點?",o:["限制","非自動獲得","指定事件","以上各項皆是"],a:3,e:"以上各項皆是保證可保選擇的特點"},{c:"3.3.1",s:"危疾保險利益附約經常指明的疾病是︰",o:["中風","心臟病","肺癌","以上所有各項"],a:3,e:"以上都是危疾保險利益附約經常指明\n的疾病的例子"},{c:"3.3.2",s:"以下哪項描述不適用於長期護理附約?\ni. 等候期一般是一至九個月\nii. 會扣除部分死亡保險金支付長期護理利益\niii. 在接受長期護理利益的期間會獲得豁免保費\niv. 必須在醫院接受護理",o:["i,ii","i,ii,iii","i,iv","ii,iii,iv"],a:2,e:"長期護理附約等候期一般是一至九個\n月"},{c:"3.1.1",s:"以下那項是「豁免保費附約」的正確描述？",o:["保單所有人完全殘疾，殘疾期間豁免保費","當保單生效一段期間後保單所有人完全殘疾，殘疾期間豁免保費","當保單所有人失業時豁免保單所有人之保費","當市場上競爭對手保費低廉，保險人便退還保費"],a:0,e:"「豁免保費附約承諾在受保保單所有\n人完全傷殘時放棄其收取續保保費的\n權利。這並不代表保單被中止，保單\n將依然有效，"},{c:"3.1.1(d)",s:"下列哪三項較可能是豁免保費(WP)附約的除外責任？\ni. 保單生效前既存的狀況\nii. 在從事違法活動時導致的殘疾\niii.因受僱用及其過程導致的殘疾\niv. 戰爭時服兵役導致的殘疾",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"選項iii因受僱用及其過程導致的殘疾\n不屬是豁免保費(WP)附約的除外責任\n，只有i,ii,iv選項正確"},{c:"3.1.1(d)",s:"以下哪項是殘疾豁免保費附約的描述是正確的?\ni. 保險人放棄收取本來應收保費的權利\nii. 代表保單將會終止\niii. 保單紅利仍然累積\niv. 可附加於不同類型的壽險",o:["i, ii","i, iii","i, iii, iv(cid:9)","ii, iii, iv"],a:2,e:"殘疾豁免保費附約一經開始，豁免會\n於保單的有效期內繼續下去，一直到\n相關傷殘結束為止，選項ii不正確"},{c:"3.2.1",s:"意外死亡保險利益附約支付利益的準則,死亡必須於?",o:["意外身體受傷後一段指定時間內發生","有關基本計劃須包含豁免保費附約","在受保保單所有人昏迷時死亡","即時死亡"],a:0,e:"意外死亡保險利益附約支付利益的準\n則，死亡必須由意外身體受傷而直接\n引起， 並與所有其他原因無關並\n於該受傷的一年之內發生"},{c:"3.3(c)",s:"根據提前支付死亡保險利益條款，在某些嚴重的情況下，縱使死亡並未發生，保單所列明的死亡金\n是可以支付給保單所有人，但",o:["受益人/承讓人必須簽署棄權聲明","受益人同樣可以取回所有索償","受益人如果在受保人死後兩年內便可獲取所有索償","受益人只可取回保費"],a:0,e:"由於向在世的受保保單所有人發放保\n險利益會對保單受益人的期望造成一\n定的影響，因此有些保險人會於處理\n此類附約的給付申請時，要求受益人\n簽署一份棄權聲明或稱解除責任憑證\n，同意提前支付的保險利益數額會從\n將來的死亡保險金中扣除。"},{c:"3.3.1(e)",s:"以下哪些是危疾保險利益附約設定的保障限制？\ni)必須累積某數額或以上的現金價值\nii)危疾保障生效僅適用於某歲數以下的人\niii)多重疾病和復發性的疾病可能不會獲得給付，某一兩類疾病或屬例外\niv) 遂漸減少的自負額",o:["i,ii","ii,iii","i,iii,iv","i,iii"],a:1,e:"必須累積現金價值及自負額都不是危\n疾保險利益附約的限制，只有選項(ii\n)及(iii)正確"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認\n可的個人償款住院保險產品，供消費\n者自願選購，團體保險並不適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫\n療服務的消費者提額外的保險計劃選\n擇"},{c:"3.4.1",s:"以下哪一項不是《自願醫保計劃下保險公司的實務守則》的涵蓋範圍?",o:["轉移安排","保障條款","銷售及推廣","售後服務"],a:1,e:"保障條款不是《自願醫保計劃下保險\n公司的實務守則》的涵蓋範圍"},{c:"3.5.1",s:"保證可保利益在某些情況下亦稱為",o:["終身保證利益","預批購買選擇","終身可保選擇","保證受保利益"],a:1,e:"保證可保利益在某些情況下亦稱為預\n批購買選擇"},{c:"3.1.1",s:"以下哪項或哪些是「豁免保費」附約支付利益的準則描述是正確?",o:["受保保單所有人必須死於他生前引致完全傷殘的那項成因","受保保單所有人在保單有效期內變成完全傷殘,而且已持續一段指明時間(稱為等侯期)","當受保保單所有人完全傷殘時,之前最少已經部分傷殘達到某段時間(稱為等侯期)","以上各項均不屬於該附約支付利益的準則"],a:1,e:"受保保單所有人在保單有效期內變成\n完全傷殘,而且已持續一段指明時間(\n稱為等侯期，一般為為3或6個月)"},{c:"3.1.1",s:"以下哪項或哪些有關豁免保費附約的描述是正確的？",o:["(WP)即代表「無利潤」","在完全傷殘時，保險人放棄收取保費的權利","保險利益通常須通過相等於保險期限的百分之十的「等候期」","以上各項"],a:1,e:"保險人根據此項附約承諾在受保保單\n所有人完全傷殘時放棄其收取續保保\n費的權利。這並不代表保單被中\n止，保單將依然有效"},{c:"3.2.1(a)",s:"壽險保單中的雙倍補償利益，如果死亡由意外身體受傷引致",o:["保險人會支付相當於保單保額兩倍的金額","在保額以外再支付殮葬費用","支付一筆相等於現存紅利兩倍的金額","支付一筆相等於已繳保費兩倍的退保費"],a:0,e:"壽險保單中的雙倍補償利益，如果死\n亡由意外身體受傷引致，保險人會支\n付相當於保單保額兩倍的金額"},{c:"3.2.1(b)",s:"喪失肢體附約定義為",o:["某些保險人可能會將定義延至整條手臂或臀部以下部位","保障涉及喪失該肢體功能","喪失一個手指關節也可得到賠償","附有每周住院津貼保障"],a:1,e:"在意外死亡及喪失肢體附約中，「喪\n失肢體」包括喪失肢體及喪失視力的\n意思"},{c:"3.3.2",s:"當保險人按長期護理保險利益附約支付利益時，其原本的基本保費和附約保費將會？",o:["提高","暫停，但要在較後的時間繳還或扣除","於保險人支付利益時期豁免保費","減少百分之五十，並於康復後回復正常"],a:2,e:"受保保單所有人在接受長期護理利益\n的期間，通常都會獲得豁免保費，包\n括附約的保費及基本保險計劃的保費\n。"},{c:"3.3.2",s:"附加壽險保單的長期護理附約規定",o:["於死亡時支付雙賠保額","提供的付款與可予支付的保單毫無關係","由保險人支付認可護理院的費用","支付保單死亡保險金的某所述部份作長期護理的費用"],a:3,e:"長期護理附約利益屬預繳性質，已支\n付的保單利益會在死亡保險金扣除"},{c:"3.4",s:"一份典型的醫療保險，不大可能接受以下哪項原因的「醫療開支」?",o:["道路交通意外導致的住院醫療","出院後一個月內的門診病人跟進護理","由主診醫生建議的私人護理","除去先天性面部皮膚疤痕的整容手術"],a:3,e:"除去先天性面部皮膚疤痕的整容手術\n不大可能接受以下哪項原因的「醫療\n開支」"},{c:"3.5.1",s:"有關保證可保選擇，容許受保人作出購買增額保障的選擇，以下那項描述是不正確的?",o:["自動獲得增額保障的選擇","如不及時作出選擇，便會喪失權利","部分保險人於備擇日期內提供定期壽險","只可在指定限期內作出選擇"],a:0,e:"保單所有人如果錯過了行使已觸發的\n選擇權以購買增額保障的話，就會喪\n失該次權利，答案A不正確"},{c:"3.5.1(f)",s:"如果一項保單有「保證可保權益」附約，被保險人可選擇增額的保障，而且保證接納；如果該份保\n單同時附帶「豁免保費支付」附約，而被保險人在決定行使該選擇權時，遭致殘障，那麼",o:["有關「保證可保權益」會取消","增額的保障會自動生效","直至被保險人康復，才會提供增額的保障","被保險人可要求增額的保障，但可能獲拒絕"],a:1,e:"受保保單所有人在行使購買增額保險\n選擇權時已經成了殘疾人，他將會自\n動獲得該項額外保障。\n豁免保費附約也規定可以豁免所有保\n費，直至受保保單所有人\n康復或死亡為止。"},{c:"3.6.1",s:"稱為生活指數調整利益的附約的原意是",o:["對抗經濟週期的影響","對抗通貨膨脹和通貨收縮兩者的影響","為罹患終末疾病的人發放部份保額","上面各項都不是答案"],a:3,e:"對抗經濟週期的影響及通貨收縮，為\n罹患終末疾病的人發放部份保額等，\n都不是生活指數調整利益的附約的原\n意，以上各項都不是答案"},{c:"3.6.1",s:"COLA的英文全寫是",o:["壽險成本調整 Cost of Life Insurance Adjustment","壽險/年金合同的補償 Compensation of Life / Annuity Contract","壽險利益補償 Compensation of Life Assurance Benefit","生活指數調整利益 Cost of Living Adjustment"],a:3,e:"COLA的英文全寫是生活指數調整利益\nCost of Living Adjustment"},{c:"4.9",s:"對於一個保單所有人來說，對保險合約的權益也可形容為「復歸的」 ，即是說",o:["仍未取得該項權益","肯定會在將來取得該權益","保單所有人對該合約的權益獲得承認，但他尚未能實際享用該項權益","該權益可以轉讓給其他人"],a:2,e:"「復歸的」權益是指保單所有人對該\n合約的權益獲得承認，但他尚未能實\n際享用該項權益"},{c:"4.5",s:"以下哪項不屬於人壽保險的不能作廢條款常見的選擇?",o:["減額清繳保險","支付全數的死亡保險金","展期保險","以上各項皆不是"],a:1,e:"支付全數的死亡保險金不屬於人壽保\n險的不能作廢條款常見的選擇"},{c:"4.1",s:"以下哪項就人壽保險保單文件的描述是正確的?",o:["索償出現時，死亡保險金只可以支付給保單所有人","只有在索償時才適用","完整的保險合約由保險單、任何夾附的附約及夾附的投保單複印本構成","以上各項皆正確"],a:2,e:"完整的保險合約由保險單、任何夾附\n的附約\n及夾附的投保單複印本構成，只有答\n案C描述正確"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保\n單，保單的持有人決定不再繳付任何\n保費有權選取的選擇"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["保險人有權選擇賠付方法","通常是整筆過支付","用利益購買年金","將收益保留在保險人處以賺取利息"],a:0,e:"只有保單持有人或受益人有權選擇賠\n付方法"},{c:"4.8",s:"因混淆外國人名字，人壽保單簽發一段時間後，才發現該保單將女性受保人誤以為是男性，經相討\n後，如果保單所有人願意支付相同的保費金額，保險人會作出以下哪項修改？",o:["退還由投保當日起計的所有保費","將保單保額調高","調低保單保額，以反映已繳付保費相符的正確保額","調高保費，以反映保單少付的保費"],a:1,e:"保單將女性受保人誤以為是男性，因\n女性保費率比男性為低，如果保單所\n有人願意支付相同的保費金額，保險\n人便會將保單保額調高"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已婚者地位條\n例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非張先生就《已婚者地位條例》訂明，被保險人就自身生命購買保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有\n人如為其配偶及或其任何子女的利益\n而購買壽險單，將達到建立一個（法\n定信託的效用，從而令該配偶及或子\n女成為該保單的實益擁有人。"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許\n藉訂明手續來轉讓據法權產"},{c:"4.11(e)",s:"終身收益選擇，是分期支付約定的保單收益(及利息)，這項選擇實際上是以該項保單收益作為整付\n保費，購買了甚麼?",o:["儲蓄壽險","投資相連壽險","終身年金","終身壽險"],a:2,e:"這項選擇實際上是以該項保單收益作\n為整付保費，購買一份終身年金"},{c:"4.12",s:"保險公司通常就索償提供的一種給付，出於善意或恩恤的目的，保險公司在法律上並沒有義務就這\n些索償提供給付，這給付稱為",o:["解除賠付","恩恤賠付","通融賠付","額外賠付"],a:2,e:"出於善意或恩恤的目的，保險公司在\n法律上並沒有義務就這些索償提供給\n付，這給付稱為通融賠付"},{c:"4.10",s:"如果保單所有人沒有作出紅利選擇，大多數保單會採用一種稱為___________的方式。",o:["自動紅利選擇","現金紅利選擇","保單紅利選擇","以上皆不是"],a:0,e:"如果保單所有人沒有從上述各項中作\n出選擇，大多數保單會採用一種稱為\n「 自動紅利選擇 」的方式。"},{c:"4.3",s:"以下哪項寬限期的說明是正確的？",o:["適用於保單的首期保費","保險人必須在賠償付款前的期限","保單所有人索償的一段時間","在保費到期日仍未繳交後，保單仍然有效的一段時間"],a:3,e:"寬限期又稱「寬限日期」，它指保費\n到期日之後保險保障仍然維持有效的\n一段時間。"},{c:"4.3",s:"根據美式寬限期的規定，在於寬限期內死亡而保險保費尚未付清，以下哪項是採取的措施？",o:["不能獲取死亡保險金","死亡保險金可獲給付，但未繳清之保費可獲豁免","死亡保險金可獲給付，但未繳清之保費將會從中扣減","該保險合約屬於無效"],a:2,e:"根據美式寬限期的規定，它不是免費\n保險期，在於寬限期內死亡而保險保\n費尚未付清，死亡保險金可獲給付，\n但未繳清之保費將會從中扣減"},{c:"4.4",s:"以下哪項不屬於受益人的「概括式指定」？",o:["「本人的妻子」","「本人的子女」","「本人的兄弟姊妹」","「本人第一段婚姻的子女」"],a:0,e:"「概括式指定」是即指定一組人為受\n益人，而非指名每個人，答案A不正確"},{c:"4.4",s:"某人在訂立某份人壽保險合約時，指定瑪莉為受益人。兩年後，他更改保單，致令萬一瑪莉比他早\n過世，莉莉便會成為受益人。莉莉在該份保險計劃中稱為",o:["後備受益人","次順位受益人","第二受益人","第一順位準受益人"],a:1,e:"受益人付款的基本條件之一是受益人\n在受保生命去世時 還活着\n。可在第一順位受益人以外，指定\n一個或一個\n以上的次順位受益人，如果第一順位\n受益人早逝，死亡保險金會支付給次\n順位受益人"},{c:"4.5",s:"人壽保單中通常具有一些條文，把保單的現金價值即時用於支付尚未繳交的保費，從而避免保單失\n效，部分保險人不認為這是不能作廢條款，而稱之為?",o:["一筆強制性的保單貸款","一筆自動的保費貸款","一項延續保單條款","一項自動保單復效條款"],a:1,e:"把保單的現金價值即時用於支付尚未\n繳交的保費，部分保險人認為這是不\n能作廢條款，他們視之為一個獨立自\n動保費貸款條款或稱保費自動墊繳條\n款"},{c:"4.5",s:"壽險保單中自動保費貸款",o:["貸款用途由保險人任意決定的","貸款在所有壽險保單中，都是常見的","貸款只可用作保單規定的指定用途","以上各項描述均不是"],a:2,e:"壽險保單中自動保費貸款只可用作保\n單規定的指定用途，例如繳交已過期\n保費"},{c:"4.6",s:"下列哪項或哪些屬於保單抵押貸款中慣用條文的特點?",o:["該筆貸款必須用於繳交未來的保費","該筆貸款唯一需要的抵押品就是保單的定期保險","於保單生效期內可以償還或不償還該筆貸款","保單的貸款由保險人決定"],a:2,e:"保單抵押貸款於保單生效期內可以償\n還或不償還"},{c:"4.8",s:"如果一份已簽發的壽險保單顯示受保人的年齡不正確,而該錯誤是於提出任何索償前發現,那麼以下\n哪項描述是正確的?",o:["必須取消該份保單而簽發一份新保單","其中一項選擇是支付任何差額保費(或獲退回多繳保費)","要更改保額或任何合約條款,實屬太遲","基於不可異議條款,不必有所作為"],a:1,e:"如果於提出索償前之前已發現錯誤，\n保單所有人通常可以選擇調整保險利\n益的金額，或調整應付保費，以反映\n在根據正確的年齡／性別"},{c:"4.8",s:"因為保單所有人外語名字，保單資料被誤將女性填寫為男性，此為終身壽險保單，當發現錯誤時，\n被保人堅持支付現時保費金額，保險人該如何處理？",o:["調整保單保額，以反映已繳付保費相符的正確保額","退回多收保費","撤銷保單","保單保額向下調整"],a:0,e:"保單將女性受保人誤以為是男性，因\n女性保費率比男性為低，如果保單所\n有人願意支付相同的保費金額，保險\n人便會將調整保單保額，以反映已繳\n付保費相符的正確保額"},{c:"4.9",s:"壽險保單的絕對轉讓是指",o:["將保單轉給另一名保險人","有關保單即時變為不可異議","原有的保單所有人已被宣佈破產","不可撤銷地轉讓對某份壽險保單的一切擁有權"],a:3,e:"絕對轉讓屬永久性，不可撤銷地轉讓\n對某份壽險保單的一切擁有權"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["即時整筆支付","存放在保險人處以賺取利息","投資於有關保險公司的股份","以上所有各項"],a:2,e:"投資於有關保險公司的股份不屬於壽\n險保單的賠付選擇"},{c:"4.12",s:"若一份已生效四年的保單的索償是基於自殺,該索償",o:["保險人可拒絕該索償","不會被自殺成因影響","刑事法例不允許支付此索償","保險人只須支付50%死亡金"],a:1,e:"保單生效初期(通常一年)若受保生命\n自殺列為除外責任，一份已生效四年\n的保單的索償是基於自殺,該索償不會\n被自殺成因影響"},{c:"5.6.1",s:"對於大部份壽險保單而言，若保單到期日即將迫近，保險公司會﹕\ni) 提醒保單期滿的日期\nii) 說明應付金額\niii) 通知保單所有人將利益付給受益人\niv) 附上適當形式的解除責任憑證 (release)",o:["i, ii","ii, iii(cid:9)","i, ii, iv(cid:9)","ii, iii, iv"],a:2,e:"儲蓄保險期滿索償，益付給保單所有\n人，而不是益人，選項iii不正確，正\n確答案是C。"},{c:"5.2.7",s:"相對投資相連保單，以下哪項不是分紅保單的好處?\na. 回報風險較投資相連保單低\nb. 高透明度保險制度\nc. 保單價值由精算師監管\nd. 靈活性",o:["i,ii,iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:3,e:"參考章節5.2.8 相對投資相連保單，分\n紅保單的好處是較投資相連保單風險\n低，選項ii,iii,iv都不是分紅保單的\n好處，正確答案是D"},{c:"5.2.1(b)",s:"以下哪項是處理人壽險保投保時是應注意的事項？\ni) 下一個(或上一個)生日年齡\nii) 投保人的身份\niii) 保單生效日期\niv) 投保人過去三年的職業紀錄",o:["i, iii","ii, iii(cid:9)","i,ii,iii","i,ii, iii, iv"],a:2,e:"投保人過去三年的職業不是處理人壽\n險保投保時是應注意的事項，選項iii\n不正確，正確答案是C。"},{c:"5.2.7d",s:"以下哪項是關於保費抵銷的正確描述？",o:["將來的現金紅利存放於保險人那裏","將來的紅利購買減額清繳保險","對未來業績表現有利","將來的紅利回報有利"],a:0,e:"保費抵銷預期將來的現金紅利存放於\n保險人那裏，保單持有人有權選擇停\n止繳付保費，但須注意是，未來利率\n水平可以下降的，到時客戶須要\n恢復掏錢付保費，否則可能導致保單\n失效，只有答案A正確。"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個近期曾發出\n新保單的產品實現率是怎樣計算的?",o:["實現率是指按「實際派發的保證英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算","實現率是指按「實際派發英式紅利」除以銷售時「利益說明所述數額」的平均數計算。","實現率是指按「實際派發的非保證英式紅利」除以銷售時「利益說明所述數額」的平均數計算","實現率是指按「實際派發的英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算"],a:2,e:"某個產品的實現率是指按「實際派發\n的非保證紅利／英式紅利」除以銷售\n時「利益說明所述數額」的平均數計\n算"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["身體檢查服務","醫療咨詢服務","緊急救助支援","超市禮券"],a:3,e:"超市禮券，不屬（指引25）內指明的\n許可禮品"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","投資風險","保險回報率"],a:2,e:"投資風險不屬《重要資料聲明書－內\n地人士在港投購人身╱壽險保單》涵\n蓋的部分，詳細參閱研集資料手冊附\n件M"},{c:"5.3.1(a)",s:"人壽保險根據實質危險及道德危險核保確定有關風險程度，以下哪項因素是正確的描述?",o:["與實質危險相比，道德危險較難確定","實質危險涉及較主觀的因素，環繞準被保人的基本誠信或正直意向，道德危險主要考慮到可能增\n加受保事件發生率的","實質危險主要考慮誠信因素，道德危險主要考慮家族遺傳因素","實質危險主要考慮正直意向因素，道德危險主要考慮高危職業或消閒活動因素"],a:0,e:"道德危險涉及一些較主觀的因素，實\n質危險考慮死亡發生率的客觀因素。\n與實質危險相比，道德危險較難確定"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","所有類別人壽保單","投資相連壽險計劃（“投連壽險”）保單"],a:3,e:"就保監局發出的指引28投資相連壽險\n計劃（“投連壽險”）保單可由獲授\n權保險人選擇是否發出有效利益說明"},{c:"5",s:"就人壽保險而言，判斷一項可保性的基本因素可能是",o:["準投保生命的性別","準投保生命的年齡","準投保生命的健康狀況","較大的投保額"],a:2,e:"就人壽保險而言，判斷一項可保性的\n基本因素可能是準投保生命的健康狀\n況"},{c:"5.2.6a",s:"保險計劃建議書根據甚麼預期保費抵銷?",o:["預期所有的現金紅利購買減額清繳保險","每年支付的均衡保費","對未來的投資表現有利","以上各項皆不是"],a:2,e:"保險計劃建議書根據預期所有的現金\n紅利購買減額清繳保險以作保費抵銷"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個近期曾發出\n新保單的產品系列的非保證紅利/英式紅利實現率是怎樣計算的?",o:["某個產品的實現率是指按「實際派發的保證紅利」除以銷售時「利益說明所述數額」的平均數計\n算。","某個產品的實現率是指按「實際派發的非保證紅利/英式紅利」除以銷售時「利益說明所述數額\n」的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所承諾數額」的總額計算\n。"],a:1,e:"某個產品的實現率是指按「實際派發\n的非保證紅利/英式紅利」除以銷售時\n「利益說明所述數額」的平均數計算\n。"},{c:"5.2.8",s:"根據《承保長期保險業務類別C業務除外）指引》(指引16)，當銷售分紅（或有利潤）長期保單時\n，必須告知客戶",o:["過往的投資表現非分紅產品未來表現的指標","過往的紅利派發表現並非分紅產品未來表現的指標","過往的紅利派發表現僅指非分紅產品未來表現的指標","保險人不是承擔任何投資風險"],a:1,e:"根據指引16，當銷售分紅（或有利潤\n）長期保單時，必須告知客戶過往的\n紅利派發表現並非分紅產品未來表現\n的指標"},{c:"5.2.7a",s:"就保單紅利的派發而言,什麼是匯集基金?",o:["它是指相關的保險人隨著提供了分紅保單而在其資產負債表上顯示出來的資產的全部,而之後保\n險人須為這些保單管理該等資產","它是指相關的保險人隨著經營一切類型的長期保險業務而在其資產負債表上顯示出來的資產的全\n部","它是指相關的保險人隨著提供了分紅保單而在其保費收入的全部顯示出來的資產的全部","它是指相關的保險人隨著提供了分紅保單而在已扣除日常開支的保費收入的全部顯示出來的資產\n的全部"],a:0,e:"所謂「匯集基金」是指相關的保險人\n隨着提供了分紅保單而在其資產負債\n表上顯示出來的資產的全部，而之後\n保險人須為這些保單管理該等資產"},{c:"5.2.7c",s:"相對投資相連保單，分紅保單的好處是︰",o:["高透明度保險制度","保單價值由精算師監管","較投資相連保單風險低","靈活性"],a:2,e:"相對投資相連保單，分紅保單的好處\n是保單承受的風險較低"},{c:"5.3.2",s:"通常或曾經對投保人提供醫療護理的醫生或其他合格醫務人員被稱為",o:["護理醫生","主診醫生","體檢醫生","機密醫生"],a:1,e:"主診醫生是通常或曾經對投保人提供\n醫療護理的醫生或其他合格醫務人員"},{c:"5.5.1",s:"在人壽保險合約中，以下哪項是不大可能是常見的更改",o:["保單保障的類型","受保生命的身份","受益人","以上沒有一項不大可能是常見更改"],a:1,e:"在人壽保險合約中，受保生命的身份\n不大可能是常見的更改"}],"paper3-2025-12":[{c:"1.2.2(b)",s:"就最高誠信原則，在免體檢的投保的前題下，以下哪項不屬違反最高誠信的情況?",o:["沒有披露未被驗出的腦瘤","沒有披露近日收到高利貸債主的死亡恐嚇","隱瞞自己從驗身得知的癌症","隱瞞自己意外導致嚴重受傷"],a:0,e:"有些疾病對合資格醫生而言可能很容\n易察覺，但是不能期望一般人也能夠\n進行自我診斷並作披露。"},{c:"1.3.2b(a)",s:"人壽保險費率的均衡保費制度是指在保險期內，每年所繳的保費相同， 並假設",o:["利率沒有大幅度下降","死亡保險金維持不變","經濟環境保持合理平穩","保險人的賠償經驗仍可接受的"],a:1,e:"人壽保險費率的均衡保費制度是指在\n保險期內，保費不變，同時死亡保險\n金亦維持不變。"},{c:"1.3.2a",s:"下列哪項屬於自然保費制度的特點？",o:["保費隨年齡增長而增加","會產生逆選擇","大部份保險公司已不採用","以上各項皆正確"],a:3,e:"以上各項都屬於自然保費制度的特點"},{c:"1.3.1a",s:"以下哪項關於死亡表的描述是正確的?\ni. 顯示不同年齡的預期死亡比率的計算表\nii. 應付所有預期及可能出現的營運開支\niii. 考慮某種新疾病或其他災難引起異常死亡率的可能性\niv. 只應付正常風險和正常預期的死亡率",o:["i, iii","i,iv","ii,iv","以上各項皆是"],a:1,e:"死亡表或稱生命表顯示不同年齡的預\n期死亡比率的計算表，在保險行業中\n十分通用。利用死亡表釐定費率，只\n是應付正常風險和正常預期。所以只\n有選項i及iv是正確"},{c:"1.2.1(h)",s:"在人壽保險中，只有在合約開始時才需要可保權益，以下哪項情況會出現有效索償?",o:["夫妻於離婚前，為其配偶的生命購買人壽保單","債務清還前，就債務人的生命購買人壽保單","關鍵人物人壽保單，受保僱於保單起保數天後離職","以上各項例子"],a:3,e:"人壽保險的可保權益只有在合約開始\n時才需要，就以上的關係轉變，仍然\n維持該保單的有效性"},{c:"1.2.1(h)(iii)",s:"以下哪項有關壽險保單轉讓與可保權益法律規定的關係的陳述是正確？",o:["保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者","保單所有人一般可以將正當地安排的人壽保險合約轉讓給第三者，即使該第三者對受保生命缺乏\n可保權益","保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者","準保單所有人意圖向一受保生命購買一份壽險合約，但卻與受保生命缺乏可保權益，他大可以安\n排後者購買保單自保生命後轉讓給他，而成為轉讓保單的合法所有人"],a:1,e:"保單所有人一般可以將正當地安排的\n人壽保險合約轉讓給第三者，即使該\n第三者對受保生命缺乏可保權益仍可\n作出保單轉讓"},{c:"1.2.2",s:"下列哪項肯定屬於投保人必須披露的重要事實",o:["與實質物件(財產)的保險有關的事實","會影響一名審慎的保險人訂定保費或決定是否承擔風險方面判斷的事實","可能影響一名審慎的核保人就一項特定風險釐定保費的判斷的事實","被保險人向保險人披露的重要事實"],a:1,e:"重要事實是會影響一名審慎的保險人\n訂定保費或決定是否承擔風險方面判\n斷的事實"},{c:"1.2.2(e)",s:"以下哪項為最高誠信的正確描述？\ni. 就某些不可異議條文，保險人不得在保單生效了一段時訂明時間內對該份保單提出異議或質疑\nii. 就免體檢的投保，一份小心設計的投保單是很重要\niii. 在不構成欺詐的情況下，若受保生命違反最高誠信在可異議期間後才可獲得寬宥\niv. 要求投保人披露所有重要事實，不管保險人有沒有提出要求",o:["ii,iii,iv","i,ii,iv","i,ii","iii,iv"],a:3,e:"就不可異議條文，保險人可以在保單\n生效了的兩年內對該份保單提出異議\n或質疑，就免體檢的投保，一份小心\n設計的投保單未必很重要"},{c:"1.1",s:"人壽保險最初的目的為",o:["為退休後支付每個月的生活費","向被保險人的家屬提供幫助","為一名海上死亡的船員提供保障","應付短期債務之用"],a:1,e:"人壽保險的最初及最基本目的是，\n在被保險人或稱受保人去世後，尤其\n在早逝的情況下，很大可能會給受養\n人帶來經濟困難，人壽保險利益可向\n被保險人的家人或其他人提供幫助。"},{c:"1.1",s:"人壽保險最初及最基本的目的，在現代社會也有這樣的保障保險(定期壽險)是什麼？",o:["死亡(尤其在早逝的情況下)","為受保人在生的每一年提供生活收入","儲蓄","在餘下生命裏提供保障"],a:0,e:"最初，保險單有效期較短，只為暫時\n性的風險情況"},{c:"1.3.1",s:"按照壽險傳統保費計算方法，保費應該可應付所有有關成本，並可反映有關之風險，描述有關之保\n費標準為",o:["公平及公正的","公平及足夠的","充足及公平（公正）的","充足及合適的"],a:2,e:"按照壽險傳統保費計算方法有關之保\n費標準為充足及公平（公正）的"},{c:"1.3.1a",s:"在人壽保險保費的一般計算中，在正常統計預期下足夠支付死亡索償所需，向保單所有人收取的金\n額是以下哪一種保費",o:["實收保費","淨保費（純保險費）","毛保費","充足及公平的保費"],a:1,e:"在正常統計預期下足夠支付死亡索償\n所需向保單所有人收取的金額是淨保\n費（又叫純保險費）"},{c:"1.3.2b&c(ii)",s:"可作為保單抵押貸款的抵押物是",o:["銀行中的存款","保單的現金價值","保單所有人所持有的財產","以上各項都是"],a:1,e:"可作為保單抵押貸款的抵押物是保單\n的現金價值"},{c:"2.1.1a",s:"相比於終身壽險及儲蓄壽險，以下哪項有關定期壽險的描述是正確的？",o:["保費是最便宜的","大多數情況下，在保單到期時仍未出現索償","只提供短暫的保障","上述所有各項"],a:3,e:"上述所有各項都是定期壽險的正確的\n描述"},{c:"2(b)",s:"下列哪項屬於基本形式之壽險保單的常見變化？\ni)保單所有人可以選擇將保單紅利轉換為公司股份\nii)如果最初只投保一段有限時間，可能可以續保\niii)保單所有人可以選擇將保單紅利轉換為公司優先股\niv)保單可加入各種附約，用以改善所提供的保障",o:["i, ii","iii, iv","ii, iv","i, ii, iii, iv"],a:2,e:"可續保的及可轉換的是人壽保險的基\n本變數"},{c:"2.1.1b",s:"就可續保定期壽險而言，以下哪一個說法不正確?",o:["保費將會隨受保生命的年齡的增長而增加","新保費是按照到達年齡來計算","續保的權利已存在毋須提交可保性證明","以上各項皆不是"],a:3,e:"因為以上各項皆是可續保定期壽險的\n正確描述，所以答案D是正確答案。"},{c:"2.1.2(d)",s:"儲蓄壽險在香港並不流行，你認為原因何在？",o:["佣金率比較低","對於投保的普羅大眾，這種壽險一般較難了解","它比較貴","其實儲蓄壽險比定期壽險和終身壽險更流行"],a:2,e:"儲蓄壽險在香港並不流行，因為保費\n較貴，這是跟實務知識不相同。"},{c:"2.2.1(b)",s:"萬用壽險增加或減少保額",o:["必需提交可保性證明","如增加保額，需提供可保性證明","如減少保額，需提供可保性證明","如增加保額後第二年後提出索償，該次索償則屬無效"],a:1,e:"萬用壽險如增加保額，需提供可保性\n證明"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"延期年金計劃在累積期內，保單持有\n人在一段時間內定期繳付保費，讓保\n險人通過投資令已付金額增長"},{c:"2.3.1(b)",s:"合資格延期年金保費容許夫婦合共申請扣除總額上限是多少?",o:["60000","80000","120000","200000"],a:2,e:"合資格延期年金保費容許夫婦合共申\n請扣除總額上限是12萬"},{c:"2.1.1a",s:"當受保人去世時，賠償會直接向貸款人償還貸款餘額，這是什麼類型的保險？",o:["遞增定期壽險","信用壽險","家庭收入壽險","抵押贖回壽險"],a:1,e:"如果借款人在未完全償還欠款之前死\n亡，信用壽險直接向貸款人支付貸款\n結欠"},{c:"2.1.1a(b)",s:"丈夫和妻子以聯名形式購買了抵押贖回保險保單，丈夫不幸去世後，賠償金會給付",o:["妻子","銀行","他們的子女","貸款機構"],a:0,e:"以聯合壽險方式提供保障的壽險保單\n承保兩人夫婦兩人的生命，\n不論哪一位最先或最後死亡\n，保單於此 時支付保險利益。"},{c:"2.1.1b(a)",s:"下列哪項對於可續保定期壽險的描述是正確的?",o:["在續保時,其保費增加以反映其年齡之提高","在續保時,其保額只可相同或小於其原有保障額","於續保時,無須提供可保性證明","以上所列各項"],a:3,e:"以上各項皆是可續保定期壽險可續保\n定期壽險的正確描述"},{c:"2.1.1b(b)",s:"駱先生大學畢業不久，沒多少錢可以用於買人壽保險，然而將於明年結婚。為什麼你認為他應該考\n慮購買可轉換定期壽險？",o:["可轉換定期壽險的保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單\n轉為永久計劃","可轉換定期壽險給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單轉換為更便宜的\n計劃","可轉換定期壽險保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單轉\n換為聯合壽險計劃","對年不過三十的人來說，可轉換定期壽險最適合不過"],a:0,e:"可轉換定期壽險保單所有人提供一個\n轉換特權，在毋須提供可保性健康證\n明的情況下將保單轉換為永久計劃的\n權利"},{c:"2.1.3",s:"一份不分紅終身壽險",o:["只會於指定期間結束時才給付保單利益","就不論甚麼時間出現的死亡，均會給付保額","於受保生命仍然在世期間給付指定的利益","只會就指定期間內出現的死亡給付保單利益"],a:1,e:"一份不分紅終身壽險就不論甚麼時間\n出現的死亡，均會給付保額"},{c:"2.1.3(a)",s:"一份人壽保險單如稱為「連續繳費終身壽險單」，則意味著",o:["受保人只需繳付一份保費","在保險期內保費不變","在限定期間受保人在去世後，仍需繳付保費","受保人須終身繳付保費"],a:3,e:"純粹壽險是指受保生命在世期間終身\n繳付保費，亦可稱為「連續繳費終身\n壽險單，亦是終身壽險的別稱，"},{c:"2.2.1",s:"下列哪項關於萬用壽險的陳述是不正確的?",o:["具有分別列示各定價因素的定價","保費靈活,可以於某一年完全不繳付保險費","一種非常複雜的產品,它為保單所有人提供極大的自由度","無須要提供可保性證明,可要求增加或減少保險利益"],a:3,e:"萬用壽險就任何增加保險利益的情況\n都可能須要提供可保性證明"},{c:"2.2.2(c)",s:"絕大部分的單位相連保單是終身壽險和下列哪種",o:["定期壽險","儲蓄壽險","純生存壽險","遞減定期壽險"],a:1,e:"絕大部分的單位相連保單是終身壽險\n和儲蓄壽險"},{c:"2.3",s:"年金利益款項給付予?",o:["收款人","保單受益人","保單持有人","年金購買人"],a:0,e:"年金利益款項給付予收款人"},{c:"2.3",s:"以下哪項對年金的描述是正確的？",o:["女性不可以購買年金","女性的保費比相同情況下的男性保費為低","向男性支付年金金額低於向女性支付的年金金額","向女性支付年金金額低於向男性支付的年金金額"],a:3,e:"因為女性的預期壽命比同齡男性長，\n所以向女性支付年金金額低於向男性\n支付的年金金額"},{c:"2.3.1(a)",s:"一種以整付方式購入，並且於一個年金期間屆滿後便開始支付年金利益款項的年金合約稱為；",o:["即時年金","特快年金","即期年金","連續年金"],a:2,e:"即期年金是一種以整付方式購入，並\n且於一個年金期間屆滿後便開始支付\n年金利益款項的年金合約"},{c:"2.4(c)",s:"以下哪項有關供款式團體保險計劃是正確的？",o:["僱員無須分擔保費","僱主無須分擔保費","僱主及僱員無須分擔保費","僱主及僱員雙方須分擔保費"],a:3,e:"供款式團體保險計劃是僱主及僱員雙\n方須分擔保費"},{c:"2.4(g)",s:"就團體人壽保險而言，其中一位合資格被保險人起初拒絕參加保險計劃，後來又想加入，以上的情\n形是？",o:["沒有可能加入","不需任何手續就可加入","只有繳付己過期但未繳清的保費才可","可以加入，但有可能需要出示可保性證明"],a:3,e:"就團體人壽保險而言，其中一位合資\n格被保險人起初拒絕參加保險計劃，\n後來又想加入，是可以的，但有可能\n需要出示可保性證明"},{c:"3.4.1(iii)(7)",s:"以下哪項是自願醫保計劃下標準計劃靈活計劃中，基本保障，額外保障及其他保障的定義原則?\n1. 標準計劃 - 基本保障:必須包括，額外保障:不可包括，其他保障 : (1)\n2. 靈活計劃 - 基本保障:必須包括，額外保障: (2)，其他保障 : (3)",o:["(1)不可包括,(2)必須包括,(3)可選擇包括或不包括","(1)必須包括,(2)必須包括,(3)可選擇包括或不包括","(1)可選擇包括或不包括,(2)必須包括,(3)可選擇包括或不包括","(1)可選擇包括或不包括, (2)必須包括, (3)不可包括"],a:2,e:"詳細可參閱研習資料手冊參考章節\n3.4.1(iii)(7)自願醫保標準計劃和靈\n活計劃定義原則說明表格"},{c:"3.2.2",s:"附加於人壽保單的意外死亡及喪失肢體附約，有時會賠付超出意外死亡保險利益及其他保險利益，\n以下哪項是適用的保障範圍?\n(i) 嚴重燒傷，可獲支付指明金額\n(ii) 每周津貼，最長為52周\n(iii) 住院津貼，每日津貼上限為 1,000日\n(iv) 因乘搭一般公共交通工具引果傷殘可獲「雙倍賠償」",o:["i,ii","ii,iii","ii,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是意外死亡保險利益附約\n所提供的其他保險利益"},{c:"3.2",s:"意外死亡及喪失肢體(AD&D)附約，近因原則對這種附約顯得非常重要，原因是",o:["不適用於危疾保單","只有被保險人因意外死亡才有會給付雙倍賠償利益","每索償賠付，都會是保單基本保單保額的兩倍","就一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付"],a:1,e:"就意外死亡及喪失肢體(AD&D)附約而\n言，只有被保險人因意外死亡才有會\n給付雙倍賠償利益，所以近因原則(死\n亡原因)對這種附約顯得非常重要"},{c:"3.4.2",s:"以下哪項屬醫療保險業務指引的目的適用範圍?",o:["個人及團體業務","自願醫保認可產品","其他種類醫療保險業務","以上各項皆是"],a:3,e:"所有醫療保險業務指引適用於所有醫\n療保險業務"},{c:"3.1.2",s:"以下哪項不是殘疾收入附約的常用條款?",o:["預期健康狀況","應付金額","等候期","並非貸款或預繳"],a:0,e:"預期健康狀況不是殘疾收入附約的常\n用條款"},{c:"3.1.1(a)",s:"以下哪項或哪些有關「豁免保費」附約的支付利益準則描述是正確的？",o:["受保保單所有人在變成完全傷殘時必須維持達到某段時間然後死亡","受保保單所有人在變成完全傷殘時必須已經有部份殘疾達到某段時間","受保保單所有人必須在保單有效期內完全傷殘且達到某段時間, 稱為 「等候期」","以上所有各項均不屬於豁免保費附約支付利益的準則"],a:2,e:"受保保單所有人一旦根據保單的定義\n完全傷殘達最低期限（通常為三或六\n個月）他將獲豁免支付續保保費。一\n經開始，豁免會於保單的有效期內繼\n續下去，一直到相關傷殘結束為止。"},{c:"3.1.1(a)",s:"下列那兩項對殘疾豁免保費的描述是不正確的？\ni.從保單所有人遭受到殘疾起計至等候期完結後，保費才開始被豁免\nii.從保單所有人遭受到殘疾之時計起，保費才開始被豁免\niii. 等候期通常是三個月或六個月\niv. 保單所有人的年齡是沒有限制的",o:["i 及 ii","ii 及 iv","iii 及 iv","i 及 iv"],a:1,e:"豁免一般只限於指明年歲範圍內開始\n的傷殘，比如15至65歲。受保保單所\n有人一旦根據保單的定義完全傷殘達\n最低期限（通常為三或六個月）他將\n獲豁免支付續保保費。選項ii 及\niv不正確"},{c:"3.2.1",s:"意外死亡保險利益附約支付利益的準則,死亡必須於?",o:["意外身體受傷後一段指定時間內發生","有關基本計劃須包含豁免保費附約","在受保保單所有人昏迷時死亡","即時死亡"],a:0,e:"意外死亡保險利益附約支付利益的準\n則，死亡必須由意外身體受傷而直接\n引起， 並與所有其他原因無關並\n於該受傷的一年之內發生"},{c:"3.3(c)",s:"根據提前支付死亡保險利益條款，在某些嚴重的情況下，縱使死亡並未發生，保單所列明的死亡金\n是可以支付給保單所有人，但",o:["受益人/承讓人必須簽署棄權聲明","受益人同樣可以取回所有索償","受益人如果在受保人死後兩年內便可獲取所有索償","受益人只可取回保費"],a:0,e:"由於向在世的受保保單所有人發放保\n險利益會對保單受益人的期望造成一\n定的影響，因此有些保險人會於處理\n此類附約的給付申請時，要求受益人\n簽署一份棄權聲明或稱解除責任憑證\n，同意提前支付的保險利益數額會從\n將來的死亡保險金中扣除。"},{c:"3.3.1",s:"以下哪項是危疾保險利益的賠償限制?\ni. 被診斷患上指明疾病\nii. 被診斷患上終末疾病並只有18個月或更短的壽命\niii. 有必要接受指明的醫療程序\niv. 僅適用60歲或以下的受保人",o:["i,ii","i,iii","ii,iii,iv","i,iii,iv"],a:1,e:"危疾保險利益的賠償限制被診斷患上\n終末疾病並只有12個月或更短的壽命\n，危疾保障僅適用於某歲數（如\n80歲）或以下的人，只有選項i,iii是\n正確"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認\n可的個人償款住院保險產品，供消費\n者自願選購，團體保險並不適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫\n療服務的消費者提額外的保險計劃選\n擇"},{c:"3.5.1",s:"保證可保利益在某些情況下亦稱為",o:["終身保證利益","預批購買選擇","終身可保選擇","保證受保利益"],a:1,e:"保證可保利益在某些情況下亦稱為預\n批購買選擇"},{c:"3.1.1",s:"以下哪項不是(WP)附約的描述？",o:["(WP)是”waiting period”的縮寫，意指「等候期」","(WP)是”waiver of premium”的縮寫，意指「殘疾豁免保費附約」","被保險保單所有人須要完全傷殘，才可獲權益","受到特定年齡所限制"],a:0,e:"(WP)是Waiver of\nPremium的縮寫，意指「殘疾豁免保費\n附約」，而不是waiting\nperiod”「等候期」的意思"},{c:"3.1.2",s:"如果人壽保單收到殘疾收入附約約束,並且受保生命遭遇殘疾,而現正提供收入",o:["該收入通常以每月形式支付","其基本保障會暫時停止","所支付金額會於死亡保障額中扣除","此類保障通常並不設有等候期"],a:0,e:"殘疾收入等候期由一個月至六個月不\n等，所支付的利益並非貸款或預繳，\n不會於死亡保障額中扣除，殘疾收入\n附約如名稱所示，則在完全殘疾期間\n提供收入"},{c:"3.1.2",s:"把「豁免保費附約」及「殘疾收入附約」比較時",o:["兩者皆無分別","豁免保費附約受等候時間所限","豁免保費附約在完全殘疾期間提供一項收入","殘疾保險利益在完全殘疾期間提供一項收入"],a:3,e:"把「豁免保費附約」及「殘疾收入附\n約」比較時，殘疾保險利益在完全殘\n疾期間提供一項收入"},{c:"3.1.2",s:"根據「殘疾收入附約」所支付的收入保險利益",o:["會從最後的死亡保險金扣除","不會從最後的死亡保險金扣除","會從未來的紅利扣除","實質上是一種利用額外保費償還的貸款"],a:1,e:"「殘疾收入附約」所支付的收入保險\n利益不是預繳或貸款，不會從最後的\n死亡保險金扣除"},{c:"3.2.1(b)",s:"根據意外死亡及喪失肢體附約中，「喪失肢體」是指?",o:["嚴格地指喪失雙臂","必須喪失一雙肢體(雙臂或雙腿)","往往適用於單目失明(同時適用於喪失肢體)","可用於雙目失明"],a:2,e:"在意外死亡及喪失肢體附約中，「喪\n失肢體」包括喪失肢體及喪失視力的\n意思"},{c:"3.3",s:"提前支付死亡權益附約可附加在人壽保險單中，以下哪項描述是正確的？",o:["只適用於分紅保單","只適用於保障額較少的保單","只適用於保障額較大的保單","在是次申請，必須經過第二次體檢"],a:2,e:"為了降低行政成本，這種附約往往只\n准附加於保額相當大的保單。"},{c:"3.3.1",s:'危疾保險利益中"指明疾病"指:\ni. 傷殘\nii. 心臟相關疾病\niii.癌症\niv. 重要器官相關疾病',o:["i,ii, iii","ii,iii, iv","i,ii, iv","i,ii,iii ,iv"],a:3,e:'以上都可以是危疾保險利益中"指明疾\n病"'},{c:"3.5.1",s:"有關保證可保選擇，容許受保人作出購買增額保障的選擇，以下那項描述是不正確的?",o:["自動獲得增額保障的選擇","如不及時作出選擇，便會喪失權利","部分保險人於備擇日期內提供定期壽險","只可在指定限期內作出選擇"],a:0,e:"保單所有人如果錯過了行使已觸發的\n選擇權以購買增額保障的話，就會喪\n失該次權利，答案A不正確"},{c:"3.5.1(c)",s:"保證可保利益",o:["保單所有人有權在指定的備擇日期購買增額保險","備擇日期沒有作出購買增額保障的選擇，就會喪失該項約定的權利","增額保險的金額不能超過原有保單的面額","以上各項皆是"],a:3,e:"以上各項皆是保證可保利益的限制"},{c:"3.5.1(f)",s:"如保險已加有豁免保費及預批購買選擇附約，而保單所有人在可以行使購買權時發現遭致傷殘，在\n此情況下，下列哪項為正確？",o:["預批購買選擇會被取消","豁免保費附約會被取消","豁免保費及保證可保利益附約會被取消","可自動獲得該額外保障，豁免保費附約也可以豁免所有保費"],a:3,e:"受保保單所有人在有權行使購買增額\n保險選擇權時已經成了殘疾人，他將\n會自動獲得該項額外保障。並豁免保\n費，直至受保保單所有人康復或死亡"},{c:"4.9",s:"對於一個保單所有人來說，對保險合約的權益也可形容為「復歸的」 ，即是說",o:["仍未取得該項權益","肯定會在將來取得該權益","保單所有人對該合約的權益獲得承認，但他尚未能實際享用該項權益","該權益可以轉讓給其他人"],a:2,e:"「復歸的」權益是指保單所有人對該\n合約的權益獲得承認，但他尚未能實\n際享用該項權益"},{c:"4.5",s:"以下哪項不屬於人壽保險的不能作廢條款，保單的持有人可以作出的選擇?",o:["中止保單時獲付退保現金價值","取回已經支付的保費","利用淨現金價值作為整付保費購買減額清繳保險","以上各項皆不是"],a:1,e:"取回已經支付的保費不屬於人壽保險\n的不能作廢條款下的選擇"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保\n單，保單的持有人決定不再繳付任何\n保費有權選取的選擇"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["保險人有權選擇賠付方法","通常是整筆過支付","用利益購買年金","將收益保留在保險人處以賺取利息"],a:0,e:"只有保單持有人或受益人有權選擇賠\n付方法，答案A不屬於壽險保單的賠付\n選擇"},{c:"4.8",s:"就誤報年齡或性別方面，人壽保險單通常",o:["也適用於自願變性的情況","只容許保單利益向上調整","只容許保單利益向下調整","試圖改變保單條款至以符合應有情況"],a:3,e:"若事實與安排保險時所說明的年齡或\n性別不相同，這可能對保費及／或保\n險利益產生顯著影響。"},{c:"4.1",s:"以下哪項關於「完整合約」條款的描述是正確的？",o:["在人壽保險索償時毋需出示保單的正本","除非得到保單所有人的同意，否則不能對保險合約作出任何修改","保險公司的指定高級職員有權對保單作出更改","保單的內容已是一份完整的合約，並不包括其他文件"],a:1,e:"「完整合約」條款其中一個定義是，\n除非得到保單所有人的同意，否則不\n能對保險合約作出任何修改"},{c:"4.4(c)",s:"黃生就自身生命購買壽險保單，自己為受保人，並指明他最小的兒子為該保單受益人，根據《已婚\n者地位條例》，此舉起了甚麼的法律效用?",o:["該受益人成為該保單的法定保單所有人","該受益人成為該保單的法定保單所有人，直至黃先生修訂其他受益人為止","信託效用並不用適指定子女成為受益人","該受益人成為該保單的實益擁有人"],a:3,e:"根據《已婚者地位條例》，保單持有\n人如為其配偶及或其任何子女的利益\n而購買壽險單，將達到建立一個（法\n定信託的效用，從而令該配偶及或子\n女成為該保單的實益擁有人。"},{c:"4.5",s:"以下哪項是不能作廢條款的常規規定?",o:["保單所有人可中止保單時獲付退保現金價值","保單不會因為中斷繳付保費而失效，除非收到相反指示，否則保單的現金價值會被用作支付到期\n保費直至用完為止","利用淨現金價值作為整付保費，購買與原保額相同的定期壽險","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽保險"],a:1,e:"常規的不能作廢條款則規定是保單不\n會因為中斷繳付保費而失效。除非收\n到相反指示，否則保單的現金價值會\n被用作支付到期保費直至用完為止，\n以保持保單全額有效。"},{c:"4.7",s:"若要把已失效的人壽保單復效，以下哪項不是復效條件?",o:["繳一筆復效費","保險人書面同意","繳付已到期而未繳清的保費及利息","提供可保性證明"],a:1,e:"保險人書面同意不是人壽保單復效條\n件"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許\n藉訂明手續來轉讓據法權產"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，\n擬轉讓的據法權產須屬現時的，而非\n未來的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許\n藉訂明手續來轉讓據法權產，而對保\n險合約的權益屬於據法權產。"},{c:"4.9",s:"對於一個保單所有人來說，如果他對產權的權益是復歸的，那",o:["仍未取得該項權益","雖然對產權有獲得認可的權益，財產的享用將延遲至將來的某一天或某事發生時","肯定會在將來取得該權益","該權益屬於受益人權益"],a:1,e:"復歸的權益是指對產權有獲得認可的\n權益，財產的享用將延遲至將來的某\n一天或某事發生時"},{c:"4.2",s:"按照香港普遍採用的「不可異議條款」，儘管違反「最高誠信原則」(假設按照香港法律)，保險人\n對以下哪項仍不可能拒絕有關之死亡索償？",o:["保單生效了只有一年","保單生效了20個月,但死亡6個月後才向保險人索償","保單生效了4年，違反最高誠信原則涉及故意隱瞞有重要意義的的醫療資料","保單生效了4年，違反最高誠信原則涉及到沒有披露重要資料，而投保人真誠地認為此資料是無\n關的"],a:3,e:"不可異議條款規定，保險合約於受保\n生命在世時從保單發出日起計已生效\n了兩年後，保險人不會對該合約提出\n異議或質疑，答案D的情況保險人仍不\n可能拒絕有關之死亡索償"},{c:"4.2",s:"不可異議條款規定保險人不能對保單有效性提出異議，該可異議期為",o:["十二個月","三個月","二年","一個月"],a:2,e:"不可異議條款規定保險人不能對保單\n有效性提出異議，該可異議期為兩年"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["該期間一般最少30或31天","它不適用於保單的首期保費","於寬限期內繳付保費可維持保單的保障繼續有效","於寬限期內繳付保費須另外繳付利息"],a:3,e:"於寬限期內繳付保費須被視為準時繳\n交"},{c:"4.5",s:"根據壽險保單中常見的不能作廢條例，下列哪一項不屬於決定不再繳付任何保費的保單所有人的選\n擇?",o:["退保並收取保單現金價值","利用保單價值作為保費，接受一份減額清繳保險","利用現金價值購買與原本保單保額相同的定額壽險","暫停保障，但有權在任何時間恢復保險"],a:3,e:"暫停保障，但有權在任何時間恢復保\n險不屬於決定不再繳付任何保費的保\n單所有人的選擇"},{c:"4.6",s:"如果抵押貸款在投保生命死亡時仍未清還，那麼",o:["有關的死亡索償便會無效","有關的保險人可豁免該筆保費的償還","受益人於支付該保險利益前,要先繳清該筆貸款","有關的抵押貸款及相關的利息會在保單利益中扣減"],a:3,e:"如果抵押貸款在投保生命死亡時仍未\n清還，有關的抵押貸款及相關的利息\n會在保單利益中扣減"},{c:"4.6",s:"下列哪項屬於保單抵押貸款中不大可能是正確的?",o:["該筆貸款用途無任何限制","該筆貸款唯一需要的抵押品就是保單的現金價值","若是意外死亡，不須償還該筆貸款","貸款金額須在受保生命死亡時在保額內扣除"],a:2,e:"保單抵押貸款貸款金額須在受保生命\n死亡時在保額內扣除，不論任何原因\n身故，答案C不正確。"},{c:"4.8",s:"如果保單於提出索償時，才發現有關受保生命的真實年齡較保單顯示的為高",o:["保單自動無效","調整利益，支付比保單較低的保額","調整利益，支付比保單較高的保額","維持保額不變，退回多繳的保費"],a:1,e:"如果保單於提出索償時，才發現有關\n受保生命的真實年齡較保單顯示的為\n高，即是出現少交保費的情況，保險\n人會調整利益，支付比保單較低的保\n額"},{c:"4.10",s:"如保單所有人沒有註明紅利的選擇，保險人會自動為保單所有人將紅利存放以賺取利息或",o:["以現金支付","用以繳付未來保費","用以購買清繳增額保險","購買一年期的定期壽險"],a:2,e:"購買清繳增額保險及紅利存放保險人\n以賺取利息屬自動紅利選擇"},{c:"4.11",s:"下列哪項或哪些屬於壽險保單的賠付選擇？",o:["即時整筆支付","受益人逝世時整筆支付","投資於有關保險公司的股份","以上所有各項"],a:0,e:"上述只有即時整筆支付死亡保險利益\n屬於壽險保單的賠付選擇"},{c:"4.11",s:"在理賠時，下列那種方法不是常用的？",o:["整筆支付","以定期定額支付","定額支付","以有關公司的股份支付"],a:3,e:"以有關公司的股份支付不是常用的理\n賠選擇"},{c:"4.12",s:"壽險保單中的自殺條款目的在於?",o:["阻止人們自殺","把所有涉及自殺的索償無效","避免本著自殺的念頭而購買的人壽保險生效","杜絕所有涉及自殺的索償的可能性"],a:2,e:"自殺除外責任條款是為防止有人藉自\n殺來取得保險金賠償，保險人採取一\n些防範措施，也絕對是合理的。"},{c:"5.2.7",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni. 保險人一般會將紅利平均派發，以減低短期大幅波動\nii. 紅利金額是基於獲委任精算師的意見\niii. 紅利金額是基於獲委任財務總裁的意見，並經精算師批准而釐定\niv. 保險人一般保留釐定紅利金額的權利",o:["i,ii","ii,iii,iv","i,ii,iv","ii,iii"],a:2,e:"紅利派發金額視乎匯集基金的業績情\n況而定，保險人一般保留釐定紅利金\n額的權利。實務上，紅利金額是基於\n獲委任精算師的意見，並經各董事會\n批准而釐定的。選項iii不正確，正確\n答案是C"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["提前提取保單費用","提前退保費用","紅利","冷靜期"],a:3,e:"參考章節5.2.10&附件M 冷靜期不屬《\n重要資料聲明書－內地人士在港投購\n人身╱壽險保單》涵蓋的部分，詳細\n研集資料手冊附件M"},{c:"5.2.1(b)",s:"以下哪項是處理人壽險保投保時是應注意的事項？\ni) 下一個(或上一個)生日年齡\nii) 投保人的身份\niii) 保單生效日期\niv) 投保人過去三年的職業紀錄",o:["i, iii","ii, iii(cid:9)","i,ii,iii","i,ii, iii, iv"],a:2,e:"投保人過去三年的職業不是處理人壽\n險保投保時是應注意的事項，選項iv\n不正確，正確答案是C。"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個近期曾發出\n新保單的產品實現率是怎樣計算的?",o:["實現率是指按「實際派發的保證英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算","實現率是指按「實際派發英式紅利」除以銷售時「利益說明所述數額」的平均數計算。","實現率是指按「實際派發的非保證英式紅利」除以銷售時「利益說明所述數額」的平均數計算","實現率是指按「實際派發的英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算"],a:2,e:"某個產品的實現率是指按「實際派發\n的非保證紅利／英式紅利」除以銷售\n時「利益說明所述數額」的平均數計\n算"},{c:"5.6.2",s:"以下哪項是一項法律原則容許法庭對有損害公眾利益或公共秩序的傾向的行為或交易，可予以廢除\n或不接受?",o:["程序不當","政策公正","公共政策","以上各項皆不是"],a:2,e:"在大部分情況下，如果證實殺人犯是\n受益人的話，法律\n「公共政策」是不會容許殺人犯本人\n獲益的"},{c:"5.3.1(a)",s:"人壽保險根據實質危險及道德危險核保確定有關風險程度，以下哪項因素是正確的描述?",o:["與實質危險相比，道德危險較難確定","實質危險涉及較主觀的因素，環繞準被保人的基本誠信或正直意向，道德危險主要考慮到可能增\n加受保事件發生率的","實質危險主要考慮誠信因素，道德危險主要考慮家族遺傳因素","實質危險主要考慮正直意向因素，道德危險主要考慮高危職業或消閒活動因素"],a:0,e:"道德危險涉及一些較主觀的因素，實\n質危險考慮死亡發生率的客觀因素。\n與實質危險相比，道德危險較難確定"},{c:"5.1.1(a)",s:"保險公司會計部的主要職能和責任包括：\ni) 記錄公司收入\nii) 監管公司支出\niii) 遵守(保費守則)\niv) 遵守(保險代理操守守則)",o:["i, ii","i, iii","iii,iv","ii,iii"],a:0,e:"遵守(保費守則)及遵守(保險代理操守\n守則)不屬保險公司會計部的職責，選\n項iii&iv不正確"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》根據以下哪項/些機構頒布的保險核心原則而制定？",o:["國際保險監督聯會","特區政府","保險監督聯合會","國際保險業聯會及國際保險監督聯會"],a:0,e:"《承保長期保險業務(類別C業務除外)\n指引》根據國際保險監督聯會頒布的\n保險核心原則而制定"},{c:"5.2.7a",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni.通貨膨脹期間保險人只會派發最低額的紅利\nii. 保險人一般保留釐定紅利金額的權利\niii.紅利金額是基於獲委任精算師的意見，並經董事會批准而釐定\niv.傳統分紅保單規定了上升的紅利率",o:["i , ii","ii, iii","ii,iv","i,ii,iii,iv"],a:1,e:"保險人一般保留釐定紅利金額的權利\n。紅利金額是基於各自的獲委任精算\n師的意見，並經各自的董事會批准而\n釐定的。只有選項ii,iii正確"},{c:"5.4.1(b)",s:"以下哪項保險種類會提供「保險憑證」及「成員登記卡」？",o:["終身保險","儲蓄保險","團體保險","以上皆不是"],a:2,e:"團體保單文件涉及總保單，\n為每位受保人提供保險憑證\n，還有成員登記卡。"},{c:"5.1.1(e)",s:"下列哪項不大可能屬於保單所有人服務部的職能？",o:["通訊","收取保費","索償處理","權益管理"],a:2,e:"索償處理屬理賠部負責"},{c:"5.2.2(a)",s:"人壽保險人透過簽發其中一種的保費收據，表示同意有關保險於投保時開始生效，但須於稍後證實\n投保人按照標準條款是屬於可保的。這種收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:2,e:"附條件保費收據須於稍後證實投保人\n按照標準條款是屬於可保的，有關保\n險於投保時開始生效"},{c:"5.2.2(b)",s:"立約保費收據有另一名稱，其中TIA全名為",o:["定期被接納保險 Term Insurance accepted","臨時保險證明 Temporary Insurance acknowledge","臨時保險協議 Temporary Insurance agreement","定期保險申請 Term Insurance application"],a:2,e:"立約保費收據有另一名稱，其中TIA全\n名為臨時保險協議 Temporary\nInsurance agreement"},{c:"5.2.9",s:"黃先生現年五十五歲，計劃六十歲退休，他請你提供壽險和投資上的意見，你覺得投資相連長期保\n險適合他嗎？",o:["需要視乎他的目標及適合情況，這是他可以選擇的選項","投資風險對他來說屬於相當高，故不建議投資相連長期保險給他","以他的年齡來說，傳統壽險會較適合","不建議投資相連保險，因為它是靈活性不適合一位五十五歲的人士"],a:0,e:"持牌保險中介人就任何合適的人壽保\n險保單作出建議前，須確保對各客戶\n的情況，包括需要、財務狀況、支付\n保費的能力及意願等作適當評估，及\n所作出的建議是建基於該評估，答案A\n正確"},{c:"5.3",s:"以下哪項或哪些說明是正確?",o:["壽險的核保工作是每個保單年度必須的工作","壽險的核保工作只涉及有關保費","核保涉及可保性和合約條款的修改","以上各項皆是"],a:2,e:"核保涉及可保性和合約條款的修改，\n通常人壽保險對個別風險的核保只能\n進行一次，只有答案C正確"},{c:"5.3.1",s:"核保包括兩類型。其一是技術性核保，這是將個別風險的潛在危機及預期危險進行評估。另一類是\n計算就同一受保生命已累積購買的保單金額及對建議的保險金額作出評估，此類核保稱為",o:["標準核保","實際風險核保","財務性核保","全面性核保"],a:2,e:"計算就同一受保生命已累積購買的保\n單金額及對建議的保險金額作出評估\n，此類核保稱為財務性核保"},{c:"5.3.1",s:"有時候合資格醫務人員所有的資料要進一步調查，保險公司除了向主診醫生索取醫療資料外，還可\n以向哪位索取",o:["護理醫生","體檢醫生","保險公司指明醫生","非主診醫生"],a:1,e:"有時候合資格醫務人員所提供的進一\n步資料是有必要的。這類調查的來源\n可以是主診醫生或體檢醫生"},{c:"5.3.2",s:"以下哪項或哪些原因需要主診醫生的醫療報告?",o:["所要求的保額十分高","已超過某指明的年齡","就投保書上所披露的某些健康資料作進一步調查","以上各項皆是"],a:3,e:"以上各項皆是需要主診醫生的醫療報\n告"},{c:"5.6.2",s:"就死亡索償提出時，死亡證明方式為",o:["死亡證明書正本","死亡證明書副本","受益人簽署證明","以上任何一項"],a:0,e:"就死亡索償提出時，死亡證明方式為\n死亡證明書正本"},{c:"5.6.2(d)(iv)",s:"如果一名客戶暗示，他正在考慮將本身的保單退保，保險中介人應採取以下哪項或哪些行動？",o:["有禮地詢問為何作出這個決定","小心地解釋保單退保的權利或影響","略述各種其他的可能選擇(如保單抵押貸款，清繳保障等)","以上各項皆是"],a:3,e:"以上各項皆是保險中介人處理保單退\n保時應採取的行動"}],"paper3-2025-08":[{c:"1.2.1",s:"以下哪項保險原則是彌償的引伸?",o:["披露責任","代位權","A&B","以上皆不正確"],a:1,e:"彌償有兩個引伸，即分擔及代位權。"},{c:"1.2.2(b)",s:"就人壽保險而言，如果未有披露以下哪種情況，則被視為違反最高誠信?",o:["未被驗出的腦瘤","投保人的體檢醫生未能驗出投保人的心跳不正常","沒有披露投保人於兒時多次罹患輕微的兒童疾病","以上各項皆不是"],a:2,e:"就最高誠信而言，保險人希望瞭解投保\n人所有已知的重要事實"},{c:"1.3.1",s:"釐定人壽保險保費的傳統標準是",o:["可負擔的","合理的","可計算的","公平的"],a:3,e:"釐定人壽保險保費的傳統標準是公平(\n公正)的，及充足的"},{c:"1.3.2(a)",s:"以下哪項不是影響保費率的主要因素？",o:["死亡率","利息","開支","發病率"],a:3,e:"發病率是影響保費率的其他因素"},{c:"1.2(h)(ii)",s:"債權人可就其債務人的生命投保。在債務得到償還後，會出現以下哪個情況？",o:["保單必定立即終止","債權人必須轉讓保單給債務人才繼續有效","仍然維持該保單的有效性，並在適當時候「再次得到償付」","以上答案均不正確"],a:2,e:"人壽保險的可保權益只有在合約開始時\n才需要，在債務得到償還後，仍然維持\n該保單的有效性"},{c:"1.1",s:"以下哪項為人壽保險最初的基本目的?",o:["為退休提供一筆資金","儲蓄","應付暫時的需要","退休安排"],a:2,e:"最初，保險單有效期較短，只為暫時性\n的風險情況"},{c:"1.2.1",s:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係要求的描述是正確的？\ni.就 某人的生命購買保險，對該受保生命必須具有可保權益。但透過轉讓程序購買別人的現有保\n單，對該受保生命無須具有可保權益\nii.保 單所有人不能將壽險合約轉讓予第三者，即使該第三者對受保生命具有可保權益\niii.保 單所有人可以把正當地安排的壽險合約轉讓予第三者，即使該第三者對受保生命缺乏可保\n權益\niv.保 單所有人只可將壽險合約轉讓予對該受保生命有可保權益的第三者",o:["i, iii","i, ii","i, iii, iv","ii, iii, iv"],a:0,e:"保單所有人可把正當地安排的人壽保險\n合約轉讓給第三者，即使該第三者對受\n保生命缺乏可保權益"},{c:"1.2.1",s:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係的陳述是正確的?\ni.為 某人的生命購買保險，必須具有可保權益。但購買別人的現有保單，則無須可保權益\nii.壽 險合約轉讓予第三者無須可保權益\niii.保 單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者\niv.保 單所有人需透過另外一份合約才可將壽險合約轉讓給第三者",o:["i, ii","i, iii","i, iii, iv","ii, iii, iv"],a:0,e:"保 單 所 有人可把正當地安排的人壽保險\n合約轉讓給第三者，即使該第三者對受\n保生命缺乏可保權益"},{c:"1.2.1(h)",s:"在人壽保險中，只有在合約開始時才需要可保權益，以下哪項情況會出現有效索償?",o:["夫妻於離婚前，為其配偶的生命購買人壽保單","債務清還前，就債務人的生命購買人壽保單","關鍵人物人壽保單，受保僱於保單起保數天後離職","以上各項例子"],a:3,e:"人壽保險的可保權益只有在合約開始時\n才需要，就以上的關係轉變，仍然維持\n該保單的有效性"},{c:"1.2.2(e)",s:"以下哪項為最高誠信的正確描述？\ni.就 某些不可異議條文，保險人不得在保單生效了一段時訂明時間內對該份保單提出異議或質疑\nii.就 免體檢的投保，一份小心設計的投保單是很重要\niii.在 不構成欺詐的情況下，若受保生命違反最高誠信在可異議期間後才可獲得寬宥\niv.要 求投保人披露所有重要事實，不管保險人有沒有提出要求",o:["ii,iii,iv","i,ii,iv","i,ii","iii,iv"],a:3,e:"就不可異議條文，保險人可以在保單生\n效了的兩年內對該份保單提出異議或質\n疑\n就免體檢的投保，一份小心設計的投保\n單未必很重要"},{c:"1.2.3(b)",s:"當發現死者就其生命購買了多於一份人壽保單，而每一份保單仍然生效，當作出賠付時",o:["只有最先購買的保單作出賠付","只有最高保額的保單作出賠付","每份保單對賠償都必須負責","應付保額為最高保額，而所有保險人分擔責任"],a:2,e:"人壽保險亦稱為利益保單，不可能超額\n賠償，因為人壽保險可保權益在大多數\n情況下是無限的"},{c:"1.1",s:"人壽保險合約最初類型",o:["本質上屬於短暫的，以保障早逝情況","本質上屬於長久的，即直至死亡","與物業抵押貸款有關","屬單位相連的安排"],a:0,e:"最初，保險單有效期較短，只為暫時性\n的風險情況"},{c:"1.2.1",s:"一名人士對另一人的生命具有一項權益，這權益在法律上賦予法定權利可就該人物的生命購買保\n險，這稱為",o:["可保權益","最高誠信","家庭保險權益","特別權益"],a:0,e:"可保權益是某人對某項保險標的在法律\n上被認可的一種關係，這種關係賦予他\n對該保險標的購買保險的權利。"},{c:"1.2.1(b)",s:"根據《保險業條例》第64b條指出，任何對受保生命沒有可保權益的保單均屬",o:["可使無效","無效","得不到保障的","正常的"],a:1,e:"根據《保險業條例》第64b條指出，任\n何對受保生命沒有可保權益的保單均屬\n無效的"},{c:"1.2.2(e)",s:"若違反人壽保險合約的最高誠信責任通常會令該合約變為可使無效。就香港的壽險保單而言",o:["這種情況在任何時候也適用","最高誠信的原則並不適用","違反最高誠信便會自動令該合約變為無效","保單的不可異議條款可能改變這種情況"],a:3,e:"就不可異議條文，保險人可以在保單生\n效了的兩年內對該份保單提出異議或質\n疑"},{c:"1.2.3(a)(ii)",s:"下列哪項關於彌償的陳述是正確的？",o:["除非由法律隱含，否則彌償不存在於人壽保險","法律不容許人壽保險作出彌償","不可能對喪失生命作出超額彌償","五十年前，彌償普遍存在於人壽保險"],a:2,e:"人壽保險亦稱為利益保單，不可能超額\n賠償，因為人壽保險可保權益在大多數\n情況下是無限的"},{c:"1.3.1a",s:"在人壽保險保費的一般計算中，在正常統計預期下足夠支付死亡索償所需向保單所有人收取的金\n額是以下哪一種保費",o:["實收保費","淨保費（純保險費）","毛保費","充足及公平的保費"],a:1,e:"在正常統計預期下足夠支付死亡索償所\n需向保單所有人收取的金額是淨保費（\n又叫純保險費）"},{c:"1.3.2a",s:"下列哪項不是自然保費制度的特性？",o:["隨著年齡的增長增加保費","對保險人有不利影響","續保時，對保單所有人帶來實際問題","隨著年齡的增長而減少保費"],a:3,e:"自然保費制度的特性是隨著受保人的年\n齡的增長而增加保費"},{c:"1.3.2b&c(ii)",s:"可作為保單抵押貸款的抵押物是",o:["銀行中的存款","保單的現金價值","保單所有人所持有的財產","以上各項都是"],a:1,e:"可作為保單抵押貸款的抵押物是保單的\n現金價值"},{c:"2.3.1(d)",s:"以下哪項是年金的核保特色?\ni.女 性收取的定期年金高於相同年齡的男性\nii.年 金核保以生存率為基礎\niii.年 金核保須要驗身報告\niv.年 金利益付款開始時的年齡越高，毎一期年金利益付款便越高",o:["i,ii","ii,iv","i,ii,iii","i,iii,iv"],a:1,e:"女性收取的定期年金低於相同年齡的男\n性\n年金核保並無提及須要驗身報告"},{c:"1.2",s:"以下哪項屬於儲蓄壽險合約的特點？",o:["於香港十分普遍","儲蓄壽險是不分紅的","它包含一項重大的儲蓄成份","只會於保單期滿時仍然生存才支付保額"],a:2,e:"儲蓄壽險合約它包含一項重大的儲蓄成\n份，並有機會出現死亡或期滿索償"},{c:"2.3.1",s:"合資格延期年金保費及強積金可扣稅自願性供款合計可享的扣除金額是",o:["3萬","5萬","6萬","8萬"],a:2,e:"合資格延期年金保費及強積金可扣稅自\n願性供款合計可享的扣除金額是6萬"},{c:"2(b)",s:"下列哪項屬於基本形式之壽險保單的常見變化？\ni)保單所有人可以選擇將保單紅利轉換為公司股份\nii)如果最初只投保一段有限時間，可能可以續保\niii)保單所有人可以選擇將保單紅利轉換為公司優先股\niv)保單可加入各種附約，用以改善所提供的保障",o:["i, ii","iii, iv","ii, iv","i, ii, iii, iv"],a:2,e:"可續保的及可轉換的是人壽保險的基本\n變數"},{c:"2.1.1",s:"下列哪項有關定期壽險的陳述是正確的？",o:["索償是無可避免的","在大多數情況下，定期壽險到期時仍沒有出現索償","長達很久的保險期","保單往往被保險人取消，並退回保費"],a:1,e:"定期壽險因為保障期短，在大多數情況\n下，定期壽險到期時仍沒有出現索償"},{c:"2.2.2",s:"以下哪項是單位相連保單的不正確描述?",o:["它可以與股票基金掛勾","全部或部份保費用以購買基金單位","它只可以與定期壽險或儲蓄壽險相連","保單價值會隨投資表現而變動"],a:2,e:"單位相連保單理論上是可以跟所有保險\n險種相連，最常見的是與定期壽險或儲\n蓄壽險相連"},{c:"2.2.2",s:"以下哪一項是「投資相連長期保單」的正確描述?",o:["總是有最低保單價值保證","保單的價值從不會隨所掛鈎的基金單位的價值變動而波動","保單的價值會隨所掛鈎的基金單位的價值變動而波動","以上都不正確"],a:2,e:"投資相連長期保單並沒有最低保單價值\n保證，保單的價值會隨所掛鈎的基金單\n位的價值變動而波動"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"年金計劃在累積期內，保單持有人在一\n段時間內定期繳付保費，讓保險人通過\n投資令已付金額增長"},{c:"2.3.1(b)",s:"保險人須在課稅年度（ 即 3月 31日）結束後的\n____天內，向保單持有人就其每張保單各別發出合資格延期年金保單的年度摘要。",o:["40","30","50","45"],a:0,e:"保險人須在課稅年度結束後的40天內，\n向保單持有人就其每張保單各別發出合\n資格延期年金保單的年度摘要。"},{c:"2.1",s:"如果對人壽保險有短暫的需求，所需的財務金額在該段時期都不會增加或減少，並且該需求會在\n指明的期間後便消失，就以保險成本為一重要的考慮因素，以下哪一項不太適合?",o:["定額定期壽險","非儲蓄定期壽險","分紅終身壽險","非分紅終身壽險"],a:2,e:"終身壽險的保費比定期壽險高，而分紅\n計劃的保費亦比非分紅計劃高，以保險\n成本為一重要的考慮因素，分紅終身壽\n險最不適合"},{c:"2.1.1",s:"假設該保單持續有效或生效，所有壽險保單均不能避免索償的出現，除了以下哪項？",o:["定期壽險","儲蓄壽險","分紅終身壽險","不分紅終身壽險"],a:0,e:"定期壽險因為保障期短，在大多數情況\n下，定期壽險到期時仍沒有出現索償"},{c:"2.1.1",s:"定期壽險保單的利益，只於死亡時候保單仍屬有效時情況，以下哪種或哪些情況下才給付？",o:["被保險人在整個保險期內仍然生存","被保險人患上危疾","於指明保單期限內死亡","於指明保單期限之後死亡"],a:2,e:"定期壽保單利益只限於受保生命在特定\n期間或時期內死亡\n；及死亡發生時保單是有效的。"},{c:"2.1.1a(b)(ii)",s:"一種也許會與其他壽險於死亡時提供一筆死亡利益的計劃互相結合，還在指明期間的剩餘時間每\n月支付利益，這種壽險產品稱為",o:["家庭收入壽險","萬用壽險","抵押贖回壽險","遞減定期壽險"],a:0,e:"家庭收入壽險是一種也許會與其他壽險\n於死亡時提供一筆死亡利益的計劃互相\n結合，還在指明期間的剩餘時間每月支\n付利益"},{c:"2.1.2(b)",s:"一份罕見人壽保險產品，這產品只有在受保生命在保障期間結束時仍然生存才支付保險利益，這\n份壽險是",o:["儲蓄壽險","定期壽險","延期年金","純生存保險"],a:3,e:"純生存保險一份罕見人壽保險產品，這\n產品只有在受保生命在保障期間結束時\n仍然生存才支付保險利益"},{c:"2.1.3(a)(i)",s:"純粹壽險是指",o:["保單不適用附約或其他保障","保額在意外死亡時才支付","受保生命在世期間終身繳付保費","受保生命被評估為可按標準保費及屬標準風險"],a:2,e:"純粹壽險是指受保生命在世期間終身繳\n付保費，亦是終身壽險的別稱"},{c:"2.2.1",s:"下列哪項或哪些不屬於萬用壽險的特點？",o:["它具有可調整的保險利益","它從不累積現金價值","靈活的保費","上述所有各項都不屬於萬用壽險的特點"],a:1,e:"萬用壽險是具有累積的現金價值"},{c:"2.3",s:"以下哪項對年金的描述是正確的？",o:["女性不可以購買年金","女性的保費比相同情況下的男性保費為低","向男性支付年金金額低於向女性支付的年金金額","向女性支付年金金額低於向男性支付的年金金額"],a:3,e:"因為女性的預期壽命比同齡男性長，所\n以向女性支付年金金額低於向男性支付\n的年金金額"},{c:"2.3(a)",s:"週期性地領取年金的人士稱為",o:["收款人","年金購買人","年金持有人","保單所有人"],a:0,e:"週期性地領取年金的人士稱為收款人"},{c:"2.4(e)",s:"核保團體壽險保單",o:["與核保個人保單完全相同","往往需要詳細個人資料","一般不需要詳細個人資料","把受保成員分作個別受保計算保費"],a:2,e:"團體計劃以集體核保形式核保。通常不\n會要求詳細的個人資料"},{c:"2.4(f)",s:"參加團體保險的「在職工作條款」的定義是",o:["保險生效後，個別受保險人士必須受僱並當值","保險生效後，個別受保險人士可以是受僱及放假","保險生效後，個別受保險人士可以是受僱及生病","保障範圍必須與工作有關"],a:0,e:"參加團體保險的「在職工作條款」的定\n義是保險生效後，個別受保險人士必須\n受僱並當值"},{c:"3.4.1(c)(iv)",s:"根據《自願醫保計劃下保險公司的實務守則》，以下哪項不屬該守則的要求?",o:["自願醫保的產品提供者應根據政府公布的稅項扣減細節，在銷售過程中及接獲查詢時，讓消費\n者知道認可產品的稅項扣減資格。","自願醫保的產品提供者在銷售過程中及接獲查詢時，應向消費者解釋，不同計劃的病房級別選\n擇的限制。","自願醫保的產品提供者在銷售過程中及接獲查詢時，應向消費者解釋，不同計劃的保障地域範\n圍限制的，並解釋所有保障均不適用於全球","自願醫保的產品提供者應確保所有銷售及推廣資料，均為準確及非誤導性、備有中英文版本、\n用字淺白及完整。"],a:2,e:"自願醫保的不同計劃的保障地域範圍限\n制，所有保障是適用於全球的"},{c:"3.2.1(a)",s:"在意外死亡保險利益附約中，下列哪項死因一般是受到保障？",o:["自殺","一名被警察開槍擊斃的賊人","作為一名艙務員的時候，死於撞機意外","一名死於撞機意外，普通購票的乘客"],a:3,e:"死於撞機意外，普通購票的乘客不屬意\n外死亡保險利益附約中的除責任"},{c:"3.5.1",s:"保證可保利益的附約特點",o:["限制","指定事件","暫時的保障","以上各皆是"],a:3,e:"以上都是保證可保利益的附約特點"},{c:"3.3.1",s:"危疾保險利益附約經常指明的疾病是︰",o:["中風","心臟病","肺癌","以上所有各項"],a:3,e:"以上都是危疾保險利益附約經常指明的\n疾病的例子"},{c:"3.5.1",s:"以下哪兩項是對保證可保利益的陳述是正確的?\ni.增 額保險的金額不能超過原有保單的面額\nii.保 單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明\niii.保 單所有人必須提供持續良好的健康證明\niv.該 項權利於在受保生命達到40歲之後才可行使",o:["i,ii","i iii","ii,iii,iv","iii,iv"],a:0,e:"保證可保利益的保單所有人毋須提供持\n續良好的健康證明，\n該項權利也可能限於在受保生命達到某\n一年齡一般 為 40歲之前才可行使。"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認可\n的個人償款住院保險產品，供消費者自\n願選購，團體保險並不適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫療\n服務的消費者提額外的保險計劃選擇"},{c:"3.1.1",s:"以下哪項或哪些是「豁免保費」附約支付利益的準則描述是正確?",o:["受保保單所有人必須死於他生前引致完全傷殘的那項成因","受保保單所有人在保單有效期內變成完全傷殘,而且已持續一段指明時間(稱為等侯期)","當受保保單所有人完全傷殘時,之前最少已經部分傷殘達到某段時間(稱為等侯期)","以上各項均不屬於該附約支付利益的準則"],a:1,e:"受保保單所有人在保單有效期內變成完\n全傷殘,而且已持續一段指明時間(稱為\n等侯期，一般為為3或6個月)"},{c:"3.1.1(a)",s:"豁免保費附約通常設有「等候期」條文。這條文是要︰",o:["為容許過期繳付保費而提供的一指明的「寬限期」","給予保險人一定的時間限制去支付保險利益","延至殘疾情況維持一段時間之後才豁免保費","「等候期」內豁免保費"],a:2,e:"豁免保費附約的「等候期」是指被保險\n人的殘疾情況須維持一段時間之後才豁\n免保費，等侯期一般為3或6個月"},{c:"3.1.2(d)",s:"根據殘疾收入附約，支付的殘疾收入保險利益",o:["會在最後的保險金扣除","不會在最後的保險金扣除","在未來的保單紅利中扣除","實質上是從保單中的現金價值貸款"],a:1,e:"殘疾收入保險利益不是預繳或貸款，不\n會在死亡保險金扣除"},{c:"3.2.1(a)",s:"意外保險中，「雙倍賠償利益」在技術上不適用於人壽保險，因為",o:["導致意外的原因可能是不保事項","彌償只適用於財產保險","此利益不適用於自然死亡","給付保額實際上不是彌償，是屬於利益"],a:3,e:"這種保險利益經常被稱為雙倍賠償利益\n(Double Indemnity\nBenefit)。在這裏使用字面意思為「彌\n償」一詞技術上並不準確，因為人壽保\n險一般不適用彌償原則"},{c:"3.2.1(a)",s:"以下哪項有關雙倍賠償利益附約(double Indemnity benefit)的陳述是不正確的？",o:["只適用於第3者保險","引起死亡的近因對這附約很重要","嚴格來說，它的英文術語在技術上是不正確","它是意外保險利益附約的另一名稱"],a:0,e:"雙倍賠償利益附約與第3者保險無關"},{c:"3.2.1(b)",s:"在意外死亡保險收益，喪失肢體在於實際喪失由手腕或足踝關節處以上完全斷離作定義。但保險\n人亦可以包括以下情況",o:["臂部及肩斷離開始才作賠償","一根手指或腳指之斷離也作賠償","包括喪失肢體功能","喪失任何2肢才作出賠償"],a:2,e:"喪失一肢可以描述為實際喪失肢體，或\n喪失肢體的功能"},{c:"3.3.1",s:"危疾保險利益附約支付利益的支付方法，會因為不同的保險人而有所不同。但一般往往是",o:["一整筆支付","按年分期支付","一連串的按月分期支付","在受保人死亡時一整筆支付"],a:0,e:"危疾保險利益附約支付利益的支付方法\n，一般往往是一整筆支付"},{c:"3.3.2",s:"附加壽險保單的長期護理附約規定",o:["於死亡時支付雙賠保額","提供的付款與可予支付的保單毫無關係","由保險人支付認可護理院的費用","支付保單死亡保險金的某所述部份作長期護理的費用"],a:3,e:"長期護理附約利益屬預繳性質，已支付\n的保單利益會在死亡保險金扣除"},{c:"3.4",s:"如果一間人壽險公司打算提供醫療保險利益保障作為獨立的保單",o:["這在任何情況都不可能","這種做法必須透過另一間保險公司來完成","只有在該公司同時簽發壽險保單時這種做才可能","這公司必須獲得經營有關一般保險險種的授權"],a:3,e:"獨立形式發售的醫療保險單屬一般保險\n類別，這公司必須獲得經營有關一般保\n險險種的授權"},{c:"3.5.1(a)",s:"保證可保利益的定義為",o:["保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明","保單所有人有權在任何時候購買增額保險，無需遞交可保證明","保單所有人有權在指定的備擇日期購買增額保險，必需遞交可保證明","保單所有人有權在任何時候購買增額保險，必需遞交可保證明"],a:0,e:"保證可保利益的保單所有人有權在指定\n的備擇日期購買增額保險，無需遞交可\n保證明"},{c:"3.6",s:"通貨膨脹可能會重大的降低壽險利益的購買能力，為了解決這個難題而設的特定條文或獨立的附\n約稱為",o:["購買能力條文","生活指數調整利益利益","通脹條文","通脹調整條文"],a:1,e:"生活指數調整利益利益條文是抵銷將來\n因通貨膨脹可能會重大的降低壽險利益\n的購買能力"},{c:"3.6.1",s:"稱為生活指數調整利益的附約的原意是",o:["對抗物價通脹及物價通縮","對罹患終末疾病的人支付部份保額","於保險人盈利低於一般水平時，當補充紅利","以上各項皆不是"],a:3,e:"生活指數調整利益利益條文只會按通漲\n增加保險利益，所以以上情況都不正確"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保單\n，保單的持有人決定不再繳付任何保費\n有權選取的選擇"},{c:"4.11",s:"在傳統的保單條文，以下哪項是給付保單利益時，給受益人或保單所有人的賠付選擇?",o:["以保險公司的股份取代以現金方式支付保單利益","以保單利益購買一份定期壽險作替代壽險","在一段時期內，分期支付保單收益及利息","以上各項皆是"],a:2,e:"受益人收取死亡保險金時，除了一整筆\n獲支付之外，亦可以在一段時期內，分\n期支付保單收益及利息"},{c:"4.2",s:"一項典型的「不可異議」條款，為其目的訂下兩年的期限，該期限稱為",o:["無訴訟期","不可異議期","可異議期","超出期"],a:2,e:"可異議期是根據「不可異議」條款，訂\n下兩年的期限，保險人可在此期間內對\n保單提出質疑或反對"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已婚者地位\n條例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非張先生就《已婚者地位條例》訂明，被保險人就自身生命購買保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有人\n如為其配偶及或其任何子女的利益而購\n買壽險單，將達到建立一個（法定信託\n的效用，從而令該配偶及或子女成為該\n保單的實益擁有人。"},{c:"4.4(c)",s:"如某壽險單符合《已婚者地位條例》所指明的情況，將會產生以下甚麼的法律效用?",o:["所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的受託人","這是條例隱含的法定轉讓，並惠及保單所有人的指定受益人","信託效用自動產生，並惠及保單所有人的的其配偶及/子女等指定受益人","所指定的受益人如為保單所有人的其配偶及/子女，將成為該保單的實益擁有人，直至保單所有\n人更改受益人為止"],a:2,e:"根據《已婚者地位條例》，保單持有人\n如為其配偶及或其任何子女的利益而購\n買壽險單，將達到建立一個（法定信託\n的效用，從而令該配偶及或子女成為該\n保單的實益擁有人。"},{c:"4.4(c)",s:"黃生就自身生命購買壽險保單，自己為受保人，並指明他最小的兒子為該保單受益人，根據《已\n婚者地位條例》，此舉起了甚麼的法律效用?",o:["該受益人成為該保單的法定保單所有人","該受益人成為該保單的法定保單所有人，直至黃先生修訂其他受益人為止","信託效用並不用適指定子女成為受益人","該受益人成為該保單的實益擁有人"],a:3,e:"根據《已婚者地位條例》，保單持有人\n如為其配偶及或其任何子女的利益而購\n買壽險單，將達到建立一個（法定信託\n的效用，從而令該配偶及或子女成為該\n保單的實益擁有人。"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許藉\n訂明手續來轉讓據法權產"},{c:"4.9",s:"以下哪項有關抵押轉讓的描述是正確的?",o:["它是永久性的轉讓安排","承讓人對保單擁有單的一切擁有權","保單仍可用作貸款","以上各項皆不是"],a:3,e:"抵押轉讓安排是暫時性的，轉讓條款把\n承讓人的利益限於貸款金額連利息並賦\n予轉讓人復歸權\n，於完全還款之後取回權益。"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，擬\n轉讓\n的據法權產須屬現時的，而非未來的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許藉\n訂明手續來轉讓據法權產，而對保險合\n約的權益屬於據法權產。"},{c:"4.4(b)",s:"保單中的指定受益人有第一順位受益人及次順位受益人。第一順位受益人於受保人在生期間過身\n，受保人過世時，次順位受益人仍然在生。那麼保險金將分配給",o:["成為保單所有人的遺產","由次順位受益人所擁有","由保單所有人之繼承人所擁有","由次順位受益人及保單所有人之繼承人平均分配"],a:1,e:"以防第一順位受益人不能比受保生命活\n得久\n，可在第一順位受益人以外，指定一個\n或一個以上的 次順位受益人"},{c:"4.9",s:"對於一個保單所有人來說，如果他對產權的權益是復歸的，那",o:["仍未取得該項權益","雖然對產權有獲得認可的權益，財產的享用將延遲至將來的某一天或某事發生時","肯定會在將來取得該權益","該權益屬於受益人權益"],a:1,e:"復歸的權益是指對產權有獲得認可的權\n益，財產的享用將延遲至將來的某一天\n或某事發生時"},{c:"4.2",s:"一個人購買免體檢保險，他無意地誤導了保險人，若將事實表明，他的身體狀況是得不到保障的\n，後來他死亡並被知道真相，下列哪項在此情況下為不正確呢？",o:["在任何情況下也不得異議","若保單生效不足兩年，保險人可使保單無效","若保單生效兩年，保險人便不可異議該保單","保單生效已兩年，因並非欺詐情況，保險人很難不承認保單"],a:0,e:"不可異議條款規定\n：保險合約發出日起計已\n生效了兩年可異議期內，保險人可以對\n該約提出異議或質疑"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["該期間一般最少30或31天","它不適用於保單的首期保費","於寬限期內繳付保費可維持保單的保障繼續有效","於寬限期內繳付保費須另外繳付利息"],a:3,e:"於寬限期內繳付保費須被視為準時繳交"},{c:"4.3",s:"按照英式保單處理方法，如寬限期內仍未繳清保費，而保單沒有現金價值，那英式保單會於何時\n開始失效?",o:["寬限期過後","寬限期後的十四天","保費到期日後的十四天","保費到期日開始"],a:3,e:"按照英式保單處理方法，如寬限期內仍\n未繳清保費，而保單沒有現金價值，保\n單會於保費到期日開始開始失效"},{c:"4.4(b)",s:"如果已指定兩名受益人,但沒有顯示他們分別所佔的比例,在需要給付保單利益時",o:["會平均分配保險利益","第一順位受益人可取得兩倍的分配","第二順位受益人可取得兩倍的分配","第一順位受益人可取得所有保險利益"],a:0,e:"如果已指定兩名受益人,但沒有顯示他\n們分別所佔的比例,在需要給付保單利\n益時會平均分配保險利益"},{c:"4.5",s:"保單條款指出可利用保單現金價值使保單維持有效，條款稱為「不能作廢」及",o:["續保保費貸款","自動保費貸款","自動保費透支","自動清繳貸款"],a:1,e:"部分保險人視不能作廢條款，為自動保\n費貸款條款或稱保費自動墊繳條款"},{c:"4.5",s:"壽險保單中自動保費貸款",o:["貸款用途由保險人任意決定的","貸款在所有壽險保單中，都是常見的","貸款只可用作保單規定的指定用途","以上各項描述均不是"],a:2,e:"壽險保單中自動保費貸款只可用作保單\n規定的指定用途"},{c:"4.6",s:"就合資格的壽險保單的保單貸款而言",o:["要求貸款是一種權利，而不是權益","貸款毋須在提供索償前償還","除保單價值以外，保單持有人毋須提供其他抵押","以上所有各項皆正確"],a:3,e:"保單抵押貸款的用途是無限制的"},{c:"4.8",s:"如果保單於提出索償時，才發現有關受保生命的真實年齡較保單顯示的為高",o:["保單自動無效","調整利益，支付比保單較低的保額","調整利益，支付比保單較高的保額","維持保額不變，退回多繳的保費"],a:1,e:"如果保單於提出索償時，才發現有關受\n保生命的真實年齡較保單顯示的為高，\n即是出現少交保費的情況，保險人會調\n整利益，支付比保單較低的保額"},{c:"4.8",s:"大部分的香港保險公司簽發的保單，在誤報年齡或性別的情況下(根據美式慣例)，如果於提出索\n償後才被發現，保險人不會如何處理？",o:["不會調高保費亦不會退回保費","如果保單上顯示的年齡較真實為低，可能獲得的利益便調低","如果保單上顯示的年齡較真實為高，可能獲得的利益便調高","以上各項都有可能"],a:0,e:"根據美式慣例，如果於提出索償後才被\n發現，保險人調整應付保險利益的金額\n或調整應付保費，以反映在根據正確的\n年齡／性別"},{c:"4.8",s:"如果一份已簽發的壽險保單顯示受保人的年齡不正確,而該錯誤是於提出任何索償前發現,那麼以\n下哪項描述是正確的?",o:["必須取消該份保單而簽發一份新保單","其中一項選擇是支付任何差額保費(或獲退回多繳保費)","要更改保額或任何合約條款,實屬太遲","基於不可異議條款,不必有所作為"],a:1,e:"根據美式慣例，如果於提出索償後才被\n發現，保險人調整應付保險利益的金額\n或調整應付保費，以反映在根據正確的\n年齡／性別"},{c:"4.9",s:"壽險保單的絕對轉讓是指",o:["將保單轉給另一名保險人","有關保單即時變為不可異議","原有的保單所有人已被宣佈破產","不可撤銷地轉讓對某份壽險保單的一切擁有權"],a:3,e:"絕對轉讓屬永久性，不可撤銷地轉讓對\n某份壽險保單的一切擁有權"},{c:"4.9(e)(ii)",s:"一種屬於暫時性質的轉讓(例如利用保單作為一項貸款的抵押品)稱為？",o:["暫時性轉讓","絕對轉讓","抵押轉讓","附條件轉讓"],a:2,e:"抵押轉讓屬於暫時性質的轉讓"},{c:"4.10",s:"如保單所有人沒有註明紅利的選擇，保險人會自動為保單所有人將紅利存放以賺取利息或",o:["以現金支付","用以繳付未來保費","用以購買清繳增額保險","購買一年期的定期壽險"],a:2,e:"購買清繳增額保險及紅利存放保險人以\n賺取利息屬自動紅利選擇"},{c:"5.2.10&附件M",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","保險回報率","冷靜期"],a:3,e:"冷靜期不屬《重要資料聲明書－內地人\n士在港投購人身╱壽險保單》涵蓋的部\n分，詳細 研集資料手冊附件M"},{c:"5.2.3b",s:"達致高素質的顧客服務的因素是?",o:["公司文化","權力下放","A&B","以上皆不正確"],a:2,e:"公司文化及權力下放是達致高素質的顧\n客服務的因素"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個近期曾發\n出新保單的產品實現率是怎樣計算的?",o:["實現率是指按「實際派發的保證英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算","實現率是指按「實際派發英式紅利」除以銷售時「利益說明所述數額」的平均數計算。","實現率是指按「實際派發的非保證英式紅利」除以銷售時「利益說明所述數額」的平均數計算","實現率是指按「實際派發的英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算"],a:2,e:"某個產品的實現率是指按「實際派發的\n非保證紅利／英式紅利」除以銷售時「\n利益說明所述數額」的平均數計算"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","投資風險","保險回報率"],a:2,e:"投資風險不屬《重要資料聲明書－內地\n人士在港投購人身╱壽險保單》涵蓋的\n部分，詳細參閱研集資料手冊附件M"},{c:"5.3.1(a)",s:"人壽保險根據實質危險及道德危險核保確定有關風險程度，以下哪項因素是正確的描述?",o:["與實質危險相比，道德危險較難確定","實質危險涉及較主觀的因素，環繞準被保人的基本誠信或正直意向，道德危險主要考慮到可能\n增加受保事件發生率的","實質危險主要考慮誠信因素，道德危險主要考慮家族遺傳因素","實質危險主要考慮正直意向因素，道德危險主要考慮高危職業或消閒活動因素"],a:0,e:"道德危險涉及一些較主觀的因素，實質\n危險考慮死亡發生率的客觀因素。與實\n質危險相比，道德危險較難確定"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","所有類別人壽保單","投資相連壽險計劃（“投連壽險”）保單"],a:3,e:"就保監局發出的指引28投資相連壽險計\n劃（“投連壽險”）保單可由獲授權保\n險人選擇是否發出有效利益說明"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》根據以下哪項/些機構頒布的保險核心原則而制定？",o:["國際保險監督聯會","特區政府","保險監督聯合會","國際保險業聯會及國際保險監督聯會"],a:0,e:"《承保長期保險業務(類別C業務除外)\n指引》根據國際保險監督聯會頒布的保\n險核心原則而制定"},{c:"5.2.6",s:"以下哪項是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨回報率?",o:["3%","8%","1%","以上各項皆是"],a:0,e:"投資壽險保單利益說明文件的具體規定\n獲授權保險人可選擇闡述的假設淨回報\n率是:0%, 3%,6%,9%,或較低的0%,\n2%,5%,7%"},{c:"5.3.1(a)",s:"以下哪項屬於人壽保險的核保考慮因素？原因何在？",o:["身體明顯過重是核保考慮因素，因可能與其他疾病有聯繫","在卡拉OK，酒吧或賭場工作並不屬於核保考慮因素，保險人不會就這些職業而收取 較高的保費","體重過輕不屬於核保考慮因素，因這並不涉及任何其他疾病","經營香煙業務是核保考慮因素，他們可以平價買香煙"],a:0,e:"身體明顯過重是核保考慮因素，因可能\n與其他疾病有聯繫"},{c:"5.1.1(e)",s:"下列哪項不大可能屬於保單所有人服務部的職能？",o:["通訊","收取保費","索償處理","權益管理"],a:2,e:"索償處理屬理賠部負責"},{c:"5.2.2(b)",s:"在非人壽保險的保單中，有類似文件以提供暫時性、不附帶條件、但可取消的保障稱爲暫保單。\n在人壽保險亦有一種類似這種的收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:1,e:"立約保費收據又叫不附帶條件保費收據\n、或可取消的保障稱爲暫保單。"},{c:"5.3",s:"風險評估、選擇、評級以及按需要附加限制條款。決定所需的再保險程度並針對個別保險情況,而\n作出適當的再保險安排,屬於哪個部門的活動?",o:["理賠部","核保部","保單條款制定部","精算部"],a:1,e:"核保部是對風險作出!評估、選擇、評\n級以及按需要附加限制條款的部門"},{c:"5.3.1",s:"核保的兩大主要階段，是確定風險程度，以及",o:["將建議風險分類","提供合適計劃","安排足夠再保險","建議次標準措施"],a:0,e:"核保的兩大主要階段，是確定風險程度\n，以及將建議風險分類"},{c:"5.3.1(b)",s:"保險人在核保時對某特定的風險，由於投保人的健康或其他因素使這些投保不可能被接受，此類\n核保稱為",o:["不承保風險","拒保風險","不可保風險","不接受風險"],a:1,e:"拒保風險是保險人不可能被接受"},{c:"5.3.2",s:"通常或曾經對投保人提供醫療護理的醫生或其他合格醫務人員被稱為",o:["護理醫生","主診醫生","體檢醫生","機密醫生"],a:1,e:"主診醫生是通常或曾經對投保人提供醫\n療護理的醫生或其他合格醫務人員"},{c:"5.3.2b",s:"保險人最常要求的醫療報告 APS 的全寫為",o:["輔助的醫療報告 (Ancillary Physical Statement)","實質醫療的聲明 (Acutal Physical Statement)","附加的醫療聲明 (Additional Physical Statement)","主診醫生報告 (Attending Physician's Statement)"],a:3,e:"主診醫生報告的英文名稱是\n(Attending Physician's\nStatement)︿簡稱APS"},{c:"5.6.2(d)(i)",s:"如果證實殺人犯是受益人的話，以下哪項法律是不會容許殺人犯本人獲益？",o:["合約法","公共政策","衡平法","人權法"],a:1,e:"如果證實殺人犯是受益人的話，根據法\n律的公共政策，是不會容許殺人犯本人\n獲益"}],"paper3-2025-09":[{c:"1.2.3(c)",s:"以下哪項保險原則是彌償的引伸?",o:["代位","近因","A&B","以上皆不正確"],a:0,e:"只有代位是彌償原則的引伸"},{c:"1.2.2(b)",s:"就最高誠信原則，在免體檢的投保的前題下，以下哪項不屬違反最高誠信的情況?",o:["沒有披露未被驗出的腦瘤","沒有披露近日收到高利貸債主的死亡恐嚇","隱瞞自己從驗身得知的癌症","隱瞞自己意外導致嚴重受傷"],a:0,e:"有些疾病對合資格醫生而言可能很容易\n察覺，但是不能期望一般人也能夠進行\n自我診斷並作披露。"},{c:"1.2.2(b)",s:"就人壽保險而言，如果未有披露以下哪種情況，則被視為違反最高誠信?",o:["未被驗出的腦瘤","投保人的體檢醫生未能驗出投保人的心跳不正常","沒有披露投保人於兒時多次罹患輕微的兒童疾病","以上各項皆不是"],a:2,e:"就最高誠信而言，保險人希望瞭解投保\n人所有已知的重要事實"},{c:"1.2.3(a)",s:"以下哪三項有關人壽保險的近因原則的應用的描述是正確的?\ni.不 保危險不大可能是重要原則\nii.由 於所有死亡原因都受保，近因原則不適用\niii.如 果懷疑受保人自殺是死亡原因，近因原則的應用是很重要\niv.如 果雙倍賠償利益附約適用，近因原則的應用是很重要",o:["i, ii, iii","i,ii,iv","i,iii,iv","ii,iii,iv"],a:2,e:"如果受保生命在該免責期內(通常為保\n單發出後一年內)自殺，保險人無須支\n付死亡保險金，構成人壽保險的除外責\n任，所以選項(ii)不正確"},{c:"1.3.1",s:"釐定人壽保險保費的傳統標準是",o:["可負擔的","合理的","可計算的","公平的"],a:3,e:"釐定人壽保險保費的傳統標準是公平(\n公正)的，及充足的"},{c:"1.3.2(a)",s:"以下哪項不是影響保費率的主要因素？",o:["死亡率","利息","開支","發病率"],a:3,e:"發病率是影響保費率的其他因素"},{c:"1.3.2a",s:"下列哪項屬於自然保費制度的特點？",o:["保費隨年齡增長而增加","會產生逆選擇","大部份保險公司已不採用","以上各項皆正確"],a:3,e:"以上各項都屬於自然保費制度的特點"},{c:"1.2(h)(ii)",s:"債權人可就其債務人的生命投保。在債務得到償還後，會出現以下哪個情況？",o:["保單必定立即終止","債權人必須轉讓保單給債務人才繼續有效","仍然維持該保單的有效性，並在適當時候「再次得到償付」","以上答案均不正確"],a:2,e:"人壽保險的可保權益只有在合約開始時\n才需要，在債務得到償還後，仍然維持\n該保單的有效性"},{c:"1.3.1a",s:"以下哪項關於死亡表的描述是正確的?\ni.顯 示不同年齡的預期死亡比率的計算表\nii.應 付所有預期及可能出現的營運開支\niii.考 慮某種新疾病或其他災難引起異常死亡率的可能性\niv.只 應付正常風險和正常預期的死亡率",o:["i, iii","i,iv","ii,iv","以上各項皆是"],a:1,e:"死亡表或稱生命表顯示不同年齡的預期\n死亡比率的計算表，在保險行業中十分\n通用。利用死亡表釐定費率，只是應付\n正常風險和正常預期。所以只有選項i\n及iv是正確"},{c:"1.1",s:"以下哪項為人壽保險最初的基本目的?",o:["為退休提供一筆資金","儲蓄","應付暫時的需要","退休安排"],a:2,e:"最初，保險單有效期較短，只為暫時性\n的風險情況"},{c:"1.2.1",s:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係要求的描述是正確的？\ni.就 某人的生命購買保險，對該受保生命必須具有可保權益。但透過轉讓程序購買別人的現有保單\n，對該受保生命無須具有可保權益\nii.保 單所有人不能將壽險合約轉讓予第三者，即使該第三者對受保生命具有可保權益\niii.保 單所有人可以把正當地安排的壽險合約轉讓予第三者，即使該第三者對受保生命缺乏可保權\n益\niv.保 單所有人只可將壽險合約轉讓予對該受保生命有可保權益的第三者",o:["i, iii","i, ii","i, iii, iv","ii, iii, iv"],a:0,e:"保單所有人可把正當地安排的人壽保險\n合約轉讓給第三者，即使該第三者對受\n保生命缺乏可保權益"},{c:"1.2.1(h)",s:"在人壽保險中，只有在合約開始時才需要可保權益，以下哪項情況會出現有效索償?",o:["夫妻於離婚前，為其配偶的生命購買人壽保單","債務清還前，就債務人的生命購買人壽保單","關鍵人物人壽保單，受保僱於保單起保數天後離職","以上各項例子"],a:3,e:"人壽保險的可保權益只有在合約開始時\n才需要，就以上的關係轉變，仍然維持\n該保單的有效性"},{c:"1.2.2(e)",s:"以下哪項為最高誠信的正確描述？\ni.就 某些不可異議條文，保險人不得在保單生效了一段時訂明時間內對該份保單提出異議或質疑\nii.就 免體檢的投保，一份小心設計的投保單是很重要\niii.在 不構成欺詐的情況下，若受保生命違反最高誠信在可異議期間後才可獲得寬宥\niv.要 求投保人披露所有重要事實，不管保險人有沒有提出要求",o:["ii,iii,iv","i,ii,iv","i,ii","iii,iv"],a:3,e:"就不可異議條文，保險人可以在保單生\n效了的兩年內對該份保單提出異議或質\n疑\n就免體檢的投保，一份小心設計的投保\n單未必很重要"},{c:"1.2.3(b)",s:"當發現死者就其生命購買了多於一份人壽保單，而每一份保單仍然生效，當作出賠付時",o:["只有最先購買的保單作出賠付","只有最高保額的保單作出賠付","每份保單對賠償都必須負責","應付保額為最高保額，而所有保險人分擔責任"],a:2,e:"人壽保險亦稱為利益保單，不可能超額\n賠償，因為人壽保險可保權益在大多數\n情況下是無限的"},{c:"1.1",s:"人壽保險合約最初類型",o:["本質上屬於短暫的，以保障早逝情況","本質上屬於長久的，即直至死亡","與物業抵押貸款有關","屬單位相連的安排"],a:0,e:"最初，保險單有效期較短，只為暫時性\n的風險情況"},{c:"1.2.1",s:"一名人士對另一人的生命具有一項權益，這權益在法律上賦予法定權利可就該人物的生命購買保險\n，這稱為",o:["可保權益","最高誠信","家庭保險權益","特別權益"],a:0,e:"可保權益是某人對某項保險標的在法律\n上被認可的一種關係，這種關係賦予他\n對該保險標的購買保險的權利。"},{c:"1.2.2(e)",s:"若違反人壽保險合約的最高誠信責任通常會令該合約變為可使無效。就香港的壽險保單而言",o:["這種情況在任何時候也適用","最高誠信的原則並不適用","違反最高誠信便會自動令該合約變為無效","保單的不可異議條款可能改變這種情況"],a:3,e:"就不可異議條文，保險人可以在保單生\n效了的兩年內對該份保單提出異議或質\n疑"},{c:"1.3.1a",s:"在人壽保險保費的一般計算中，在正常統計預期下足夠支付死亡索償所需向保單所有人收取的金額\n是以下哪一種保費",o:["實收保費","淨保費（純保險費）","毛保費","充足及公平的保費"],a:1,e:"在正常統計預期下足夠支付死亡索償所\n需向保單所有人收取的金額是淨保費（\n又叫純保險費）"},{c:"1.3.2a",s:"下列哪項不是自然保費制度的特性？",o:["隨著年齡的增長增加保費","對保險人有不利影響","續保時，對保單所有人帶來實際問題","隨著年齡的增長而減少保費"],a:3,e:"自然保費制度的特性是隨著受保人的年\n齡的增長而增加保費"},{c:"1.3.2b&c(ii)",s:"可作為保單抵押貸款的抵押物是",o:["銀行中的存款","保單的現金價值","保單所有人所持有的財產","以上各項都是"],a:1,e:"可作為保單抵押貸款的抵押物是保單的\n現金價值"},{c:"2(a)",s:"我們預期人壽保險的基本形式或保障不會出現以下哪項?",o:["只就指定時期內發生的死亡支付保險利益","就任何時候發生的死亡都支付保險利益","就指明的疾病導致的死亡給付保險利益","在某一特定日期 或 在那日期前發生的死亡支付保險利益"],a:2,e:"就指明的疾病導致的死亡給付保險利益\n不是預期人壽保險的基本形式"},{c:"2.3.1(c)",s:"以下哪項不是年金的變化?",o:["年金利益於年金購買後的第一個年金期，如一個月完結時開始支付","於規定年期內定期支付年金利益，不論年金標的人在此期間內是否已死亡","於退休時一整筆支付年金利益","如果年金標的人在年金期完結後還活着，年金更會終身支付利益"],a:2,e:"根據年金合約，保險人承諾「年金標的\n人\n」生前或一約定期限內向「收款人」週\n期性地支付一連串款項稱為「年金利益\n款項」，年金利益不會以整付形式支付\n的。"},{c:"2.3.1(d)",s:"以下哪項是年金的核保特色?\ni.女 性收取的定期年金高於相同年齡的男性\nii.年 金核保以生存率為基礎\niii.年 金核保須要驗身報告\niv.年 金利益付款開始時的年齡越高，毎一期年金利益付款便越高",o:["i,ii","ii,iv","i,ii,iii","i,iii,iv"],a:1,e:"女性收取的定期年金低於相同年齡的男\n性\n年金核保並無提及須要驗身報告"},{c:"1.2",s:"以下哪項屬於儲蓄壽險合約的特點？",o:["於香港十分普遍","儲蓄壽險是不分紅的","它包含一項重大的儲蓄成份","只會於保單期滿時仍然生存才支付保額"],a:2,e:"儲蓄壽險合約它包含一項重大的儲蓄成\n份，並有機會出現死亡或期滿索償"},{c:"2.3.1",s:"合資格延期年金保費及強積金可扣稅自願性供款合計可享的扣除金額是",o:["3萬","5萬","6萬","8萬"],a:2,e:"合資格延期年金保費及強積金可扣稅自\n願性供款合計可享的扣除金額是6萬"},{c:"2.1.1",s:"下列哪項有關定期壽險的陳述是正確的？",o:["索償是無可避免的","在大多數情況下，定期壽險到期時仍沒有出現索償","長達很久的保險期","保單往往被保險人取消，並退回保費"],a:1,e:"定期壽險因為保障期短，在大多數情況\n下，定期壽險到期時仍沒有出現索償"},{c:"2.1.1a(b)",s:"以下哪類保險的特色是保險額可按需求而遞減的？\ni 信用壽險\nii 遞減定期壽險\niii 抵押贖回保險\niv 家庭收入壽險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上皆是遞減定期壽險的種類，滿足逐\n漸減少的短暫保障需求。"},{c:"2.2.2",s:"以下哪項是單位相連保單的不正確描述?",o:["它可以與股票基金掛勾","全部或部份保費用以購買基金單位","它只可以與定期壽險或儲蓄壽險相連","保單價值會隨投資表現而變動"],a:2,e:"單位相連保單理論上是可以跟所有保險\n險種相連，最常見的是與定期壽險或儲\n蓄壽險相連"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"年金計劃在累積期內，保單持有人在一\n段時間內定期繳付保費，讓保險人通過\n投資令已付金額增長"},{c:"2.1",s:"如果對人壽保險有短暫的需求，所需的財務金額在該段時期都不會增加或減少，並且該需求會在指\n明的期間後便消失，就以保險成本為一重要的考慮因素，以下哪一項不太適合?",o:["定額定期壽險","非儲蓄定期壽險","分紅終身壽險","非分紅終身壽險"],a:2,e:"終身壽險的保費比定期壽險高，而分紅\n計劃的保費亦比非分紅計劃高，以保險\n成本為一重要的考慮因素，分紅終身壽\n險最不適合"},{c:"2.1.1",s:"假設該保單持續有效或生效，所有壽險保單均不能避免索償的出現，除了以下哪項？",o:["定期壽險","儲蓄壽險","分紅終身壽險","不分紅終身壽險"],a:0,e:"定期壽險因為保障期短，在大多數情況\n下，定期壽險到期時仍沒有出現索償"},{c:"2.1.1",s:"定期壽險的另一名稱為",o:["短期人壽保險","有條件保險","可終於人壽保險","期限保險"],a:0,e:"定期壽險的另一名稱為:短期人壽保險"},{c:"2.1.1",s:"定期壽險保單的利益，只於死亡時候保單仍屬有效時情況，以下哪種或哪些情況下才給付？",o:["被保險人在整個保險期內仍然生存","被保險人患上危疾","於指明保單期限內死亡","於指明保單期限之後死亡"],a:2,e:"定期壽保單利益只限於受保生命在特定\n期間或時期內死亡\n；及死亡發生時保單是有效的。"},{c:"2.1.1",s:"假設有一項對壽險之要求為於某段期間內須提供一項不多也不少的保障額，而低保險費用為首要要\n求，以下哪項最為適用？",o:["儲蓄壽險","定期壽險","分紅終身壽險","不分紅終身壽險"],a:1,e:"定期壽險是保費最便宜，在整個保險期\n內， 死亡保險金均維持定額不變"},{c:"2.1.1a(b)(ii)",s:"一種也許會與其他壽險於死亡時提供一筆死亡利益的計劃互相結合，還在指明期間的剩餘時間每月\n支付利益，這種壽險產品稱為",o:["家庭收入壽險","萬用壽險","抵押贖回壽險","遞減定期壽險"],a:0,e:"家庭收入壽險是一種也許會與其他壽險\n於死亡時提供一筆死亡利益的計劃互相\n結合，還在指明期間的剩餘時間每月支\n付利益"},{c:"2.1.2(b)",s:"一份罕見人壽保險產品，這產品只有在受保生命在保障期間結束時仍然生存才支付保險利益，這份\n壽險是",o:["儲蓄壽險","定期壽險","延期年金","純生存保險"],a:3,e:"純生存保險一份罕見人壽保險產品，這\n產品只有在受保生命在保障期間結束時\n仍然生存才支付保險利益"},{c:"2.1.3(a)(i)",s:"純粹壽險是指",o:["保單不適用附約或其他保障","保額在意外死亡時才支付","受保生命在世期間終身繳付保費","受保生命被評估為可按標準保費及屬標準風險"],a:2,e:"純粹壽險是指受保生命在世期間終身繳\n付保費，亦是終身壽險的別稱"},{c:"2.2.1",s:"下列哪項或哪些不屬於萬用壽險的特點？",o:["它具有可調整的保險利益","它從不累積現金價值","靈活的保費","上述所有各項都不屬於萬用壽險的特點"],a:1,e:"萬用壽險是具有累積的現金價值"},{c:"2.2.1(c)",s:"在萬用壽險的年報中，分別獨立地向保單持有人披露三個主要的定價方式(即保障的純成本，投資\n收益，公司開支)這特點稱為",o:["透明度","最高誠信","「分別列示各定價因素」","分項開列項目"],a:2,e:"萬用壽險具有「分別列示各定價因素」\n的定價結構，在萬用壽險的年報中，分\n別獨立地向保單持有人披露三個主要的\n定價方式(即保障的純成本，投資收益\n，公司開支)"},{c:"2.3(a)",s:"週期性地領取年金的人士稱為",o:["收款人","年金購買人","年金持有人","保單所有人"],a:0,e:"週期性地領取年金的人士稱為收款人"},{c:"2.4(e)",s:"核保團體壽險保單",o:["與核保個人保單完全相同","往往需要詳細個人資料","一般不需要詳細個人資料","把受保成員分作個別受保計算保費"],a:2,e:"團體計劃以集體核保形式核保。通常不\n會要求詳細的個人資料"},{c:"3.4.1(c)(iv)",s:"根據《自願醫保計劃下保險公司的實務守則》，以下哪項不屬該守則的要求?",o:["自願醫保的產品提供者應根據政府公布的稅項扣減細節，在銷售過程中及接獲查詢時，讓消費者\n知道認可產品的稅項扣減資格。","自願醫保的產品提供者在銷售過程中及接獲查詢時，應向消費者解釋，不同計劃的病房級別選擇\n的限制。","自願醫保的產品提供者在銷售過程中及接獲查詢時，應向消費者解釋，不同計劃的保障地域範圍\n限制的，並解釋所有保障均不適用於全球","自願醫保的產品提供者應確保所有銷售及推廣資料，均為準確及非誤導性、備有中英文版本、用\n字淺白及完整。"],a:2,e:"自願醫保的不同計劃的保障地域範圍限\n制，所有保障是適用於全球的"},{c:"3.5.1",s:"以下哪項是保證可保選擇的特點?",o:["限制","非自動獲得","指定事件","以上各項皆是"],a:3,e:"以上各項皆是保證可保選擇的特點"},{c:"3.2.2",s:"附加於人壽保單的意外死亡及喪失肢體附約，有時會賠付超出意外死亡保險利益及其他保險利益，\n以下哪項是適用的保障範圍?\n(i) 嚴重燒傷，可獲支付指明金額\n(ii) 每周津貼，最長為52周\n(iii) 住院津貼，每日津貼上限為 1,000日\n(iv) 因乘搭一般公共交通工具引果傷殘可獲「雙倍賠償」",o:["i,ii","ii,iii","ii,iii,iv","i,ii,iii,iv"],a:3,e:"以上各項皆是意外死亡保險利益附約所\n提供的其他保險利益"},{c:"3.2.1(a)",s:"在意外死亡保險利益附約中，下列哪項死因一般是受到保障？",o:["自殺","一名被警察開槍擊斃的賊人","作為一名艙務員的時候，死於撞機意外","一名死於撞機意外，普通購票的乘客"],a:3,e:"死於撞機意外，普通購票的乘客不屬意\n外死亡保險利益附約中的除責任"},{c:"3.5.1",s:"保證可保利益的附約特點",o:["限制","指定事件","暫時的保障","以上各皆是"],a:3,e:"以上都是保證可保利益的附約特點"},{c:"3.2",s:"意外死亡及喪失肢體(AD&D)附約，近因原則對這種附約顯得非常重要，原因是",o:["不適用於危疾保單","只有被保險人因意外死亡才有會給付雙倍賠償利益","每索償賠付，都會是保單基本保單保額的兩倍","就一宗意外而引致的傷殘，喪失肢體利益及死亡保險金同時支付"],a:1,e:"就意外死亡及喪失肢體(AD&D)附約而言\n，只有被保險人因意外死亡才有會給付\n雙倍賠償利益，所以近因原則(死亡原\n因)對這種附約顯得非常重要"},{c:"3.3.1",s:"危疾保險利益附約經常指明的疾病是︰",o:["中風","心臟病","肺癌","以上所有各項"],a:3,e:"以上都是危疾保險利益附約經常指明的\n疾病的例子"},{c:"3.1.1(a)",s:"以下哪項或哪些有關「豁免保費」附約的支付利益準則描述是正確的？",o:["受保保單所有人在變成完全傷殘時必須維持達到某段時間然後死亡","受保保單所有人在變成完全傷殘時必須已經有部份殘疾達到某段時間","受保保單所有人必須在保單有效期內完全傷殘且達到某段時間, 稱為 「等候期」","以上所有各項均不屬於豁免保費附約支付利益的準則"],a:2,e:"等候期即是受保保單所有人一旦根據保\n單的定義，完全傷殘達最低期限（通常\n為三個月或六個月），他將獲豁免支付\n續保保費。"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認可\n的個人償款住院保險產品，供消費者自\n願選購，團體保險並不適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫療\n服務的消費者提額外的保險計劃選擇"},{c:"3.1.1",s:"以下哪項不是(WP)附約的描述？",o:["(WP)是”waiting period”的縮寫，意指「等候期」","(WP)是”waiver of premium”的縮寫，意指「殘疾豁免保費附約」","被保險保單所有人須要完全傷殘，才可獲權益","受到特定年齡所限制"],a:0,e:"(WP)是Waiver of\nPremium的縮寫，意指「殘疾豁免保費\n附約」，而不是waiting\nperiod”「等候期」的意思"},{c:"3.1.1(a)",s:"豁免保費附約通常設有「等候期」條文。這條文是要︰",o:["為容許過期繳付保費而提供的一指明的「寬限期」","給予保險人一定的時間限制去支付保險利益","延至殘疾情況維持一段時間之後才豁免保費","「等候期」內豁免保費"],a:2,e:"豁免保費附約的「等候期」是指被保險\n人的殘疾情況須維持一段時間之後才豁\n免保費，等侯期一般為3或6個月"},{c:"3.1.2",s:"如果人壽保單收到殘疾收入附約約束,並且受保生命遭遇殘疾,而現正提供收入",o:["該收入通常以每月形式支付","其基本保障會暫時停止","所支付金額會於死亡保障額中扣除","此類保障通常並不設有等候期"],a:0,e:"殘疾收入等候期由一個月至六個月不等\n，所支付的利益並非貸款或預繳，不會\n於死亡保障額中扣除，殘疾收入附約如\n名稱所示，則在完全殘疾期間提供收入"},{c:"3.2.1(a)",s:"意外保險中，「雙倍賠償利益」在技術上不適用於人壽保險，因為",o:["導致意外的原因可能是不保事項","彌償只適用於財產保險","此利益不適用於自然死亡","給付保額實際上不是彌償，是屬於利益"],a:3,e:"這種保險利益經常被稱為雙倍賠償利益\n(Double Indemnity\nBenefit)。在這裏使用字面意思為「彌\n償」一詞技術上並不準確，因為人壽保\n險一般不適用彌償原則"},{c:"3.2.1(b)",s:"在意外死亡保險收益，喪失肢體在於實際喪失由手腕或足踝關節處以上完全斷離作定義。但保險人\n亦可以包括以下情況",o:["臂部及肩斷離開始才作賠償","一根手指或腳指之斷離也作賠償","包括喪失肢體功能","喪失任何2肢才作出賠償"],a:2,e:"喪失一肢可以描述為實際喪失肢體，或\n喪失肢體的功能"},{c:"3.3.1",s:'危疾保險利益中"指明疾病"指:\ni. 傷殘\nii. 心臟相關疾病\niii.癌症\niv. 重要器官相關疾病',o:["i,ii, iii","ii,iii, iv","i,ii, iv","i,ii,iii ,iv"],a:3,e:'以上都可以是危疾保險利益中"指明疾\n病"'},{c:"3.4",s:"如果一間人壽險公司打算提供醫療保險利益保障作為獨立的保單",o:["這在任何情況都不可能","這種做法必須透過另一間保險公司來完成","只有在該公司同時簽發壽險保單時這種做才可能","這公司必須獲得經營有關一般保險險種的授權"],a:3,e:"獨立形式發售的醫療保險單屬一般保險\n類別，這公司必須獲得經營有關一般保\n險險種的授權"},{c:"3.6",s:"通貨膨脹可能會重大的降低壽險利益的購買能力，為了解決這個難題而設的特定條文或獨立的附約\n稱為",o:["購買能力條文","生活指數調整利益利益","通脹條文","通脹調整條文"],a:1,e:"生活指數調整利益利益條文是抵銷將來\n因通貨膨脹可能會重大的降低壽險利益\n的購買能力"},{c:"3.6.1",s:"稱為生活指數調整利益的附約的原意是",o:["對抗物價通脹及物價通縮","對罹患終末疾病的人支付部份保額","於保險人盈利低於一般水平時，當補充紅利","以上各項皆不是"],a:3,e:"生活指數調整利益利益條文只會按通漲\n增加保險利益，所以以上情況都不正確"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保單\n，保單的持有人決定不再繳付任何保費\n有權選取的選擇"},{c:"4.8",s:"就誤報年齡或性別方面，人壽保險單通常",o:["也適用於自願變性的情況","只容許保單利益向上調整","只容許保單利益向下調整","試圖改變保單條款至以符合應有情況"],a:3,e:"若事實與安排保險時所說明的年齡或性\n別不相同，這可能對保費及／或保險利\n益產生顯著影響。"},{c:"4.2",s:"一項典型的「不可異議」條款，為其目的訂下兩年的期限，該期限稱為",o:["無訴訟期","不可異議期","可異議期","超出期"],a:2,e:"可異議期是根據「不可異議」條款，訂\n下兩年的期限，保險人可在此期間內對\n保單提出質疑或反對"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已婚者地位條\n例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非張先生就《已婚者地位條例》訂明，被保險人就自身生命購買保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有人\n如為其配偶及或其任何子女的利益而購\n買壽險單，將達到建立一個（法定信託\n的效用，從而令該配偶及或子女成為該\n保單的實益擁有人。"},{c:"4.4(c)",s:"黃生就自身生命購買壽險保單，自己為受保人，並指明他最小的兒子為該保單受益人，根據《已婚\n者地位條例》，此舉起了甚麼的法律效用?",o:["該受益人成為該保單的法定保單所有人","該受益人成為該保單的法定保單所有人，直至黃先生修訂其他受益人為止","信託效用並不用適指定子女成為受益人","該受益人成為該保單的實益擁有人"],a:3,e:"根據《已婚者地位條例》，保單持有人\n如為其配偶及或其任何子女的利益而購\n買壽險單，將達到建立一個（法定信託\n的效用，從而令該配偶及或子女成為該\n保單的實益擁有人。"},{c:"4.7",s:"若要把已失效的人壽保單復效，以下哪項不是復效條件?",o:["繳一筆復效費","保險人書面同意","繳付已到期而未繳清的保費及利息","提供可保性證明"],a:1,e:"保險人書面同意不是人壽保單復效條件"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許藉\n訂明手續來轉讓據法權產"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，擬\n轉讓的據法權產須屬現時的，而非未來\n的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許藉\n訂明手續來轉讓據法權產，而對保險合\n約的權益屬於據法權產。"},{c:"4.4(b)",s:"保單中的指定受益人有第一順位受益人及次順位受益人。第一順位受益人於受保人在生期間過身，\n受保人過世時，次順位受益人仍然在生。那麼保險金將分配給",o:["成為保單所有人的遺產","由次順位受益人所擁有","由保單所有人之繼承人所擁有","由次順位受益人及保單所有人之繼承人平均分配"],a:1,e:"以防第一順位受益人不能比受保生命活\n得久，可在第一順位受益人以外，指定\n一個或一個以上的 次順位受益人"},{c:"4.9",s:"對於一個保單所有人來說，如果他對產權的權益是復歸的，那",o:["仍未取得該項權益","雖然對產權有獲得認可的權益，財產的享用將延遲至將來的某一天或某事發生時","肯定會在將來取得該權益","該權益屬於受益人權益"],a:1,e:"復歸的權益是指對產權有獲得認可的權\n益，財產的享用將延遲至將來的某一天\n或某事發生時"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["該期間一般最少30或31天","它不適用於保單的首期保費","於寬限期內繳付保費可維持保單的保障繼續有效","於寬限期內繳付保費須另外繳付利息"],a:3,e:"於寬限期內繳付保費須被視為準時繳交"},{c:"4.3",s:"按照英式保單處理方法，如寬限期內仍未繳清保費，而保單沒有現金價值，那英式保單會於何時開\n始失效?",o:["寬限期過後","寬限期後的十四天","保費到期日後的十四天","保費到期日開始"],a:3,e:"按照英式保單處理方法，如寬限期內仍\n未繳清保費，而保單沒有現金價值，保\n單會於保費到期日開始開始失效"},{c:"4.4(b)",s:"如果已指定兩名受益人,但沒有顯示他們分別所佔的比例,在需要給付保單利益時",o:["會平均分配保險利益","第一順位受益人可取得兩倍的分配","第二順位受益人可取得兩倍的分配","第一順位受益人可取得所有保險利益"],a:0,e:"如果已指定兩名受益人,但沒有顯示他\n們分別所佔的比例,在需要給付保單利\n益時會平均分配保險利益"},{c:"4.5",s:"保單條款指出可利用保單現金價值使保單維持有效，條款稱為「不能作廢」及",o:["續保保費貸款","自動保費貸款","自動保費透支","自動清繳貸款"],a:1,e:"部分保險人視不能作廢條款，為自動保\n費貸款條款或稱保費自動墊繳條款"},{c:"4.8",s:"如果保單於提出索償時，才發現有關受保生命的真實年齡較保單顯示的為高",o:["保單自動無效","調整利益，支付比保單較低的保額","調整利益，支付比保單較高的保額","維持保額不變，退回多繳的保費"],a:1,e:"如果保單於提出索償時，才發現有關受\n保生命的真實年齡較保單顯示的為高，\n即是出現少交保費的情況，保險人會調\n整利益，支付比保單較低的保額"},{c:"4.8",s:"如果一份已簽發的壽險保單顯示受保人的年齡不正確,而該錯誤是於提出任何索償前發現,那麼以下\n哪項描述是正確的?",o:["必須取消該份保單而簽發一份新保單","其中一項選擇是支付任何差額保費(或獲退回多繳保費)","要更改保額或任何合約條款,實屬太遲","基於不可異議條款,不必有所作為"],a:1,e:"根據美式慣例，如果於提出索償後才被\n發現，保險人調整應付保險利益的金額\n或調整應付保費，以反映在根據正確的\n年齡／性別"},{c:"4.9",s:"壽險保單的絕對轉讓是指",o:["將保單轉給另一名保險人","有關保單即時變為不可異議","原有的保單所有人已被宣佈破產","不可撤銷地轉讓對某份壽險保單的一切擁有權"],a:3,e:"絕對轉讓屬永久性，不可撤銷地轉讓對\n某份壽險保單的一切擁有權"},{c:"4.10",s:"如保單所有人沒有註明紅利的選擇，保險人會自動為保單所有人將紅利存放以賺取利息或",o:["以現金支付","用以繳付未來保費","用以購買清繳增額保險","購買一年期的定期壽險"],a:2,e:"購買清繳增額保險及紅利存放保險人以\n賺取利息屬自動紅利選擇"},{c:"4.12",s:"壽險保單中的自殺條款目的在於?",o:["阻止人們自殺","把所有涉及自殺的索償無效","避免本著自殺的念頭而購買的人壽保險生效","杜絕所有涉及自殺的索償的可能性"],a:2,e:"自殺除外責任條款是為防止有人藉自殺\n來取得保險金賠償，保險人採取一些防\n範措施，也絕對是合理的。"},{c:"5.2.10&附件M",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","保險回報率","冷靜期"],a:3,e:"冷靜期不屬《重要資料聲明書－內地人\n士在港投購人身╱壽險保單》涵蓋的部\n分，詳細 研集資料手冊附件M"},{c:"5.2.3b",s:"達致高素質的顧客服務的因素是?",o:["公司文化","權力下放","A&B","以上皆不正確"],a:2,e:"公司文化及權力下放是達致高素質的顧\n客服務的因素"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個近期曾發出\n新保單的產品實現率是怎樣計算的?",o:["實現率是指按「實際派發的保證英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算","實現率是指按「實際派發英式紅利」除以銷售時「利益說明所述數額」的平均數計算。","實現率是指按「實際派發的非保證英式紅利」除以銷售時「利益說明所述數額」的平均數計算","實現率是指按「實際派發的英式紅利」除以銷售時「利益說明所承諾數額」的平均數計算"],a:2,e:"某個產品的實現率是指按「實際派發的\n非保證紅利／英式紅利」除以銷售時「\n利益說明所述數額」的平均數計算"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","銷售人員","投資風險","保險回報率"],a:2,e:"投資風險不屬《重要資料聲明書－內地\n人士在港投購人身╱壽險保單》涵蓋的\n部分，詳細參閱研集資料手冊附件M"},{c:"5.3.1(a)",s:"人壽保險根據實質危險及道德危險核保確定有關風險程度，以下哪項因素是正確的描述?",o:["與實質危險相比，道德危險較難確定","實質危險涉及較主觀的因素，環繞準被保人的基本誠信或正直意向，道德危險主要考慮到可能增\n加受保事件發生率的","實質危險主要考慮誠信因素，道德危險主要考慮家族遺傳因素","實質危險主要考慮正直意向因素，道德危險主要考慮高危職業或消閒活動因素"],a:0,e:"道德危險涉及一些較主觀的因素，實質\n危險考慮死亡發生率的客觀因素。與實\n質危險相比，道德危險較難確定"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni.它 沒有股東\nii.公 司在法律上由分紅保單所有人擁有\niii.由 董事局及高級管理層控制\niv.相 互公司不能轉變成為營利公司",o:["ii,iii,iv","i,ii","ii,iii","i,ii,iii"],a:3,e:"相互公司並不代表不能轉變成為營利公\n司，選項iv不正確。"},{c:"5.2.6",s:"以下哪項是投資壽險保單利益說明文件的具體規定獲授權保險人可選擇闡述的假設淨回報率?",o:["3%","8%","1%","以上各項皆是"],a:0,e:"投資壽險保單利益說明文件的具體規定\n獲授權保險人可選擇闡述的假設淨回報\n率是:0%, 3%,6%,9%,或較低的0%,\n2%,5%,7%"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","所有類別人壽保單","投資相連壽險計劃（“投連壽險”）保單"],a:3,e:"就保監局發出的指引28投資相連壽險計\n劃（“投連壽險”）保單可由獲授權保\n險人選擇是否發出有效利益說明"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》根據以下哪項/些機構頒布的保險核心原則而制定？",o:["國際保險監督聯會","特區政府","保險監督聯合會","國際保險業聯會及國際保險監督聯會"],a:0,e:"《承保長期保險業務(類別C業務除外)\n指引》根據國際保險監督聯會頒布的保\n險核心原則而制定"},{c:"5.3.1(a)",s:"以下哪項屬於人壽保險的核保考慮因素？原因何在？",o:["身體明顯過重是核保考慮因素，因可能與其他疾病有聯繫","在卡拉OK，酒吧或賭場工作並不屬於核保考慮因素，保險人不會就這些職業而收取 較高的保費","體重過輕不屬於核保考慮因素，因這並不涉及任何其他疾病","經營香煙業務是核保考慮因素，他們可以平價買香煙"],a:0,e:"身體明顯過重是核保考慮因素，因可能\n與其他疾病有聯繫"},{c:"5.4.1(b)",s:"以下哪項保險種類會提供「保險憑證」及「成員登記卡」？",o:["終身保險","儲蓄保險","團體保險","以上皆不是"],a:2,e:"團體保單文件涉及總保單，\n為每位受保人提供保險憑證\n，還有成員登記卡。"},{c:"5.1.1(e)",s:"下列哪項不大可能屬於保單所有人服務部的職能？",o:["通訊","收取保費","索償處理","權益管理"],a:2,e:"索償處理屬理賠部負責"},{c:"5.2.2(b)",s:"立約保費收據有另一名稱，其中TIA全名為",o:["定期被接納保險 Term Insurance accepted","臨時保險證明 Temporary Insurance acknowledge","臨時保險協議 Temporary Insurance agreement","定期保險申請 Term Insurance application"],a:2,e:"立約保費收據有另一名稱，其中TIA全\n名為臨時保險協議 Temporary\nInsurance agreement"},{c:"5.2.2(b)",s:"在非人壽保險的保單中，有類似文件以提供暫時性、不附帶條件、但可取消的保障稱爲暫保單。在\n人壽保險亦有一種類似這種的收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:1,e:"立約保費收據又叫不附帶條件保費收據\n、或可取消的保障稱爲暫保單。"},{c:"5.3",s:"風險評估、選擇、評級以及按需要附加限制條款。決定所需的再保險程度並針對個別保險情況,而\n作出適當的再保險安排,屬於哪個部門的活動?",o:["理賠部","核保部","保單條款制定部","精算部"],a:1,e:"核保部是對風險作出!評估、選擇、評\n級以及按需要附加限制條款的部門"},{c:"5.3.1",s:"核保的兩大主要階段，是確定風險程度，以及",o:["將建議風險分類","提供合適計劃","安排足夠再保險","建議次標準措施"],a:0,e:"核保的兩大主要階段，是確定風險程度\n，以及將建議風險分類"},{c:"5.3.1(b)",s:"保險人在核保時對某特定的風險，由於投保人的健康或其他因素使這些投保不可能被接受，此類核\n保稱為",o:["不承保風險","拒保風險","不可保風險","不接受風險"],a:1,e:"拒保風險是保險人不可能被接受"},{c:"5.3.2",s:"通常或曾經對投保人提供醫療護理的醫生或其他合格醫務人員被稱為",o:["護理醫生","主診醫生","體檢醫生","機密醫生"],a:1,e:"主診醫生是通常或曾經對投保人提供醫\n療護理的醫生或其他合格醫務人員"},{c:"5.3.2b",s:"保險人最常要求的醫療報告 APS 的全寫為",o:["輔助的醫療報告 (Ancillary Physical Statement)","實質醫療的聲明 (Acutal Physical Statement)","附加的醫療聲明 (Additional Physical Statement)","主診醫生報告 (Attending Physician's Statement)"],a:3,e:"主診醫生報告的英文名稱是\n(Attending Physician's\nStatement)︿簡稱APS"},{c:"5.6.2(d)(i)",s:"如果證實殺人犯是受益人的話，以下哪項法律是不會容許殺人犯本人獲益？",o:["合約法","公共政策","衡平法","人權法"],a:1,e:"如果證實殺人犯是受益人的話，根據法\n律的公共政策，是不會容許殺人犯本人\n獲益"}],"paper3-2026-01":[{c:"1.1",s:"人壽保險最初的目的為",o:["為退休後支付每個月的生活費","向被保險人的家屬提供幫助","為一名海上死亡的船員提供保障","應付短期債務之用"],a:1,e:"人壽保險的最初及最基本目的是，在被保險人或稱\n受保人去世後，尤其在早逝的情況下，很大可能會\n給受養人帶來經濟困難，人壽保險利益可向被保險\n人的家人或其他人提供幫助。"},{c:"1.1.1",s:"考慮可供選擇的人壽保險的類型時，以下哪三項可被視為人壽保險中的個人而非商業要\n求?\ni) 關鍵人物\nii) 教育經費\niii) 退休收入\niv) 受贍養者的生活開支",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii , iii , iv"],a:3,e:"關鍵人物是屬於人壽保險的商業需求"},{c:"1.2.1",s:"以下哪項保險原則是彌償的引伸?",o:["披露責任","代位權","A&B","以上皆不正確"],a:1,e:"彌償有兩個引伸，即分擔及代位權。"},{c:"1.2.1",s:"在香港，以下哪項有關人壽保險的可保權益的說明是不正確的？",o:["配偶對另一方都具有可保權益","根據法例，父母對於任何一個子女具可保權益","血緣關係能構成可保權益","監護人對未成年的受監護人足可構成可保權益"],a:1,e:"在香港，根據《保險業條例》第64A條，未成年人\n（未滿18歲的人）的父母或監護人就該年輕人享有\n可保權益。這類關係是在配偶關係以外，唯一構成\n可保權益的血緣或家庭關係。答案B不正確"},{c:"1.2.1(c)",s:"對個人及其配偶的可保權益保額是怎樣釐定的？",o:["夫婦總資產為上限","兩人的總保費","保額是無限的","配偶的收入"],a:2,e:"對個人及其配偶的可保權益保額是保額是無限的"},{c:"1.2.1(h)(iii)",s:"以下哪項有關壽險保單轉讓與可保權益法律規定的關係的陳述是正確？",o:["保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者","保單所有人一般可以將正當地安排的人壽保險合約轉讓給第三者，即使該第三者對受\n保生命缺乏可保權益","保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者","準保單所有人意圖向一受保生命購買一份壽險合約，但卻與受保生命缺乏可保權益，\n他大可以安排後者購買保單自保生命後轉讓給他，而成為轉讓保單的合法所有人"],a:1,e:"保單所有人一般可以將正當地安排的人壽保險合約\n轉讓給第三者，即使該第三者對受保生命缺乏可保\n權益仍可作出保單轉讓"},{c:"1.2.2",s:"以下哪項為最高誠信的正確描述？\ni)不期望被保人披露有理由不可能知道的情況\nii)人壽保險只要求投保人回答保險人問題時具有最高誠信\niii)免體檢的保單，投保人不用披露體檢表格內沒有問及的事情\niv)沒有欺詐而違反最高誠信，超過可異議期後可得到豁免",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],a:1,e:"最高誠信要求投保人披露所有重要事實不管保險人\n有沒有提出要求，選項ii不正確，正確答案是B"},{c:"1.2.2(d)",s:"在現行的法律及慣例下，如果需要就某一人壽保險投保單進行特殊的身體檢查，投保人\n有權知道下列哪項或哪些資料？",o:["進行什麼檢查","需要有關資料的目的","任何檢查的結果","以上所有各項"],a:3,e:"以上各項皆是投保人在進行身體檢查時有權知道的\n資料"},{c:"1.2.3(a)",s:"人壽保險近因原則",o:["從不適用於人壽保險","絕對適用於人壽保險","有時適用，尤其懷疑自殺的死亡原因","只有意外死亡利益附約時才適用"],a:2,e:"近因原則是確定死亡是否由自殺導致的重要工具，\n因為自殺僅於一段期限自殺免責期內構成除外責任"},{c:"1.3.2(b)",s:"以下哪一項不是均衡保費制度的特點？",o:["經過初期的年數，保單會累積一個現金退保價值","保費(根據相同的死亡利益不會每年增加","保費會按照被保險人到達之年齡而增加","較早的保單保費高於死亡風險所需要的金額"],a:2,e:"自然保費（釐定）制度下，保費才會按照被保險人\n到達之年齡而增加"},{c:"1.3.2a",s:"以下哪項就自然保費釐定制度的描述不正確?",o:["保險人已不再使用自然保費制度","該制度會出現不利於保險人的逆選擇","保費會隨年齡增長而增加","以上各項皆不是"],a:3,e:"以上各項都是自然保費釐定制度的正確的描述，所\n以答案D正確"},{c:"2(a)",s:"下列哪項保險產品的索償是無可避免的？\ni) 定期壽險\nii) 儲蓄壽險\niii) 終身壽險\niv) 團體壽險",o:["i, ii","ii, iii","i, iii","i, ii, iii, iv"],a:1,e:"儲蓄壽險可以現期滿，及死亡索償，終身壽險保障\n受保生命任何時候身故，所以都屬索償是無可避免\n的保險產品"},{c:"2(a)&(b)",s:"以下哪項並不屬於人壽保險的變化？",o:["分享保險人的利潤","保單所有人有權選擇轉換另一個不同的 計劃","保險公司解散時，可以分享其剩餘資產","加入各種附加條款附約，即批單"],a:2,e:"分享其剩餘資產不屬於人壽保險的變化"},{c:"2(b)",s:"普通壽險保單的基本變數可以是以下哪幾項?\ni. 普通保單可轉化為保證保單\nii. 最初只保障有限期間的壽險單可以續保\niii.保單所有人可以選擇將保單紅利轉換為公司股份\niv.可在保單中加入附加條款以獲取更多保障",o:["i, ii","iii, iv","i, ii, iv","ii, iv"],a:3,e:"可續保的及在基本保單中加入各種附加條款附約\n是人壽保險的基本變數"},{c:"2(c)",s:"向保單所有人提供意見時，保險中介人清晰地詢問向客戶能夠並且願意支付多少保費。\n對於一個負責及聲譽好的保險中介人來說，還會關注到問題是",o:["該保單的佣金率是多少","客人希望購買壽險能夠做些甚麽","朋友及其家屬是否有興趣買保險","客戶承諾在保單生效的首年不會提早終止保單"],a:1,e:"客人希望購買壽險能夠做些甚麽，對保險中介人來\n說是另一個值得關注的問題"},{c:"2.1",s:"如果對人壽保險有短暫的需求，所需的財務金額在該段時期都不會增加或減少，並且該\n需求會在指明的期間後便消失，就以保險成本為一重要的考慮因素，以下哪一項不太適\n合?",o:["定額定期壽險","非儲蓄定期壽險","分紅終身壽險","非分紅終身壽險"],a:2,e:"終身壽險的保費比定期壽險高，而分紅計劃的保費\n亦比非分紅計劃高，以保險成本為一重要的考慮因\n素，分紅終身壽險最不適合"},{c:"2.1.1",s:"以下哪項屬於儲蓄壽險合約的特點？",o:["於香港十分普遍","儲蓄壽險是不分紅的","它包含一項重大的儲蓄成份","只會於保單期滿時仍然生存才支付保額"],a:2,e:"儲蓄壽險合約它包含一項重大的儲蓄成份，並有機\n會出現死亡或期滿索償"},{c:"2.1.1(b)",s:"定期壽險保險期最短為",o:["1年","10年","20年","30年"],a:0,e:"定期壽險保險期最短為1年"},{c:"2.1.1a",s:"作為一種定期壽險，定額定期壽險",o:["以分紅形式簽發","於指定數目的學期內支付學費","是一種非常有效的儲蓄工具","受保生命在保險期內死亡，才可以獲得按保單的保額支付的保險利益"],a:3,e:"定額定期壽險是沒有現金價值，固定的死亡保險金\n額，並不會分紅形式簽發，只有選項iv是正確"},{c:"2.1.1a",s:"以下哪項有關遞減定期壽險的描述是不正確？",o:["這是定期壽險其中一種變化","現有人壽保險種類中最便宜的","適合於逐漸減少的短暫保障需求","支付的利益按保單持有人的實際需要而變化"],a:3,e:"支付的利益按保單持有人的實際需要而變化，不是\n遞減定期壽險的描述"},{c:"2.1.1a(a)",s:"下列哪項有關定額定期壽險的陳述是不正確的？",o:["它是人壽定期保險種類中保費最便宜的","有關年度保費在保險期內通常固定不變","有關利益的水平在保險期內維持不變","通常不會按分紅形式簽發"],a:0,e:"遞減定期壽險才是保險種類中保費最便宜的"},{c:"2.1.1a(b)",s:"某人供錢購買一個住宅單位。根據貸款的安排，他於十年內每年支付利息及部份本金，\n十年後便可還清該筆貸款。他打算購買最便宜的人壽保險計劃，以確保假如他在該十年\n內死亡的時候，便可由保險金支付貸款結欠。這種保險形式可能是",o:["終身壽險","定額定期壽險","儲蓄壽險","遞減定期壽險"],a:3,e:"遞減定期壽險指計劃，死亡保險金按年或其他特定\n周期遞減。它特別適合於逐漸減少的短暫保障需求\n。一些典型實例包括抵押贖回保險，目的是提供一\n筆與一項抵押貸款的遞減結欠相符的死亡保險"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言，以下哪項的說明是不正確？",o:["保險利益和保費按年或其他認可方式隨時間遞增","保費可按某百分比增加，也可按某個約定指數","續保時需要提供良好的健康証明，保額才可以增加","遞增定期壽險的目的是要抵銷通貨膨脹"],a:2,e:"遞增定期壽險所保的死亡保險金按年或按其他相隔\n期間遞增，可以按固定百分比增加，或按某個約定\n的指數，例如：綜合消費物價指數增加，答案C不\n正確"},{c:"2.1.1b(a)",s:"以下哪項或哪些是可續保定期壽險可能涉及防止逆選擇的方法？",o:["不接受續保時高於原來的保額","可能限制允許的續保次數","保險費率可能高於不可續保保單的費率","以上各項皆是"],a:3,e:"以上各項皆是可續保定期壽險可能涉及防止逆選擇\n的方法"},{c:"2.1.1b(b)",s:"駱先生大學畢業不久，沒多少錢可以用於買人壽保險，然而將於明年結婚。為什麼你認\n為他應該考慮購買可轉換定期壽險？",o:["可轉換定期壽險的保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情\n況下把保單轉為永久計劃","可轉換定期壽險給保單所有人靈活性，選擇在無須提供可保證明的情況下把保單轉換\n為更便宜的計劃","可轉換定期壽險保費頗低，又給保單所有人靈活性，選擇在無須提供可保證明的情況\n下把保單轉換為聯合壽險計劃","對年不過三十的人來說，可轉換定期壽險最適合不過"],a:0,e:"可轉換定期壽險保單所有人提供一個轉換特權，在\n毋須提供可保性健康證明的情況下將保單轉換為永\n久計劃的權利"},{c:"2.1.2",s:"儲蓄壽險的概念是指純生存保險加上",o:["定期壽險","終生壽險","家居保險","商業保險"],a:0,e:"儲蓄壽險的概念是指純生存保險加上定期壽險"},{c:"2.1.2",s:"在二十年的儲蓄壽險裏，若受保人士在第十年不久之後逝世，賠償會",o:["面額的50%","全數保額一次過即時支付","在十年後才支付","在意外死亡後才支付"],a:1,e:"儲蓄壽險承諾於受保生命活到指定期間結束時給付\n保額，但萬一受保生命在該期間內死亡，則即時給\n付保額"},{c:"2.1.3(c)",s:"有一種壽險名為等級保費保險，容許保費按一定規律(例如每三年增加)，而保額則",o:["按一定規律調整","每三年向下調整","每三年向上調整","維持不變"],a:3,e:"有一種壽險名為等級保費保險，容許保費按一定規\n律(例如每三年增加)，而保額則維持不變"},{c:"2.3.1(b)",s:"以下哪一項是香港年金的特色?",o:["最高保證年金總額","最低保證年金總額","最高年金總額","最低年金總額"],a:1,e:"香港年金的其中一項特色是提供最低保證年金總額"},{c:"2.3.1(b)",s:"保險人須在課稅年度（ 即 3月 31日）結束後的\n____天內，向保單持有人就其每張保單各別發出合資格延期年金保單的年度摘要。",o:["40","30","50","45"],a:0,e:"保險人須在課稅年度結束後的40天內，向保單持有\n人就其每張保單各別發出合資格延期年金保單的年\n度摘要。"},{c:"2.3.1b",s:"根據《合資格延期年金保單指引》，合資格延期年金保費的總額不得少於",o:["100000","150000","180000","200000"],a:2,e:"合資格延期年金保費的總額不得少於18萬元"},{c:"2.4(h)",s:"對於個別僱員離職，以下哪項關於其團體保險保單是正確的",o:["僱員可以取回就其過往已繳交的保費","僱員不可以再接受該公司提供的保障","僱員可取回過往保障的保額","團體壽險可以轉換成個人保險保單，並且通常不會要求提供可保性證明"],a:3,e:"團體壽險受保僱員離職可以轉換成個人保險保單，\n並且通常不會要求提供可保性證明"},{c:"3",s:"就保險人放棄某種權利的專業術語，會稱為",o:["放棄","豁免","優惠","免費"],a:1,e:"豁免是個自願放棄某項權利或取消某項規則的條件\n的行為"},{c:"3.1.1",s:"殘疾豁免保費附約可附加於",o:["定期壽險保單而已","分紅保單而已","終身壽險和儲蓄壽險保單","事實上適用於各類型的壽險保單"],a:3,e:"殘疾豁免保費附約可附加於幾乎所有類型的壽險"},{c:"3.1.1",s:"以下哪項或哪些是「豁免保費」附約支付利益的準則描述是正確?",o:["受保保單所有人必須死於他生前引致完全傷殘的那項成因","受保保單所有人在保單有效期內變成完全傷殘,而且已持續一段指明時間(稱為等侯期)","當受保保單所有人完全傷殘時,之前最少已經部分傷殘達到某段時間(稱為等侯期)","以上各項均不屬於該附約支付利益的準則"],a:1,e:"受保保單所有人在保單有效期內變成完全傷殘,而\n且已持續一段指明時間(稱為等侯期，一般為為3或\n6個月)"},{c:"3.1.1(b)",s:"一般應用於「豁免保費」附約的年齡限制，意思是指這種保障通常只提供予下列哪項受\n保保單所有人?",o:["15歲以下人士","65歲以上人士","18歲以上人士","年齡介乎15至65歲人士"],a:3,e:"一般應用於「豁免保費」附約的年齡限制，意思是\n指這種保障通常只提供予年齡介乎15至65歲人士"},{c:"3.1.1(d)",s:"下列哪三項較可能是豁免保費(WP)附約的除外責任？\ni. 保單生效前既存的狀況\nii. 在從事違法活動時導致的殘疾\niii.因受僱用及其過程導致的殘疾\niv. 戰爭時服兵役導致的殘疾",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"選項iii因受僱用及其過程導致的殘疾不屬是豁免\n保費(WP)附約的除外責任，只有i,ii,iv選項正確"},{c:"3.1.2",s:"以下哪項不是殘疾收入附約的常用條款?",o:["年齡限制","應付金額","等侯期","並非貸款或預繳"],a:0,e:"年齡限制不是殘疾收入附約的常用條款"},{c:"3.1.2(d)",s:"根據殘疾收入附約，支付的殘疾收入保險利益",o:["會在最後的保險金扣除","不會在最後的保險金扣除","在未來的保單紅利中扣除","實質上是從保單中的現金價值貸款"],a:1,e:"殘疾收入保險利益不是預繳或貸款，不會在死亡保\n險金扣除"},{c:"3.2",s:"AD & D英文全名為",o:["意外死亡及傷殘 accidental death & disablement","意外死亡及喪失肢體 accidental death & dismemberment","預計死亡及傷殘 anticipated death & disablement","預計死亡及喪失肢體 anticipated death & dismemberment"],a:1,e:"AD & D英文全名為意外死亡及喪失肢體\naccidental death & dismemberment"},{c:"3.2.1",s:"在意外死亡保險利益的先決條件下，死亡必須發生於意外後的一段時間，該段時間通常\n指",o:["即時","24小時内","保單期限額滿前","受傷後指定期間"],a:3,e:"意外死亡保險利益附約支付利益的準則，死亡必須\n由意外身體受傷而直接引起，並與所有其他原因無\n關並於該受傷的一年之內發生"},{c:"3.2.1(a)",s:"雙倍賠償利益是指意外死亡由身體受傷而引起",o:["保單保額雙倍賠償","保額意外的殮葬費","現金紅利的兩倍","以繳交保費兩倍的退保費"],a:0,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，這種保險利益經常被稱\n為雙倍賠償利益 (Double Indemnity Benefit)"},{c:"3.2.1(a)",s:"意外保險中，「雙倍賠償利益」在技術上不適用於人壽保險，因為",o:["導致意外的原因可能是不保事項","彌償只適用於財產保險","此利益不適用於自然死亡","給付保額實際上不是彌償，是屬於利益"],a:3,e:"這種保險利益經常被稱為雙倍賠償利益(Double\nIndemnity\nBenefit)。在這裏使用字面意思為「彌償」一詞技\n術上並不準確，因為人壽保險一般不適用彌償原則"},{c:"3.2.1(b)",s:"根據意外死亡及喪失肢體附約，經修改的保障意外死亡保險收益，保險人亦可以包括以\n下情況",o:["喪失手指或腳趾會賠償保障金額","臂部斷離會賠償保障金額","喪失單肢會賠償保障金額的一半/規定比率","單目失明會賠償兩倍保障金額"],a:2,e:"若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷給付額通常相等於意外\n死亡保險金的規定比率"},{c:"3.2.1(b)(iv)",s:"某人因一宗嚴重的交通意外而死亡。初時，傷勢只是失去兩個肢體，但該名受害人一星\n期後因傷重而死亡，如果他的人壽保單加有意外死亡及喪失肢體附約，保單將會支付",o:["保額而已","保額的2倍","保額的3倍","保額的4倍"],a:0,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項，在同一次意外事故同時引致喪失肢體\n和死亡的情況下，保單只須支付喪失肢體保險利益\n或死亡保險利益，而非同時支付兩項利益。"},{c:"3.3.1",s:"人壽保險在以下哪種情況下會根據危疾保險利益附約支付利益?",o:["受保保單所有人罹患末期疾病，預計壽命只剩下十二個月或以下","受保保單所有人罹患不可痊癒疾病，預計壽命只剩下十二個月或以下","受保保單所有人罹患末期疾病或不可識別疾病，壽命期只剩下十二個月或以下","受保保單所有人在患上末期疾病六月內死於該病"],a:0,e:"當受保保單所有人罹患末期疾病，預計壽命只剩下\n十二個月或以下，會根據危疾保險利益附約支付利\n益"},{c:"3.3.2",s:"受保保單所有人何時可獲得長期護理(LTC)附約的利益？",o:["已證實為完全殘廢","失去日常起居活動能力","預期壽命不足兩年","受保保單所有人在家中由護理員護理"],a:1,e:"當受保保單所有人失去日常活動能力(ADLs)，可獲\n得長期護理(LTC)附約的利益"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自\n願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願\n選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民\n自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認可的個人償款\n住院保險產品，供消費者自願選購，團體保險並不\n適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫療服務的消費\n者提額外的保險計劃選擇"},{c:"3.4.1(iii)(7)",s:"以下哪項是自願醫保計劃下標準計劃靈活計劃中，基本保障，額外保障及其他保障的定\n義原則?\n1. 標準計劃 - 基本保障:必須包括，額外保障:不可包括，其他保障 : (1)\n2. 靈活計劃 - 基本保障:必須包括，額外保障: (2)，其他保障 : (3)",o:["(1)不可包括,(2)必須包括,(3)可選擇包括或不包括","(1)必須包括,(2)必須包括,(3)可選擇包括或不包括","(1)可選擇包括或不包括,(2)必須包括,(3)可選擇包括或不包括","(1)可選擇包括或不包括, (2)必須包括, (3)不可包括"],a:2,e:"詳細可參閱研習資料手冊參考章節\n3.4.1(iii)(7)自願醫保標準計劃和靈活計劃定義\n原則說明表格"},{c:"3.5.1",s:"以下哪項是保證可保選擇的特點?",o:["限制","非自動獲得","指定事件","以上各項皆是"],a:3,e:"以上各項皆是保證可保選擇的特點"},{c:"3.5.1",s:"有關保證可保選擇，容許受保人作出購買增額保障的選擇，以下那項描述是不正確的?",o:["自動獲得增額保障的選擇","如不及時作出選擇，便會喪失權利","部分保險人於備擇日期內提供定期壽險","只可在指定限期內作出選擇"],a:0,e:"保單所有人如果錯過了行使已觸發的選擇權以購買\n增額保障的話，就會喪失該次權利，答案A不正確"},{c:"3.5.1(a)",s:"保證可保利益的定義為",o:["保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明","保單所有人有權在任何時候購買增額保險，無需遞交可保證明","保單所有人有權在指定的備擇日期購買增額保險，必需遞交可保證明","保單所有人有權在任何時候購買增額保險，必需遞交可保證明"],a:0,e:"保證可保利益的保單所有人有權在指定的備擇日期\n購買增額保險，無需遞交可保證明"},{c:"3.6",s:"通貨膨脹對下列哪項保單的實質價值帶來負面影響？\ni) 保額\nii) 保費\niii) 利益\niv) 現金價值",o:["i , iv","i , iii","i, ii , iii","i, iii , iv"],a:1,e:"通貨膨脹足以降低貨幣的購買力，它是任何指明保\n額長期保險必須考慮的一個重要因素。選項i ,\niii正確"},{c:"3.6.1",s:"稱為生活指數調整利益的附約的原意是",o:["對抗物價通脹及物價通縮","對罹患終末疾病的人支付部份保額","於保險人盈利低於一般水平時，當補充紅利","以上各項皆不是"],a:3,e:"生活指數調整利益利益條文只會按通漲增加保險利\n益，所以以上情況都不正確"},{c:"4",s:"在死亡索償中,在哪種情況下,死因對索償來說屬於重要事項?",o:["該份保單設有意外死亡保險利益附約","自殺條款可能仍然生效","受益人謀殺受保生命","以上所有各項"],a:3,e:"在死亡索償中,在以上所有各項情況下,死因對索償\n來說屬於重要事項"},{c:"4.1",s:"以下哪項關於「完整合約」條款的描述是不正確的？",o:["完整合約包括保單正本、任何夾附的附約及投保單的複印本","只有在保單所有人同意下才可更改保單","只有保險公司的指定高級職員才有權對保單作出更改","保單的內容已是一份完整的合約，並不包括其他文件"],a:3,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保單複印本構成。"},{c:"4.2",s:"一項典型的「不可異議」條款，為其目的訂下兩年的期限，該期限稱為",o:["無訴訟期","不可異議期","可異議期","超出期"],a:2,e:"可異議期是根據「不可異議」條款，訂下兩年的期\n限，保險人可在此期間內對保單提出質疑或反對"},{c:"4.2",s:"某項保單條文規定受保生命仍然生存期間，保單已經生效最少兩年的話，不涉及任何欺\n詐行為的情況下，保險人不能以違反最高誠信原則為理由而推翻合約 ，稱為",o:["復效條款","不能作廢條款","不可異議條款","完整合約"],a:2,e:"某項保單條文規定受保生命仍然生存期間，保單已\n經生效最少兩年的話，不涉及任何欺詐行為的情況\n下，保險人不能以違反最高誠信原則為理由而推翻\n合約，稱為不可異議條款"},{c:"4.4",s:"保單一般會指定受益人可能是一個群體，例如：「我的子女」，這種方式稱為",o:["概括式指定","次順位受益人","不可撤換受益人","團體保單"],a:0,e:"指定受益人可能是一個群屬體概括式指定"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已\n婚者地位條例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非張先生就《已婚者地位條例》訂明，被保險人就自身生命購買保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽\n保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保單，保單的持\n有人決定不再繳付任何保費有權選取的選擇"},{c:"4.5",s:"對於停止供款的保單持有人，保單條文訂明了若干權力，以下哪項不正確？",o:["接受一份減額清繳保險","退保以取回保單內的現金價值","以現金價值購買一份定期壽險","要求保險人發放免息貸款以繳交保費"],a:3,e:"如果具有現金價值或紅利價值的保單，，要求保險\n人發放免息貸款以繳交保費，不是持有人決定不再\n繳付任何保費下，有權選取的選擇"},{c:"4.6",s:"以下哪項對保單抵押貸款條款的描述是不正確的?",o:["貸款金額上限為現金價值（扣除一年貸款利息）","貸款用途必須經保險人許可","要求使用保單抵押貸款,是在保單上列名的保單所有人的權利","有關利息可在保單利益應付時償還"],a:1,e:"保單抵押貸款條款貸款用途並無限制，答案B不正\n確。"},{c:"4.6",s:"哪一項是有關典型壽險保險的保單抵押貸款條款的正確陳述？",o:["借款用途無任何限制","保單持有人有權向保險人借入款項","貸款需要的抵押是保單的現金價值","以上各項皆是"],a:3,e:"以上各項皆是典型壽險保險的保單抵押貸款條款的\n正確陳述"},{c:"4.6",s:"下列哪項或哪些屬於保單抵押貸款中慣用條文的特點?",o:["該筆貸款必須用於繳交未來的保費","該筆貸款唯一需要的抵押品就是保單的定期保險","於保單生效期內可以償還或不償還該筆貸款","保單的貸款由保險人決定"],a:2,e:"保單所有人自行決定還款多少和何時償還，\n未償還貸款額，包括任何未償還利息會從應付的死\n亡保險金或退保價值中扣除"},{c:"4.7",s:"一份壽險保單的復效",o:["是違法的","適用於已失效或退保的保單","有條件性的限制,是保單條文中的一項權利","只可在保險人於復效時同意的一刻進行"],a:2,e:"一份壽險保單的復效需符合某些條件性的限制,是\n保單條文中保單所有人的一項權利"},{c:"4.8",s:"因混淆外國人名字，人壽保單簽發一段時間後，才發現該保單將女性受保人誤以為是男\n性，經相討後，如果保單所有人願意支付相同的保費金額，保險人會作出以下哪項修改\n？",o:["退還由投保當日起計的所有保費","將保單保額調高","調低保單保額，以反映已繳付保費相符的正確保額","調高保費，以反映保單少付的保費"],a:1,e:"保單將女性受保人誤以為是男性，因女性保費率比\n男性為低，如果保單所有人願意支付相同的保費金\n額，保險人便會將保單保額調高"},{c:"4.8",s:"如果於保單簽發後數年(在出現索償前)發現有關受保生命的真實年齡較保單顯示的高",o:["有關保單便自動宣告無效","由於保單已是不可異議，因此無須作任何修改","便必須調整有關保額或保費的其中一項","便取消有關保單，並退回全部保費"],a:2,e:"如果於保單簽發後數年(在出現索償前)發現有關受\n保生命的真實年齡較保單顯示的高，保險人便必須\n調整有關保額或保費的其中一項"},{c:"4.9",s:"下列哪項屬於壽險保單的轉讓限制？",o:["有關轉讓不能因為非法目的而安排","規定只能以一次過整筆支付保單利益","不得侵犯任何受益人的既得權利","以上各項皆是"],a:3,e:"以上各項皆是轉讓保單的限制"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許藉訂明手續來\n轉讓據法權產"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，擬轉讓的據法\n權產須屬現時的，而非未來的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許藉訂明手續來\n轉讓據法權產，而對保險合約的權益屬於據法權產\n。"},{c:"4.9",s:"壽險保單的絕對轉讓是指",o:["將保單轉給另一名保險人","有關保單即時變為不可異議","原有的保單所有人已被宣佈破產","不可撤銷地轉讓對某份壽險保單的一切擁有權"],a:3,e:"絕對轉讓屬永久性，不可撤銷地轉讓對某份壽險保\n單的一切擁有權，抵押轉讓安排是暫時性的，通常"},{c:"4.10",s:"如果保單所有人沒有作出選擇，“自動紅利選擇”是指",o:["以現金方式支付","儲存於保險人處以賺取利息或購買清繳增額保險","用以購買保險公司股份","用紅利繳付未來保費"],a:1,e:"“自動紅利選擇”是指儲存於保險人處以賺取利息\n或購買清繳增額保險"},{c:"4.11(e)",s:"終身收益選擇，是分期支付約定的保單收益(及利息)，這項選擇實際上是以該項保單收\n益作為整付保費，購買了甚麼?",o:["儲蓄壽險","投資相連壽險","終身年金","終身壽險"],a:2,e:"這項選擇實際上是以該項保單收益作為整付保費，\n購買一份終身年金"},{c:"4.11",s:"下列哪項或哪些不屬於壽險保單的賠付選擇？",o:["通常是整筆過支付","將收益保留在保險人處以賺取利息","用以購買為期一年的定期壽險","保險人分期給付約定等額"],a:2,e:"用以購買為期一年的定期壽險不屬於壽險保單的賠\n付選擇"},{c:"4.12",s:"壽險保單中常用的自殺條款",o:["列明任何時間發生的自殺為除外責任","列明保單生初期﹝通常一年的時間﹞發生的自殺為除外責任","發生這類事件時便會把該保單的保額減低百分之五十","將自殺視作意外處理，而雙倍賠償亦告適用"],a:1,e:"壽險保單中常用的自殺條款列明保單生初期﹝通常\n一年的時間﹞發生的自殺為除外責任"},{c:"4.12",s:"由自殺引至死亡發生，如果保單在死亡前不久訂立，要知道死亡是不由自殺所引致，這\n工作由下列誰人負責？",o:["警察","保險人","受益人","保單所有人"],a:1,e:"證明死亡是由自殺引起的舉證責任便落在保險人身\n上"},{c:"5.1(a)",s:"以下哪項是對「相互」保險公司的正確描述？\ni. 它沒有股東\nii. 公司在法律上由分紅保單所有人擁有\niii. 由董事局及高級管理層控制\niv. 相互公司不能轉變成為營利公司",o:["ii,iii,iv","i,ii","ii,iii","i,ii,iii"],a:3,e:"相互公司並不代表不能轉變成為營利公司，選項iv\n不正確。"},{c:"5.1(a)",s:"某些保險公司的名稱含有「相互」的字眼，而該公司是有股東的，該公司已進行了一個\n過程，稱為︰",o:["資本化","股份化","股份登記","不分紅成員確認"],a:1,e:"世界各地的「相互公司」都陸續進行股份化的轉變\n，並將其法定地位變成了營利公司（或稱股份公司\n）"},{c:"5.1.1(a)",s:"保險公司會計部的主要職能和責任包括：\ni) 記錄公司收入\nii) 監管公司支出\niii) 提交已審核的財務報告\niv) 處理電話投訴",o:["i, ii 及 iii","i, iii 及 iv","ii, iii 及 iv","以上各項都是"],a:0,e:"處理電話投訴不屬保險公司會計部的主要職能和責\n任"},{c:"5.2.1(a)",s:"以下哪項或哪些為填寫投保書的一般規則？",o:["必須披露所有重要事實","不得修改","必須見證","以上各項皆是"],a:0,e:"投保單是唯一的核保所需的資料來源，在填寫投保\n單時，保險中介人應該特別留意自己對客戶所提供\n的建議和幫助，提醒客戶提供所有重要事實"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["整個銷售過程必須在香港境內進行","回佣協議","政策改變","投資風險"],a:3,e:"投資風險不屬《重要資料聲明書－內地人士在港投\n購人身╱壽險保單》涵蓋的部分，詳細參閱研集資\n料手冊附件M"},{c:"5.2.11",s:"根據送贈禮品指引（指引25），以下哪項不屬內指明的許可禮品?",o:["身體檢查服務","醫療咨詢服務","緊急救助支援","超市禮券"],a:3,e:"超市禮券，不屬（指引25）內指明的許可禮品"},{c:"5.2.2(b)",s:"就立約保費收據而言，下列哪三項是正確的?\ni)它們亦稱為不附條件保費收據\nii)它們構成一份獨立於任何其後簽發之保單的合約\niii)是否提供保障並不以投保人的可保性為條件\niv)如果事後證明投保人為不可保，便可取消有關保障",o:["i , ii , iii","i , ii , iv","i , iii , iv","ii , iii , iv"],a:0,e:"立約保費收據收據本身是一份合約，保障由投保人\n簽署投保單並繳清有關保費之日開始生效，選項iv\n不正確"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","具現金價值的保單","展期保險保單"],a:3,e:"對於額清繳保險保單及展期保險保單，非分紅保單\n；及\n投資相連壽險計劃保單而言，可由保險人選擇是否\n發出有效利益說明"},{c:"5.2.6",s:"就於下列哪項類別的人壽保險保單而言，可由獲授權保險人選擇是否發出有效利益說明?",o:["清繳保險保單","分紅保單","所有類別人壽保單","投資相連壽險計劃（“投連壽險”）保單"],a:3,e:"就保監局發出的指引28投資相連壽險計劃（“投連\n壽險”）保單可由獲授權保險人選擇是否發出有效\n利益說明"},{c:"5.2.7a",s:"指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，必須以清晰及統\n一的計算方式及披露方式向客戶準確披露以下哪項的資料？",o:["非保證紅利／英式紅利實現率及過往派息率","承保長期保險的回報率及收益率","非保證預期紅利率及過往派息比率","承保分紅保單的預期紅利率及過往派息率"],a:0,e:"指引16的規定，銷售分紅（或有利潤）保單或萬用\n壽險保單的保險人，必須以清晰及統一的計算方式\n及披露方式向客戶準確披露非保證紅利／英式紅利\n實現率及過往派息率"},{c:"5.2.7a",s:"下面有關宣佈紅利金額的陳述中，哪項是正確的？\ni.保險人一般會將紅利平均派發，以減低短期大幅波動\nii.紅利金額是基於獲委任精算師的意見而釐定的\niii.紅利金額是基於獲委任精算師的意見，並經董事會批准而釐定\niv.保險人一般保留釐定紅利金額的權利",o:["i,ii","ii,iii","i,iii,iv","i, iii"],a:2,e:"保險人一般保留釐定紅利金額的權利。紅利金額是\n基於獲委任精算師的意見，並經董事會批准而釐定\n的。保險人可因應政策決定平均派發的方法，選項\nii不正確"},{c:"5.2.7b",s:"派發紅利方式共有三種，其中一種是",o:["即時紅利","期終額外紅利","延遲紅利","以上各項皆是"],a:1,e:"在香港，保單紅利一般是透過三種方式派發的，分\n別是派發現金紅利，復歸紅利及期終額外紅利"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》根據以下哪項/些機構頒布的保險核心原則\n而制定？",o:["國際保險監督聯會","特區政府","保險監督聯合會","國際保險業聯會及國際保險監督聯會"],a:0,e:"《承保長期保險業務(類別C業務除外)指引》根據\n國際保險監督聯會頒布的保險核心原則而制定"},{c:"5.2.8",s:"根據《承保長期保險業務(類別C業務除外)指引》,銷售有關萬用壽險的保險人必需予以\n披露",o:["未來的預期派息率","過往派息率","非保證紅利的實現率","保險人所提供的保證息率"],a:1,e:"根據指引16,銷售有關萬用壽險的保險人必需予以\n披露過往派息率"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個\n近期曾發出新保單的產品系列的非保證紅利/英式紅利實現率是怎樣計算的?",o:["某個產品的實現率是指按「實際派發的保證紅利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「實際派發的非保證紅利/英式紅利」除以銷售時「利益說明\n所述數額」的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所承諾數額」\n的總額計算。"],a:1,e:"某個產品的實現率是指按「實際派發的非保證紅利\n/英式紅利」除以銷售時「利益說明所述數額」的\n平均數計算。"},{c:"5.2.8",s:"《承保長期保險業務(類別C業務除外)指引》由哪個機構制訂?",o:["香港保險業聯會","國際保險業聯會","保險監督聯會","保險業監管局"],a:3,e:"《承保長期保險業務(類別C業務除外)指引》由保\n險業監管局制訂"},{c:"5.3.1",s:"核保的過程主要針對風險的評估，包括哪個或哪些風險程度？",o:["只有實際危險","只有道德危險","實質危險及道德危險","既非實際危險亦非道德危險"],a:2,e:"人壽保險核保人憑經驗可以確定投保的風險程度，\n包括確定實質危險及道德危險"},{c:"5.3.1",s:"與技術性核保相比，財務性核保較為著重保險的金額，尤其關於下列哪項或哪些?",o:["預期受保保單所有人繳付保費的能力","審慎保險人需安排再保險的可能性","就一個人已累積購買的保單計劃","以上各項均需考慮"],a:3,e:"以上各項都是財務性核保均需考慮的因素"},{c:"5.3.1(b)",s:"以下哪幾種是人壽保險的風險類型︰\ni) 標準風險\nii) 次標準風險\niii) 拒保風險\niv) 優質風險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"優質風險不是人壽保險的風險類型，只有選項i,\nii, iii正確"},{c:"5.4",s:"人壽保險保單的準備及交付十分重要，因為",o:["只適用於替配偶購買保單","以防競爭者將來有一套較有效律的制度","避免將來的麻煩","保單的更改需要保單所有人的同意，否則不可更改或取消"],a:3,e:"人壽保險保單的準備及交付十分重要，因為保單的\n更改需要保單所有人的同意，否則不可更改或取消"},{c:"5.6.2",s:"以下哪項是一項法律原則容許法庭對有損害公眾利益或公共秩序的傾向的行為或交易，\n可予以廢除或不接受?",o:["程序不當","政策公正","公共政策","以上各項皆不是"],a:2,e:"在大部分情況下，如果證實殺人犯是受益人的話，\n法律「公共政策」是不會容許殺人犯本人獲益的"}],"paper3-2026-02":[{c:"1.1",s:"人壽保險的最初目的是",o:["為某人在某段時間內死亡提供整筆金錢","為英年早逝死亡提供整筆金錢","為退休人士提供金錢的儲蓄","為某人早逝死亡時為其家人提供一筆金錢"],a:3,e:"人壽保險的最初目的是為某人早逝死亡時為其家人\n提供一筆金錢"},{c:"1.1",s:"人壽保險合約最初類型",o:["本質上屬於短暫的，以保障早逝情況","本質上屬於長久的，即直至死亡","與物業抵押貸款有關","屬單位相連的安排"],a:0,e:"最初，保險單有效期較短，只為暫時性的風險情況"},{c:"1.1.1",s:"下列哪項為壽險保單商業需求而非個人需求？",o:["合夥人","教育經費","應急資金","受養者生活開支"],a:0,e:"關鍵人物人壽保險就某公司員的生命購買保險，以\n補償公司由於該要員的死亡而帶來的損失。生意合\n夥人就是其中例子"},{c:"1.2.1(e)",s:"在美國及美洲，家庭關係本身可構成可保權益，在香港",o:["情況一樣","其中家庭成員構成可保權益只限於配偶","任何情況下均不可能","家庭成員構成可保權益是受到更多的限制"],a:3,e:"例如只有未成年人（未滿18歲的人）的父母或監護\n人就該年輕人享有可保權益。這類關係是在配偶關\n係以外，唯一構成可保權益的血緣或家庭關係。"},{c:"1.2.1(h)",s:"丈夫為自己生命投買了一份保險，保單的受益人為其妻子。兩年後，他們離婚，但丈夫\n仍有繼續供款。後來丈夫離世，妻子可否獲得賠償？",o:["不可以，因為離婚後，妻子對丈夫的生命沒有可保權益","可以索取全部保額","可以取回已交保費","可以索取一半保額的賠償"],a:1,e:"人壽保險只有在合約開始時才需要可保權益，夫妻\n中任何一方為其配偶的生命投保後，即使離婚，仍\n可維持保單的有效性，而且完全有權在適當時候收\n取利益。"},{c:"1.2.1(h)",s:"以下哪一項說明是不正確的?",o:["人壽保單可以轉讓予某個對受保生命不具可保權益的人","人壽保單可以轉讓予某個對受保生命不具可保權益的人，但受保生命必須並非一名破\n產人","不論承讓人是否具有可保權益，人壽保單不可以轉讓","以上所有皆不正確"],a:2,e:"保單所有人一般可以將正當地安排的人壽保險合約\n轉讓給第三者，即使該第三者對受保生命缺乏可保\n權益仍可作出保單轉讓"},{c:"1.2.1(h)(iii)",s:"以下哪項有關壽險保單轉讓與可保權益法律規定的關係的陳述是正確？",o:["保單所有人是不能將壽險合約轉讓給缺乏可保權益的第三者","保單所有人一般可以將正當地安排的人壽保險合約轉讓給第三者，即使該第三者對受\n保生命缺乏可保權益","保單所有人需透過另外一份合約才可將壽險合約轉讓給第三者","準保單所有人意圖向一受保生命購買一份壽險合約，但卻與受保生命缺乏可保權益，\n他大可以安排後者購買保單自保生命後轉讓給他，而成為轉讓保單的合法所有人"],a:1,e:"保單所有人一般可以將正當地安排的人壽保險合約\n轉讓給第三者，即使該第三者對受保生命缺乏可保\n權益仍可作出保單轉讓"},{c:"1.2.2",s:"下列哪項肯定屬於投保人必須披露的重要事實",o:["與實質物件(財產)的保險有關的事實","會影響一名審慎的保險人訂定保費或決定是否承擔風險方面判斷的事實","可能影響一名審慎的核保人就一項特定風險釐定保費的判斷的事實","被保險人向保險人披露的重要事實"],a:1,e:"重要事實是會影響一名審慎的保險人訂定保費或決\n定是否承擔風險方面判斷的事實"},{c:"1.2.3(a)(ii)",s:"下列哪項關於彌償的陳述是正確的？",o:["除非由法律隱含，否則彌償不存在於人壽保險","法律不容許人壽保險作出彌償","不可能對喪失生命作出超額彌償","五十年前，彌償普遍存在於人壽保險"],a:2,e:"人壽保險亦稱為利益保單，不可能超額賠償，因為\n人壽保險可保權益在大多數情況下是無限的"},{c:"1.3.2c",s:"下列哪項可以歸因保單於均衡保費釐定制度下多繳的「剩餘」保費?\ni. 現金價值\nii. 保單抵押貸款\niii. 清繳保險\niv. 不能作廢條文",o:["i, ii, iii","ii, iii, iv","i,ii,iv","i,ii,iii,iv"],a:3,e:"以上皆是均衡保費釐定制度下多繳的「剩餘」保費\n導致的長期後果"},{c:"2(a)",s:"下列哪一項較不可能出現於人壽保險合約的基本形式功能範圍？",o:["為特定時間內發生死亡給付死亡金","為指定時期內發生死亡給付死亡金","為特定原因內發生死亡給付死亡金","於某一特定日子或以前發生死亡給付死亡金"],a:2,e:"人壽保險合約一般不會為特定原因發生的死亡給付\n死亡金"},{c:"2(b)",s:"普通壽險保單的基本變數可以是以下哪幾項?\ni. 普通保單可轉化為保證保單\nii. 最初只保障有限期間的壽險單可以續保\niii.保單所有人可以選擇將保單紅利轉換為公司股份\niv.可在保單中加入附加條款以獲取更多保障",o:["i, ii","iii, iv","i, ii, iv","ii, iv"],a:3,e:"可續保的及在基本保單中加入各種附加條款附約\n是人壽保險的基本變數"},{c:"2(b)",s:"早期的基本壽險就死亡賠付一筆金額，當中這些基本計劃是可以存在變化的，這些是",o:["可參與及分享保險人的利潤","按保單持有人的選擇，轉換為另一類計劃的可轉換性","加以附約(批單)，以增加保障範圍","以上所有各項"],a:3,e:"以上所有各項都是基本壽險可以存在變化"},{c:"2.1",s:"如果對人壽保險有短暫的需求，所需的財務金額在該段時期都不會增加或減少，並且該\n需求會在指明的期間後便消失，就以保險成本為一重要的考慮因素，以下哪一項不太適\n合?",o:["定額定期壽險","非儲蓄定期壽險","分紅終身壽險","非分紅終身壽險"],a:2,e:"終身壽險的保費比定期壽險高，而分紅計劃的保費\n亦比非分紅計劃高，以保險成本為一重要的考慮因\n素，分紅終身壽險最不適合"},{c:"2.1.1a",s:"遞減定期壽險指",o:["利益每年遞減","保險費每年遞減","利益與保險費每年遞減","付給代理人的佣金每年遞減"],a:0,e:"遞減定期壽險指計劃，死亡保險金按年或其他特定\n周期遞減。在整個保險期內，年保費的水平通常維\n持不變。"},{c:"2.1.1a(b)",s:"以下哪類保險的特色是保險額可按需求而遞減的？\ni 信用壽險\nii 遞減定期壽險\niii 抵押贖回保險\niv 家庭收入壽險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"以上皆是遞減定期壽險的種類，滿足逐漸減少的短\n暫保障需求。"},{c:"2.1.1a(b)",s:"以下哪項描述抵押贖回保險是不正確的？",o:["保障形式與按揭賠償保險相同","可以聯名(例如：夫婦)形式為基礎","用來繳付未清還的貸款結欠","保障形式是為個人而設，並非銀行及貸款給銀行"],a:0,e:"按揭賠償保險並不屬遞減定期壽險，與抵押贖回保\n險不相同"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言，以下哪項的描述是正確的？",o:["這是一項目的為抵銷通貨膨脹的條款","保險利益和保費按年或其他協訂方式隨時間遞增","保費按所保利益水平的增加的比例增加","以上各項皆正確"],a:3,e:"以上各項皆是遞增定期壽險的正確描述"},{c:"2.1.1a(c)",s:"就遞增定期壽險而言，以下哪項的說明是不正確？",o:["保險利益和保費按年或其他認可方式隨時間遞增","保費可按某百分比增加，也可按某個約定指數","續保時需要提供良好的健康証明，保額才可以增加","遞增定期壽險的目的是要抵銷通貨膨脹"],a:2,e:"遞增定期壽險所保的死亡保險金按年或按其他相隔\n期間遞增，可以按固定百分比增加，或按某個約定\n的指數，例如：綜合消費物價指數增加，答案C不\n正確"},{c:"2.1.2",s:"如果保單所有人同是受保人,以下哪項壽險他最有可能且期待索償的?",o:["定期壽險","儲蓄壽險","分紅終身壽險","不分紅終身壽險"],a:1,e:"儲蓄壽險索償會在保單期滿時或之前，即受保命在\n該期間內死亡時出現"},{c:"2.2.1",s:"以下哪項屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","「分別列示各定價因素」","以上各項皆是"],a:3,e:"以上皆是萬用壽險的特點"},{c:"2.2.1(a)",s:"以下哪項不屬於萬用壽險的特點？",o:["靈活保費","可調整的保單利益","披露因營運開支而徵收的附加保費","自動按年增加的保額"],a:3,e:"萬用壽險不會自動按年增加的保額"},{c:"2.2.1(b)",s:"萬用壽險增加或減少保額",o:["必需提交可保性證明","如增加保額，需提供可保性證明","如減少保額，需提供可保性證明","如增加保額後第二年後提出索償，該次索償則屬無效"],a:1,e:"萬用壽險如增加保額，需提供可保性證明"},{c:"2.2.2",s:"以下哪項是單位相連長期保單的基礎？",o:["保費與單位基金表現掛鈎","保額與單位基金表現掛鈎","保單價值與單位基金表現掛鈎","保額是單位的基本"],a:2,e:"單位相連長期保單的保單價值與單位基金表現掛鈎"},{c:"2.3(a)",s:"一種由人壽保險公司提供的合約，涉及向保險人作出一筆過的付款﹝或一連串付款﹞，\n以換取在他/她餘下有生之年內，定期取得款項。這種合約稱為",o:["年金","儲蓄壽險","分紅保險","不分紅保險"],a:0,e:"涉及向保險人作出一筆過的付款﹝或一連串付款﹞\n，以換取在他/她餘下有生之年內，定期取得款項\n。這種合約稱為年金合約"},{c:"2.3.1",s:"在_________內，保單持有人在一段時間內定期繳付保費，讓保險人通過投資令已付金額\n增長。",o:["累積期","延遲時間","年金期","以上各項皆不是"],a:0,e:"延期年金計劃在累積期內，保單持有人在一段時間\n內定期繳付保費，讓保險人通過投資令已付金額增\n長"},{c:"2.3.1(a)",s:"香港的年金計劃是",o:["延期終身年金計劃","退休延期終身年金計劃","經稅務局批准的即期終身年金計劃","以上皆不是"],a:3,e:"香港的年金計劃是即期終身年金計劃，以上皆不正\n確"},{c:"2.3.1(b)",s:"保險人須在課稅年度（ 即 3月 31日）結束後的\n____天內，向保單持有人就其每張保單各別發出合資格延期年金保單的年度摘要。",o:["40","30","50","45"],a:0,e:"保險人須在課稅年度結束後的40天內，向保單持有\n人就其每張保單各別發出合資格延期年金保單的年\n度摘要。"},{c:"2.3.1(d)",s:"以下哪項是年金的核保特色?\ni. 女性收取的定期年金高於相同年齡的男性\nii. 年金核保以生存率為基礎\niii. 年金核保須要驗身報告\niv. 年金利益付款開始時的年齡越高，毎一期年金利益付款便越高",o:["i,ii","ii,iv","i,ii,iii","i,iii,iv"],a:1,e:"因為女性預期壽命比男性長，女性所收取的定期年\n金低於相同年齡的男性，年金核保並無提及必須要\n提供驗身報告，年金核保以生存率為基礎，年金利\n益付款開始時的年齡越高，毎一期年金利益付款便\n越高，只有選項ii,iv正確"},{c:"2.4",s:"下列哪項正確描述團體保險計劃?",o:["所有僱員不能從團體保單轉換為個人保險保單","每個受保僱員須詳細審核","保費相等於個別受保僱員保費之總和","團體保險計劃可以是僱員福利計劃的其中一種"],a:3,e:"團體保險計劃可以是僱員福利計劃的其中一種，計\n劃通常不會要求詳細的個人資料，某些計劃允許個\n人從團體保險保單轉為個人保單，並且通常不會要\n求提供可保性證明 。"},{c:"2.4(e)",s:"以下有關團體壽險保單在核保的審核正確的是？",o:["團體計劃通常不會要求詳細的個人資料","團體計劃通常要求詳細的家族病歷","團體計劃通常要求詳細的個人核保","團體計劃的個人保費通常高於個人保險的累積保費"],a:0,e:"團體計劃通常不會要求詳細的個人資料"},{c:"3",s:"就保險人放棄某種權利的專業術語，會稱為",o:["放棄","豁免","優惠","免費"],a:1,e:"豁免是個自願放棄某項權利或取消某項規則的條件\n的行為"},{c:"3.1.1",s:"「殘疾豁免保費」附約規定？",o:["如果受保保單所有人完全傷殘，保險人會豁免傷殘期間的保費","如果在受保保單生效6個月以上，保單所有人完全傷殘，保險人會豁免傷殘期間的保費","失業期間豁免支付保費","如其他保險人提供較低的保費率，保險人便會退回保費"],a:0,e:"殘疾豁免保費附約承諾在受保保單所有人完全傷殘\n時放棄其收取續保保費的權利。這並不代表保單被\n中止，保單將依然有效，因此，保單將會繼續產生\n現金價值及紅利，猶如保單所有人已如期支付了保\n費 。"},{c:"3.1.1(a)",s:"就豁免保費附約中的等候期而言，下列哪項不正確？",o:["該時期可以是3個月","只會在等候期內獲得豁免保費","等候期可能屬於也可能不屬於起賠期限","如果殘疾於等候期內康復，便不會獲得豁免保費"],a:1,e:"受保保單所有人一旦根據保單的定義完全傷殘達最\n低期限\n（通常為三或六個月）後他將獲豁免支付續保保費\n，選項ii不正確"},{c:"3.1.1(a)",s:"下列哪項或哪些對豁免保費附約的陳述是正確的?",o:["在受保保單所有人失業期間,保險人豁免有關保險","在完全殘疾的情況下豁免有關保費,而保障取消","在受保保單所有人完全殘疾期間,保險人豁免有關保費","以上所有各項"],a:2,e:"殘疾豁免保費是指受保保單所有人根據保單的定義\n完全傷殘達最低期限（通常為三或六個月）他將獲\n豁免支付續保保費。(超過等候期開始豁免保費)，\n答案C正確"},{c:"3.1.1(c)",s:"就變更支付保費頻率，殘疾豁免保費附約的規定是",o:["在任何時候，所有更改都不允許","在任何情況，所有更改也允許","在傷殘保險期間，不得更改保費頻率","在傷殘保險期間，按月繳保費頻率可轉為年繳保費頻率"],a:2,e:"就變更支付保費頻率，殘疾豁免保費附約的規定在\n傷殘保險期間，不得更改保費頻率"},{c:"3.1.2(d)",s:"以下哪項描述殘疾收入附約中的收入保險利益是正確的？",o:["保險利益會在保額中扣除","保險利益不會在保額中扣除","保險利益會在保單未來紅利中扣除","保險利益其實是未來保費的保單貸款"],a:1,e:"殘疾收入所支付的利益並非貸款或預繳，不會於死\n亡保障額中扣除"},{c:"3.2",s:"經常附加於壽險保單的一系列的意外死亡及喪失肢體附約設有多種限制，當中可以找到\n的除外責任包括",o:["生育及懷孕引起的傷殘","參與違法活動時造成的傷殘","參與危險運動時造成的傷殘","以上各項皆正確"],a:3,e:"以上各項都是意外保險利益的其他利益意外死亡及\n喪失肢體附約的除外責任"},{c:"3.2",s:"AD & D附約就下列哪項提供了額外利益？",o:["只限於意外死亡","意外死亡及殘疾 (每月支付)","意外死亡或列明的疾病而導致死亡","意外喪失肢體及死亡(按照有關定義)"],a:3,e:"意外保險利益通常附加於與意外死亡及喪失肢體有\n關的任何種類的壽險保單。它們通常被歸納為一個\n單一的附約，稱之為意外死亡及喪失肢體\n(AD&D)附約，答案D正確"},{c:"3.2.1(a)",s:"就意外保險而言，近因的應用為何這樣重要？",o:["死亡及喪失兩肢時，會作出雙倍賠償","意外事故導致受保生命喪失單肢或單目失明，會作出雙倍賠償","喪失兩肢時，會作出雙倍賠償","因為只有意外死亡，才會作出雙倍賠償利益"],a:3,e:"意外死亡保險利益附約一般承諾，於意外導致死亡\n的情況下，額外支付一筆與基本保單的保額相等的\n保險利益，而死亡必須由意外身體受傷而直接引起\n，並與所有其他原因無關，近因對這種附約顯得非\n常重要，因為只有意外死亡，才會作出雙倍賠償利\n益"},{c:"3.2.1(a)",s:"意外保險中，「雙倍賠償利益」在技術上不適用於人壽保險，因為",o:["導致意外的原因可能是不保事項","彌償只適用於財產保險","此利益不適用於自然死亡","給付保額實際上不是彌償，是屬於利益"],a:3,e:"這種保險利益經常被稱為雙倍賠償利益(Double\nIndemnity\nBenefit)。在這裏使用字面意思為「彌償」一詞技\n術上並不準確，因為人壽保險一般不適用彌償原則"},{c:"3.2.1(b)",s:"意外死亡及喪失肢體附約受保生命在意外事故中可得到一筆與死亡保險金相等的賠償金,\n經修改後受保人可收取50%保險金若意外事故導致",o:["喪失一腿","喪失一目","喪失一手","以上各項皆是"],a:3,e:"在正常情況下，若受保生命在意外事故中喪失任何\n兩肢或雙目失明，則會支付一筆與意外死亡保險金\n相等的款項。\n若意外事故導致受保生命喪失單肢或單目失明，或\n遭受其他較輕微的指明受傷，給付額通常相等於意\n外死亡保險金的規定比率，例如喪失單肢或單目失\n明可收取50%保險金"},{c:"3.3",s:"以下哪項屬於提前支付死亡保險利益?\ni. 殘疾收入\nii. 保證可保利益\niii. 長期護理利益\niv. 危疾保險利益",o:["i, ii","i, iii","iii, iv","ii, iii, iv"],a:2,e:"只有長期護理利益及危疾保險利益屬於提前支付死\n亡保險利益，選項iii, iv正確"},{c:"3.3",s:"以下哪項就提前支付死亡保險利益附約的陳述是正確的?\ni. 此附約亦稱為生前支付保險利益附約\nii. 此附約只適用於如癌症般的嚴重疾病\niii. 於極度悲傷或生命受到威脅情況下可提取\niv. 該支付可能會影響受益人的期望",o:["i, ii, iii","i, ii, iv","i,iii,iv","ii,iii,iv"],a:2,e:"兩種提前支付死亡保險利益有兩種，分別是危疾和\n長期護理保險利益。選項ii不正確"},{c:"3.3",s:"一份保單包含提前提前支付死亡保險利益附約,這代表",o:["這份保單可轉換為儲蓄壽險","這份保單已加入殘疾利益","受保保單所有人可於生命結束前支取保險利益","受保保單所有人年屆100歲時,可支取保險利益"],a:2,e:"一份保單包含提前提前支付死亡保險利益附約,這\n代表受保保單所有人可於生命結束前支取保險利益"},{c:"3.3(c)",s:"根據提前支付死亡保險利益條款，在某些嚴重的情況下，縱使死亡並未發生，保單所列\n明的死亡金是可以支付給保單所有人，但",o:["受益人/承讓人必須簽署棄權聲明","受益人同樣可以取回所有索償","受益人如果在受保人死後兩年內便可獲取所有索償","受益人只可取回保費"],a:0,e:"由於向在世的受保保單所有人發放保險利益會對保\n單受益人的期望造成一定的影響，因此有些保險人\n會於處理此類附約的給付申請時，要求受益人簽署\n一份棄權聲明或稱解除責任憑證，同意提前支付的\n保險利益數額會從將來的死亡保險金中扣除。"},{c:"3.3.1",s:"危疾保險利益附約經常指明的疾病是︰",o:["中風","心臟病","肺癌","以上所有各項"],a:3,e:"以上都是危疾保險利益附約經常指明的疾病的例子"},{c:"3.3.2",s:"以下哪項就長期護理利益的陳述正確?\ni. 通常設有180日的等候期\nii. 受保保單所有人在接受長期護理利益的期間，通常獲得豁免保費\niii. 已接受長期護理利益的受保保單所有人死亡，將支付全數的死亡保險金\niv. 受保保單所有人可選擇在家中由正式註冊的護理員護理",o:["i, iii","ii,iv","i,ii,iii","i,ii,iii,iv"],a:1,e:"通常在給付長期護理保險利益之前有一個為期90日\n的等候期。每月在護理院護理的利益為死亡保險金\n的某個百分比，正確描述只有ii,iv, 正確答案是B"},{c:"3.3.2",s:"受保保單所有人唯有在下列哪種情況下才可取得長期護理保險利益附約的條款 ?",o:["在昏迷期間","終身癱瘓","因為身體某種狀況而需要接受長期護理","罹患終末疾病，且預期壽命只有一年或以下"],a:2,e:"如因某些疾病而須接受長期護理的受保保單所有人\n，可獲支付死亡保險金的規定部分作為長期護理保\n險利益，在認可的護理院接受護理或在受保保單所\n有人的家中由正式註冊的護理員護理"},{c:"3.4",s:"一份典型的醫療保險，不大可能接受以下哪項原因的「醫療開支」?",o:["道路交通意外導致的住院醫療","出院後一個月內的門診病人跟進護理","由主診醫生建議的私人護理","除去先天性面部皮膚疤痕的整容手術"],a:3,e:"除去先天性面部皮膚疤痕的整容手術不大可能接受\n以下哪項原因的「醫療開支」"},{c:"3.4.1(a)",s:"自願醫保計劃推動個人住院保險產品的發展，並為香港保險人帶來甚麼機會?",o:["自願醫保容許參與的保險人提供受認可的個人償款住院保險產品，供消費者自願選購","自願醫保容許參與的保險人提供受認可的個人及團體償款住院保險產品，供消費者自\n願選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，供消費者自願\n選購","自願醫保容許參與保險人提供受稅務局認可的個人償款住院保險產品，僅供香港居民\n自由購買"],a:0,e:"自願醫保容許參與的保險人提供受認可的個人償款\n住院保險產品，供消費者自願選購，團體保險並不\n適用"},{c:"3.4.1(a)",s:"自願醫保計劃（簡稱「自願醫保」）為保險買家提供了甚麼的機會?",o:["自願醫保為沒有能力承擔私營醫療服務的消費者提供保險計劃","自願醫保為沒有獲僱主提供醫療保險的消費者提供保險計劃","自願醫保為願意及有能力使用私營醫療服務的消費者提額外的保險計劃選擇","自願醫保為沒有能力承擔私營醫療服務的消費者提供保險低收入保險計劃"],a:2,e:"自願醫保為願意及有能力使用私營醫療服務的消費\n者提額外的保險計劃選擇"},{c:"3.5.1",s:"以下哪項是保證可保選擇的特點?",o:["限制","可附加豁免保費","非自動獲得","上述所有皆是"],a:3,e:"上述所有皆是保證可保選擇的特點"},{c:"3.5.1(a)",s:"保證可保利益的定義為",o:["保單所有人有權在指定的備擇日期購買增額保險，無需遞交可保證明","保單所有人有權在任何時候購買增額保險，無需遞交可保證明","保單所有人有權在指定的備擇日期購買增額保險，必需遞交可保證明","保單所有人有權在任何時候購買增額保險，必需遞交可保證明"],a:0,e:"保證可保利益的保單所有人有權在指定的備擇日期\n購買增額保險，無需遞交可保證明"},{c:"3.6.1",s:"以下哪項是「生活指數調整利益」附約的正確描述",o:["對抗經濟周期的影響","被保險人身故後提供一筆過的保險利益","紅利派發低於一般水平時，保險人將提供補充紅利","以上都不正確"],a:3,e:"「生活指數調整利益」附約增加的數目是跟綜合消\n費物價指數掛鈎的，只會按通漲調整，通縮情況下\n不會下降。"},{c:"4.1",s:"人壽保險單是一份重要的合約，該合約是一份完整合約，以下哪項有關完整合約的描述\n是正確的?\ni.完整的合約包括保險單、任何夾附的附約及夾附的投保單複印本\nii.保險公司某些指定的高級職員才有權改保險合約\niii.必須得到保單所有人的同意才可修改合約內容\niv.保單合約已經是一份完整的合約，並無需要附加其他的檔案",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"完整的合約由保險單、任何夾附的附約及夾附的投\n保單複印本構成，選項iv不正確"},{c:"4.1",s:"下列哪一項有關香港典型壽險保單「完整合約」條款的陳述是不正確的？",o:["一份完整的合約包括保險單、任何夾附的附約以及夾附的投保單的複印本","除非得到保單所有人同意，否則不能對合約作出任何修改","儘管保險人不同意，保單所有人仍有權利輕微地修改合約","只有保險公司中指明的高級職員才有權更改合約"],a:2,e:"「完整合約」條款規定：除非得到保單所有人的同\n意，否則保險人不能修改該合約。答案C不正確"},{c:"4.1",s:"如保單所有人沒有註明紅利的選擇，保險人會自動為保單所有人將紅利存放以賺取利息\n或",o:["以現金支付","用以繳付未來保費","用以購買清繳增額保險","購買一年期的定期壽險"],a:2,e:"購買清繳增額保險及紅利存放保險人以賺取利息屬\n自動紅利選擇"},{c:"4.1",s:"以下哪項關於紅利給付不正確？",o:["可以現金即時給付","存於保險人處以賺取利息",'如果沒有作出選擇,保險人會採用"自動紅利選擇"',"如果沒有作出選擇,保單所有人將會喪失該紅利"],a:3,e:"如果保單所有人沒有從上述各項中作出選擇，大多\n數保單會採用一種稱為「自動紅利選擇」的方式項\n選擇，將紅利存放在保險人處以賺取利息，或購買\n一項清繳增額保險。答案D不正確"},{c:"4.2",s:"以下有關不可異議條款，哪項陳述是不正確的？",o:["保單生效兩年後即不可異議","保單生效首兩年為可異議期","根據香港法律，即使是有欺詐的情況存在都不可以推翻該條款","該條款規定了一段可異議期"],a:2,e:"無論保單生效多久，存在欺詐的情況都可以推翻保\n單"},{c:"4.3",s:"就美式保單而言，受保生命在寬限期內死亡而保費還沒繳清，而該索償",o:["屬於無效","將獲支付，保險人會豁免所有到期保費","將獲支付，保險人會從應付死亡保險金中扣除到期保費","只有繳付所有到期保費索償才有效"],a:2,e:"如果受保生命在寬限期內死亡而保費還沒繳清，保\n險人會從應付死亡保險金中扣除到期保費，答案C\n正確"},{c:"4.3",s:"下列哪項或哪些有關寬限期條款的陳述是不正確的？",o:["該期間一般最少30或31天","它不適用於保單的首期保費","於寬限期內繳付保費可維持保單的保障繼續有效","於寬限期內繳付保費須另外繳付利息"],a:3,e:"於寬限期內繳付保費須被視為準時繳交"},{c:"4.3",s:"假設沒有不能作廢條款情況下，寬限期內沒有繳付保費，則保單便",o:["失效","被取消","變成不可異議","需要繳交較高保費，保單才可繼續生效"],a:0,e:"假設沒有不能作廢條款情況下，寬限期內沒有繳付\n保費，則保單便失效"},{c:"4.4",s:"人壽保單通常允許保單所有人在保單有效時變更受益人的指定，在這情況下，該指定受\n益人稱為",o:["第一順位受益人","第二順位受益人","次順位受益人","可撤換受益人"],a:3,e:"人壽保單通常允許保單所有人在保單有效時變更受\n益人的指定，在這情況下，該指定受益人稱為可撤\n換受益人"},{c:"4.4(c)",s:"張生買了一張人身意外壽險保單，自己為受保人，並訂明他的兒子為受益人，根據《已\n婚者地位條例》，此舉會否建立建立一個（法定）信託的效用嗎?",o:["會，《已婚者地位條例》明文合適用於人壽保險及人身意外保險","會，但大前題下該保單由人身意外保險人所發出","不會，除非構成《已婚者地位條例》所指，張先生就自身生命購買的保單","不會，除非張先生所購買的是一份附有人身意保險附約的壽險保單"],a:2,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.4(c)",s:"黃生就自身生命購買壽險保單，自己為受保人，並指明他最小的兒子為該保單受益人，\n根據《已婚者地位條例》，此舉起了甚麼的法律效用?",o:["該受益人成為該保單的法定保單所有人","該受益人成為該保單的法定保單所有人，直至黃先生修訂其他受益人為止","信託效用並不用適指定子女成為受益人","該受益人成為該保單的實益擁有人"],a:3,e:"根據《已婚者地位條例》，保單持有人如為其配偶\n及或其任何子女的利益而購買壽險單，將達到建立\n一個（法定信託的效用，從而令該配偶及或子女成\n為該保單的實益擁有人。"},{c:"4.5",s:"如果具有現金價值或紅利價值的保單的持有人決定不再繳付任何保費，他有權選取",o:["中止保單時獲付退保現金價值","利用淨現金價值作為整付保費，購買與原保單所提供的計劃相同的但保額較低的人壽\n保險","A&B","以上皆不是"],a:2,e:"退保及清繳保險是具有現金價值的保單，保單的持\n有人決定不再繳付任何保費有權選取的選擇"},{c:"4.5",s:"壽險合約中，不能作廢條款的首要目的是",o:["不得扣減保額的價值","保險人無權取消保單","保單不會在沒有繳付保費的情況下失效","保單不會因為被保險人無法償還貸款而作廢"],a:2,e:"壽險合約中，不能作廢條款的首要目的是保單不會\n在沒有繳付保費的情況下失效"},{c:"4.5",s:"一份完全清繳的保單是指",o:["以往所有到期保費已給支付","保費由第三者(如僱主)支付","保單一經生效必須支付所有保費","保單保費已全數支付，但保單仍然維持有效"],a:3,e:"一份完全清繳的保單是指保單保費已全數支付，保\n單仍然維持有效"},{c:"4.6",s:"以下哪項是對保單抵押貸款的正確描述？",o:["貸款用途由保單所有人決定","貸款通常是保險人任意決定的","唯一受到保單條款約束的是定期壽險","保單貸款的用途只能用作繳付未來保費之用"],a:0,e:"保單抵押貸款屬保單有人有權向保險人借入款項，\n貸款用途無任何限制，以及保單所有人自行決定還\n款多少和 何時償還，只有答案A正確"},{c:"4.6",s:"關於人壽保單的保單抵押貸款",o:["貸款通常是保險人任意決定的","就任何種類的壽險而言，貸款都是常見的","貸款只獲允許用於保單指定的某些用途","以上所有各項均不正確"],a:3,e:"保單抵押貸款條款下，保單所有人有權向保險人借\n入款項，貸款用途無任何限制；以上各項均不是保\n單抵押貸款正確陳述"},{c:"4.7",s:"跟據英式人壽保險的慣例，「復效」稱為?",o:["重新訂立合約","保單復效","不能作廢","保單續保"],a:1,e:"跟據英式人壽保險的慣例，「復效」稱為保單復效"},{c:"4.7",s:"按照英式人壽保險慣例，在某些情況下，己失效的保單可以重獲「生命」，此稱為",o:["恢復保單","復效","轉保","生效"],a:1,e:"在某些情況下，己失效的保單可以重獲「生命」，\n此稱為復效"},{c:"4.8",s:"誤報年齡或性別資料的情況，如果保單於提出索償後才被發現，保險人會如何處理？",o:["不會作出任何調整","保單將會失效","退回全數已繳保費","向上或向下調整利益金額"],a:3,e:"誤報年齡或性別資料的情況，如果保單於提出索償\n後才被發現，保險人會向上或向下調整利益金額"},{c:"4.8",s:"保險人對於誤報資料的保單，在索償前通常也有一些常規條款，下列哪項為正確的？",o:["不會收取增加之保費及退回保費","若年齡在保單上過輕，則降低保額","若年齡在保單上過大，則退回多交之保費連利息","以上各項均不成立"],a:1,e:"如果在賠案發生之前已發現錯誤，便必須調整有關\n保額或保費的其中一項，若在保單年齡教真實年齡\n為輕，則出現少交保費情況，會降低保額"},{c:"4.9",s:"以下哪項法律條文容許藉訂明手續來轉讓據法權產?",o:["法律改革(綜合)條例","衡平法的原則","轉讓(據法權產)條例","法律修訂及改革(綜合)條例"],a:3,e:"《法律修訂及改革(綜合)條例》容許藉訂明手續來\n轉讓據法權產"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益無論於一般保險或人壽保險單都屬復歸權益","該項權益須屬現時的","該項權益須透過訂明手續來轉讓據法權產","該項權益屬轉屬轉讓人的可保權益"],a:1,e:"有效的法定轉讓其中的一項標準是，擬轉讓的據法\n權產須屬現時的，而非未來的"},{c:"4.9",s:"對保單權益屬轉讓需通過以下甚麼條件才可進行轉讓?",o:["該項權益須透過訂明手續來轉讓據法權產","該項權益須屬於轉讓據法權產","該項權益屬轉屬轉讓人的可保權益","擬轉讓的據法權產須屬現時的，延遲的或未來的"],a:1,e:"《法律修訂及改革(綜合)條例》容許藉訂明手續來\n轉讓據法權產，而對保險合約的權益屬於據法權產\n。"},{c:"4.11",s:"人壽保險可選取哪一項或哪些賠付的方式",o:["整數給付","固定的給付數額，直至終生","保單支付利息","以上各項皆是"],a:3,e:"以上各項皆是人壽保險可選取賠付的方式"},{c:"5.1(b)",s:"以下哪種情況下，營利(或合資股份公司)，不能強迫股東就公司虧損或資本需求提供額\n外資金，如果",o:["已經向他們發出股票","股東已完全清繳股票價值","公司已有足夠資本並開始交易","某段期間會計紀錄經已完結"],a:1,e:"營利公司（或稱股份公司）：這是更普遍的公司結\n構，是由股東共同擁有的股份有限責任公司，一旦\n股東「完全清繳」他所擁有的股票的價值，便不必\n再為公司的虧損或資本需求提供任何額外的資金。"},{c:"5.1.1(a)",s:"保險公司會計部的主要職能和責任包括：\ni) 記錄公司收入\nii) 監管公司支出\niii) 遵守(保費守則)\niv) 遵守(保險代理操守守則)",o:["i, ii","i, iii","iii,iv","ii,iii"],a:0,e:"遵守(保費守則)及遵守(保險代理操守守則)不屬保\n險公司會計部的職責，選項iii&iv不正確"},{c:"5.1.1(d)",s:"以下哪項較可能直接涉及理賠部門功能？",o:["監管由公司支付的所有款項","紀錄由公司支付及收取的所有款項","近因的調查核証工作","以上各項皆是"],a:2,e:"只有近因的調查核証工作較可能直接涉及理賠部門\n功能"},{c:"5.2.1(b)",s:"以下哪項是處理人壽險保投保時是應注意的事項？\ni) 下一個(或上一個)生日年齡\nii) 投保人的身份\niii) 保單生效日期\niv) 投保人過去三年的職業紀錄",o:["i, iii","ii, iii","i,ii,iii","i,ii, iii, iv"],a:2,e:"投保人過去三年的職業不是處理人壽險保投保時是\n應注意的事項，選項iv不正確，正確答案是C。"},{c:"5.2.2",s:"人壽保單投保人連同首期保費投保，人壽保險人已簽發保費收據。因詢問過程需時，剛\n巧在保險交付前投保人遇上交通意外身故，後來證實投保人按照標準條款是屬於可保的",o:["不論任何的保費收據類型索償均屬無效","不論任何的保費收據類型索償均屬有效","只有附條件保費收據索償有效","只有立約(不附條件) 保費收據索償有效"],a:1,e:"如果事故後能確定投保人在投保時乃屬按照標準條\n款並具有可保性的，不論附條件保費收據或立約保\n費收據的索償均屬有效"},{c:"5.2.2(a)",s:"人壽保險人透過簽發其中一種的保費收據，表示同意有關保險於投保時開始生效，但須\n於稍後證實投保人按照標準條款是屬於可保的。這種收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:2,e:"附條件保費收據須於稍後證實投保人按照標準條款\n是屬於可保的，有關保險於投保時開始生效"},{c:"5.2.2(b)",s:"在非人壽保險的保單中，有類似文件以提供暫時性、不附帶條件、但可取消的保障稱爲\n暫保單。在人壽保險亦有一種類似這種的收據稱為",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],a:1,e:"立約保費收據又叫不附帶條件保費收據、或可取消\n的保障稱爲暫保單。"},{c:"5.2.3b",s:"達致高素質的顧客服務的因素是?",o:["公司文化","權力下放","A&B","以上皆不正確"],a:2,e:"公司文化及權力下放是達致高素質的顧客服務的因\n素"},{c:"5.2.4(c)",s:"冷靜期是指允許保單所人就新購或已申請的人壽保險保單，在一段時間內改變主意，但\n容許保險人對下列哪類保單從退還的保費中減去「市值調整」？",o:["所有類別人壽保單","儲蓄壽險保單","定期壽險保單","投資相連保單"],a:3,e:"投資相連或非投資相連整付保費人壽保單，於冷靜\n期內取消保單，須從退還的保費中減去「市值調整\n」"},{c:"5.2.7",s:"相對投資相連保單，分紅保單的好處是︰\ni. 有保證的現金價值及死亡利益\nii. 保單所有人所承受的投資風險較低\niii. 有獨立的精算師監管\niv. 分紅保單的回報一般是平均派發",o:["i, ii, iii","i, ii, iv","ii,iii,iv","i,iii,iv"],a:1,e:"有獨立的精算師監管不屬有獨立的精算師監管分紅\n保單的好處，只有選項i, ii, iv正確"},{c:"5.2.7c",s:"相對投資相連保單，分紅保單的好處是︰",o:["高透明度保險制度","保單價值由精算師監管","較投資相連保單風險低","靈活性"],a:2,e:"相對投資相連保單，分紅保單的好處是保單承受的\n風險較低"},{c:"5.2.7d",s:"以下哪項是關於保費抵銷的正確描述？",o:["將來的現金紅利存放於保險人那裏","將來的紅利購買減額清繳保險","對未來業績表現有利","將來的紅利回報有利"],a:0,e:"保費抵銷預期將來的現金紅利存放於保險人那裏，\n保單持有人有權選擇停止繳付保費，但須注意是，\n未來利率水平可以下降的，到時客戶須要恢復掏錢\n付保費，否則可能導致保單失效，只有答案A正確\n。"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個\n近期曾發出新保單的產品系列的非保證紅利/英式紅利實現率是怎樣計算的?",o:["某個產品的實現率是指按「實際派發的保證紅利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「實際派發的非保證紅利/英式紅利」除以銷售時「利益說明\n所述數額」的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所述數額」\n的平均數計算。","某個產品的實現率是指按「保險人的實際盈利」除以銷售時「利益說明所承諾數額」\n的總額計算。"],a:1,e:"某個產品的實現率是指按「實際派發的非保證紅利\n/英式紅利」除以銷售時「利益說明所述數額」的\n平均數計算。"},{c:"5.2.8",s:"根據《承保長期保險業務類別C業務除外）指引》(指引16)，當銷售分紅（或有利潤）長\n期保單時，必須告知客戶",o:["過往的投資表現非分紅產品未來表現的指標","過往的紅利派發表現並非分紅產品未來表現的指標","過往的紅利派發表現僅指非分紅產品未來表現的指標","保險人不是承擔任何投資風險"],a:1,e:"根據指引16，當銷售分紅（或有利潤）長期保單時\n，必須告知客戶過往的紅利派發表現並非分紅產品\n未來表現的指標"},{c:"5.2.8",s:"按照指引16的規定，銷售分紅（或有利潤）保單或萬用壽險保單的保險人，應披露每個\n近期曾發出新保單的產品實現率是怎樣計算的?",o:["實現率是指按「實際派發的保證英式紅利」除以銷售時「利益說明所承諾數額」的平\n均數計算","實現率是指按「實際派發英式紅利」除以銷售時「利益說明所述數額」的平均數計算\n。","實現率是指按「實際派發的非保證英式紅利」除以銷售時「利益說明所述數額」的平\n均數計算","實現率是指按「實際派發的英式紅利」除以銷售時「利益說明所承諾數額」的平均數\n計算"],a:2,e:"某個產品的實現率是指按「實際派發的非保證紅利\n／英式紅利」除以銷售時「利益說明所述數額」的\n平均數計算"},{c:"5.2.10",s:"以下哪項不屬《重要資料聲明書－內地人士在港投購人身╱壽險保單》涵蓋的部分?",o:["提前提取保單費用","提前退保費用","紅利","保證回報"],a:3,e:"保證回報不屬《重要資料聲明書－內地人士在港投\n購人身╱壽險保單》涵蓋的部分"},{c:"5.3",s:"以下哪項的描述是正確的?",o:["人壽保險對個別風險的核保工作於每個保週年重新進行","核保工作只影響保費","人壽保險核保可以確定可保性及條款","以上全部皆正確"],a:2,e:"人壽保險核保可以確定可保性及條款，而且只有一\n次核保機會，除了影響保費，也會影響保險人承保\n決定，只有答案C是正確"},{c:"5.3.2",s:"以下哪項或哪些原因需要主診醫生的醫療報告?",o:["所要求的保額十分高","已超過某指明的年齡","就投保書上所披露的某些健康資料作進一步調查","以上各項皆是"],a:3,e:"以上各項皆是需要主診醫生的醫療報告"},{c:"5.5.1",s:"在人壽保險合約中，以下哪項是不大可能是常見的更改",o:["保單保障的類型","受保生命的身份","受益人","以上沒有一項不大可能是常見更改"],a:1,e:"在人壽保險合約中，受保生命的身份不大可能是常\n見的更改"},{c:"5.6.2(d)",s:"某人壽保險單訂明由陳大民作為受託人，假如被保險人逝世後保險金將全數支付給他，\n最終被保人被陳大民所殺害，請問陳大民可獲得保險金賠償嗎?",o:["殺人犯會喪失對所有人的權利，故此不能提出申索","保險業條例某項條文訂明殺人犯不能提出申索","人壽保險賠償只會賠付予受益人，並非受託人，故此不能提出申索","以上各項皆不正確"],a:3,e:"在大部分情況下，如果證實殺人犯是受益人的話，\n法律「公共政策」是不會容許殺人犯本人獲益的月\n，以上各項皆不正確"},{c:"5.6.2(d)(iv)",s:"如果一名客戶暗示，他正在考慮將本身的保單退保，保險中介人應採取以下哪項或哪些\n行動？",o:["有禮地詢問為何作出這個決定","小心地解釋保單退保的權利或影響","略述各種其他的可能選擇(如保單抵押貸款，清繳保障等)","以上各項皆是"],a:3,e:"以上各項皆是保險中介人處理保單退保時應採取的\n行動"}]};let extraPapers=[],extraQuestionsByPaper={};try{const i=require("./exam-data-extra");extraPapers=Array.isArray(i.papers)?i.papers:[],extraQuestionsByPaper=i.questionsByPaper&&"object"==typeof i.questionsByPaper?i.questionsByPaper:{}}catch(i){extraPapers=[],extraQuestionsByPaper={}}const mergedPapers=[...papers,...extraPapers],mergedQuestionsByPaper={...questionsByPaper,...extraQuestionsByPaper};function normalizePremiumPaper(i){return!i||"卷二"!==i.type&&"卷五"!==i.type?i:{...i,premium:!0}}function getPapersByType(i){return mergedPapers.filter(n=>n.type===i).map(i=>normalizePremiumPaper({...i,total:(mergedQuestionsByPaper[i.id]||[]).length}))}function getPaperById(i){return normalizePremiumPaper(mergedPapers.find(n=>n.id===i))}function getQuestionsByPaperId(i){return(mergedQuestionsByPaper[i]||[]).map((n,a)=>{const e=n.no||a+1,c=n.c||n.chapter||"",o=n.s||n.stem||"",s=n.o||n.options||[],v="number"==typeof n.a?n.a:n.answer,_=n.e??n.explain??"";return{id:n.id||`${i}-${String(e).padStart(4,"0")}`,no:e,chapter:c,stem:o,options:s,answer:v,explain:_}})}module.exports={chapterTitleMap:chapterTitleMap,papers:mergedPapers,questionsByPaper:mergedQuestionsByPaper,getPaperById:getPaperById,getPapersByType:getPapersByType,getQuestionsByPaperId:getQuestionsByPaperId};